/**
 * Назначение: admin API списка, статусов и SSE-событий feedback.
 */

import express from 'express';

import {
  buildFeedbackStatusUpdate,
  encodeFeedbackCursor,
  parseAdminFeedbackListQuery,
  parseAdminFeedbackPatchBody,
  serializeAdminFeedback,
} from '../feedback/adminFeedback.js';
import { subscribeFeedbackEvents } from '../feedback/feedbackEventHub.js';
import { Feedback } from '../models/public.js';
import { parseObjectIdParam } from '../projects/parseObjectId.js';
import { logger } from '../utils/logger.js';
import { ERROR_CODES } from './errorCodes.js';
import { sendErrorEnvelope } from './sendErrorEnvelope.js';

const SSE_HEARTBEAT_INTERVAL_MS = 25_000;

/**
 * @param {import('express').Request} req
 * @returns {{ requestId: string } | null}
 */
function reqLogMeta(req) {
  return req.requestId ? { requestId: req.requestId } : null;
}

/**
 * @param {unknown} value
 * @returns {string}
 */
function asRouteParam(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value) && typeof value[0] === 'string') return value[0];
  return '';
}

/**
 * @param {import('express').Response<import('../types/shared-types.js').ErrorEnvelope>} res
 * @param {string} message
 * @returns {void}
 */
function respondValidationError(res, message) {
  sendErrorEnvelope(res, {
    statusCode: 400,
    message,
    code: ERROR_CODES.VALIDATION_ERROR,
  });
}

/**
 * @returns {import('express').Router}
 */
export function createAdminFeedbackRouter() {
  const router = express.Router();

  /**
   * @param {import('express').Request} req
   * @param {import('express').Response<import('../types/shared-types.js').AdminFeedbackListResponse | import('../types/shared-types.js').ErrorEnvelope>} res
   * @param {import('express').NextFunction} next
   */
  router.get('/api/v1/admin/feedback', async (req, res, next) => {
    try {
      const parsed = parseAdminFeedbackListQuery(req.query);
      if (!parsed.ok) {
        respondValidationError(res, parsed.message);
        return;
      }

      /** @type {import('mongoose').QueryFilter<import('../types/shared-types.js').FeedbackMongoDoc>} */
      const filter = {};
      /** @type {import('mongoose').QueryFilter<import('../types/shared-types.js').FeedbackMongoDoc>[]} */
      const conditions = [];
      if (parsed.value.status === 'new') {
        conditions.push({
          $or: [
            { status: 'new' },
            { status: { $exists: false } },
          ],
        });
      } else if (parsed.value.status) {
        filter.status = parsed.value.status;
      }
      if (parsed.value.type) filter.type = parsed.value.type;
      if (parsed.value.cursor) {
        conditions.push({
          $or: [
            { createdAt: { $lt: parsed.value.cursor.createdAt } },
            {
              createdAt: parsed.value.cursor.createdAt,
              _id: { $lt: parsed.value.cursor.id },
            },
          ],
        });
      }
      if (conditions.length > 0) filter.$and = conditions;

      const docs = /** @type {import('../types/shared-types.js').FeedbackMongoDoc[]} */ (
        await Feedback.find(filter)
          .sort({ createdAt: -1, _id: -1 })
          .limit(parsed.value.limit + 1)
          .lean()
          .exec()
      );
      const hasMore = docs.length > parsed.value.limit;
      const page = hasMore ? docs.slice(0, parsed.value.limit) : docs;
      const last = page.at(-1);
      const nextCursor =
        hasMore && last?._id && last.createdAt
          ? encodeFeedbackCursor({ createdAt: last.createdAt, id: last._id })
          : null;

      res.status(200).json({
        ok: true,
        items: page.map(serializeAdminFeedback),
        nextCursor,
        limit: parsed.value.limit,
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * Маршрут объявлен до `/:id`, чтобы `stream` не интерпретировался как ObjectId.
   *
   * @param {import('express').Request} req
   * @param {import('express').Response} res
   */
  router.get('/api/v1/admin/feedback/stream', (req, res) => {
    res.status(200);
    res.set({
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    });
    res.flushHeaders();
    res.write(': connected\n\n');

    const unsubscribe = subscribeFeedbackEvents((event) => {
      res.write(`event: ${event.event}\ndata: ${JSON.stringify(event.feedback)}\n\n`);
    });
    const heartbeat = setInterval(() => {
      res.write(': heartbeat\n\n');
    }, SSE_HEARTBEAT_INTERVAL_MS);
    heartbeat.unref();

    let closed = false;
    const cleanup = () => {
      if (closed) return;
      closed = true;
      clearInterval(heartbeat);
      unsubscribe();
      logger.info('admin.feedback.stream.closed', reqLogMeta(req), {
        actorUserId: req.user?.id,
      });
    };

    req.on('close', cleanup);
    res.on('close', cleanup);
    logger.info('admin.feedback.stream.opened', reqLogMeta(req), {
      actorUserId: req.user?.id,
    });
  });

  /**
   * @param {import('express').Request<{ id: string }, import('../types/shared-types.js').AdminFeedbackPatchResponse, import('../types/shared-types.js').AdminFeedbackPatchBody>} req
   * @param {import('express').Response<import('../types/shared-types.js').AdminFeedbackPatchResponse | import('../types/shared-types.js').ErrorEnvelope>} res
   * @param {import('express').NextFunction} next
   */
  router.patch('/api/v1/admin/feedback/:id', async (req, res, next) => {
    try {
      const id = parseObjectIdParam(asRouteParam(req.params.id));
      if (!id) {
        respondValidationError(res, 'Некорректный id feedback');
        return;
      }

      const parsed = parseAdminFeedbackPatchBody(req.body);
      if (!parsed.ok) {
        respondValidationError(res, parsed.message);
        return;
      }

      const current = await Feedback.findById(id).lean().exec();
      if (!current) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Feedback не найден', code: ERROR_CODES.FEEDBACK_NOT_FOUND });
        return;
      }

      const update = buildFeedbackStatusUpdate(parsed.status, current.readAt, new Date());
      const updated = await Feedback.findByIdAndUpdate(id, update, {
        new: true,
        runValidators: true,
      })
        .lean()
        .exec();
      if (!updated) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Feedback не найден', code: ERROR_CODES.FEEDBACK_NOT_FOUND });
        return;
      }

      const feedback = serializeAdminFeedback(updated);
      logger.info('admin.feedback.patch', reqLogMeta(req), {
        feedbackId: feedback.id,
        status: feedback.status,
        actorUserId: req.user?.id,
      });
      res.status(200).json({ ok: true, feedback });
    } catch (err) {
      next(err);
    }
  });

  return router;
}

/**
 * Назначение: загрузчик JSON Schema для AJV.
 * Описание: Собирает components/schemas/CalcInput.yaml с $ref в единую схему для валидации анкеты; OpenAPI использует те же YAML-файлы. После bundle адаптирует enum и поля под runtime-нормализацию в validate.js. Экспортирует loadCalcInputSchemaForAjv().
 */

import $RefParser from '@apidevtools/json-schema-ref-parser';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  HOT_WATER_BOILER_MATCHING_SCHEME_ENUM,
} from '../../../shared/heatingMatchingSchemes.js';
import { CANONICAL_ROOM_TYPES } from '../../../shared/roomTypeNormalization.js';
import { UFH_MODE_PRESET_IDS } from '../../../shared/ufhModePresetIds.js';
import { HEATING_THERMAL_REGIME_PRESET_ENUM } from '../logic/heatingThermalRegimes.js';

const REPO_ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '../../..');

/** @type {import('ajv').SchemaObject | null} */
let cachedSchema = null;

/**
 * Правки после bundle: поведение runtime (нормализация типов комнат, enum из shared/*.js).
 *
 * @param {import('ajv').SchemaObject} schema
 */
function adaptBundledSchemaForAjv(schema) {
  const building = schema.properties?.building;
  const roomItems = building?.properties?.rooms?.items;
  if (roomItems?.properties?.type) {
    // До AJV тип комнаты: compat synonym/legacy, strict reject неизвестных (validate.js).
    roomItems.properties.type = {
      type: 'string',
      enum: [...CANONICAL_ROOM_TYPES],
    };
  }

  const heating = schema.properties?.heatingSystem?.properties;
  if (heating?.hotWaterBoilerPowerMatchingScheme) {
    heating.hotWaterBoilerPowerMatchingScheme.enum = [...HOT_WATER_BOILER_MATCHING_SCHEME_ENUM];
  }
  if (heating?.thermalRegimePreset) {
    heating.thermalRegimePreset.enum = [...HEATING_THERMAL_REGIME_PRESET_ENUM];
  }
  if (heating?.ufhPresetId) {
    heating.ufhPresetId.enum = [...UFH_MODE_PRESET_IDS];
  }
}

/**
 * Собрать CalcInput из YAML-компонентов репозитория (кэш на процесс).
 *
 * @returns {Promise<import('ajv').SchemaObject>}
 */
export async function loadCalcInputSchemaForAjv() {
  if (cachedSchema) return cachedSchema;

  const calcInputPath = path.join(REPO_ROOT, 'components/schemas/CalcInput.yaml');

  /** @type {import('ajv').SchemaObject} */
  // Парсинг .yaml — встроенный js-yaml (зависимость ref-parser).
  const bundled = await $RefParser.bundle(calcInputPath);

  adaptBundledSchemaForAjv(bundled);
  cachedSchema = bundled;
  return bundled;
}

/**
 * Назначение: REST API проектов и расчётов.
 * Описание: CRUD для проектов клиента (ownerId + JWT) и расчётов в MongoDB. Rate limit и квоты. Экспортирует createProjectsRouter().
 */

import express from 'express';
import { Project, Calculation } from '../models/public.js';
import { requireAuth } from '../auth/requireAuth.js';
import { requireRole } from '../auth/requireRole.js';
import { resolveProjectsDevOwnerObjectId } from '../auth/projectsAuthConfig.js';
import {
  projectCalcRateLimiter,
  projectsReadRateLimiter,
  projectsWriteRateLimiter,
} from './middleware/rateLimiters.js';
import { ERROR_CODES } from './errorCodes.js';
import { sendErrorEnvelope } from './sendErrorEnvelope.js';
import { runCalculation } from './runCalculation.js';
import { extractCalculationSummary } from '../projects/extractCalculationSummary.js';
import {
  validateProjectCreateBody,
  validateProjectUpdateBody,
} from '../projects/validateProjectBody.js';
import { parseObjectIdParam } from '../projects/parseObjectId.js';
import { requireMongoForProjects } from '../projects/requireMongo.js';
import {
  assertCanCreateCalculation,
  assertCanCreateProject,
  buildAccessibleProjectByIdFilter,
  findAccessibleProjectDoc,
  findAccessibleProjectLean,
  isProjectsAdminRequest,
  logAdminCrossOwnerProjectAccess,
  resolveProjectListFilter,
  validateProjectsListQueryForRole,
} from '../projects/projectAccess.js';
import { loadOwnerEmailByOwnerId } from '../projects/projectOwnerMeta.js';
import {
  serializeCalculationDetail,
  serializeCalculationListItem,
  serializeProjectDetail,
  serializeProjectListItem,
} from '../projects/serializeProject.js';
import { resolveProjectCalcInput } from '../projects/resolveProjectCalcInput.js';
import { assertCalculationDocumentSize } from '../projects/documentSizeLimits.js';
import {
  calcInputAuditMeta,
  projectPatchFields,
  surveyAuditMeta,
} from '../projects/projectChangeMeta.js';
import { buildShareSnapshot } from '../projects/buildShareSnapshot.js';
import { buildPublisherPresentationFromUser } from '../projects/buildPublisherPresentation.js';
import { generateShareToken } from '../projects/shareToken.js';
import { serializeProjectShareMeta } from '../projects/serializeShare.js';
import { parseIncludeTechnicalQuery } from '../projects/parseIncludeTechnicalQuery.js';
import { renderEstimatePdf } from '../projects/renderEstimatePdf.js';
import { validateProjectImportBody } from '../projects/validateProjectImportBody.js';
import { importProjectBundle } from '../projects/importProjectBundle.js';
import { logger } from '../utils/logger.js';

/**
 * @param {import('express').Request} _req
 * @param {import('express').Response} _res
 * @param {import('express').NextFunction} next
 */
async function mongoMiddleware(_req, _res, next) {
  try {
    await requireMongoForProjects();
    next();
  } catch (err) {
    next(err);
  }
}

/**
 * ObjectId владельца проекта: req.user.id (users._id) или dev-fallback без JWT.
 *
 * @param {import('express').Request} req
 * @returns {import('mongoose').Types.ObjectId}
 */
function ownerIdFromRequest(req) {
  if (req.user?.id) {
    const oid = parseObjectIdParam(req.user.id);
    if (oid) return oid;
  }
  return resolveProjectsDevOwnerObjectId();
}

/**
 * Мета для logger с optional requestId (exactOptionalPropertyTypes).
 *
 * @param {import('express').Request} req
 * @returns {{ requestId: string } | null}
 */
function reqLogMeta(req) {
  return req.requestId ? { requestId: req.requestId } : null;
}

/**
 * Параметр маршрута Express → строка (checkJs: params может быть string | string[]).
 *
 * @param {unknown} value
 * @returns {string}
 */
function asRouteParam(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value) && typeof value[0] === 'string') return value[0];
  return '';
}

/**
 * @param {unknown} raw
 * @param {number} fallback
 * @param {number} max
 */
function parseLimit(raw, fallback, max) {
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return fallback;
  return Math.min(Math.floor(n), max);
}

/**
 * @returns {import('express').Router}
 */
export function createProjectsRouter() {
  const router = express.Router();

  router.use('/api/v1/projects', mongoMiddleware, requireAuth);

  /**
   * @param {import('express').Request} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectsListResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.get('/api/v1/projects', projectsReadRateLimiter, async (req, res, next) => {
    try {
      const listQueryError = validateProjectsListQueryForRole(req);
      if (listQueryError) {
        sendErrorEnvelope(res, { statusCode: 403, message: listQueryError, code: 'ADMIN_REQUIRED' });
        return;
      }

      const ownerId = ownerIdFromRequest(req);
      const limit = parseLimit(req.query.limit, 50, 100);
      const skip = parseLimit(req.query.skip, 0, 10_000);
      const search =
        typeof req.query.search === 'string' && req.query.search.trim()
          ? req.query.search.trim()
          : null;

      /** @type {import('mongoose').QueryFilter<import('../types/shared-types.js').ProjectMongoDoc>} */
      const filter = { ...(await resolveProjectListFilter(req, ownerId)) };
      if (search) {
        filter.clientName = {
          $regex: search.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
          $options: 'i',
        };
      }

      const [docsRaw, total] = await Promise.all([
        Project.find(filter).sort({ updatedAt: -1 }).skip(skip).limit(limit).lean(),
        Project.countDocuments(filter),
      ]);
      /** @type {import('../types/shared-types.js').ProjectMongoDoc[]} */
      const docs = docsRaw;

      const ids = docs.map((d) => d._id);
      const counts = await Calculation.aggregate([
        { $match: { projectId: { $in: ids } } },
        { $group: { _id: '$projectId', count: { $sum: 1 } } },
      ]);
      const countByProject = new Map(counts.map((c) => [String(c._id), c.count]));

      const ownerEmailById = isProjectsAdminRequest(req)
        ? await loadOwnerEmailByOwnerId(docs)
        : new Map();

      const projects = docs.map((doc) => {
        const ownerKey = doc.ownerId != null ? String(doc.ownerId) : '';
        const ownerEmail = ownerKey ? ownerEmailById.get(ownerKey) : undefined;
        return serializeProjectListItem(
          {
            ...doc,
            calculationsCount: countByProject.get(String(doc._id)) ?? 0,
          },
          ownerEmail ? { ownerEmail } : {},
        );
      });

      if (isProjectsAdminRequest(req) && total > 0) {
        logger.info('projects.admin.list', reqLogMeta(req), {
          total,
          limit,
          skip,
          adminUserId: req.user?.id ?? '',
        });
      }

      res.status(200).json({ ok: true, projects, total, limit, skip });
    } catch (err) {
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{}, import('../types/shared-types.js').ProjectCreateResponse, import('../types/shared-types.js').ProjectCreateBody>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectCreateResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.post('/api/v1/projects', projectsWriteRateLimiter, async (req, res, next) => {
    try {
      const ownerId = ownerIdFromRequest(req);
      await assertCanCreateProject(ownerId);

      const payload = validateProjectCreateBody(req.body);
      /** @type {import('../types/shared-types.js').ProjectMongoDoc} */
      const createDoc = {
        ownerId: ownerId,
        clientName: payload.clientName,
      };
      if (payload.label !== undefined) createDoc.label = payload.label;
      if (payload.survey !== undefined) createDoc.survey = payload.survey;

      const doc = await Project.create(createDoc);
      logger.info('project.create', reqLogMeta(req), {
        projectId: String(doc._id),
        ownerId: ownerId,
        survey: surveyAuditMeta(payload.survey),
      });
      res.status(201).json({
        ok: true,
        project: serializeProjectDetail(doc.toObject(), { calculationsCount: 0 }),
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{}, import('../types/shared-types.js').ProjectImportResponse, import('../types/shared-types.js').ProjectImportBody>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectImportResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.post(
    '/api/v1/projects/import',
    projectsWriteRateLimiter,
    requireRole('admin'),
    async (req, res, next) => {
      try {
        const ownerId = ownerIdFromRequest(req);
        const payload = validateProjectImportBody(req.body);
        const { project, calculationsImported } = await importProjectBundle({
          ownerId,
          payload,
          requestId: req.requestId ?? null,
        });

        res.status(201).json({
          ok: true,
          project: serializeProjectDetail(project.toObject(), {
            calculationsCount: calculationsImported,
          }),
          calculationsImported,
        });
      } catch (err) {
        next(err);
      }
    },
  );

  /**
   * @param {import('express').Request<{ id: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectGetResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.get('/api/v1/projects/:id', projectsReadRateLimiter, async (req, res, next) => {
    try {
      const ownerId = ownerIdFromRequest(req);
      const oid = parseObjectIdParam(asRouteParam(req.params.id));
      if (!oid) {
        sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
        return;
      }

      const doc = await findAccessibleProjectLean(oid, ownerId, req);
      if (!doc) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      const calculationsCount = await Calculation.countDocuments({ projectId: oid });

      /** @type {import('../types/shared-types.js').CalculationListItem | undefined} */
      let lastCalculation;
      if (req.query.includeLastCalculation === '1' || req.query.includeLastCalculation === 'true') {
        const last = await Calculation.findOne({ projectId: oid })
          .sort({ createdAt: -1 })
          .lean();
        if (last) lastCalculation = serializeCalculationListItem(last);
      }

      const ownerEmailMap = isProjectsAdminRequest(req)
        ? await loadOwnerEmailByOwnerId([doc])
        : new Map();
      const ownerKey = doc.ownerId != null ? String(doc.ownerId) : '';
      const ownerEmail = ownerKey ? ownerEmailMap.get(ownerKey) : undefined;

      /** @type {{ calculationsCount: number; lastCalculation?: import('../types/shared-types.js').CalculationListItem; ownerEmail?: string }} */
      const detailExtra = { calculationsCount };
      if (lastCalculation !== undefined) {
        detailExtra.lastCalculation = lastCalculation;
      }
      if (ownerEmail) {
        detailExtra.ownerEmail = ownerEmail;
      }

      res.status(200).json({
        ok: true,
        project: serializeProjectDetail(doc, detailExtra),
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{ id: string }, import('../types/shared-types.js').ProjectUpdateResponse, import('../types/shared-types.js').ProjectUpdateBody>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectUpdateResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.put('/api/v1/projects/:id', projectsWriteRateLimiter, async (req, res, next) => {
    try {
      const ownerId = ownerIdFromRequest(req);
      const oid = parseObjectIdParam(asRouteParam(req.params.id));
      if (!oid) {
        sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
        return;
      }

      const existing = await findAccessibleProjectLean(oid, ownerId, req);
      if (!existing) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      const patch = validateProjectUpdateBody(req.body);
      const update = /** @type {Record<string, unknown>} */ ({});
      if (patch.clientName !== undefined) update.clientName = patch.clientName;
      if (patch.label !== undefined) update.label = patch.label;
      if (patch.survey !== undefined) update.survey = patch.survey;

      const doc = await Project.findOneAndUpdate(
        buildAccessibleProjectByIdFilter(oid, ownerId, req),
        { $set: update },
        { new: true },
      ).lean();

      if (!doc) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      logAdminCrossOwnerProjectAccess(req, existing, 'mutate');

      const calculationsCount = await Calculation.countDocuments({ projectId: oid });
      logger.info('project.update', reqLogMeta(req), {
        projectId: String(oid),
        ownerId: ownerId,
        changedFields: projectPatchFields(/** @type {Record<string, unknown>} */ (patch)),
        ...(patch.survey !== undefined ? { survey: surveyAuditMeta(patch.survey) } : {}),
      });

      res.status(200).json({
        ok: true,
        project: serializeProjectDetail(doc, { calculationsCount }),
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{ id: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectDeleteResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.delete('/api/v1/projects/:id', projectsWriteRateLimiter, async (req, res, next) => {
    try {
      const ownerId = ownerIdFromRequest(req);
      const oid = parseObjectIdParam(asRouteParam(req.params.id));
      if (!oid) {
        sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
        return;
      }

      const existing = await findAccessibleProjectLean(oid, ownerId, req);
      if (!existing) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      const deleted = await Project.findOneAndDelete(
        buildAccessibleProjectByIdFilter(oid, ownerId, req),
      );

      if (!deleted) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      logAdminCrossOwnerProjectAccess(req, existing, 'mutate');

      const calcResult = await Calculation.deleteMany({ projectId: oid });
      logger.info('project.delete', reqLogMeta(req), {
        projectId: String(oid),
        ownerId: ownerId,
        calculationsRemoved: calcResult.deletedCount ?? 0,
      });

      res.status(200).json({
        ok: true,
        deleted: true,
        calculationsRemoved: calcResult.deletedCount ?? 0,
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{ id: string }, import('../types/shared-types.js').ProjectCalcResponse, import('../types/shared-types.js').ProjectCalcBody>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectCalcResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.post('/api/v1/projects/:id/calc', projectCalcRateLimiter, async (req, res, next) => {
    const logMeta = reqLogMeta(req);
    /** @type {string | undefined} */
    let projectIdForLog;
    /** @type {string | undefined} */
    let ownerIdForLog;
    /** @type {'calcInput' | 'body' | 'lastCalcInput' | undefined} */
    let calcInputSource;
    /** @type {boolean | undefined} */
    let surveyInRequest;
    try {
      const ownerId = ownerIdFromRequest(req);
      ownerIdForLog = String(ownerId);
      const oid = parseObjectIdParam(asRouteParam(req.params.id));
      if (!oid) {
        sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
        return;
      }

      const projectRaw = await findAccessibleProjectDoc(oid, ownerId, req);
      if (!projectRaw) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      /** @type {import('mongoose').Document & {
       *   survey?: unknown;
       *   lastCalcInput?: import('../types/shared-types.js').CalcRequestBody;
       *   ownerId?: import('mongoose').Types.ObjectId;
       * }} */
      const project = /** @type {import('mongoose').Document & {
       *   survey?: unknown;
       *   lastCalcInput?: import('../types/shared-types.js').CalcRequestBody;
       *   ownerId?: import('mongoose').Types.ObjectId;
       * }} */ (projectRaw);

      await assertCanCreateCalculation(oid);

      projectIdForLog = String(oid);

      const body = req.body ?? {};
      const saveSurvey =
        body.survey !== undefined &&
        body.survey !== null &&
        typeof body.survey === 'object' &&
        !Array.isArray(body.survey);
      surveyInRequest = saveSurvey;

      if (saveSurvey) {
        const { survey } = validateProjectUpdateBody({ survey: body.survey });
        if (survey) project.survey = survey;
      }

      const resolved = resolveProjectCalcInput(body, project.lastCalcInput);
      calcInputSource = resolved.source;

      logger.info('project.calc.start', logMeta, {
        projectId: projectIdForLog,
        ownerId: ownerId,
        calcInputSource,
        surveyInRequest: saveSurvey,
        ...(saveSurvey ? { survey: surveyAuditMeta(body.survey) } : {}),
        lastCalcInput: calcInputAuditMeta(project.lastCalcInput),
      });

      if (calcInputSource === 'lastCalcInput' && !saveSurvey) {
        logger.info('project.calc.reuseLastInput', logMeta, {
          projectId: projectIdForLog,
          ownerId: ownerId,
        });
      }

      const calcPayload = resolved.payload;

      const { input, report } = await runCalculation(calcPayload);

      const summary = extractCalculationSummary(report);
      const calculationDocPayload = {
        projectId: oid,
        calcInput: input,
        report,
        summary,
      };
      const estimatedBsonBytes = assertCalculationDocumentSize(calculationDocPayload);
      const calcDoc = await Calculation.create(calculationDocPayload);

      if (!project.ownerId) {
        project.ownerId = ownerId;
      }
      logAdminCrossOwnerProjectAccess(req, project.toObject(), 'mutate');
      project.lastCalcInput = input;
      await project.save();

      logger.info('project.calc.done', logMeta, {
        projectId: projectIdForLog,
        ownerId: ownerId,
        calculationId: String(calcDoc._id),
        calcInputSource,
        surveySaved: saveSurvey,
        lastCalcInputUpdated: true,
        calcInput: calcInputAuditMeta(input),
        heatLossKw: summary.heatLossKw,
        objectType: summary.objectType,
        boilerRequiredKw: summary.boilerRequiredKw,
        warnings: report?.warnings?.length ?? 0,
        estimatedBsonBytes,
      });

      res.status(200).json({
        ok: true,
        report,
        calculation: serializeCalculationListItem(calcDoc.toObject()),
        project: serializeProjectDetail(project.toObject(), {
          calculationsCount: await Calculation.countDocuments({ projectId: oid }),
        }),
      });
    } catch (err) {
      logger.error('project.calc.fail', logMeta, {
        projectId: projectIdForLog,
        ownerId: ownerIdForLog,
        calcInputSource,
        surveyInRequest,
        internalMessage: err instanceof Error ? err.message : String(err),
      });
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{ id: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').CalculationsListResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.get('/api/v1/projects/:id/calculations', projectsReadRateLimiter, async (req, res, next) => {
    try {
      const ownerId = ownerIdFromRequest(req);
      const oid = parseObjectIdParam(asRouteParam(req.params.id));
      if (!oid) {
        sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
        return;
      }

      const owned = await findAccessibleProjectLean(oid, ownerId, req);
      if (!owned) {
        sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
        return;
      }

      const limit = parseLimit(req.query.limit, 20, 100);
      const skip = parseLimit(req.query.skip, 0, 10_000);

      const [items, total] = await Promise.all([
        Calculation.find({ projectId: oid })
          .sort({ createdAt: -1 })
          .skip(skip)
          .limit(limit)
          .lean(),
        Calculation.countDocuments({ projectId: oid }),
      ]);

      res.status(200).json({
        ok: true,
        calculations: items.map(serializeCalculationListItem),
        total,
        limit,
        skip,
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * @param {import('express').Request<{ projectId: string, calcId: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').CalculationGetResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.get(
    '/api/v1/projects/:projectId/calculations/:calcId',
    projectsReadRateLimiter,
    async (req, res, next) => {
      try {
        const ownerId = ownerIdFromRequest(req);
        const projectOid = parseObjectIdParam(asRouteParam(req.params.projectId));
        const calcOid = parseObjectIdParam(asRouteParam(req.params.calcId));
        if (!projectOid || !calcOid) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id', code: ERROR_CODES.VALIDATION_ERROR });
          return;
        }

        const owned = await findAccessibleProjectLean(projectOid, ownerId, req);
        if (!owned) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
          return;
        }

        const doc = await Calculation.findOne({ _id: calcOid, projectId: projectOid }).lean();
        if (!doc) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Розрахунок не знайдено', code: ERROR_CODES.CALCULATION_NOT_FOUND });
          return;
        }

        res.status(200).json({
          ok: true,
          calculation: serializeCalculationDetail(doc),
        });
      } catch (err) {
        next(err);
      }
    },
  );

  /**
   * Скачать PDF сметы (owner). Источник — последний сохранённый расчёт проекта.
   *
   * @param {import('express').Request<{ id: string }>} req
   * @param {import('express').Response} res
   * @param {import('express').NextFunction} next
   */
  router.get(
    '/api/v1/projects/:id/pdf',
    projectsReadRateLimiter,
    async (req, res, next) => {
      try {
        const ownerId = ownerIdFromRequest(req);
        const oid = parseObjectIdParam(asRouteParam(req.params.id));
        if (!oid) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
          return;
        }

        const project = await findAccessibleProjectLean(oid, ownerId, req);
        if (!project) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
          return;
        }

        const calcDoc = await Calculation.findOne({ projectId: oid }).sort({ createdAt: -1 }).lean();
        if (!calcDoc || !/** @type {{ report?: unknown }} */ (calcDoc).report) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'Немає збереженого розрахунку для PDF', code: 'PDF_REPORT_REQUIRED' });
          return;
        }

        const includeTechnical = parseIncludeTechnicalQuery(req.query.includeTechnical);
        const publisherPresentation = buildPublisherPresentationFromUser(req.user);
        const snapshot = buildShareSnapshot({
          clientName: String(project.clientName ?? ''),
          label: project.label != null ? String(project.label) : null,
          report: /** @type {{ report: unknown }} */ (calcDoc).report,
          ...(publisherPresentation ? { publisherPresentation } : {}),
        });

        const started = Date.now();
        const pdf = await renderEstimatePdf(snapshot, { includeTechnical });
        logger.info('project.pdf.download', reqLogMeta(req), {
          projectId: String(oid),
          includeTechnical,
          bytes: pdf.bytes,
          ms: Date.now() - started,
        });

        res.status(200);
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', pdf.contentDisposition);
        res.setHeader('Content-Length', String(pdf.bytes));
        res.send(pdf.buffer);
      } catch (err) {
        next(err);
      }
    },
  );

  /**
   * Публикация / обновление публичной ссылки (owner). Тело: { calculationId? } или берётся последний calc.
   *
   * @param {import('express').Request<{ id: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectSharePublishResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.post(
    '/api/v1/projects/:id/share',
    projectsWriteRateLimiter,
    async (req, res, next) => {
      try {
        const ownerId = ownerIdFromRequest(req);
        const oid = parseObjectIdParam(asRouteParam(req.params.id));
        if (!oid) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
          return;
        }

        const project = await findAccessibleProjectDoc(oid, ownerId, req);
        if (!project) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
          return;
        }

        const body = req.body && typeof req.body === 'object' ? req.body : {};
        const calcIdRaw =
          typeof /** @type {{ calculationId?: unknown }} */ (body).calculationId === 'string'
            ? /** @type {{ calculationId: string }} */ (body).calculationId.trim()
            : '';

        /** @type {import('mongoose').Document | Record<string, unknown> | null} */
        let calcDoc = null;
        if (calcIdRaw) {
          const calcOid = parseObjectIdParam(calcIdRaw);
          if (!calcOid) {
            sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний calculationId', code: ERROR_CODES.VALIDATION_ERROR });
            return;
          }
          calcDoc = await Calculation.findOne({ _id: calcOid, projectId: oid }).lean();
          if (!calcDoc) {
            sendErrorEnvelope(res, { statusCode: 404, message: 'Розрахунок не знайдено', code: ERROR_CODES.CALCULATION_NOT_FOUND });
            return;
          }
        } else {
          calcDoc = await Calculation.findOne({ projectId: oid }).sort({ createdAt: -1 }).lean();
        }

        if (!calcDoc || !/** @type {{ report?: unknown }} */ (calcDoc).report) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'Немає збереженого розрахунку для публікації посилання', code: 'SHARE_REPORT_REQUIRED' });
          return;
        }

        const projectPlain = project.toObject();

        const publisherPresentation = buildPublisherPresentationFromUser(req.user);
        const snapshot = buildShareSnapshot({
          clientName: String(projectPlain.clientName ?? ''),
          label: projectPlain.label != null ? String(projectPlain.label) : null,
          report: /** @type {{ report: unknown }} */ (calcDoc).report,
          ...(publisherPresentation ? { publisherPresentation } : {}),
        });

        const existingToken =
          typeof projectPlain.shareToken === 'string' && projectPlain.shareToken.trim()
            ? projectPlain.shareToken.trim()
            : null;
        const shareToken = existingToken ?? generateShareToken();
        const sharePublishedAt = new Date();

        logAdminCrossOwnerProjectAccess(req, projectPlain, 'mutate');

        const updated = await Project.findOneAndUpdate(
          buildAccessibleProjectByIdFilter(oid, ownerId, req),
          {
            $set: {
              shareToken,
              sharePublishedAt,
              shareSnapshot: snapshot,
            },
          },
          { new: true },
        ).lean();

        if (!updated) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
          return;
        }

        const calculationsCount = await Calculation.countDocuments({ projectId: oid });
        const shareMeta = serializeProjectShareMeta(updated);
        if (!shareMeta) {
          /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
          const err = new Error('Не вдалося серіалізувати share');
          err.statusCode = 500;
          err.code = 'INTERNAL_ERROR';
          throw err;
        }

        logger.info('project.share.publish', reqLogMeta(req), {
          projectId: String(oid),
          ownerId: ownerId,
          rotated: !existingToken,
        });

        res.status(200).json({
          ok: true,
          shareToken: shareMeta.shareToken,
          sharePublishedAt: shareMeta.sharePublishedAt,
          publicPath: shareMeta.publicPath,
          project: serializeProjectDetail(updated, { calculationsCount }),
        });
      } catch (err) {
        next(err);
      }
    },
  );

  /**
   * Отзыв публичной ссылки (owner).
   *
   * @param {import('express').Request<{ id: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').ProjectShareRevokeResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.delete(
    '/api/v1/projects/:id/share',
    projectsWriteRateLimiter,
    async (req, res, next) => {
      try {
        const ownerId = ownerIdFromRequest(req);
        const oid = parseObjectIdParam(asRouteParam(req.params.id));
        if (!oid) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'Некоректний id проєкту', code: ERROR_CODES.VALIDATION_ERROR });
          return;
        }

        const project = await findAccessibleProjectDoc(oid, ownerId, req);
        if (!project) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Проєкт не знайдено', code: ERROR_CODES.PROJECT_NOT_FOUND });
          return;
        }

        const projectPlain = project.toObject();
        logAdminCrossOwnerProjectAccess(req, projectPlain, 'mutate');

        await Project.updateOne(
          buildAccessibleProjectByIdFilter(oid, ownerId, req),
          { $unset: { shareToken: 1, sharePublishedAt: 1, shareSnapshot: 1 } },
        );

        const refreshed = await findAccessibleProjectLean(oid, ownerId, req);
        const calculationsCount = await Calculation.countDocuments({ projectId: oid });

        logger.info('project.share.revoke', reqLogMeta(req), {
          projectId: String(oid),
          ownerId: ownerId,
        });

        res.status(200).json({
          ok: true,
          revoked: true,
          project: serializeProjectDetail(refreshed ?? { _id: oid, clientName: '' }, {
            calculationsCount,
          }),
        });
      } catch (err) {
        next(err);
      }
    },
  );

  return router;
}

/**
 * Назначение: публичный read-only API снимков сметы по shareToken.
 * Описание: GET без JWT; только whitelist snapshot; rate limit по IP.
 */

import express from 'express';
import { Project } from '../models/public.js';
import { publicShareReadRateLimiter } from './middleware/rateLimiters.js';
import { sendErrorEnvelope } from './sendErrorEnvelope.js';
import { requireMongoForProjects } from '../projects/requireMongo.js';
import { normalizeShareTokenParam } from '../projects/shareToken.js';
import { serializePublicShare } from '../projects/serializeShare.js';
import { parseIncludeTechnicalQuery } from '../projects/parseIncludeTechnicalQuery.js';
import { renderEstimatePdf } from '../projects/renderEstimatePdf.js';
import { isPlainObject } from '../utils/isPlainObject.js';
import { logger } from '../utils/logger.js';

/**
 * @param {import('express').Request} _req
 * @param {import('express').Response} _res
 * @param {import('express').NextFunction} next
 */
async function mongoMiddleware(_req, _res, next) {
  try {
    await requireMongoForProjects();
    next();
  } catch (err) {
    next(err);
  }
}

/**
 * @param {import('express').Request} req
 * @returns {{ requestId: string } | null}
 */
function reqLogMeta(req) {
  return req.requestId ? { requestId: req.requestId } : null;
}

/**
 * @param {unknown} value
 * @returns {string}
 */
function asRouteParam(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value) && typeof value[0] === 'string') return value[0];
  return '';
}

/**
 * @returns {import('express').Router}
 */
export function createPublicSharesRouter() {
  const router = express.Router();

  /**
   * @param {import('express').Request<{ shareToken: string }>} req
   * @param {import('express').Response<import('../types/shared-types.js').PublicShareResponse>} res
   * @param {import('express').NextFunction} next
   */
  router.get(
    '/api/v1/public/shares/:shareToken',
    mongoMiddleware,
    publicShareReadRateLimiter,
    async (req, res, next) => {
      try {
        const token = normalizeShareTokenParam(asRouteParam(req.params.shareToken));
        if (!token) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Посилання не знайдено', code: 'SHARE_NOT_FOUND' });
          return;
        }

        const doc = await Project.findOne({ shareToken: token })
          .select({
            shareToken: 1,
            shareSnapshot: 1,
            sharePublishedAt: 1,
          })
          .lean();

        const snapshot = doc && isPlainObject(doc.shareSnapshot) ? doc.shareSnapshot : null;
        if (!doc || !snapshot || typeof snapshot.clientName !== 'string') {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Посилання не знайдено', code: 'SHARE_NOT_FOUND' });
          return;
        }

        const typed = /** @type {import('../types/shared-types.js').ProjectShareSnapshot} */ (
          /** @type {unknown} */ (snapshot)
        );

        logger.info('share.public.get', reqLogMeta(req), {
          tokenPrefix: token.slice(0, 6),
        });

        res.status(200).json({
          ok: true,
          share: serializePublicShare(typed, token),
        });
      } catch (err) {
        next(err);
      }
    },
  );

  /**
   * Скачать PDF публичной сметы (без JWT). Только shareSnapshot.
   *
   * @param {import('express').Request<{ shareToken: string }>} req
   * @param {import('express').Response} res
   * @param {import('express').NextFunction} next
   */
  router.get(
    '/api/v1/public/shares/:shareToken/pdf',
    mongoMiddleware,
    publicShareReadRateLimiter,
    async (req, res, next) => {
      try {
        const token = normalizeShareTokenParam(asRouteParam(req.params.shareToken));
        if (!token) {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Посилання не знайдено', code: 'SHARE_NOT_FOUND' });
          return;
        }

        const doc = await Project.findOne({ shareToken: token })
          .select({
            shareToken: 1,
            shareSnapshot: 1,
            sharePublishedAt: 1,
          })
          .lean();

        const snapshot = doc && isPlainObject(doc.shareSnapshot) ? doc.shareSnapshot : null;
        if (!doc || !snapshot || typeof snapshot.clientName !== 'string') {
          sendErrorEnvelope(res, { statusCode: 404, message: 'Посилання не знайдено', code: 'SHARE_NOT_FOUND' });
          return;
        }

        if (!isPlainObject(snapshot.commercial)) {
          sendErrorEnvelope(res, { statusCode: 400, message: 'У знімку немає фінансової смети', code: 'PDF_COMMERCIAL_REQUIRED' });
          return;
        }

        const includeTechnical = parseIncludeTechnicalQuery(req.query.includeTechnical);
        const typed = /** @type {import('../types/shared-types.js').ProjectShareSnapshot} */ (
          /** @type {unknown} */ (snapshot)
        );

        const started = Date.now();
        const pdf = await renderEstimatePdf(typed, { includeTechnical });
        logger.info('share.public.pdf', reqLogMeta(req), {
          tokenPrefix: token.slice(0, 6),
          includeTechnical,
          bytes: pdf.bytes,
          ms: Date.now() - started,
        });

        res.status(200);
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', pdf.contentDisposition);
        res.setHeader('Content-Length', String(pdf.bytes));
        res.send(pdf.buffer);
      } catch (err) {
        next(err);
      }
    },
  );

  return router;
}

/**
 * Назначение: основной HTTP-роутер API.
 * Описание: Создаёт Express-роутер с эндпоинтами MVP: health-check, каталог, пресеты ограждений и ТП, расчёт POST /api/v1/calc. Подключает роутер проектов; calc-пайплайн — runCalculation.js.
 */

import express from 'express';
import { getReferenceBundle } from '../reference/public.js';
import { FLOORING_FINISH_MATERIALS } from '../data/flooringFinishMaterials.js';
import { UNDERFLOOR_HEATING_BASE_PRESETS } from '../data/warmFloorAssemblyPresets.js';
import { ENVELOPE_PRESETS } from '../logic/envelopePresets.js';
import { runCalculation } from './runCalculation.js';
import { logger } from '../utils/logger.js';
import { setNoStoreCacheHeaders } from '../utils/setNoStoreCacheHeaders.js';
import { createProjectsRouter } from './projectsRoutes.js';
import { createPublicSharesRouter } from './publicSharesRoutes.js';
import { createSystemRouter } from './systemRoutes.js';
import { createFeedbackRouter } from './feedbackRoutes.js';
import { createMeRouter } from './meRoutes.js';
import { createAdminRouter } from './adminRoutes.js';
import { calcRateLimiter } from './middleware/rateLimiters.js';
import { sendErrorEnvelope } from './sendErrorEnvelope.js';

/**
 * @returns {Promise<import('express').Router>}
 */
export async function createRoutes() {
  const router = express.Router();

  /**
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').HealthOkResponse>} res
   */
  const healthHandler = (_req, res) => res.status(200).json({ ok: true, status: 'up' });
  router.get('/health', healthHandler);
  /** Legacy alias для мониторинга / старых URL (канонический путь — GET /health). */
  router.get('/api/health', healthHandler);

  /**
   * Корень API: открытие базового URL в браузере без 404.
   *
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').ApiRootResponse>} res
   */
  router.get('/', (_req, res) => {
    res.status(200).json({
      ok: true,
      status: 'up',
      service: 'heatcalc-api',
      health: '/health',
      api: '/api/v1',
      endpoints: {
        health: 'GET /health',
        catalog: 'GET /api/v1/catalog',
        calc: 'POST /api/v1/calc',
        projects: 'GET /api/v1/projects',
        me: 'GET /api/v1/me',
      },
    });
  });

  /**
   * Подсказка для /api без версии (канонический префикс — /api/v1).
   *
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').ApiVersionHintResponse>} res
   */
  router.get('/api', (_req, res) => {
    res.status(200).json({
      ok: true,
      version: 'v1',
      base: '/api/v1',
      hint: 'Використовуйте шляхи з префіксом /api/v1/…',
    });
  });

  router.use(createSystemRouter());

  /**
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').CatalogResponse>} res
   */
  router.get('/api/v1/catalog', async (_req, res, next) => {
    try {
      const bundle = await getReferenceBundle();
      res.status(200).json({
        ok: true,
        catalog: bundle.catalog,
        catalogSource: bundle.catalogSource,
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * Справочники для анкеты: не кешировать в браузере/прокси (envelope, ТП, финиши, modes).
   *
   * @param {import('express').Request} _req
   * @param {import('express').Response} res
   * @param {import('express').NextFunction} next
   */
  router.use('/api/v1/presets', (_req, res, next) => {
    setNoStoreCacheHeaders(res);
    next();
  });

  /**
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').EnvelopePresetsResponse>} res
   */
  router.get('/api/v1/presets/envelope', (_req, res) => {
    res.status(200).json({ ok: true, presets: ENVELOPE_PRESETS });
  });

  /**
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').UnderfloorHeatingBasesResponse>} res
   */
  router.get('/api/v1/presets/underfloor-heating/bases', (_req, res) => {
    res.status(200).json({ ok: true, bases: UNDERFLOOR_HEATING_BASE_PRESETS });
  });

  /**
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').FlooringFinishesResponse>} res
   */
  router.get('/api/v1/presets/flooring-finishes', (_req, res) => {
    res.status(200).json({ ok: true, finishes: FLOORING_FINISH_MATERIALS });
  });

  /**
   * Сводный ответ: базы + финиши (для одного запроса UI).
   *
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').UnderfloorHeatingPresetsBundleResponse>} res
   */
  router.get('/api/v1/presets/underfloor-heating', (_req, res) => {
    res.status(200).json({
      ok: true,
      bases: UNDERFLOOR_HEATING_BASE_PRESETS,
      finishes: FLOORING_FINISH_MATERIALS,
    });
  });

  /**
   * Режимы ТП с человекочитаемым UI (Mongo underfloor_heating_presets).
   *
   * @param {import('express').Request} _req
   * @param {import('express').Response} res
   * @param {import('express').NextFunction} next
   */
  router.get('/api/v1/presets/underfloor-heating/modes', async (_req, res, next) => {
    try {
      const bundle = await getReferenceBundle();
      res.status(200).json({
        ok: true,
        schemaVersion: bundle.ufhPresets.schemaVersion,
        source: bundle.ufhPresetsSource,
        presets: bundle.ufhPresets.presets.map((p) => ({
          presetId: p.presetId,
          ui: p.ui,
        })),
      });
    } catch (err) {
      next(err);
    }
  });

  /**
   * Legacy alias: /api/projects/* → внутренний rewrite на /api/v1/projects/*.
   *
   * @param {import('express').Request} req
   * @param {import('express').Response} _res
   * @param {import('express').NextFunction} next
   */
  router.use((req, _res, next) => {
    const path = req.path ?? '';
    if (path === '/api/projects' || path.startsWith('/api/projects/')) {
      req.url = req.url.replace(/^\/api\/projects/, '/api/v1/projects');
    }
    next();
  });

  /**
   * @param {import('express').Request<{}, import('../types/shared-types.js').CalcOkResponse, import('../types/shared-types.js').CalcRequestBody>} req
   * @param {import('express').Response<import('../types/shared-types.js').CalcOkResponse>} res
   * @param {import('express').NextFunction} next
   * @returns {Promise<void>}
   */
  router.use(createProjectsRouter());
  router.use(createMeRouter());
  router.use(createAdminRouter());
  router.use(createPublicSharesRouter());
  router.use(createFeedbackRouter());

  router.post('/api/v1/calc', calcRateLimiter, async (req, res, next) => {
    const logMeta = req.requestId ? { requestId: req.requestId } : null;
    try {
      logger.debug('calc.request.start', logMeta);
      const { report } = await runCalculation(req.body);
      logger.debug('calc.request.done', logMeta, { warnings: report?.warnings?.length ?? 0 });
      res.status(200).json({ ok: true, report });
    } catch (err) {
      next(err);
    }
  });

  // 404 для всіх інших маршрутів (у форматі ErrorEnvelope, як і раніше)
  /**
   * @param {import('express').Request} _req
   * @param {import('express').Response<import('../types/shared-types.js').ErrorEnvelope>} res
   */
  router.use((_req, res) =>
    sendErrorEnvelope(res, {
      statusCode: 404,
      message: 'Не знайдено',
      code: 'NOT_FOUND',
    }),
  );

  return router;
}

/**
 * Назначение: валидация и нормализация входной анкеты.
 * Описание: Фазы: reject legacy → compat-нормализация (room type, границы квартиры) → AJV strict
 * (coerceTypes: false) → cross-validation. Неизвестный room.type → 400 ROOM_TYPE_INVALID.
 * Экспортирует validateAndNormalizeInput().
 */

import AjvImport from 'ajv';
import {
  CANONICAL_ROOM_TYPES,
  ROOM_TYPE_SYNONYMS,
} from '../../../shared/roomTypeNormalization.js';
import {
  HOT_WATER_BOILER_MATCHING_SCHEME_ENUM,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
} from '../../../shared/heatingMatchingSchemes.js';
import {
  isUfhTerminalControl,
  resolveUfhTerminalControl,
} from '../../../shared/ufhTerminalControl.js';
import {
  assertRoomExteriorLayoutWalls,
  normalizeRoomExteriorLayouts,
} from '../logic/roomExteriorLayoutHeatLoss.js';
import { normalizeHeatingSystemThermalRegime } from '../logic/heatingThermalRegimes.js';
import {
  normalizeHeatingUfhPreset,
  appendThermalRegimeSchemeWarnings,
} from '../logic/normalizeHeatingUfhPreset.js';
import { normalizeUnderfloorDistributionPreset } from '../logic/normalizeUnderfloorDistribution.js';
import { assertCalcRuntimeContext } from '../reference/assertCalcRuntimeContext.js';
import { isPlainObject } from '../utils/isPlainObject.js';
import { logger } from '../utils/logger.js';
import { sanitizeTrimAngleBrackets } from '../utils/sanitizeString.js';
import {
  getBoilerRoomType,
  isBoilerRoomVolumeCompliant,
  resolveBoilerRoomMetrics,
  resolveObjectType,
} from '../utils/boilerMountingConstraints.js';
import {
  isLargeApartmentByInput,
} from '../utils/apartmentMatching.js';
import { assertExternalWalls } from '../logic/externalWallsValidate.js';
import { ERROR_CODES } from './errorCodes.js';
import { normalizeVentilationReserveMode } from '../logic/ventilationReserve.js';
import {
  normalizeApartmentStackPosition,
  resolveApartmentRoomBoundaries,
  defaultHouseBottomBoundary,
  warnApartmentCeilingPresetMismatch,
} from '../logic/apartmentStackBoundaries.js';
import {
  getUnderfloorHeatingBasePresetById,
  LEGACY_MONOLITHIC_UFH_PRESET_MAP,
  resolveUnderfloorHeatingComposition,
  UNDERFLOOR_HEATING_BASE_PRESETS,
} from '../data/warmFloorAssemblyPresets.js';
import { getFlooringFinishMaterialById } from '../data/flooringFinishMaterials.js';
import { loadCalcInputSchemaForAjv } from './calcInputSchemaLoader.js';

/** @type {typeof import('ajv').default} */
const Ajv = /** @type {typeof import('ajv').default} */ (
  /** @type {unknown} */ (AjvImport)
);

const UNDERFLOOR_HEATING_BASE_PRESET_IDS = new Set(
  UNDERFLOOR_HEATING_BASE_PRESETS.map((p) => p.id),
);
const LEGACY_UFH_PRESET_IDS = new Set(Object.keys(LEGACY_MONOLITHIC_UFH_PRESET_MAP));
const ENVELOPE_FORBIDDEN_UFH_FLOOR_IDS = new Set([
  ...UNDERFLOOR_HEATING_BASE_PRESET_IDS,
  ...LEGACY_UFH_PRESET_IDS,
]);

const ajv = new Ajv({
  allErrors: true,
  coerceTypes: false,
  removeAdditional: true,
});

/**
 * Бросает Error с полями AppErrorLike (statusCode/code/details) для HTTP error handler.
 *
 * @param {string} message
 * @param {string} code
 * @param {import('../types/shared-types.js').ErrorDetailsAjvItem[]} [details]
 * @returns {never}
 */
function throwAppError(message, code, details) {
  const err = new Error(message);
  /** @type {import('../types/shared-types.js').AppErrorLike} */
  const appErr = err;
  appErr.statusCode = 400;
  appErr.code = code;
  if (details !== undefined) {
    appErr.details = details;
  }
  throw err;
}

const CANONICAL_ROOM_TYPE_SET = new Set(CANONICAL_ROOM_TYPES);

const ROOM_TYPE_SYNONYM_BY_LOWER = Object.fromEntries(
  Object.entries(ROOM_TYPE_SYNONYMS).map(([k, v]) => [k.toLowerCase(), v]),
);

/**
 * Точное или без учёта регистра совпадение с каноническим типом (кириллица/латиница).
 *
 * @param {string} raw
 * @returns {string | null}
 */
function matchCanonicalRoomType(raw) {
  if (CANONICAL_ROOM_TYPE_SET.has(raw)) return raw;
  const low = raw.toLowerCase();
  for (const c of CANONICAL_ROOM_TYPES) {
    if (c.toLowerCase() === low) return c;
  }
  return null;
}

/**
 * Убираем невидимые символы и приводим строку (без смены смысла кириллицы).
 *
 * @param {unknown} v
 * @returns {string}
 */
function sanitizeRoomTypeString(v) {
  try {
    return String(v)
      .normalize('NFKC')
      .replace(/[\u200B-\u200D\uFEFF]/g, '')
      .trim()
      .replace(/[<>]/g, '');
  } catch {
    return String(v ?? '')
      .replace(/[\u200B-\u200D\uFEFF]/g, '')
      .trim()
      .replace(/[<>]/g, '');
  }
}

/**
 * @param {unknown} body
 * @param {string} message
 */
function pushNormalizationWarning(body, message) {
  if (!body || typeof body !== 'object') return;
  const record = /** @type {Record<string, unknown>} */ (body);
  if (!record.heatingSystem || typeof record.heatingSystem !== 'object') {
    record.heatingSystem = {};
  }
  const hs = /** @type {Record<string, unknown>} */ (record.heatingSystem);
  const prev = Array.isArray(hs._normalizationWarnings) ? hs._normalizationWarnings : [];
  if (prev.includes(message)) return;
  hs._normalizationWarnings = [...prev, message];
}

/**
 * Compat-нормализация типа комнаты до AJV: trim, синонимы (исправление опечаток UI).
 * Неизвестное значение → 400 ROOM_TYPE_INVALID (без silent «помещение»).
 * Legacy-типы (living/bathroom/tech/жилое) больше не поддерживаются: их мигрирует клиент.
 *
 * @param {unknown} building
 * @returns {string[]} сообщения для heatingSystem._normalizationWarnings (после AJV)
 */
function normalizeRoomTypesBeforeValidate(building) {
  /** @type {string[]} */
  const compatWarnings = [];

  if (!building || typeof building !== 'object') return compatWarnings;
  const buildingRec = /** @type {Record<string, unknown>} */ (building);
  const rooms = buildingRec.rooms;
  if (!Array.isArray(rooms)) return compatWarnings;

  for (const r of rooms) {
    if (!isPlainObject(r) || r.type == null) continue;
    const raw = sanitizeRoomTypeString(r.type);
    const lower = raw.toLowerCase();
    const roomId = typeof r.id === 'string' && r.id.trim() ? r.id.trim() : '?';

    /** @type {string | null} */
    let next;
    /** @type {string | null} */
    let compatSource = null;

    if (Object.prototype.hasOwnProperty.call(ROOM_TYPE_SYNONYMS, raw)) {
      const mapped = ROOM_TYPE_SYNONYMS[/** @type {keyof typeof ROOM_TYPE_SYNONYMS} */ (raw)];
      next = mapped ?? null;
      compatSource = raw;
    } else if (ROOM_TYPE_SYNONYM_BY_LOWER[lower] != null) {
      next = ROOM_TYPE_SYNONYM_BY_LOWER[lower] ?? null;
      compatSource = raw;
    } else {
      next = matchCanonicalRoomType(raw);
    }

    if (next == null) {
      throwAppError(
        `Невідомий тип приміщення «${raw}» (room id=${roomId}). Допустимі значення — enum room.type в CalcInput.`,
        'ROOM_TYPE_INVALID',
      );
    }

    if (compatSource != null) {
      compatWarnings.push(
        `Тип приміщення «${roomId}»: «${compatSource}» нормалізовано до «${next}».`,
      );
    }

    r.type = next;
  }

  return compatWarnings;
}

/**
 * @param {unknown} body — распакованное тело запроса
 */
function rejectLegacyHotWaterFields(body) {
  if (!isPlainObject(body)) return;
  const hw = body.hotWater;
  if (!isPlainObject(hw)) return;

  if (Object.prototype.hasOwnProperty.call(hw, 'coldWaterC')) {
    throwAppError(
      'Поле hotWater.coldWaterC видалено. Задайте hotWater.coldWaterDesignSeason: «winter» (+5 °C) або «summer» (+15 °C).',
      'HOT_WATER_LEGACY_FIELD',
    );
  }

  const fx = hw.fixtures;
  if (isPlainObject(fx) && Object.prototype.hasOwnProperty.call(fx, 'kitchen')) {
    throwAppError(
      'Поле hotWater.fixtures.kitchen видалено. Використовуйте лише kitchenSink.',
      'HOT_WATER_LEGACY_FIELD',
    );
  }
}

const INPUT_SCHEMA = await loadCalcInputSchemaForAjv();
const validateInput = ajv.compile(INPUT_SCHEMA);

// При старте процесса: в логах должно быть это сообщение. Если в ответе API по-прежнему
// фигурирует enum [жилое, санузел, living, …] — запущен старый процесс Node (перезапустите backend).
logger.info('validate.schema', null, {
  source: 'components/schemas/CalcInput.yaml',
  roomType: 'compat-then-strict-enum',
  ajvCoerceTypes: false,
  canonicalRoomTypes: CANONICAL_ROOM_TYPES,
});

/**
 * @param {unknown} input
 * @param {import('../types/shared-types.js').CalcRuntimeContext} ctx
 * @returns {import('../types/shared-types.js').CalcRequestBody}
 */
export function validateAndNormalizeInput(input, ctx) {
  assertCalcRuntimeContext(ctx);
  const rawClone = structuredClone(input ?? {});
  rejectLegacyHotWaterFields(rawClone);
  const draft = isPlainObject(rawClone) ? rawClone : {};
  const roomTypeCompatWarnings = normalizeRoomTypesBeforeValidate(draft.building);
  normalizeRoomBoundariesBeforeValidate(draft.building);
  // ТП комнаты: конструкция base+finish из data/ (статический слой, до AJV).
  normalizeUnderfloorHeatingBeforeValidate(rawClone);
  const ok = validateInput(rawClone);
  if (!ok) {
    /** @type {import('../types/shared-types.js').ErrorDetailsAjvItem[]} */
    const details = validateInput.errors ?? [];
    const short = details.slice(0, 5).map((e) => ({
      instancePath: e.instancePath,
      message: e.message,
      keyword: e.keyword,
    }));
    logger.warn('validation.failed', null, {
      code: ERROR_CODES.VALIDATION_ERROR,
      errors: short,
    });
    throwAppError('Некоректні вхідні дані', ERROR_CODES.VALIDATION_ERROR, details);
  }

  /** @type {import('../types/shared-types.js').CalcRequestBody} */
  const clone = /** @type {import('../types/shared-types.js').CalcRequestBody} */ (rawClone);

  for (const message of roomTypeCompatWarnings) {
    pushNormalizationWarning(clone, message);
  }

  // ГВС: сезон расчётной ХВ по умолчанию зима (+5 °C)
  if (isPlainObject(clone.hotWater)) {
    if (clone.hotWater.coldWaterDesignSeason == null) {
      clone.hotWater.coldWaterDesignSeason = 'winter';
    }
  }

  // Нормализация температур: поддерживаем оба варианта,
  // но каноническое расположение — building.temps.
  if (clone.building?.temps == null && clone.temps != null) {
    clone.building.temps = clone.temps;
  }

  // График отопления и база ΔT каталога радиатора по пресету (или 75/65 по умолчанию).
  normalizeHeatingSystemThermalRegime(clone);
  // Режим ТП: heatingSystem.ufhPresetId из ctx.ufhPresets (Mongo/file bundle).
  normalizeHeatingUfhPreset(clone, ctx.ufhPresets);
  appendThermalRegimeSchemeWarnings(clone);
  normalizeUnderfloorDistributionPreset(clone);

  // Санитизация строк: trim + базовая очистка опасных символов (< >),
  // чтобы случайные пробелы/вставки не ломали дальнейшую обработку или UI.
  if (clone.location?.address != null)
    clone.location.address = sanitizeTrimAngleBrackets(clone.location.address);

  for (const r of clone.building?.rooms ?? []) {
    if (r.id != null) r.id = sanitizeTrimAngleBrackets(r.id);
    if (r.name != null) r.name = sanitizeTrimAngleBrackets(r.name);
    if (r.type != null) {
      r.type = /** @type {import('../types/shared-types.js').RoomType} */ (
        sanitizeTrimAngleBrackets(r.type)
      );
    }
  }

  for (const e of clone.building?.envelopeElements ?? []) {
    if (e.roomId != null) e.roomId = sanitizeTrimAngleBrackets(e.roomId);
    if (e.name != null) e.name = sanitizeTrimAngleBrackets(e.name);
    if (e.construction != null) e.construction = sanitizeTrimAngleBrackets(e.construction);
    if (e.material != null) e.material = sanitizeTrimAngleBrackets(e.material);
    if (e.presetId != null) e.presetId = sanitizeTrimAngleBrackets(e.presetId);
  }

  // Cross-validation (базовая):
  // если заданы обе температуры подачи/обратки — обратка должна быть меньше подачи.
  if (
    clone.heatingSystem?.supplyC != null &&
    clone.heatingSystem?.returnC != null
  ) {
    if (!(clone.heatingSystem.returnC < clone.heatingSystem.supplyC)) {
      throwAppError(
        'Некоректний heatingSystem: returnC має бути меншим за supplyC.',
        'HEATING_SYSTEM_INVALID',
      );
    }
  }

  if (clone.hotWater?.hotWaterC != null) {
    const season =
      clone.hotWater.coldWaterDesignSeason === 'summer' ? 'summer' : 'winter';
    const effectiveColdC = season === 'summer' ? 15 : 5;
    if (!(effectiveColdC < clone.hotWater.hotWaterC)) {
      throwAppError(
        'Некоректний hotWater: розрахункова ХВ за сезоном має бути нижчою за hotWaterC.',
        'HOT_WATER_TEMPS_INVALID',
      );
    }
  }

  assertBoilerDhwSchemeCompatibility(clone, ctx.appliances);

  assertBoilerPlacementAndBoilerRoom(clone, ctx.appliances);

  assertExternalWalls(clone.building);

  normalizeRoomExteriorLayouts(clone.building);
  assertRoomExteriorLayoutWalls(clone.building);

  assertEnvelopeFloorPresetsNotUnderfloorHeating(clone.building);

  normalizeObjectMetaVentilationReserve(clone);

  assertVentilationLegacyFieldsDisabled(clone);

  collectApartmentEnvelopeWarnings(clone);

  return clone;
}

/**
 * Убирает underfloorHeating, если ТП выключен глобально; нормализует base + finish.
 * Источник пресетов: data/warmFloorAssemblyPresets.js + data/flooringFinishMaterials.js.
 *
 * @param {unknown} input
 */
function normalizeUnderfloorHeatingBeforeValidate(input) {
  if (!input || typeof input !== 'object') return;
  const body = /** @type {import('../types/shared-types.js').CalcRequestBody} */ (input);
  const rooms = body.building?.rooms;
  if (!Array.isArray(rooms)) return;

  const globalUfh =
    Boolean(body.heatingSystem?.waterUnderfloorHeating) ||
    Boolean(body.heatingSystem?.ufhPresetId);

  for (const room of rooms) {
    if (!globalUfh) {
      delete room.underfloorHeating;
      continue;
    }
    const ufh = room.underfloorHeating;
    if (!ufh || ufh.enabled !== true) {
      delete room.underfloorHeating;
      continue;
    }

    const composed = resolveUnderfloorHeatingComposition(ufh);
    if (!composed) {
      delete room.underfloorHeating;
      continue;
    }

    const { basePresetId, finishMaterialId } = composed;
    if (!getUnderfloorHeatingBasePresetById(basePresetId)) {
      throwAppError(
        `Невідома база ТП "${basePresetId}" (roomId="${room.id}").`,
        'UNDERFLOOR_HEATING_BASE_INVALID',
      );
    }
    if (!getFlooringFinishMaterialById(finishMaterialId)) {
      throwAppError(
        `Невідоме фінішне покриття "${finishMaterialId}" (roomId="${room.id}").`,
        'UNDERFLOOR_HEATING_FINISH_INVALID',
      );
    }

    const rawSpacing = ufh.pipeSpacingMm;
    /** @type {100 | 150 | 200} */
    let pipeSpacingMm = 150;
    if (rawSpacing !== undefined && rawSpacing !== null) {
      const spacingNum = Number(rawSpacing);
      if (!Number.isFinite(spacingNum) || !Number.isInteger(spacingNum)) {
        throwAppError(
          `pipeSpacingMm: очікується ціле 100, 150 або 200 (roomId="${room.id}").`,
          'UNDERFLOOR_HEATING_PIPE_SPACING_INVALID',
        );
      }
      if (spacingNum !== 100 && spacingNum !== 150 && spacingNum !== 200) {
        throwAppError(
          `pipeSpacingMm=${spacingNum}: допустимі лише 100, 150 або 200 мм (roomId="${room.id}").`,
          'UNDERFLOOR_HEATING_PIPE_SPACING_INVALID',
        );
      }
      pipeSpacingMm = /** @type {100 | 150 | 200} */ (spacingNum);
    }

    let furnitureOccupiedAreaM2 = 0;
    if (
      ufh.furnitureOccupiedAreaM2 !== undefined
      && ufh.furnitureOccupiedAreaM2 !== null
    ) {
      const furnitureNum = Number(ufh.furnitureOccupiedAreaM2);
      if (!Number.isFinite(furnitureNum) || furnitureNum < 0) {
        throwAppError(
          `furnitureOccupiedAreaM2: очікується число ≥ 0 (roomId="${room.id}").`,
          'UNDERFLOOR_HEATING_FURNITURE_AREA_INVALID',
        );
      }
      furnitureOccupiedAreaM2 = furnitureNum;
    }

    const roomAreaM2 = Number(room.areaM2);
    if (
      Number.isFinite(roomAreaM2)
      && furnitureOccupiedAreaM2 >= roomAreaM2
    ) {
      throwAppError(
        `furnitureOccupiedAreaM2=${furnitureOccupiedAreaM2} м²: має бути строго меншим за площу приміщення ${roomAreaM2} м² (roomId="${room.id}").`,
        'UNDERFLOOR_HEATING_FURNITURE_AREA_INVALID',
      );
    }

    const rawTerminal = ufh.ufhTerminalControl;
    if (
      rawTerminal !== undefined
      && rawTerminal !== null
      && !isUfhTerminalControl(rawTerminal)
    ) {
      throwAppError(
        `ufhTerminalControl: очікується "collector" або "unibox" (roomId="${room.id}").`,
        'UNDERFLOOR_HEATING_TERMINAL_INVALID',
      );
    }
    const ufhTerminalControl = resolveUfhTerminalControl(
      rawTerminal,
      roomAreaM2,
    );

    room.underfloorHeating = {
      enabled: true,
      basePresetId,
      finishMaterialId,
      pipeSpacingMm,
      ...(furnitureOccupiedAreaM2 > 0 ? { furnitureOccupiedAreaM2 } : {}),
      ...(ufhTerminalControl === 'unibox' ? { ufhTerminalControl: 'unibox' } : {}),
    };
  }
}

/**
 * floorPresetId в envelopeElements не должен ссылаться на сборки ТП.
 *
 * @param {unknown} building
 */
function assertEnvelopeFloorPresetsNotUnderfloorHeating(building) {
  if (!building || typeof building !== 'object') return;
  const elements = /** @type {import('../types/shared-types.js').BuildingInput} */ (building)
    .envelopeElements;
  if (!Array.isArray(elements)) return;

  for (const el of elements) {
    if (el.kind !== 'floor') continue;
    const pid = typeof el.presetId === 'string' ? el.presetId.trim() : '';
    if (pid && ENVELOPE_FORBIDDEN_UFH_FLOOR_IDS.has(pid)) {
      throwAppError(
        `presetId "${pid}" — пресет збірки ТП; для тепловтрат використовуйте envelopePresets (kind=floor), для ТП — room.underfloorHeating.`,
        'ENVELOPE_FLOOR_PRESET_MIXED_WITH_UFH',
      );
    }
  }
}

/**
 * Границы комнат до AJV: bottomBoundary обязателен в схеме.
 *
 * @param {unknown} building
 */
function normalizeRoomBoundariesBeforeValidate(building) {
  if (!building || typeof building !== 'object') return;
  const b = /** @type {import('../types/shared-types.js').BuildingInput} */ (building);
  const rooms = b.rooms;
  if (!Array.isArray(rooms)) return;

  const om = b.objectMeta;
  const objectType =
    om?.objectType === 'apartment' || om?.objectType === 'house' ? om.objectType : 'house';

  if (objectType === 'apartment' && om) {
    // Единственная нормализация apartmentStackPosition в пайплайне (до derive границ).
    om.apartmentStackPosition = normalizeApartmentStackPosition(om.apartmentStackPosition);
    const maxF = om.floors ?? 1;
    for (const r of rooms) {
      if (!r || typeof r !== 'object') continue;
      const floorNum = Math.max(1, Math.min(3, Math.trunc(Number(r.floor) || 1)));
      const floor = /** @type {1 | 2 | 3} */ (floorNum === 2 ? 2 : floorNum === 3 ? 3 : 1);
      const bounds = resolveApartmentRoomBoundaries(
        om.apartmentStackPosition,
        floor,
        maxF,
      );
      r.bottomBoundary = bounds.bottomBoundary;
      if (r.topBoundary !== 'roof') {
        r.topBoundary = bounds.topBoundary;
      }
    }
    return;
  }

  for (const r of rooms) {
    if (!r || typeof r !== 'object') continue;
    if (r.bottomBoundary !== 'heated' && r.bottomBoundary !== 'unheated') {
      r.bottomBoundary = defaultHouseBottomBoundary(r.floor);
    }
  }
}

/**
 * Предупреждения по пресетам потолка квартиры (в heatingSystem._normalizationWarnings).
 *
 * @param {unknown} clone
 */
function collectApartmentEnvelopeWarnings(clone) {
  if (!isPlainObject(clone)) return;
  const body = /** @type {import('../types/shared-types.js').CalcRequestBody} */ (
    /** @type {unknown} */ (clone)
  );
  const building = body.building;
  if (building?.objectMeta?.objectType !== 'apartment') return;

  /** @type {string[]} */
  const warns = [];
  const elements = building.envelopeElements ?? [];
  const roomsById = new Map((building.rooms ?? []).map((r) => [r.id, r]));

  for (const el of elements) {
    if (!el || typeof el !== 'object') continue;
    if (el.kind !== 'ceiling') continue;
    const room = roomsById.get(String(el.roomId ?? ''));
    if (!room) continue;
    const msg = warnApartmentCeilingPresetMismatch(room.topBoundary, el.presetId);
    if (msg) warns.push(msg);
  }

  if (warns.length === 0) return;
  if (!body.heatingSystem || typeof body.heatingSystem !== 'object') {
    body.heatingSystem = {};
  }
  const hs = /** @type {Record<string, unknown>} */ (body.heatingSystem);
  const prev = Array.isArray(hs._normalizationWarnings) ? hs._normalizationWarnings : [];
  hs._normalizationWarnings = [...prev, ...warns];
}

/**
 * Дефолт режима вентиляции для MVP (kVent по комнатам).
 *
 * @param {unknown} clone
 */
function normalizeObjectMetaVentilationReserve(clone) {
  if (!clone || typeof clone !== 'object') return;
  const building = /** @type {{ building?: import('../types/shared-types.js').BuildingInput }} */ (
    clone
  ).building;
  if (!building?.objectMeta || typeof building.objectMeta !== 'object') return;
  building.objectMeta.ventilationReserveMode = normalizeVentilationReserveMode(
    building.objectMeta.ventilationReserveMode,
  );
}

/**
 * MVP: расход L / кратность n на здание не используются — только kVent по комнатам.
 *
 * @param {unknown} clone
 */
function assertVentilationLegacyFieldsDisabled(clone) {
  if (!clone || typeof clone !== 'object') return;
  const building = /** @type {{ building?: import('../types/shared-types.js').BuildingInput }} */ (
    clone
  ).building;
  const v = building?.ventilation;
  if (!v || typeof v !== 'object') return;

  const flow = Number(v.flowM3PerHour);
  const n = Number(v.airChangesPerHour);
  const hasFlow = Number.isFinite(flow) && flow > 0;
  const hasN = Number.isFinite(n) && n > 0;
  if (!hasFlow && !hasN) return;

  throwAppError(
    'Поля building.ventilation.flowM3PerHour і airChangesPerHour у MVP не використовуються. ' +
      'Задайте building.objectMeta.ventilationReserveMode: natural (kVent 1.3) або recuperation (kVent 1.1).',
    'VENTILATION_LEGACY_FIELD',
  );
}

/**
 * Cross-validation: зона установки котла и объём котельной (дом).
 *
 * @param {unknown} clone
 * @param {import('../dhw/types.js').AppliancesBundle} appliances
 */
function assertBoilerPlacementAndBoilerRoom(clone, appliances) {
  if (!clone || typeof clone !== 'object') return;
  const building = /** @type {import('../types/shared-types.js').BuildingInput | undefined} */ (
    /** @type {{ building?: import('../types/shared-types.js').BuildingInput }} */ (clone).building
  );
  if (!building?.objectMeta || typeof building.objectMeta !== 'object') return;

  const om = /** @type {Record<string, unknown>} */ (
    /** @type {unknown} */ (building.objectMeta)
  );
  const objectType = resolveObjectType(
    /** @type {import('../types/shared-types.js').BuildingObjectMeta} */ (
      /** @type {unknown} */ (om)
    ),
  );

  if (objectType === 'apartment') {
    // apartmentStackPosition нормализуется в normalizeRoomBoundariesBeforeValidate (фаза 3).
    if (om.boilerPlacementZone != null) delete om.boilerPlacementZone;
    if (om.boilerRoomAreaM2 != null) delete om.boilerRoomAreaM2;
    if (om.ceilingHeightM != null) delete om.ceilingHeightM;
    if (om.indirectDhwSpaceAvailable === false) delete om.indirectDhwSpaceAvailable;
    return;
  }

  if (om.apartmentStackPosition != null) delete om.apartmentStackPosition;

  if (om.indirectDhwSpaceAvailable != null) delete om.indirectDhwSpaceAvailable;

  if (om.boilerPlacementZone == null || om.boilerPlacementZone === '') {
    om.boilerPlacementZone = 'kitchen';
  }

  const zone = om.boilerPlacementZone;
  if (
    typeof zone !== 'string' ||
    !['kitchen', 'living_zone', 'boiler_room'].includes(zone)
  ) {
    throwAppError(
      'Для будинку вкажіть building.objectMeta.boilerPlacementZone: kitchen, living_zone або boiler_room.',
      'BOILER_PLACEMENT_REQUIRED',
    );
  }

  if (zone !== 'boiler_room') {
    return;
  }

  const hasMetaArea = om.boilerRoomAreaM2 != null;
  const hasMetaHeight = om.ceilingHeightM != null;
  if (hasMetaArea !== hasMetaHeight) {
    throwAppError(
      'Вкажіть обидва поля boilerRoomAreaM2 і ceilingHeightM або додайте приміщення type=котельная в building.rooms.',
      'BOILER_ROOM_METRICS_INCOMPLETE',
    );
  }

  const mounting = appliances.byKind.boiler.mounting;

  const metrics = resolveBoilerRoomMetrics(
    building,
    /** @type {import('../types/shared-types.js').BuildingObjectMeta} */ (
      /** @type {unknown} */ (om)
    ),
    mounting,
  );

  if (!isBoilerRoomVolumeCompliant(metrics, mounting)) {
    throwAppError(
      `Для напольного котла в окремій котельні потрібен об'єм не менше ${mounting.minBoilerRoomVolumeM3} м³ і висота не менше ${mounting.minBoilerRoomHeightM} м (приміщення type=${getBoilerRoomType(mounting)} в rooms або boilerRoomAreaM2×ceilingHeightM).`,
      'BOILER_ROOM_VOLUME_INVALID',
    );
  }
}

/**
 * Нормализация связки котёл/ГВС и тип объекта после AJV (без 400 там, где достаточно авто-поправки).
 *
 * @param {unknown} clone — нормализованное тело запроса calc
 * @param {import('../dhw/types.js').AppliancesBundle} appliances
 */
function assertBoilerDhwSchemeCompatibility(clone, appliances) {
  if (!isPlainObject(clone)) return;
  const body = /** @type {import('../types/shared-types.js').CalcRequestBody} */ (
    /** @type {unknown} */ (clone)
  );
  const ot = body.building?.objectMeta?.objectType;
  const objectType = ot === 'apartment' ? 'apartment' : 'house';

  const hsEarly = body.heatingSystem;
  const scheme =
    isPlainObject(hsEarly) &&
    typeof hsEarly.hotWaterBoilerPowerMatchingScheme === 'string'
      ? hsEarly.hotWaterBoilerPowerMatchingScheme
      : HOT_WATER_BOILER_MATCHING_SCHEME_ENUM[0];

  // Квартира + одноконтурный с БКН: для малых — max-combi; для больших с местом под БКН — разрешено.
  if (scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM && objectType === 'apartment') {
    if (!body.heatingSystem || typeof body.heatingSystem !== 'object') {
      body.heatingSystem = {};
    }

    const building = body.building;
    const fixtures = body.hotWater?.fixtures;
    const isLarge = isLargeApartmentByInput(
      building,
      fixtures,
      appliances.byKind.boiler.apartmentClassification,
    );
    const hasSpace =
      building?.objectMeta?.indirectDhwSpaceAvailable === true;

    const hs = /** @type {Record<string, unknown>} */ (body.heatingSystem);

    if (!isLarge) {
      hs.hotWaterBoilerPowerMatchingScheme = SCHEME_BOILER_MAX_COMBI;
      hs._normalizationWarnings = [
        'Зв\'язка «Одноконтурний котел + БКН» змінено на двоконтурну: для малих квартир БКН надмірний за габаритами.',
      ];
      return;
    }

    if (!hasSpace) {
      hs.hotWaterBoilerPowerMatchingScheme = SCHEME_BOILER_MAX_COMBI;
      hs._normalizationWarnings = [
        'Зв\'язка «1К + БКН» змінено на двоконтурну: вкажіть наявність місця під бойлер (objectMeta.indirectDhwSpaceAvailable).',
      ];
      return;
    }

    hs._apartmentIndirectDhwStorage = true;
    return;
  }
}

/**
 * Назначение: общая обработка ошибок auth middleware.
 */

import { sendErrorEnvelope } from '../api/sendErrorEnvelope.js';
import { logger } from '../utils/logger.js';

/**
 * @param {unknown} err
 * @returns {{ statusCode: number, code: string, message: string }}
 */
export function mapAuthErrorToResponse(err) {
  const known = err && typeof err === 'object' ? /** @type {import('../types/shared-types.js').AppErrorLike} */ (err) : null;
  const statusCode =
    known?.statusCode === 503 ? 503 : known?.statusCode === 401 ? 401 : 403;

  /** @type {string} */
  let code = 'PROJECTS_AUTH_FORBIDDEN';
  if (known?.code === 'PROJECTS_AUTH_NOT_CONFIGURED') {
    code = 'PROJECTS_AUTH_NOT_CONFIGURED';
  } else if (known?.code === 'MONGODB_UNAVAILABLE') {
    code = 'MONGODB_UNAVAILABLE';
  } else if (known?.code) {
    code = known.code;
  }

  /** @type {string} */
  let message = 'Недійсний або прострочений токен';
  if (statusCode === 503 && code === 'PROJECTS_AUTH_NOT_CONFIGURED') {
    message = 'Аутентифікація проєктів не налаштована на сервері';
  } else if (code === 'MONGODB_UNAVAILABLE') {
    message = 'Не вдалося підключитися до MongoDB.';
  } else if (err instanceof Error && err.message) {
    message = err.message;
  }

  return { statusCode, code, message };
}

/**
 * @param {import('express').Request} req
 * @param {import('express').Response<import('../types/shared-types.js').ErrorEnvelope>} res
 * @param {{ statusCode?: number; code?: string; message?: string } | unknown} err
 * @returns {void}
 */
export function respondAuthorizationError(req, res, err) {
  const known =
    err && typeof err === 'object'
      ? /** @type {import('../types/shared-types.js').AppErrorLike} */ (err)
      : null;
  const statusCode = known?.statusCode === 403 ? 403 : 403;
  const code =
    typeof known?.code === 'string' && known.code.length > 0
      ? known.code
      : 'AUTHORIZATION_FORBIDDEN';
  const message =
    known instanceof Error && known.message
      ? known.message
      : typeof known?.message === 'string' && known.message
        ? known.message
        : 'Доступ заборонено';

  /** @type {{ requestId?: string } | null} */
  const logMeta = req.requestId ? { requestId: req.requestId } : null;

  logger.warn('auth.authorization.failed', logMeta, {
    statusCode,
    code,
    message,
  });

  sendErrorEnvelope(res, { statusCode, message, code });
}

/**
 * @param {import('express').Request} req
 * @param {import('express').Response<import('../types/shared-types.js').ErrorEnvelope>} res
 * @param {unknown} err
 * @returns {void}
 */
export function respondAuthError(req, res, err) {
  const { statusCode, code, message } = mapAuthErrorToResponse(err);

  /** @type {{ requestId?: string } | null} */
  const logMeta = req.requestId ? { requestId: req.requestId } : null;

  logger.warn('auth.failed', logMeta, {
    statusCode,
    code,
    message: err instanceof Error ? err.message : String(err),
  });

  sendErrorEnvelope(res, { statusCode, message, code });
}

/**
 * Назначение: нормализация verified JWT payload → AuthIdentity.
 * Описание: IdP-agnostic mapping claims; единственное место чтения email/name/sub.
 */

import { resolveAuthProvider } from './projectsAuthConfig.js';

/**
 * @param {import('jose').JWTPayload} payload
 * @returns {import('../types/auth.js').AuthProvider}
 */
function resolveProviderFromPayload(payload) {
  const fromEnv = resolveAuthProvider();
  if (fromEnv) return fromEnv;

  const iss = typeof payload.iss === 'string' ? payload.iss.trim() : '';
  if (iss) {
    const mapRaw = process.env.AUTH_ISSUER_PROVIDER_MAP?.trim();
    if (mapRaw) {
      try {
        const parsed = /** @type {unknown} */ (JSON.parse(mapRaw));
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
          const mapped = /** @type {Record<string, unknown>} */ (parsed)[iss];
          if (mapped === 'clerk' || mapped === 'auth0') {
            return mapped;
          }
        }
      } catch {
        // ignore invalid JSON — fallback ниже
      }
    }
  }

  const err = new Error('AUTH_PROVIDER не задан и issuer не сопоставлен');
  /** @type {import('../types/shared-types.js').AppErrorLike} */
  const appErr = err;
  appErr.code = 'PROJECTS_AUTH_FORBIDDEN';
  appErr.statusCode = 403;
  throw err;
}

/**
 * @param {import('jose').JWTPayload} payload
 * @returns {string}
 */
function requireProviderUserId(payload) {
  const sub = payload.sub;
  if (typeof sub !== 'string' || !sub.trim()) {
    const err = new Error('JWT без claim sub');
    /** @type {import('../types/shared-types.js').AppErrorLike} */
    const appErr = err;
    appErr.code = 'PROJECTS_AUTH_FORBIDDEN';
    appErr.statusCode = 403;
    throw err;
  }
  return sub.trim();
}

/**
 * @param {import('jose').JWTPayload} payload
 * @returns {string | null}
 */
function readEmailClaim(payload) {
  if (typeof payload.email === 'string' && payload.email.trim()) {
    return payload.email.trim().toLowerCase();
  }
  return null;
}

/**
 * @param {import('jose').JWTPayload} payload
 * @returns {boolean}
 */
function readEmailVerified(payload) {
  return payload.email_verified === true;
}

/**
 * @param {import('jose').JWTPayload} payload
 * @returns {string | undefined}
 */
function readNameClaim(payload) {
  if (typeof payload.name === 'string' && payload.name.trim()) {
    return payload.name.trim();
  }
  const given = typeof payload.given_name === 'string' ? payload.given_name.trim() : '';
  const family = typeof payload.family_name === 'string' ? payload.family_name.trim() : '';
  const combined = [given, family].filter(Boolean).join(' ').trim();
  return combined || undefined;
}

/**
 * @param {import('jose').JWTPayload} payload — только после jose.jwtVerify().
 * @returns {import('../types/auth.js').AuthIdentity}
 */
export function mapJwtPayload(payload) {
  const providerUserId = requireProviderUserId(payload);
  const email = readEmailClaim(payload);
  if (!email) {
    const err = new Error('JWT без claim email');
    /** @type {import('../types/shared-types.js').AppErrorLike} */
    const appErr = err;
    appErr.code = 'PROJECTS_AUTH_FORBIDDEN';
    appErr.statusCode = 403;
    throw err;
  }

  const name = readNameClaim(payload);

  return {
    provider: resolveProviderFromPayload(payload),
    providerUserId,
    email,
    emailVerified: readEmailVerified(payload),
    ...(name ? { name } : {}),
  };
}

/**
 * Назначение: конфигурация JWT-аутентификации для API проектов.
 * Описание: Clerk/Auth0 — OIDC + JWKS (RS256/ES256); HS256 только для изолированных unit-тестов.
 * Режимы AUTH_JWKS_URI и AUTH_JWT_SECRET взаимоисключающие.
 */

import mongoose from 'mongoose';

/** @type {readonly import('../types/auth.js').AuthProvider[]} */
const AUTH_PROVIDERS = ['clerk', 'auth0'];

/**
 * @returns {boolean}
 */
function isProductionRuntime() {
  return process.env.NODE_ENV === 'production';
}

/**
 * Auth enforced на runtime (production или dev с PROJECTS_AUTH_ENABLED=true).
 * @returns {boolean}
 */
export function isAuthEnforcedByConfig() {
  return isProductionRuntime() || process.env.PROJECTS_AUTH_ENABLED === 'true';
}

/**
 * @returns {boolean}
 */
export function isProjectsAuthRequired() {
  return isAuthEnforcedByConfig();
}

/**
 * @returns {boolean}
 */
export function hasConflictingJwtConfig() {
  const jwks = process.env.AUTH_JWKS_URI?.trim();
  const secret = process.env.AUTH_JWT_SECRET?.trim();
  return Boolean(jwks && secret);
}

/**
 * @returns {import('../types/auth.js').AuthJwtMode | null}
 */
export function resolveAuthJwtMode() {
  if (hasConflictingJwtConfig()) return null;

  const jwks = process.env.AUTH_JWKS_URI?.trim();
  const secret = process.env.AUTH_JWT_SECRET?.trim();
  if (jwks) return 'jwks';
  if (secret) return 'hs256';
  return null;
}

/**
 * @returns {import('../types/auth.js').AuthProvider | null}
 */
export function resolveAuthProvider() {
  const raw = process.env.AUTH_PROVIDER?.trim().toLowerCase();
  if (raw === 'clerk' || raw === 'auth0') {
    return raw;
  }
  return null;
}

/**
 * @returns {boolean}
 */
export function hasProjectsJwtConfig() {
  return resolveAuthJwtMode() !== null;
}

/**
 * @param {{ production?: boolean; authEnforced?: boolean }} [options]
 * @returns {import('../types/auth.js').AuthConfigValidationResult}
 */
export function validateAuthConfiguration(options = {}) {
  const production = options.production ?? isProductionRuntime();
  const authEnforced = options.authEnforced ?? isAuthEnforcedByConfig();
  /** @type {string[]} */
  const errors = [];

  if (hasConflictingJwtConfig()) {
    errors.push(
      'Задайте либо AUTH_JWKS_URI (Clerk/Auth0 OIDC), либо AUTH_JWT_SECRET (локальный HS256 для unit-тестов), но не оба одновременно.',
    );
    return { ok: false, mode: null, errors };
  }

  const mode = resolveAuthJwtMode();

  if (!mode) {
    errors.push(
      'Задайте AUTH_JWKS_URI (Clerk/Auth0: JWKS + issuer + audience) или AUTH_JWT_SECRET (только unit-тесты без PROJECTS_AUTH_ENABLED).',
    );
    return { ok: false, mode: null, errors };
  }

  if (mode === 'jwks') {
    if (!process.env.AUTH_JWKS_URI?.trim()) {
      errors.push('AUTH_JWKS_URI обязателен для режима OIDC/JWKS (Clerk/Auth0).');
    }
    if (!process.env.AUTH_ISSUER?.trim()) {
      errors.push('AUTH_ISSUER обязателен для режима OIDC/JWKS.');
    }
    if (!process.env.AUTH_AUDIENCE?.trim()) {
      errors.push('AUTH_AUDIENCE обязателен для режима OIDC/JWKS.');
    }
    if ((production || authEnforced) && !resolveAuthProvider()) {
      errors.push('AUTH_PROVIDER обязателен при включённой auth (clerk | auth0).');
    }
  }

  if (mode === 'hs256') {
    if (!process.env.AUTH_JWT_SECRET?.trim()) {
      errors.push('AUTH_JWT_SECRET обязателен для режима HS256.');
    }
    if (production || authEnforced) {
      errors.push(
        'При включённой auth (production или PROJECTS_AUTH_ENABLED=true) используйте Clerk/Auth0: AUTH_JWKS_URI, AUTH_ISSUER, AUTH_AUDIENCE, AUTH_PROVIDER=clerk. AUTH_JWT_SECRET — не для runtime.',
      );
    }
  }

  const provider = resolveAuthProvider();
  if (provider && !AUTH_PROVIDERS.includes(provider)) {
    errors.push(`AUTH_PROVIDER="${provider}" недопустим; допустимо: clerk | auth0.`);
  }

  return { ok: errors.length === 0, mode, errors };
}

/**
 * Fail fast: production не стартует без полной конфигурации Clerk/Auth0 JWKS.
 * @returns {void}
 */
export function assertAuthConfiguredForProduction() {
  if (!isProductionRuntime()) return;

  const result = validateAuthConfiguration({ production: true, authEnforced: true });
  if (result.ok) return;

  process.stderr.write('NODE_ENV=production: конфигурация JWT-аутентификации неполная:\n');
  for (const message of result.errors) {
    process.stderr.write(`  - ${message}\n`);
  }
  process.exitCode = 1;
}

/**
 * Fail fast при PROJECTS_AUTH_ENABLED=true в dev — только JWKS (Clerk).
 * @returns {void}
 */
export function assertAuthConfiguredWhenEnabled() {
  if (!isAuthEnforcedByConfig() || isProductionRuntime()) return;

  const result = validateAuthConfiguration({ production: false, authEnforced: true });
  if (result.ok) return;

  process.stderr.write('PROJECTS_AUTH_ENABLED=true: конфигурация Clerk/JWKS неполная:\n');
  for (const message of result.errors) {
    process.stderr.write(`  - ${message}\n`);
  }
  process.exitCode = 1;
}

/** Фиксированный ObjectId dev-владельца, если PROJECTS_DEV_OWNER_ID не задан или невалиден. */
export const DEFAULT_DEV_OWNER_OBJECT_ID_HEX = '000000000000000000000001';

/**
 * ObjectId dev-владельца для локальной разработки без JWT.
 * PROJECTS_DEV_OWNER_ID — 24-символьный hex ObjectId; иначе DEFAULT_DEV_OWNER_OBJECT_ID_HEX.
 *
 * @returns {import('mongoose').Types.ObjectId}
 */
export function resolveProjectsDevOwnerObjectId() {
  const fromEnv = process.env.PROJECTS_DEV_OWNER_ID?.trim();
  if (fromEnv && /^[a-fA-F0-9]{24}$/.test(fromEnv)) {
    return new mongoose.Types.ObjectId(fromEnv);
  }
  return new mongoose.Types.ObjectId(DEFAULT_DEV_OWNER_OBJECT_ID_HEX);
}

/**
 * Hex-строка ObjectId dev-владельца (для логов и verify).
 *
 * @returns {string}
 */
export function resolveProjectsDevOwnerId() {
  return String(resolveProjectsDevOwnerObjectId());
}

/**
 * @returns {boolean}
 */
export function isRateLimitDisabled() {
  return !isProductionRuntime() && process.env.RATE_LIMIT_DISABLED === 'true';
}

/**
 * @returns {number}
 */
export function resolveMaxProjectsPerOwner() {
  const n = Number(process.env.PROJECTS_MAX_PER_OWNER);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 200;
}

/**
 * @returns {number}
 */
export function resolveMaxCalculationsPerProject() {
  const n = Number(process.env.PROJECTS_MAX_CALCULATIONS_PER_PROJECT);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 100;
}

/**
 * Назначение: материализация AuthIdentity → AuthUser (MongoDB users).
 * Описание: find по (authProvider, providerUserId) или create один раз; без upsert на каждый request.
 */
import { normalizeAuthUserAuthorization } from './authorizationPolicy.js';
import { isPlatformAdminEmail } from './platformAdminAllowlist.js';
import { User } from '../models/public.js';
import { ensureMongoReferenceConnection } from '../utils/mongoReferenceConnection.js';
import { logger } from '../utils/logger.js';

/**
 * @param {import('../types/shared-types.js').UserMongoDoc} doc
 * @returns {import('../types/auth.js').AuthUser}
 */
export function userDocumentToAuthUser(doc) {
  const id = doc._id != null ? String(doc._id) : '';
  if (!id) {
    throw new Error('User document без _id');
  }

  return normalizeAuthUserAuthorization({
    id,
    authProvider: doc.authProvider,
    providerUserId: doc.providerUserId,
    email: doc.email,
    emailVerified: doc.emailVerified,
    ...(doc.name ? { name: doc.name } : {}),
    role: doc.role,
    subscription: doc.subscription,
  });
}

/**
 * @param {import('../types/auth.js').AuthIdentity} identity
 * @returns {Promise<import('../types/auth.js').AuthUser>}
 */
export async function resolveUser(identity) {
  const connected = await ensureMongoReferenceConnection();
  if (!connected) {
    const err = new Error('MongoDB недоступна для resolveUser');
    /** @type {import('../types/shared-types.js').AppErrorLike} */
    const appErr = err;
    appErr.code = 'MONGODB_UNAVAILABLE';
    appErr.statusCode = 503;
    throw err;
  }

  let user = await User.findOne({
    authProvider: identity.provider,
    providerUserId: identity.providerUserId,
  });

  if (!user) {
    const platformAdmin = isPlatformAdminEmail(identity.email);
    try {
      user = await User.create({
        authProvider: identity.provider,
        providerUserId: identity.providerUserId,
        email: identity.email,
        emailVerified: identity.emailVerified,
        ...(identity.name ? { name: identity.name } : {}),
        ...(platformAdmin ? { role: 'admin' } : {}),
      });
    } catch (createErr) {
      const code =
        createErr && typeof createErr === 'object'
          ? /** @type {{ code?: number }} */ (createErr).code
          : undefined;
      if (code === 11000) {
        user = await User.findOne({
          authProvider: identity.provider,
          providerUserId: identity.providerUserId,
        });
      }
      if (!user) throw createErr;
    }
  }

  if (isPlatformAdminEmail(identity.email) && user.role !== 'admin') {
    const userId = user._id != null ? String(user._id) : '';
    user = await User.findByIdAndUpdate(
      user._id,
      { $set: { role: 'admin' } },
      { new: true, runValidators: true },
    );
    if (!user) {
      throw new Error('Platform admin sync: пользователь не найден после update');
    }
    if (userId) {
      logger.info('auth.platform_admin.sync', null, { userId });
    }
  }

  return userDocumentToAuthUser(user);
}

/**
 * Назначение: проверка Bearer JWT для API проектов.
 * Описание: Clerk/Auth0 — OIDC + JOSE + JWKS (RS256/ES256); HS256 только для unit-тестов.
 */

import * as jose from 'jose';
import { hasProjectsJwtConfig, resolveAuthJwtMode } from './projectsAuthConfig.js';

/** @type {ReturnType<typeof jose.createRemoteJWKSet> | null} */
let remoteJwks = null;

/**
 * @returns {ReturnType<typeof jose.createRemoteJWKSet>}
 */
function getRemoteJwks() {
  const jwksUri = process.env.AUTH_JWKS_URI?.trim();
  if (!jwksUri) {
    throw new Error('AUTH_JWKS_URI не задан');
  }
  if (!remoteJwks) {
    remoteJwks = jose.createRemoteJWKSet(new URL(jwksUri));
  }
  return remoteJwks;
}

/**
 * @returns {jose.JWTVerifyOptions}
 */
function buildVerifyOptions() {
  const verifyOptions = /** @type {jose.JWTVerifyOptions} */ ({});
  const issuer = process.env.AUTH_ISSUER?.trim();
  const audience = process.env.AUTH_AUDIENCE?.trim();
  if (issuer) verifyOptions.issuer = issuer;
  if (audience) verifyOptions.audience = audience;
  return verifyOptions;
}

/**
 * @param {string} bearerToken — без префикса Bearer
 * @returns {Promise<jose.JWTPayload>}
 */
export async function verifyAccessToken(bearerToken) {
  if (!hasProjectsJwtConfig()) {
    const err = new Error('AUTH_NOT_CONFIGURED');
    /** @type {import('../types/shared-types.js').AppErrorLike} */
    const appErr = err;
    appErr.code = 'PROJECTS_AUTH_NOT_CONFIGURED';
    appErr.statusCode = 503;
    throw err;
  }

  const mode = resolveAuthJwtMode();
  const verifyOptions = buildVerifyOptions();

  /** @type {jose.JWTVerifyResult<jose.JWTPayload>} */
  let result;
  try {
    if (mode === 'jwks') {
      result = await jose.jwtVerify(bearerToken, getRemoteJwks(), verifyOptions);
    } else if (mode === 'hs256') {
      const secret = process.env.AUTH_JWT_SECRET?.trim();
      if (!secret) {
        const err = new Error('AUTH_NOT_CONFIGURED');
        /** @type {import('../types/shared-types.js').AppErrorLike} */
        const appErr = err;
        appErr.code = 'PROJECTS_AUTH_NOT_CONFIGURED';
        appErr.statusCode = 503;
        throw err;
      }
      const key = new TextEncoder().encode(secret);
      result = await jose.jwtVerify(bearerToken, key, verifyOptions);
    } else {
      const err = new Error('AUTH_NOT_CONFIGURED');
      /** @type {import('../types/shared-types.js').AppErrorLike} */
      const appErr = err;
      appErr.code = 'PROJECTS_AUTH_NOT_CONFIGURED';
      appErr.statusCode = 503;
      throw err;
    }
  } catch (verifyErr) {
    if (
      verifyErr &&
      typeof verifyErr === 'object' &&
      /** @type {import('../types/shared-types.js').AppErrorLike} */ (verifyErr).code ===
        'PROJECTS_AUTH_NOT_CONFIGURED'
    ) {
      throw verifyErr;
    }
    const err = new Error(
      verifyErr instanceof Error ? verifyErr.message : 'JWT verify failed',
    );
    /** @type {import('../types/shared-types.js').AppErrorLike} */
    const appErr = err;
    appErr.code = 'PROJECTS_AUTH_FORBIDDEN';
    appErr.statusCode = 403;
    throw err;
  }

  return result.payload;
}

/**
 * Назначение: паспортная геометрия серий котельных коллекторов (boilerManifold).
 * Описание: фиксированные габариты и формула ширины для известных серий каталога.
 */

/** @typedef {'fado_kgz'} BoilerManifoldSeriesId */

/** Допуск сравнения габаритов, мм. */
export const BOILER_MANIFOLD_GEOMETRY_TOLERANCE_MM = 0.5;

/**
 * @typedef {Object} BoilerManifoldSeriesGeometryPreset
 * @property {number} depth Глубина, мм.
 * @property {number} height Высота, мм.
 * @property {number} interaxleDistanceMm Межосевое, мм (для формулы ширины FADO).
 * @property {string} connectionBoilerInch
 * @property {string} connectionCircuitsInch
 * @property {number} maxPowerKw Ожидаемая maxPowerKw серии.
 * @property {number} maxPressureBar
 * @property {number} maxTemperatureC
 * @property {Record<number, number>} widthByCircuitsCount Таблица ширины по circuitsCount.
 */

/** @type {Record<BoilerManifoldSeriesId, Readonly<BoilerManifoldSeriesGeometryPreset>>} */
export const BOILER_MANIFOLD_SERIES_GEOMETRY = Object.freeze({
  fado_kgz: Object.freeze({
    depth: 135,
    height: 178,
    interaxleDistanceMm: 125,
    connectionBoilerInch: '1 1/2',
    connectionCircuitsInch: '1 1/2',
    maxPowerKw: 85,
    maxPressureBar: 6,
    maxTemperatureC: 100,
    widthByCircuitsCount: Object.freeze({
      3: 500,
      5: 750,
      7: 1000,
    }),
  }),
});

/**
 * Нормализует обозначение резьбы.
 *
 * @param {unknown} raw
 * @returns {string}
 */
export function normalizeBoilerManifoldInchLabel(raw) {
  return String(raw ?? '')
    .replace(/[<>]/g, '')
    .replace(/"/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * @param {Record<string, unknown>} item
 * @returns {BoilerManifoldSeriesId | null}
 */
export function resolveBoilerManifoldSeriesId(item) {
  const article = String(item.article ?? '').trim().toUpperCase();
  const brand = String(item.brand ?? '').trim().toLowerCase();

  if (article.startsWith('KGZ') || brand === 'fado') {
    return 'fado_kgz';
  }
  return null;
}

/**
 * Ожидаемая ширина котельного коллектора FADO: (circuitsCount + 1) × межосевое.
 *
 * @param {number} circuitsCount
 * @param {number} interaxleDistanceMm
 * @returns {number}
 */
export function expectedBoilerManifoldWidthMm(circuitsCount, interaxleDistanceMm) {
  return (circuitsCount + 1) * interaxleDistanceMm;
}

/**
 * @param {Record<string, unknown>} item
 * @param {string} ctx
 */
export function assertKnownBoilerManifoldSeriesGeometry(item, ctx) {
  const seriesId = resolveBoilerManifoldSeriesId(item);
  if (!seriesId) return;

  const preset = BOILER_MANIFOLD_SERIES_GEOMETRY[seriesId];
  const circuitsCount = Number(item.circuitsCount);

  const expectedFromTable = preset.widthByCircuitsCount[circuitsCount];
  if (expectedFromTable == null) {
    throw new Error(
      `Каталог: ${ctx} — для серии ${seriesId} circuitsCount=${circuitsCount} не поддерживается.`,
    );
  }

  const interaxle = Number(item.interaxleDistanceMm);
  if (Math.abs(interaxle - preset.interaxleDistanceMm) > BOILER_MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — interaxleDistanceMm=${interaxle}, ожидалось ${preset.interaxleDistanceMm} (серия ${seriesId}).`,
    );
  }

  const expectedW = expectedBoilerManifoldWidthMm(circuitsCount, preset.interaxleDistanceMm);
  if (Math.abs(expectedW - expectedFromTable) > BOILER_MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — внутренняя ошибка пресета ширины для ${seriesId}.`,
    );
  }

  if (normalizeBoilerManifoldInchLabel(item.connectionBoilerInch) !== preset.connectionBoilerInch) {
    throw new Error(
      `Каталог: ${ctx} — connectionBoilerInch должен быть "${preset.connectionBoilerInch}" (серия ${seriesId}).`,
    );
  }
  if (
    normalizeBoilerManifoldInchLabel(item.connectionCircuitsInch) !== preset.connectionCircuitsInch
  ) {
    throw new Error(
      `Каталог: ${ctx} — connectionCircuitsInch должен быть "${preset.connectionCircuitsInch}" (серия ${seriesId}).`,
    );
  }

  const maxPowerKw = Number(item.maxPowerKw);
  if (Math.abs(maxPowerKw - preset.maxPowerKw) > 0.01) {
    throw new Error(
      `Каталог: ${ctx} — maxPowerKw=${maxPowerKw}, ожидалось ${preset.maxPowerKw} (серия ${seriesId}).`,
    );
  }

  const dimensions = item.dimensions;
  if (!dimensions || typeof dimensions !== 'object') {
    throw new Error(`Каталог: ${ctx} — dimensions обязателен для серии ${seriesId}.`);
  }

  const dim = /** @type {Record<string, unknown>} */ (dimensions);
  const depth = Number(dim.depth);
  const height = Number(dim.height);
  const width = Number(dim.width);

  if (Math.abs(depth - preset.depth) > BOILER_MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — depth=${depth}, ожидалось ${preset.depth} (серия ${seriesId}).`,
    );
  }
  if (Math.abs(height - preset.height) > BOILER_MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — height=${height}, ожидалось ${preset.height} (серия ${seriesId}).`,
    );
  }
  if (Math.abs(width - expectedFromTable) > BOILER_MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — width=${width}, ожидалось ${expectedFromTable} ` +
        `(серия ${seriesId}: (${circuitsCount}+1)×${preset.interaxleDistanceMm}).`,
    );
  }
}

/**
 * Назначение: загрузка каталога оборудования.
 * Описание: чтение номенклатуры из MongoDB (коллекция products) или локального JSON с режимами
 * mongo, file и auto; нормализация через validateAndNormalizeCatalog.
 */
import * as fs from 'node:fs/promises';
import { validateAndNormalizeCatalog } from './validateCatalog.js';
import { resolvePipeCatalogId } from './pipeCatalogHelpers.js';
import { resolvePumpCatalogId } from './pumpCatalogHelpers.js';
import { resolveUniboxCatalogId } from './uniboxCatalogHelpers.js';
import { Product } from '../models/public.js';
import { logger } from '../utils/logger.js';
import { ensureMongoReferenceConnection } from '../utils/mongoReferenceConnection.js';
import { resolveCatalogJsonFilePath } from '../../scripts/utils/catalogPaths.js';

/**
 * Завантаження каталогу обладнання.
 *
 * - mongo: тільки колекція Product (production); порожня БД — помилка.
 * - file: тільки локальний JSON (offline dev).
 * - auto: Mongo; при недоступності БД — чистий файл без merge.
 */

/**
 * @param {unknown} json
 * @returns {number}
 */
function countBoilersInProductsJson(json) {
  if (!json || typeof json !== 'object') return 0;
  const products = /** @type {Record<string, unknown>} */ (json).products;
  if (!products || typeof products !== 'object') return 0;
  const boilers = /** @type {Record<string, unknown>} */ (products).boilers;
  if (!boilers || typeof boilers !== 'object' || Array.isArray(boilers)) return 0;
  const boilersRec = /** @type {Record<string, unknown>} */ (boilers);
  const dc = boilersRec.doubleCircuit;
  const sc = boilersRec.singleCircuit;
  return (Array.isArray(dc) ? dc.length : 0) + (Array.isArray(sc) ? sc.length : 0);
}

/**
 * @param {unknown} json
 * @returns {number}
 */
function countProductRowsInEnvelope(json) {
  if (!json || typeof json !== 'object') return 0;
  const productsRaw = /** @type {Record<string, unknown>} */ (json).products;
  if (!productsRaw || typeof productsRaw !== 'object' || Array.isArray(productsRaw)) return 0;
  /** @type {Record<string, unknown>} */
  const products = /** @type {Record<string, unknown>} */ (productsRaw);
  const root = /** @type {Record<string, unknown>} */ (json);
  const boilers = countBoilersInProductsJson(json);
  const radiators = Array.isArray(products.radiators) ? products.radiators.length : 0;
  const waterHeaters = Array.isArray(products.waterHeaters)
    ? products.waterHeaters.length
    : 0;
  const pipes = Array.isArray(products.pipes) ? products.pipes.length : 0;
  const pumps = Array.isArray(root.pumps)
    ? root.pumps.length
    : Array.isArray(products.pumps)
      ? products.pumps.length
      : 0;
  const indirect = Array.isArray(root.indirectWaterHeaters)
    ? root.indirectWaterHeaters.length
    : 0;
  const manifolds = Array.isArray(root.manifold) ? root.manifold.length : 0;
  const boilerManifolds = Array.isArray(root.boilerManifold)
    ? root.boilerManifold.length
    : 0;
  const uniboxes = Array.isArray(root.uniboxes)
    ? root.uniboxes.length
    : Array.isArray(products.uniboxes)
      ? products.uniboxes.length
      : 0;
  return (
    boilers +
    radiators +
    waterHeaters +
    pipes +
    pumps +
    indirect +
    manifolds +
    boilerManifolds +
    uniboxes
  );
}

/**
 * Убираем служебные поля MongoDB перед валидацией каталога.
 * @param {Record<string, unknown>} doc
 * @returns {Record<string, unknown>}
 */
function mongoDocToPlain(doc) {
  if (!doc || typeof doc !== 'object') return {};
  const {
    _id: _mongoId,
    __v: _mongoV,
    catalogKey: _catalogKey,
    createdAt: _createdAt,
    updatedAt: _updatedAt,
    ...rest
  } = doc;
  void _mongoId;
  void _mongoV;
  void _catalogKey;
  void _createdAt;
  void _updatedAt;
  return rest;
}

/**
 * Труба из Mongo → строка каталога (без kind, catalogKey, pipeId).
 * @param {Record<string, unknown>} doc
 */
function pipeMongoDocToCatalogRow(doc) {
  const plain = mongoDocToPlain(doc);
  const { kind: _k, pipeId: _p, ...rest } = plain;
  void _k;
  void _p;
  /** @type {Record<string, unknown>} */
  const row = { ...rest };
  const catalogId = resolvePipeCatalogId(plain);
  if (catalogId) {
    row.id = catalogId;
  }
  return row;
}

/**
 * Насос из Mongo → строка каталога (без kind, catalogKey, pumpId).
 * @param {Record<string, unknown>} doc
 */
function pumpMongoDocToCatalogRow(doc) {
  const plain = mongoDocToPlain(doc);
  const { kind: _k, pumpId: _p, ...rest } = plain;
  void _k;
  void _p;
  /** @type {Record<string, unknown>} */
  const row = { ...rest };
  const catalogId = resolvePumpCatalogId(plain);
  if (catalogId) {
    row.id = catalogId;
  }
  return row;
}

/**
 * Унибокс из Mongo → строка каталога (без kind, catalogKey, uniboxId).
 * @param {Record<string, unknown>} doc
 */
function uniboxMongoDocToCatalogRow(doc) {
  const plain = mongoDocToPlain(doc);
  const { kind: _k, uniboxId: _u, ...rest } = plain;
  void _k;
  void _u;
  /** @type {Record<string, unknown>} */
  const row = { ...rest };
  const catalogId = resolveUniboxCatalogId(plain);
  if (catalogId) {
    row.id = catalogId;
  }
  return row;
}

/**
 * @param {Record<string, unknown>} doc
 */
function mongoDocToCatalogProductDoc(doc) {
  const plain = mongoDocToPlain(doc);
  const { kind: _k, ...rest } = plain;
  void _k;
  return rest;
}

/**
 * @returns {Promise<unknown>}
 */
async function loadCatalogJsonFromFile() {
  const p = resolveCatalogJsonFilePath();
  let raw;
  try {
    raw = await fs.readFile(p, 'utf8');
  } catch (err) {
    const code = err && typeof err === 'object' ? /** @type {NodeJS.ErrnoException} */ (err).code : null;
    if (code === 'ENOENT') {
      throw new Error(
        `Файл каталогу не знайдено: ${p}. Скопіюйте backend/test_data.json.example → test_data.json ` +
          'або задайте CATALOG_FILE_PATH / SEED_CATALOG_PATH.',
        { cause: err },
      );
    }
    throw err;
  }
  return JSON.parse(raw);
}

/**
 * @returns {Promise<unknown>}
 */
async function loadCatalogJsonFromMongo() {
  const connected = await ensureMongoReferenceConnection();
  if (!connected) {
    throw new Error(
      'CATALOG_SOURCE=mongo|auto: не задані MONGODB_URI або параметри підключення до MongoDB.',
    );
  }

  const docs = await Product.find({}).sort({ kind: 1, catalogKey: 1 }).lean();
  if (!docs.length) {
    throw new Error(
      'Каталог у MongoDB порожній (колекція products). Виконайте: cd backend && npm run seed',
    );
  }

  const boilers = docs
    .filter((d) => d.kind === 'boiler')
    .map((d) => mongoDocToCatalogProductDoc(/** @type {Record<string, unknown>} */ (d)));
  const radiators = docs
    .filter((d) => d.kind === 'radiator')
    .map((d) => mongoDocToCatalogProductDoc(/** @type {Record<string, unknown>} */ (d)));
  const waterHeaters = docs
    .filter((d) => d.kind === 'waterHeater')
    .map((d) => mongoDocToCatalogProductDoc(/** @type {Record<string, unknown>} */ (d)));
  const pipes = docs
    .filter((d) => d.kind === 'pipe')
    .map((d) => pipeMongoDocToCatalogRow(/** @type {Record<string, unknown>} */ (d)));
  const pumps = docs
    .filter((d) => d.kind === 'pump')
    .map((d) => pumpMongoDocToCatalogRow(/** @type {Record<string, unknown>} */ (d)));
  const indirectWaterHeaters = docs
    .filter((d) => d.kind === 'indirectWaterHeater')
    .map((d) => mongoDocToCatalogProductDoc(/** @type {Record<string, unknown>} */ (d)));
  const manifolds = docs
    .filter((d) => d.kind === 'manifold')
    .map((d) => mongoDocToCatalogProductDoc(/** @type {Record<string, unknown>} */ (d)));
  const boilerManifolds = docs
    .filter((d) => d.kind === 'boilerManifold')
    .map((d) => mongoDocToCatalogProductDoc(/** @type {Record<string, unknown>} */ (d)));
  const uniboxes = docs
    .filter((d) => d.kind === 'unibox')
    .map((d) => uniboxMongoDocToCatalogRow(/** @type {Record<string, unknown>} */ (d)));

  /** @type {Array<Record<string, unknown> & { isDoubleCircuit?: boolean }>} */
  const doubleCircuit = [];
  /** @type {Array<Record<string, unknown> & { isDoubleCircuit?: boolean }>} */
  const singleCircuit = [];
  for (const b of boilers) {
    if (b.isDoubleCircuit) doubleCircuit.push(b);
    else singleCircuit.push(b);
  }

  const envelope = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    currency: 'UAH',
    products: {
      boilers: { doubleCircuit, singleCircuit },
      radiators,
      waterHeaters,
      pipes,
    },
    pumps,
    indirectWaterHeaters,
    manifold: manifolds,
    boilerManifold: boilerManifolds,
    uniboxes,
  };

  if (countBoilersInProductsJson(envelope) < 1) {
    throw new Error(
      'У MongoDB немає котлів (kind=boiler). Виконайте: cd backend && npm run seed',
    );
  }

  if (countProductRowsInEnvelope(envelope) < 1) {
    throw new Error('Каталог у MongoDB не містить номенклатури products.');
  }

  return envelope;
}

/**
 * @param {'file' | 'mongo'} catalogSource
 * @param {unknown} json
 * @returns {{ catalog: import('./types.js').NormalizedCatalog, catalogSource: 'file' | 'mongo' }}
 */
function normalizeCatalogEnvelope(json, catalogSource) {
  const normalized = validateAndNormalizeCatalog(json);

  const radiators = [...normalized.radiators];
  const waterHeaters = [...normalized.waterHeaters];

  const nBoilersFinal =
    normalized.boilers.doubleCircuit.length + normalized.boilers.singleCircuit.length;
  logger.info('catalog.loaded', null, {
    catalogSource,
    boilers: nBoilersFinal,
    radiators: normalized.radiators.length,
    waterHeaters: normalized.waterHeaters.length,
    pipes: Array.isArray(normalized.pipes) ? normalized.pipes.length : 0,
    pumps: Array.isArray(normalized.pumps) ? normalized.pumps.length : 0,
    indirectWaterHeaters: Array.isArray(normalized.indirectWaterHeaters)
      ? normalized.indirectWaterHeaters.length
      : 0,
    manifolds: Array.isArray(normalized.manifolds) ? normalized.manifolds.length : 0,
    boilerManifolds: Array.isArray(normalized.boilerManifolds)
      ? normalized.boilerManifolds.length
      : 0,
    uniboxes: Array.isArray(normalized.uniboxes) ? normalized.uniboxes.length : 0,
  });

  return {
    catalog: {
      boilers: {
        doubleCircuit: normalized.boilers.doubleCircuit,
        singleCircuit: normalized.boilers.singleCircuit,
      },
      radiators,
      waterHeaters,
      pipes: Array.isArray(normalized.pipes) ? [...normalized.pipes] : [],
      pumps: Array.isArray(normalized.pumps) ? [...normalized.pumps] : [],
      indirectWaterHeaters: Array.isArray(normalized.indirectWaterHeaters)
        ? [...normalized.indirectWaterHeaters]
        : [],
      manifolds: Array.isArray(normalized.manifolds) ? [...normalized.manifolds] : [],
      boilerManifolds: Array.isArray(normalized.boilerManifolds)
        ? [...normalized.boilerManifolds]
        : [],
      uniboxes: Array.isArray(normalized.uniboxes) ? [...normalized.uniboxes] : [],
    },
    catalogSource,
  };
}

/**
 * @returns {Promise<{ catalog: import('./types.js').NormalizedCatalog, catalogSource: 'file' | 'mongo' }>}
 */
export async function loadCatalog() {
  const rawSource = String(process.env.CATALOG_SOURCE ?? 'auto').trim().toLowerCase();
  /** @type {'file' | 'mongo' | 'auto'} */
  let mode;
  if (rawSource === 'mongo') mode = 'mongo';
  else if (rawSource === 'file') mode = 'file';
  else if (rawSource === 'auto') mode = 'auto';
  else {
    logger.warn('catalog.source.unknown', null, { value: rawSource, fallback: 'auto' });
    mode = 'auto';
  }

  if (mode === 'mongo') {
    const json = await loadCatalogJsonFromMongo();
    return normalizeCatalogEnvelope(json, 'mongo');
  }

  if (mode === 'file') {
    const json = await loadCatalogJsonFromFile();
    return normalizeCatalogEnvelope(json, 'file');
  }

  try {
    const json = await loadCatalogJsonFromMongo();
    logger.info('catalog.auto', null, { decision: 'mongo' });
    return normalizeCatalogEnvelope(json, 'mongo');
  } catch (err) {
    logger.warn('catalog.auto', null, {
      decision: 'file',
      reason: 'mongo_unavailable_or_empty',
      message: err instanceof Error ? err.message : String(err),
    });
    const json = await loadCatalogJsonFromFile();
    return normalizeCatalogEnvelope(json, 'file');
  }
}

/**
 * Назначение: паспортная геометрия серий коллекторов (manifold).
 * Описание: формулы ширины от числа выходов и фиксированные H×D для известных серий каталога.
 */

/** @typedef {'giacomini_r553' | 'valtec_vtc589'} ManifoldSeriesId */

/** Допуск сравнения габаритов, мм. */
export const MANIFOLD_GEOMETRY_TOLERANCE_MM = 0.5;

/**
 * @typedef {Object} ManifoldSeriesGeometryPreset
 * @property {number} depth Глубина, мм.
 * @property {number} height Высота, мм.
 * @property {number} widthBase База формулы ширины, мм.
 * @property {number} widthStepPerOutlet Приращение ширины на один выход, мм.
 * @property {string} connectionMainInch Каноническое обозначение магистрали.
 * @property {string} connectionOutletsInch Каноническое обозначение отводов.
 * @property {number} outletsMin Минимум выходов для серии.
 * @property {number} outletsMax Максимум выходов для серии.
 */

/** @type {Record<ManifoldSeriesId, Readonly<ManifoldSeriesGeometryPreset>>} */
export const MANIFOLD_SERIES_GEOMETRY = Object.freeze({
  giacomini_r553: Object.freeze({
    depth: 116.6,
    height: 473,
    widthBase: 277,
    widthStepPerOutlet: 50,
    connectionMainInch: '1',
    connectionOutletsInch: '3/4',
    outletsMin: 3,
    outletsMax: 12,
  }),
  valtec_vtc589: Object.freeze({
    depth: 82,
    height: 313,
    widthBase: 45,
    widthStepPerOutlet: 50,
    connectionMainInch: '1',
    connectionOutletsInch: '3/4',
    outletsMin: 4,
    outletsMax: 12,
  }),
});

/**
 * Нормализует обозначение резьбы (убирает дюймовые кавычки и лишние пробелы).
 *
 * @param {unknown} raw
 * @returns {string}
 */
export function normalizeInchLabel(raw) {
  return String(raw ?? '')
    .replace(/[<>]/g, '')
    .replace(/"/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Ожидаемая ширина коллектора по паспорту серии, мм.
 *
 * @param {number} outletsCount
 * @param {ManifoldSeriesGeometryPreset} preset
 * @returns {number}
 */
export function expectedManifoldWidthMm(outletsCount, preset) {
  return preset.widthBase + outletsCount * preset.widthStepPerOutlet;
}

/**
 * Определяет серию коллектора по артикулу и бренду.
 *
 * @param {Record<string, unknown>} item
 * @returns {ManifoldSeriesId | null}
 */
export function resolveManifoldSeriesId(item) {
  const article = String(item.article ?? '').toUpperCase();
  const brand = String(item.brand ?? '')
    .trim()
    .toLowerCase();

  if (article.startsWith('R553') || brand === 'giacomini') {
    return 'giacomini_r553';
  }
  if (
    article.includes('VTC.589') ||
    article.includes('VTc.589') ||
    brand === 'valtec'
  ) {
    return 'valtec_vtc589';
  }
  return null;
}

/**
 * Проверяет геометрию и подключения для известной серии коллектора.
 * Для неизвестной серии — no-op (достаточно универсального контракта validateManifold).
 *
 * @param {Record<string, unknown>} item — нормализованная позиция manifold
 * @param {string} ctx — контекст ошибки, например manifold[2]
 */
export function assertKnownManifoldSeriesGeometry(item, ctx) {
  const seriesId = resolveManifoldSeriesId(item);
  if (!seriesId) return;

  const preset = MANIFOLD_SERIES_GEOMETRY[seriesId];
  const outletsCount = Number(item.outletsCount);

  if (outletsCount < preset.outletsMin || outletsCount > preset.outletsMax) {
    throw new Error(
      `Каталог: ${ctx} — для серии ${seriesId} outletsCount=${outletsCount} ` +
        `вне диапазона ${preset.outletsMin}…${preset.outletsMax}.`,
    );
  }

  const expectedW = expectedManifoldWidthMm(outletsCount, preset);

  if (
    normalizeInchLabel(item.connectionMainInch) !== preset.connectionMainInch
  ) {
    throw new Error(
      `Каталог: ${ctx} — connectionMainInch должен быть "${preset.connectionMainInch}" (серия ${seriesId}).`,
    );
  }
  if (
    normalizeInchLabel(item.connectionOutletsInch) !==
    preset.connectionOutletsInch
  ) {
    throw new Error(
      `Каталог: ${ctx} — connectionOutletsInch должен быть "${preset.connectionOutletsInch}" (серия ${seriesId}).`,
    );
  }

  const dimensions = item.dimensions;
  if (!dimensions || typeof dimensions !== 'object') {
    throw new Error(
      `Каталог: ${ctx} — dimensions обязателен для серии ${seriesId}.`,
    );
  }

  const depth = Number(
    /** @type {Record<string, unknown>} */ (dimensions).depth,
  );
  const height = Number(
    /** @type {Record<string, unknown>} */ (dimensions).height,
  );
  const width = Number(
    /** @type {Record<string, unknown>} */ (dimensions).width,
  );

  if (Math.abs(depth - preset.depth) > MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — depth=${depth}, ожидалось ${preset.depth} (серия ${seriesId}).`,
    );
  }
  if (Math.abs(height - preset.height) > MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — height=${height}, ожидалось ${preset.height} (серия ${seriesId}).`,
    );
  }
  if (Math.abs(width - expectedW) > MANIFOLD_GEOMETRY_TOLERANCE_MM) {
    throw new Error(
      `Каталог: ${ctx} — width=${width}, ожидалось ${expectedW} ` +
        `(серия ${seriesId}: ${preset.widthBase} + ${outletsCount}×${preset.widthStepPerOutlet}).`,
    );
  }
}

/**
 * Назначение: предсортированные пулы каталога для matching.
 * Описание: котлы (по max powerKw) и электронакопительные водонагреватели (по min volumeLiters)
 * с кэшем WeakMap на снимке NormalizedCatalog. Радиаторы, трубы и БКН здесь не индексируются:
 * радиаторы — sortRadiatorsForMatching() в matching/internal/pickRadiatorsCore.js;
 * остальное — прямой обход каталога в соответствующих pick* модулях.
 */
import {
  compareBoilersByMaxPowerAsc,
  compareWaterHeatersByMinVolumeAsc,
} from './comparators.js';

/** @type {WeakMap<object, { boilersSortedByMaxPower: import('./types.js').BoilerCatalogItemNormalized[], waterHeatersSortedByMinVolume: import('./types.js').WaterHeaterCatalogItemNormalized[] }>} */
const sortPoolsCache = new WeakMap();

/**
 * @param {import('./types.js').NormalizedCatalog} catalog
 * @returns {{
 *   boilersSortedByMaxPower: import('./types.js').BoilerCatalogItemNormalized[],
 *   waterHeatersSortedByMinVolume: import('./types.js').WaterHeaterCatalogItemNormalized[],
 * }}
 */
export function buildMatchingSortPools(catalog) {
  if (catalog && typeof catalog === 'object') {
    const cached = sortPoolsCache.get(catalog);
    if (cached) return cached;
  }

  const allBoilers = [
    ...(catalog?.boilers?.doubleCircuit ?? []),
    ...(catalog?.boilers?.singleCircuit ?? []),
  ];

  const boilersSortedByMaxPower = [...allBoilers].sort(compareBoilersByMaxPowerAsc);
  const waterHeatersSortedByMinVolume = [...(catalog?.waterHeaters ?? [])].sort(
    compareWaterHeatersByMinVolumeAsc,
  );

  const pools = {
    boilersSortedByMaxPower,
    waterHeatersSortedByMinVolume,
  };

  if (catalog && typeof catalog === 'object') {
    sortPoolsCache.set(catalog, pools);
  }

  return pools;
}

/**
 * Назначение: хелперы номенклатуры труб в каталоге.
 * Описание: единая формула подписи model и round-trip id для validateCatalog и seed.
 */

/**
 * Идентификатор строки каталога при round-trip Mongo → validateCatalog.
 * В products корневое поле id Mongoose не сохраняет надёжно; дубль — pipeId при seed.
 *
 * @param {Record<string, unknown>} rec — поля документа pipe после mongoDocToPlain (или строка каталога)
 * @returns {string}
 */
export function resolvePipeCatalogId(rec) {
  const pipeId = rec.pipeId != null ? String(rec.pipeId).trim() : '';
  if (pipeId) return pipeId;
  const id = rec.id != null ? String(rec.id).trim() : '';
  return id;
}

/**
 * Подпись модели трубы для каталога/Mongo, если в JSON нет явного model.
 *
 * @param {Record<string, unknown>} item
 * @param {number} idx — индекс в массиве pipes (fallback)
 * @returns {string}
 */
export function derivePipeModelLabel(item, idx) {
  const id = item.id != null ? String(item.id).trim() : '';
  const brand = item.brand != null ? String(item.brand).trim() : '';
  const material = item.material != null ? String(item.material).trim() : '';
  const dn = Number.isFinite(Number(item.diameter)) ? Number(item.diameter) : null;
  const wn = Number.isFinite(Number(item.wallThickness)) ? Number(item.wallThickness) : null;

  return (
    [
      id,
      brand || null,
      material || null,
      dn != null ? `Ø${dn}` : '',
      wn != null ? `×${wn}` : '',
    ]
      .filter(Boolean)
      .join(' ')
      .trim() || `pipe-${idx}`
  );
}

/**
 * Назначение: валидация и нормализация каталога.
 * Описание: проверка числовых полей, mountingType (boilerCatalogHelpers), типов оборудования
 * и санитизация строк перед использованием в формулах подбора; защита от NaN и физически
 * некорректных значений.
 */
import { isPlainObject } from '../utils/isPlainObject.js';
import { sanitizeTrimAngleBrackets } from '../utils/sanitizeString.js';
import { applyBoilerMountingType } from './boilerCatalogHelpers.js';
import { derivePipeModelLabel } from './pipeCatalogHelpers.js';
import { derivePumpCatalogIdFromModel } from './pumpCatalogHelpers.js';
import {
  assertPumpModeCurveGeometry,
  normalizePumpModeQMaxToCurve,
  PUMP_CURVE_MIN_HEAD_AT_QMAX_M,
} from '../utils/pumpCurveMath.js';
import {
  assertKnownManifoldSeriesGeometry,
  normalizeInchLabel,
} from './manifoldSeriesGeometry.js';
import { assertKnownBoilerManifoldSeriesGeometry } from './boilerManifoldSeriesGeometry.js';

/**
 * Верхні межі outputWatts (Вт) при валідації каталогу радіаторів.
 * Панель — сумарна потужність приладу; секція — потужність однієї секції.
 */
const RADIATOR_OUTPUT_WATTS_LIMITS = Object.freeze({
  panelDeltaT50Max: 10_000,
  panelDeltaT70Max: 15_000,
  sectionalDeltaT50Max: 2_000,
  sectionalDeltaT70Max: 3_000,
});

/**
 * @param {unknown} x
 * @param {{ field?: string, min?: number, max?: number }} [opts]
 * @returns {number}
 */
function toFiniteNumber(x, { field, min = -Infinity, max = Infinity } = {}) {
  const n = Number(x);
  if (!Number.isFinite(n)) {
    throw new Error(`Каталог: поле ${field} должно быть числом.`);
  }
  if (n < min || n > max) {
    throw new Error(`Каталог: поле ${field} вне диапазона (${min}..${max}).`);
  }
  return n;
}

/**
 * Приводит «расширенные» записи из test_data.json к полям, ожидаемым подбором (MVP).
 * @param {Record<string, unknown>} item
 */
function normalizeBoilerFromExtendedFormats(item) {
  if (!isPlainObject(item)) return;

  if (!isPlainObject(item.powerKw)) {
    const specs = /** @type {Record<string, unknown>} */ (item.specs);
    const sp = specs && isPlainObject(specs.power) ? specs.power : null;
    const rp = isPlainObject(item.power) ? item.power : null;
    const min = (sp?.min_kw ?? rp?.min_kw) ?? null;
    const max =
      (sp?.max_heating_kw ?? rp?.max_heating_kw ?? sp?.max_dhw_kw ?? rp?.max_dhw_kw) ?? null;
    if (
      min != null &&
      max != null &&
      Number.isFinite(Number(min)) &&
      Number.isFinite(Number(max))
    ) {
      item.powerKw = { min: Number(min), max: Number(max) };
    }
  }

  if (!sanitizeTrimAngleBrackets(item.fuel)) item.fuel = 'Газ';

  if (item.efficiencyPercent != null && typeof item.efficiencyPercent === 'object') {
    const o = /** @type {Record<string, unknown>} */ (item.efficiencyPercent);
    const v = o.nominal_80_60 ?? o.condensing_50_30 ?? o.seasonal;
    if (v != null && Number.isFinite(Number(v))) item.efficiencyPercent = Number(v);
    else delete item.efficiencyPercent;
  }
  if (
    (item.efficiencyPercent == null || item.efficiencyPercent === '') &&
    isPlainObject(item.specs) &&
    isPlainObject(/** @type {Record<string, unknown>} */ (item.specs).efficiency)
  ) {
    const eff = /** @type {Record<string, unknown>} */ (
      /** @type {Record<string, unknown>} */ (item.specs).efficiency
    );
    const v = eff.nominal_80_60 ?? eff.condensing_50_30;
    if (v != null && Number.isFinite(Number(v))) item.efficiencyPercent = Number(v);
  }

  // Количество контуров из тегов (если не задано числом) — до синхронизации с isDoubleCircuit.
  if (item.circuitsCount == null && Array.isArray(item.tags)) {
    const tagSet = new Set(item.tags.map((t) => sanitizeTrimAngleBrackets(t).toLowerCase()));
    if (tagSet.has('double-circuit')) item.circuitsCount = 2;
    else if (tagSet.has('single-circuit')) item.circuitsCount = 1;
  }

  if (item.isDoubleCircuit !== true && item.isDoubleCircuit !== false) {
    const cc = item.circuitsCount;
    if (cc === 2) item.isDoubleCircuit = true;
    else if (cc === 1) item.isDoubleCircuit = false;
    else {
      const m = sanitizeTrimAngleBrackets(item.model).toLowerCase();
      if (/\bduo\b|duo-tec|двух|double-circuit/.test(m)) item.isDoubleCircuit = true;
      else item.isDoubleCircuit = false;
    }
  }

  if (item.gasConsumptionM3PerHour == null) {
    let g = item.gas_consumption_max_m3_h;
    if (g == null && isPlainObject(item.specs)) {
      const specs = /** @type {Record<string, unknown>} */ (item.specs);
      const gc = specs.gas_consumption;
      if (isPlainObject(gc)) {
        g = /** @type {Record<string, unknown>} */ (gc).max_m3_h;
      }
    }
    if (g != null && Number.isFinite(Number(g))) item.gasConsumptionM3PerHour = Number(g);
  }
}

/**
 * Панельный радиатор — теплоотдача целиком по изделию (specs.thermal_output_full).
 * @param {Record<string, unknown>} item
 * @returns {boolean}
 */
function radiatorLooksLikePanelRecord(item) {
  const specs = /** @type {Record<string, unknown>} */ (item.specs);
  return Boolean(specs && isPlainObject(specs.thermal_output_full));
}

/**
 * Оценка базиса цены для радиатора (если в JSON не задан priceBasis).
 * @param {Record<string, unknown>} item
 */
function inferRadiatorPriceBasis(item) {
  if (radiatorLooksLikePanelRecord(item)) return 'panel';
  const t = sanitizeTrimAngleBrackets(item.type).toLowerCase();
  if (t.includes('steel panel') || /\bpanel\b/.test(t)) return 'panel';
  const c = sanitizeTrimAngleBrackets(item.construction).toLowerCase();
  if (c.includes('monolith')) return 'panel';
  return 'section';
}

/**
 * @param {Record<string, unknown>} item
 */
function normalizeRadiatorFromExtendedFormats(item) {
  if (!isPlainObject(item)) return;

  if (!isPlainObject(item.outputWatts)) {
    const specs = /** @type {Record<string, unknown>} */ (item.specs);
    const ts =
      specs && isPlainObject(specs.thermal_output_section)
        ? specs.thermal_output_section
        : null;
    const tf =
      specs && isPlainObject(specs.thermal_output_full) ? specs.thermal_output_full : null;
    const dt50 = ts?.dt_50_w ?? tf?.dt_50_w;
    const dt70 = ts?.dt_70_w ?? tf?.dt_70_w;
    if (dt50 != null && dt70 != null) {
      item.outputWatts = { deltaT50: Number(dt50), deltaT70: Number(dt70) };
    }
  }

  if (item.volumeLiters == null && isPlainObject(item.specs)) {
    const specs = /** @type {Record<string, unknown>} */ (item.specs);
    const v = specs.volume_l_section ?? specs.volume_l_total;
    if (v != null && Number.isFinite(Number(v))) item.volumeLiters = Number(v);
  }

  if (!sanitizeTrimAngleBrackets(item.material)) item.material = 'разное';

  if (item.dimensions == null && isPlainObject(item.specs) && isPlainObject(item.specs.dimensions)) {
    const specs = /** @type {Record<string, unknown>} */ (item.specs);
    const d = /** @type {Record<string, unknown>} */ (specs.dimensions);
    const isPanel = isPlainObject(specs.thermal_output_full);
    const height = d.height_mm ?? d.height;
    const depth = d.depth_mm ?? d.depth;
    const interaxle = d.center_distance_mm ?? d.interaxle;
    const lengthMm = d.length_mm ?? null;
    const width = isPanel
      ? (lengthMm ?? d.width_section_mm ?? d.width)
      : (d.width_section_mm ?? lengthMm ?? d.width ?? depth);
    if (width != null) {
      item.dimensions = {
        height: height != null ? Number(height) : undefined,
        width: Number(width),
        depth: depth != null ? Number(depth) : undefined,
        interaxle: interaxle != null ? Number(interaxle) : undefined,
      };
    }
  }
}

/**
 * @param {Record<string, unknown>} item
 * @param {string} ctx
 * @param {1 | 2} expectedCircuitsCount Ожидаемое число контуров для секции каталога (doubleCircuit | singleCircuit).
 */
function validateBoiler(item, ctx, expectedCircuitsCount) {
  if (!isPlainObject(item)) throw new Error(`Каталог: котёл должен быть объектом (${ctx}).`);

  item.model = sanitizeTrimAngleBrackets(item.model);
  if (!item.model) throw new Error(`Каталог: model обязателен (${ctx}).`);

  normalizeBoilerFromExtendedFormats(item);

  const boolCirc = item.isDoubleCircuit;
  if (boolCirc != null && typeof boolCirc !== 'boolean') {
    throw new Error(`Каталог: isDoubleCircuit должен быть boolean (${ctx}).`);
  }

  let ccRaw =
    item.circuitsCount != null && Number.isFinite(Number(item.circuitsCount))
      ? Number(item.circuitsCount)
      : null;

  if (boolCirc === true && ccRaw != null && ccRaw !== 2) {
    throw new Error(`Каталог: при isDoubleCircuit=true ожидается circuitsCount=2 (${ctx}).`);
  }
  if (boolCirc === false && ccRaw != null && ccRaw !== 1) {
    throw new Error(`Каталог: при isDoubleCircuit=false ожидается circuitsCount=1 (${ctx}).`);
  }

  let cc = ccRaw;
  if (cc == null && boolCirc === true) cc = 2;
  if (cc == null && boolCirc === false) cc = 1;
  // Если в записи не указано число контуров и флаг двухконтурности не задан — используем секцию каталога.
  if (cc == null) cc = expectedCircuitsCount;

  item.circuitsCount = toFiniteNumber(cc, {
    field: `circuitsCount (${ctx})`,
    min: 1,
    max: 3,
  });

  if (item.circuitsCount !== expectedCircuitsCount) {
    throw new Error(
      `Каталог: circuitsCount=${item.circuitsCount} не соответствует секции каталога (ожидается ${expectedCircuitsCount}) (${ctx}).`,
    );
  }

  item.isDoubleCircuit = item.circuitsCount === 2;

  if (!isPlainObject(item.powerKw)) throw new Error(`Каталог: powerKw обязателен (${ctx}).`);
  // Ноль или отрицательные значения мощности приведут к абсурдному подбору.
  // Поэтому задаём нижнюю границу > 0 (минимум 0.1 кВт).
  const powerKw = item.powerKw;
  const powerKwMax = toFiniteNumber(powerKw.max, { field: `powerKw.max (${ctx})`, min: 0.1 });
  const powerKwMin = toFiniteNumber(powerKw.min, { field: `powerKw.min (${ctx})`, min: 0.1 });
  if (powerKwMin > powerKwMax) {
    throw new Error(`Каталог: powerKw.min > powerKw.max (${ctx}).`);
  }
  powerKw.max = powerKwMax;
  powerKw.min = powerKwMin;

  const fuel = sanitizeTrimAngleBrackets(item.fuel);
  item.fuel = fuel;
  if (fuel && !['Газ', 'Электричество', 'Твердое топливо', 'Твердотопливный'].includes(fuel)) {
    // Мягкая проверка enum: можно расширять список по мере появления.
    // Не бросаем ошибку, если fuel пустой/неизвестный — но фиксируем очевидный мусор в model/power.
  }

  // После нормализации не оставляем объект КПД (Mongoose / валидация ожидают число).
  if (item.efficiencyPercent != null && typeof item.efficiencyPercent === 'object') {
    delete item.efficiencyPercent;
  }

  if (item.efficiencyPercent != null) {
    item.efficiencyPercent = toFiniteNumber(item.efficiencyPercent, {
      field: `efficiencyPercent (${ctx})`,
      min: 1,
      max: 150,
    });
  }

  if (item.gasConsumptionM3PerHour != null) {
    item.gasConsumptionM3PerHour = toFiniteNumber(item.gasConsumptionM3PerHour, {
      field: `gasConsumptionM3PerHour (${ctx})`,
      min: 0,
      max: 20,
    });
  }

  item.price = toFiniteNumber(item.price, {
    field: `price (${ctx})`,
    min: 1,
    max: 1_000_000_000,
  });

  applyBoilerMountingType(item, ctx);

  if (item.connectionDiameters != null) {
    if (!Array.isArray(item.connectionDiameters)) {
      throw new Error(`Каталог: connectionDiameters должен быть массивом строк (${ctx}).`);
    }
    item.connectionDiameters = item.connectionDiameters
      .map((x) => sanitizeTrimAngleBrackets(x))
      .filter(Boolean);
  }

  if (item.combustionType != null) {
    const c = sanitizeTrimAngleBrackets(item.combustionType).toLowerCase();
    if (c === 'turbo' || c === 'atmospheric') item.combustionType = c;
    else delete item.combustionType;
  }

  item.type = sanitizeTrimAngleBrackets(item.type).toLowerCase();
  if (!item.type) {
    throw new Error(`Каталог: type обязателен (непустая строка) (${ctx}).`);
  }

  if (item.tags != null) {
    if (!Array.isArray(item.tags)) {
      throw new Error(`Каталог: tags должен быть массивом строк (${ctx}).`);
    }
    item.tags = item.tags.map((x) => sanitizeTrimAngleBrackets(x)).filter(Boolean);
  }

  if (item.priceSegment != null) {
    item.priceSegment = sanitizeTrimAngleBrackets(item.priceSegment).toLowerCase();
  }

  if (item.circulationPump != null) {
    if (!isPlainObject(item.circulationPump)) {
      throw new Error(`Каталог: circulationPump должен быть объектом (${ctx}).`);
    }
    const circulationPump = /** @type {Record<string, unknown>} */ (item.circulationPump);
    if (
      !Array.isArray(circulationPump.operatingModes)
      || circulationPump.operatingModes.length < 1
    ) {
      throw new Error(
        `Каталог: circulationPump.operatingModes — непустой массив (${ctx}).`,
      );
    }
    circulationPump.operatingModes.forEach((mode, mi) => {
      validatePumpOperatingMode(mode, `${ctx}.circulationPump.operatingModes[${mi}]`);
    });
  }
}

/**
 * @param {unknown} item
 * @param {number} idx
 */
function validateRadiator(item, idx) {
  if (!isPlainObject(item)) throw new Error(`Каталог: радиатор должен быть объектом (radiators[${idx}]).`);

  item.model = sanitizeTrimAngleBrackets(item.model);
  if (!item.model) throw new Error(`Каталог: model обязателен (radiators[${idx}]).`);

  normalizeRadiatorFromExtendedFormats(item);

  const looksPanel = radiatorLooksLikePanelRecord(item);
  const outputDt50Max = looksPanel
    ? RADIATOR_OUTPUT_WATTS_LIMITS.panelDeltaT50Max
    : RADIATOR_OUTPUT_WATTS_LIMITS.sectionalDeltaT50Max;
  const outputDt70Max = looksPanel
    ? RADIATOR_OUTPUT_WATTS_LIMITS.panelDeltaT70Max
    : RADIATOR_OUTPUT_WATTS_LIMITS.sectionalDeltaT70Max;

  if (!isPlainObject(item.outputWatts)) throw new Error(`Каталог: outputWatts обязателен (radiators[${idx}]).`);
  item.outputWatts.deltaT50 = toFiniteNumber(item.outputWatts.deltaT50, {
    field: `outputWatts.deltaT50 (radiators[${idx}])`,
    min: 1,
    max: outputDt50Max,
  });
  item.outputWatts.deltaT70 = toFiniteNumber(item.outputWatts.deltaT70, {
    field: `outputWatts.deltaT70 (radiators[${idx}])`,
    min: 1,
    max: outputDt70Max,
  });

  item.material = sanitizeTrimAngleBrackets(item.material);
  if (item.volumeLiters != null) {
    item.volumeLiters = toFiniteNumber(item.volumeLiters, {
      field: `volumeLiters (radiators[${idx}])`,
      min: 0,
      max: 50,
    });
  }

  const widthMaxMm = looksPanel || item.priceBasis === 'panel' ? 3000 : 500;

  // Габариты (мм): для секции — ширина секции; для панели — длина прибора в width/sectionWidthMm.
  if (item.dimensions != null) {
    if (!isPlainObject(item.dimensions)) {
      throw new Error(`Каталог: dimensions должен быть объектом (radiators[${idx}]).`);
    }
    if (item.dimensions.width == null) {
      throw new Error(`Каталог: dimensions.width обязателен (radiators[${idx}]).`);
    }
    item.dimensions.width = toFiniteNumber(item.dimensions.width, {
      field: `dimensions.width (radiators[${idx}])`,
      min: 20,
      max: widthMaxMm,
    });

    if (item.dimensions.height != null) {
      item.dimensions.height = toFiniteNumber(item.dimensions.height, {
        field: `dimensions.height (radiators[${idx}])`,
        min: 100,
        max: 3000,
      });
    }
    if (item.dimensions.depth != null) {
      item.dimensions.depth = toFiniteNumber(item.dimensions.depth, {
        field: `dimensions.depth (radiators[${idx}])`,
        min: 10,
        max: 500,
      });
    }
    if (item.dimensions.interaxle != null) {
      item.dimensions.interaxle = toFiniteNumber(item.dimensions.interaxle, {
        field: `dimensions.interaxle (radiators[${idx}])`,
        min: 100,
        max: 2500,
      });
    }

    // Удобный алиас для расчётов
    item.sectionWidthMm = item.dimensions.width;
  }

  item.price = toFiniteNumber(item.price, {
    field: `price (radiators[${idx}])`,
    min: 1,
    max: 1_000_000_000,
  });

  let priceBasis = sanitizeTrimAngleBrackets(item.priceBasis).toLowerCase();
  if (priceBasis !== 'section' && priceBasis !== 'panel') {
    priceBasis = inferRadiatorPriceBasis(item);
  }
  if (priceBasis !== 'section' && priceBasis !== 'panel') {
    throw new Error(`Каталог: priceBasis должен быть "section" или "panel" (radiators[${idx}]).`);
  }
  item.priceBasis = priceBasis;

  if (item.priceBasis === 'panel' && !looksPanel) {
    throw new Error(
      `Каталог: priceBasis=panel допустим только для позиций с specs.thermal_output_full (radiators[${idx}]).`,
    );
  }
  if (item.priceBasis === 'section' && looksPanel) {
    throw new Error(
      `Каталог: для панельного типа (thermal_output_full) укажите priceBasis=panel (radiators[${idx}]).`,
    );
  }
}

/**
 * @param {unknown} item
 * @param {number} idx
 */
function validateWaterHeater(item, idx) {
  if (!isPlainObject(item)) {
    throw new Error(`Каталог: водонагреватель должен быть объектом (waterHeaters[${idx}]).`);
  }

  item.model = sanitizeTrimAngleBrackets(item.model);
  if (!item.model) throw new Error(`Каталог: model обязателен (waterHeaters[${idx}]).`);

  const typeRaw = item.type != null ? sanitizeTrimAngleBrackets(item.type).trim().toLowerCase() : '';
  if (!typeRaw) {
    item.type = 'electric_storage';
  } else if (typeRaw !== 'electric_storage') {
    throw new Error(
      `Каталог: waterHeaters[${idx}].type ожидается "electric_storage" (получено "${typeRaw}").`,
    );
  } else {
    item.type = typeRaw;
  }

  if (!Array.isArray(item.variants) || item.variants.length < 1) {
    throw new Error(`Каталог: variants должен быть непустым массивом (waterHeaters[${idx}]).`);
  }

  const seenVolumes = new Set();
  /** @type {{ volumeLiters: number; price: number; powerKw?: number; heatingTimeMinutes?: number }[]} */
  const normalizedVariants = [];

  item.variants.forEach((raw, vi) => {
    if (!isPlainObject(raw)) {
      throw new Error(`Каталог: variants[${vi}] должен быть объектом (waterHeaters[${idx}]).`);
    }

    const volumeLiters = toFiniteNumber(raw.volumeLiters, {
      field: `variants[${vi}].volumeLiters (waterHeaters[${idx}])`,
      min: 1,
      max: 1000,
    });
    if (seenVolumes.has(volumeLiters)) {
      throw new Error(
        `Каталог: дубликат volumeLiters=${volumeLiters} в variants (waterHeaters[${idx}]).`,
      );
    }
    seenVolumes.add(volumeLiters);

    const price = toFiniteNumber(raw.price, {
      field: `variants[${vi}].price (waterHeaters[${idx}])`,
      min: 1,
      max: 1_000_000_000,
    });

    /** @type {{ volumeLiters: number; price: number; powerKw?: number; heatingTimeMinutes?: number }} */
    const nv = { volumeLiters, price };
    if (raw.powerKw != null) {
      nv.powerKw = toFiniteNumber(raw.powerKw, {
        field: `variants[${vi}].powerKw (waterHeaters[${idx}])`,
        min: 0.1,
        max: 30,
      });
    }
    if (raw.heatingTimeMinutes != null) {
      nv.heatingTimeMinutes = toFiniteNumber(raw.heatingTimeMinutes, {
        field: `variants[${vi}].heatingTimeMinutes (waterHeaters[${idx}])`,
        min: 1,
        max: 10080,
      });
    }
    normalizedVariants.push(nv);
  });

  normalizedVariants.sort((a, b) => a.volumeLiters - b.volumeLiters);
  item.variants = normalizedVariants;

  delete item.powerKw;

  if (item.heatingElementType != null) {
    item.heatingElementType = sanitizeTrimAngleBrackets(item.heatingElementType);
  }

  if (item.powerDetails != null) {
    item.powerDetails = sanitizeTrimAngleBrackets(item.powerDetails);
  }

  if (item.features != null) {
    if (!Array.isArray(item.features)) {
      throw new Error(`Каталог: features должен быть массивом строк (waterHeaters[${idx}]).`);
    }
    item.features = item.features.map((x) => sanitizeTrimAngleBrackets(x)).filter(Boolean);
  }
}

/**
 * @param {Record<string, unknown>} item
 * @param {number} idx
 * @param {Set<string>} seenIds
 */
function validatePipe(item, idx, seenIds) {
  const ctx = `pipes[${idx}]`;
  if (!isPlainObject(item)) {
    throw new Error(`Каталог: pipe[${idx}] должен быть объектом.`);
  }

  item.id = sanitizeTrimAngleBrackets(item.id);
  if (!item.id) {
    throw new Error(`Каталог: id обязателен (${ctx}).`);
  }
  const pipeId = /** @type {string} */ (item.id);
  if (seenIds.has(pipeId)) {
    throw new Error(`Каталог: дубликат id="${pipeId}" (${ctx}).`);
  }
  seenIds.add(pipeId);

  item.brand = sanitizeTrimAngleBrackets(item.brand);
  if (!item.brand) {
    throw new Error(`Каталог: brand обязателен (${ctx}).`);
  }

  item.material = sanitizeTrimAngleBrackets(item.material);
  if (!item.material) {
    throw new Error(`Каталог: material обязателен (${ctx}).`);
  }

  if (item.category != null) {
    item.category = sanitizeTrimAngleBrackets(item.category);
  }

  item.diameter = toFiniteNumber(item.diameter, {
    field: `${ctx}.diameter`,
    min: 1,
    max: 1000,
  });

  item.wallThickness = toFiniteNumber(item.wallThickness, {
    field: `${ctx}.wallThickness`,
    min: 0.1,
    max: 100,
  });

  item.price = toFiniteNumber(item.price, {
    field: `${ctx}.price`,
    min: 1,
    max: 1_000_000_000,
  });

  let model = sanitizeTrimAngleBrackets(item.model);
  if (!model) {
    model = derivePipeModelLabel(item, idx);
  }
  item.model = model;
  if (!item.model) {
    throw new Error(`Каталог: model обязателен (${ctx}).`);
  }
}

/** Допустимые типы насосов в каталоге. */
const PUMP_TYPES_ALLOWED = Object.freeze([
  'electronic',
  'three_speed',
  'circulation_hot_water',
]);

/** Допустимые сегменты насосов. */
const PUMP_SEGMENTS_ALLOWED = Object.freeze(['premium', 'medium', 'budget']);

/**
 * Насосы: корень JSON или `products.pumps`.
 *
 * @param {Record<string, unknown>} json
 * @returns {unknown[]}
 */
function collectPumps(json) {
  if (Array.isArray(json.pumps)) return json.pumps;
  const p = json.products;
  if (isPlainObject(p) && Array.isArray(p.pumps)) return p.pumps;
  return [];
}

/**
 * Импорт legacy-формата насосов (commercial.priceEstimate, _id.$oid, kind) в контракт PumpCatalogItem.
 * Канонический JSON: id, price на верхнем уровне; валюта — только currency каталога, не у позиции.
 *
 * @param {Record<string, unknown>} item
 * @param {number} idx
 */
function normalizePumpFromExtendedFormats(item, idx) {
  if (item.price == null && isPlainObject(item.commercial)) {
    const commercial = /** @type {Record<string, unknown>} */ (item.commercial);
    if (commercial.priceEstimate != null) {
      item.price = commercial.priceEstimate;
    }
  }

  if (!sanitizeTrimAngleBrackets(item.id)) {
    const oidWrap = item._id;
    if (isPlainObject(oidWrap) && oidWrap.$oid != null) {
      item.id = `pump-${String(oidWrap.$oid).trim()}`;
    } else {
      const model = sanitizeTrimAngleBrackets(item.model);
      item.id = derivePumpCatalogIdFromModel(model || '', idx);
    }
  }

  delete item._id;
  delete item.kind;
  delete item.commercial;
}

/**
 * @param {unknown} raw
 * @param {string} ctx
 */
function validatePumpOperatingMode(raw, ctx) {
  if (!isPlainObject(raw)) {
    throw new Error(`Каталог: ${ctx} должен быть объектом.`);
  }

  /** @type {Record<string, unknown>} */
  const mode = raw;
  mode.modeName = sanitizeTrimAngleBrackets(mode.modeName);
  if (!mode.modeName) {
    throw new Error(`Каталог: modeName обязателен (${ctx}).`);
  }

  mode.speedIndex = toFiniteNumber(mode.speedIndex, {
    field: `${ctx}.speedIndex`,
    min: 1,
    max: 9,
  });

  mode.powerWatts = toFiniteNumber(mode.powerWatts, {
    field: `${ctx}.powerWatts`,
    min: 0,
    max: 10_000,
  });

  if (!isPlainObject(mode.coefficients)) {
    throw new Error(`Каталог: coefficients обязателен (${ctx}).`);
  }
  const coef = /** @type {Record<string, unknown>} */ (mode.coefficients);
  coef.a = toFiniteNumber(coef.a, { field: `${ctx}.coefficients.a`, min: -100, max: 100 });
  coef.b = toFiniteNumber(coef.b, { field: `${ctx}.coefficients.b`, min: -100, max: 100 });
  coef.c = toFiniteNumber(coef.c, { field: `${ctx}.coefficients.c`, min: -100, max: 100 });

  mode.qMinM3h = toFiniteNumber(mode.qMinM3h, {
    field: `${ctx}.qMinM3h`,
    min: 0,
    max: 100,
  });
  mode.qMaxM3h = toFiniteNumber(mode.qMaxM3h, {
    field: `${ctx}.qMaxM3h`,
    min: 0,
    max: 100,
  });
  const qMinM3h = /** @type {number} */ (mode.qMinM3h);
  const qMaxM3h = /** @type {number} */ (mode.qMaxM3h);
  if (qMaxM3h < qMinM3h) {
    throw new Error(`Каталог: qMaxM3h < qMinM3h (${ctx}).`);
  }

  /** @type {{ qMinM3h: number; qMaxM3h: number; coefficients: object }} */
  const modeCurve = {
    qMinM3h,
    qMaxM3h,
    coefficients: coef,
  };
  normalizePumpModeQMaxToCurve(modeCurve, ctx, PUMP_CURVE_MIN_HEAD_AT_QMAX_M);
  mode.qMaxM3h = modeCurve.qMaxM3h;

  assertPumpModeCurveGeometry(
    modeCurve,
    ctx,
    PUMP_CURVE_MIN_HEAD_AT_QMAX_M,
  );
}

/**
 * @param {unknown} item
 * @param {number} idx
 * @param {Set<string>} seenIds
 */
function validatePump(item, idx, seenIds) {
  const ctx = `pumps[${idx}]`;
  if (!isPlainObject(item)) {
    throw new Error(`Каталог: pump[${idx}] должен быть объектом.`);
  }

  normalizePumpFromExtendedFormats(item, idx);

  item.id = sanitizeTrimAngleBrackets(item.id);
  if (!item.id) {
    throw new Error(`Каталог: id обязателен (${ctx}).`);
  }
  const pumpId = /** @type {string} */ (item.id);
  if (seenIds.has(pumpId)) {
    throw new Error(`Каталог: дубликат id="${pumpId}" (${ctx}).`);
  }
  seenIds.add(pumpId);

  item.brand = sanitizeTrimAngleBrackets(item.brand);
  if (!item.brand) {
    throw new Error(`Каталог: brand обязателен (${ctx}).`);
  }

  item.model = sanitizeTrimAngleBrackets(item.model);
  if (!item.model) {
    throw new Error(`Каталог: model обязателен (${ctx}).`);
  }

  if (item.series != null) {
    item.series = sanitizeTrimAngleBrackets(item.series);
  }
  if (item.country != null) {
    item.country = sanitizeTrimAngleBrackets(item.country);
  }

  const typeRaw = sanitizeTrimAngleBrackets(item.type).trim().toLowerCase();
  if (!PUMP_TYPES_ALLOWED.includes(typeRaw)) {
    throw new Error(
      `Каталог: pumps[${idx}].type недопустимое значение "${String(item.type)}"; ` +
        `разрешено: ${PUMP_TYPES_ALLOWED.join(' | ')}.`,
    );
  }
  item.type = typeRaw;

  const segmentRaw = sanitizeTrimAngleBrackets(item.segment).trim().toLowerCase();
  if (!PUMP_SEGMENTS_ALLOWED.includes(segmentRaw)) {
    throw new Error(
      `Каталог: pumps[${idx}].segment недопустимое значение "${String(item.segment)}"; ` +
        `разрешено: ${PUMP_SEGMENTS_ALLOWED.join(' | ')}.`,
    );
  }
  item.segment = segmentRaw;

  item.price = toFiniteNumber(item.price, {
    field: `${ctx}.price`,
    min: 1,
    max: 1_000_000_000,
  });

  if (!isPlainObject(item.connections)) {
    throw new Error(`Каталог: connections обязателен (${ctx}).`);
  }
  const conn = /** @type {Record<string, unknown>} */ (item.connections);
  conn.mountingLengthMm = toFiniteNumber(conn.mountingLengthMm, {
    field: `${ctx}.connections.mountingLengthMm`,
    min: 1,
    max: 1000,
  });
  conn.threadInch = sanitizeTrimAngleBrackets(conn.threadInch);
  if (!conn.threadInch) {
    throw new Error(`Каталог: connections.threadInch обязателен (${ctx}).`);
  }
  conn.nominalDiameterMm = toFiniteNumber(conn.nominalDiameterMm, {
    field: `${ctx}.connections.nominalDiameterMm`,
    min: 1,
    max: 500,
  });

  if (!Array.isArray(item.operatingModes) || item.operatingModes.length < 1) {
    throw new Error(`Каталог: operatingModes — непустой массив (${ctx}).`);
  }
  item.operatingModes.forEach((mode, mi) => {
    validatePumpOperatingMode(mode, `${ctx}.operatingModes[${mi}]`);
  });
}

/**
 * Бойлеры косвенного нагрева (БКН): корень JSON или `products.indirectWaterHeaters`.
 *
 * @param {Record<string, unknown>} json
 * @returns {unknown[]}
 */
function collectIndirectWaterHeaters(json) {
  if (Array.isArray(json.indirectWaterHeaters)) return json.indirectWaterHeaters;
  const p = json.products;
  if (isPlainObject(p) && Array.isArray(p.indirectWaterHeaters)) return p.indirectWaterHeaters;
  return [];
}

/** Допустимые значения mounting/placement каталога БКН после нормализации. */
const INDIRECT_WATER_HEATER_TYPES_ALLOWED = Object.freeze([
  'indirect_wall',
  'indirect_floor',
  'storage_indirect',
]);

/**
 * @param {string} normalized
 */
function isAllowedIndirectWaterHeaterType(normalized) {
  return INDIRECT_WATER_HEATER_TYPES_ALLOWED.includes(normalized);
}

/**
 * Нормализует поле **type** БКН — три независимых допустимых значения классификации в каталоге (не взаимозаменяемы).
 * @param {unknown} raw
 * @param {number} idx
 */
function normalizeIndirectWaterHeaterType(raw, idx) {
  const s = sanitizeTrimAngleBrackets(raw).trim().toLowerCase();
  // «indirect wall», «indirect-wall», лишние пробелы
  const collapsed = s.replace(/[\s-]+/g, '_');
  if (!collapsed) {
    throw new Error(
      `Каталог: indirectWaterHeaters[${idx}].type обязателен; допускаются только: indirect_wall | indirect_floor | storage_indirect (три разных класса номенклатуры).`,
    );
  }
  if (!isAllowedIndirectWaterHeaterType(collapsed)) {
    throw new Error(
      `Каталог: indirectWaterHeaters[${idx}].type недопустимое значение "${s}" (нормализовано: "${collapsed}"). Разрешено только: indirect_wall (настенный БКН), indirect_floor (напольный БКН), storage_indirect (отдельный номенклатурный тип БКН в каталоге, не смешивать с wall/floor).`,
    );
  }
  return collapsed;
}

/**
 * @param {unknown} item
 * @param {number} idx
 */
function validateIndirectWaterHeater(item, idx) {
  if (!isPlainObject(item)) {
    throw new Error(`Каталог: indirectWaterHeaters[${idx}] должен быть объектом.`);
  }

  item.model = sanitizeTrimAngleBrackets(item.model);
  if (!item.model) {
    throw new Error(`Каталог: model обязателен (indirectWaterHeaters[${idx}]).`);
  }

  if (item.brand != null) item.brand = sanitizeTrimAngleBrackets(item.brand);
  if (item.article != null) item.article = sanitizeTrimAngleBrackets(item.article);

  item.type = normalizeIndirectWaterHeaterType(item.type, idx);

  // Цена в валюте каталога (UAH): берём из прайсов официальных представителей / авторизованных дистрибьюторов в UA (ниже строк в тестовых данных).
  item.price = toFiniteNumber(item.price, {
    field: `indirectWaterHeaters[${idx}].price`,
    min: 1,
    max: 1_000_000_000,
  });

  const specs = item.specs;
  if (!isPlainObject(specs)) {
    throw new Error(`Каталог: indirectWaterHeaters[${idx}].specs должен быть объектом.`);
  }

  specs.volumeLiters = toFiniteNumber(specs.volumeLiters, {
    field: `indirectWaterHeaters[${idx}].specs.volumeLiters`,
    min: 1,
    max: 5000,
  });

  for (const key of ['powerKw', 'surfaceAreaM2', 'maxTempC', 'heatingTimeMinutes', 'standingLossKwh24h']) {
    if (specs[key] != null) {
      specs[key] = toFiniteNumber(specs[key], {
        field: `indirectWaterHeaters[${idx}].specs.${String(key)}`,
        min: 0,
        max: 1_000_000,
      });
    }
  }

  // Минимальная рекомендуемая мощность теплоносителя/котла для штатного нагрева (кВт); опционально.
  if (specs.minSourcePowerKw != null) {
    specs.minSourcePowerKw = toFiniteNumber(specs.minSourcePowerKw, {
      field: `indirectWaterHeaters[${idx}].specs.minSourcePowerKw`,
      min: 0.1,
      max: 500,
    });
  }
}

