/** Допустимые конструкции унибокса. */
const UNIBOX_TYPES_ALLOWED = Object.freeze([
  'rtl_air',
  'rtl',
  'rtl_afc',
  'balancing_valve',
  'air_only',
]);

/** Резьба подключения унибокса. */
const UNIBOX_THREADS_ALLOWED = Object.freeze(['G1/2', 'G3/4']);

/** Тип фитинга унибокса. */
const UNIBOX_FITS_ALLOWED = Object.freeze(['eurocone', 'internal_thread']);

/**
 * Унибоксы: корень JSON или `products.uniboxes`.
 *
 * @param {Record<string, unknown>} json
 * @returns {unknown[]}
 */
function collectUniboxes(json) {
  if (Array.isArray(json.uniboxes)) return json.uniboxes;
  const p = json.products;
  if (isPlainObject(p) && Array.isArray(p.uniboxes)) return p.uniboxes;
  return [];
}

/**
 * @param {Record<string, unknown>} item
 * @param {string} ctx
 * @param {string} minKey
 * @param {string} maxKey
 */
function assertOptionalMinMaxPair(item, ctx, minKey, maxKey) {
  const hasMin = item[minKey] != null;
  const hasMax = item[maxKey] != null;
  if (hasMin && !hasMax) {
    throw new Error(`Каталог: ${ctx}.${maxKey} обязателен, если задан ${minKey}.`);
  }
  if (hasMax && !hasMin) {
    throw new Error(`Каталог: ${ctx}.${minKey} обязателен, если задан ${maxKey}.`);
  }
  if (!hasMin || !hasMax) return;
  const min = /** @type {number} */ (item[minKey]);
  const max = /** @type {number} */ (item[maxKey]);
  if (min > max) {
    throw new Error(`Каталог: ${ctx}.${minKey} (${min}) не может быть больше ${maxKey} (${max}).`);
  }
}

/**
 * @param {unknown} item
 * @param {number} idx
 * @param {Set<string>} seenIds
 */
function validateUnibox(item, idx, seenIds) {
  const ctx = `uniboxes[${idx}]`;
  if (!isPlainObject(item)) {
    throw new Error(`Каталог: uniboxes[${idx}] должен быть объектом.`);
  }

  delete item.kind;
  delete item.catalogKey;
  delete item.currency;
  delete item.sku;
  delete item.article;
  delete item.maxWorkingPressureBar;
  delete item.kvs;
  delete item.kvValueM3h;
  delete item.maxPipeLengthM;
  delete item.maxTempC;
  delete item.mountDepthMm;
  delete item.purpose;
  delete item.headsCount;
  delete item.controlType;
  delete item.connectionDiameter;
  delete item.connectionType;

  // Запрет явных null в match-полях (omit вместо null).
  for (const key of Object.keys(item)) {
    if (item[key] === null) {
      throw new Error(`Каталог: ${ctx}.${key} не может быть null (уберите ключ).`);
    }
  }

  // Round-trip Mongo: id може прийти лише як uniboxId (Mongoose не зберігає id надійно).
  if (!item.id && item.uniboxId != null) {
    item.id = item.uniboxId;
  }
  delete item.uniboxId;

  item.id = sanitizeTrimAngleBrackets(item.id);
  if (!item.id) {
    throw new Error(`Каталог: id обязателен (${ctx}).`);
  }
  const uniboxId = /** @type {string} */ (item.id);
  if (seenIds.has(uniboxId)) {
    throw new Error(`Каталог: дублирующий id унибокса "${uniboxId}" (${ctx}).`);
  }
  seenIds.add(uniboxId);

  item.brand = sanitizeTrimAngleBrackets(item.brand);
  if (!item.brand) {
    throw new Error(`Каталог: brand обязателен (${ctx}).`);
  }

  item.model = sanitizeTrimAngleBrackets(item.model);
  if (!item.model) {
    throw new Error(`Каталог: model обязателен (${ctx}).`);
  }

  const typeRaw = sanitizeTrimAngleBrackets(item.type).trim().toLowerCase();
  if (!UNIBOX_TYPES_ALLOWED.includes(typeRaw)) {
    throw new Error(
      `Каталог: ${ctx}.type недопустимо "${String(item.type)}"; ` +
        `разрешено: ${UNIBOX_TYPES_ALLOWED.join(' | ')}.`,
    );
  }
  item.type = typeRaw;

  item.loopsCount = toFiniteInteger(item.loopsCount, {
    field: `${ctx}.loopsCount`,
    min: 1,
    max: 8,
  });

  item.maxAreaSqM = toFiniteNumber(item.maxAreaSqM, {
    field: `${ctx}.maxAreaSqM`,
    min: 0.1,
    max: 500,
  });
  item.maxLoopLengthM = toFiniteNumber(item.maxLoopLengthM, {
    field: `${ctx}.maxLoopLengthM`,
    min: 0.1,
    max: 500,
  });
  item.maxTemperatureC = toFiniteNumber(item.maxTemperatureC, {
    field: `${ctx}.maxTemperatureC`,
    min: 30,
    max: 120,
  });
  item.maxPressureBar = toFiniteNumber(item.maxPressureBar, {
    field: `${ctx}.maxPressureBar`,
    min: 0.1,
    max: 25,
  });
  item.kvM3h = toFiniteNumber(item.kvM3h, {
    field: `${ctx}.kvM3h`,
    min: 0.01,
    max: 50,
  });

  item.price = toFiniteNumber(item.price, {
    field: `${ctx}.price`,
    min: 1,
    max: 1_000_000_000,
  });

  item.material = sanitizeTrimAngleBrackets(item.material);
  if (!item.material) {
    throw new Error(`Каталог: material обязателен (${ctx}).`);
  }

  if (!isPlainObject(item.connection)) {
    throw new Error(`Каталог: объект connection обязателен (${ctx}).`);
  }
  /** @type {Record<string, unknown>} */
  const conn = item.connection;
  const thread = sanitizeTrimAngleBrackets(conn.thread).trim().replace(/\s+/g, '');
  const threadNorm = thread === 'G½' || thread === 'G1/2"' ? 'G1/2' : thread === 'G¾' || thread === 'G3/4"' ? 'G3/4' : thread;
  if (!UNIBOX_THREADS_ALLOWED.includes(threadNorm)) {
    throw new Error(
      `Каталог: ${ctx}.connection.thread недопустимо "${String(conn.thread)}"; ` +
        `разрешено: ${UNIBOX_THREADS_ALLOWED.join(' | ')}.`,
    );
  }
  conn.thread = threadNorm;

  const fit = sanitizeTrimAngleBrackets(conn.fit).trim().toLowerCase();
  if (!UNIBOX_FITS_ALLOWED.includes(fit)) {
    throw new Error(
      `Каталог: ${ctx}.connection.fit недопустимо "${String(conn.fit)}"; ` +
        `разрешено: ${UNIBOX_FITS_ALLOWED.join(' | ')}.`,
    );
  }
  conn.fit = fit;

  if (item.description != null) {
    item.description = sanitizeTrimAngleBrackets(item.description);
    if (!item.description) delete item.description;
  }

  /** @type {string[]} */
  const optionalNumberKeys = [
    'minAirTempC',
    'maxAirTempC',
    'minCoolantTempC',
    'maxCoolantTempC',
    'minFlowLph',
    'maxFlowLph',
    'maxSupplyTempC',
  ];
  for (const key of optionalNumberKeys) {
    if (item[key] === undefined) continue;
    const min = key.startsWith('min') || key === 'maxSupplyTempC' ? -20 : -20;
    const max = key.includes('Flow') ? 5000 : 120;
    item[key] = toFiniteNumber(item[key], {
      field: `${ctx}.${key}`,
      min: key.includes('Flow') || key === 'maxSupplyTempC' ? (key.includes('Flow') ? 0.01 : 20) : min,
      max,
    });
  }

  assertOptionalMinMaxPair(item, ctx, 'minAirTempC', 'maxAirTempC');
  assertOptionalMinMaxPair(item, ctx, 'minCoolantTempC', 'maxCoolantTempC');
  assertOptionalMinMaxPair(item, ctx, 'minFlowLph', 'maxFlowLph');

  if (item.type === 'rtl_air') {
    for (const key of ['minAirTempC', 'maxAirTempC', 'minCoolantTempC', 'maxCoolantTempC']) {
      if (item[key] == null) {
        throw new Error(`Каталог: ${ctx}.${key} обязателен при type=rtl_air.`);
      }
    }
  } else if (item.type === 'rtl') {
    for (const key of ['minCoolantTempC', 'maxCoolantTempC']) {
      if (item[key] == null) {
        throw new Error(`Каталог: ${ctx}.${key} обязателен при type=rtl.`);
      }
    }
  } else if (item.type === 'rtl_afc') {
    for (const key of [
      'minCoolantTempC',
      'maxCoolantTempC',
      'minFlowLph',
      'maxFlowLph',
    ]) {
      if (item[key] == null) {
        throw new Error(`Каталог: ${ctx}.${key} обязателен при type=rtl_afc.`);
      }
    }
  } else if (item.type === 'air_only') {
    for (const key of ['minAirTempC', 'maxAirTempC', 'maxSupplyTempC']) {
      if (item[key] == null) {
        throw new Error(`Каталог: ${ctx}.${key} обязателен при type=air_only.`);
      }
    }
  } else if (item.type === 'balancing_valve') {
    for (const key of [
      'minAirTempC',
      'maxAirTempC',
      'minCoolantTempC',
      'maxCoolantTempC',
      'minFlowLph',
      'maxFlowLph',
      'maxSupplyTempC',
    ]) {
      if (item[key] != null) {
        throw new Error(
          `Каталог: ${ctx}.${key} недопустим при type=balancing_valve (в паспорте нет этих диапазонов).`,
        );
      }
    }
  }

  if (item.dimensions !== undefined) {
    if (!isPlainObject(item.dimensions)) {
      throw new Error(`Каталог: ${ctx}.dimensions должен быть объектом.`);
    }
    /** @type {Record<string, unknown>} */
    const dim = item.dimensions;
    dim.height = toFiniteNumber(dim.height, {
      field: `${ctx}.dimensions.height`,
      min: 0.1,
      max: 2000,
    });
    dim.width = toFiniteNumber(dim.width, {
      field: `${ctx}.dimensions.width`,
      min: 0.1,
      max: 2000,
    });
    dim.depth = toFiniteNumber(dim.depth, {
      field: `${ctx}.dimensions.depth`,
      min: 0.1,
      max: 500,
    });
  }
}

/**
 * Валидирует и (минимально) нормализует каталог.
 * Входной json не мутируется (клонирование как в validateAndNormalizeInput для calc).
 * @param {unknown} json
 * @returns {import('./types.js').NormalizedCatalog}
 */
export function validateAndNormalizeCatalog(json) {
  if (!isPlainObject(json)) throw new Error('Каталог: корневой JSON должен быть объектом.');
  /** @type {Record<string, unknown>} */
  const root = structuredClone(json);
  if (!isPlainObject(root.products)) throw new Error('Каталог: отсутствует объект products.');

  const boilers = isPlainObject(root.products.boilers) ? root.products.boilers : {};
  const doubleCircuit = Array.isArray(boilers.doubleCircuit) ? boilers.doubleCircuit : [];
  const singleCircuit = Array.isArray(boilers.singleCircuit) ? boilers.singleCircuit : [];

  doubleCircuit.forEach((b, i) => validateBoiler(b, `boilers.doubleCircuit[${i}]`, 2));
  singleCircuit.forEach((b, i) => validateBoiler(b, `boilers.singleCircuit[${i}]`, 1));

  const radiators = Array.isArray(root.products.radiators) ? root.products.radiators : [];
  radiators.forEach((r, i) => validateRadiator(r, i));

  const waterHeaters = Array.isArray(root.products.waterHeaters) ? root.products.waterHeaters : [];
  waterHeaters.forEach((h, i) => validateWaterHeater(h, i));

  const pipes = Array.isArray(root.products.pipes) ? root.products.pipes : [];
  const seenPipeIds = new Set();
  pipes.forEach((p, i) => validatePipe(p, i, seenPipeIds));

  const pumpsRaw = collectPumps(root);
  const pumps = pumpsRaw.filter(isPlainObject);
  const seenPumpIds = new Set();
  pumps.forEach((p, i) => validatePump(p, i, seenPumpIds));

  const indirectWaterHeatersRaw = collectIndirectWaterHeaters(root);
  const indirectWaterHeaters = indirectWaterHeatersRaw.filter(isPlainObject);
  indirectWaterHeaters.forEach((item, i) => validateIndirectWaterHeater(item, i));

  const manifoldsRaw = collectManifolds(root);
  const manifolds = manifoldsRaw.filter(isPlainObject);
  manifolds.forEach((item, i) => validateManifold(item, i));

  const boilerManifoldsRaw = collectBoilerManifolds(root);
  const boilerManifolds = boilerManifoldsRaw.filter(isPlainObject);
  boilerManifolds.forEach((item, i) => validateBoilerManifold(item, i));

  const uniboxesRaw = collectUniboxes(root);
  const uniboxes = uniboxesRaw.filter(isPlainObject);
  const seenUniboxIds = new Set();
  uniboxes.forEach((item, i) => validateUnibox(item, i, seenUniboxIds));

  return {
    boilers: {
      doubleCircuit: /** @type {import('./types.js').BoilerCatalogItemNormalized[]} */ (
        doubleCircuit
      ),
      singleCircuit: /** @type {import('./types.js').BoilerCatalogItemNormalized[]} */ (
        singleCircuit
      ),
    },
    radiators: /** @type {import('./types.js').RadiatorCatalogItemNormalized[]} */ (radiators),
    waterHeaters: /** @type {import('./types.js').WaterHeaterCatalogItemNormalized[]} */ (
      waterHeaters
    ),
    pipes: /** @type {import('./types.js').PipeCatalogItemNormalized[]} */ (pipes),
    pumps: /** @type {import('./types.js').PumpCatalogItemNormalized[]} */ (pumps),
    indirectWaterHeaters:
      /** @type {import('./types.js').IndirectWaterHeaterCatalogItemNormalized[]} */ (
        indirectWaterHeaters
      ),
    manifolds: /** @type {import('./types.js').ManifoldCatalogItemNormalized[]} */ (manifolds),
    boilerManifolds: /** @type {import('./types.js').BoilerManifoldCatalogItemNormalized[]} */ (
      boilerManifolds
    ),
    uniboxes: /** @type {import('./types.js').UniboxCatalogItemNormalized[]} */ (uniboxes),
  };
}

/**
 * Назначение: геокодинг адресы через Nominatim.
 * Описание: Преобразует текстовый адрес в координаты lat/lon через OpenStreetMap Nominatim для последующего климатического расчёта. Требует User-Agent (GEOCODE_USER_AGENT). Экспортирует geocodeAddress(); вызывается из climate/index.js.
 */

import { logger } from '../utils/logger.js';
import { throwAppError } from '../utils/createAppError.js';

const NOMINATIM_URL = 'https://nominatim.openstreetmap.org/search';
const DEFAULT_GEOCODE_TIMEOUT_MS = 8_000;

/**
 * Таймаут HTTP до Nominatim: GEOCODE_TIMEOUT_MS або дефолт 8000 мс.
 *
 * @returns {number}
 */
function resolveGeocodeTimeoutMs() {
  const n = Number(process.env.GEOCODE_TIMEOUT_MS);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : DEFAULT_GEOCODE_TIMEOUT_MS;
}

/**
 * @param {unknown} err
 * @returns {boolean}
 */
function isAbortError(err) {
  if (!err || typeof err !== 'object') return false;
  const named = /** @type {{ name?: string, code?: string }} */ (err);
  if (named.name === 'AbortError' || named.code === 'ABORT_ERR') return true;
  return err instanceof Error && /aborted|AbortError/i.test(err.message);
}

/**
 * Геокодинг адреси через Nominatim (OpenStreetMap).
 *
 * Повертає координати (lat/lon) для подальших кліматичних розрахунків.
 * Важливо: Nominatim просить вказувати User-Agent (див. GEOCODE_USER_AGENT).
 *
 * @param {string} address
 * @returns {Promise<import('../types/shared-types.js').LocationInput & { displayName?: string | null } | null>}
 */
export async function geocodeAddress(address) {
  if (!address || typeof address !== 'string') return null;

  logger.info('climate.geocode.start', null, { hasAddress: true });

  const url = new URL(NOMINATIM_URL);
  url.searchParams.set('q', address);
  url.searchParams.set('format', 'json');
  url.searchParams.set('limit', '1');

  const timeoutMs = resolveGeocodeTimeoutMs();
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);

  /** @type {Response} */
  let resp;
  try {
    resp = await fetch(url, {
      headers: {
        // Nominatim просит указывать User-Agent.
        'user-agent': process.env.GEOCODE_USER_AGENT ?? 'heating-selection-service/1.0',
        accept: 'application/json',
      },
      signal: ctrl.signal,
    });
  } catch (err) {
    if (isAbortError(err)) {
      logger.warn('climate.geocode.fail', null, {
        reason: 'timeout',
        timeoutMs,
      });
      throwAppError(
        'Таймаут геокодування адреси (Nominatim)',
        'GEOCODE_TIMEOUT',
        502,
      );
    }
    logger.warn('climate.geocode.fail', null, {
      reason: 'network',
      message: err instanceof Error ? err.message : String(err),
    });
    throwAppError('Не вдалося виконати геокодування адреси', 'GEOCODE_FAILED', 502);
  } finally {
    clearTimeout(t);
  }

  if (!resp.ok) {
    logger.warn('climate.geocode.fail', null, { status: resp.status });
    throwAppError('Не вдалося виконати геокодування адреси', 'GEOCODE_FAILED', 502);
  }

  /** @type {unknown} */
  const data = await resp.json();
  const first = Array.isArray(data) ? data[0] : null;
  if (!first) return null;

  const row = /** @type {{ lat?: unknown, lon?: unknown, display_name?: unknown }} */ (first);

  logger.info('climate.geocode.ok', null, { lat: Number(row.lat), lon: Number(row.lon) });

  return {
    lat: Number(row.lat),
    lon: Number(row.lon),
    displayName: typeof row.display_name === 'string' ? row.display_name : null,
  };
}

/**
 * Назначение: фасад климатического модуля.
 * Описание: Единая точка получения расчётной наружной температуры: при необходимости геокодирует адрес через geocode.js, затем запрашивает Meteostat через snipClimate.js. Экспортирует getDesignOutsideTempC(); используется в report/buildReport.js при отсутствии temps.outsideC.
 */

import { geocodeAddress } from './geocode.js';
import { getDesignOutsideTempFromMeteostat } from './snipClimate.js';

/**
 * @param {import('../types/shared-types.js').LocationInput} location
 * @returns {Promise<import('../types/shared-types.js').ClimateSnapshot | null>}
 */
export async function getDesignOutsideTempC(location) {
  if (!location || typeof location !== 'object') return null;

  let lat = location.lat;
  let lon = location.lon;
  let geocoded = null;

  if ((!lat || !lon) && location.address) {
    geocoded = await geocodeAddress(location.address);
    lat = geocoded?.lat;
    lon = geocoded?.lon;
  }

  if (!Number.isFinite(Number(lat)) || !Number.isFinite(Number(lon))) return null;

  const designOutsideTempC = await getDesignOutsideTempFromMeteostat({
    lat: Number(lat),
    lon: Number(lon),
  });

  return {
    source: 'meteostat',
    designOutsideTempC,
    lat: Number(lat),
    lon: Number(lon),
    displayName: geocoded?.displayName ?? null,
  };
}

/**
 * Назначение: климатический расчёт по данным Meteostat.
 * Описание: Загружает bulk-данные станций и суточные температуры с data.meteostat.net, находит ближайшую станцию и минимальное 5-дневное скользящее среднее как расчётную наружную температуру. Экспортирует getDesignOutsideTempFromMeteostat(); вызывается из climate/index.js.
 */

import { gunzipSync } from 'node:zlib';
import { logger } from '../utils/logger.js';
import { throwAppError } from '../utils/createAppError.js';

const STATIONS_LITE_GZ_URL = 'https://bulk.meteostat.net/v2/stations/lite.json.gz';

/**
 * @param {number} year
 * @param {string} stationId
 * @returns {string}
 */
const DAILY_CSV_GZ_URL = (year, stationId) => `https://data.meteostat.net/daily/${year}/${stationId}.csv.gz`;

/** @type {Promise<Array<{ id: string, lat: number, lon: number }>> | null} */
let stationsLiteCachePromise = null;

/**
 * Модуль кліматичного розрахунку на основі **безкоштовних bulk-даних Meteostat** (без RapidAPI).
 *
 * Результат: одна температура (°C), яку ми трактуємо як “температуру найхолоднішої пʼятиденки”.
 * Для MVP це наближення:
 * - беремо щоденні середні температури (tavg)
 * - шукаємо мінімальне ковзне середнє за 5 днів
 */

/**
 * @param {unknown} value
 * @param {number} fallback
 * @returns {number}
 */
function toInt(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.trunc(n);
}

/**
 * @param {number[]} values
 * @param {number} windowSize
 * @returns {number | null}
 */
function minRollingAverage(values, windowSize) {
  if (!Array.isArray(values) || values.length < windowSize) return null;
  let sum = 0;
  for (let i = 0; i < windowSize; i += 1) {
    const v = values[i];
    if (v === undefined) return null;
    sum += v;
  }
  let min = sum / windowSize;
  for (let i = windowSize; i < values.length; i += 1) {
    const current = values[i];
    const outgoing = values[i - windowSize];
    if (current === undefined || outgoing === undefined) return null;
    sum += current - outgoing;
    const avg = sum / windowSize;
    if (avg < min) min = avg;
  }
  return min;
}

/**
 * @param {number} lat1
 * @param {number} lon1
 * @param {number} lat2
 * @param {number} lon2
 * @returns {number}
 */
function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  /** @param {number} deg */
  const toRad = (deg) => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2
    + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(a)));
}

/**
 * Таймаут HTTP до bulk Meteostat: METEOSTAT_BULK_TIMEOUT_MS або fallback.
 * Якщо env задано — одне значення для fetch і HEAD; інакше — історичні дефолти.
 *
 * @param {number} fallbackMs
 * @returns {number}
 */
function resolveMeteostatBulkTimeoutMs(fallbackMs) {
  const n = Number(process.env.METEOSTAT_BULK_TIMEOUT_MS);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallbackMs;
}

/**
 * @param {string} url
 * @returns {Promise<Buffer>}
 */
async function fetchBuffer(url) {
  const ctrl = new AbortController();
  const timeoutMs = resolveMeteostatBulkTimeoutMs(15_000);
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  let resp;
  try {
    resp = await fetch(url, { headers: { accept: '*/*' }, signal: ctrl.signal });
  } finally {
    clearTimeout(t);
  }
  if (!resp.ok) {
    throwAppError(
      `Не удалось загрузить Meteostat bulk: ${url} (HTTP ${resp.status})`,
      'METEOSTAT_BULK_HTTP_ERROR',
      502,
    );
  }
  const ab = await resp.arrayBuffer();
  return Buffer.from(ab);
}

/**
 * @param {string} url
 * @returns {Promise<boolean>}
 */
async function headOk(url) {
  const ctrl = new AbortController();
  const timeoutMs = resolveMeteostatBulkTimeoutMs(8_000);
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const resp = await fetch(url, { method: 'HEAD', headers: { accept: '*/*' }, signal: ctrl.signal });
    return resp.ok;
  } catch {
    return false;
  } finally {
    clearTimeout(t);
  }
}

/**
 * @returns {Promise<Array<{ id: string, lat: number, lon: number }>>}
 */
async function loadStationsLite() {
  if (!stationsLiteCachePromise) {
    stationsLiteCachePromise = (async () => {
      logger.info('climate.meteostat.stationsLite.start', null);
      const gz = await fetchBuffer(STATIONS_LITE_GZ_URL);
      let jsonText;
      try {
        jsonText = gunzipSync(gz).toString('utf8');
      } catch {
        throwAppError(
          'Не вдалося розпакувати stations/lite.json.gz',
          'METEOSTAT_STATIONS_LITE_GUNZIP_FAILED',
          502,
        );
      }

      /** @type {unknown} */
      const parsed = JSON.parse(jsonText);
      if (!Array.isArray(parsed)) {
        throwAppError(
          'Некоректний формат stations/lite.json.gz (очікувався масив)',
          'METEOSTAT_STATIONS_LITE_BAD_FORMAT',
          502,
        );
      }

      const lite = parsed
        .map((s) => {
          const rec = s && typeof s === 'object' ? /** @type {Record<string, unknown>} */ (s) : null;
          const location = rec?.location && typeof rec.location === 'object'
            ? /** @type {Record<string, unknown>} */ (rec.location)
            : null;
          const id = rec?.id ?? rec?.i ?? null;
          const lat = location?.latitude ?? rec?.lat ?? rec?.latitude ?? null;
          const lon = location?.longitude ?? rec?.lon ?? rec?.longitude ?? null;
          if (!id) return null;
          if (!Number.isFinite(Number(lat)) || !Number.isFinite(Number(lon))) return null;
          return { id: String(id), lat: Number(lat), lon: Number(lon) };
        })
        .filter((item) => item !== null);

      logger.info('climate.meteostat.stationsLite.ok', null, { count: lite.length });
      return /** @type {Array<{ id: string, lat: number, lon: number }>} */ (lite);
    })();
  }
  return stationsLiteCachePromise;
}

/**
 * @param {number} lat
 * @param {number} lon
 * @returns {Promise<{ stationId: string | null, distanceKm: number, candidates: Array<{ id: string, km: number }> }>}
 */
async function pickNearestStationId(lat, lon) {
  const stations = await loadStationsLite();
  let best = null;
  let bestKm = Infinity;
  /** @type {Array<{ id: string, km: number }>} */
  const bestCandidates = [];
  for (const s of stations) {
    const km = haversineKm(lat, lon, s.lat, s.lon);
    if (km < bestKm) {
      bestKm = km;
      best = s;
    }
    // Держим топ-20 кандидатів поблизу (для випадків, коли найближча станція не має daily).
    if (bestCandidates.length < 20) {
      bestCandidates.push({ id: s.id, km });
      bestCandidates.sort((a, b) => a.km - b.km);
    } else {
      const last = bestCandidates[bestCandidates.length - 1];
      if (last && km < last.km) {
        bestCandidates[bestCandidates.length - 1] = { id: s.id, km };
        bestCandidates.sort((a, b) => a.km - b.km);
      }
    }
  }
  return {
    stationId: best?.id ?? null,
    distanceKm: bestKm,
    candidates: bestCandidates,
  };
}

/**
 * @param {string} csvText
 * @returns {number[]}
 */
function parseDailyCsvTavg(csvText) {
  const lines = csvText.split('\n').map((l) => l.trim()).filter(Boolean);
  const headerLine = lines[0];
  if (!headerLine) return [];
  const header = headerLine.split(',').map((x) => x.trim());
  // В bulk daily по документации колонка средней температуры может называться `temp`
  // (а в некоторых форматах встречается `tavg`). Поддерживаем оба варианта.
  const idxTemp = header.indexOf('tavg') >= 0 ? header.indexOf('tavg') : header.indexOf('temp');
  if (idxTemp < 0) return [];
  /** @type {number[]} */
  const out = [];
  for (let i = 1; i < lines.length; i += 1) {
    const line = lines[i];
    if (!line) continue;
    const cols = line.split(',');
    const v = cols[idxTemp];
    const n = Number(v);
    if (Number.isFinite(n)) out.push(n);
  }
  return out;
}

/**
 * Получить расчётную наружную температуру «самой холодной пятидневки» через Meteostat.
 *
 * Подход MVP:
 * - Берём дневные средние температуры (tavg) за последние N лет
 * - Считаем минимальное скользящее среднее за 5 дней
 *
 * Это приближение к «температуре самой холодной пятидневки» по нормативам.
 */
/**
 * @param {{ lat: number, lon: number }} args
 * @returns {Promise<number>}
 */
export async function getDesignOutsideTempFromMeteostat({ lat, lon }) {
  const years = Math.max(1, Math.min(50, toInt(process.env.METEOSTAT_YEARS, 10)));

  const end = new Date();
  const start = new Date(end);
  start.setFullYear(end.getFullYear() - years);

  logger.info('climate.meteostat.stations.start', null, { lat: Number(lat), lon: Number(lon), years });

  const { candidates } = await pickNearestStationId(Number(lat), Number(lon));
  if (!candidates.length) {
    logger.warn('climate.meteostat.stations.none', null, { lat: Number(lat), lon: Number(lon) });
    throwAppError(
      'Не знайдено станцію Meteostat поблизу вказаних координат',
      'METEOSTAT_NO_STATION',
      502,
    );
  }

  const startYear = start.getFullYear();
  const endYear = end.getFullYear();
  /** @type {number[]} */
  const windowYears = [];
  for (let y = startYear; y <= endYear; y += 1) windowYears.push(y);

  // Пробуем несколько ближайших станций: часто у самой близкой нет daily-данных.
  for (const c of candidates) {
    const stationId = c.id;
    /** @type {number[]} */
    const allTavg = [];

    // Быстрый “пробник”: если нет daily хотя бы за один из последних 3 лет — станцию пропускаем.
    // Это резко снижает объём скачиваний и делает путь более стабильным.
    const probeYears = [endYear, endYear - 1, endYear - 2].filter((y) => y >= startYear);
    let hasAny = false;
    for (const y of probeYears) {
      // HEAD дешевле, чем скачивать .csv.gz
      // Если год недоступен (404) — идём дальше
      // Если хотя бы один доступен — пробуем станцию полноценно.
      if (await headOk(DAILY_CSV_GZ_URL(y, stationId))) {
        hasAny = true;
        break;
      }
    }
    if (!hasAny) {
      logger.info('climate.meteostat.daily.skipNoRecentData', null, { stationId });
      continue;
    }

    logger.info('climate.meteostat.daily.start', null, {
      stationId,
      distanceKm: Number(c.km.toFixed(1)),
      years: windowYears.length,
    });

    for (const y of windowYears) {
      const url = DAILY_CSV_GZ_URL(y, stationId);
      let gz;
      try {
        gz = await fetchBuffer(url);
      } catch {
        // Если год отсутствует — просто пропускаем; это нормально для многих станций.
        continue;
      }
      let csvText;
      try {
        csvText = gunzipSync(gz).toString('utf8');
      } catch {
        logger.warn('climate.meteostat.daily.gunzipFail', null, { stationId, year: y });
        continue;
      }
      const tavg = parseDailyCsvTavg(csvText);
      for (const t of tavg) allTavg.push(t);
    }

    const min5day = minRollingAverage(allTavg, 5);
    if (min5day == null) {
      logger.warn('climate.meteostat.daily.insufficient', null, { stationId, points: allTavg.length });
      continue;
    }

    const result = Math.round(min5day * 10) / 10;
    logger.info('climate.meteostat.ok', null, { stationId, resultC: result });
    return result;
  }

  throwAppError(
    'Недостатньо даних Meteostat для розрахунку п\'ятиденки',
    'METEOSTAT_INSUFFICIENT_DATA',
    502,
  );
}

/**
 * Назначение: базовые конструкции водяного тёплого пола (без финишного покрытия).
 * Описание: usage=underfloor_heating_base — плита, утеплитель, стяжка с трубами, выравнивание.
 * Финиш — отдельно в flooringFinishMaterials.js. Не смешивать с ENVELOPE_PRESETS.
 */

import {
  computeFinishCoveringResistanceM2KW,
  getFlooringFinishMaterialById,
} from './flooringFinishMaterials.js';

/** @typedef {import('../types/shared-types.js').UnderfloorHeatingAssemblyLayer} UnderfloorHeatingAssemblyLayer */
/** @typedef {import('../types/shared-types.js').UnderfloorHeatingBasePreset} UnderfloorHeatingBasePreset */
/** @typedef {import('../types/shared-types.js').FlooringFinishMaterial} FlooringFinishMaterial */

/**
 * Термическое сопротивление одного слоя, м²·K/Вт (R = δ/λ).
 *
 * @param {UnderfloorHeatingAssemblyLayer} layer
 * @returns {number}
 */
export function computeLayerResistanceM2KW(layer) {
  const d = layer.thicknessM;
  const lambda = layer.thermalConductivityWmK;
  if (!(d > 0) || !(lambda > 0)) return 0;
  return d / lambda;
}

/**
 * Rλ,B слоёв базы над плоскостью isHeatingLayer (без финиша), м²·K/Вт.
 *
 * @param {UnderfloorHeatingAssemblyLayer[]} layers
 * @returns {number}
 */
export function computeBaseCoveringResistanceM2KW(layers) {
  const heatingIdx = layers.findIndex((l) => l.isHeatingLayer);
  if (heatingIdx < 0) return 0;
  let sum = 0;
  for (let i = heatingIdx + 1; i < layers.length; i += 1) {
    const layer = layers[i];
    if (!layer) continue;
    sum += computeLayerResistanceM2KW(layer);
  }
  return Math.round(sum * 10000) / 10000;
}

/**
 * Составное Rλ,B = база над контуром + финишное покрытие.
 *
 * @param {UnderfloorHeatingBasePreset} base
 * @param {FlooringFinishMaterial} finish
 * @returns {number}
 */
export function computeComposedCoveringResistanceM2KW(base, finish) {
  const baseR = computeBaseCoveringResistanceM2KW(base.layers);
  const finishR = computeFinishCoveringResistanceM2KW(finish);
  return Math.round((baseR + finishR) * 10000) / 10000;
}

/** Гостовая / эталонная база (XPS 30 мм) — дефолт анкеты. */
export const DEFAULT_UFH_BASE_PRESET_ID = 'ufh_base_interstory_screed_65';

/** Миграция устаревших монолитных presetId → base + finish. */
export const LEGACY_MONOLITHIC_UFH_PRESET_MAP = Object.freeze({
  underfloor_heating_glued_pvc_quartz_vinyl_interstory: {
    basePresetId: DEFAULT_UFH_BASE_PRESET_ID,
    finishMaterialId: 'pvc_glue',
  },
  underfloor_heating_floating_quartz_vinyl_interstory: {
    basePresetId: DEFAULT_UFH_BASE_PRESET_ID,
    finishMaterialId: 'pvc_click',
  },
});

/**
 * Сборка межэтажной базы ТП с заданной толщиной XPS под стяжкой.
 *
 * @param {object} args
 * @param {string} args.id
 * @param {string} args.name
 * @param {number} args.xpsThicknessM
 * @returns {UnderfloorHeatingBasePreset}
 */
function buildInterstoryUfhBasePreset({ id, name, xpsThicknessM }) {
  const xpsMm = Math.round(xpsThicknessM * 1000);
  /** @type {UnderfloorHeatingAssemblyLayer[]} */
  const layers = [
    {
      name: 'Залізобетонна плита перекриття',
      thicknessM: 0.15,
      thermalConductivityWmK: 1.74,
      isHeatingLayer: false,
    },
    {
      name: 'Теплоізоляція (XPS)',
      thicknessM: xpsThicknessM,
      thermalConductivityWmK: 0.034,
      isHeatingLayer: false,
    },
    {
      name: 'Стяжка ТП з трубами',
      thicknessM: 0.065,
      thermalConductivityWmK: 1.4,
      isHeatingLayer: true,
    },
    {
      name: 'Самовирівнювальний шар',
      thicknessM: 0.005,
      thermalConductivityWmK: 1.1,
      isHeatingLayer: false,
    },
  ];
  return {
    id,
    name,
    description:
      `Водяна тепла підлога в стяжці 65 мм над плитою перекриття; XPS ${xpsMm} мм під контуром. Фініш обирається окремо.`,
    usage: /** @type {const} */ ('underfloor_heating_base'),
    bottomBoundary: /** @type {const} */ ('heated'),
    layers,
    baseCoveringResistanceM2KW: computeBaseCoveringResistanceM2KW(layers),
  };
}

