/**
 * @param {string} basePresetId
 * @returns {import('../types/shared-types.js').UnderfloorHeatingBasePreset | null}
 */
export function getUnderfloorHeatingBasePresetById(basePresetId) {
  if (!basePresetId) return null;
  return (
    UNDERFLOOR_HEATING_BASE_PRESETS.find((p) => p.id === basePresetId) ?? null
  );
}

/**
 * Разрешает base + finish из комнаты (с миграцией legacy presetId).
 *
 * @param {import('../types/shared-types.js').RoomUnderfloorHeatingInput | {
 *   enabled?: boolean;
 *   presetId?: string;
 *   basePresetId?: string;
 *   finishMaterialId?: string;
 * } | null | undefined} ufh
 * @returns {{
 *   basePresetId: string;
 *   finishMaterialId: string;
 *   base: import('../types/shared-types.js').UnderfloorHeatingBasePreset;
 *   finish: import('../types/shared-types.js').FlooringFinishMaterial;
 * } | null}
 */
export function resolveUnderfloorHeatingComposition(ufh) {
  if (!ufh || ufh.enabled !== true) return null;

  let basePresetId =
    typeof ufh.basePresetId === 'string' ? ufh.basePresetId.trim() : '';
  let finishMaterialId =
    typeof ufh.finishMaterialId === 'string' ? ufh.finishMaterialId.trim() : '';

  const legacyId = typeof ufh.presetId === 'string' ? ufh.presetId.trim() : '';
  if ((!basePresetId || !finishMaterialId) && legacyId) {
    const mapped =
      /** @type {Record<string, { basePresetId: string, finishMaterialId: string }>} */ (
        LEGACY_MONOLITHIC_UFH_PRESET_MAP
      )[legacyId];
    if (mapped) {
      basePresetId = mapped.basePresetId;
      finishMaterialId = mapped.finishMaterialId;
    }
  }

  if (!basePresetId || !finishMaterialId) return null;
  const base = getUnderfloorHeatingBasePresetById(basePresetId);
  const finish = getFlooringFinishMaterialById(finishMaterialId);
  if (!base || !finish) return null;

  return { basePresetId, finishMaterialId, base, finish };
}

/**
 * Назначение: валидация справочника appliances.
 * Описание: проверка и нормализация правил подбора по типам техники (котёл, БКН, радиатор,
 * электробойлер); числовые пороги только из JSON/Mongo без дублирования в коде.
 */
import {
  requireFiniteNum,
  requireNonEmptyString,
  requireObject,
  requirePosNum,
} from './validateReferenceHelpers.js';

/**
 * @param {unknown} doc
 * @returns {import('./types.js').NormalizedApplianceRules}
 */
function validateAndNormalizeApplianceDoc(doc) {
  if (!doc || typeof doc !== 'object') {
    throw new Error('appliances: ожидается объект документа');
  }
  const d = /** @type {Record<string, unknown>} */ (doc);
  const kind = String(d.applianceKind ?? '').trim();
  const schemaVersionRaw = Number(d.schemaVersion);
  if (!Number.isFinite(schemaVersionRaw) || Math.trunc(schemaVersionRaw) < 1) {
    throw new Error(`appliances[${kind || '?'}].schemaVersion: обязательное целое >= 1`);
  }
  const schemaVersion = Math.trunc(schemaVersionRaw);
  const label = d.label != null ? String(d.label).trim() : kind;
  const basePath = `appliances[${kind || '?'}]`;

  if (kind === 'indirect_water_heater') {
    const c = requireObject(d, 'coupling', `${basePath}.coupling`);
    const sel = requireObject(d, 'selection', `${basePath}.selection`);
    return {
      applianceKind: 'indirect_water_heater',
      schemaVersion,
      label,
      coupling: {
        heatTimeSoftHintMinutes: requirePosNum(
          c,
          'heatTimeSoftHintMinutes',
          `${basePath}.coupling`,
        ),
        heatTimeParasiticHintMinutes: requirePosNum(
          c,
          'heatTimeParasiticHintMinutes',
          `${basePath}.coupling`,
        ),
        boilerBelowMinSourceToleranceKw: requirePosNum(
          c,
          'boilerBelowMinSourceToleranceKw',
          `${basePath}.coupling`,
        ),
        coilWeakerThanBoilerToleranceKw: requirePosNum(
          c,
          'coilWeakerThanBoilerToleranceKw',
          `${basePath}.coupling`,
        ),
        effectivePowerUsesMinOfCoilAndBoiler: c.effectivePowerUsesMinOfCoilAndBoiler !== false,
      },
      selection: {
        sortByVolumeAsc: sel.sortByVolumeAsc !== false,
        pickFirstGteRequired: sel.pickFirstGteRequired !== false,
      },
    };
  }

  if (kind === 'boiler') {
    const m = requireObject(d, 'mounting', `${basePath}.mounting`);
    const mt = requireObject(d, 'matching', `${basePath}.matching`);
    const h = requireObject(d, 'hints', `${basePath}.hints`);
    const sb = requireObject(
      h,
      'apartmentCombiSerialBuffer',
      `${basePath}.hints.apartmentCombiSerialBuffer`,
    );
    const ac = requireObject(d, 'apartmentClassification', `${basePath}.apartmentClassification`);
    const capRaw = Number(mt.nominalReservePercentCap);
    if (!Number.isFinite(capRaw) || Math.trunc(capRaw) < 100) {
      throw new Error(`${basePath}.matching.nominalReservePercentCap: обязательное целое >= 100`);
    }
    return {
      applianceKind: 'boiler',
      schemaVersion,
      label,
      mounting: {
        boilerRoomType: requireNonEmptyString(m, 'boilerRoomType', `${basePath}.mounting`),
        minBoilerRoomVolumeM3: requirePosNum(
          m,
          'minBoilerRoomVolumeM3',
          `${basePath}.mounting`,
        ),
        minBoilerRoomHeightM: requirePosNum(m, 'minBoilerRoomHeightM', `${basePath}.mounting`),
        maxApartmentNominalKw: requirePosNum(
          m,
          'maxApartmentNominalKw',
          `${basePath}.mounting`,
        ),
      },
      matching: {
        heatingReserveFactor: requirePosNum(
          mt,
          'heatingReserveFactor',
          `${basePath}.matching`,
        ),
        condensingHeatingReserveFactor: requirePosNum(
          mt,
          'condensingHeatingReserveFactor',
          `${basePath}.matching`,
        ),
        cascadeHintMinKw: requirePosNum(mt, 'cascadeHintMinKw', `${basePath}.matching`),
        nominalReservePercentCap: Math.trunc(capRaw),
      },
      hints: {
        comfortHotWaterHeatPartKwMax: requirePosNum(
          h,
          'comfortHotWaterHeatPartKwMax',
          `${basePath}.hints`,
        ),
        comfortHotWaterDhwKwMax: requirePosNum(
          h,
          'comfortHotWaterDhwKwMax',
          `${basePath}.hints`,
        ),
        comfortHotWaterTypicalBoilerKw: requirePosNum(
          h,
          'comfortHotWaterTypicalBoilerKw',
          `${basePath}.hints`,
        ),
        apartmentCombiSerialBuffer: {
          enabled: sb.enabled !== false,
          bufferTankLitersMin: requirePosNum(
            sb,
            'bufferTankLitersMin',
            `${basePath}.hints.apartmentCombiSerialBuffer`,
          ),
          bufferTankLitersMax: requirePosNum(
            sb,
            'bufferTankLitersMax',
            `${basePath}.hints.apartmentCombiSerialBuffer`,
          ),
          peakThermalPowerKwMin: requirePosNum(
            sb,
            'peakThermalPowerKwMin',
            `${basePath}.hints.apartmentCombiSerialBuffer`,
          ),
          minThermalFixtures: Math.max(
            1,
            Math.trunc(
              requireFiniteNum(
                sb,
                'minThermalFixtures',
                `${basePath}.hints.apartmentCombiSerialBuffer`,
              ),
            ),
          ),
        },
      },
      apartmentClassification: {
        largeAreaM2Min: requirePosNum(
          ac,
          'largeAreaM2Min',
          `${basePath}.apartmentClassification`,
        ),
        largeHeatingLoadKwMin: requirePosNum(
          ac,
          'largeHeatingLoadKwMin',
          `${basePath}.apartmentClassification`,
        ),
        minBathroomsForLargeApartment: Math.max(
          1,
          Math.trunc(
            requireFiniteNum(
              ac,
              'minBathroomsForLargeApartment',
              `${basePath}.apartmentClassification`,
            ),
          ),
        ),
        singleCircuitOversizeRatio: requirePosNum(
          ac,
          'singleCircuitOversizeRatio',
          `${basePath}.apartmentClassification`,
        ),
      },
    };
  }

  if (kind === 'electric_storage') {
    return {
      applianceKind: 'electric_storage',
      schemaVersion,
      label,
      matching: {},
    };
  }

  if (kind === 'radiator') {
    const p = requireObject(d, 'panelLengthRangeMm', `${basePath}.panelLengthRangeMm`);
    const min = Math.trunc(Number(p.min));
    const max = Math.trunc(Number(p.max));
    if (!Number.isFinite(min) || min <= 0) {
      throw new Error(`${basePath}.panelLengthRangeMm.min: обязательное целое > 0`);
    }
    if (!Number.isFinite(max) || max < min) {
      throw new Error(`${basePath}.panelLengthRangeMm.max: обязательное целое >= min`);
    }
    const ml = requireObject(d, 'microLoad', `${basePath}.microLoad`);
    const threshold = requirePosNum(
      ml,
      'minDesignWattsThreshold',
      `${basePath}.microLoad`,
    );
    const entryRaw = ml.entryRoomTypes;
    if (!Array.isArray(entryRaw) || entryRaw.length === 0) {
      throw new Error(`${basePath}.microLoad.entryRoomTypes: непустой массив строк`);
    }
    const entryRoomTypes = entryRaw.map((t, i) => {
      const s = String(t ?? '').trim();
      if (!s) {
        throw new Error(`${basePath}.microLoad.entryRoomTypes[${i}]: непустая строка`);
      }
      return s;
    });
    const ek = requireObject(d, 'emitterKind', `${basePath}.emitterKind`);
    const maxSectionsBeforeMultiUnit = Math.max(
      1,
      Math.trunc(
        requireFiniteNum(
          ek,
          'maxSectionsBeforeMultiUnit',
          `${basePath}.emitterKind`,
        ),
      ),
    );
    const maxUnitsPerRoom = Math.max(
      1,
      Math.trunc(
        requireFiniteNum(ek, 'maxUnitsPerRoom', `${basePath}.emitterKind`),
      ),
    );
    const maxSectionsHeuristic = Math.max(
      maxSectionsBeforeMultiUnit,
      Math.trunc(
        requireFiniteNum(
          ek,
          'maxSectionsHeuristic',
          `${basePath}.emitterKind`,
        ),
      ),
    );
    const sectionalCandidatesPerRoom = Math.max(
      1,
      Math.trunc(
        requireFiniteNum(
          ek,
          'sectionalCandidatesPerRoom',
          `${basePath}.emitterKind`,
        ),
      ),
    );
    const tieRaw = String(ek.tieBreakKind ?? '').trim();
    if (tieRaw !== 'sectional' && tieRaw !== 'panel') {
      throw new Error(
        `${basePath}.emitterKind.tieBreakKind: ожидается sectional|panel`,
      );
    }
    return {
      applianceKind: 'radiator',
      schemaVersion,
      label,
      panelLengthRangeMm: { min, max },
      microLoad: {
        minDesignWattsThreshold: threshold,
        entryRoomTypes,
      },
      emitterKind: {
        maxSectionsBeforeMultiUnit,
        maxUnitsPerRoom,
        maxSectionsHeuristic,
        sectionalCandidatesPerRoom,
        tieBreakKind: /** @type {'sectional' | 'panel'} */ (tieRaw),
      },
    };
  }

  if (kind === 'underfloor_heating') {
    const dist = requireObject(d, 'distribution', `${basePath}.distribution`);
    const mix = requireObject(d, 'mixingNode', `${basePath}.mixingNode`);
    return {
      applianceKind: 'underfloor_heating',
      schemaVersion,
      label,
      distribution: {
        autoHydraulicSeparatorMinBoilerKw: requirePosNum(
          dist,
          'autoHydraulicSeparatorMinBoilerKw',
          `${basePath}.distribution`,
        ),
        autoHydraulicSeparatorMinRoomsCount: Math.max(
          1,
          Math.trunc(
            requireFiniteNum(
              dist,
              'autoHydraulicSeparatorMinRoomsCount',
              `${basePath}.distribution`,
            ),
          ),
        ),
      },
      mixingNode: {
        deltaTK: requirePosNum(mix, 'deltaTK', `${basePath}.mixingNode`),
        valvePressureDropBar: requirePosNum(
          mix,
          'valvePressureDropBar',
          `${basePath}.mixingNode`,
        ),
        headMetersMinCollector: requirePosNum(
          mix,
          'headMetersMinCollector',
          `${basePath}.mixingNode`,
        ),
        headMetersMinHydraulicSeparator: requirePosNum(
          mix,
          'headMetersMinHydraulicSeparator',
          `${basePath}.mixingNode`,
        ),
      },
    };
  }

  if (kind === 'hydraulics') {
    const vel = requireObject(d, 'velocityLimitsMps', `${basePath}.velocityLimitsMps`);
    const len = requireObject(d, 'defaultLengthsM', `${basePath}.defaultLengthsM`);
    const zeta = requireObject(d, 'localLossZeta', `${basePath}.localLossZeta`);
    const rough = requireObject(d, 'roughnessMmByMaterial', `${basePath}.roughnessMmByMaterial`);
    const rec = {
      applianceKind: 'hydraulics',
      schemaVersion,
      label,
      mainTransitMinInternalDiameterMm: (() => {
        if (d.mainTransitMinInternalDiameterMm == null) return 20;
        return requirePosNum(d, 'mainTransitMinInternalDiameterMm', basePath);
      })(),
      branchMinInternalDiameterMm: (() => {
        if (d.branchMinInternalDiameterMm == null) return 12;
        return requirePosNum(d, 'branchMinInternalDiameterMm', basePath);
      })(),
      velocityLimitsMps: {
        mainMax: requirePosNum(vel, 'mainMax', `${basePath}.velocityLimitsMps`),
        branchMax: requirePosNum(vel, 'branchMax', `${basePath}.velocityLimitsMps`),
        mainMin: requirePosNum(vel, 'mainMin', `${basePath}.velocityLimitsMps`),
        ...(vel.branchMin != null
          ? {
            branchMin: (() => {
              const n = Number(vel.branchMin);
              if (!Number.isFinite(n) || n < 0) {
                throw new Error(`${basePath}.velocityLimitsMps.branchMin: число ≥ 0`);
              }
              return n;
            })(),
          }
          : { branchMin: 0 }),
      },
      radiatorBranchGrouping: (() => {
        if (d.radiatorBranchGrouping == null) {
          return {
            minFlowM3PerHourForIndividualBranch: 0.019,
            minHeatLoadWattsForIndividualBranch: 150,
            manifoldTrunkLengthM: 2,
            localZetaManifold: 1.5,
          };
        }
        const g = requireObject(d, 'radiatorBranchGrouping', `${basePath}.radiatorBranchGrouping`);
        const gp = `${basePath}.radiatorBranchGrouping`;
        return {
          minFlowM3PerHourForIndividualBranch: requirePosNum(
            g,
            'minFlowM3PerHourForIndividualBranch',
            gp,
          ),
          minHeatLoadWattsForIndividualBranch: requirePosNum(
            g,
            'minHeatLoadWattsForIndividualBranch',
            gp,
          ),
          manifoldTrunkLengthM: requirePosNum(g, 'manifoldTrunkLengthM', gp),
          localZetaManifold: requirePosNum(g, 'localZetaManifold', gp),
        };
      })(),
      defaultLengthsM: {
        mainLine: requirePosNum(len, 'mainLine', `${basePath}.defaultLengthsM`),
        radiatorBranch: requirePosNum(
          len,
          'radiatorBranch',
          `${basePath}.defaultLengthsM`,
        ),
        ufhCollectorBranch: requirePosNum(
          len,
          'ufhCollectorBranch',
          `${basePath}.defaultLengthsM`,
        ),
      },
      maxUfhLoopLengthM: requirePosNum(d, 'maxUfhLoopLengthM', basePath),
      ufhLoopLengthLayoutFactor: (() => {
        const n = requirePosNum(d, 'ufhLoopLengthLayoutFactor', basePath);
        if (n < 1 || n > 1.3) {
          throw new Error(
            `${basePath}.ufhLoopLengthLayoutFactor: ожидается число в диапазоне 1…1.3`,
          );
        }
        return n;
      })(),
      ufhLoopDeltaTK: requirePosNum(d, 'ufhLoopDeltaTK', basePath),
      ufhLoopVelocityMinMps: requirePosNum(d, 'ufhLoopVelocityMinMps', basePath),
      ufhLoopVelocityMaxMps: requirePosNum(d, 'ufhLoopVelocityMaxMps', basePath),
      maxUfhLoopPressureDropKPa: requirePosNum(d, 'maxUfhLoopPressureDropKPa', basePath),
      ufhLoopMinNominalDiameterMm: requirePosNum(d, 'ufhLoopMinNominalDiameterMm', basePath),
      ufhParasiticDownTriggerWm2: requirePosNum(d, 'ufhParasiticDownTriggerWm2', basePath),
      ufhParasiticDownToUpRatio: (() => {
        const n = requirePosNum(d, 'ufhParasiticDownToUpRatio', basePath);
        if (n > 1) {
          throw new Error(`${basePath}.ufhParasiticDownToUpRatio: число ≤ 1`);
        }
        return n;
      })(),
      ufhLoopPipeResizeEnabled: (() => {
        if (typeof d.ufhLoopPipeResizeEnabled !== 'boolean') {
          throw new Error(`${basePath}.ufhLoopPipeResizeEnabled: ожидается boolean`);
        }
        return d.ufhLoopPipeResizeEnabled;
      })(),
      ufhLoopPressureUtilizationForResize: (() => {
        const n = requirePosNum(d, 'ufhLoopPressureUtilizationForResize', basePath);
        if (n > 1) {
          throw new Error(`${basePath}.ufhLoopPressureUtilizationForResize: число ≤ 1`);
        }
        return n;
      })(),
      roughnessMmByMaterial: Object.fromEntries(
        Object.entries(rough).map(([k, v]) => {
          const n = Number(v);
          if (!Number.isFinite(n) || n <= 0) {
            throw new Error(`${basePath}.roughnessMmByMaterial.${k}: число > 0`);
          }
          return [k, n];
        }),
      ),
      localLossZeta: {
        elbow90: requirePosNum(zeta, 'elbow90', `${basePath}.localLossZeta`),
        teeBranch: requirePosNum(zeta, 'teeBranch', `${basePath}.localLossZeta`),
        teePass: requirePosNum(zeta, 'teePass', `${basePath}.localLossZeta`),
        teeBranchTakeoff: requirePosNum(
          zeta,
          'teeBranchTakeoff',
          `${basePath}.localLossZeta`,
        ),
        mixingNode: requirePosNum(zeta, 'mixingNode', `${basePath}.localLossZeta`),
        collector: requirePosNum(zeta, 'collector', `${basePath}.localLossZeta`),
      },
      pumpHeadMarginPercent: requirePosNum(d, 'pumpHeadMarginPercent', basePath),
      pumpDutyQMaxUtilizationPercent: (() => {
        const n = requirePosNum(d, 'pumpDutyQMaxUtilizationPercent', basePath);
        if (n > 100) {
          throw new Error(`${basePath}.pumpDutyQMaxUtilizationPercent: число ≤ 100`);
        }
        return n;
      })(),
      pumpMinHeadAtDutyM: requirePosNum(d, 'pumpMinHeadAtDutyM', basePath),
      pumpMaxHeadMarginPercent: requirePosNum(d, 'pumpMaxHeadMarginPercent', basePath),
      pumpMinHeadAtQMaxM: requirePosNum(d, 'pumpMinHeadAtQMaxM', basePath),
      primaryFlowMarginPercent: requirePosNum(d, 'primaryFlowMarginPercent', basePath),
      balancingValveKPaPerTurn: requirePosNum(d, 'balancingValveKPaPerTurn', basePath),
    };
    const mainTransitMin = rec.mainTransitMinInternalDiameterMm;
    const branchMin = rec.branchMinInternalDiameterMm;
    if (branchMin > mainTransitMin) {
      throw new Error(
        `${basePath}.branchMinInternalDiameterMm (${branchMin}) не может быть больше `
        + `mainTransitMinInternalDiameterMm (${mainTransitMin})`,
      );
    }
    return /** @type {import('./types.js').HydraulicsApplianceRulesDoc} */ (rec);
  }

  throw new Error(`appliances: неизвестный applianceKind «${kind}»`);
}

/**
 * @param {unknown} json — массив документов
 * @param {'file' | 'mongo'} [source]
 * @returns {import('./types.js').AppliancesBundle}
 */
export function validateAndNormalizeAppliancesBundle(json, source = 'file') {
  if (!Array.isArray(json)) {
    throw new Error('appliances: ожидается массив документов');
  }
  /** @type {Partial<import('./types.js').AppliancesBundle['byKind']>} */
  const byKind = {};
  /** @type {Partial<Record<import('./types.js').ApplianceKind, number>>} */
  const schemaVersions = {};

  for (const item of json) {
    const rec = validateAndNormalizeApplianceDoc(item);
    switch (rec.applianceKind) {
      case 'indirect_water_heater':
        byKind.indirect_water_heater = rec;
        schemaVersions.indirect_water_heater = rec.schemaVersion;
        break;
      case 'boiler':
        byKind.boiler = rec;
        schemaVersions.boiler = rec.schemaVersion;
        break;
      case 'electric_storage':
        byKind.electric_storage = rec;
        schemaVersions.electric_storage = rec.schemaVersion;
        break;
      case 'radiator':
        byKind.radiator = rec;
        schemaVersions.radiator = rec.schemaVersion;
        break;
      case 'underfloor_heating':
        byKind.underfloor_heating = rec;
        schemaVersions.underfloor_heating = rec.schemaVersion;
        break;
      case 'hydraulics':
        byKind.hydraulics = rec;
        schemaVersions.hydraulics = rec.schemaVersion;
        break;
      default: {
        const _exhaustive = /** @type {never} */ (rec);
        void _exhaustive;
        throw new Error('appliances: неподдерживаемый applianceKind после валидации');
      }
    }
  }

  const required = /** @type {const} */ ([
    'indirect_water_heater',
    'boiler',
    'electric_storage',
    'radiator',
    'underfloor_heating',
    'hydraulics',
  ]);
  for (const k of required) {
    if (!byKind[k]) {
      throw new Error(`appliances: отсутствует обязательный документ applianceKind=${k}`);
    }
  }

  const resolvedSource = source === 'mongo' ? 'mongo' : 'file';

  return {
    byKind: /** @type {import('./types.js').AppliancesBundle['byKind']} */ (byKind),
    schemaVersions,
    source: resolvedSource,
  };
}

/**
 * Назначение: валидация справочника water_norms.
 * Описание: проверка и нормализация норм ГВС (расходы, сеансы, storage, simultaneity);
 * единственный источник чисел — JSON/Mongo, без запасных констант в коде.
 */
import {
  requireEnum,
  requireFiniteNum,
  requireObject,
  requirePosNum,
} from './validateReferenceHelpers.js';

/** @param {unknown} raw */
function normObjectTypes(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('water_norms.objectTypes: ожидается объект');
  }
  const o = /** @type {Record<string, unknown>} */ (raw);
  /** @type {ReadonlyArray<'house' | 'apartment'>} */
  const keys = ['house', 'apartment'];
  /** @type {import('./types.js').NormalizedWaterNorms['objectTypes']} */
  const out = {
    house: { simultaneityBase: 0, dhwSupplyScenario: 'storage' },
    apartment: { simultaneityBase: 0, dhwSupplyScenario: 'flowThrough' },
  };
  for (const key of keys) {
    const rec = requireObject(o, key, `water_norms.objectTypes.${key}`);
    const base = requirePosNum(rec, 'simultaneityBase', `water_norms.objectTypes.${key}`);
    const scenario = requireEnum(
      rec,
      'dhwSupplyScenario',
      ['flowThrough', 'storage'],
      `water_norms.objectTypes.${key}`,
    );
    out[key] = {
      simultaneityBase: base,
      dhwSupplyScenario: /** @type {'storage' | 'flowThrough'} */ (scenario),
    };
  }
  return out;
}

/**
 * @param {unknown} json
 * @returns {import('./types.js').NormalizedWaterNorms}
 */
export function validateAndNormalizeWaterNorms(json) {
  if (!json || typeof json !== 'object') {
    throw new Error('water_norms: ожидается объект');
  }
  const root = /** @type {Record<string, unknown>} */ (json);
  const schemaVersionRaw = Number(root.schemaVersion);
  if (!Number.isFinite(schemaVersionRaw) || Math.trunc(schemaVersionRaw) < 1) {
    throw new Error('water_norms.schemaVersion: обязательное целое >= 1');
  }
  const schemaVersion = Math.trunc(schemaVersionRaw);
  const label = root.label != null ? String(root.label).trim() : '';
  if (!label) {
    throw new Error('water_norms.label: обязательная непустая строка');
  }

  const objectTypes = normObjectTypes(root.objectTypes ?? null);
  const sim = requireObject(root, 'simultaneity', 'water_norms.simultaneity');

  const fixtureRaw = requireObject(root, 'fixtureHotFlowLps', 'water_norms.fixtureHotFlowLps');
  /** @type {Record<string, number>} */
  const fixtureHotFlowLps = {};
  for (const [k, v] of Object.entries(fixtureRaw)) {
    const n = Number(v);
    if (!Number.isFinite(n) || n < 0) {
      throw new Error(`water_norms.fixtureHotFlowLps.${k}: ожидается число >= 0`);
    }
    fixtureHotFlowLps[k] = n;
  }

  const keysRaw = root.hotThermalFixtureKeys;
  if (!Array.isArray(keysRaw) || keysRaw.length === 0) {
    throw new Error('water_norms.hotThermalFixtureKeys: обязательный непустой массив');
  }
  const hotThermalFixtureKeys = keysRaw.map((k) => String(k).trim()).filter(Boolean);
  if (hotThermalFixtureKeys.length !== keysRaw.length) {
    throw new Error('water_norms.hotThermalFixtureKeys: пустые ключи приборов недопустимы');
  }

  const excludedRaw = root.hotThermalFixtureKeysExcludedForApartment;
  if (!Array.isArray(excludedRaw)) {
    throw new Error(
      'water_norms.hotThermalFixtureKeysExcludedForApartment: обязательный массив строк',
    );
  }
  const hotThermalFixtureKeysExcludedForApartment = excludedRaw
    .map((k) => String(k).trim())
    .filter(Boolean);
  for (const k of hotThermalFixtureKeysExcludedForApartment) {
    if (!(k in fixtureHotFlowLps)) {
      throw new Error(
        `water_norms.hotThermalFixtureKeysExcludedForApartment: неизвестный прибор "${k}"`,
      );
    }
  }

  const cold = requireObject(root, 'coldWaterDesignC', 'water_norms.coldWaterDesignC');
  const hw = requireObject(root, 'hotWaterC', 'water_norms.hotWaterC');
  const st = requireObject(root, 'storage', 'water_norms.storage');
  const aes = requireObject(root, 'apartmentElectricStorage', 'water_norms.apartmentElectricStorage');
  const cbe = requireObject(root, 'combiBufferElectricStorage', 'water_norms.combiBufferElectricStorage');
  const scbe = requireObject(
    root,
    'singleCircuitBufferElectricStorage',
    'water_norms.singleCircuitBufferElectricStorage',
  );
  const ses = requireObject(root, 'session', 'water_norms.session');
  const ph = requireObject(root, 'physics', 'water_norms.physics');

  const typicalRaw = st.typicalTankSizes;
  if (!Array.isArray(typicalRaw) || typicalRaw.length === 0) {
    throw new Error('water_norms.storage.typicalTankSizes: обязательный непустой массив');
  }
  const typicalTankSizes = typicalRaw.map((x, i) => {
    const n = Math.trunc(Number(x));
    if (!Number.isFinite(n) || n <= 0) {
      throw new Error(`water_norms.storage.typicalTankSizes[${i}]: ожидается целое > 0`);
    }
    return n;
  });

  const betaMin = requireFiniteNum(sim, 'betaMin', 'water_norms.simultaneity');
  const betaMax = requireFiniteNum(sim, 'betaMax', 'water_norms.simultaneity');
  if (betaMin > betaMax) {
    throw new Error('water_norms.simultaneity: betaMin не может быть больше betaMax');
  }

  const hwMin = requireFiniteNum(hw, 'min', 'water_norms.hotWaterC');
  const hwMax = requireFiniteNum(hw, 'max', 'water_norms.hotWaterC');
  const hwDefault = requireFiniteNum(hw, 'default', 'water_norms.hotWaterC');
  if (hwMin > hwMax || hwDefault < hwMin || hwDefault > hwMax) {
    throw new Error('water_norms.hotWaterC: min <= default <= max');
  }

  return {
    schemaVersion,
    label,
    objectTypes,
    simultaneity: {
      residentsFactorPerPerson: requirePosNum(
        sim,
        'residentsFactorPerPerson',
        'water_norms.simultaneity',
      ),
      residentsFactorCap: Math.max(
        1,
        Math.trunc(requireFiniteNum(sim, 'residentsFactorCap', 'water_norms.simultaneity')),
      ),
      fixtureCountDivisor: requirePosNum(sim, 'fixtureCountDivisor', 'water_norms.simultaneity'),
      betaMin,
      betaMax,
    },
    fixtureHotFlowLps,
    hotThermalFixtureKeys,
    hotThermalFixtureKeysExcludedForApartment,
    coldWaterDesignC: {
      winter: requireFiniteNum(cold, 'winter', 'water_norms.coldWaterDesignC'),
      summer: requireFiniteNum(cold, 'summer', 'water_norms.coldWaterDesignC'),
    },
    hotWaterC: {
      min: hwMin,
      max: hwMax,
      default: hwDefault,
    },
    apartmentElectricStorage: {
      litersPerResident: requirePosNum(
        aes,
        'litersPerResident',
        'water_norms.apartmentElectricStorage',
      ),
      minTankLiters: requirePosNum(
        aes,
        'minTankLiters',
        'water_norms.apartmentElectricStorage',
      ),
    },
    combiBufferElectricStorage: {
      litersPerResident: requirePosNum(
        cbe,
        'litersPerResident',
        'water_norms.combiBufferElectricStorage',
      ),
      minTankLiters: requirePosNum(
        cbe,
        'minTankLiters',
        'water_norms.combiBufferElectricStorage',
      ),
    },
    singleCircuitBufferElectricStorage: {
      litersPerResident: requirePosNum(
        scbe,
        'litersPerResident',
        'water_norms.singleCircuitBufferElectricStorage',
      ),
      minTankLiters: requirePosNum(
        scbe,
        'minTankLiters',
        'water_norms.singleCircuitBufferElectricStorage',
      ),
    },
    storage: {
      litersPerResident: requirePosNum(st, 'litersPerResident', 'water_norms.storage'),
      bathMinTankLiters: requirePosNum(st, 'bathMinTankLiters', 'water_norms.storage'),
      tropicalShowerVolumeFactor: requirePosNum(
        st,
        'tropicalShowerVolumeFactor',
        'water_norms.storage',
      ),
      indirectHeatTimeMinutes: requirePosNum(
        st,
        'indirectHeatTimeMinutes',
        'water_norms.storage',
      ),
      boilerDhwPowerMinKw: requirePosNum(st, 'boilerDhwPowerMinKw', 'water_norms.storage'),
      volumeSubstitutionFactor: requirePosNum(
        st,
        'volumeSubstitutionFactor',
        'water_norms.storage',
      ),
      typicalTankSizes,
    },
    session: {
      bathLiters: requirePosNum(ses, 'bathLiters', 'water_norms.session'),
      showerLiters: requirePosNum(ses, 'showerLiters', 'water_norms.session'),
      kitchenSinkLiters: requirePosNum(ses, 'kitchenSinkLiters', 'water_norms.session'),
      bathroomSinkLiters: requirePosNum(ses, 'bathroomSinkLiters', 'water_norms.session'),
      minMixedLiters: requirePosNum(ses, 'minMixedLiters', 'water_norms.session'),
      kitchenSinkCap: Math.max(
        0,
        Math.trunc(requireFiniteNum(ses, 'kitchenSinkCap', 'water_norms.session')),
      ),
      bathroomSinkCap: Math.max(
        0,
        Math.trunc(requireFiniteNum(ses, 'bathroomSinkCap', 'water_norms.session')),
      ),
      showerUsesResidentsDivisor: Math.max(
        1,
        Math.trunc(
          requireFiniteNum(ses, 'showerUsesResidentsDivisor', 'water_norms.session'),
        ),
      ),
    },
    physics: {
      cpKjPerKgK: requirePosNum(ph, 'cpKjPerKgK', 'water_norms.physics'),
      rhoKgPerL: requirePosNum(ph, 'rhoKgPerL', 'water_norms.physics'),
    },
  };
}

/**
 * Назначение: расчётные формулы ГВС.
 * Описание: чистые функции тепловой мощности, объёма накопительного бака и времени нагрева;
 * все числовые нормы передаются из справочника water_norms.
 */

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {number} flowLps
 * @param {number} deltaTK
 * @returns {number}
 */
export function hotWaterThermalPowerKw(norms, flowLps, deltaTK) {
  const q = Number(flowLps) || 0;
  const dt = Number(deltaTK) || 0;
  if (q <= 0 || dt <= 0) return 0;
  const { rhoKgPerL, cpKjPerKgK } = norms.physics;
  return q * rhoKgPerL * cpKjPerKgK * dt;
}

/**
 * Legacy-норма накопичувача: жильці × л/особу, мін. при ванні.
 * Множник tropicalShower застосовується в calculateHotWaterDemand
 * один раз до combinedRaw (max legacy/сеанс), не тут.
 *
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {number} residents
 * @param {number} bathCount
 * @returns {number}
 */
export function recommendedStorageTankLitersRaw(norms, residents, bathCount) {
  const { storage } = norms;
  const pop = Math.max(0, Math.trunc(Number(residents) || 0));
  const baths = Math.max(0, Math.trunc(Number(bathCount) || 0));
  let liters = pop * storage.litersPerResident;
  if (baths >= 1) {
    liters = Math.max(liters, storage.bathMinTankLiters);
  }
  return Math.ceil(liters);
}

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {number} volumeLiters
 * @param {number} deltaTK
 * @param {number} [heatMinutes]
 */
export function tankVolumeHeatPowerKw(norms, volumeLiters, deltaTK, heatMinutes) {
  const V = Number(volumeLiters) || 0;
  const dt = Number(deltaTK) || 0;
  const tMin = Number(heatMinutes) || norms.storage.indirectHeatTimeMinutes;
  const tSec = Math.max(60, tMin * 60);
  if (V <= 0 || dt <= 0) return 0;
  const { rhoKgPerL, cpKjPerKgK } = norms.physics;
  return (V * rhoKgPerL * cpKjPerKgK * dt) / tSec;
}

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {import('../types/shared-types.js').HotWaterFixturesInput | Record<string, number>} fixtures
 * @param {number} residents
 * @returns {number}
 */
export function estimatePeakSessionLitersMixed(norms, fixtures, residents) {
  const { session } = norms;
  const bath = Math.max(0, Math.trunc(Number(fixtures?.bath) || 0));
  const shower = Math.max(0, Math.trunc(Number(fixtures?.shower) || 0));
  const kitchenSink = Math.max(0, Math.trunc(Number(fixtures?.kitchenSink) || 0));
  const sink = Math.max(0, Math.trunc(Number(fixtures?.sink) || 0));
  const pop = Math.max(0, Math.min(20, Math.trunc(Number(residents) || 0)));

  let sessionLiters = 0;
  if (bath >= 1) sessionLiters += session.bathLiters;
  const div = session.showerUsesResidentsDivisor;
  const showerUses =
    shower <= 0 ? 0 : Math.min(shower, Math.max(1, Math.ceil(pop / div)));
  sessionLiters += showerUses * session.showerLiters;
  sessionLiters += Math.min(kitchenSink, session.kitchenSinkCap) * session.kitchenSinkLiters;
  sessionLiters += Math.min(sink, session.bathroomSinkCap) * session.bathroomSinkLiters;

  if (pop > 0 && sessionLiters < session.minMixedLiters) {
    sessionLiters = session.minMixedLiters;
  }
  return Math.ceil(sessionLiters);
}

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {number} sessionLitersMixed
 */
export function equivalentStorageTankLitersFromSession(norms, sessionLitersMixed) {
  const L = Number(sessionLitersMixed) || 0;
  const k = norms.storage.volumeSubstitutionFactor;
  if (L <= 0 || k <= 0) return 0;
  return Math.ceil(L / k);
}

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {number} volumeLiters
 * @param {number} deltaTK
 * @param {number} powerKw
 * @returns {number | null}
 */
function tankFullHeatTimeSeconds(norms, volumeLiters, deltaTK, powerKw) {
  const V = Number(volumeLiters) || 0;
  const dt = Number(deltaTK) || 0;
  const P = Number(powerKw) || 0;
  if (V <= 0 || dt <= 0 || P <= 0) return null;
  const { rhoKgPerL, cpKjPerKgK } = norms.physics;
  const energyKj = V * rhoKgPerL * cpKjPerKgK * dt;
  return energyKj / P;
}

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {number} volumeLiters
 * @param {number} deltaTK
 * @param {number} powerKw
 * @returns {number | null}
 */
export function tankFullHeatTimeMinutes(norms, volumeLiters, deltaTK, powerKw) {
  const sec = tankFullHeatTimeSeconds(norms, volumeLiters, deltaTK, powerKw);
  return sec == null ? null : Number((sec / 60).toFixed(1));
}

/**
 * @param {import('./types.js').NormalizedWaterNorms} norms
 * @param {'house' | 'apartment'} objectType
 * @param {number} thermalFixtureCount
 * @param {number} residents
 */
export function simultaneityFactor(norms, objectType, thermalFixtureCount, residents) {
  const n = Math.max(0, thermalFixtureCount);
  if (n <= 0) return 1;
  if (n === 1) return 1;

  const ot = norms.objectTypes[objectType] ?? norms.objectTypes.house;
  const { simultaneity: sim } = norms;
  let beta = ot.simultaneityBase;
  const pop = Math.max(0, Math.min(20, Math.trunc(Number(residents) || 0)));
  beta *= 1 + Math.min(pop, sim.residentsFactorCap) * sim.residentsFactorPerPerson;
  beta *= 1 / (1 + sim.fixtureCountDivisor * Math.max(0, n - 1));
  return Math.min(sim.betaMax, Math.max(sim.betaMin, beta));
}

/**
 * Назначение: чистые функции контракта admin feedback API.
 */

import mongoose from 'mongoose';

const FEEDBACK_STATUSES = new Set(['new', 'read', 'resolved']);
const FEEDBACK_TYPES = new Set(['bug', 'contact']);

/**
 * @param {unknown} value
 * @returns {string}
 */
function singleQueryValue(value) {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * @param {unknown} value
 * @returns {import('../types/shared-types.js').FeedbackStatus | null}
 */
function parseStatus(value) {
  const status = singleQueryValue(value);
  return FEEDBACK_STATUSES.has(status)
    ? /** @type {import('../types/shared-types.js').FeedbackStatus} */ (status)
    : null;
}

/**
 * @param {unknown} value
 * @returns {import('../types/shared-types.js').FeedbackType | null}
 */
function parseType(value) {
  const type = singleQueryValue(value);
  return FEEDBACK_TYPES.has(type)
    ? /** @type {import('../types/shared-types.js').FeedbackType} */ (type)
    : null;
}

/**
 * @param {unknown} value
 * @returns {Date | undefined}
 */
function optionalDate(value) {
  if (value instanceof Date && Number.isFinite(value.getTime())) return value;
  return undefined;
}

/**
 * @param {unknown} value
 * @returns {string | undefined}
 */
function optionalString(value) {
  return typeof value === 'string' && value !== '' ? value : undefined;
}

/**
 * @param {unknown} value
 * @param {string} field
 * @returns {string}
 */
function requiredDateIso(value, field) {
  const date = optionalDate(value);
  if (!date) throw new TypeError(`Feedback ${field} отсутствует`);
  return date.toISOString();
}

/**
 * @param {{ createdAt: Date, id: import('mongoose').Types.ObjectId }} cursor
 * @returns {string}
 */
export function encodeFeedbackCursor(cursor) {
  return Buffer.from(
    JSON.stringify({ createdAt: cursor.createdAt.toISOString(), id: String(cursor.id) }),
    'utf8',
  ).toString('base64url');
}

/**
 * @param {unknown} value
 * @returns {{ createdAt: Date, id: import('mongoose').Types.ObjectId } | null}
 */
export function decodeFeedbackCursor(value) {
  const raw = singleQueryValue(value);
  if (!raw) return null;

  try {
    /** @type {unknown} */
    const decoded = JSON.parse(Buffer.from(raw, 'base64url').toString('utf8'));
    if (!decoded || typeof decoded !== 'object') return null;
    const record = /** @type {Record<string, unknown>} */ (decoded);
    if (typeof record.createdAt !== 'string' || typeof record.id !== 'string') return null;
    const createdAt = new Date(record.createdAt);
    if (!Number.isFinite(createdAt.getTime()) || !mongoose.Types.ObjectId.isValid(record.id)) {
      return null;
    }
    const id = new mongoose.Types.ObjectId(record.id);
    if (String(id) !== record.id) return null;
    return { createdAt, id };
  } catch {
    return null;
  }
}

/**
 * @param {import('express').Request['query']} query
 * @returns {{ ok: true, value: { limit: number, status?: import('../types/shared-types.js').FeedbackStatus, type?: import('../types/shared-types.js').FeedbackType, cursor?: { createdAt: Date, id: import('mongoose').Types.ObjectId } } } | { ok: false, message: string }}
 */
export function parseAdminFeedbackListQuery(query) {
  for (const field of ['limit', 'status', 'type', 'cursor']) {
    if (query[field] !== undefined && typeof query[field] !== 'string') {
      return { ok: false, message: `${field} должен быть единственным строковым значением` };
    }
  }

  const limitRaw = singleQueryValue(query.limit);
  const limit = limitRaw === '' ? 20 : Number(limitRaw);
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    return { ok: false, message: 'limit должен быть целым числом от 1 до 100' };
  }

  const statusRaw = singleQueryValue(query.status);
  const status = statusRaw ? parseStatus(statusRaw) : null;
  if (statusRaw && !status) {
    return { ok: false, message: 'status должен быть new, read или resolved' };
  }

  const typeRaw = singleQueryValue(query.type);
  const type = typeRaw ? parseType(typeRaw) : null;
  if (typeRaw && !type) {
    return { ok: false, message: 'type должен быть bug или contact' };
  }

  const cursorRaw = singleQueryValue(query.cursor);
  const cursor = cursorRaw ? decodeFeedbackCursor(cursorRaw) : null;
  if (cursorRaw && !cursor) {
    return { ok: false, message: 'Некорректный cursor' };
  }

  return {
    ok: true,
    value: {
      limit,
      ...(status ? { status } : {}),
      ...(type ? { type } : {}),
      ...(cursor ? { cursor } : {}),
    },
  };
}

/**
 * @param {unknown} body
 * @returns {{ ok: true, status: import('../types/shared-types.js').FeedbackStatus } | { ok: false, message: string }}
 */
export function parseAdminFeedbackPatchBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { ok: false, message: 'Тело запроса должно быть объектом { status }' };
  }
  const record = /** @type {Record<string, unknown>} */ (body);
  if (Object.keys(record).length !== 1) {
    return { ok: false, message: 'Допускается только поле status' };
  }
  const status = parseStatus(record.status);
  return status
    ? { ok: true, status }
    : { ok: false, message: 'status должен быть new, read или resolved' };
}

/**
 * @param {import('../types/shared-types.js').FeedbackStatus} status
 * @param {Date | undefined} currentReadAt
 * @param {Date} now
 * @returns {{ $set: { status: import('../types/shared-types.js').FeedbackStatus, readAt?: Date, resolvedAt?: Date }, $unset?: { readAt?: 1, resolvedAt?: 1 } }}
 */
export function buildFeedbackStatusUpdate(status, currentReadAt, now) {
  if (status === 'new') {
    return { $set: { status }, $unset: { readAt: 1, resolvedAt: 1 } };
  }
  if (status === 'read') {
    return {
      $set: { status, readAt: currentReadAt ?? now },
      $unset: { resolvedAt: 1 },
    };
  }
  return {
    $set: {
      status,
      readAt: currentReadAt ?? now,
      resolvedAt: now,
    },
  };
}

/**
 * @param {import('../types/shared-types.js').FeedbackMongoDoc} doc
 * @returns {import('../types/shared-types.js').AdminFeedbackItem}
 */
export function serializeAdminFeedback(doc) {
  if (!doc._id) throw new TypeError('Feedback _id отсутствует');
  const status = doc.status === undefined ? 'new' : parseStatus(doc.status);
  if (!status) throw new TypeError('Feedback status некорректен');

  const readAt = optionalDate(doc.readAt);
  const resolvedAt = optionalDate(doc.resolvedAt);
  return {
    id: String(doc._id),
    type: doc.type,
    status,
    message: doc.message,
    ...(optionalString(doc.email) ? { email: doc.email } : {}),
    ...(optionalString(doc.name) ? { name: doc.name } : {}),
    ...(optionalString(doc.pageUrl) ? { pageUrl: doc.pageUrl } : {}),
    ...(optionalString(doc.appVersion) ? { appVersion: doc.appVersion } : {}),
    ...(optionalString(doc.buildId) ? { buildId: doc.buildId } : {}),
    ...(optionalString(doc.ownerSub) ? { ownerSub: doc.ownerSub } : {}),
    ...(readAt ? { readAt: readAt.toISOString() } : {}),
    ...(resolvedAt ? { resolvedAt: resolvedAt.toISOString() } : {}),
    createdAt: requiredDateIso(doc.createdAt, 'createdAt'),
    updatedAt: requiredDateIso(doc.updatedAt, 'updatedAt'),
  };
}

/**
 * Назначение: in-memory fan-out событий feedback для одного процесса API.
 */

import { logger } from '../utils/logger.js';

/** @type {Set<import('../types/shared-types.js').FeedbackEventListener>} */
const listeners = new Set();

/**
 * @param {import('../types/shared-types.js').FeedbackEventListener} listener
 * @returns {() => void}
 */
export function subscribeFeedbackEvents(listener) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Метадані події для логів без PII (як feedback.created).
 *
 * @param {import('../types/shared-types.js').FeedbackCreatedEvent} event
 * @returns {{ event?: string, feedbackId?: string, type?: string, hasEmail: boolean }}
 */
function feedbackEventLogMeta(event) {
  const fb =
    event && typeof event === 'object' && event.feedback && typeof event.feedback === 'object'
      ? event.feedback
      : null;
  return {
    ...(typeof event?.event === 'string' ? { event: event.event } : {}),
    ...(fb && typeof fb.id === 'string' ? { feedbackId: fb.id } : {}),
    ...(fb && typeof fb.type === 'string' ? { type: fb.type } : {}),
    hasEmail: Boolean(fb && typeof fb.email === 'string' && fb.email.trim()),
  };
}

/**
 * @param {import('../types/shared-types.js').FeedbackCreatedEvent} event
 * @returns {void}
 */
export function publishFeedbackEvent(event) {
  for (const listener of [...listeners]) {
    try {
      listener(event);
    } catch (err) {
      // Ошибка одного SSE-клиента не должна мешать доставке остальным.
      // Payload (email/message) у лог не кладемо — лише метадані.
      logger.warn('feedbackEventHub.sse.listener_error', null, {
        ...feedbackEventLogMeta(event),
        message: err instanceof Error ? err.message : String(err),
      });
    }
  }
}

/**
 * @returns {number}
 */
export function feedbackEventSubscriberCount() {
  return listeners.size;
}

/**
 * Назначение: валидация тела POST /api/v1/feedback.
 */

const EMAIL_RE = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;
const TYPE_SET = new Set(['bug', 'contact']);

/**
 * Санитизация строки (без HTML).
 *
 * @param {unknown} value
 * @param {number} maxLen
 * @returns {string | null}
 */
function sanitizeString(value, maxLen) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim().replace(/[<>]/g, '');
  if (!trimmed) return null;
  return trimmed.slice(0, maxLen);
}

/**
 * @param {unknown} body
 * @returns {{ ok: true, data: import('../types/shared-types.js').FeedbackInput } | { ok: false, message: string, code: string }}
 */
export function validateFeedbackBody(body) {
  if (!body || typeof body !== 'object') {
    return { ok: false, message: 'Очікується JSON-об\'єкт', code: 'FEEDBACK_INVALID_BODY' };
  }

  const raw = /** @type {Record<string, unknown>} */ (body);
  const type = typeof raw.type === 'string' ? raw.type.trim() : '';
  if (!TYPE_SET.has(type)) {
    return { ok: false, message: 'type має бути bug або contact', code: 'FEEDBACK_INVALID_TYPE' };
  }

  const message = sanitizeString(raw.message, 4000);
  if (!message) {
    return { ok: false, message: 'message обов\'язковий', code: 'FEEDBACK_MESSAGE_REQUIRED' };
  }

  const emailRaw = sanitizeString(raw.email, 200);
  if (type === 'contact' && !emailRaw) {
    return { ok: false, message: 'email обов\'язковий для contact', code: 'FEEDBACK_EMAIL_REQUIRED' };
  }
  if (emailRaw && !EMAIL_RE.test(emailRaw)) {
    return { ok: false, message: 'Некоректний email', code: 'FEEDBACK_EMAIL_INVALID' };
  }

  const name = sanitizeString(raw.name, 120) ?? undefined;
  const pageUrl = sanitizeString(raw.pageUrl, 2000) ?? undefined;
  const appVersion = sanitizeString(raw.appVersion, 40) ?? undefined;
  const buildId = sanitizeString(raw.buildId, 80) ?? undefined;

  /** @type {import('../types/shared-types.js').FeedbackInput} */
  const data = {
    type: /** @type {'bug' | 'contact'} */ (type),
    message,
  };
  if (emailRaw) data.email = emailRaw;
  if (name) data.name = name;
  if (pageUrl) data.pageUrl = pageUrl;
  if (appVersion) data.appVersion = appVersion;
  if (buildId) data.buildId = buildId;

  return {
    ok: true,
    data,
  };
}

/**
 * Назначение: построение топологического графа из HydraulicsPipelineInput.
 * Описание: radiators_only, ufh_only, mixed — узлы и рёбра без подбора диаметров.
 */

import {
  resolveCirculationFlows,
  resolvePrimaryMainLineFlowM3h,
} from './resolveCirculationFlows.js';
import { thermalLoadToFlow } from './thermalLoadToFlow.js';
import { round } from '../utils/math.js';
import { buildRadiatorSubgraph } from './buildRadiatorSubgraph.js';

/**
 * @param {number} floor
 * @returns {string}
 */
function ufhCollectorNodeId(floor) {
  return `ufh_collector_floor_${floor}`;
}

/**
 * @param {import('./types.js').HydraulicsUfhRoom} room
 * @returns {import('./types.js').HydraulicsUfhLoop[]}
 */
function resolveRoomLoopsForGraph(room) {
  if (room.loops?.length) return room.loops;
  const spacingM = Math.max(0.05, (Number(room.pipeSpacingMm) || 150) / 1000);
  const area = Math.max(0, Number(room.areaM2) || 0);
  const loopLengthM = area > 0 ? round(area / spacingM, 1) : 0;
  return [{
    loopId: `${room.roomId}_loop_1`,
    loopLengthM,
    heatLoadWatts: room.heatLoadWatts,
    flowRateM3PerHour: room.flowRateM3PerHour,
  }];
}

/**
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {import('./types.js').HydraulicsGraph}
 */
export function buildHydraulicsGraph(dto) {
  const flowCtx = resolveCirculationFlows(dto);

  /** @type {import('./types.js').HydraulicsGraphNode[]} */
  const nodes = [];
  /** @type {import('./types.js').HydraulicsGraphEdge[]} */
  const edges = [];

  /**
   * @param {string} id
   * @param {import('./types.js').HydraulicsNodeKind} kind
   * @param {string} label
   * @param {Partial<Omit<import('./types.js').HydraulicsGraphNode, 'id' | 'kind' | 'label'>>} [extra]
   */
  const pushNode = (id, kind, label, extra = {}) => {
    nodes.push({ id, kind, label, ...extra });
  };

  pushNode('boiler', 'boiler', 'Котел');
  let upstreamId = 'boiler';

  const mode = dto.meta.heatingEmittersMode;
  const ufh = dto.circuits.underfloor;
  const rad = dto.circuits.radiators;

  const needsSeparator =
    ufh?.isMixingNodeRequired
    && ufh.distributionPreset === 'hydraulic_separator';
  const needsMixingNode =
    ufh?.isMixingNodeRequired
    && ufh.distributionPreset === 'collector_mixing_valve';

  const primaryMainFlow = resolvePrimaryMainLineFlowM3h(dto);

  if (needsSeparator) {
    pushNode('hydraulic_separator', 'hydraulic_separator', 'Гідрострілка');
    edges.push({
      id: 'e_boiler_separator',
      from: upstreamId,
      to: 'hydraulic_separator',
      lengthM: dto.layout.mainLineLengthM,
      fluid: 'heating',
      designFlowM3PerHour: primaryMainFlow,
      supplyC: dto.source.supplyC,
      returnC: dto.source.returnC,
      segmentRole: 'main',
      isMainLine: true,
    });
    upstreamId = 'hydraulic_separator';
  } else if (
    dto.layout.mainLineLengthM > 0
    || mode !== 'ufh_only'
    || needsMixingNode
  ) {
    pushNode('main_collector', 'main_collector', 'Магістраль / колектор');
    edges.push({
      id: 'e_boiler_main',
      from: upstreamId,
      to: 'main_collector',
      lengthM: dto.layout.mainLineLengthM,
      fluid: 'heating',
      designFlowM3PerHour: primaryMainFlow,
      supplyC: dto.source.supplyC,
      returnC: dto.source.returnC,
      segmentRole: 'main',
      isMainLine: true,
    });
    upstreamId = 'main_collector';
  }

  if (rad?.consumers?.length && mode !== 'ufh_only') {
    buildRadiatorSubgraph({
      upstreamId,
      dto,
      pushNode,
      pushEdge: (edge) => edges.push(edge),
    });
  }

  if (ufh?.rooms?.length && mode !== 'radiators_only') {
    let ufhUpstreamId = upstreamId;

    if (needsMixingNode) {
      if (!nodes.some((n) => n.id === 'mixing_node')) {
        pushNode('mixing_node', 'mixing_node', 'Насосно-змішувальний вузол');
      }
      edges.push({
        id: 'e_main_to_mixing',
        from: upstreamId,
        to: 'mixing_node',
        lengthM: dto.rules.defaultLengthsM.ufhCollectorBranch,
        fluid: 'heating',
        designFlowM3PerHour: flowCtx.mixingNodePrimaryBleedM3PerHour,
        supplyC: dto.source.supplyC,
        returnC: dto.source.returnC,
        segmentRole: 'main',
        isMainLine: true,
      });
      ufhUpstreamId = 'mixing_node';
    }

    const transitByFloor = new Map(
      (dto.layout.ufhCollectorTransit ?? []).map((t) => [t.floor, t.transitLengthM]),
    );

    /** @type {Map<number, import('./types.js').HydraulicsUfhRoom[]>} */
    const roomsByFloor = new Map();
    for (const room of ufh.rooms) {
      const floor = room.floor ?? 1;
      const list = roomsByFloor.get(floor) ?? [];
      list.push(room);
      roomsByFloor.set(floor, list);
    }

    for (const floor of [...roomsByFloor.keys()].sort((a, b) => a - b)) {
      const floorRooms = roomsByFloor.get(floor) ?? [];
      const collectorRooms = floorRooms.filter(
        (r) => r.ufhTerminalControl !== 'unibox',
      );
      const uniboxRooms = floorRooms.filter(
        (r) => r.ufhTerminalControl === 'unibox',
      );

      if (collectorRooms.length > 0) {
        const collectorId = ufhCollectorNodeId(floor);
        if (!nodes.some((n) => n.id === collectorId)) {
          pushNode(collectorId, 'ufh_collector', `Колектор ТП, поверх ${floor}`, {
            floor,
          });
        }

        const floorFlow = round(
          collectorRooms.reduce((s, r) => s + (r.flowRateM3PerHour ?? 0), 0),
          3,
        );
        const transitLengthM =
          transitByFloor.get(floor)
          ?? dto.rules.defaultLengthsM.ufhCollectorBranch;

        const firstRoom = collectorRooms[0];
        edges.push({
          id: `e_${ufhUpstreamId}_to_${collectorId}`,
          from: ufhUpstreamId,
          to: collectorId,
          lengthM: transitLengthM,
          fluid: 'heating',
          designFlowM3PerHour: floorFlow,
          ...(firstRoom?.circuitSupplyC !== undefined
            ? { supplyC: firstRoom.circuitSupplyC }
            : {}),
          ...(firstRoom?.circuitReturnC !== undefined
            ? { returnC: firstRoom.circuitReturnC }
            : {}),
          segmentRole: 'ufh_collector_transit',
        });

        for (const room of collectorRooms) {
          const loops = resolveRoomLoopsForGraph(room);
          for (const loop of loops) {
            const loopNodeId = `ufh_loop_${loop.loopId}`;
            pushNode(loopNodeId, 'ufh_loop', `${room.roomName} — ${loop.loopId}`, {
              roomId: room.roomId,
              loopId: loop.loopId,
            });
            edges.push({
              id: `e_${collectorId}_to_${loop.loopId}`,
              from: collectorId,
              to: loopNodeId,
              lengthM: loop.loopLengthM,
              fluid: 'heating',
              designFlowM3PerHour: loop.flowRateM3PerHour,
              supplyC: room.circuitSupplyC,
              returnC: room.circuitReturnC,
              segmentRole: 'ufh_loop',
              ...(loop.catalogPipeId
                ? { preferredCatalogPipeId: loop.catalogPipeId }
                : {}),
            });
          }
        }
      }

      for (const room of uniboxRooms) {
        const loops = resolveRoomLoopsForGraph(room);
        for (const loop of loops) {
          const loopNodeId = `ufh_loop_${loop.loopId}`;
          pushNode(loopNodeId, 'ufh_loop', `${room.roomName} — ${loop.loopId}`, {
            roomId: room.roomId,
            loopId: loop.loopId,
          });
          edges.push({
            id: `e_${ufhUpstreamId}_to_${loop.loopId}`,
            from: ufhUpstreamId,
            to: loopNodeId,
            lengthM: loop.loopLengthM,
            fluid: 'heating',
            designFlowM3PerHour: loop.flowRateM3PerHour,
            supplyC: room.circuitSupplyC,
            returnC: room.circuitReturnC,
            segmentRole: 'ufh_loop',
            ...(loop.catalogPipeId
              ? { preferredCatalogPipeId: loop.catalogPipeId }
              : {}),
          });
        }
      }
    }
  }

  const dhw = dto.circuits.dhw;
  if (dhw && dhw.peakFlowLps > 0 && dhw.scenario === 'flowThrough') {
    pushNode('dhw_load', 'dhw_load', 'Пікове навантаження ГВП');
    const flowM3h = (dhw.peakFlowLps * 3600) / 1000;
    edges.push({
      id: 'e_boiler_dhw',
      from: 'boiler',
      to: 'dhw_load',
      lengthM: dto.rules.defaultLengthsM.radiatorBranch,
      fluid: 'water',
      designFlowM3PerHour: Math.round(flowM3h * 1000) / 1000,
      segmentRole: 'dhw',
    });
  }

  if (
    dhw?.indirectTank
    && dhw.hotWaterPowerKw > 0
    && dhw.scenario === 'storage'
  ) {
    const coilNodeId = 'indirect_coil';
    pushNode(coilNodeId, 'indirect_coil', 'Змійовик БКН');
    const coilFlow = thermalLoadToFlow({
      heatLoadWatts: dhw.hotWaterPowerKw * 1000,
      deltaTK: dto.source.deltaTK,
    });
    edges.push({
      id: 'e_boiler_indirect_coil',
      from: upstreamId,
      to: coilNodeId,
      lengthM: dto.rules.defaultLengthsM.radiatorBranch * 2,
      fluid: 'heating',
      designFlowM3PerHour: coilFlow.flowRateM3PerHour,
      supplyC: dto.source.supplyC,
      returnC: dto.source.returnC,
      segmentRole: 'branch',
    });
  }

  return { nodes, edges };
}

/**
 * Назначение: продуктовое предложение по гидравлике для клиента.
 * Описание: Обогащает matching.hydraulics данными каталога (brand, model, price).
 */

import { round } from '../utils/math.js';

/** @type {Record<string, string>} */
const SEGMENT_ROLE_LABELS = {
  main: 'Магістраль',
  trunk: 'Магістраль (послідовна)',
  branch: 'Гілка радіатора',
  ufh_collector_transit: 'Транзит колектора ТП',
  ufh_loop: 'Петля ТП',
  dhw: 'ГВП',
};

/** @type {string} */
const MAIN_TRANSIT_ROLE_LABEL = 'Транзит котла';

/**
 * @param {import('./types.js').HydraulicsGraphEdge} edge
 * @param {Map<string, import('./types.js').HydraulicsGraphNode>} nodesById
 * @returns {string}
 */
function edgeSegmentLabel(edge, nodesById) {
  const from = nodesById.get(edge.from)?.label ?? edge.from;
  const to = nodesById.get(edge.to)?.label ?? edge.to;
  const role = edge.isMainLine === true
    ? MAIN_TRANSIT_ROLE_LABEL
    : (SEGMENT_ROLE_LABELS[edge.segmentRole] ?? edge.segmentRole);
  return `${role}: ${from} → ${to}`;
}

/**
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} pipes
 * @param {string} catalogPipeId
 * @returns {import('../catalog/types.js').PipeCatalogItemNormalized | null}
 */
function findPipeInCatalog(pipes, catalogPipeId) {
  if (!pipes?.length || !catalogPipeId) return null;
  return pipes.find((p) => p.id === catalogPipeId) ?? null;
}

/**
 * @param {import('../catalog/types.js').NormalizedCatalog['pumps']} pumps
 * @param {string} catalogPumpId
 * @returns {import('../catalog/types.js').PumpCatalogItemNormalized | null}
 */
function findPumpInCatalog(pumps, catalogPumpId) {
  if (!pumps?.length || !catalogPumpId) return null;
  return pumps.find((p) => p.id === catalogPumpId) ?? null;
}

/**
 * @param {import('../catalog/types.js').NormalizedCatalog['boilers']} boilers
 * @param {string | undefined} catalogBoilerId
 * @returns {import('../catalog/types.js').BoilerCatalogItemNormalized | null}
 */
function findBoilerInCatalog(boilers, catalogBoilerId) {
  if (!catalogBoilerId || !boilers) return null;
  const all = [
    ...(boilers.doubleCircuit ?? []),
    ...(boilers.singleCircuit ?? []),
  ];
  return all.find((b) => {
    const id = /** @type {{ id?: string }} */ (b).id;
    return id === catalogBoilerId || b.model === catalogBoilerId;
  }) ?? null;
}

/**
 * @param {import('./types.js').HydraulicsPipeSegmentProposal[]} segments
 * @returns {import('./types.js').HydraulicsPipeProposalLine[]}
 */
function aggregatePipeLinesFromSegments(segments) {
  /** @type {Map<string, import('./types.js').HydraulicsPipeProposalLine>} */
  const aggregated = new Map();

  for (const seg of segments) {
    const prev = aggregated.get(seg.catalogPipeId);
    if (prev) {
      prev.totalLengthM = round(prev.totalLengthM + seg.lengthM, 2);
      prev.edgeCount += 1;
      prev.linePrice = round(prev.linePrice + seg.linePrice, 2);
    } else {
      aggregated.set(seg.catalogPipeId, {
        catalogPipeId: seg.catalogPipeId,
        brand: seg.brand,
        model: seg.model,
        material: seg.material,
        outerDiameterMm: seg.outerDiameterMm,
        wallThicknessMm: seg.wallThicknessMm,
        internalDiameterMm: seg.internalDiameterMm,
        totalLengthM: seg.lengthM,
        edgeCount: 1,
        pricePerMeter: seg.pricePerMeter,
        linePrice: seg.linePrice,
      });
    }
  }

  return [...aggregated.values()].sort((a, b) => b.totalLengthM - a.totalLengthM);
}

/**
 * @param {import('./types.js').HydraulicsPipeSegmentProposal[]} segments
 * @param {Set<string>} roles
 * @returns {import('./types.js').HydraulicsPipeProposalLine[]}
 */
function pipeLinesForRoles(segments, roles) {
  return aggregatePipeLinesFromSegments(
    segments.filter((seg) => roles.has(seg.segmentRole)),
  );
}

/**
 * @param {import('./types.js').HydraulicsResolvedPump} resolved
 * @param {import('../catalog/types.js').NormalizedCatalog} catalog
 * @returns {import('./types.js').HydraulicsPumpProposal}
 */
function buildPumpProposal(resolved, catalog) {
  if (resolved.pumpSource === 'boiler_builtin') {
    const boiler = findBoilerInCatalog(catalog.boilers, resolved.catalogBoilerId);
    return {
      zoneId: resolved.zoneId,
      zoneLabel: resolved.zoneLabel,
      pumpRole: resolved.pumpRole,
      pumpSource: 'boiler_builtin',
      ...(resolved.catalogBoilerId ? { catalogBoilerId: resolved.catalogBoilerId } : {}),
      brand: boiler?.model?.split(' ')[0] ?? 'Котел',
      model: boiler?.model ?? 'Вбудований насос',
      price: 0,
      modeName: resolved.modeName,
      headAtDesignM: resolved.headAtDesignM,
      headRequiredM: resolved.headRequiredM,
      designFlowM3PerHour: resolved.designFlowM3PerHour,
      headMarginPercent: resolved.headMarginPercent,
      note: resolved.note ?? 'Використовується вбудований насос котла.',
    };
  }

  const catalogPump = findPumpInCatalog(catalog.pumps, resolved.catalogPumpId ?? '');
  return {
    zoneId: resolved.zoneId,
    zoneLabel: resolved.zoneLabel,
    pumpRole: resolved.pumpRole,
    pumpSource: 'catalog',
    catalogPumpId: resolved.catalogPumpId ?? '',
    brand: catalogPump?.brand ?? '',
    model: catalogPump?.model ?? resolved.catalogPumpId ?? '',
    ...(catalogPump?.segment !== undefined ? { segment: catalogPump.segment } : {}),
    price: catalogPump?.price ?? 0,
    modeName: resolved.modeName,
    headAtDesignM: resolved.headAtDesignM,
    headRequiredM: resolved.headRequiredM,
    designFlowM3PerHour: resolved.designFlowM3PerHour,
    headMarginPercent: resolved.headMarginPercent,
    ...(catalogPump?.connections?.nominalDiameterMm !== undefined
      ? { connectionNominalMm: catalogPump.connections.nominalDiameterMm }
      : {}),
    ...(resolved.note ? { note: resolved.note } : {}),
  };
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsMatchingReport} args.matching
 * @param {import('./types.js').HydraulicsGraph} args.graph
 * @param {import('./types.js').HydraulicsPressureReport} args.pressure
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @param {import('./types.js').HydraulicsSystemPumpsResult} [args.pumpResult]
 * @returns {import('./types.js').HydraulicsProposalReport}
 */
export function buildHydraulicsProposal({
  matching,
  graph,
  pressure,
  catalog,
  pumpResult,
}) {
  /** @type {Map<string, import('./types.js').HydraulicsGraphNode>} */
  const nodesById = new Map(graph.nodes.map((n) => [n.id, n]));
  /** @type {Map<string, import('./types.js').HydraulicsGraphEdge>} */
  const edgesById = new Map(graph.edges.map((e) => [e.id, e]));

  /** @type {import('./types.js').HydraulicsPipeSegmentProposal[]} */
  const pipeSegments = [];

  for (const pipeMatch of matching.pipes ?? []) {
    const edge = edgesById.get(pipeMatch.edgeId);
    const catalogPipe = findPipeInCatalog(catalog.pipes, pipeMatch.catalogPipeId);
    const lengthM = edge?.lengthM ?? 0;
    const pricePerMeter = catalogPipe?.price ?? 0;
    const linePrice = round(lengthM * pricePerMeter, 2);

    if (pipeMatch.catalogPoolExhausted) {
      continue;
    }

    pipeSegments.push({
      edgeId: pipeMatch.edgeId,
      segmentLabel: edge ? edgeSegmentLabel(edge, nodesById) : pipeMatch.edgeId,
      segmentRole: edge?.segmentRole ?? 'main',
      lengthM,
      catalogPipeId: pipeMatch.catalogPipeId,
      brand: catalogPipe?.brand ?? '',
      model: catalogPipe?.model ?? pipeMatch.catalogPipeId,
      material: catalogPipe?.material ?? '',
      outerDiameterMm: catalogPipe?.diameter ?? 0,
      wallThicknessMm: catalogPipe?.wallThickness ?? 0,
      internalDiameterMm: pipeMatch.internalDiameterMm,
      velocityMps: pipeMatch.velocityMps,
      pressureDropKPa: pipeMatch.pressureDropKPa,
      pricePerMeter,
      linePrice,
      ...(pipeMatch.velocityLimitExceeded
        ? { velocityLimitExceeded: true }
        : {}),
      ...(pipeMatch.velocityBelowMin ? { velocityBelowMin: true } : {}),
      ...(edge?.isMainLine === true ? { isMainLine: true } : {}),
      ...(pipeMatch.mainTransitGuardApplied
        ? { mainTransitGuardApplied: true }
        : {}),
      ...(pipeMatch.catalogPoolExhausted
        ? { catalogPoolExhausted: true }
        : {}),
      ...(edge?.to
        ? (() => {
          const toNode = nodesById.get(edge.to);
          return toNode?.roomIds?.length
            ? { groupedRoomIds: [...toNode.roomIds] }
            : {};
        })()
        : {}),
    });
  }

  const pipeLines = aggregatePipeLinesFromSegments(pipeSegments);

  const heatingRoles = new Set(['main', 'branch']);
  const ufhRoles = new Set(['ufh_collector_transit', 'ufh_loop']);

  /** @type {import('./types.js').HydraulicsPipeLineGroup[]} */
  const pipeLineGroups = [];

  const heatingLines = pipeLinesForRoles(pipeSegments, heatingRoles);
  if (heatingLines.length > 0) {
    pipeLineGroups.push({
      circuitId: 'heating',
      label: 'Контур опалення (радіатори)',
      pipeLines: heatingLines,
      estimatedPrice: round(heatingLines.reduce((s, l) => s + l.linePrice, 0), 2),
    });
  }

  const ufhLines = pipeLinesForRoles(pipeSegments, ufhRoles);
  if (ufhLines.length > 0) {
    pipeLineGroups.push({
      circuitId: 'ufh',
      label: 'Контур теплої підлоги',
      pipeLines: ufhLines,
      estimatedPrice: round(ufhLines.reduce((s, l) => s + l.linePrice, 0), 2),
    });
  }

  const estimatedPipesPrice = round(
    pipeLines.reduce((s, l) => s + l.linePrice, 0),
    2,
  );

  const resolvedPumps = pumpResult?.pumps ?? [];
  /** @type {import('./types.js').HydraulicsPumpProposal[]} */
  const pumpProposals = resolvedPumps.map((p) => buildPumpProposal(p, catalog));
  const estimatedPumpPrice = round(
    pumpProposals.reduce((s, p) => s + (p.price ?? 0), 0),
    2,
  );
  const mainPumpProposal =
    pumpProposals.find((p) => p.zoneId === 'boiler_primary') ?? pumpProposals[0];

  const designFlowM3PerHour =
    pumpResult?.boilerPumpDesignFlowM3PerHour
    ?? matching.pump?.designFlowM3PerHour
    ?? pipeSegments.reduce((max, s) => {
      const edge = edgesById.get(s.edgeId);
      return Math.max(max, edge?.designFlowM3PerHour ?? 0);
    }, 0);

  const headRequiredM = pressure.headRequiredM ?? matching.pump?.headRequiredM ?? 0;

  /** @type {string | undefined} */
  let unavailableReason;
  /** @type {string | undefined} */
  let pumpUnavailableReason;
  const hasAnyPump = pumpProposals.length > 0;
  const hasPipes = pipeSegments.length > 0;

  if (!hasPipes && !hasAnyPump) {
    unavailableReason = 'Не вдалося підібрати труби та насос з каталогу.';
  } else if (!hasPipes) {
    unavailableReason = 'Труби з каталогу не підібрано — перевірте каталог pipes.';
  } else if (!hasAnyPump) {
    if (matching.builtinPumpDuty?.status === 'below_manufacturer_qmin') {
      pumpUnavailableReason =
        `Вбудований насос котла враховано: витрата ${matching.builtinPumpDuty.designFlowM3PerHour} м³/год `
        + `нижче заводського q_min=${matching.builtinPumpDuty.heatingCircuitMinFlowM3h} м³/год — `
        + 'окремий насос з каталогу не підбирається.';
    } else {
      pumpUnavailableReason =
        'Насос з каталогу не підібрано для розрахункової робочої точки — див. попередження.';
    }
  }

  return {
    designFlowM3PerHour: round(designFlowM3PerHour, 3),
    headRequiredM: round(headRequiredM, 2),
    ...(matching.topology ? { topology: matching.topology } : {}),
    ...(matching.circulationZones?.length
      ? { circulationZones: matching.circulationZones }
      : {}),
    pipeLines,
    ...(pipeLineGroups.length ? { pipeLineGroups } : {}),
    pipeSegments,
    ...(mainPumpProposal ? { pump: mainPumpProposal } : {}),
    ...(pumpProposals.length ? { pumps: pumpProposals } : {}),
    estimatedPipesPrice,
    estimatedPumpPrice,
    estimatedTotalPrice: round(estimatedPipesPrice + estimatedPumpPrice, 2),
    ...(unavailableReason ? { unavailableReason } : {}),
    ...(pumpUnavailableReason ? { pumpUnavailableReason } : {}),
  };
}

/**
 * Назначение: фабрика топологий радиаторного подграфа.
 * Описание: auto (звезда), dead-end, pass-through, manifold — по layout.radiatorWiringSystemType.
 */

import {
  buildMicroManifoldLabel,
  partitionRadiatorConsumersForGraph,
  RAD_MICRO_MANIFOLD_NODE_ID,
  resolveMicroManifoldEdgeLength,
  sumMicroConsumersFlowM3h,
} from './groupRadiatorGraphBranches.js';
import {
  orderRadiatorConsumers,
  RAD_DISTRIBUTION_MANIFOLD_NODE_ID,
  radiatorConsumerNodeId,
  radiatorThermalRegime,
  radiatorTrunkJunctionNodeId,
  resolveBranchLengthM,
  splitMainLineIntoTrunkSegments,
  sumConsumerFlowsFromIndex,
} from './radiatorGraphHelpers.js';

/**
 * @typedef {object} RadiatorSubgraphContext
 * @property {string} upstreamId
 * @property {import('./types.js').HydraulicsPipelineInput} dto
 * @property {(id: string, kind: import('./types.js').HydraulicsNodeKind, label: string, extra?: object) => void} pushNode
 * @property {(edge: import('./types.js').HydraulicsGraphEdge) => void} pushEdge
 */

/**
 * @param {RadiatorSubgraphContext} ctx
 */
function buildStarRadiatorGraph(ctx) {
  const rad = ctx.dto.circuits.radiators;
  if (!rad?.consumers?.length) return;

  const upstreamId = ctx.upstreamId;
  const { individual, microConsumers } = partitionRadiatorConsumersForGraph({
    consumers: rad.consumers,
    grouping: ctx.dto.rules.radiatorBranchGrouping,
  });

  for (const consumer of individual) {
    const nodeId = radiatorConsumerNodeId(consumer.roomId);
    ctx.pushNode(nodeId, 'radiator_consumer', consumer.roomName, {
      roomId: consumer.roomId,
    });
    const thermal = radiatorThermalRegime(rad);
    const branch = ctx.dto.layout.radiatorBranches.find(
      (b) => b.roomId === consumer.roomId,
    );
    ctx.pushEdge({
      id: `e_${upstreamId}_to_${nodeId}`,
      from: upstreamId,
      to: nodeId,
      lengthM: branch?.pipeLengthToEquipmentM ?? ctx.dto.rules.defaultLengthsM.radiatorBranch,
      fluid: 'heating',
      designFlowM3PerHour: consumer.flowRateM3PerHour,
      supplyC: thermal.supplyC,
      returnC: thermal.returnC,
      segmentRole: 'branch',
    });
  }

  if (microConsumers.length > 0) {
    const roomIds = microConsumers.map((c) => c.roomId);
    ctx.pushNode(
      RAD_MICRO_MANIFOLD_NODE_ID,
      'radiator_manifold',
      buildMicroManifoldLabel(microConsumers),
      { roomIds },
    );
    const thermal = radiatorThermalRegime(rad);
    ctx.pushEdge({
      id: `e_${upstreamId}_to_${RAD_MICRO_MANIFOLD_NODE_ID}`,
      from: upstreamId,
      to: RAD_MICRO_MANIFOLD_NODE_ID,
      lengthM: resolveMicroManifoldEdgeLength({
        microConsumers,
        branches: ctx.dto.layout.radiatorBranches,
        defaultBranchLengthM: ctx.dto.rules.defaultLengthsM.radiatorBranch,
        manifoldTrunkLengthM: ctx.dto.rules.radiatorBranchGrouping.manifoldTrunkLengthM,
      }),
      fluid: 'heating',
      designFlowM3PerHour: sumMicroConsumersFlowM3h(microConsumers),
      supplyC: thermal.supplyC,
      returnC: thermal.returnC,
      segmentRole: 'branch',
    });
  }
}

/**
 * @param {RadiatorSubgraphContext} ctx
 * @param {'dead_end' | 'pass_through'} mode
 */
function buildSequentialRadiatorGraph(ctx, mode) {
  const rad = ctx.dto.circuits.radiators;
  if (!rad?.consumers?.length) return;

  const consumers = orderRadiatorConsumers(ctx.dto).filter(
    (c) => c.heatLoadWatts > 0 && c.flowRateM3PerHour > 0,
  );
  if (!consumers.length) return;

  const thermal = radiatorThermalRegime(rad);
  const totalFlow = rad.totalFlowRateM3PerHour;
  const trunkLen = splitMainLineIntoTrunkSegments(
    ctx.dto.layout.mainLineLengthM,
    Math.max(consumers.length - 1, 1),
  );

  if (consumers.length === 1) {
    const consumer = consumers[0];
    if (!consumer) return;
    const nodeId = radiatorConsumerNodeId(consumer.roomId);
    ctx.pushNode(nodeId, 'radiator_consumer', consumer.roomName, {
      roomId: consumer.roomId,
    });
    ctx.pushEdge({
      id: `e_${ctx.upstreamId}_to_${nodeId}`,
      from: ctx.upstreamId,
      to: nodeId,
      lengthM: resolveBranchLengthM(consumer.roomId, ctx.dto),
      fluid: 'heating',
      designFlowM3PerHour: consumer.flowRateM3PerHour,
      supplyC: thermal.supplyC,
      returnC: thermal.returnC,
      segmentRole: 'branch',
      teeRole: 'branch_takeoff',
    });
    return;
  }

  for (let i = 0; i < consumers.length; i += 1) {
    const junctionId = radiatorTrunkJunctionNodeId(i);
    ctx.pushNode(junctionId, 'radiator_trunk_junction', `Тройник ${i + 1}`, {});

    const consumer = consumers[i];
    if (!consumer) continue;
    const radNodeId = radiatorConsumerNodeId(consumer.roomId);
    ctx.pushNode(radNodeId, 'radiator_consumer', consumer.roomName, {
      roomId: consumer.roomId,
    });

    const fromId = i === 0 ? ctx.upstreamId : radiatorTrunkJunctionNodeId(i - 1);
    if (i === 0) {
      ctx.pushEdge({
        id: `e_${fromId}_to_${junctionId}`,
        from: fromId,
        to: junctionId,
        lengthM: 0,
        fluid: 'heating',
        designFlowM3PerHour:
          mode === 'pass_through'
            ? totalFlow
            : sumConsumerFlowsFromIndex(consumers, 0),
        supplyC: thermal.supplyC,
        returnC: thermal.returnC,
        segmentRole: 'branch',
      });
    }

    ctx.pushEdge({
      id: `e_${junctionId}_to_${radNodeId}`,
      from: junctionId,
      to: radNodeId,
      lengthM: resolveBranchLengthM(consumer.roomId, ctx.dto),
      fluid: 'heating',
      designFlowM3PerHour: consumer.flowRateM3PerHour,
      supplyC: thermal.supplyC,
      returnC: thermal.returnC,
      segmentRole: 'branch',
      teeRole: 'branch_takeoff',
    });

    if (i < consumers.length - 1) {
      const nextJunctionId = radiatorTrunkJunctionNodeId(i + 1);
      const trunkFlow =
        mode === 'pass_through'
          ? totalFlow
          : sumConsumerFlowsFromIndex(consumers, i + 1);
      ctx.pushEdge({
        id: `e_${junctionId}_to_${nextJunctionId}`,
        from: junctionId,
        to: nextJunctionId,
        lengthM: trunkLen,
        fluid: 'heating',
        designFlowM3PerHour: trunkFlow,
        supplyC: thermal.supplyC,
        returnC: thermal.returnC,
        segmentRole: 'trunk',
        teeRole: 'pass_through',
      });
    }
  }
}

/**
 * @param {RadiatorSubgraphContext} ctx
 */
function buildDeadEndRadiatorGraph(ctx) {
  buildSequentialRadiatorGraph(ctx, 'dead_end');
}

/**
 * @param {RadiatorSubgraphContext} ctx
 */
function buildPassThroughRadiatorGraph(ctx) {
  buildSequentialRadiatorGraph(ctx, 'pass_through');
}

/**
 * @param {RadiatorSubgraphContext} ctx
 */
function buildManifoldRadiatorGraph(ctx) {
  const rad = ctx.dto.circuits.radiators;
  if (!rad?.consumers?.length) return;

  const consumers = orderRadiatorConsumers(ctx.dto).filter(
    (c) => c.heatLoadWatts > 0 && c.flowRateM3PerHour > 0,
  );
  if (!consumers.length) return;

  const thermal = radiatorThermalRegime(rad);
  const upstreamId = ctx.upstreamId;

  ctx.pushNode(
    RAD_DISTRIBUTION_MANIFOLD_NODE_ID,
    'radiator_distribution_manifold',
    'Колектор радіаторів',
    { roomIds: consumers.map((c) => c.roomId) },
  );

  ctx.pushEdge({
    id: `e_${upstreamId}_to_${RAD_DISTRIBUTION_MANIFOLD_NODE_ID}`,
    from: upstreamId,
    to: RAD_DISTRIBUTION_MANIFOLD_NODE_ID,
    lengthM: ctx.dto.rules.radiatorBranchGrouping.manifoldTrunkLengthM,
    fluid: 'heating',
    designFlowM3PerHour: rad.totalFlowRateM3PerHour,
    supplyC: thermal.supplyC,
    returnC: thermal.returnC,
    segmentRole: 'branch',
  });

  for (const consumer of consumers) {
    const nodeId = radiatorConsumerNodeId(consumer.roomId);
    ctx.pushNode(nodeId, 'radiator_consumer', consumer.roomName, {
      roomId: consumer.roomId,
    });
    ctx.pushEdge({
      id: `e_${RAD_DISTRIBUTION_MANIFOLD_NODE_ID}_to_${nodeId}`,
      from: RAD_DISTRIBUTION_MANIFOLD_NODE_ID,
      to: nodeId,
      lengthM: resolveBranchLengthM(consumer.roomId, ctx.dto),
      fluid: 'heating',
      designFlowM3PerHour: consumer.flowRateM3PerHour,
      supplyC: thermal.supplyC,
      returnC: thermal.returnC,
      segmentRole: 'branch',
    });
  }
}

/**
 * @param {RadiatorSubgraphContext} ctx
 */
export function buildRadiatorSubgraph(ctx) {
  const wiring = ctx.dto.layout.radiatorWiringSystemType ?? 'auto';
  switch (wiring) {
    case 'two-pipe-dead-end':
      buildDeadEndRadiatorGraph(ctx);
      break;
    case 'two-pipe-pass':
      buildPassThroughRadiatorGraph(ctx);
      break;
    case 'manifold':
      buildManifoldRadiatorGraph(ctx);
      break;
    default:
      buildStarRadiatorGraph(ctx);
  }
}

/**
 * Назначение: сборка HydraulicsPipelineInput из блоков отчёта после matchEquipment.
 * Описание: Pure Pipeline не пересчитывает тепло — только агрегирует готовые поля upstream.
 */

import { SCHEME_BOILER_MAX_COMBI } from '../../../shared/heatingMatchingSchemes.js';
import { parseConnectionDiametersMm } from './parseConnectionDiameter.js';
import {
  estimateBranchLengthM,
  hydraulicsRulesFromAppliance,
  resolvePipelineEmittersMode,
} from './resolveEmittersMode.js';
import { round } from '../utils/math.js';
import { resolveFlowDeltaTK } from './resolveFlowDeltaTK.js';

/**
 * @param {import('./types.js').HydraulicsUfhLoop & { hydraulics?: unknown }} loop
 * @returns {import('./types.js').HydraulicsUfhLoop}
 */
function toPipelineUfhLoop(loop) {
  const hydraulics = loop.hydraulics;
  const catalogPipeId =
    typeof hydraulics === 'object'
    && hydraulics !== null
    && typeof /** @type {{ catalogPipeId?: string }} */ (hydraulics).catalogPipeId === 'string'
      ? /** @type {{ catalogPipeId: string }} */ (hydraulics).catalogPipeId
      : loop.catalogPipeId;

  return {
    loopId: loop.loopId,
    loopLengthM: loop.loopLengthM,
    heatLoadWatts: loop.heatLoadWatts,
    flowRateM3PerHour: loop.flowRateM3PerHour,
    ...(catalogPipeId ? { catalogPipeId } : {}),
  };
}

/**
 * @param {import('../types/shared-types.js').BuildingInput | undefined | null} building
 * @returns {Map<string, number>}
 */
function roomFloorById(building) {
  /** @type {Map<string, number>} */
  const map = new Map();
  for (const room of building?.rooms ?? []) {
    if (room?.id) map.set(room.id, Number(room.floor) || 1);
  }
  return map;
}

/**
 * @param {import('../types/shared-types.js').HydraulicsSurveyInput | undefined | null} hydraulics
 * @returns {Map<string, number>}
 */
function radiatorBranchOverrideByRoomId(hydraulics) {
  /** @type {Map<string, number>} */
  const map = new Map();
  for (const item of hydraulics?.radiatorBranchOverrides ?? []) {
    if (
      item?.roomId
      && typeof item.pipeLengthToEquipmentM === 'number'
      && item.pipeLengthToEquipmentM >= 0
    ) {
      map.set(item.roomId, item.pipeLengthToEquipmentM);
    }
  }
  return map;
}

/**
 * @param {import('./types.js').HydraulicsRadiatorConsumer[]} consumers
 * @param {import('../types/shared-types.js').HydraulicsRadiatorBranchOverride[] | undefined} overrides
 * @param {Map<string, number>} radiatorOverrides
 * @param {number} defaultBranchLengthM
 * @returns {import('./types.js').HydraulicsRadiatorBranchLayout[]}
 */
function buildOrderedRadiatorBranches(consumers, overrides, radiatorOverrides, defaultBranchLengthM) {
  /** @type {Map<string, number>} */
  const orderIndex = new Map();
  const overrideList = overrides ?? [];
  for (let i = 0; i < overrideList.length; i += 1) {
    const item = overrideList[i];
    if (item?.roomId) orderIndex.set(item.roomId, i);
  }

  const sorted = [...consumers].sort((a, b) => {
    const ai = orderIndex.get(a.roomId);
    const bi = orderIndex.get(b.roomId);
    if (ai != null && bi != null) return ai - bi;
    if (ai != null) return -1;
    if (bi != null) return 1;
    return a.floor - b.floor || a.roomId.localeCompare(b.roomId);
  });

  return sorted.map((c) => ({
    roomId: c.roomId,
    pipeLengthToEquipmentM:
      radiatorOverrides.get(c.roomId)
      ?? estimateBranchLengthM(c.floor, defaultBranchLengthM),
  }));
}

/**
 * @param {string | undefined} raw
 * @returns {import('./types.js').RadiatorWiringSystemType}
 */
function resolveRadiatorWiringSystemType(raw) {
  const allowed = new Set([
    'auto',
    'two-pipe-dead-end',
    'two-pipe-pass',
    'manifold',
  ]);
  if (raw && allowed.has(raw)) {
    return /** @type {import('./types.js').RadiatorWiringSystemType} */ (raw);
  }
  return 'auto';
}

/**
 * @param {object} args
 * @param {import('../types/shared-types.js').CalcRequestBody} args.input
 * @param {import('../types/shared-types.js').HotWaterReport} args.hotWater
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} args.underfloorHeating
 * @param {import('../types/shared-types.js').MatchingReport} args.matching
 * @param {import('./types.js').HydraulicsApplianceRules} args.hydraulicsRules
 * @returns {import('./types.js').HydraulicsPipelineInput}
 */
export function buildHydraulicsSnapshots({
  input,
  hotWater,
  underfloorHeating,
  matching,
  hydraulicsRules,
}) {
  const rules = hydraulicsRulesFromAppliance(hydraulicsRules);
  const heatingSystem = input.heatingSystem ?? {};
  const objectTypeRaw = input.building?.objectMeta?.objectType;
  const objectType =
    objectTypeRaw === 'apartment' || objectTypeRaw === 'house' ? objectTypeRaw : 'house';

  const emittersMode = resolvePipelineEmittersMode(heatingSystem, underfloorHeating);
  const dhwMatchingScheme =
    heatingSystem.hotWaterBoilerPowerMatchingScheme ?? SCHEME_BOILER_MAX_COMBI;

  const supplyC = Number(heatingSystem.supplyC) || 75;
  const returnC = Number(heatingSystem.returnC) || 65;
  const deltaTFromSurvey = input.hydraulics?.deltaTSystemK;
  const deltaTK = resolveFlowDeltaTK({
    deltaTSystemK: deltaTFromSurvey,
    supplyC,
    returnC,
  });

  const selected = matching.boiler?.selected ?? matching.boiler?.proposal;
  const connectionNominalMm = parseConnectionDiametersMm(
    selected?.connectionDiameters ?? [],
  );

  /** @type {import('./types.js').HydraulicsSourceNode} */
  const source = {
    ...(selected?.id || selected?.model
      ? { catalogBoilerId: selected.id ?? selected.model }
      : {}),
    supplyC,
    returnC,
    deltaTK,
    requiredKw: matching.boiler?.requiredKw ?? 0,
    connectionNominalMm,
    ...(selected?.mountingType !== undefined
      ? { mountingType: selected.mountingType }
      : {}),
  };

  /** @type {import('./types.js').HydraulicsCircuits} */
  const circuits = {};

  const floors = roomFloorById(input.building);
  const radiatorOverrides = radiatorBranchOverrideByRoomId(input.hydraulics);

  if (emittersMode !== 'ufh_only' && matching.radiators?.byRoom?.length) {
    const radInputs = matching.radiators.inputs;
    const radSupply = radInputs?.supplyC ?? supplyC;
    const radReturn = radInputs?.returnC ?? returnC;
    const radGraphDeltaTK = Math.max(0.1, radSupply - radReturn);
    const radFlowDeltaTK =
      matching.radiators.inputs?.flowDeltaTK
      ?? resolveFlowDeltaTK({
        deltaTSystemK: deltaTFromSurvey,
        supplyC: radSupply,
        returnC: radReturn,
      });

    /** @type {import('./types.js').HydraulicsRadiatorConsumer[]} */
    const consumers = matching.radiators.byRoom
      .filter((r) => (r.radiatorDesignWatts ?? 0) > 0)
      .map((r) => ({
        roomId: r.roomId,
        roomName: r.roomName,
        floor: floors.get(r.roomId) ?? 1,
        heatLoadWatts: r.radiatorDesignWatts,
        flowRateM3PerHour: r.flowRateM3PerHour ?? 0,
      }));

    const totalFlow = round(
      consumers.reduce((s, c) => s + c.flowRateM3PerHour, 0),
      3,
    );

    circuits.radiators = {
      thermalRegime: {
        supplyC: radSupply,
        returnC: radReturn,
        deltaTK: radGraphDeltaTK,
      },
      flowDeltaTK: radFlowDeltaTK,
      connectionType: radInputs?.radiatorConnection === 'bottom' ? 'bottom' : 'side',
      consumers,
      totalFlowRateM3PerHour: totalFlow,
    };
  }

  if (
    (emittersMode === 'ufh_only' || emittersMode === 'mixed')
    && underfloorHeating?.rooms?.length
  ) {
    /** @type {import('./types.js').HydraulicsUfhRoom[]} */
    const ufhRooms = underfloorHeating.rooms.map((room) => ({
      roomId: room.roomId,
      roomName: room.roomName,
      floor: floors.get(room.roomId) ?? 1,
      areaM2: room.heatedAreaM2 ?? room.areaM2,
      pipeSpacingMm: room.pipeSpacingMm,
      circuitSupplyC: room.circuitSupplyC,
      circuitReturnC: room.circuitReturnC,
      heatLoadWatts: room.heatLoadWatts ?? room.heatFluxUpWatts,
      flowRateM3PerHour: room.flowRateM3PerHour ?? 0,
      ...(room.loopsCount != null ? { loopsCount: room.loopsCount } : {}),
      ...(room.loops?.length
        ? { loops: room.loops.map(toPipelineUfhLoop) }
        : {}),
      ...(room.ufhTerminalControl === 'unibox'
        ? { ufhTerminalControl: /** @type {const} */ ('unibox') }
        : { ufhTerminalControl: /** @type {const} */ ('collector') }),
    }));

    /** @type {import('./types.js').HydraulicsMixingNodeSnapshot | undefined} */
    let mixingNodeSnap;
    const mn = underfloorHeating.mixingNode;
    if (
      mn
      && typeof mn.flowRateM3PerHour === 'number'
      && typeof mn.headMetersMin === 'number'
      && typeof mn.valveKvsMin === 'number'
    ) {
      mixingNodeSnap = {
        flowRateM3PerHour: mn.flowRateM3PerHour,
        headMetersMin: mn.headMetersMin,
        valveKvsMin: mn.valveKvsMin,
        ...(mn.boilerSupplyC !== undefined ? { boilerSupplyC: mn.boilerSupplyC } : {}),
        ...(mn.floorCircuitSupplyC !== undefined
          ? { floorCircuitSupplyC: mn.floorCircuitSupplyC }
          : {}),
      };
    }

    /** @type {import('./types.js').HydraulicsUnderfloorCircuit} */
    const underfloorCircuit = {
      deltaTK: underfloorHeating.underfloorHydraulics?.deltaTK ?? 10,
      aggregate: {
        heatLoadWatts: underfloorHeating.totalHeatFluxUpWatts ?? 0,
        flowRateM3PerHour:
          underfloorHeating.underfloorHydraulics?.flowRateM3PerHour ?? 0,
      },
      isMixingNodeRequired: underfloorHeating.isMixingNodeRequired === true,
      rooms: ufhRooms,
    };
    const dist = underfloorHeating.distributionPreset;
    if (dist === 'collector_mixing_valve' || dist === 'hydraulic_separator') {
      underfloorCircuit.distributionPreset = dist;
    }
    if (mixingNodeSnap) {
      underfloorCircuit.mixingNode = mixingNodeSnap;
    }
    circuits.underfloor = underfloorCircuit;
  }

  if (hotWater && (hotWater.peakFlowLps != null || hotWater.hotWaterPowerKw != null)) {
    /** @type {import('./types.js').HydraulicsDhwCircuit} */
    const dhw = {
      scenario: hotWater.dhwSupplyScenario === 'storage' ? 'storage' : 'flowThrough',
      peakFlowLps: hotWater.peakFlowLps ?? 0,
      hotWaterPowerKw: hotWater.hotWaterPowerKw ?? 0,
      ...(hotWater.designColdWaterC !== undefined
        ? { designColdWaterC: hotWater.designColdWaterC }
        : {}),
      ...(hotWater.hotWaterC !== undefined ? { hotWaterC: hotWater.hotWaterC } : {}),
    };

    const indirect = matching.indirectWaterHeater?.selected;
    if (indirect?.specs?.volumeLiters) {
      dhw.indirectTank = {
        volumeLiters: indirect.specs.volumeLiters,
        coilPowerKw:
          matching.indirectWaterHeater?.coilPowerKw
          ?? matching.indirectWaterHeater?.effectiveHeatPowerKw
          ?? 0,
      };
    }

    circuits.dhw = dhw;
  }

  const surveyMain = input.hydraulics?.mainLineLengthM;
  const mainLineLengthM =
    typeof surveyMain === 'number' && surveyMain >= 0
      ? surveyMain
      : rules.defaultLengthsM.mainLine;

  const radiatorBranches = buildOrderedRadiatorBranches(
    circuits.radiators?.consumers ?? [],
    input.hydraulics?.radiatorBranchOverrides,
    radiatorOverrides,
    rules.defaultLengthsM.radiatorBranch,
  );

  const radiatorWiringSystemType = resolveRadiatorWiringSystemType(
    input.hydraulics?.radiatorWiringSystemType,
  );

  /** @type {import('./types.js').HydraulicsUfhCollectorTransit[]} */
  const ufhCollectorTransit = [];
  if (circuits.underfloor?.rooms?.length) {
    const floorsWithUfh = new Set(
      circuits.underfloor.rooms.map((r) => r.floor),
    );
    for (const floor of [...floorsWithUfh].sort((a, b) => a - b)) {
      ufhCollectorTransit.push({
        floor,
        transitLengthM: estimateBranchLengthM(
          floor,
          rules.defaultLengthsM.ufhCollectorBranch,
        ),
      });
    }
  }

  /** @type {import('./types.js').HydraulicsPipelineInput} */
  return {
    schemaVersion: 1,
    meta: {
      heatingEmittersMode: emittersMode,
      objectType,
      dhwMatchingScheme,
    },
    source,
    circuits,
    layout: {
      mainLineLengthM,
      radiatorWiringSystemType,
      radiatorBranches,
      ufhCollectorTransit,
      ...(input.hydraulics?.pipeMaterialPreference
        ? { pipeMaterialPreference: input.hydraulics.pipeMaterialPreference }
        : {}),
    },
    rules,
  };
}

/**
 * Назначение: расчёт циркуляционных колец и выявление «худшей ветки».
 * Описание: Суммирует Δp по полному пути котёл → потребитель (×2 на обратку),
 * выбирает критическое кольцо для насоса и рекомендации балансировки.
 */

import { round } from '../utils/math.js';

/** @type {import('./types.js').HydraulicsNodeKind[]} */
const LEAF_NODE_KINDS = [
  'radiator_consumer',
  'radiator_manifold',
  'ufh_loop',
  'dhw_load',
  'indirect_coil',
];

/**
 * @param {import('./types.js').HydraulicsGraph} graph
 * @returns {import('./types.js').HydraulicsGraphNode[]}
 */
function findLeafNodes(graph) {
  const incoming = new Set(graph.edges.map((e) => e.to));
  return graph.nodes.filter(
    (n) => LEAF_NODE_KINDS.includes(n.kind) || !incoming.has(n.id),
  );
}

/**
 * @param {import('./types.js').HydraulicsGraph} graph
 * @param {string} leafId
 * @returns {import('./types.js').HydraulicsGraphEdge[]}
 */
function tracePathFromBoiler(graph, leafId) {
  /** @type {Map<string, import('./types.js').HydraulicsGraphEdge>} */
  const parentEdge = new Map();
  /** @type {string[]} */
  const queue = ['boiler'];
  /** @type {Set<string>} */
  const visited = new Set(['boiler']);

  while (queue.length) {
    const nodeId = queue.shift();
    if (nodeId === leafId) break;

    for (const edge of graph.edges) {
      if (edge.from !== nodeId || edge.fluid !== 'heating') continue;
      if (visited.has(edge.to)) continue;
      visited.add(edge.to);
      parentEdge.set(edge.to, edge);
      queue.push(edge.to);
    }
  }

  if (!visited.has(leafId)) return [];

  /** @type {import('./types.js').HydraulicsGraphEdge[]} */
  const path = [];
  let current = leafId;
  while (current !== 'boiler') {
    const edge = parentEdge.get(current);
    if (!edge) return [];
    path.unshift(edge);
    current = edge.from;
  }
  return path;
}

/**
 * @param {import('./types.js').HydraulicsGraphNode} node
 * @returns {import('./types.js').HydraulicsCirculationCircuitKind}
 */
function resolveCircuitKind(node) {
  if (node.kind === 'radiator_consumer' || node.kind === 'radiator_manifold') {
    return 'radiators';
  }
  if (node.kind === 'ufh_loop') return 'underfloor';
  if (node.kind === 'indirect_coil') return 'indirect_dhw';
  return 'dhw';
}

/**
 * @param {import('./types.js').HydraulicsGraphEdge[]} pathEdges
 * @param {Map<string, import('./types.js').HydraulicsPipeMatchItem>} pipeByEdge
 * @returns {number}
 */
function sumPathPressureDropKPa(pathEdges, pipeByEdge) {
  let oneWayKPa = 0;
  for (const edge of pathEdges) {
    oneWayKPa += pipeByEdge.get(edge.id)?.pressureDropKPa ?? 0;
  }
  return round(oneWayKPa * 2, 2);
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraph} args.graph
 * @param {import('./types.js').HydraulicsPipeMatchItem[]} args.pipes
 * @param {number} args.balancingValveKPaPerTurn
 * @returns {import('./types.js').HydraulicsCirculationLoopsReport}
 */
export function computeCirculationLoops({ graph, pipes, balancingValveKPaPerTurn }) {
  const pipeByEdge = new Map(pipes.map((p) => [p.edgeId, p]));
  const leaves = findLeafNodes(graph).filter((n) =>
    LEAF_NODE_KINDS.includes(n.kind),
  );

  /** @type {import('./types.js').HydraulicsCirculationLoopBranch[]} */
  const branches = [];

  for (const leaf of leaves) {
    const pathEdges = tracePathFromBoiler(graph, leaf.id);
    if (!pathEdges.length) continue;

    const pressureDropKPa = sumPathPressureDropKPa(pathEdges, pipeByEdge);
    branches.push({
      branchId: leaf.id,
      label: leaf.label,
      circuit: resolveCircuitKind(leaf),
      ...(leaf.roomId !== undefined ? { roomId: leaf.roomId } : {}),
      ...(leaf.loopId !== undefined ? { loopId: leaf.loopId } : {}),
      edgeIds: pathEdges.map((e) => e.id),
      pressureDropKPa,
      isCritical: false,
    });
  }

  branches.sort((a, b) => b.pressureDropKPa - a.pressureDropKPa);

  /** @type {import('./types.js').HydraulicsCirculationLoopBranch | null} */
  let criticalLoop = branches[0] ?? null;
  if (criticalLoop) {
    criticalLoop = { ...criticalLoop, isCritical: true };
    branches[0] = criticalLoop;
  }

  const criticalKPa = criticalLoop?.pressureDropKPa ?? 0;

  /** @type {import('./types.js').HydraulicsBalancingRecommendation[]} */
  const balancingRecommendations = [];

  for (const branch of branches) {
    if (branch.isCritical) continue;
    const excessKPa = round(criticalKPa - branch.pressureDropKPa, 2);
    if (excessKPa < 0.5) continue;

    const turns =
      balancingValveKPaPerTurn > 0
        ? Math.max(1, Math.round(excessKPa / balancingValveKPaPerTurn))
        : null;

    balancingRecommendations.push({
      branchId: branch.branchId,
      label: branch.label,
      circuit: branch.circuit,
      branchPressureDropKPa: branch.pressureDropKPa,
      criticalPressureDropKPa: criticalKPa,
      excessPressureDropKPa: excessKPa,
      ...(turns != null ? { estimatedValveTurns: turns } : {}),
      hint:
        turns != null
          ? `Прикрутити балансувальний клапан приблизно на ${turns} об. (надлишок Δp ${excessKPa} кПа відносно критичного контуру).`
          : `Додати опір ${excessKPa} кПа балансувальним клапаном відносно критичного контуру.`,
    });
  }

  return {
    branches,
    criticalLoop,
    criticalLoopEdgeIds: criticalLoop?.edgeIds ?? [],
    criticalPressureDropKPa: criticalKPa,
    headRequiredM: round(criticalKPa / 9.81, 2),
    balancingRecommendations,
  };
}

/**
 * Назначение: cross-validation режима контуров HydraulicsPipelineInput.
 * Описание: Дополняет AJV — режим emitters vs наличие radiators/underfloor; согласованность Q.
 */

import { thermalLoadToFlow } from './thermalLoadToFlow.js';
import { round } from '../utils/math.js';

/**
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 */
export function crossValidateHydraulicsPipelineInput(dto) {
  const mode = dto.meta.heatingEmittersMode;

  if (mode === 'ufh_only') {
    if (dto.circuits.radiators?.consumers?.length) {
      throw validationError(
        'ufh_only: контур radiators не повинен бути присутнім',
        'circuits.radiators',
      );
    }
    if (!dto.circuits.underfloor?.rooms?.length) {
      throw validationError(
        'ufh_only: обов’язковий circuits.underfloor.rooms',
        'circuits.underfloor',
      );
    }
  }

  if (mode === 'radiators_only' && dto.circuits.underfloor?.rooms?.length) {
    throw validationError(
      'radiators_only: circuits.underfloor не очікується',
      'circuits.underfloor',
    );
  }

  if (mode === 'mixed') {
    const hasRad = (dto.circuits.radiators?.consumers?.length ?? 0) > 0;
    const hasUfh = (dto.circuits.underfloor?.rooms?.length ?? 0) > 0;
    if (!hasRad && !hasUfh) {
      throw validationError(
        'mixed: потрібен хоча б один контур radiators або underfloor',
        'circuits',
      );
    }
  }

  for (const c of dto.circuits.radiators?.consumers ?? []) {
    if (c.heatLoadWatts > 0 && !(c.flowRateM3PerHour > 0)) {
      throw validationError(
        `radiators consumer ${c.roomId}: flowRateM3PerHour обов’язковий при heatLoadWatts > 0`,
        `circuits.radiators.consumers`,
      );
    }
  }

  const radCircuit = dto.circuits.radiators;
  if (radCircuit?.consumers?.length && radCircuit.flowDeltaTK > 0) {
    const flowDt = radCircuit.flowDeltaTK;
    for (const c of radCircuit.consumers) {
      if (c.heatLoadWatts <= 0 || c.flowRateM3PerHour <= 0) continue;
      const expected = thermalLoadToFlow({
        heatLoadWatts: c.heatLoadWatts,
        deltaTK: flowDt,
      }).flowRateM3PerHour;
      const relErr = Math.abs(c.flowRateM3PerHour - expected) / expected;
      if (relErr > 0.02) {
        throw validationError(
          `radiators consumer ${c.roomId}: flowRateM3PerHour ${c.flowRateM3PerHour} не узгоджено з flowDeltaTK=${flowDt} (очікув. ≈${expected})`,
          'circuits.radiators.consumers',
        );
      }
    }
    const sumConsumers = round(
      radCircuit.consumers.reduce((s, c) => s + c.flowRateM3PerHour, 0),
      3,
    );
    if (
      radCircuit.totalFlowRateM3PerHour > 0
      && Math.abs(sumConsumers - radCircuit.totalFlowRateM3PerHour) > 0.002
    ) {
      throw validationError(
        `radiators totalFlowRateM3PerHour (${radCircuit.totalFlowRateM3PerHour}) ≠ sum(consumers) (${sumConsumers})`,
        'circuits.radiators.totalFlowRateM3PerHour',
      );
    }
  }

  for (const r of dto.circuits.underfloor?.rooms ?? []) {
    if (r.heatLoadWatts > 0 && !(r.flowRateM3PerHour > 0)) {
      throw validationError(
        `underfloor room ${r.roomId}: flowRateM3PerHour обов’язковий при heatLoadWatts > 0`,
        'circuits.underfloor.rooms',
      );
    }
  }
}

/**
 * @param {string} message
 * @param {string} path
 * @returns {Error & import('../types/shared-types.js').AppErrorLike}
 */
function validationError(message, path) {
  const err = new Error(message);
  /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
  const appErr = err;
  appErr.code = 'HYDRAULICS_PIPELINE_INPUT_INVALID';
  appErr.details = [{ instancePath: `/${path.replace(/\./g, '/')}`, message }];
  return appErr;
}

/**
 * Назначение: парсинг номинального диаметра из строк каталога котла.
 * Описание: «3/4 дюйма», «DN20», «20 мм» → мм для граничного условия pipeline.
 */

/** @type {Record<string, number>} */
const INCH_TO_MM = {
  '1/2': 15,
  '3/4': 20,
  '1': 25,
  '1 1/4': 32,
  '1 1/2': 40,
  '2': 50,
};

/**
 * @param {string} raw
 * @returns {number | null}
 */
export function parseConnectionDiameterMm(raw) {
  if (typeof raw !== 'string' || !raw.trim()) return null;
  const s = raw.trim().toLowerCase();

  const dnMatch = s.match(/\bdn\s*(\d{1,3})\b/i);
  if (dnMatch) {
    const n = Number(dnMatch[1]);
    return Number.isFinite(n) && n > 0 ? n : null;
  }

  const mmMatch = s.match(/(\d{1,3})\s*мм/);
  if (mmMatch) {
    const n = Number(mmMatch[1]);
    return Number.isFinite(n) && n > 0 ? n : null;
  }

  for (const [inch, mm] of Object.entries(INCH_TO_MM)) {
    if (s.includes(`${inch} дюйм`) || s.includes(`${inch}"`)) {
      return mm;
    }
  }

  const bare = s.match(/\b(\d{1,2})\b/);
  if (bare) {
    const n = Number(bare[1]);
    if (n >= 10 && n <= 100) return n;
  }

  return null;
}

/**
 * @param {string[] | undefined | null} connectionDiameters
 * @returns {number[]}
 */
export function parseConnectionDiametersMm(connectionDiameters) {
  if (!Array.isArray(connectionDiameters)) return [];
  /** @type {number[]} */
  const out = [];
  for (const item of connectionDiameters) {
    const mm = parseConnectionDiameterMm(String(item));
    if (mm != null && !out.includes(mm)) out.push(mm);
  }
  return out;
}

/**
 * Назначение: подбор трубы из каталога по расходу и скорости.
 * Описание: Guard Dвн → минимальный Ø при v ≤ vMax; fallback вверх/вниз внутри guard-пула.
 */

import {
  computeSegmentHydraulics,
  pipeInternalDiameterMm,
  pipeVelocityMps,
  pickLargestPipe,
  pickSmallestPipe,
  pickSmallestPipeWithinVelocityRange,
  resolveRoughnessMm,
  resolveVelocityMinMps,
} from './pipeHydraulics.js';
import { RAD_MICRO_MANIFOLD_NODE_ID } from './groupRadiatorGraphBranches.js';
import { RAD_DISTRIBUTION_MANIFOLD_NODE_ID } from './radiatorGraphHelpers.js';
import {
  filterPoolByMinInternalDiameter,
  resolveMinInternalDiameterMm,
} from './pipeCatalogPoolFilter.js';
import {
  orderTrunkChainEdges,
  pickTrunkChainWithTaper,
  usesTrunkTaperPick,
} from './pickTrunkChain.js';

/**
 * @param {'main' | 'trunk' | 'branch' | 'ufh_collector_transit' | 'ufh_loop' | 'dhw'} segmentRole
 * @param {import('./types.js').HydraulicsRules} rules
 * @returns {number}
 */
function resolveVelocityMaxMps(segmentRole, rules) {
  return segmentRole === 'main'
    || segmentRole === 'trunk'
    || segmentRole === 'ufh_collector_transit'
    ? rules.velocityLimitsMps.mainMax
    : rules.velocityLimitsMps.branchMax;
}

/**
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized[]} pipes
 * @param {import('./types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [materialPreference]
 * @returns {import('../catalog/types.js').PipeCatalogItemNormalized[]}
 */
function filterPipePool(pipes, materialPreference) {
  /** @type {import('../catalog/types.js').PipeCatalogItemNormalized[]} */
  let pool = [...pipes];

  if (materialPreference) {
    const pref = materialPreference.toLowerCase();
    const filtered = pool.filter((p) => {
      const m = String(p.material ?? '').toLowerCase();
      if (pref === 'pex') return m.includes('pex');
      if (pref === 'metal_plastic') {
        return m.includes('metal') || m.includes('pex-al') || m.includes('ал');
      }
      if (pref === 'steel') return m.includes('steel') || m.includes('сталь');
      return true;
    });
    if (filtered.length) pool = filtered;
  }

  pool.sort(
    (a, b) => pipeInternalDiameterMm(a) - pipeInternalDiameterMm(b),
  );
  return pool;
}

/**
 * @param {object} args
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized[]} args.pool
 * @param {number} args.flowM3PerHour
 * @param {number} args.vMax
 * @param {number} args.vMin
 * @returns {{
 *   pipe: import('../catalog/types.js').PipeCatalogItemNormalized;
 *   velocityLimitExceeded?: boolean;
 *   velocityBelowMin?: boolean;
 * }}
 */
function selectPipeFromPool({ pool, flowM3PerHour, vMax, vMin }) {
  const withinRange = pickSmallestPipeWithinVelocityRange(
    pool,
    flowM3PerHour,
    vMin,
    vMax,
  );
  if (withinRange) {
    return { pipe: withinRange };
  }

  const smallest = pickSmallestPipe(pool);
  const largest = pickLargestPipe(pool);
  if (!smallest || !largest) {
    throw new Error('pickPipe: пустой пул каталога');
  }

  if (pipeVelocityMps(smallest, flowM3PerHour) > vMax) {
    return { pipe: largest, velocityLimitExceeded: true };
  }
  return { pipe: smallest, velocityBelowMin: true };
}

/**
 * @param {import('./types.js').HydraulicsGraphEdge} edge
 * @param {import('./types.js').HydraulicsRules} rules
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized[]} materialPool
 * @returns {{
 *   pool: import('../catalog/types.js').PipeCatalogItemNormalized[];
 *   exhausted: boolean;
 *   minInternalMm: number;
 *   mainTransitGuardApplied: boolean;
 * }}
 */
function applyInternalDiameterGuard(edge, rules, materialPool) {
  const minInternalMm = resolveMinInternalDiameterMm(edge, rules);
  const { pool, exhausted } = filterPoolByMinInternalDiameter(
    materialPool,
    minInternalMm,
  );
  return {
    pool,
    exhausted,
    minInternalMm,
    mainTransitGuardApplied: edge.isMainLine === true,
  };
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraphEdge} args.edge
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} args.pipes
 * @param {string} args.catalogPipeId
 * @param {import('./types.js').HydraulicsRules} args.rules
 * @param {number} [args.localZeta]
 * @returns {import('./types.js').HydraulicsPipeMatchItem | null}
 */
export function pickPipeForEdgeByCatalogId({
  edge,
  pipes,
  catalogPipeId,
  rules,
  localZeta = 0,
}) {
  const pipe = pipes?.find((p) => p.id === catalogPipeId);
  if (!pipe || edge.designFlowM3PerHour <= 0) return null;

  const internalMm = pipeInternalDiameterMm(pipe);
  const roughness = resolveRoughnessMm(pipe.material, rules.roughnessMmByMaterial);
  const hyd = computeSegmentHydraulics({
    flowM3PerHour: edge.designFlowM3PerHour,
    lengthM: edge.lengthM,
    internalDiameterMm: internalMm,
    roughnessMm: roughness,
    localZeta,
  });

  return {
    edgeId: edge.id,
    catalogPipeId: pipe.id,
    velocityMps: hyd.velocityMps,
    pressureDropKPa: hyd.pressureDropKPa,
    internalDiameterMm: internalMm,
  };
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraphEdge} args.edge
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} args.pipes
 * @param {import('./types.js').HydraulicsRules} args.rules
 * @param {import('./types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [args.materialPreference]
 * @param {number} [args.localZeta]
 * @returns {import('./types.js').HydraulicsPipeMatchItem | null}
 */
export function pickPipeForEdge({
  edge,
  pipes,
  rules,
  materialPreference,
  localZeta = 0,
}) {
  if (!pipes?.length || edge.designFlowM3PerHour <= 0) return null;

  const vMax = resolveVelocityMaxMps(edge.segmentRole, rules);
  const vMin = resolveVelocityMinMps(edge.segmentRole, rules);
  const materialPool = filterPipePool(pipes, materialPreference);
  if (!materialPool.length) return null;

  const guard = applyInternalDiameterGuard(edge, rules, materialPool);
  if (guard.exhausted) {
    return {
      edgeId: edge.id,
      catalogPipeId: '',
      velocityMps: 0,
      pressureDropKPa: 0,
      internalDiameterMm: 0,
      catalogPoolExhausted: true,
      ...(guard.mainTransitGuardApplied
        ? { mainTransitGuardApplied: true }
        : {}),
    };
  }

  const { pipe: chosen, velocityLimitExceeded, velocityBelowMin } = selectPipeFromPool({
    pool: guard.pool,
    flowM3PerHour: edge.designFlowM3PerHour,
    vMax,
    vMin,
  });

  const internalMm = pipeInternalDiameterMm(chosen);
  const roughness = resolveRoughnessMm(
    chosen.material,
    rules.roughnessMmByMaterial,
  );
  const hyd = computeSegmentHydraulics({
    flowM3PerHour: edge.designFlowM3PerHour,
    lengthM: edge.lengthM,
    internalDiameterMm: internalMm,
    roughnessMm: roughness,
    localZeta,
  });

  return {
    edgeId: edge.id,
    catalogPipeId: chosen.id,
    velocityMps: hyd.velocityMps,
    pressureDropKPa: hyd.pressureDropKPa,
    internalDiameterMm: internalMm,
    ...(velocityLimitExceeded ? { velocityLimitExceeded: true } : {}),
    ...(velocityBelowMin ? { velocityBelowMin: true } : {}),
    ...(guard.mainTransitGuardApplied
      ? { mainTransitGuardApplied: true }
      : {}),
  };
}

/**
 * @param {import('./types.js').HydraulicsGraphEdge} edge
 * @param {import('./types.js').HydraulicsRules} rules
 * @param {import('./types.js').HydraulicsApplianceRules['localLossZeta']} zeta
 * @returns {number}
 */
function resolveLocalZetaForEdge(edge, rules, zeta) {
  if (edge.segmentRole === 'trunk' && edge.teeRole === 'pass_through') {
    return zeta.teePass;
  }
  if (edge.segmentRole === 'branch' && edge.teeRole === 'branch_takeoff') {
    return zeta.teeBranchTakeoff + zeta.elbow90;
  }
  if (edge.to === RAD_DISTRIBUTION_MANIFOLD_NODE_ID) {
    return zeta.collector;
  }

  let localZeta =
    edge.segmentRole === 'ufh_loop'
      ? zeta.collector + zeta.elbow90
      : edge.segmentRole === 'ufh_collector_transit'
        ? zeta.collector + zeta.elbow90
        : edge.segmentRole === 'branch'
          ? zeta.teeBranch + zeta.elbow90
          : edge.segmentRole === 'main'
            ? zeta.elbow90
            : edge.segmentRole === 'trunk'
              ? zeta.teePass
              : 0;

  if (edge.to === RAD_MICRO_MANIFOLD_NODE_ID) {
    localZeta += rules.radiatorBranchGrouping.localZetaManifold;
  }
  if (edge.from === RAD_DISTRIBUTION_MANIFOLD_NODE_ID) {
    localZeta = zeta.teeBranch + zeta.elbow90;
  }
  return localZeta;
}

/**
 * @param {import('./types.js').HydraulicsGraphEdge} edge
 * @param {import('./types.js').HydraulicsRules} rules
 * @returns {number}
 */
function resolveVelocityMinForEdge(edge, rules) {
  if (edge.isMainLine === true || edge.segmentRole === 'trunk') {
    return rules.velocityLimitsMps.mainMin;
  }
  return resolveVelocityMinMps(edge.segmentRole, rules);
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraph} args.graph
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @param {import('./types.js').HydraulicsPipelineInput} args.dto
 * @returns {{ pipes: import('./types.js').HydraulicsPipeMatchItem[]; warnings: string[] }}
 */
export function pickPipesForGraph({ graph, catalog, dto }) {
  /** @type {import('./types.js').HydraulicsPipeMatchItem[]} */
  const pipes = [];
  /** @type {string[]} */
  const warnings = [];
  const zeta = dto.rules.localLossZeta;

  /** @type {Map<string, import('./types.js').HydraulicsPipeMatchItem | null>} */
  const trunkChainMatches = new Map();
  /** @type {Set<string>} */
  const trunkChainEdgeIds = new Set();

  if (usesTrunkTaperPick(dto.layout.radiatorWiringSystemType)) {
    const chain = orderTrunkChainEdges(graph);
    for (const edge of chain) {
      trunkChainEdgeIds.add(edge.id);
    }
    if (chain.length > 0) {
      const chainResults = pickTrunkChainWithTaper({
        chain,
        pipes: catalog.pipes ?? [],
        rules: dto.rules,
        materialPreference: dto.layout.pipeMaterialPreference,
        resolveLocalZeta: (edge) => resolveLocalZetaForEdge(edge, dto.rules, zeta),
        filterMaterialPool: filterPipePool,
      });
      for (const [edgeId, match] of chainResults) {
        trunkChainMatches.set(edgeId, match);
      }
    }
  }

  for (const edge of graph.edges) {
    const localZeta = resolveLocalZetaForEdge(edge, dto.rules, zeta);

    const preferredId = edge.preferredCatalogPipeId;
    const match =
      trunkChainEdgeIds.has(edge.id)
        ? trunkChainMatches.get(edge.id) ?? null
        : preferredId
          ? pickPipeForEdgeByCatalogId({
              edge,
              pipes: catalog.pipes ?? [],
              catalogPipeId: preferredId,
              rules: dto.rules,
              localZeta,
            })
          : pickPipeForEdge({
              edge,
              pipes: catalog.pipes ?? [],
              rules: dto.rules,
              materialPreference: dto.layout.pipeMaterialPreference,
              localZeta,
            });

    if (match) {
      if (match.catalogPoolExhausted) {
        const minInternal = match.trunkTaperFloorMm
          ?? resolveMinInternalDiameterMm(edge, dto.rules);
        warnings.push(
          `Ділянка ${edge.id}: у каталозі немає труби з Dвн ≥ ${minInternal} мм.`,
        );
      } else {
        pipes.push(match);
        const vMax = resolveVelocityMaxMps(edge.segmentRole, dto.rules);
        const vMin = resolveVelocityMinForEdge(edge, dto.rules);
        if (match.velocityLimitExceeded) {
          warnings.push(
            `Ділянка ${edge.id}: швидкість ${match.velocityMps} м/с вище ліміту ${vMax} м/с — підібрано максимальний Ø каталогу.`,
          );
        } else if (match.velocityBelowMin) {
          if (match.mainTransitGuardApplied) {
            warnings.push(
              `Ділянка ${edge.id}: швидкість ${match.velocityMps} м/с нижче мінімуму ${vMin} м/с `
              + `— застосовано guard Dвн ≥ ${dto.rules.mainTransitMinInternalDiameterMm} мм.`,
            );
          } else if (
            edge.segmentRole === 'trunk'
            && match.trunkTaperFromDownstreamMm != null
          ) {
            warnings.push(
              `Ділянка ${edge.id}: швидкість ${match.velocityMps} м/с нижче мінімуму ${vMin} м/с `
              + `— утримано Ø ≥ ${match.trunkTaperFromDownstreamMm} мм downstream (без відкату до guard 12 мм).`,
            );
          } else {
            warnings.push(
              `Ділянка ${edge.id}: швидкість ${match.velocityMps} м/с нижче мінімуму ${vMin} м/с — підібрано мінімальний Ø.`,
            );
          }
        } else if (match.velocityMps > vMax) {
          warnings.push(
            `Ділянка ${edge.id}: швидкість ${match.velocityMps} м/с вище ліміту ${vMax} м/с — перевірте каталог.`,
          );
        }
      }
    } else if (edge.designFlowM3PerHour > 0) {
      warnings.push(`Ділянка ${edge.id}: не вдалося підібрати трубу з каталогу.`);
    }
  }

  return { pipes, warnings };
}

/**
 * Назначение: подбор циркуляционного насоса по H_system(Q).
 * Описание: H_pump(Q) = a·Q² + b·Q + c из operatingModes каталога.
 */

import { pumpHeadM } from '../utils/pumpCurveMath.js';
import { round } from '../utils/math.js';

export { pumpHeadM };

/**
 * @typedef {'below_manufacturer_qmin' | 'curve_unavailable' | 'near_qmax' | 'negative_or_tiny_head' | 'insufficient_head' | 'head_oversized'} PumpDutyIssue
 */

/**
 * @typedef {'ok' | 'below_manufacturer_qmin' | 'curve_unavailable' | 'insufficient_head' | 'no_suitable_mode'} BuiltinPumpDutyStatus
 */

/**
 * @param {import('./types.js').HydraulicsRules} rules
 * @returns {import('./types.js').HydraulicsPumpDutyRules}
 */
export function pumpDutyRulesFromHydraulicsRules(rules) {
  return {
    pumpHeadMarginPercent: rules.pumpHeadMarginPercent,
    pumpDutyQMaxUtilizationPercent: rules.pumpDutyQMaxUtilizationPercent,
    pumpMinHeadAtDutyM: rules.pumpMinHeadAtDutyM,
    pumpMaxHeadMarginPercent: rules.pumpMaxHeadMarginPercent,
  };
}

/**
 * @param {Array<{ qMinM3h?: number }>} modes
 * @returns {number}
 */
export function resolveHeatingCircuitMinFlowM3h(modes) {
  /** @type {number[]} */
  const mins = [];
  for (const m of modes) {
    const v = m.qMinM3h;
    if (typeof v === 'number' && Number.isFinite(v) && v > 0) {
      mins.push(v);
    }
  }
  return mins.length ? Math.min(...mins) : 0;
}

/**
 * @param {object} args
 * @param {{ qMinM3h?: number; qMaxM3h?: number; coefficients: object }} args.mode
 * @param {number} args.q
 * @param {number} args.headRequiredM
 * @param {number} args.headTarget
 * @param {import('./types.js').HydraulicsPumpDutyRules} args.dutyRules
 * @param {boolean} [args.skipHeadOversizedCheck]
 * @param {boolean} [args.softQMin] - зона смесителя: Q < qMin не отсекает режим
 * @returns {{
 *   ok: boolean;
 *   headAtQ?: number;
 *   marginPercent?: number;
 *   issue?: PumpDutyIssue;
 *   softQMinApplied?: boolean;
 * }}
 */
export function evaluatePumpModeAtDuty({
  mode,
  q,
  headRequiredM,
  headTarget,
  dutyRules,
  skipHeadOversizedCheck = false,
  softQMin = false,
}) {
  const qMin = mode.qMinM3h ?? 0;
  const qMax = mode.qMaxM3h ?? Infinity;

  let softQMinApplied = false;
  if (q < qMin) {
    if (!softQMin) {
      return { ok: false, issue: 'below_manufacturer_qmin' };
    }
    softQMinApplied = true;
  }
  if (q > qMax) {
    return { ok: false, issue: 'curve_unavailable' };
  }

  const qMaxUtil = dutyRules.pumpDutyQMaxUtilizationPercent / 100;
  if (q > qMax * qMaxUtil) {
    return { ok: false, issue: 'near_qmax' };
  }

  const headAtQ = pumpHeadM(mode.coefficients, q);
  if (headAtQ < dutyRules.pumpMinHeadAtDutyM) {
    return { ok: false, issue: 'curve_unavailable' };
  }
  if (headAtQ < headTarget) {
    return { ok: false, issue: 'insufficient_head' };
  }

  const margin = ((headAtQ - headRequiredM) / headRequiredM) * 100;
  if (!skipHeadOversizedCheck && margin > dutyRules.pumpMaxHeadMarginPercent) {
    return { ok: false, issue: 'head_oversized' };
  }

  return {
    ok: true,
    headAtQ,
    marginPercent: margin,
    ...(softQMinApplied ? { softQMinApplied: true } : {}),
  };
}

/**
 * Подбор насоса из каталога по рабочей точке.
 *
 * @param {object} args
 * @param {number} args.designFlowM3PerHour
 * @param {number} args.headRequiredM
 * @param {import('../catalog/types.js').NormalizedCatalog['pumps']} args.pumps
 * @param {import('./types.js').HydraulicsPumpDutyRules} args.dutyRules
 * @param {boolean} [args.softQMin] - допускать Q < qMin (зона смесителя ТП)
 * @param {boolean} [args.skipHeadOversizedCheck] - не отсекать по запасу > pumpMaxHeadMarginPercent
 * @param {boolean} [args.useExactHeadRequired] - H_target = H_req без запаса pumpHeadMarginPercent
 * @returns {{ pump: import('./types.js').HydraulicsPumpMatch | null; warnings: string[] }}
 */
export function pickPumpForSystem({
  designFlowM3PerHour,
  headRequiredM,
  pumps,
  dutyRules,
  softQMin = false,
  skipHeadOversizedCheck = false,
  useExactHeadRequired = false,
}) {
  /** @type {string[]} */
  const warnings = [];
  const q = designFlowM3PerHour;
  const headTarget = useExactHeadRequired
    ? headRequiredM
    : headRequiredM * (1 + dutyRules.pumpHeadMarginPercent / 100);

  if (q <= 0 || headRequiredM <= 0) {
    return { pump: null, warnings: ['Насос не підібрано: нульовий витрата або напір.'] };
  }

  if (!pumps?.length) {
    return { pump: null, warnings: ['Каталог насосів порожній — підбір неможливий.'] };
  }

  /** @type {import('./types.js').HydraulicsPumpMatch | null} */
  let best = null;
  let bestSoftQMin = false;

  for (const pump of pumps) {
    if (pump.type === 'circulation_hot_water') continue;

    for (const mode of pump.operatingModes ?? []) {
      const evalResult = evaluatePumpModeAtDuty({
        mode,
        q,
        headRequiredM,
        headTarget,
        dutyRules,
        skipHeadOversizedCheck,
        softQMin,
      });
      if (!evalResult.ok || evalResult.headAtQ == null || evalResult.marginPercent == null) {
        continue;
      }

      /** @type {string[]} */
      const candWarnings = [];
      if (evalResult.softQMinApplied) {
        const modeQMin = mode.qMinM3h ?? 0;
        candWarnings.push(
          `Витрата Q=${q} м³/ч нижче паспортного q_min=${modeQMin} м³/ч режиму «${mode.modeName}» — `
          + 'допущено роботу біля лівого краю кривої (зона змішувального вузла).',
        );
      }

      const candidate = {
        catalogPumpId: pump.id,
        modeName: mode.modeName,
        headMarginPercent: round(evalResult.marginPercent, 1),
        designFlowM3PerHour: q,
        headRequiredM: round(headRequiredM, 2),
        headAtDesignM: round(evalResult.headAtQ, 2),
        warnings: candWarnings,
      };
      if (
        !best
        || candidate.headMarginPercent < best.headMarginPercent
      ) {
        best = candidate;
        bestSoftQMin = evalResult.softQMinApplied === true;
      }
    }
  }

  if (!best) {
    const marginHint = skipHeadOversizedCheck
      ? `H≥${round(headTarget, 2)} м (без стелі запасу за напором)`
      : `H≥${round(headTarget, 2)} м (запас за напором ${dutyRules.pumpHeadMarginPercent}…${dutyRules.pumpMaxHeadMarginPercent} %)`;
    warnings.push(
      `Не знайдено насос для Q=${q} м³/ч и ${marginHint} `
      + `(допустимая зона: Q≤${dutyRules.pumpDutyQMaxUtilizationPercent} % Q_max режима`
      + (softQMin ? ', soft qMin для зони змішувача' : '')
      + ') — розширте каталог або зменште опори.',
    );
    return { pump: null, warnings };
  }

  if (bestSoftQMin && best.warnings.length) {
    warnings.push(...best.warnings);
  }

  return { pump: best, warnings };
}

/**
 * Проверка кривой встроенного насоса котла в рабочей точке.
 *
 * @param {object} args
 * @param {Array<{ modeName: string; qMinM3h?: number; qMaxM3h?: number; coefficients: object }>} args.operatingModes
 * @param {number} args.designFlowM3PerHour
 * @param {number} args.headRequiredM
 * @param {import('./types.js').HydraulicsPumpDutyRules} args.dutyRules
 * @returns {import('./types.js').BuiltinPumpCurveEvaluation}
 */
export function evaluatePumpCurveAtDuty({
  operatingModes,
  designFlowM3PerHour,
  headRequiredM,
  dutyRules,
}) {
  const q = designFlowM3PerHour;
  const headTarget = headRequiredM * (1 + dutyRules.pumpHeadMarginPercent / 100);
  const heatingCircuitMinFlowM3h = resolveHeatingCircuitMinFlowM3h(operatingModes);

  if (q <= 0 || headRequiredM <= 0 || !operatingModes?.length) {
    return { ok: false, builtinPumpRecognized: false };
  }

  if (heatingCircuitMinFlowM3h > 0 && q < heatingCircuitMinFlowM3h) {
    return {
      ok: false,
      dutyStatus: 'below_manufacturer_qmin',
      heatingCircuitMinFlowM3h,
      builtinPumpRecognized: true,
    };
  }

  /** @type {{ modeName: string; headAtDesignM: number; headMarginPercent: number } | null} */
  let best = null;

  for (const mode of operatingModes) {
    const evalResult = evaluatePumpModeAtDuty({
      mode,
      q,
      headRequiredM,
      headTarget,
      dutyRules,
      skipHeadOversizedCheck: true,
    });
    if (!evalResult.ok || evalResult.headAtQ == null || evalResult.marginPercent == null) {
      continue;
    }

    const candidate = {
      modeName: mode.modeName,
      headAtDesignM: round(evalResult.headAtQ, 2),
      headMarginPercent: round(evalResult.marginPercent, 1),
    };
    if (!best || candidate.headMarginPercent < best.headMarginPercent) {
      best = candidate;
    }
  }

  if (!best) {
    return {
      ok: false,
      dutyStatus: 'no_suitable_mode',
      heatingCircuitMinFlowM3h,
      builtinPumpRecognized: true,
    };
  }

  return {
    ok: true,
    dutyStatus: 'ok',
    modeName: best.modeName,
    headAtDesignM: best.headAtDesignM,
    headMarginPercent: best.headMarginPercent,
    heatingCircuitMinFlowM3h,
    builtinPumpRecognized: true,
  };
}

/**
 * Назначение: подбор последовательной магистрали trunk (dead-end / pass).
 * Описание: монотонное заужение Ø по потоку — upstream Dвн ≥ downstream; при v&lt;vMin не откат к guard 12 мм.
 */

import {
  computeSegmentHydraulics,
  pipeInternalDiameterMm,
  pipeVelocityMps,
  pickLargestPipe,
  pickSmallestPipe,
  pickSmallestPipeWithinVelocityRange,
  resolveRoughnessMm,
} from './pipeHydraulics.js';

const TRUNK_JUNCTION_ID_RE = /^rad_trunk_j_(\d+)$/;

/**
 * @param {string} nodeId
 * @returns {number | null}
 */
function trunkJunctionIndex(nodeId) {
  const match = TRUNK_JUNCTION_ID_RE.exec(nodeId);
  return match ? Number(match[1]) : null;
}

/**
 * Упорядочивает trunk-рёбра магистрали от upstream к downstream (j0→j1→…).
 *
 * @param {import('./types.js').HydraulicsGraph} graph
 * @returns {import('./types.js').HydraulicsGraphEdge[]}
 */
export function orderTrunkChainEdges(graph) {
  return graph.edges
    .filter(
      (edge) =>
        edge.segmentRole === 'trunk'
        && trunkJunctionIndex(edge.from) != null,
    )
    .sort((a, b) => {
      const ai = trunkJunctionIndex(a.from) ?? 0;
      const bi = trunkJunctionIndex(b.from) ?? 0;
      return ai - bi;
    });
}

/**
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized[]} materialPool
 * @param {number} floorMm
 * @returns {import('../catalog/types.js').PipeCatalogItemNormalized[]}
 */
function poolAtOrAboveDiameter(materialPool, floorMm) {
  return materialPool.filter(
    (pipe) => pipeInternalDiameterMm(pipe) >= floorMm,
  );
}

/**
 * Подбор одного trunk-участка с нижней границей Ø от downstream-сегмента.
 *
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraphEdge} args.edge
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized[]} args.materialPool
 * @param {import('./types.js').HydraulicsRules} args.rules
 * @param {number} args.minInternalMmFromDownstream — Ø downstream; 0 на последнем участке цепочки
 * @param {number} args.localZeta
 * @returns {import('./types.js').HydraulicsPipeMatchItem | null}
 */
export function pickTrunkEdgeWithTaper({
  edge,
  materialPool,
  rules,
  minInternalMmFromDownstream,
  localZeta,
}) {
  if (!materialPool.length || edge.designFlowM3PerHour <= 0) return null;

  const vMax = rules.velocityLimitsMps.mainMax;
  const vMin = rules.velocityLimitsMps.mainMin;
  const absoluteFloorMm = rules.branchMinInternalDiameterMm ?? 12;
  const floorMm =
    minInternalMmFromDownstream > 0
      ? minInternalMmFromDownstream
      : absoluteFloorMm;

  const pool = poolAtOrAboveDiameter(materialPool, floorMm);
  if (!pool.length) {
    return {
      edgeId: edge.id,
      catalogPipeId: '',
      velocityMps: 0,
      pressureDropKPa: 0,
      internalDiameterMm: 0,
      catalogPoolExhausted: true,
      trunkTaperFloorMm: floorMm,
    };
  }

  const flow = edge.designFlowM3PerHour;
  let chosen = pickSmallestPipeWithinVelocityRange(pool, flow, vMin, vMax);
  let velocityLimitExceeded = false;
  let velocityBelowMin = false;

  if (!chosen) {
    const smallestAtFloor = pickSmallestPipe(pool);
    if (!smallestAtFloor) return null;

    const vAtFloor = pipeVelocityMps(smallestAtFloor, flow);
    if (vAtFloor > vMax) {
      chosen = pickLargestPipe(pool);
      velocityLimitExceeded = true;
    } else {
      chosen = smallestAtFloor;
      if (vAtFloor < vMin) {
        velocityBelowMin = true;
      }
    }
  }

  if (!chosen) return null;

  const internalMm = pipeInternalDiameterMm(chosen);
  const roughness = resolveRoughnessMm(
    chosen.material,
    rules.roughnessMmByMaterial,
  );
  const hyd = computeSegmentHydraulics({
    flowM3PerHour: flow,
    lengthM: edge.lengthM,
    internalDiameterMm: internalMm,
    roughnessMm: roughness,
    localZeta,
  });

  return {
    edgeId: edge.id,
    catalogPipeId: chosen.id,
    velocityMps: hyd.velocityMps,
    pressureDropKPa: hyd.pressureDropKPa,
    internalDiameterMm: internalMm,
    ...(velocityLimitExceeded ? { velocityLimitExceeded: true } : {}),
    ...(velocityBelowMin ? { velocityBelowMin: true } : {}),
    ...(minInternalMmFromDownstream > 0
      ? { trunkTaperFromDownstreamMm: minInternalMmFromDownstream }
      : {}),
  };
}

/**
 * Каскадный подбор цепочки trunk: от downstream к upstream, монотонное заужение.
 *
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraphEdge[]} args.chain — upstream→downstream
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} args.pipes
 * @param {import('./types.js').HydraulicsRules} args.rules
 * @param {import('./types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [args.materialPreference]
 * @param {(edge: import('./types.js').HydraulicsGraphEdge) => number} args.resolveLocalZeta
 * @param {(
 *   pipes: import('../catalog/types.js').PipeCatalogItemNormalized[],
 *   materialPreference?: import('./types.js').HydraulicsSurveyInput['pipeMaterialPreference']
 * ) => import('../catalog/types.js').PipeCatalogItemNormalized[]} args.filterMaterialPool
 * @returns {Map<string, import('./types.js').HydraulicsPipeMatchItem | null>}
 */
export function pickTrunkChainWithTaper({
  chain,
  pipes,
  rules,
  materialPreference,
  resolveLocalZeta,
  filterMaterialPool,
}) {
  /** @type {Map<string, import('./types.js').HydraulicsPipeMatchItem | null>} */
  const matches = new Map();
  if (!chain.length || !pipes?.length) return matches;

  const materialPool = filterMaterialPool(pipes, materialPreference);
  let downstreamFloorMm = 0;

  for (let i = chain.length - 1; i >= 0; i -= 1) {
    const edge = chain[i];
    if (!edge) continue;
    const match = pickTrunkEdgeWithTaper({
      edge,
      materialPool,
      rules,
      minInternalMmFromDownstream: downstreamFloorMm,
      localZeta: resolveLocalZeta(edge),
    });
    matches.set(edge.id, match);
    if (match?.internalDiameterMm && match.internalDiameterMm > 0) {
      downstreamFloorMm = match.internalDiameterMm;
    }
  }

  return matches;
}

/**
 * @param {import('./types.js').RadiatorWiringSystemType | undefined} wiringType
 * @returns {boolean}
 */
export function usesTrunkTaperPick(wiringType) {
  return wiringType === 'two-pipe-dead-end' || wiringType === 'two-pipe-pass';
}

/**
 * Назначение: расчёт потерь напора и критического контура.
 * Описание: Суммирует Δp по циркуляционным кольцам; учитывает mixingNode.headMetersMin.
 */

import { computeCirculationLoops } from './circulationLoops.js';
import { round } from '../utils/math.js';

export { resolveDesignPumpFlowM3h } from './resolveCirculationFlows.js';

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsGraph} args.graph
 * @param {import('./types.js').HydraulicsPipeMatchItem[]} args.pipes
 * @param {import('./types.js').HydraulicsPipelineInput} args.dto
 * @returns {import('./types.js').HydraulicsPressureReport}
 */
export function computePressureReport({ graph, pipes, dto }) {
  const pipeByEdge = new Map(pipes.map((p) => [p.edgeId, p]));

  /** @type {import('./types.js').HydraulicsPressureSegment[]} */
  const segments = [];

  for (const edge of graph.edges) {
    if (edge.fluid !== 'heating') continue;
    const pipe = pipeByEdge.get(edge.id);
    segments.push({
      edgeId: edge.id,
      lengthM: edge.lengthM,
      velocityMps: pipe?.velocityMps ?? 0,
      pressureDropKPa: pipe?.pressureDropKPa ?? 0,
      ...(pipe?.catalogPipeId !== undefined
        ? { catalogPipeId: pipe.catalogPipeId }
        : {}),
    });
  }

  const balancingKPaPerTurn =
    dto.rules.balancingValveKPaPerTurn ?? 3;

  const circulation = computeCirculationLoops({
    graph,
    pipes,
    balancingValveKPaPerTurn: balancingKPaPerTurn,
  });

  let headRequiredM = circulation.headRequiredM;
  const criticalEdgeIds = circulation.criticalLoopEdgeIds;

  const mixingMin = dto.circuits.underfloor?.mixingNode?.headMetersMin;
  if (typeof mixingMin === 'number' && mixingMin > headRequiredM) {
    headRequiredM = round(mixingMin, 2);
  }

  if (dto.source.requiredKw > 50 && dto.circuits.underfloor?.isMixingNodeRequired) {
    const sepMin =
      dto.rules.localLossZeta.collector > 0
        ? 5
        : headRequiredM;
    if (sepMin > headRequiredM) headRequiredM = sepMin;
  }

  return {
    criticalLoopEdgeIds: criticalEdgeIds,
    headRequiredM,
    criticalPressureDropKPa: circulation.criticalPressureDropKPa,
    ...(circulation.criticalLoop
      ? { criticalLoop: circulation.criticalLoop }
      : {}),
    circulationLoops: circulation.branches,
    balancingRecommendations: circulation.balancingRecommendations,
    segments,
  };
}

/**
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {import('./types.js').HydraulicsConsumerSummary[]}
 */
export function buildConsumerSummaries(dto) {
  /** @type {import('./types.js').HydraulicsConsumerSummary[]} */
  const out = [];
  if (dto.circuits.radiators) {
    out.push({
      circuit: 'radiators',
      totalFlowRateM3PerHour: dto.circuits.radiators.totalFlowRateM3PerHour,
      totalHeatLoadWatts: dto.circuits.radiators.consumers.reduce(
        (s, c) => s + c.heatLoadWatts,
        0,
      ),
    });
  }
  if (dto.circuits.underfloor) {
    out.push({
      circuit: 'underfloor',
      totalFlowRateM3PerHour: dto.circuits.underfloor.aggregate.flowRateM3PerHour,
      totalHeatLoadWatts: dto.circuits.underfloor.aggregate.heatLoadWatts,
    });
  }
  if (dto.circuits.dhw) {
    out.push({
      circuit: 'dhw',
      totalFlowRateM3PerHour: round(
        (dto.circuits.dhw.peakFlowLps * 3600) / 1000,
        3,
      ),
    });
  }
  return out;
}

/**
 * @param {number} flowM3PerHour
 * @returns {string}
 */
export function coarseRecommendedDn(flowM3PerHour) {
  if (flowM3PerHour > 1.5) return 'DN25–DN32';
  if (flowM3PerHour > 0.9) return 'DN20–DN25';
  if (flowM3PerHour > 0.4) return 'DN20';
  return 'DN15–DN20';
}

/**
 * Назначение: SSOT расходов по зонам циркуляции (Q) для гидравлики.
 * Описание: Топологические сценарии — прямое подключение, смесительный узел ТП,
 * гидрострелка, приоритет ГВС (БКН).
 */

import { round } from '../utils/math.js';
import { thermalLoadToFlow } from './thermalLoadToFlow.js';

/** @typedef {'direct' | 'mixing_valve' | 'hydraulic_separator'} CirculationTopology */

/**
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {number}
 */
function sumRadiatorHeatWatts(dto) {
  return dto.circuits.radiators?.consumers?.reduce(
    (s, c) => s + c.heatLoadWatts,
    0,
  ) ?? 0;
}

/**
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {{
 *   rad: number;
 *   ufh: number;
 *   pRad: number;
 *   pUfh: number;
 *   dtBoiler: number;
 *   dtUfh: number;
 * }}
 */
function circuitBasics(dto) {
  return {
    rad: dto.circuits.radiators?.totalFlowRateM3PerHour ?? 0,
    ufh: dto.circuits.underfloor?.aggregate.flowRateM3PerHour ?? 0,
    pRad: sumRadiatorHeatWatts(dto),
    pUfh: dto.circuits.underfloor?.aggregate.heatLoadWatts ?? 0,
    dtBoiler: dto.source.deltaTK,
    dtUfh: dto.circuits.underfloor?.deltaTK ?? 10,
  };
}

/**
 * Первичный подмес смесительного узла: Q_ufh · (ΔT_ufh / ΔT_boiler).
 *
 * @param {number} qUfh
 * @param {number} dtUfh
 * @param {number} dtBoiler
 * @returns {number}
 */
export function mixingNodePrimaryBleedM3h(qUfh, dtUfh, dtBoiler) {
  if (qUfh <= 0 || dtBoiler <= 0) return 0;
  return round(qUfh * (dtUfh / dtBoiler), 3);
}

/**
 * @param {number} heatLoadWatts
 * @param {number} deltaTK
 * @returns {number}
 */
function flowFromHeatWatts(heatLoadWatts, deltaTK) {
  return thermalLoadToFlow({ heatLoadWatts, deltaTK }).flowRateM3PerHour;
}

/**
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {import('./types.js').HydraulicsCirculationFlowsResult}
 */
export function resolveCirculationFlows(dto) {
  const mode = dto.meta.heatingEmittersMode;
  const { rad, ufh, pRad, pUfh, dtBoiler, dtUfh } = circuitBasics(dto);
  const ufhCircuit = dto.circuits.underfloor;
  const mixing = ufhCircuit?.isMixingNodeRequired === true;
  const preset = ufhCircuit?.distributionPreset;

  /** @type {import('./types.js').HydraulicsCirculationZone[]} */
  const zones = [];
  /** @type {string[]} */
  const notes = [];
  /** @type {string[]} */
  const warnings = [];

  /** @type {CirculationTopology} */
  let topology = 'direct';

  const dhw = dto.circuits.dhw;
  let qDhw = 0;
  if (
    dhw?.scenario === 'storage'
    && dhw.indirectTank
    && dhw.hotWaterPowerKw > 0
  ) {
    qDhw = flowFromHeatWatts(dhw.hotWaterPowerKw * 1000, dtBoiler);
  }

  /**
   * @param {import('./types.js').HydraulicsCirculationZone} zone
   */
  const pushZone = (zone) => {
    zones.push(zone);
  };

  if (mode === 'radiators_only') {
    pushZone({
      zoneId: 'boiler_primary',
      label: 'Котловий контур (радіатори)',
      pumpRole: 'main',
      designFlowM3PerHour: rad,
      heatLoadWatts: pRad,
      deltaTK: dtBoiler,
      requiresCatalogPump: true,
    });
  } else if (mode === 'ufh_only') {
    if (mixing && preset === 'collector_mixing_valve') {
      topology = 'mixing_valve';
      const qMain = flowFromHeatWatts(pUfh, dtBoiler);
      pushZone({
        zoneId: 'boiler_primary',
        label: 'Котловий контур (живлення змішувального вузла)',
        pumpRole: 'main',
        designFlowM3PerHour: qMain,
        heatLoadWatts: pUfh,
        deltaTK: dtBoiler,
        requiresCatalogPump: true,
      });
      pushZone({
        zoneId: 'ufh_floor',
        label: 'Контур теплої підлоги',
        pumpRole: 'zone',
        designFlowM3PerHour: ufh,
        heatLoadWatts: pUfh,
        deltaTK: dtUfh,
        requiresCatalogPump: true,
      });
    } else if (mixing && preset === 'hydraulic_separator') {
      topology = 'hydraulic_separator';
      const margin = dto.rules.primaryFlowMarginPercent;
      const qPrimaryBase = flowFromHeatWatts(pUfh, dtBoiler);
      const qPrimary = round(
        Math.max(qPrimaryBase, ufh * (1 + margin / 100)),
        3,
      );
      pushZone({
        zoneId: 'boiler_primary',
        label: 'Первинний контур (котел → гідрострілка)',
        pumpRole: 'main',
        designFlowM3PerHour: qPrimary,
        heatLoadWatts: pUfh,
        deltaTK: dtBoiler,
        requiresCatalogPump: true,
      });
      pushZone({
        zoneId: 'ufh_floor_secondary',
        label: 'Вторинний контур: тепла підлога',
        pumpRole: 'zone',
        designFlowM3PerHour: ufh,
        heatLoadWatts: pUfh,
        deltaTK: dtUfh,
        requiresCatalogPump: true,
      });
    } else {
      pushZone({
        zoneId: 'boiler_primary',
        label: 'Котловий контур (тепла підлога)',
        pumpRole: 'main',
        designFlowM3PerHour: ufh,
        heatLoadWatts: pUfh,
        deltaTK: dtUfh,
        requiresCatalogPump: true,
      });
    }
  } else if (mixing && preset === 'hydraulic_separator') {
    topology = 'hydraulic_separator';
    const margin = dto.rules.primaryFlowMarginPercent;
    const pTotal = pRad + pUfh;
    const qPrimaryBase = flowFromHeatWatts(pTotal, dtBoiler);
    const qSecondarySum = rad + ufh;
    const qPrimary = round(
      Math.max(qPrimaryBase, qSecondarySum * (1 + margin / 100)),
      3,
    );
    pushZone({
      zoneId: 'boiler_primary',
      label: 'Первинний контур (котел → гідрострілка)',
      pumpRole: 'main',
      designFlowM3PerHour: qPrimary,
      heatLoadWatts: pTotal,
      deltaTK: dtBoiler,
      requiresCatalogPump: true,
    });
    if (rad > 0) {
      pushZone({
        zoneId: 'radiators_secondary',
        label: 'Вторинний контур: радіатори',
        pumpRole: 'zone',
        designFlowM3PerHour: rad,
        heatLoadWatts: pRad,
        deltaTK: dto.circuits.radiators?.flowDeltaTK ?? dtBoiler,
        requiresCatalogPump: true,
      });
    }
    if (ufh > 0) {
      pushZone({
        zoneId: 'ufh_floor_secondary',
        label: 'Вторинний контур: тепла підлога',
        pumpRole: 'zone',
        designFlowM3PerHour: ufh,
        heatLoadWatts: pUfh,
        deltaTK: dtUfh,
        requiresCatalogPump: true,
      });
    }
  } else if (mixing && preset === 'collector_mixing_valve') {
    topology = 'mixing_valve';
    const qMainThermal = flowFromHeatWatts(pRad + pUfh, dtBoiler);
    const qUfhPrimary = mixingNodePrimaryBleedM3h(ufh, dtUfh, dtBoiler);
    const qMainMixing = round(rad + qUfhPrimary, 3);
    if (
      qMainThermal > 0
      && Math.abs(qMainThermal - qMainMixing) / qMainThermal > 0.05
    ) {
      warnings.push(
        `Витрата котлового контуру за балансом потужностей (${qMainThermal} м³/ч) `
        + `и по подмесу ТП (${qMainMixing} м³/ч) розходяться >5 % — використано тепловий баланс.`,
      );
    }
    pushZone({
      zoneId: 'boiler_primary',
      label: 'Котловий контур (радіатори + підміш ТП)',
      pumpRole: 'main',
      designFlowM3PerHour: qMainThermal,
      heatLoadWatts: pRad + pUfh,
      deltaTK: dtBoiler,
      requiresCatalogPump: true,
    });
    if (ufh > 0) {
      pushZone({
        zoneId: 'ufh_floor',
        label: 'Контур теплої підлоги (насос змішувального вузла)',
        pumpRole: 'zone',
        designFlowM3PerHour: ufh,
        heatLoadWatts: pUfh,
        deltaTK: dtUfh,
        requiresCatalogPump: true,
      });
    }
  } else {
    topology = 'direct';
    const qCombined = round(rad + ufh, 3);
    pushZone({
      zoneId: 'boiler_primary',
      label: 'Змішана система (радіатори + ТП)',
      pumpRole: 'main',
      designFlowM3PerHour: qCombined,
      heatLoadWatts: pRad + pUfh,
      deltaTK: dtBoiler,
      requiresCatalogPump: true,
    });
  }

  const boilerZone = zones.find((z) => z.zoneId === 'boiler_primary');
  const primaryMainLineFlowM3PerHour = boilerZone?.designFlowM3PerHour ?? 0;

  if (qDhw > 0 && boilerZone) {
    const qHeating = boilerZone.designFlowM3PerHour;
    boilerZone.designFlowM3PerHour = round(Math.max(qHeating, qDhw), 3);
    boilerZone.heatingFlowM3PerHour = qHeating;
    boilerZone.dhwPriorityFlowM3PerHour = qDhw;
    notes.push(
      'Пріоритет ГВП: під час прогріву БКН контури опалення відсікаються автоматикою котла.',
    );
    if (qDhw > qHeating) {
      notes.push(
        `Розрахунковий витрата котлового насоса визначено за змійовиком БКН `
        + `(${qDhw} м³/ч), а не за опаленням (${qHeating} м³/ч).`,
      );
    }
    pushZone({
      zoneId: 'dhw_coil',
      label: 'Змійовик БКН (режим прогріву)',
      pumpRole: 'dhw',
      designFlowM3PerHour: qDhw,
      heatLoadWatts: (dhw?.hotWaterPowerKw ?? 0) * 1000,
      deltaTK: dtBoiler,
      requiresCatalogPump: false,
      simultaneousWithHeating: false,
    });
  }

  const boilerPumpDesignFlowM3PerHour =
    boilerZone?.designFlowM3PerHour ?? primaryMainLineFlowM3PerHour;

  return {
    zones,
    topology,
    primaryMainLineFlowM3PerHour,
    boilerPumpDesignFlowM3PerHour,
    mixingNodePrimaryBleedM3PerHour: mixing
      ? mixingNodePrimaryBleedM3h(ufh, dtUfh, dtBoiler)
      : 0,
    notes,
    warnings,
  };
}

/**
 * Расход на магистрали графа (котёл → коллектор / гидрострелка).
 *
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {number}
 */
export function resolvePrimaryMainLineFlowM3h(dto) {
  return resolveCirculationFlows(dto).primaryMainLineFlowM3PerHour;
}

/**
 * Расчётный расход котлового насоса с учётом приоритета ГВС.
 *
 * @param {import('./types.js').HydraulicsPipelineInput} dto
 * @returns {number}
 */
export function resolveDesignPumpFlowM3h(dto) {
  return resolveCirculationFlows(dto).boilerPumpDesignFlowM3PerHour;
}

/**
 * Назначение: подбор насосов по зонам циркуляции.
 * Описание: Проверка встроенного насоса котла → каталог pumps; несколько зон (main + zone).
 */

import {
  evaluatePumpCurveAtDuty,
  pickPumpForSystem,
  pumpDutyRulesFromHydraulicsRules,
} from './pickPump.js';
import { resolveCirculationFlows } from './resolveCirculationFlows.js';
import { resolveHeadForZone } from './resolveZoneHead.js';
import { round } from '../utils/math.js';

/**
 * @param {import('../catalog/types.js').NormalizedCatalog['boilers']} boilers
 * @param {string | undefined} catalogBoilerId
 * @returns {import('../catalog/types.js').BoilerCatalogItemNormalized | null}
 */
function findBoilerInCatalog(boilers, catalogBoilerId) {
  if (!catalogBoilerId || !boilers) return null;
  const all = [
    ...(boilers.doubleCircuit ?? []),
    ...(boilers.singleCircuit ?? []),
  ];
  return all.find((b) => {
    const id = /** @type {{ id?: string }} */ (b).id;
    return id === catalogBoilerId || b.model === catalogBoilerId;
  }) ?? null;
}

/**
 * @param {Record<string, unknown> | null | undefined} boilerRecord
 * @returns {boolean}
 */
function isWallMountedBoiler(boilerRecord) {
  if (!boilerRecord) return false;
  const mt = boilerRecord.mountingType;
  if (mt === 'wall') return true;
  if (mt === 'floor') return false;
  const tags = boilerRecord.tags;
  if (Array.isArray(tags)) {
    if (tags.includes('wall-mounted')) return true;
    if (tags.includes('floor-standing')) return false;
  }
  return !!(/** @type {{ circulationPump?: unknown }} */ (boilerRecord).circulationPump);
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsCirculationZone} args.zone
 * @param {number} args.headRequiredM
 * @param {import('./types.js').HydraulicsPumpDutyRules} args.dutyRules
 * @param {Record<string, unknown> | null | undefined} args.boilerRecord
 * @param {import('../catalog/types.js').NormalizedCatalog['pumps']} args.catalogPumps
 * @returns {{
 *   match: import('./types.js').HydraulicsResolvedPump | null;
 *   warnings: string[];
 *   builtinPumpDuty?: import('./types.js').BuiltinPumpDutyReport;
 * }}
 */
function resolvePumpForZone({
  zone,
  headRequiredM,
  dutyRules,
  boilerRecord,
  catalogPumps,
}) {
  /** @type {string[]} */
  const warnings = [];
  const q = zone.designFlowM3PerHour;
  const h = headRequiredM;

  if (q <= 0 || h <= 0) {
    return {
      match: null,
      warnings: [`[${zone.label}] Насос не підібрано: нульовий витрата або напір.`],
    };
  }

  const base = {
    zoneId: zone.zoneId,
    zoneLabel: zone.label,
    pumpRole: zone.pumpRole,
    designFlowM3PerHour: q,
    headRequiredM: round(h, 2),
    warnings: [],
  };

  /** @type {import('./types.js').BuiltinPumpDutyReport | undefined} */
  let builtinPumpDuty;

  if (zone.pumpRole === 'main') {
    const builtinModes = /** @type {{ operatingModes?: unknown[] } | undefined} */ (
      boilerRecord?.circulationPump
    )?.operatingModes;

    if (Array.isArray(builtinModes) && builtinModes.length > 0) {
      const evalResult = evaluatePumpCurveAtDuty({
        operatingModes: /** @type {Array<{ modeName: string; qMinM3h?: number; qMaxM3h?: number; coefficients: object }>} */ (
          builtinModes
        ),
        designFlowM3PerHour: q,
        headRequiredM: h,
        dutyRules,
      });

      const boilerModel = typeof boilerRecord?.model === 'string' ? boilerRecord.model : undefined;
      const boilerId = typeof boilerRecord?.id === 'string' ? boilerRecord.id : undefined;

      if (evalResult.heatingCircuitMinFlowM3h != null && evalResult.builtinPumpRecognized) {
        builtinPumpDuty = {
          status: evalResult.ok ? 'ok' : (evalResult.dutyStatus ?? 'no_suitable_mode'),
          heatingCircuitMinFlowM3h: evalResult.heatingCircuitMinFlowM3h,
          ...(boilerId ? { catalogBoilerId: boilerId } : {}),
          ...(boilerModel ? { catalogBoilerModel: boilerModel } : {}),
          designFlowM3PerHour: q,
          headRequiredM: round(h, 2),
        };
      }

      if (evalResult.ok && evalResult.modeName != null && evalResult.headAtDesignM != null) {
        return {
          match: {
            ...base,
            pumpSource: 'boiler_builtin',
            ...(boilerId !== undefined ? { catalogBoilerId: boilerId } : {}),
            modeName: evalResult.modeName,
            headAtDesignM: evalResult.headAtDesignM,
            headMarginPercent: evalResult.headMarginPercent ?? 0,
            note: 'Використовується вбудований насос котла.',
          },
          warnings,
          ...(builtinPumpDuty !== undefined ? { builtinPumpDuty } : {}),
        };
      }

      if (evalResult.dutyStatus === 'below_manufacturer_qmin') {
        const qMin = evalResult.heatingCircuitMinFlowM3h ?? 0;
        warnings.push(
          `[${zone.label}] Витрата Q=${q} м³/ч нижче заводського мінімуму вбудованого насоса `
          + `(q_min=${qMin} м³/ч) — ризик тактування та перегріву теплообмінника.`,
        );
        if (isWallMountedBoiler(boilerRecord)) {
          return {
            match: null,
            warnings,
            ...(builtinPumpDuty !== undefined ? { builtinPumpDuty } : {}),
          };
        }
      } else {
        warnings.push(
          `[${zone.label}] Вбудований насос котла не перекриває робочу точку `
          + `(Q=${q} м³/ч, H=${round(h, 2)} м) — підбір з каталогу.`,
        );
      }
    }
  }

  const isZonePump = zone.pumpRole === 'zone';
  const { pump, warnings: pickWarnings } = pickPumpForSystem({
    designFlowM3PerHour: q,
    headRequiredM: h,
    pumps: catalogPumps ?? [],
    dutyRules,
    softQMin: isZonePump,
    skipHeadOversizedCheck: isZonePump,
    useExactHeadRequired: isZonePump,
  });

  warnings.push(...pickWarnings.map((w) => `[${zone.label}] ${w}`));

  if (!pump) {
    return {
      match: null,
      warnings,
      ...(builtinPumpDuty !== undefined ? { builtinPumpDuty } : {}),
    };
  }

  return {
    match: {
      ...base,
      pumpSource: 'catalog',
      ...(pump.catalogPumpId !== undefined
        ? { catalogPumpId: pump.catalogPumpId }
        : {}),
      modeName: pump.modeName,
      headAtDesignM: pump.headAtDesignM,
      headMarginPercent: pump.headMarginPercent,
      warnings: pump.warnings,
      ...(zone.pumpRole === 'main'
        ? { note: 'Дод. насос на котлову гілку (вбудований слабкий).' }
        : {}),
    },
    warnings,
    ...(builtinPumpDuty !== undefined ? { builtinPumpDuty } : {}),
  };
}

/**
 * @param {import('./types.js').HydraulicsResolvedPump} resolved
 * @returns {import('./types.js').HydraulicsPumpMatch}
 */
function toLegacyPumpMatch(resolved) {
  return {
    zoneId: resolved.zoneId,
    zoneLabel: resolved.zoneLabel,
    pumpRole: resolved.pumpRole,
    pumpSource: resolved.pumpSource,
    ...(resolved.catalogPumpId ? { catalogPumpId: resolved.catalogPumpId } : {}),
    ...(resolved.catalogBoilerId ? { catalogBoilerId: resolved.catalogBoilerId } : {}),
    modeName: resolved.modeName,
    headMarginPercent: resolved.headMarginPercent,
    designFlowM3PerHour: resolved.designFlowM3PerHour,
    headRequiredM: resolved.headRequiredM,
    headAtDesignM: resolved.headAtDesignM,
    ...(resolved.note ? { note: resolved.note } : {}),
    warnings: resolved.warnings,
  };
}

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsPipelineInput} args.dto
 * @param {import('./types.js').HydraulicsPressureReport} args.pressure
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @returns {import('./types.js').HydraulicsSystemPumpsResult}
 */
export function resolveSystemPumps({ dto, pressure, catalog }) {
  const flows = resolveCirculationFlows(dto);
  const dutyRules = pumpDutyRulesFromHydraulicsRules(dto.rules);

  const boilerRecord = findBoilerInCatalog(
    catalog.boilers,
    dto.source.catalogBoilerId,
  );

  /** @type {import('./types.js').HydraulicsResolvedPump[]} */
  const pumps = [];
  /** @type {string[]} */
  const warnings = [...flows.warnings];
  /** @type {string[]} */
  const notes = [...flows.notes];
  /** @type {import('./types.js').BuiltinPumpDutyReport | undefined} */
  let builtinPumpDuty;

  for (const zone of flows.zones) {
    if (!zone.requiresCatalogPump) continue;

    const headRequiredM = resolveHeadForZone(zone.zoneId, pressure, dto);
    const { match, warnings: zoneWarnings, builtinPumpDuty: zoneBuiltin } = resolvePumpForZone({
      zone,
      headRequiredM,
      dutyRules,
      boilerRecord: /** @type {Record<string, unknown> | null} */ (boilerRecord),
      catalogPumps: catalog.pumps,
    });
    warnings.push(...zoneWarnings);
    if (zoneBuiltin) {
      builtinPumpDuty = zoneBuiltin;
    }
    if (match) {
      pumps.push(match);
      if (match.note) notes.push(`[${match.zoneLabel}] ${match.note}`);
    }
  }

  const mainResolved = pumps.find((p) => p.zoneId === 'boiler_primary') ?? pumps[0];

  return {
    circulationZones: flows.zones,
    topology: flows.topology,
    boilerPumpDesignFlowM3PerHour: flows.boilerPumpDesignFlowM3PerHour,
    primaryMainLineFlowM3PerHour: flows.primaryMainLineFlowM3PerHour,
    pumps,
    ...(mainResolved ? { pump: toLegacyPumpMatch(mainResolved) } : {}),
    ...(builtinPumpDuty ? { builtinPumpDuty } : {}),
    warnings,
    notes,
  };
}

/**
 * Назначение: оркестратор Pure Pipeline гидравлики.
 * Описание: граф → подбор труб → Δp → зоны циркуляции → насосы → отчёт.
 */

import { buildHydraulicsProposal } from './buildHydraulicsProposal.js';
import { buildHydraulicsGraph } from './buildGraph.js';
import { pickPipesForGraph } from './pickPipe.js';
import {
  buildConsumerSummaries,
  coarseRecommendedDn,
  computePressureReport,
  resolveDesignPumpFlowM3h,
} from './pressureDrop.js';
import { resolveSystemPumps } from './resolveSystemPumps.js';
import { thermalLoadToFlow } from './thermalLoadToFlow.js';

/**
 * @param {object} args
 * @param {import('./types.js').HydraulicsPipelineInput} args.dto
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @returns {import('./types.js').HydraulicsPipelineResult}
 */
export function runHydraulicsPipeline({ dto, catalog }) {
  /** @type {string[]} */
  const notes = [];

  const graph = buildHydraulicsGraph(dto);
  const { pipes, warnings: pipeWarnings } = pickPipesForGraph({
    graph,
    catalog,
    dto,
  });

  const pressure = computePressureReport({ graph, pipes, dto });
  const pumpResult = resolveSystemPumps({ dto, pressure, catalog });
  const designFlow = resolveDesignPumpFlowM3h(dto);

  notes.push(...pumpResult.notes);

  const consumers = buildConsumerSummaries(dto);

  const pRad = dto.circuits.radiators?.consumers?.reduce(
    (s, c) => s + c.heatLoadWatts,
    0,
  ) ?? 0;
  const pUfh = dto.circuits.underfloor?.aggregate.heatLoadWatts ?? 0;
  const emittersMode = dto.meta.heatingEmittersMode;
  const primaryHeatWatts =
    emittersMode === 'mixed'
      ? pRad + pUfh
      : emittersMode === 'ufh_only'
        ? pUfh
        : pRad;

  const flowFromThermal = thermalLoadToFlow({
    heatLoadWatts: primaryHeatWatts,
    deltaTK: dto.source.deltaTK,
  });

  if (dto.layout.mainLineLengthM > 40) {
    notes.push(
      'Довга магістраль: на реальному проєкті обов’язково рахувати опори та насос.',
    );
  }

  const minBoilerKw =
    dto.circuits.underfloor?.isMixingNodeRequired
      ? 50
      : null;
  if (typeof minBoilerKw === 'number' && dto.source.requiredKw > minBoilerKw) {
    notes.push(
      'За такої розрахункової потужності котлового контуру рекомендується гідравлічний роздільник (гідрострілка) та проєктна опрацювання колекторної схеми.',
    );
  }

  if (dto.meta.heatingEmittersMode === 'ufh_only') {
    notes.push(
      'Розрахунок магістралі виконано за витратою підсистеми водяної теплої підлоги (underfloorHydraulics).',
    );
  }

  if (pumpResult.topology === 'direct' && dto.meta.heatingEmittersMode === 'mixed') {
    notes.push(
      'Змішана система: витрата котлового насоса = сума витрат радіаторів і ТП.',
    );
  }

  if (pressure.criticalLoop) {
    notes.push(
      `Критичне циркуляційне кільце: «${pressure.criticalLoop.label}» — Δp ${pressure.criticalPressureDropKPa ?? pressure.criticalLoop.pressureDropKPa} кПа (H≈${pressure.headRequiredM} м).`,
    );
  }

  for (const rec of pressure.balancingRecommendations ?? []) {
    notes.push(rec.hint);
  }

  /** @type {import('./types.js').HydraulicsReport} */
  const hydraulics = {
    schemaVersion: 1,
    inputs: {
      heatLoadWatts: primaryHeatWatts,
      deltaTSystemK: dto.source.deltaTK,
      mainLineLengthM: dto.layout.mainLineLengthM,
    },
    massFlowKgPerSec: flowFromThermal.massFlowKgPerSec,
    flowRateM3PerHour: designFlow || flowFromThermal.flowRateM3PerHour,
    boilerPumpDesignFlowM3PerHour: pumpResult.boilerPumpDesignFlowM3PerHour,
    circulationTopology: pumpResult.topology,
    recommendedPipeDiameter: coarseRecommendedDn(designFlow),
    recommendedVelocityRangeMPerSec: [
      dto.rules.velocityLimitsMps.mainMin,
      dto.rules.velocityLimitsMps.mainMax,
    ],
    consumers,
    graph,
    pressure,
    notes,
  };

  /** @type {import('./types.js').HydraulicsMatchingReport} */
  const hydraulicsMatching = {
    pipes,
    topology: pumpResult.topology,
    circulationZones: pumpResult.circulationZones,
    ...(pumpResult.pumps.length ? { pumps: pumpResult.pumps.map((p) => ({
      zoneId: p.zoneId,
      zoneLabel: p.zoneLabel,
      pumpRole: p.pumpRole,
      pumpSource: p.pumpSource,
      ...(p.catalogPumpId ? { catalogPumpId: p.catalogPumpId } : {}),
      ...(p.catalogBoilerId ? { catalogBoilerId: p.catalogBoilerId } : {}),
      modeName: p.modeName,
      headMarginPercent: p.headMarginPercent,
      designFlowM3PerHour: p.designFlowM3PerHour,
      headRequiredM: p.headRequiredM,
      headAtDesignM: p.headAtDesignM,
      ...(p.note ? { note: p.note } : {}),
      warnings: p.warnings,
    })) } : {}),
    ...(pumpResult.pump ? { pump: pumpResult.pump } : {}),
    ...(pumpResult.builtinPumpDuty ? { builtinPumpDuty: pumpResult.builtinPumpDuty } : {}),
    warnings: [...pipeWarnings, ...pumpResult.warnings],
  };

  hydraulicsMatching.proposal = buildHydraulicsProposal({
    matching: hydraulicsMatching,
    graph,
    pressure,
    catalog,
    pumpResult,
  });

  return { hydraulics, hydraulicsMatching };
}

/**
 * Назначение: точка входа HTTP-сервера.
 * Описание: Загружает переменные окружения из backend/.env, поднимает Express с CORS, Helmet (security headers), trust proxy и middleware requestId/логирования. Подключает роуты из api/public.js и прогревает кэш справочников reference/public.js. Обрабатывает ошибки и возвращает структурированный JSON.
 */

import { config as loadEnv } from 'dotenv';
import express from 'express';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import cors from 'cors';
import helmet from 'helmet';
import { createRoutes } from './api/public.js';
import { ERROR_CODES } from './api/errorCodes.js';
import { warmupReferenceCache } from './reference/public.js';
import {
  assertAuthConfiguredForProduction,
  assertAuthConfiguredWhenEnabled,
} from './auth/projectsAuthConfig.js';
import { isMongoBsonObjectTooLargeError } from './projects/documentSizeLimits.js';
import { logger } from './utils/logger.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
loadEnv({ path: join(__dirname, '..', '.env') });

assertAuthConfiguredForProduction();
assertAuthConfiguredWhenEnabled();
if (process.exitCode === 1) {
  process.exit(1);
}

// Захисна сітка: фонові rejection поза Express (без process.exit)
process.on('unhandledRejection', (reason) => {
  logger.error('process.unhandledRejection', null, {
    message: reason instanceof Error ? reason.message : String(reason),
    stack: reason instanceof Error ? reason.stack : undefined,
  });
});

const PORT = Number(process.env.PORT || 3001);
const isProduction = process.env.NODE_ENV === 'production';

const app = express();

// За reverse proxy (nginx, Traefik): req.secure и HSTS в production
const trustProxy = process.env.TRUST_PROXY;
if (trustProxy === 'true' || trustProxy === '1') {
  app.set('trust proxy', 1);
} else if (trustProxy && /^\d+$/.test(trustProxy)) {
  app.set('trust proxy', Number(trustProxy));
} else if (isProduction) {
  app.set('trust proxy', 1);
}

// CORS: dev — Vite (5173); prod — только CORS_ORIGIN (same-origin /api через nginx не требует CORS)
const defaultCorsOrigins = ['http://localhost:5173', 'http://127.0.0.1:5173'];
/** @type {string[]} */
const corsOrigins =
  typeof process.env.CORS_ORIGIN === 'string' && process.env.CORS_ORIGIN.trim()
    ? process.env.CORS_ORIGIN.split(',')
        .map((s) => s.trim())
        .filter(Boolean)
    : defaultCorsOrigins;

app.use(
  cors({
    origin: corsOrigins.length > 0 ? corsOrigins : false,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Accept',
      'Authorization',
      'X-System-Token',
    ],
    credentials: true,
    maxAge: 86400,
  }),
);

app.use(
  helmet({
    crossOriginResourcePolicy: { policy: 'cross-origin' },
    contentSecurityPolicy: false,
    hsts: isProduction
      ? { maxAge: 31_536_000, includeSubDomains: true, preload: false }
      : false,
    crossOriginOpenerPolicy: false,
    crossOriginEmbedderPolicy: false,
  }),
);

// requestId + базове логування (api.request/api.response) для кожного HTTP-запиту
/**
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
app.use((req, res, next) => {
  const requestId = randomUUID();
  req.requestId = requestId;

  const startedAt = Date.now();
  const method = String(req.method ?? 'GET').toUpperCase();
  const path = req.path ?? '/';

  logger.info('api.request', { requestId }, { method, path });

  res.on('finish', () => {
    const ms = Date.now() - startedAt;
    logger.info(
      'api.response',
      { requestId },
      { method, path, statusCode: res.statusCode, ms },
    );
  });

  next();
});

// JSON body-parser із лімітом payload (відповідає попередньому maxBytes)
app.use(express.json({ limit: '1mb' }));

// Роути API
const routes = await createRoutes();
app.use(routes);

const blockStartupWarmup =
  process.env.REFERENCE_WARMUP_BLOCK_STARTUP === 'true' ||
  process.env.REFERENCE_WARMUP_BLOCK_STARTUP === '1';

/**
 * Прогрев reference bundle. Коалесцируется с getReferenceBundle() через refreshInFlight в configCache.
 * @returns {Promise<void>}
 */
async function runReferenceCacheWarmup() {
  logger.info('referenceCache.warmup.start', null, {
    blocking: blockStartupWarmup,
  });
  try {
    const bundle = await warmupReferenceCache();
    logger.info('referenceCache.warmup.ok', null, {
      loadedAt: new Date(bundle.loadedAt).toISOString(),
      catalogSource: bundle.catalogSource,
    });
  } catch (err) {
    logger.error('referenceCache.warmup.failed', null, {
      message: err instanceof Error ? err.message : String(err),
    });
    throw err;
  }
}

// Прогрев до listen: раньше старт, без гонки с первым calc; по умолчанию не блокирует bind порта
if (blockStartupWarmup) {
  try {
    await runReferenceCacheWarmup();
  } catch {
    process.exit(1);
  }
} else {
  void runReferenceCacheWarmup().catch(() => {
    /* referenceCache.warmup.failed уже залогирован */
  });
}

// Централізований обробник помилок у форматі ErrorEnvelope (ok=false)
/**
 * @param {import('./types/shared-types.js').AppErrorLike} err
 * @param {import('express').Request} req
 * @param {import('express').Response<import('./types/shared-types.js').ErrorEnvelope>} res
 * @param {import('express').NextFunction} _next
 */
function handleApiError(err, req, res, _next) {
  const requestId = req.requestId;
  const method = String(req.method ?? 'GET').toUpperCase();
  const path = req.path ?? '/';
  const isProduction = process.env.NODE_ENV === 'production';

  let statusCode = err?.statusCode ?? err?.status ?? 500;
  let code = err?.code ?? 'ERR';
  // Legacy alias admin endpoints → канон VALIDATION_ERROR
  if (code === 'VALIDATION_FAILED') {
    code = ERROR_CODES.VALIDATION_ERROR;
  }
  let clientMessage =
    typeof err?.message === 'string' && err.message.trim()
      ? err.message
      : 'Помилка запиту';
  /** @type {import('./types/shared-types.js').ErrorDetailsAjvItem[] | undefined} */
  let details = Array.isArray(err?.details) ? err.details : undefined;

  // Помилки парсингу JSON / надто великий payload від express.json()
  if (err && typeof err === 'object') {
    if (err.type === 'entity.too.large') {
      statusCode = 413;
      code = 'PAYLOAD_TOO_LARGE';
      clientMessage = 'Занадто великий запит';
      details = undefined;
    } else if (err instanceof SyntaxError && 'body' in err) {
      statusCode = 400;
      code = 'BAD_JSON';
      clientMessage = 'Некоректний JSON';
      details = undefined;
    } else if (isMongoBsonObjectTooLargeError(err)) {
      statusCode = 413;
      code = 'CALCULATION_DOCUMENT_TOO_LARGE';
      clientMessage = 'Документ розрахунку занадто великий для збереження';
      details = undefined;
    }
  }

  const logCode = code;
  /** @type {Record<string, unknown>} */
  const errorLog = { method, path, statusCode, code: logCode };
  if (statusCode >= 500 && err instanceof Error) {
    // Приватний лог: повний текст і stack лише на сервері
    errorLog.internalMessage = err.message;
    errorLog.stack = err.stack;
  } else {
    errorLog.message = clientMessage;
  }

  if (requestId !== undefined) {
    logger.error('api.error', { requestId }, errorLog);
  } else {
    logger.error('api.error', undefined, errorLog);
  }

  // Клієнтський ErrorEnvelope: 500 без витоку err.message / внутрішніх кодів у production
  if (statusCode === 500) {
    clientMessage = 'Внутрішня помилка сервера';
    details = undefined;
    if (isProduction) {
      code = ERROR_CODES.INTERNAL_ERROR;
    } else if (!code || code === 'ERR' || typeof code !== 'string') {
      code = ERROR_CODES.INTERNAL_ERROR;
    }
  } else if (statusCode > 500) {
    // 502/503 AppError: зберігаємо code і message для клієнта
    details = undefined;
  }

  /** @type {import('./types/shared-types.js').ErrorEnvelope['error']} */
  const errorBody = { message: clientMessage, code, statusCode };
  if (details !== undefined) {
    errorBody.details = details;
  }

  res.status(statusCode).json({
    ok: false,
    error: errorBody,
  });
}

app.use(handleApiError);

const server = app.listen(PORT, '0.0.0.0', () => {
  process.stdout.write(`API запущен на порту ${PORT}\n`);
  // Не через logger: при LOG_LEVEL=warn|error сообщения info не видны.
  process.stdout.write(
    'Валидация анкеты: room.type — strict enum; legacy/synonym с warning; coerceTypes: false.\n',
  );
});

server.on('error', (err) => {
  const nodeErr =
    err && typeof err === 'object'
      ? /** @type {NodeJS.ErrnoException} */ (err)
      : null;
  if (nodeErr?.code === 'EADDRINUSE') {
    process.stderr.write(
      `Порт ${PORT} уже занят. Освободите порт и перезапустите.\n`,
    );
    process.exitCode = 1;
    return;
  }

  process.stderr.write(`Помилка сервера: ${err?.message ?? String(err)}\n`);
  process.exitCode = 1;
});

/**
 * Назначение: математика теплопотерь через ограждения.
 * Описание: Q = U·S·ΔT с heatLossFactor и per-element ΔT. Резолвинг U — только в heatlossByRooms.js
 * (envelopePresets, wallAssembly). Экспортирует calculateHeatLoss(); вызывается из heatlossByRooms.js.
 */

/**
 * Перетворення в число з підтримкою “коми” в рядку.
 *
 * @param {unknown} value
 * @param {string} fieldName
 * @returns {number}
 */
function toNumber(value, fieldName) {
  const n =
    typeof value === 'string' ? Number(value.replace(',', '.')) : Number(value);
  if (!Number.isFinite(n)) {
    throw new Error(
      `Поле "${fieldName}" має бути числом. Отримано: ${String(value)}`,
    );
  }
  return n;
}

/**
 * Расчёт теплопотерь одного элемента ограждения.
 *
 * @param {import('../types/shared-types.js').HeatLossCalcElementInput} element
 * @param {number} defaultDeltaT - ΔT по умолчанию (K или °C)
 * @returns {import('../types/shared-types.js').HeatLossElementReport}
 */
function calculateElementLoss(element, defaultDeltaT) {
  if (!element || typeof element !== 'object') {
    throw new Error('Елемент огородження має бути об\'єктом.');
  }

  const areaM2 = toNumber(element.areaM2, 'areaM2');
  if (areaM2 <= 0) {
    throw new Error(`Площа areaM2 має бути > 0. Отримано: ${areaM2}`);
  }

  if (element.uValue == null) {
    throw new Error(
      'element.uValue обов\'язковий. Резолвинг U — в heatlossByRooms (пресети envelopePresets, wallAssembly).',
    );
  }
  const uValue = toNumber(element.uValue, 'uValue');

  // U = 0 допустим: «теплый пол» между жилыми этажами — теплопотери не считаем (см. пресеты пола).
  if (uValue < 0) {
    throw new Error(`U не може бути від'ємним. Отримано: ${uValue}`);
  }

  const heatLossFactorRaw = element.heatLossFactor ?? 1;
  const heatLossFactor = toNumber(heatLossFactorRaw, 'heatLossFactor');
  if (heatLossFactor <= 0) {
    throw new Error(`heatLossFactor має бути > 0. Отримано: ${heatLossFactor}`);
  }

  const deltaT =
    element.deltaT != null
      ? toNumber(element.deltaT, 'deltaT')
      : toNumber(defaultDeltaT, 'deltaT');

  const baseQWatts = uValue * areaM2 * deltaT;
  const qWatts = baseQWatts * heatLossFactor;

  return {
    name: element.name ?? null,
    construction: element.construction ?? null,
    material: element.material ?? null,
    areaM2,
    uValue,
    deltaT,
    baseQWatts,
    heatLossFactor,
    qWatts,
    kind: element.kind ?? null,
    count: element.count ?? null,
    orientation: element.orientation ?? null,
    openingWidthMm: element.openingWidthMm ?? null,
    openingHeightMm: element.openingHeightMm ?? null,
    ...(element.cornerRoomFactor != null
      ? { cornerRoomFactor: element.cornerRoomFactor }
      : {}),
    ...(element.adjacentTempC !== undefined
      ? { adjacentTempC: element.adjacentTempC }
      : {}),
  };
}

/**
 * Суммарные теплопотери по массиву элементов ограждения.
 *
 * @param {import('../types/shared-types.js').HeatLossCalcInput} input
 * @returns {import('../types/shared-types.js').HeatLossCalcResult}
 */
export function calculateHeatLoss(input) {
  if (!input || typeof input !== 'object') {
    throw new Error('Вхідні дані мають бути об\'єктом.');
  }

  const insideTempC = toNumber(input.insideTempC, 'insideTempC');
  const outsideTempC = toNumber(input.outsideTempC, 'outsideTempC');
  const deltaT = insideTempC - outsideTempC;

  if (!Array.isArray(input.elements)) {
    throw new Error('Поле "elements" має бути масивом.');
  }

  const elementLosses = input.elements.map((el) => calculateElementLoss(el, deltaT));
  const envelopeWatts = elementLosses.reduce((sum, x) => sum + x.qWatts, 0);

  // Резерв вентиляции (kVent) — в heatlossByRooms; здесь только ограждения.
  const ventilationWatts = 0;
  const ventilationMethod = null;
  const totalWatts = envelopeWatts;

  return {
    insideTempC,
    outsideTempC,
    deltaT,
    envelope: {
      watts: envelopeWatts,
      elements: elementLosses,
    },
    ventilation: {
      method: ventilationMethod,
      watts: ventilationWatts,
    },
    totalWatts,
  };
}

/**
 * Назначение: валидация параметров наружных стен объекта.
 * Описание: Проверяет и нормализует objectMeta.externalWalls: фасадная система, пресеты утеплителя (СФТК — ППС 16Ф, вентфасад — минвата), толщины. Экспортирует assertExternalWalls(); вызывается из validate.js после AJV.
 */

import { getEnvelopePresetById } from './envelopePresets.js';
import {
  FACADE_SYSTEMS,
  INSUL_SFTK_PPS16F_ID,
  INSULATION_THICKNESS_BOUNDS,
  isMineralWoolInsulationPresetId,
  isSftkInsulationPresetId,
} from './wallAssembly.js';

/**
 * Нормализация и cross-validation externalWalls (СП 50.13330: СФТК — только ППС 16Ф; открытый фасад — минвата).
 *
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 */
export function assertExternalWalls(building) {
  if (!building?.objectMeta?.externalWalls) return;

  const ew = /** @type {Record<string, unknown>} */ (
    /** @type {unknown} */ (building.objectMeta.externalWalls)
  );

  const presetId = String(ew.presetId ?? '').trim();
  if (!presetId) {
    throw fieldError('EXTERNAL_WALLS_PRESET_REQUIRED', 'Вкажіть building.objectMeta.externalWalls.presetId');
  }

  const wallPreset = getEnvelopePresetById(presetId);
  if (!wallPreset || wallPreset.kind !== 'wall') {
    throw fieldError(
      'EXTERNAL_WALLS_INVALID_PRESET',
      `externalWalls.presetId="${presetId}" має посилатися на пресет kind=wall (несучий шар без утеплювача). Утеплювач задається окремо через facadeSystem + insulationPresetId.`,
    );
  }

  let facadeSystem = ew.facadeSystem;
  if (facadeSystem == null || facadeSystem === '') {
    facadeSystem = 'none';
    ew.facadeSystem = 'none';
  }

  if (!FACADE_SYSTEMS.includes(/** @type {string} */ (facadeSystem))) {
    throw fieldError(
      'EXTERNAL_WALLS_FACADE_SYSTEM',
      `facadeSystem має бути одним із: ${FACADE_SYSTEMS.join(', ')}.`,
    );
  }

  if (facadeSystem === 'none') {
    delete ew.insulationPresetId;
    delete ew.insulationThicknessMm;
    return;
  }

  const insulId = String(ew.insulationPresetId ?? '').trim();
  const insulThickness = ew.insulationThicknessMm;

  if (!insulId) {
    throw fieldError(
      'EXTERNAL_WALLS_INSULATION_REQUIRED',
      `При facadeSystem="${facadeSystem}" вкажіть insulationPresetId.`,
    );
  }

  if (insulThickness == null || !Number.isFinite(Number(insulThickness)) || Number(insulThickness) <= 0) {
    throw fieldError(
      'EXTERNAL_WALLS_INSULATION_THICKNESS',
      `При facadeSystem="${facadeSystem}" вкажіть insulationThicknessMm (мм).`,
    );
  }

  const t = Number(insulThickness);
  if (t < INSULATION_THICKNESS_BOUNDS.min || t > INSULATION_THICKNESS_BOUNDS.max) {
    throw fieldError(
      'EXTERNAL_WALLS_INSULATION_THICKNESS',
      `insulationThicknessMm має бути в діапазоні ${INSULATION_THICKNESS_BOUNDS.min}…${INSULATION_THICKNESS_BOUNDS.max} мм.`,
    );
  }
  ew.insulationThicknessMm = t;

  const insulPreset = getEnvelopePresetById(insulId);
  if (!insulPreset || insulPreset.kind !== 'insulation') {
    throw fieldError(
      'EXTERNAL_WALLS_INSULATION_PRESET',
      `insulationPresetId="${insulId}" має посилатися на пресет kind=insulation.`,
    );
  }

  if (facadeSystem === 'sftk') {
    if (!isSftkInsulationPresetId(insulId)) {
      throw fieldError(
        'EXTERNAL_WALLS_SFTK_INSULATION',
        `Для СФТК («мокрий фасад») допустимий лише ППС 16Ф (ПСБ-С 25Ф): insulationPresetId="${INSUL_SFTK_PPS16F_ID}". ППС-25/35 у відкритому вигляді не застосовуються.`,
      );
    }
  }

  if (facadeSystem === 'ventilated') {
    if (!isMineralWoolInsulationPresetId(insulId)) {
      throw fieldError(
        'EXTERNAL_WALLS_VENTILATED_INSULATION',
        'Для відкритого/вентильованого фасаду допустима лише мінеральна вата (insul_minwool_*).',
      );
    }
  }

  if (wallPreset.uModel && (ew.thicknessMm == null || !(Number(ew.thicknessMm) > 0))) {
    throw fieldError(
      'EXTERNAL_WALLS_WALL_THICKNESS',
      'При утепленому фасаді задайте thicknessMm несучої стіни для розрахунку U по шарах.',
    );
  }

  for (const el of building.envelopeElements ?? []) {
    if (el?.kind !== 'wall') continue;
    const elPreset = el.presetId ? String(el.presetId) : '';
    if (elPreset.startsWith('insul_')) {
      throw fieldError(
        'ENVELOPE_WALL_INSULATION_PRESET',
        `Елемент стіни roomId="${el.roomId}": presetId="${elPreset}" — це утеплювач (kind=insulation), вкажіть пресет несучої стіни.`,
      );
    }
  }
}

/**
 * @param {string} code
 * @param {string} message
 * @returns {Error & import('../types/shared-types.js').AppErrorLike}
 */
function fieldError(code, message) {
  const err = new Error(message);
  /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
  const appErr = err;
  appErr.statusCode = 400;
  appErr.code = code;
  return appErr;
}

/**
 * Назначение: температурные графики системы отопления.
 * Описание: Нормализует heatingSystem по пресетам supply/return/inside и базе ΔT радиаторов; подстраивает график под конденсационный котёл. Реэкспортирует константы из shared/heatingThermalRegimePresets.js. Используется в validate.js, calcInputSchemaLoader.js и matching.
 */

import {
  HEATING_THERMAL_REGIME_PRESETS,
  HEATING_THERMAL_REGIME_PRESET_ENUM,
  defaultThermalRegimePresetForObjectType,
  defaultThermalRegimePresetForMatchingScheme,
  isLowTemperatureThermalRegimePreset,
} from '../../../shared/heatingThermalRegimePresets.js';
import { normalizeRadiatorConnection } from '../../../shared/radiatorConnection.js';
import { normalizeRadiatorEmitterPreference } from '../../../shared/radiatorEmitterPreference.js';
import { isCondensingBoiler } from '../utils/boilerMatchingByType.js';

export {
  HEATING_THERMAL_REGIME_PRESETS,
  HEATING_THERMAL_REGIME_PRESET_ENUM,
  defaultThermalRegimePresetForObjectType,
  defaultThermalRegimePresetForMatchingScheme,
  isLowTemperatureThermalRegimePreset,
};

/**
 * Проверка идентификатора пресета.
 * @param {string | undefined | null} id
 * @returns {boolean}
 */
export function isHeatingThermalRegimePresetId(id) {
  return (
    typeof id === 'string'
    && Object.prototype.hasOwnProperty.call(HEATING_THERMAL_REGIME_PRESETS, id)
  );
}

/**
 * Нормализация heatingSystem: пресет задаёт подачу/обратку и (если не указано) базу ΔT каталога радиатора;
 * t внутри для расчёта излучателей подставляется из building.temps при отсутствии heatingSystem.insideC.
 * Без пресета: квартира — 55/45 (конденсация); дом — 75/65 (прежнее поведение).
 *
 * @param {import('../types/shared-types.js').CalcRequestBody} body
 */
export function normalizeHeatingSystemThermalRegime(body) {
  const hs = body.heatingSystem;
  if (!hs || typeof hs !== 'object') return;

  const buildingInside = body.building?.temps?.insideC;
  if (
    hs.insideC == null
    && typeof buildingInside === 'number'
    && Number.isFinite(buildingInside)
  ) {
    hs.insideC = buildingInside;
  }

  if (!isHeatingThermalRegimePresetId(hs.thermalRegimePreset)) {
    const objectType = body.building?.objectMeta?.objectType;
    const isUfhOnly =
      hs.heatingEmittersMode === 'ufh_only' || hs.ufhPresetId === 'ufh_only';
    if (!isUfhOnly) {
      hs.thermalRegimePreset = defaultThermalRegimePresetForMatchingScheme(
        hs.hotWaterBoilerPowerMatchingScheme,
        objectType,
      );
    }
  }

  // Подача/зворот з радіаторного пресета; для ufh_only їх перезапише normalizeHeatingUfhPreset (40/30).
  const regimePresetId = hs.thermalRegimePreset;
  if (regimePresetId != null && isHeatingThermalRegimePresetId(regimePresetId)) {
    const p = HEATING_THERMAL_REGIME_PRESETS[regimePresetId];
    if (p) {
      hs.supplyC = p.supplyC;
      hs.returnC = p.returnC;
      if (hs.radiatorReferenceDeltaT == null) {
        hs.radiatorReferenceDeltaT = p.defaultRadiatorReferenceDeltaT;
      }
    }
  } else {
    if (hs.supplyC == null) hs.supplyC = 75;
    if (hs.returnC == null) hs.returnC = 65;
  }

  hs.radiatorConnection = normalizeRadiatorConnection(hs.radiatorConnection);
  hs.radiatorEmitterPreference = normalizeRadiatorEmitterPreference(
    hs.radiatorEmitterPreference,
  );
}

/**
 * @param {import('../types/shared-types.js').HeatingSystemInput} hs
 * @returns {string} Человекочитаемая метка текущего графика для сообщений.
 */
function formatHeatingGraphLabel(hs) {
  const presetId = hs.thermalRegimePreset;
  if (presetId != null && isHeatingThermalRegimePresetId(presetId)) {
    return presetId;
  }
  const s = hs.supplyC;
  const r = hs.returnC;
  if (typeof s === 'number' && typeof r === 'number') {
    return `${s}/${r} °C`;
  }
  return 'високотемпературний';
}

/**
 * Высокотемпературный график (не подходит для устойчивой конденсации).
 * Фактические supplyC/returnC приоритетнее лейбла thermalRegimePreset
 * (после ufh_only нормализация пишет 40/30, пресет может ещё не совпадать).
 * @param {import('../types/shared-types.js').HeatingSystemInput | undefined} hs
 * @returns {boolean}
 */
export function isHighTemperatureHeatingGraph(hs) {
  if (!hs || typeof hs !== 'object') return false;
  const supply = Number(hs.supplyC);
  const ret = Number(hs.returnC);
  if (Number.isFinite(supply) && Number.isFinite(ret)) {
    if (ret < 55 && supply < 65) return false;
    if (ret >= 55 || supply >= 65) return true;
  }
  if (hs.thermalRegimePreset === 'condensing_dt30_55_45') return false;
  if (
    hs.thermalRegimePreset === 'traditional_dt50_75_65' ||
    hs.thermalRegimePreset === 'traditional_high_dt70_95_85'
  ) {
    return true;
  }
  if (Number.isFinite(ret) && ret >= 55) return true;
  if (Number.isFinite(supply) && supply >= 65) return true;
  return false;
}

/**
 * Подставляет пресет в heatingSystem (подача, обратка, база ΔT каталога).
 * @param {import('../types/shared-types.js').HeatingSystemInput} hs
 * @param {import('../types/shared-types.js').HeatingThermalRegimePreset} presetId
 * @returns {boolean}
 */
export function applyThermalRegimePresetToHeatingSystem(hs, presetId) {
  if (!hs || typeof hs !== 'object') return false;
  if (!isHeatingThermalRegimePresetId(presetId)) return false;
  const p = HEATING_THERMAL_REGIME_PRESETS[presetId];
  if (!p) return false;
  hs.thermalRegimePreset = presetId;
  hs.supplyC = p.supplyC;
  hs.returnC = p.returnC;
  hs.radiatorReferenceDeltaT = p.defaultRadiatorReferenceDeltaT;
  return true;
}

/**
 * Если подобран конденсационный котёл, а график высокотемпературный — предупреждение без подмены input.
 *
 * @param {import('../types/shared-types.js').HeatingSystemInput | undefined} heatingSystem
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized | null | undefined} selectedBoiler
 * @returns {string | null} Текст предупреждения или null
 */
export function alignHeatingGraphForCondensingBoiler(heatingSystem, selectedBoiler) {
  if (!heatingSystem || typeof heatingSystem !== 'object' || !selectedBoiler) {
    return null;
  }
  if (!isCondensingBoiler(selectedBoiler)) return null;
  if (!isHighTemperatureHeatingGraph(heatingSystem)) return null;
  if (heatingSystem.heatingEmittersMode === 'ufh_only') return null;

  const previousLabel = formatHeatingGraphLabel(heatingSystem);
  const model =
    typeof selectedBoiler.model === 'string' ? selectedBoiler.model : 'котел';
  return (
    `Підібрано конденсаційний котел ${model}, а радіаторний графік високотемпературний (${previousLabel}). ` +
    'При звороті вище ~55 °C конденсація і заявлений ККД можуть не досягатися. Розрахунок радіаторів виконано за обраним графіком.'
  );
}

/**
 * Назначение: расчёт теплопотерь здания по комнатам.
 * Описание: Собирает envelopeElements с U из пресетов, objectMeta.externalWalls и ориентационных поправок; учитывает границы комнат и запас на вентиляцию (kVent). Экспортирует calculateHeatLossForBuilding(); вызывается из report/buildReport.js.
 */

import { calculateHeatLoss } from './envelopeHeatLoss.js';
import { getEnvelopePresetById } from './envelopePresets.js';
import {
  INTERNAL_CORRIDOR_DESIGN_TEMP_C,
  isInternalCorridorWallConstruction,
  resolveElementDeltaT,
  resolveElementHeatLossFactors,
  resolveElementUValue,
  resolveRoomExteriorLayout,
} from './roomExteriorLayoutHeatLoss.js';
import { resolveExternalWallUValue } from './wallAssembly.js';
import { envelopeKindIncludedForHeatLoss } from './topBoundaryEnvelope.js';
import {
  normalizeVentilationReserveMode,
  resolveKVent,
  ventilationReserveModeLabel,
} from './ventilationReserve.js';
import { logger } from '../utils/logger.js';
import { resolveDesignRoomAirTempC } from '../../../shared/roomDesignAirTemp.js';

/**
 * Расчёт теплопотерь с детализацией по комнатам.
 *
 * Вход:
 * - temps (inside/outside)
 * - building.rooms + building.envelopeElements
 *
 * Выход:
 * - общие теплопотери
 * - теплопотери по каждой комнате
 * - список элементов ограждений с привязкой к комнате
 */

/**
 * @param {number[]} numbers
 * @returns {number}
 */
function sum(numbers) {
  return numbers.reduce((/** @type {number} */ a, /** @type {number} */ b) => a + b, 0);
}

/**
 * @param {import('../types/shared-types.js').EnvelopePresetUModel} model
 * @param {number} thicknessMm
 * @returns {number}
 */
function computeUFromThickness(model, thicknessMm) {
  const dM = thicknessMm / 1000;
  const extraR = model.extraR ?? 0;
  const rTotal = model.surfaceR + extraR + dM / model.lambdaWmK;
  return 1 / rTotal;
}

/**
 * @param {object} args
 * @param {{ insideC: number, outsideC: number, bathroomAirTempC?: number }} args.temps
 * @param {import('../types/shared-types.js').BuildingInput} args.building
 * @returns {import('../types/shared-types.js').HeatLossReport}
 */
export function calculateHeatLossForBuilding({ temps, building }) {
  const insideC = temps.insideC;
  const outsideC = temps.outsideC;
  const bathroomAirTempC =
    typeof temps.bathroomAirTempC === 'number' && Number.isFinite(temps.bathroomAirTempC)
      ? temps.bathroomAirTempC
      : typeof building?.temps?.bathroomAirTempC === 'number' &&
          Number.isFinite(building.temps.bathroomAirTempC)
        ? building.temps.bathroomAirTempC
        : undefined;

  logger.debug('heatloss.building.start', null, {
    insideC,
    outsideC,
    bathroomAirTempC: bathroomAirTempC ?? null,
    rooms: building?.rooms?.length ?? 0,
    elements: building?.envelopeElements?.length ?? 0,
  });

  const roomsById = new Map(building.rooms.map((r) => [r.id, r]));
  /** @type {Map<string, { designAirTempC: number, source: import('../types/shared-types.js').DesignRoomAirTempSource }>} */
  const roomAirById = new Map();
  for (const room of building.rooms) {
    const resolved = resolveDesignRoomAirTempC({
      roomType: room.type,
      insideC,
      ...(bathroomAirTempC !== undefined ? { bathroomAirTempC } : {}),
    });
    if (resolved) roomAirById.set(room.id, resolved);
  }
  const roomLayoutById = new Map(
    building.rooms.map((r) => [
      r.id,
      resolveRoomExteriorLayout(r, building.envelopeElements ?? []),
    ]),
  );
  const allElements = [...(building.envelopeElements ?? [])];

  const normalizedElements = allElements.map((el) => {
    const room = roomsById.get(el.roomId);
    if (!room) {
      const err = new Error(`Невідоме приміщення roomId="${el.roomId}"`);
      /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
      const appErr = err;
      appErr.statusCode = 400;
      appErr.code = 'UNKNOWN_ROOM';
      throw appErr;
    }

    const preset = el.presetId ? getEnvelopePresetById(el.presetId) : null;

    const elementThicknessMm = el.thicknessMm ?? null;
    const defaultWallThicknessMm = building.objectMeta?.externalWalls?.thicknessMm ?? null;
    const thicknessMmToUse =
      elementThicknessMm != null
        ? elementThicknessMm
        : preset?.kind === 'wall'
          ? defaultWallThicknessMm
          : null;

    const kindForRule = /** @type {'wall' | 'window' | 'ceiling' | 'floor' | 'roof' | undefined} */ (
      el.kind ?? preset?.kind ?? undefined
    );

    let uValue =
      el.uValue ??
      (kindForRule === 'wall' && building.objectMeta?.externalWalls
        ? resolveExternalWallUValue(building.objectMeta.externalWalls, el.presetId ?? undefined)
        : preset?.uModel && thicknessMmToUse != null
          ? computeUFromThickness(preset.uModel, thicknessMmToUse)
          : preset?.uValue ?? null);

    if (uValue == null) {
      const err = new Error(
        `Некоректний елемент огородження: не задано uValue і не вдалося вивести його з presetId/thickness (roomId="${el.roomId}", construction="${el.construction}")`,
      );
      /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
      const appErr = err;
      appErr.statusCode = 400;
      appErr.code = 'ENVELOPE_UVALUE_MISSING';
      throw appErr;
    }

    const constructionResolved = el.construction ?? preset?.construction ?? null;
    uValue = resolveElementUValue(uValue, constructionResolved) ?? uValue;

    const roomInput = /** @type {import('../types/shared-types.js').RoomInput} */ (room);
    const tb = /** @type {'heated' | 'unheated' | 'roof'} */ (roomInput.topBoundary);
    const bb = /** @type {'heated' | 'unheated'} */ (
      roomInput.bottomBoundary ?? 'unheated'
    );
    if (!envelopeKindIncludedForHeatLoss({ topBoundary: tb, bottomBoundary: bb, kind: kindForRule })) {
      logger.debug('heatloss.envelope.skipped_boundary', null, {
        roomId: room.id,
        topBoundary: tb,
        bottomBoundary: bb,
        kind: kindForRule,
        construction: el.construction ?? null,
      });
      uValue = 0;
    }

    return {
      name: el.name ?? null,
      roomId: el.roomId,
      roomName: room.name,
      construction: el.construction ?? preset?.construction ?? null,
      material: el.material ?? preset?.material ?? null,
      kind: el.kind ?? preset?.kind ?? null,
      count: el.count ?? 1,
      orientation: el.orientation ?? null,
      openingWidthMm: el.openingWidthMm ?? null,
      openingHeightMm: el.openingHeightMm ?? null,
      areaM2: el.areaM2 * (el.count ?? 1),
      uValue,
      roomLayout: roomLayoutById.get(el.roomId) ?? 'facade',
    };
  });

  const ventilationReserveMode = normalizeVentilationReserveMode(
    building.objectMeta?.ventilationReserveMode,
  );
  const kVent = resolveKVent(ventilationReserveMode);

  const heatLoss = calculateHeatLoss({
    insideTempC: insideC,
    outsideTempC: outsideC,
    elements: normalizedElements.map((e) => {
      const construction = e.construction;
      const roomAir = roomAirById.get(e.roomId);
      const roomInsideC = roomAir?.designAirTempC ?? insideC;
      const elementDeltaT = resolveElementDeltaT({
        insideC: roomInsideC,
        outsideC,
        construction,
      });
      const { heatLossFactor, cornerRoomFactor } = resolveElementHeatLossFactors({
        kind: e.kind,
        orientation: e.orientation,
        construction,
        roomLayout: e.roomLayout,
      });
      const adjacentTempC = isInternalCorridorWallConstruction(construction)
        ? INTERNAL_CORRIDOR_DESIGN_TEMP_C
        : outsideC;

      /** @type {import('../types/shared-types.js').HeatLossCalcElementInput['kind']} */
      const kind =
        e.kind === 'wall'
        || e.kind === 'window'
        || e.kind === 'ceiling'
        || e.kind === 'floor'
        || e.kind === 'roof'
          ? e.kind
          : null;

      /** @type {import('../types/shared-types.js').HeatLossCalcElementInput} */
      const element = {
        name: e.name,
        construction: e.construction,
        material: e.material,
        areaM2: e.areaM2,
        uValue: e.uValue,
        kind,
        count: e.count,
        orientation: e.orientation,
        openingWidthMm: e.openingWidthMm,
        openingHeightMm: e.openingHeightMm,
        deltaT: elementDeltaT,
        heatLossFactor,
        cornerRoomFactor,
        adjacentTempC,
      };
      return element;
    }),
    ventilation: null,
  });

  const elementsWithRoom = heatLoss.envelope.elements.map((calcEl, idx) => {
    const normalized = normalizedElements[idx];
    if (!normalized) {
      throw new Error(`heatloss: отсутствует normalizedElements[${idx}]`);
    }
    return {
      ...calcEl,
      roomId: normalized.roomId,
      roomName: normalized.roomName,
    };
  });

  const rooms = building.rooms.map((room) => {
    const els = elementsWithRoom.filter((x) => x.roomId === room.id);
    const envelopeWatts = sum(els.map((x) => x.qWatts));
    const designWatts = envelopeWatts * kVent;
    const air = roomAirById.get(room.id);
    return {
      id: room.id,
      name: room.name,
      type: room.type,
      areaM2: room.areaM2,
      heightM: room.heightM,
      volumeM3: room.areaM2 * room.heightM,
      designAirTempC: air?.designAirTempC ?? insideC,
      designAirTempSource: air?.source ?? 'survey',
      envelopeWatts,
      ventilationReserveFactor: kVent,
      designWatts,
      elements: els,
    };
  });

  const totalWatts = sum(rooms.map((r) => r.designWatts));

  logger.debug('heatloss.building.kVent', null, {
    ventilationReserveMode,
    kVent,
    envelopeWatts: heatLoss.envelope.watts,
    totalWatts,
  });

  return {
    insideC,
    outsideC,
    deltaT: heatLoss.deltaT,
    ventilation: {
      method: 'kVentPerRoom',
      watts: 0,
      ventilationReserveMode,
      kVent,
      label: ventilationReserveModeLabel(ventilationReserveMode),
    },
    envelopeWatts: heatLoss.envelope.watts,
    totalWatts,
    rooms,
  };
}

/**
 * Назначение: расчёт горячего водоснабжения (ГВС).
 * Описание: По типу объекта (квартира/дом) и справочнику water_norms считает пиковую мощность, объём бака и параметры сеансов через dhw/waterCalc.js. Экспортирует calculateHotWaterDemand(); результат попадает в report.calculations.hotWater и matching.
 */

import {
  equivalentStorageTankLitersFromSession,
  estimatePeakSessionLitersMixed,
  hotWaterThermalPowerKw,
  recommendedStorageTankLitersRaw,
  simultaneityFactor,
  tankVolumeHeatPowerKw,
} from '../dhw/waterCalc.js';

/**
 * @param {number} value
 * @param {number} min
 * @param {number} max
 */
function clampInteger(value, min, max) {
  const n = Number.isFinite(value) ? Math.trunc(value) : 0;
  return Math.max(min, Math.min(max, n));
}

/**
 * @param {import('../types/shared-types.js').HotWaterInput & { objectType?: string }} input
 * @param {import('../dhw/types.js').NormalizedWaterNorms} norms
 * @param {{ dhwSupplyScenarioOverride?: 'flowThrough' | 'storage' }} [options]
 * @returns {import('../types/shared-types.js').HotWaterReport}
 */
export function calculateHotWaterDemand(input = {}, norms, options = {}) {
  if (!norms) {
    throw new Error('calculateHotWaterDemand: не передан справочник water_norms');
  }

  const objectType =
    input.objectType === 'apartment' || input.objectType === 'house'
      ? input.objectType
      : 'house';

  const dhwSupplyScenario =
    options.dhwSupplyScenarioOverride ??
    norms.objectTypes[objectType]?.dhwSupplyScenario ??
    (objectType === 'apartment' ? 'flowThrough' : 'storage');

  const residents = clampInteger(input.residents ?? 0, 0, 20);

  const fx = input.fixtures ?? {};
  const fixtures = {
    shower: clampInteger(fx.shower ?? 0, 0, 30),
    bath: clampInteger(fx.bath ?? 0, 0, 30),
    sink: clampInteger(fx.sink ?? 0, 0, 30),
    toilet: clampInteger(fx.toilet ?? 0, 0, 30),
    kitchenSink: clampInteger(fx.kitchenSink ?? 0, 0, 30),
    dishwasher: clampInteger(fx.dishwasher ?? 0, 0, 30),
    laundrySink: clampInteger(fx.laundrySink ?? 0, 0, 30),
    washingMachine: clampInteger(fx.washingMachine ?? 0, 0, 30),
    bidet: clampInteger(fx.bidet ?? 0, 0, 30),
  };

  const tropicalShower = Boolean(input.tropicalShower);

  const coldWaterDesignSeason =
    input.coldWaterDesignSeason === 'summer' ? 'summer' : 'winter';
  const coldClamped =
    coldWaterDesignSeason === 'summer'
      ? norms.coldWaterDesignC.summer
      : norms.coldWaterDesignC.winter;

  const hotDefault = norms.hotWaterC.default;
  const hotWaterC = input.hotWaterC != null ? Number(input.hotWaterC) : hotDefault;
  const hotClamped = Math.max(
    norms.hotWaterC.min,
    Math.min(norms.hotWaterC.max, hotWaterC),
  );

  const deltaTK = Math.max(0, hotClamped - coldClamped);

  let sumFlowLpsRaw = 0;
  let thermalFixtureCount = 0;
  let maxSingleFlowLps = 0;

  const excludedForApartment = new Set(
    norms.hotThermalFixtureKeysExcludedForApartment ?? [],
  );
  const thermalKeys =
    objectType === 'apartment'
      ? norms.hotThermalFixtureKeys.filter((k) => !excludedForApartment.has(k))
      : norms.hotThermalFixtureKeys;

  for (const key of thermalKeys) {
    const count = fixtures[/** @type {keyof typeof fixtures} */ (key)] ?? 0;
    if (count <= 0) continue;
    const unitFlow = norms.fixtureHotFlowLps[key] ?? 0;
    if (unitFlow <= 0) continue;
    thermalFixtureCount += count;
    sumFlowLpsRaw += count * unitFlow;
    maxSingleFlowLps = Math.max(maxSingleFlowLps, unitFlow);
  }

  const beta = simultaneityFactor(
    norms,
    objectType,
    thermalFixtureCount,
    residents,
  );

  const reduced = sumFlowLpsRaw * beta;
  const peakFlowLps = Math.max(reduced, maxSingleFlowLps);

  const peakThermalPowerKw = Number(
    hotWaterThermalPowerKw(norms, peakFlowLps, deltaTK).toFixed(2),
  );

  const typicalTankSizes = norms.storage.typicalTankSizes;

  /** @type {number} */
  let recommendedTankLiters;
  /** @type {number | undefined} */
  let sessionDemandLitersMixed;
  /** @type {number | undefined} */
  let dhwEquivalentTankLitersFromSession;
  /** @type {number | undefined} */
  let dhwTankLitersCombinedRaw;

  if (dhwSupplyScenario === 'flowThrough') {
    recommendedTankLiters = 0;
  } else {
    // Множник tropicalShower — один раз до combinedRaw (не в legacy-формулі).
    const rawTankLegacy = recommendedStorageTankLitersRaw(
      norms,
      residents,
      fixtures.bath,
    );
    sessionDemandLitersMixed = estimatePeakSessionLitersMixed(
      norms,
      fixtures,
      residents,
    );
    dhwEquivalentTankLitersFromSession = equivalentStorageTankLitersFromSession(
      norms,
      sessionDemandLitersMixed,
    );
    let combinedRaw = Math.max(
      rawTankLegacy,
      dhwEquivalentTankLitersFromSession,
    );
    if (tropicalShower) {
      combinedRaw = Math.ceil(
        combinedRaw * norms.storage.tropicalShowerVolumeFactor,
      );
    }
    dhwTankLitersCombinedRaw = combinedRaw;

    const fallbackTank =
      typicalTankSizes[typicalTankSizes.length - 1];
    if (fallbackTank === undefined) {
      throw new Error('water_norms.storage.typicalTankSizes пуст');
    }
    recommendedTankLiters =
      typicalTankSizes.find((t) => t >= combinedRaw) ??
      fallbackTank;
  }

  let hotWaterPowerKw;
  /** @type {number | undefined} */
  let storageHeatTimeMinutes;
  /** @type {number | undefined} */
  let storageIndirectHeatPowerKw;

  const heatMinutes = norms.storage.indirectHeatTimeMinutes;
  const dhwMinKw = norms.storage.boilerDhwPowerMinKw;

  if (dhwSupplyScenario === 'flowThrough') {
    hotWaterPowerKw = peakThermalPowerKw;
  } else {
    storageHeatTimeMinutes = heatMinutes;
    storageIndirectHeatPowerKw = Number(
      tankVolumeHeatPowerKw(norms, recommendedTankLiters, deltaTK, heatMinutes).toFixed(
        2,
      ),
    );
    hotWaterPowerKw = Number(
      Math.max(dhwMinKw, storageIndirectHeatPowerKw).toFixed(2),
    );
  }

  const objectNorms = norms.objectTypes[objectType] ?? norms.objectTypes.house;

  return {
    objectType,
    residents,
    fixtures,
    tropicalShower,
    coldWaterDesignSeason,
    dhwSupplyScenario,
    designColdWaterC: Number(coldClamped.toFixed(1)),
    hotWaterC: Number(hotClamped.toFixed(1)),
    deltaTK: Number(deltaTK.toFixed(1)),
    sumFlowLpsRaw: Number(sumFlowLpsRaw.toFixed(3)),
    simultaneityFactor: Number(beta.toFixed(3)),
    peakFlowLps: Number(peakFlowLps.toFixed(3)),
    peakThermalPowerKw,
    hotWaterPowerKw,
    recommendedTankLiters,
    normsSchemaVersion: norms.schemaVersion,
    ...(dhwSupplyScenario === 'storage'
      ? {
          storageTankLitersPerPersonBasis: norms.storage.litersPerResident,
          ...(storageHeatTimeMinutes !== undefined
            ? { storageHeatTimeMinutes }
            : {}),
          ...(storageIndirectHeatPowerKw !== undefined
            ? { storageIndirectHeatPowerKw }
            : {}),
          ...(sessionDemandLitersMixed !== undefined
            ? { sessionDemandLitersMixed }
            : {}),
          ...(dhwEquivalentTankLitersFromSession !== undefined
            ? { dhwEquivalentTankLitersFromSession }
            : {}),
          ...(dhwTankLitersCombinedRaw !== undefined
            ? { dhwTankLitersCombinedRaw }
            : {}),
        }
      : {}),
    simultaneityBaseNorm: objectNorms.simultaneityBase,
  };
}

/**
 * Назначение: нормализация heatingSystem.ufhPresetId и heatingEmittersMode.
 * Описание: Lookup пресета из переданного bundle; для «только ТП» — график котла 40/30 и согласованный thermalRegimePreset (без рассинхрона с 75/65).
 */
import { UFH_PRESET_ONLY, ufhModePresetIsMixedRadiators } from '../../../shared/ufhModePresetIds.js';
import { thermalRegimeRecommendationHint } from '../../../shared/heatingThermalRegimeRecommendations.js';

/**
 * @param {import('../types/shared-types.js').CalcRequestBody} body
 * @param {import('../ufh/types.js').UnderfloorHeatingPresetsBundle} ufhPresets
 */
export function normalizeHeatingUfhPreset(body, ufhPresets) {
  const hs = body.heatingSystem;
  if (!hs || typeof hs !== 'object') return;

  const presetId = typeof hs.ufhPresetId === 'string' ? hs.ufhPresetId.trim() : '';
  if (!presetId) return;

  if (!ufhPresets?.byPresetId) {
    throw new Error('Архитектурная ошибка: ufhPresets обязательны для нормализации ТП.');
  }

  const preset = ufhPresets.byPresetId[presetId];
  if (!preset) {
    const err = new Error(`Неизвестный ufhPresetId "${presetId}".`);
    /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
    const appErr = err;
    appErr.statusCode = 400;
    appErr.code = 'UFH_PRESET_INVALID';
    throw appErr;
  }

  hs.waterUnderfloorHeating = true;

  if (!hs.heatingEmittersMode) {
    hs.heatingEmittersMode =
      presetId === UFH_PRESET_ONLY ? 'ufh_only' : 'mixed';
  }

  if (ufhModePresetIsMixedRadiators(presetId) && hs.heatingEmittersMode !== 'ufh_only') {
    hs.heatingEmittersMode = 'mixed';
  }

  if (presetId === UFH_PRESET_ONLY) {
    const tech = preset.technical;
    hs.heatingEmittersMode = 'ufh_only';
    hs.supplyC = tech.supplyC;
    hs.returnC = tech.returnC;
    // Радіаторний пресет (у т.ч. 75/65) не повинен лишатися поруч із фактичним 40/30.
    hs.thermalRegimePreset = 'condensing_dt30_55_45';
  }

  /** @type {string[]} */
  const normWarnings = [];
  const scheme = hs.hotWaterBoilerPowerMatchingScheme;
  const objectType = body.building?.objectMeta?.objectType;
  const thermalHint = thermalRegimeRecommendationHint(
    scheme,
    objectType,
    hs.thermalRegimePreset,
  );
  if (thermalHint && hs.heatingEmittersMode !== 'ufh_only') {
    normWarnings.push(thermalHint);
  }

  if (preset.technical.requiresCondensingBoiler) {
    normWarnings.push(
      `Режим «${preset.ui.title}» розрахований на конденсаційний котел (низькотемпературний контур ${preset.technical.supplyC}/${preset.technical.returnC} °C).`,
    );
  }

  if (normWarnings.length) {
    const existing = Array.isArray(hs._normalizationWarnings)
      ? hs._normalizationWarnings
      : [];
    hs._normalizationWarnings = [...existing, ...normWarnings];
  }
}

/**
 * Подсказка при явном thermalRegimePreset, расходящемся с рекомендацией схемы.
 *
 * @param {import('../types/shared-types.js').CalcRequestBody} body
 */
export function appendThermalRegimeSchemeWarnings(body) {
  const hs = body.heatingSystem;
  if (!hs || typeof hs !== 'object' || hs.ufhPresetId) return;
  if (hs.heatingEmittersMode === 'ufh_only') return;

  const hint = thermalRegimeRecommendationHint(
    hs.hotWaterBoilerPowerMatchingScheme,
    body.building?.objectMeta?.objectType,
    hs.thermalRegimePreset,
  );
  if (!hint) return;

  const existing = Array.isArray(hs._normalizationWarnings)
    ? hs._normalizationWarnings
    : [];
  if (existing.includes(hint)) return;
  hs._normalizationWarnings = [...existing, hint];
}

/**
 * Назначение: поправки теплопотерь по положению комнаты (roomExteriorLayout).
 * Описание: Угловой множитель на wall/window, пониженный ΔT и U для стены в неотапливаемый корidor.
 */

import { heatLossFactorForEnvelopeKind, ORIENTATION_KINDS } from './orientationHeatLoss.js';

/** Совпадает с frontend INTERNAL_CORRIDOR_WALL_CONSTRUCTION. */
export const INTERNAL_CORRIDOR_WALL_CONSTRUCTION = 'стена в неотапливаемый коридор';

/** Множитель угловой комнаты (5–10 % к wall/window поверх β ориентации). */
export const CORNER_ROOM_HEAT_LOSS_FACTOR = 1.08;

/** Расчётная температура неотапливаемого коридора/подъезда, °C (зима). */
export const INTERNAL_CORRIDOR_DESIGN_TEMP_C = 15;

/** @type {ReadonlySet<string>} */
export const ROOM_EXTERIOR_LAYOUTS = new Set(['corner', 'facade', 'internal']);

/**
 * @param {string | null | undefined} construction
 * @returns {boolean}
 */
export function isInternalCorridorWallConstruction(construction) {
  return (
    String(construction ?? '')
      .trim()
      .toLowerCase() === INTERNAL_CORRIDOR_WALL_CONSTRUCTION.toLowerCase()
  );
}

/**
 * @param {string | null | undefined} construction
 * @returns {boolean}
 */
function isFacadeExteriorWallConstruction(construction) {
  const c = String(construction ?? '').trim().toLowerCase();
  if (!c) return true;
  if (isInternalCorridorWallConstruction(c)) return false;
  return c.includes('наруж') || c.includes('фасад') || c === 'wall';
}

/**
 * Подсчёт фасадных и корidorных стен комнаты во входе API.
 *
 * @param {import('../types/shared-types.js').EnvelopeElementInput[]} elements
 * @param {string} roomId
 * @returns {{ facadeWallCount: number, internalWallCount: number }}
 */
export function countExteriorWallsForRoom(elements, roomId) {
  let facadeWallCount = 0;
  let internalWallCount = 0;
  for (const el of elements ?? []) {
    if (!el || el.roomId !== roomId) continue;
    const kind = el.kind ?? null;
    if (kind != null && kind !== 'wall') continue;
    if (isInternalCorridorWallConstruction(el.construction)) {
      internalWallCount += 1;
    } else if (isFacadeExteriorWallConstruction(el.construction)) {
      facadeWallCount += 1;
    }
  }
  return { facadeWallCount, internalWallCount };
}

/**
 * Вывод layout по envelopeElements (legacy API без поля в room).
 *
 * @param {{ facadeWallCount: number, internalWallCount: number }} counts
 * @returns {'corner' | 'facade' | 'internal'}
 */
export function inferRoomExteriorLayoutFromWallCounts(counts) {
  if (counts.internalWallCount > 0 && counts.facadeWallCount === 0) {
    return 'internal';
  }
  if (counts.facadeWallCount >= 2) return 'corner';
  return 'facade';
}

/**
 * @param {import('../types/shared-types.js').RoomInput} room
 * @param {import('../types/shared-types.js').EnvelopeElementInput[]} elements
 * @returns {'corner' | 'facade' | 'internal'}
 */
export function resolveRoomExteriorLayout(room, elements) {
  const raw = room.roomExteriorLayout;
  if (typeof raw === 'string' && ROOM_EXTERIOR_LAYOUTS.has(raw)) {
    return /** @type {'corner' | 'facade' | 'internal'} */ (raw);
  }
  return inferRoomExteriorLayoutFromWallCounts(
    countExteriorWallsForRoom(elements, room.id),
  );
}

/**
 * ΔT для элемента ограждения.
 *
 * @param {object} args
 * @param {number} args.insideC
 * @param {number} args.outsideC
 * @param {string | null | undefined} args.construction
 * @returns {number}
 */
export function resolveElementDeltaT({ insideC, outsideC, construction }) {
  if (isInternalCorridorWallConstruction(construction)) {
    return insideC - INTERNAL_CORRIDOR_DESIGN_TEMP_C;
  }
  return insideC - outsideC;
}

/**
 * U для элемента (internal — тот же расчёт фасада из objectMeta; основной эффект — ΔT).
 *
 * @param {number | null | undefined} resolvedU
 * @param {string | null | undefined} _construction
 * @returns {number | null}
 */
export function resolveElementUValue(resolvedU, _construction) {
  return resolvedU ?? null;
}

/**
 * Итоговый heatLossFactor: β ориентации × множитель угловой комнаты.
 * Для стены в корidor — 1 (ориентация к улице не применяется).
 *
 * @param {object} args
 * @param {string | null | undefined} args.kind
 * @param {string | null | undefined} args.orientation
 * @param {string | null | undefined} args.construction
 * @param {'corner' | 'facade' | 'internal'} args.roomLayout
 * @returns {{ heatLossFactor: number, cornerRoomFactor: number }}
 */
export function resolveElementHeatLossFactors({
  kind,
  orientation,
  construction,
  roomLayout,
}) {
  if (isInternalCorridorWallConstruction(construction)) {
    return { heatLossFactor: 1, cornerRoomFactor: 1 };
  }

  const kindStr = String(kind ?? '');
  if (!ORIENTATION_KINDS.has(kindStr)) {
    return { heatLossFactor: 1, cornerRoomFactor: 1 };
  }

  const orientationFactor = heatLossFactorForEnvelopeKind(kindStr, orientation);
  if (roomLayout === 'corner') {
    return {
      heatLossFactor: orientationFactor * CORNER_ROOM_HEAT_LOSS_FACTOR,
      cornerRoomFactor: CORNER_ROOM_HEAT_LOSS_FACTOR,
    };
  }
  return { heatLossFactor: orientationFactor, cornerRoomFactor: 1 };
}

/**
 * Валидация согласованности layout и числа стен.
 *
 * @param {import('../types/shared-types.js').BuildingInput} building
 */
export function assertRoomExteriorLayoutWalls(building) {
  const rooms = building?.rooms ?? [];
  const elements = building?.envelopeElements ?? [];

  for (const room of rooms) {
    const layout = resolveRoomExteriorLayout(room, elements);
    const { facadeWallCount, internalWallCount } = countExteriorWallsForRoom(
      elements,
      room.id,
    );

    /** @type {string | null} */
    let message = null;

    if (layout === 'internal') {
      if (facadeWallCount > 0) {
        message = `Приміщення "${room.name}" (${room.id}): layout=internal, але задано фасадних стін: ${facadeWallCount}.`;
      } else if (internalWallCount !== 1) {
        message = `Приміщення "${room.name}" (${room.id}): layout=internal вимагає рівно одну стіну в коридор, отримано: ${internalWallCount}.`;
      }
    } else if (layout === 'facade') {
      if (internalWallCount > 0) {
        message = `Приміщення "${room.name}" (${room.id}): layout=facade не допускає стіну в коридор.`;
      } else if (facadeWallCount !== 1) {
        message = `Приміщення "${room.name}" (${room.id}): layout=facade вимагає одну фасадну стіну, отримано: ${facadeWallCount}.`;
      }
    } else if (layout === 'corner') {
      if (internalWallCount > 0) {
        message = `Приміщення "${room.name}" (${room.id}): layout=corner не допускає стіну в коридор.`;
      } else if (facadeWallCount !== 2) {
        message = `Приміщення "${room.name}" (${room.id}): layout=corner вимагає дві фасадні стіни, отримано: ${facadeWallCount}.`;
      }
    }

    if (message) {
      const err = new Error(message);
      /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
      const appErr = err;
      appErr.statusCode = 400;
      appErr.code = 'ROOM_EXTERIOR_LAYOUT_WALLS';
      throw appErr;
    }
  }
}

/**
 * Нормализация roomExteriorLayout на комнатах (если не задан — infer).
 *
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 */
export function normalizeRoomExteriorLayouts(building) {
  if (!building?.rooms) return;
  const elements = building.envelopeElements ?? [];
  for (const room of building.rooms) {
    room.roomExteriorLayout = resolveRoomExteriorLayout(room, elements);
  }
}

/**
 * Назначение: гидравлическая проверка петель ТП (СП 60.13330 / ГОСТ Р 70834-2023, MVP).
 * Описание: Расход по Q/(c·Δt), подбор трубы из каталога, v и Δp (Darcy + повороты 90°).
 * Автооптимизация: число петель (v ↔ Δp) и Ø (мин. номинал из appliances, типично 16 мм).
 */

import { pickPipeForEdge } from '../hydraulics/pickPipe.js';
import {
  computeSegmentHydraulics,
  pipeInternalDiameterMm,
  resolveRoughnessMm,
} from '../hydraulics/pipeHydraulics.js';
import { thermalLoadToFlow } from '../hydraulics/thermalLoadToFlow.js';
import { pushRecommendation } from '../recommendations/recommendationResolver.js';
import { round } from '../utils/math.js';
import {
  UFH_LOOP_LENGTH_LAYOUT_FACTOR_DEFAULT,
  computeUfhLoopTotalLengthM,
} from './ufhLoopLength.js';

const MAX_LOOPS_HEURISTIC = 32;

/**
 * Оценка числа поворотов 90° в контуре петли ТП (MVP: аппроксимация меандра).
 * @param {number} loopLengthM
 * @param {number} pipeSpacingMm
 * @returns {number}
 */
export function estimateUfhLoopElbowCount(loopLengthM, pipeSpacingMm) {
  const spacingM = Math.max(0.05, (Number(pipeSpacingMm) || 150) / 1000);
  const len = Math.max(0, Number(loopLengthM) || 0);
  if (len <= 0) return 0;
  const ratio = len / spacingM;
  if (ratio <= 0) return 2;
  return Math.max(2, Math.round(2 * Math.sqrt(ratio)));
}

/**
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} rules
 * @returns {{ deltaTK: number; velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number }}
 */
export function ufhLoopHydraulicsThresholds(rules) {
  return {
    deltaTK: rules.ufhLoopDeltaTK,
    velocityMinMps: rules.ufhLoopVelocityMinMps,
    velocityMaxMps: rules.ufhLoopVelocityMaxMps,
    maxPressureDropKPa: rules.maxUfhLoopPressureDropKPa,
  };
}

/**
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} rules
 * @returns {number}
 */
function ufhLoopMinNominalDiameterMm(rules) {
  const n = Number(rules.ufhLoopMinNominalDiameterMm);
  return Number.isFinite(n) && n > 0 ? n : 16;
}

/**
 * @param {object} args
 * @param {number} [args.heatFluxDownWm2]
 * @param {number} [args.heatFluxDownWatts]
 * @param {number} [args.heatFluxUpWatts]
 * @param {string} [args.bottomBoundary]
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @returns {boolean}
 */
export function shouldTriggerUfhPipeResize({
  heatFluxDownWm2 = 0,
  heatFluxDownWatts = 0,
  heatFluxUpWatts = 0,
  bottomBoundary,
  hydraulicsRules,
}) {
  if (!hydraulicsRules.ufhLoopPipeResizeEnabled) return false;

  if (
    bottomBoundary === 'heated'
    && heatFluxDownWm2 >= hydraulicsRules.ufhParasiticDownTriggerWm2
  ) {
    return true;
  }

  if (
    heatFluxUpWatts > 0
    && heatFluxDownWatts / heatFluxUpWatts >= hydraulicsRules.ufhParasiticDownToUpRatio
  ) {
    return true;
  }

  return false;
}

/**
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} pipes
 * @param {number} minNominalDiameterMm
 * @param {import('../hydraulics/types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [materialPreference]
 * @returns {import('../catalog/types.js').PipeCatalogItemNormalized[]}
 */
function filterUfhPipePool(pipes, minNominalDiameterMm, materialPreference) {
  if (!pipes?.length) return [];

  const minNom = Math.max(1, minNominalDiameterMm);

  /** @type {import('../catalog/types.js').PipeCatalogItemNormalized[]} */
  let pool = pipes.filter((p) => (Number(p.diameter) || 0) >= minNom);

  if (materialPreference) {
    const pref = materialPreference.toLowerCase();
    const filtered = pool.filter((p) => {
      const m = String(p.material ?? '').toLowerCase();
      if (pref === 'pex') return m.includes('pex');
      if (pref === 'metal_plastic') {
        return m.includes('metal') || m.includes('pex-al') || m.includes('ал');
      }
      if (pref === 'steel') return m.includes('steel') || m.includes('сталь');
      return true;
    });
    if (filtered.length) pool = filtered;
  }

  pool.sort((a, b) => pipeInternalDiameterMm(a) - pipeInternalDiameterMm(b));
  return pool;
}

/**
 * @param {object} args
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized} args.pipe
 * @param {number} args.loopLengthM
 * @param {number} args.flowRateM3PerHour
 * @param {number} args.localZeta
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @returns {{ catalogPipeId: string; internalDiameterMm: number; velocityMps: number; pressureDropKPa: number } | null}
 */
function computeUfhLoopPipeHydraulics({
  pipe,
  loopLengthM,
  flowRateM3PerHour,
  localZeta,
  hydraulicsRules,
}) {
  if (loopLengthM <= 0 || flowRateM3PerHour <= 0) return null;

  const internalMm = pipeInternalDiameterMm(pipe);
  const roughness = resolveRoughnessMm(
    pipe.material,
    hydraulicsRules.roughnessMmByMaterial,
  );
  const hyd = computeSegmentHydraulics({
    flowM3PerHour: flowRateM3PerHour,
    lengthM: loopLengthM,
    internalDiameterMm: internalMm,
    roughnessMm: roughness,
    localZeta,
  });

  return {
    catalogPipeId: pipe.id,
    internalDiameterMm: internalMm,
    velocityMps: hyd.velocityMps,
    pressureDropKPa: hyd.pressureDropKPa,
  };
}

/**
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult} h
 * @param {{ velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number }} thresholds
 * @returns {boolean}
 */
function isLoopVelocityOk(h, thresholds) {
  return (
    h.velocityMps != null
    && h.velocityMps >= thresholds.velocityMinMps
    && h.velocityMps <= thresholds.velocityMaxMps
  );
}

/**
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult} h
 * @param {{ maxPressureDropKPa: number }} thresholds
 * @returns {boolean}
 */
function isLoopPressureOk(h, thresholds) {
  return (
    h.pressureDropKPa == null
    || h.pressureDropKPa <= thresholds.maxPressureDropKPa
  );
}

/**
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]} loopHydraulics
 * @param {{ velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number }} thresholds
 * @returns {{ pressureOk: boolean; velocityOk: boolean }}
 */
function evaluateLoopsHydraulics(loopHydraulics, thresholds) {
  const pressureOk = loopHydraulics.every((h) => isLoopPressureOk(h, thresholds));
  const velocityOk = loopHydraulics.every((h) => isLoopVelocityOk(h, thresholds));
  return { pressureOk, velocityOk };
}

/**
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]} loopHydraulics
 * @param {{ velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number }} thresholds
 * @returns {number}
 */
function scorePartialLoopsConfiguration(loopHydraulics, thresholds) {
  let score = 0;
  for (const h of loopHydraulics) {
    if (h.velocityMps == null || h.pressureDropKPa == null) {
      return Number.MAX_SAFE_INTEGER;
    }
    if (h.velocityMps < thresholds.velocityMinMps) {
      score += 1000 + (thresholds.velocityMinMps - h.velocityMps) * 100;
    } else if (h.velocityMps > thresholds.velocityMaxMps) {
      score += 500 + (h.velocityMps - thresholds.velocityMaxMps) * 100;
    }
    if (h.pressureDropKPa > thresholds.maxPressureDropKPa) {
      score += 800 + (h.pressureDropKPa - thresholds.maxPressureDropKPa) * 10;
    }
  }
  return score;
}

/**
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]} loopHydraulics
 * @param {{ velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number }} thresholds
 * @returns {import('./ufhLoopHydraulics.types.js').UfhLoopResolutionStatus}
 */
function deriveResolutionStatus(loopHydraulics, thresholds) {
  let hasLowVelocity = false;
  let hasHighVelocity = false;
  let hasHighPressure = false;

  for (const h of loopHydraulics) {
    if (h.velocityMps == null || h.pressureDropKPa == null) continue;
    if (h.velocityMps < thresholds.velocityMinMps) hasLowVelocity = true;
    if (h.velocityMps > thresholds.velocityMaxMps) hasHighVelocity = true;
    if (h.pressureDropKPa > thresholds.maxPressureDropKPa) hasHighPressure = true;
  }

  const velocityBad = hasLowVelocity || hasHighVelocity;

  if (!velocityBad && !hasHighPressure) {
    return 'resolved_auto';
  }
  if (velocityBad && hasHighPressure) {
    return 'unresolved_conflict';
  }
  if (hasHighPressure) {
    return 'unresolved_pressure';
  }
  return 'unresolved_velocity';
}

/**
 * @param {object} args
 * @param {number} args.loopsCount
 * @param {number} args.minLoopsGeom
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]} args.loopHydraulics
 * @returns {import('./ufhLoopHydraulics.types.js').UfhLoopAppliedFix}
 */
function deriveAppliedFix({ loopsCount, minLoopsGeom, loopHydraulics }) {
  if (loopsCount < minLoopsGeom) return 'loops_reduced';
  if (loopsCount > minLoopsGeom) return 'loops_increased';
  if (loopHydraulics.some((h) => h.pipeResizeAction === 'downsized')) {
    return 'pipe_downsized';
  }
  if (loopHydraulics.some((h) => h.pipeResizeAction === 'upsized')) {
    return 'pipe_upsized';
  }
  return 'none';
}

/**
 * @param {object} args
 * @param {import('../hydraulics/types.js').HydraulicsPipeMatchItem} args.defaultMatch
 * @param {import('../catalog/types.js').PipeCatalogItemNormalized[]} args.pool
 * @param {number} args.loopLengthM
 * @param {number} args.flowRateM3PerHour
 * @param {number} args.localZeta
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @param {{ velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number }} args.thresholds
 * @param {string} args.loopId
 * @returns {{ finalMatch: import('../hydraulics/types.js').HydraulicsPipeMatchItem; pipeResizeAction: import('./ufhLoopHydraulics.types.js').UfhLoopPipeResizeAction; pipeResizeReason: string | null }}
 */
function optimizeUfhLoopPipe({
  defaultMatch,
  pool,
  loopLengthM,
  flowRateM3PerHour,
  localZeta,
  hydraulicsRules,
  thresholds,
  loopId,
}) {
  let finalMatch = defaultMatch;
  /** @type {import('./ufhLoopHydraulics.types.js').UfhLoopPipeResizeAction} */
  let pipeResizeAction = 'unchanged';
  /** @type {string | null} */
  let pipeResizeReason = null;

  if (!hydraulicsRules.ufhLoopPipeResizeEnabled || pool.length === 0) {
    return { finalMatch, pipeResizeAction, pipeResizeReason };
  }

  const pressureUtilThreshold =
    thresholds.maxPressureDropKPa * hydraulicsRules.ufhLoopPressureUtilizationForResize;

  const vLow = defaultMatch.velocityMps < thresholds.velocityMinMps;
  const vHigh = defaultMatch.velocityMps > thresholds.velocityMaxMps;
  const dpHigh = defaultMatch.pressureDropKPa > pressureUtilThreshold;

  if (vLow) {
    /** @type {import('./ufhLoopHydraulics.types.js').UfhLoopPipeCandidate | null} */
    let smallerCandidate = null;
    for (const pipe of pool) {
      const computed = computeUfhLoopPipeHydraulics({
        pipe,
        loopLengthM,
        flowRateM3PerHour,
        localZeta,
        hydraulicsRules,
      });
      if (!computed) continue;
      if (computed.velocityMps < thresholds.velocityMinMps) continue;
      if (computed.pressureDropKPa > thresholds.maxPressureDropKPa) continue;
      if (
        !smallerCandidate
        || computed.internalDiameterMm < smallerCandidate.internalDiameterMm
      ) {
        smallerCandidate = { ...computed, pipe };
      }
    }

    if (
      smallerCandidate
      && smallerCandidate.catalogPipeId !== defaultMatch.catalogPipeId
    ) {
      finalMatch = {
        edgeId: loopId,
        catalogPipeId: smallerCandidate.catalogPipeId,
        velocityMps: smallerCandidate.velocityMps,
        pressureDropKPa: smallerCandidate.pressureDropKPa,
        internalDiameterMm: smallerCandidate.internalDiameterMm,
      };
      pipeResizeAction = 'downsized';
      pipeResizeReason =
        `Низька швидкість ${defaultMatch.velocityMps} м/с — `
        + `рекомендовано менший Ø ${smallerCandidate.internalDiameterMm} мм.`;
    }
  } else if (vHigh || dpHigh) {
    /** @type {import('./ufhLoopHydraulics.types.js').UfhLoopPipeCandidate | null} */
    let best = null;
    for (const pipe of pool) {
      const computed = computeUfhLoopPipeHydraulics({
        pipe,
        loopLengthM,
        flowRateM3PerHour,
        localZeta,
        hydraulicsRules,
      });
      if (!computed) continue;

      const vOk =
        computed.velocityMps >= thresholds.velocityMinMps
        && computed.velocityMps <= thresholds.velocityMaxMps;
      const dpOk = computed.pressureDropKPa <= thresholds.maxPressureDropKPa;

      if (!vOk || !dpOk) continue;

      const candidate = { ...computed, pipe };

      if (
        !best
        || computed.internalDiameterMm > best.internalDiameterMm
        || (
          computed.internalDiameterMm === best.internalDiameterMm
          && computed.pressureDropKPa < (best.pressureDropKPa ?? Infinity)
        )
      ) {
        best = candidate;
      }
    }

    if (best && best.catalogPipeId !== defaultMatch.catalogPipeId) {
      finalMatch = {
        edgeId: loopId,
        catalogPipeId: best.catalogPipeId,
        velocityMps: best.velocityMps,
        pressureDropKPa: best.pressureDropKPa,
        internalDiameterMm: best.internalDiameterMm,
      };
      pipeResizeAction = 'upsized';
      if (vHigh) {
        pipeResizeReason =
          `Швидкість ${defaultMatch.velocityMps} м/с вище порогу ${thresholds.velocityMaxMps} м/с — `
          + `рекомендовано Ø ${best.internalDiameterMm} мм.`;
      } else {
        pipeResizeReason =
          `Втрати ${defaultMatch.pressureDropKPa} кПа близькі до ліміту — `
          + `рекомендовано Ø ${best.internalDiameterMm} мм.`;
      }
    }
  }

  return { finalMatch, pipeResizeAction, pipeResizeReason };
}

/**
 * @param {object} args
 * @param {string} args.loopId
 * @param {number} args.loopLengthM
 * @param {number} args.pipeSpacingMm
 * @param {number} args.heatLoadWatts
 * @param {number} args.deltaTK
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} args.pipes
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @param {import('../hydraulics/types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [args.materialPreference]
 * @returns {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult}
 */
export function validateUfhLoopHydraulics({
  loopId,
  loopLengthM,
  pipeSpacingMm,
  heatLoadWatts,
  deltaTK,
  pipes,
  hydraulicsRules,
  materialPreference,
}) {
  /** @type {string[]} */
  const warnings = [];
  const thresholds = ufhLoopHydraulicsThresholds(hydraulicsRules);
  const minNominalMm = ufhLoopMinNominalDiameterMm(hydraulicsRules);
  const flow = thermalLoadToFlow({ heatLoadWatts, deltaTK });
  const elbowCount = estimateUfhLoopElbowCount(loopLengthM, pipeSpacingMm);
  const localZeta = elbowCount * hydraulicsRules.localLossZeta.elbow90;

  /** @type {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult} */
  const base = {
    loopId,
    loopLengthM: round(loopLengthM, 1),
    pipeSpacingMm,
    heatLoadWatts: round(heatLoadWatts, 0),
    deltaTK,
    flowRateM3PerHour: flow.flowRateM3PerHour,
    massFlowKgPerSec: flow.massFlowKgPerSec,
    elbowCount,
    localZeta: round(localZeta, 2),
    catalogPipeId: null,
    initialCatalogPipeId: null,
    internalDiameterMm: null,
    velocityMps: null,
    pressureDropKPa: null,
    pipeResizeAction: 'unchanged',
    pipeResizeReason: null,
    warnings,
  };

  if (loopLengthM <= 0 || heatLoadWatts <= 0) {
    warnings.push(`Петля ${loopId}: нульова длина або навантаження — гідравліку не розраховано.`);
    return base;
  }

  const pool = filterUfhPipePool(pipes, minNominalMm, materialPreference);
  const pipesForPick = pool.length ? pool : pipes;

  if (!pipesForPick?.length) {
    warnings.push(`Петля ${loopId}: каталог труб порожній — підбір неможливий.`);
    return base;
  }

  /** @type {import('../hydraulics/types.js').HydraulicsRules} */
  const rulesForPick = {
    mainTransitMinInternalDiameterMm: hydraulicsRules.mainTransitMinInternalDiameterMm ?? 20,
    branchMinInternalDiameterMm: hydraulicsRules.branchMinInternalDiameterMm ?? 12,
    velocityLimitsMps: {
      ...hydraulicsRules.velocityLimitsMps,
      branchMax: thresholds.velocityMaxMps,
    },
    radiatorBranchGrouping: hydraulicsRules.radiatorBranchGrouping,
    defaultLengthsM: hydraulicsRules.defaultLengthsM,
    maxUfhLoopLengthM: hydraulicsRules.maxUfhLoopLengthM,
    roughnessMmByMaterial: hydraulicsRules.roughnessMmByMaterial,
    localLossZeta: hydraulicsRules.localLossZeta,
    pumpHeadMarginPercent: hydraulicsRules.pumpHeadMarginPercent,
    pumpDutyQMaxUtilizationPercent: hydraulicsRules.pumpDutyQMaxUtilizationPercent,
    pumpMinHeadAtDutyM: hydraulicsRules.pumpMinHeadAtDutyM,
    pumpMaxHeadMarginPercent: hydraulicsRules.pumpMaxHeadMarginPercent,
    pumpMinHeadAtQMaxM: hydraulicsRules.pumpMinHeadAtQMaxM,
    primaryFlowMarginPercent: hydraulicsRules.primaryFlowMarginPercent,
    balancingValveKPaPerTurn: hydraulicsRules.balancingValveKPaPerTurn,
  };

  const defaultMatch = pickPipeForEdge({
    edge: {
      id: loopId,
      from: 'ufh_collector',
      to: loopId,
      lengthM: loopLengthM,
      fluid: 'heating',
      designFlowM3PerHour: flow.flowRateM3PerHour,
      segmentRole: 'ufh_loop',
    },
    pipes: pipesForPick,
    rules: rulesForPick,
    materialPreference,
    localZeta,
  });

  if (!defaultMatch) {
    warnings.push(`Петля ${loopId}: не вдалося підібрати трубу з каталогу.`);
    return base;
  }

  base.initialCatalogPipeId = defaultMatch.catalogPipeId;

  const { finalMatch, pipeResizeAction, pipeResizeReason } = optimizeUfhLoopPipe({
    defaultMatch,
    pool: pool.length ? pool : pipesForPick,
    loopLengthM,
    flowRateM3PerHour: flow.flowRateM3PerHour,
    localZeta,
    hydraulicsRules,
    thresholds,
    loopId,
  });

  base.catalogPipeId = finalMatch.catalogPipeId;
  base.internalDiameterMm = finalMatch.internalDiameterMm;
  base.velocityMps = finalMatch.velocityMps;
  base.pressureDropKPa = finalMatch.pressureDropKPa;
  base.pipeResizeAction = pipeResizeAction;
  base.pipeResizeReason = pipeResizeReason;

  if (finalMatch.velocityMps < thresholds.velocityMinMps) {
    warnings.push(
      `Петля ${loopId}: низька швидкість ${finalMatch.velocityMps} м/с (< ${thresholds.velocityMinMps} м/с) — високий ризик завоздушування контуру.`,
    );
  }
  if (finalMatch.velocityMps > thresholds.velocityMaxMps) {
    warnings.push(
      `Петля ${loopId}: швидкість ${finalMatch.velocityMps} м/с перевищує шумовий поріг ${thresholds.velocityMaxMps} м/с.`,
    );
  }
  if (finalMatch.pressureDropKPa > thresholds.maxPressureDropKPa) {
    warnings.push(
      `Петля ${loopId}: втрати тиску ${finalMatch.pressureDropKPa} кПа перевищують допустимі ${thresholds.maxPressureDropKPa} кПа — зменште довжину петлі або збільште число контурів.`,
    );
  }
  if (pipeResizeReason) {
    warnings.push(`Петля ${loopId}: ${pipeResizeReason}`);
  }

  return base;
}

/**
 * @param {object} args
 * @param {number} args.loopsCount
 * @param {number} args.totalLengthM
 * @param {number} args.heatLoadWatts
 * @param {number} args.deltaTK
 * @param {string} args.roomId
 * @returns {import('../hydraulics/types.js').HydraulicsUfhLoop[]}
 */
function buildLoopsArray({
  loopsCount,
  totalLengthM,
  heatLoadWatts,
  deltaTK,
  roomId,
}) {
  const count = Math.max(1, loopsCount);
  const perLoopLength = totalLengthM / count;
  const perLoopHeat = heatLoadWatts / count;
  const perLoopFlow = thermalLoadToFlow({
    heatLoadWatts: perLoopHeat,
    deltaTK,
  });

  /** @type {import('../hydraulics/types.js').HydraulicsUfhLoop[]} */
  const loops = [];
  for (let i = 0; i < count; i += 1) {
    loops.push({
      loopId: `${roomId}_loop_${i + 1}`,
      loopLengthM: round(perLoopLength, 1),
      heatLoadWatts: round(perLoopHeat, 0),
      flowRateM3PerHour: perLoopFlow.flowRateM3PerHour,
    });
  }
  return loops;
}

/**
 * @param {import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]} loopHydraulics
 * @param {number} loopsCount
 * @param {number} minLoopsGeom
 */
function markLoopsCountAdjustment(loopHydraulics, loopsCount, minLoopsGeom) {
  if (loopsCount === minLoopsGeom) return;

  const reason =
    loopsCount < minLoopsGeom
      ? `Число петель зменшено до ${loopsCount} (замість ${minLoopsGeom}) для підвищення швидкості на петлі.`
      : `Число петель збільшено до ${loopsCount} (замість ${minLoopsGeom}) для зменшення втрат тиску.`;

  for (const h of loopHydraulics) {
    if (h.pipeResizeAction === 'unchanged') {
      h.pipeResizeAction = 'loops_adjusted';
      h.pipeResizeReason = reason;
      h.warnings.push(`Петля ${h.loopId}: ${reason}`);
    }
  }
}

/**
 * @param {object} args
 * @param {number} args.loopsCount
 * @param {number} args.totalLengthM
 * @param {number} args.pipeSpacingMm
 * @param {number} args.heatLoadWatts
 * @param {string} args.roomId
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} args.pipes
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @param {import('../hydraulics/types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [args.materialPreference]
 * @param {{ velocityMinMps: number; velocityMaxMps: number; maxPressureDropKPa: number; deltaTK: number }} args.thresholds
 * @returns {{ loops: import('../hydraulics/types.js').HydraulicsUfhLoop[]; loopHydraulics: import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]; pressureOk: boolean; velocityOk: boolean }}
 */
function buildAndValidateLoopsConfiguration({
  loopsCount,
  totalLengthM,
  pipeSpacingMm,
  heatLoadWatts,
  roomId,
  pipes,
  hydraulicsRules,
  materialPreference,
  thresholds,
}) {
  const loops = buildLoopsArray({
    loopsCount,
    totalLengthM,
    heatLoadWatts,
    deltaTK: thresholds.deltaTK,
    roomId,
  });

  const loopHydraulics = loops.map((loop) =>
    validateUfhLoopHydraulics({
      loopId: loop.loopId,
      loopLengthM: loop.loopLengthM,
      pipeSpacingMm,
      heatLoadWatts: loop.heatLoadWatts,
      deltaTK: thresholds.deltaTK,
      pipes,
      hydraulicsRules,
      materialPreference,
    }),
  );

  return {
    loops,
    loopHydraulics,
    ...evaluateLoopsHydraulics(loopHydraulics, thresholds),
  };
}

/**
 * Подбор числа петель: геометрия + ограничения v и Δp на петлю.
 * @param {object} args
 * @param {number} args.areaM2
 * @param {number} args.pipeSpacingMm
 * @param {number} args.heatLoadWatts
 * @param {number} [args.heatFluxDownWm2]
 * @param {number} [args.heatFluxDownWatts]
 * @param {number} [args.heatFluxUpWatts]
 * @param {string} [args.bottomBoundary]
 * @param {string} args.roomId
 * @param {import('../catalog/types.js').NormalizedCatalog['pipes']} args.pipes
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @param {import('../hydraulics/types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [args.materialPreference]
 * @returns {import('./ufhLoopHydraulics.types.js').UfhRoomLoopsHydraulicsResult}
 */
export function resolveUfhRoomLoopsHydraulics({
  areaM2,
  pipeSpacingMm,
  heatLoadWatts,
  heatFluxDownWm2: _heatFluxDownWm2 = 0,
  heatFluxDownWatts: _heatFluxDownWatts = 0,
  heatFluxUpWatts: _heatFluxUpWatts = 0,
  bottomBoundary: _bottomBoundary,
  roomId,
  pipes,
  hydraulicsRules,
  materialPreference,
}) {
  /** @type {string[]} */
  const warnings = [];
  const thresholds = ufhLoopHydraulicsThresholds(hydraulicsRules);
  const layoutFactor =
    typeof hydraulicsRules.ufhLoopLengthLayoutFactor === 'number' &&
    Number.isFinite(hydraulicsRules.ufhLoopLengthLayoutFactor)
      ? hydraulicsRules.ufhLoopLengthLayoutFactor
      : UFH_LOOP_LENGTH_LAYOUT_FACTOR_DEFAULT;
  const totalLengthM = computeUfhLoopTotalLengthM({
    areaM2,
    pipeSpacingMm,
    layoutFactor,
  });
  const maxLen = Math.max(20, hydraulicsRules.maxUfhLoopLengthM);
  const minLoopsGeom = Math.max(1, Math.ceil(totalLengthM / maxLen));

  /** @type {{ loopsCount: number; loops: import('../hydraulics/types.js').HydraulicsUfhLoop[]; loopHydraulics: import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]; distance: number } | null} */
  let bestResolved = null;
  /** @type {{ loopsCount: number; loops: import('../hydraulics/types.js').HydraulicsUfhLoop[]; loopHydraulics: import('./ufhLoopHydraulics.types.js').UfhLoopHydraulicsResult[]; score: number; distance: number } | null} */
  let bestPartial = null;

  for (let loopsCount = 1; loopsCount <= MAX_LOOPS_HEURISTIC; loopsCount += 1) {
    const perLoopLength = totalLengthM / loopsCount;
    if (perLoopLength > maxLen + 0.01) continue;

    const cfg = buildAndValidateLoopsConfiguration({
      loopsCount,
      totalLengthM,
      pipeSpacingMm,
      heatLoadWatts,
      roomId,
      pipes,
      hydraulicsRules,
      materialPreference,
      thresholds,
    });

    const distance = Math.abs(loopsCount - minLoopsGeom);

    if (cfg.pressureOk && cfg.velocityOk) {
      if (!bestResolved || distance < bestResolved.distance) {
        bestResolved = {
          loopsCount,
          loops: cfg.loops,
          loopHydraulics: cfg.loopHydraulics,
          distance,
        };
      }
      continue;
    }

    const score = scorePartialLoopsConfiguration(cfg.loopHydraulics, thresholds);
    if (!bestPartial || score < bestPartial.score || (score === bestPartial.score && distance < bestPartial.distance)) {
      bestPartial = {
        loopsCount,
        loops: cfg.loops,
        loopHydraulics: cfg.loopHydraulics,
        score,
        distance,
      };
    }
  }

  const outcome = (() => {
    if (bestResolved) {
      const { loops, loopHydraulics, loopsCount: chosenLoopsCount } = bestResolved;
      markLoopsCountAdjustment(loopHydraulics, chosenLoopsCount, minLoopsGeom);
      return {
        loops,
        loopHydraulics,
        chosenLoopsCount,
        resolutionStatus: 'resolved_auto',
        appliedFix: deriveAppliedFix({
          loopsCount: chosenLoopsCount,
          minLoopsGeom,
          loopHydraulics,
        }),
        pipeResizeApplied: loopHydraulics.some(
          (h) => h.pipeResizeAction !== 'unchanged',
        ),
        extraWarnings: [],
      };
    }

    if (bestPartial) {
      const { loops, loopHydraulics, loopsCount: chosenLoopsCount } = bestPartial;
      const resolutionStatus = deriveResolutionStatus(loopHydraulics, thresholds);
      markLoopsCountAdjustment(loopHydraulics, chosenLoopsCount, minLoopsGeom);
      /** @type {string[]} */
      const extraWarnings = [];
      if (resolutionStatus === 'unresolved_pressure') {
        extraWarnings.push(
          `Кімната ${roomId}: не вдалося вкластися в ${thresholds.maxPressureDropKPa} кПа на петлю за допустимого числа контурів — потрібна проєктна опрацювання.`,
        );
      }
      return {
        loops,
        loopHydraulics,
        chosenLoopsCount,
        resolutionStatus,
        appliedFix: deriveAppliedFix({
          loopsCount: chosenLoopsCount,
          minLoopsGeom,
          loopHydraulics,
        }),
        pipeResizeApplied: loopHydraulics.some(
          (h) => h.pipeResizeAction !== 'unchanged',
        ),
        extraWarnings,
      };
    }

    const fallback = buildAndValidateLoopsConfiguration({
      loopsCount: minLoopsGeom,
      totalLengthM,
      pipeSpacingMm,
      heatLoadWatts,
      roomId,
      pipes,
      hydraulicsRules,
      materialPreference,
      thresholds,
    });
    return {
      loops: fallback.loops,
      loopHydraulics: fallback.loopHydraulics,
      chosenLoopsCount: minLoopsGeom,
      resolutionStatus: deriveResolutionStatus(fallback.loopHydraulics, thresholds),
      appliedFix: deriveAppliedFix({
        loopsCount: minLoopsGeom,
        minLoopsGeom,
        loopHydraulics: fallback.loopHydraulics,
      }),
      pipeResizeApplied: false,
      extraWarnings: [
        `Кімната ${roomId}: не вдалося підібрати конфігурацію петель — потрібна проєктна опрацювання.`,
      ],
    };
  })();

  warnings.push(...outcome.extraWarnings);
  // Предупреждения петель остаются только на loopHydraulics[].warnings —
  // не дублируем их в room/global (см. enrichUnderfloorHeatingLoopHydraulics).

  return {
    loopsCount: outcome.loops.length,
    loops: outcome.loops,
    loopHydraulics: outcome.loopHydraulics,
    warnings,
    pipeResizeApplied: outcome.pipeResizeApplied,
    resolutionStatus:
      /** @type {import('./ufhLoopHydraulics.types.js').UfhLoopResolutionStatus} */ (
        outcome.resolutionStatus
      ),
    appliedFix: outcome.appliedFix,
    minLoopsGeom,
    chosenLoopsCount: outcome.chosenLoopsCount,
  };
}

/**
 * Структурированные REC/WARN по гидравлике петель ТП.
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport} underfloorHeating
 * @param {import('../recommendations/types.js').RecommendationsBundle} recommendations
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc | undefined} [hydraulicsRules]
 */
export function applyUfhLoopHydraulicsRecommendations(
  underfloorHeating,
  recommendations,
  hydraulicsRules,
) {
  if (!underfloorHeating?.rooms?.length || !hydraulicsRules) return;

  const thresholds = ufhLoopHydraulicsThresholds(hydraulicsRules);

  /** @type {string[]} */
  const warnings = [];
  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const resolvedRecommendations = [];

  for (const room of underfloorHeating.rooms) {
    const status = room.loopHydraulicsResolutionStatus;
    if (!status) continue;

    const vars = {
      roomName: room.roomName,
      loopsCount: room.loopsCount ?? 0,
      minLoopsGeom: room.loopHydraulicsMinLoopsGeom ?? room.loopsCount ?? 0,
      velocityMinMps: thresholds.velocityMinMps,
      maxPressureDropKPa: thresholds.maxPressureDropKPa,
    };

    if (
      status === 'resolved_auto'
      && room.loopHydraulicsAppliedFix
      && room.loopHydraulicsAppliedFix !== 'none'
    ) {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendations,
        'REC_UFH_LOOP_VELOCITY_AUTO_FIXED',
        {
          ...vars,
          appliedFix: room.loopHydraulicsAppliedFix,
        },
      );
      continue;
    }

    if (status === 'unresolved_velocity') {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_UFH_LOOP_LOW_VELOCITY_UNRESOLVED',
        vars,
      );
    } else if (status === 'unresolved_pressure') {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_UFH_LOOP_HIGH_PRESSURE',
        vars,
      );
    } else if (status === 'unresolved_conflict') {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_UFH_LOOP_VELOCITY_PRESSURE_CONFLICT',
        vars,
      );
    }
  }

  if (warnings.length > 0) {
    underfloorHeating.warnings = [...(underfloorHeating.warnings ?? []), ...warnings];
  }
  if (resolvedRecommendations.length > 0) {
    underfloorHeating.resolvedRecommendations = [
      ...(underfloorHeating.resolvedRecommendations ?? []),
      ...resolvedRecommendations,
    ];
  }
}

/**
 * Обогащает отчёт ТП гидравликой петель (после warmFloorCalc, когда доступен каталог).
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport} underfloorHeating
 * @param {object} ctx
 * @param {import('../catalog/types.js').NormalizedCatalog} ctx.catalog
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} ctx.hydraulicsRules
 * @param {import('../hydraulics/types.js').HydraulicsSurveyInput['pipeMaterialPreference']} [ctx.materialPreference]
 */
export function enrichUnderfloorHeatingLoopHydraulics(
  underfloorHeating,
  { catalog, hydraulicsRules, materialPreference },
) {
  if (!underfloorHeating?.rooms?.length) return;

  const pipes = catalog.pipes ?? [];

  for (const room of underfloorHeating.rooms) {
    const resolved = resolveUfhRoomLoopsHydraulics({
      areaM2: room.heatedAreaM2 ?? room.areaM2,
      pipeSpacingMm: room.pipeSpacingMm,
      heatLoadWatts: room.heatLoadWatts ?? room.heatFluxUpWatts,
      heatFluxDownWm2: room.heatFluxDownWm2,
      heatFluxDownWatts: room.heatFluxDownWatts,
      heatFluxUpWatts: room.heatFluxUpWatts,
      bottomBoundary: room.bottomBoundary,
      roomId: room.roomId,
      pipes,
      hydraulicsRules,
      materialPreference,
    });

    room.loopsCount = resolved.loopsCount;
    room.loops = resolved.loops.map((loop, idx) => ({
      ...loop,
      catalogPipeId: resolved.loopHydraulics[idx]?.catalogPipeId ?? undefined,
      hydraulics: resolved.loopHydraulics[idx],
    }));
    room.flowRateM3PerHour = round(
      resolved.loops.reduce((s, l) => s + l.flowRateM3PerHour, 0),
      3,
    );
    room.loopHydraulicsResolutionStatus = resolved.resolutionStatus;
    room.loopHydraulicsAppliedFix = resolved.appliedFix;
    room.loopHydraulicsMinLoopsGeom = resolved.minLoopsGeom;

    if (resolved.pipeResizeApplied) {
      room.pipeResizeApplied = true;
    }

    const prefixed = resolved.warnings.map(
      (w) => `Кімната «${room.roomName}»: ${w}`,
    );
    room.warnings = [...(room.warnings ?? []), ...prefixed];
    underfloorHeating.warnings = [...(underfloorHeating.warnings ?? []), ...prefixed];
  }
}

/**
 * Назначение: ориентиры насоса и клапана узла смешения ТП.
 * Описание: Q = P×0.86/(Δt×ρ), Kvs, напор H — без подбора артикулов из каталога.
 */

import { round } from '../utils/math.js';

/** Плотность воды, кг/л (≈1). */
const RHO_KG_PER_L = 1;

/**
 * @param {object} args
 * @param {number} args.powerKw — суммарная полезная мощность ТП, кВт
 * @param {number} [args.deltaTK=10]
 * @param {'collector_mixing_valve' | 'hydraulic_separator'} [args.distributionPreset]
 * @param {import('../dhw/types.js').UnderfloorHeatingMixingNodeRules} [args.mixingNodeRules]
 * @returns {import('../types/shared-types.js').UfhMixingNodeSpec}
 */
export function computeUfhMixingNodeSpec(args) {
  const {
    powerKw,
    deltaTK,
    distributionPreset = 'collector_mixing_valve',
    mixingNodeRules,
  } = args;

  const dt = deltaTK ?? mixingNodeRules?.deltaTK ?? 10;
  const valvePressureDropBar = mixingNodeRules?.valvePressureDropBar ?? 0.17;
  const headCollector = mixingNodeRules?.headMetersMinCollector ?? 3;
  const headSeparator = mixingNodeRules?.headMetersMinHydraulicSeparator ?? 5;

  const p = Number(powerKw) || 0;
  const flowRateM3PerHour =
    dt > 0 && p > 0 ? round((p * 0.86) / (dt * RHO_KG_PER_L), 3) : 0;

  const headMetersMin =
    distributionPreset === 'hydraulic_separator' ? headSeparator : headCollector;

  const valveKvsMin =
    flowRateM3PerHour > 0 && valvePressureDropBar > 0
      ? round(flowRateM3PerHour / valvePressureDropBar, 2)
      : 0;

  /** @type {string[]} */
  const notes = [
    `Орієнтир витрати контуру ТП: не менше ${flowRateM3PerHour} м³/ч (Δt = ${dt} K).`,
    `Насос контуру ТП: напір не менше ${headMetersMin} м.в.ст.`,
    `Триходовий змішувальний клапан: Kvs від ${valveKvsMin} м³/ч (Δp ≈ ${valvePressureDropBar} бар).`,
  ];

  return {
    isMixingNodeRequired: true,
    deltaTK: dt,
    powerKw: round(p, 2),
    flowRateM3PerHour,
    headMetersMin,
    valveKvsMin,
    distributionPreset,
    notes,
  };
}

/**
 * Назначение: теплоотдача водяного ТП по одной комнате (q↑/q↓, Tповерх).
 * Описание: Физика покрытия base+finish; без оркестрации отчёта.
 */

import {
  computeBaseCoveringResistanceM2KW,
  computeComposedCoveringResistanceM2KW,
  computeLayerResistanceM2KW,
} from '../data/warmFloorAssemblyPresets.js';
import { computeFinishCoveringResistanceM2KW } from '../data/flooringFinishMaterials.js';
import { resolvePipeEmbedmentResistanceM2KW } from './ufhPipeEmbedment.js';
import { round } from '../utils/math.js';

/** Сопротивление конвекции пол→воздух, м²·K/Вт. */
export const R_CONV_UP_M2KW = 0.1;
/** От плиты к тёплому перекрытию соседа. */
export const R_CONV_DOWN_HEATED_M2KW = 0.05;
/** От плиты к холодной зоне снизу. */
export const R_CONV_DOWN_UNHEATED_M2KW = 0.15;

/**
 * @param {import('../types/shared-types.js').UnderfloorHeatingAssemblyLayer[]} layers
 * @param {number} heatingIdx
 * @returns {number}
 */
function sumResistanceBelowHeatingLayer(layers, heatingIdx) {
  let sum = 0;
  for (let i = 0; i < heatingIdx; i += 1) {
    const layer = layers[i];
    if (!layer) continue;
    sum += computeLayerResistanceM2KW(layer);
  }
  return sum;
}

/**
 * Лимит температуры поверхности: min(пресет Mongo, паспорт финиша) при заданном пресете.
 *
 * @param {number | undefined} presetMaxSurfaceTemperatureC
 * @param {import('../types/shared-types.js').FlooringFinishMaterial} finish
 * @returns {{
 *   appliedMaxSurfaceT: number,
 *   appliedComfortMaxSurfaceT: number | undefined,
 *   finishMaxSurfaceT: number,
 *   presetMaxSurfaceT?: number,
 * }}
 */
function resolveAppliedSurfaceTemperatureLimits(
  presetMaxSurfaceTemperatureC,
  finish,
) {
  const finishMaxSurfaceT = finish.maxSurfaceTemperatureCelsius;
  const finishComfortMaxSurfaceT = finish.comfortMaxSurfaceTemperatureCelsius;

  const presetMax =
    typeof presetMaxSurfaceTemperatureC === 'number'
    && Number.isFinite(presetMaxSurfaceTemperatureC)
    && presetMaxSurfaceTemperatureC > 0
      ? presetMaxSurfaceTemperatureC
      : undefined;

  const appliedMaxSurfaceT =
    presetMax != null
      ? Math.min(presetMax, finishMaxSurfaceT)
      : finishMaxSurfaceT;

  const appliedComfortMaxSurfaceT =
    presetMax != null && typeof finishComfortMaxSurfaceT === 'number'
      ? Math.min(presetMax, finishComfortMaxSurfaceT)
      : finishComfortMaxSurfaceT;

  return {
    appliedMaxSurfaceT,
    appliedComfortMaxSurfaceT,
    finishMaxSurfaceT,
    ...(presetMax != null ? { presetMaxSurfaceT: presetMax } : {}),
  };
}

/**
 * Результат физической модели тепловіддачі ТП (без полів кімнати/анкети).
 *
 * @typedef {object} UfhRoomHeatFluxComputed
 * @property {number} areaM2
 * @property {number} pipeSpacingMm
 * @property {number} pipeEmbedmentResistanceM2KW
 * @property {number} baseCoveringResistanceM2KW
 * @property {number} finishCoveringResistanceM2KW
 * @property {number} coveringResistanceM2KW
 * @property {number} resistanceUpM2KW
 * @property {number} resistanceDownM2KW
 * @property {number} circuitSupplyC
 * @property {number} circuitReturnC
 * @property {number} circuitMeanC
 * @property {number} heatFluxUpWm2
 * @property {number} heatFluxDownWm2
 * @property {number} maxAllowableHeatFluxUpWm2
 * @property {number} heatFluxUpWatts
 * @property {number} heatFluxDownWatts
 * @property {number} surfaceTempC
 * @property {number} maxSurfaceTemperatureCelsius
 * @property {number} [comfortMaxSurfaceTemperatureCelsius]
 * @property {number} finishMaxSurfaceTemperatureCelsius
 * @property {number} [presetMaxSurfaceTemperatureCelsius]
 * @property {'heated' | 'unheated'} bottomBoundary
 * @property {number} neighborTempC
 * @property {boolean} heatFluxUpLimitedBySurface
 * @property {string[]} roomWarnings
 */

/**
 * @param {object} args
 * @param {import('../types/shared-types.js').UnderfloorHeatingBasePreset} args.base
 * @param {import('../types/shared-types.js').FlooringFinishMaterial} args.finish
 * @param {number} args.pipeSpacingMm
 * @param {number} args.circuitMeanC
 * @param {number} [args.circuitSupplyC]
 * @param {number} [args.circuitReturnC]
 * @param {number} [args.presetMaxSurfaceTemperatureC]
 * @param {number} args.insideC
 * @param {number} args.outsideC
 * @param {'heated' | 'unheated'} args.bottomBoundary
 * @param {number} args.areaM2
 * @returns {UfhRoomHeatFluxComputed}
 */
export function computeUfhRoomHeatFlux(args) {
  const {
    base,
    finish,
    pipeSpacingMm,
    circuitMeanC,
    circuitSupplyC,
    circuitReturnC,
    presetMaxSurfaceTemperatureC,
    insideC,
    outsideC,
    bottomBoundary,
    areaM2,
  } = args;

  const resolvedSupplyC = circuitSupplyC ?? circuitMeanC;
  const resolvedReturnC = circuitReturnC ?? circuitMeanC;

  const layers = base.layers;
  const heatingIdx = layers.findIndex((l) => l.isHeatingLayer);
  const rPipeEmbed = resolvePipeEmbedmentResistanceM2KW(pipeSpacingMm);
  const screedLayer = heatingIdx >= 0 ? layers[heatingIdx] : undefined;
  if (!screedLayer) {
    throw new Error('ufhRoomHeatFlux: в сборке нет слоя isHeatingLayer');
  }
  const rScreedHalf = computeLayerResistanceM2KW(screedLayer) / 2;
  const rBaseAbove = computeBaseCoveringResistanceM2KW(layers);
  const rFinish = computeFinishCoveringResistanceM2KW(finish);
  const rCovering = computeComposedCoveringResistanceM2KW(base, finish);
  const rBelow = sumResistanceBelowHeatingLayer(layers, heatingIdx);

  const rUp = rPipeEmbed + rScreedHalf + rCovering + R_CONV_UP_M2KW;
  const neighborTempC = bottomBoundary === 'heated' ? insideC : outsideC;
  const rConvDown =
    bottomBoundary === 'heated'
      ? R_CONV_DOWN_HEATED_M2KW
      : R_CONV_DOWN_UNHEATED_M2KW;
  const rDown = rPipeEmbed + rScreedHalf + rBelow + rConvDown;

  const surfaceLimits = resolveAppliedSurfaceTemperatureLimits(
    presetMaxSurfaceTemperatureC,
    finish,
  );
  const maxSurfaceT = surfaceLimits.appliedMaxSurfaceT;
  const comfortMaxSurfaceT = surfaceLimits.appliedComfortMaxSurfaceT;
  const maxAllowableHeatFluxUpWm2 = Math.max(0, (maxSurfaceT - insideC) / rFinish);

  const heatFluxUpUncappedWm2 = Math.max(0, (circuitMeanC - insideC) / rUp);
  const heatFluxUpLimitedBySurface =
    heatFluxUpUncappedWm2 > maxAllowableHeatFluxUpWm2 + 1e-9;
  const heatFluxUpWm2 = Math.min(heatFluxUpUncappedWm2, maxAllowableHeatFluxUpWm2);
  const heatFluxDownWm2 = Math.max(0, (circuitMeanC - neighborTempC) / rDown);
  const surfaceTempC = insideC + heatFluxUpWm2 * rFinish;

  const heatFluxUpWatts = heatFluxUpWm2 * areaM2;
  const heatFluxDownWatts = heatFluxDownWm2 * areaM2;

  /** @type {string[]} */
  const roomWarnings = [];
  if (heatFluxUpLimitedBySurface) {
    roomWarnings.push(
      `Віддача вгору обмежена лімітом поверхні ${round(maxSurfaceT, 1)} °C: q↑ знижено з ≈${round(heatFluxUpUncappedWm2, 0)} до ≈${round(heatFluxUpWm2, 0)} Вт/м² (Tповерх ≈${round(surfaceTempC, 1)} °C).`,
    );
  }
  // Паразитный q↓ при heated: структурированный WARN_UFH_PARASITIC_DOWN_HEATED в matching/warmFloor.js

  /** @type {UfhRoomHeatFluxComputed} */
  const result = {
    areaM2,
    pipeSpacingMm,
    pipeEmbedmentResistanceM2KW: round(rPipeEmbed, 3),
    baseCoveringResistanceM2KW: round(rBaseAbove, 4),
    finishCoveringResistanceM2KW: round(rFinish, 4),
    coveringResistanceM2KW: round(rCovering, 4),
    resistanceUpM2KW: round(rUp, 4),
    resistanceDownM2KW: round(rDown, 4),
    circuitSupplyC: resolvedSupplyC,
    circuitReturnC: resolvedReturnC,
    circuitMeanC: round(circuitMeanC, 1),
    heatFluxUpWm2: round(heatFluxUpWm2, 1),
    heatFluxDownWm2: round(heatFluxDownWm2, 1),
    maxAllowableHeatFluxUpWm2: round(maxAllowableHeatFluxUpWm2, 1),
    heatFluxUpWatts: round(heatFluxUpWatts, 0),
    heatFluxDownWatts: round(heatFluxDownWatts, 0),
    surfaceTempC: round(surfaceTempC, 1),
    maxSurfaceTemperatureCelsius: maxSurfaceT,
    finishMaxSurfaceTemperatureCelsius: surfaceLimits.finishMaxSurfaceT,
    bottomBoundary,
    neighborTempC: round(neighborTempC, 1),
    heatFluxUpLimitedBySurface,
    roomWarnings,
  };
  if (comfortMaxSurfaceT !== undefined) {
    result.comfortMaxSurfaceTemperatureCelsius = comfortMaxSurfaceT;
  }
  if (surfaceLimits.presetMaxSurfaceT != null) {
    result.presetMaxSurfaceTemperatureCelsius = surfaceLimits.presetMaxSurfaceT;
  }
  return result;
}

/**
 * Назначение: расчёт U наружной стены по многослойной конструкции.
 * Описание: Вычисляет коэффициент теплопередачи R = Rsi+Rse + dст/λст + dут/λут для objectMeta.externalWalls с учётом фасадной системы (none/sftk/ventilated). Экспортирует resolveExternalWallUValue и константы пресетов утеплителя. Используется в heatlossByRooms.js и externalWallsValidate.js.
 */

import { getEnvelopePresetById } from './envelopePresets.js';

/** Системы утепления фасада (objectMeta.externalWalls.facadeSystem). */
export const FACADE_SYSTEMS = Object.freeze(['none', 'sftk', 'ventilated']);

/** ППС 16Ф (ПСБ-С 25Ф) — единственный ППС для СФТК по СП 50.13330. */
export const INSUL_SFTK_PPS16F_ID = 'insul_sftk_pps16f';

const MINERAL_WOOL_PREFIX = 'insul_minwool_';

/** Поверхностное сопротивление Rsi+Rse для вертикальных стен, м²·К/Вт. */
export const WALL_SURFACE_R = 0.158;

/** @type {Readonly<{ min: number; max: number }>} */
export const INSULATION_THICKNESS_BOUNDS = Object.freeze({ min: 30, max: 300 });

/**
 * @param {string | null | undefined} presetId
 * @returns {boolean}
 */
export function isMineralWoolInsulationPresetId(presetId) {
  return String(presetId ?? '').startsWith(MINERAL_WOOL_PREFIX);
}

/**
 * @param {string | null | undefined} presetId
 * @returns {boolean}
 */
export function isSftkInsulationPresetId(presetId) {
  return String(presetId ?? '') === INSUL_SFTK_PPS16F_ID;
}

/**
 * λ утеплителя из пресета (только kind=insulation, поле uModel.lambdaWmK).
 *
 * @param {string} insulationPresetId
 * @returns {number | null}
 */
function insulationLambdaFromPresetId(insulationPresetId) {
  const preset = getEnvelopePresetById(insulationPresetId);
  if (!preset || preset.kind !== 'insulation') return null;
  const lambda = preset.uModel?.lambdaWmK;
  return typeof lambda === 'number' && lambda > 0 ? lambda : null;
}

/**
 * U многослойной наружной стены: R = Rпов + dст/λст + dут/λут.
 *
 * @param {object} args
 * @param {number} args.wallLambdaWmK
 * @param {number} args.wallThicknessMm
 * @param {number} [args.insulationLambdaWmK]
 * @param {number} [args.insulationThicknessMm]
 * @param {number} [args.surfaceR]
 * @returns {number}
 */
function computeWallUFromLayers({
  wallLambdaWmK,
  wallThicknessMm,
  insulationLambdaWmK = 0,
  insulationThicknessMm = 0,
  surfaceR = WALL_SURFACE_R,
}) {
  if (!(wallLambdaWmK > 0) || !(wallThicknessMm > 0)) {
    throw new Error('computeWallUFromLayers: некорректные параметры несущего слоя');
  }
  const rWall = wallThicknessMm / 1000 / wallLambdaWmK;
  let rIns = 0;
  if (insulationLambdaWmK > 0 && insulationThicknessMm > 0) {
    rIns = insulationThicknessMm / 1000 / insulationLambdaWmK;
  }
  const rTotal = surfaceR + rWall + rIns;
  if (!(rTotal > 0)) {
    throw new Error('computeWallUFromLayers: суммарное R должно быть > 0');
  }
  return 1 / rTotal;
}

/**
 * U наружной стены объекта по objectMeta.externalWalls и пресету стены.
 *
 * @param {import('../types/shared-types.js').BuildingObjectMetaExternalWalls} externalWalls
 * @param {string | null | undefined} [wallPresetIdOverride] presetId элемента (если отличается)
 * @returns {number}
 */
export function resolveExternalWallUValue(externalWalls, wallPresetIdOverride = undefined) {
  const wallPresetId = wallPresetIdOverride ?? externalWalls?.presetId;
  const wallPreset = getEnvelopePresetById(wallPresetId);
  if (!wallPreset || wallPreset.kind !== 'wall') {
    throw new Error(`resolveExternalWallUValue: неизвестный пресет стены "${wallPresetId}"`);
  }

  const facadeSystem = externalWalls?.facadeSystem ?? 'none';
  const wallThicknessMm = externalWalls?.thicknessMm;

  if (facadeSystem === 'none') {
    if (wallPreset.uModel && wallThicknessMm != null) {
      return computeWallUFromLayers({
        wallLambdaWmK: wallPreset.uModel.lambdaWmK,
        wallThicknessMm,
        surfaceR: wallPreset.uModel.surfaceR ?? WALL_SURFACE_R,
      });
    }
    if (wallPreset.uValue != null) return wallPreset.uValue;
    throw new Error(
      `resolveExternalWallUValue: для "${wallPresetId}" задайте thicknessMm (uModel) или uValue`,
    );
  }

  if (wallThicknessMm == null || !(wallThicknessMm > 0)) {
    throw new Error('resolveExternalWallUValue: задайте thicknessMm несущей стены');
  }
  if (!wallPreset.uModel?.lambdaWmK) {
    throw new Error(
      `resolveExternalWallUValue: пресет "${wallPresetId}" не поддерживает расчёт слоёв (нет uModel)`,
    );
  }

  const insulId = externalWalls?.insulationPresetId;
  const insulThicknessMm = externalWalls?.insulationThicknessMm;
  if (!insulId || insulThicknessMm == null || !(insulThicknessMm > 0)) {
    throw new Error('resolveExternalWallUValue: задайте insulationPresetId и insulationThicknessMm');
  }

  const insulLambda = insulationLambdaFromPresetId(insulId);
  if (insulLambda == null) {
    throw new Error(`resolveExternalWallUValue: неизвестный пресет утеплителя "${insulId}"`);
  }

  return computeWallUFromLayers({
    wallLambdaWmK: wallPreset.uModel.lambdaWmK,
    wallThicknessMm,
    insulationLambdaWmK: insulLambda,
    insulationThicknessMm: insulThicknessMm,
    surfaceR: wallPreset.uModel.surfaceR ?? WALL_SURFACE_R,
  });
}

/**
 * Назначение: оркестратор расчёта водяного тёплого пола по комнатам.
 * Описание: Пресет контура по финишу, смеситель, S_акт, авто-шаг, ufhRoomHeatFlux.
 */

import { resolveUnderfloorHeatingComposition } from '../data/warmFloorAssemblyPresets.js';
import { DEFAULT_PIPE_SPACING_MM } from './ufhPipeEmbedment.js';
import { resolveUfhCircuitForFinish } from './ufhCircuitResolve.js';
import { isMixingNodeRequiredForProject } from './ufhMixingNode.js';
import { resolveUfhDistributionPreset } from '../../../shared/ufhDistributionPresets.js';
import { UFH_PRESET_MIXED_RADIATORS } from '../../../shared/ufhModePresetIds.js';
import { computeUfhMixingNodeSpec } from './ufhMixingNodeHydraulics.js';
import { computeUnderfloorHydraulicsCircuit } from './ufhHydraulicsCircuit.js';
import { computeUfhLoopGeometry } from './ufhLoopGeometry.js';
import { computeUfhRoomHeatFlux } from './ufhRoomHeatFlux.js';
import { resolveUfhActiveFloorAreaM2 } from './ufhActiveFloorArea.js';
import { computeUfhRequiredHeatFluxUpWm2 } from './ufhRequiredHeatFlux.js';
import { resolveUfhPipeSpacingMm } from './ufhPipeSpacingResolve.js';
import {
  assessUfhActiveAreaHeatFlux,
  assessUfhRoomHeatLossCoverage,
  resolveRoomDesignHeatLossWatts,
} from './ufhRoomCoverageCheck.js';
import { round } from '../utils/math.js';
import { resolveDesignRoomAirTempC } from '../../../shared/roomDesignAirTemp.js';

/**
 * @param {object} args
 * @param {{ insideC: number, outsideC: number, bathroomAirTempC?: number }} args.temps
 * @param {import('../types/shared-types.js').BuildingInput | undefined | null} args.building
 * @param {import('../types/shared-types.js').HeatingSystemInput | undefined | null} args.heatingSystem
 * @param {import('../types/shared-types.js').HeatLossReport | undefined | null} [args.heatLoss]
 * @param {import('../ufh/types.js').UnderfloorHeatingPresetsBundle} args.ufhPresets
 * @param {number} [args.maxUfhLoopLengthM]
 * @param {number} [args.ufhLoopLengthLayoutFactor]
 * @returns {import('../types/shared-types.js').UnderfloorHeatingReport | null}
 */
export function calculateUnderfloorHeating(args) {
  const {
    temps,
    building,
    heatingSystem,
    heatLoss,
    ufhPresets,
    maxUfhLoopLengthM = 80,
    ufhLoopLengthLayoutFactor = 1.1,
  } = args;

  if (!ufhPresets?.byPresetId) {
    throw new Error('Розрахунок ТП: ufhPresets обов\'язкові.');
  }

  if (!heatingSystem?.waterUnderfloorHeating && !heatingSystem?.ufhPresetId) {
    return null;
  }

  const ufhPresetId =
    typeof heatingSystem?.ufhPresetId === 'string'
      ? heatingSystem.ufhPresetId.trim()
      : '';
  /** @type {import('../ufh/types.js').NormalizedUfhModePreset | null} */
  let modePreset = null;
  if (ufhPresetId) {
    modePreset = ufhPresets.byPresetId[ufhPresetId] ?? null;
    if (!modePreset) {
      const err = new Error(
        `Неизвестный ufhPresetId "${ufhPresetId}" в расчёте ТП.`,
      );
      /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
      const appErr = err;
      appErr.statusCode = 400;
      appErr.code = 'UFH_PRESET_INVALID';
      throw appErr;
    }
  }

  const rooms = building?.rooms ?? [];
  const boilerSupplyC = heatingSystem.supplyC;
  const surveyInsideC = temps.insideC;
  const bathroomAirTempC =
    typeof temps.bathroomAirTempC === 'number' &&
    Number.isFinite(temps.bathroomAirTempC)
      ? temps.bathroomAirTempC
      : typeof building?.temps?.bathroomAirTempC === 'number' &&
          Number.isFinite(building.temps.bathroomAirTempC)
        ? building.temps.bathroomAirTempC
        : undefined;
  const isUfhOnly = heatingSystem?.heatingEmittersMode === 'ufh_only';

  /** @type {import('../types/shared-types.js').UnderfloorHeatingRoomReport[]} */
  const roomReports = [];
  /** @type {string[]} */
  const globalWarnings = [];

  for (const room of rooms) {
    const composed = resolveUnderfloorHeatingComposition(
      room.underfloorHeating,
    );
    if (!composed) continue;

    const { basePresetId, finishMaterialId, base, finish } = composed;
    let circuitResolved = resolveUfhCircuitForFinish(finishMaterialId);
    if (
      isUfhOnly &&
      typeof heatingSystem.supplyC === 'number' &&
      typeof heatingSystem.returnC === 'number'
    ) {
      circuitResolved = {
        preset: {
          id: 'ufh_dt10_40_30',
          supplyC: heatingSystem.supplyC,
          returnC: heatingSystem.returnC,
          deltaTK: heatingSystem.supplyC - heatingSystem.returnC,
          finishMaterialIds: [finishMaterialId],
          label: 'Графік з режиму ufh_only',
        },
        source: 'finish_preset',
      };
    }
    if (!circuitResolved) {
      globalWarnings.push(
        `Кімната «${room.name}»: для фінішу «${finishMaterialId}» не задано пресет контуру ТП.`,
      );
      continue;
    }

    const { preset } = circuitResolved;
    const circuitMeanC = (preset.supplyC + preset.returnC) / 2;
    const requestedPipeSpacingMm =
      room.underfloorHeating?.pipeSpacingMm ?? DEFAULT_PIPE_SPACING_MM;
    const bottomBoundary =
      room.bottomBoundary ?? base.bottomBoundary ?? 'heated';

    const areaResolved = resolveUfhActiveFloorAreaM2({
      roomAreaM2: room.areaM2,
      ...(room.underfloorHeating?.furnitureOccupiedAreaM2 !== undefined
        ? {
            furnitureOccupiedAreaM2:
              room.underfloorHeating.furnitureOccupiedAreaM2,
          }
        : {}),
    });
    const { roomAreaM2, furnitureOccupiedAreaM2, heatedAreaM2 } = areaResolved;

    const heatingIdx = base.layers.findIndex(
      (/** @type {import('../types/shared-types.js').UnderfloorHeatingAssemblyLayer} */ l) =>
        l.isHeatingLayer,
    );
    if (heatingIdx < 0) {
      globalWarnings.push(
        `Кімната «${room.name}»: у базі ТП немає шару isHeatingLayer.`,
      );
      continue;
    }

    const presetMaxSurfaceT = modePreset?.technical?.maxSurfaceTemperatureC;
    const roomHeatLossWatts = resolveRoomDesignHeatLossWatts(heatLoss, room.id);
    const airResolved = resolveDesignRoomAirTempC({
      roomType: room.type,
      insideC: surveyInsideC,
      ...(bathroomAirTempC !== undefined ? { bathroomAirTempC } : {}),
    });
    const insideC = airResolved?.designAirTempC ?? surveyInsideC;

    const requiredHeatFluxUpWm2 = computeUfhRequiredHeatFluxUpWm2({
      roomHeatLossWatts,
      heatedAreaM2,
    });

    const fluxContext = {
      base,
      finish,
      circuitMeanC,
      circuitSupplyC: preset.supplyC,
      circuitReturnC: preset.returnC,
      presetMaxSurfaceTemperatureC: presetMaxSurfaceT,
      insideC,
      outsideC: temps.outsideC,
      bottomBoundary,
    };

    const spacingResolved = resolveUfhPipeSpacingMm({
      requestedPipeSpacingMm,
      qRequiredWm2: requiredHeatFluxUpWm2,
      fluxContext,
    });

    const flux = computeUfhRoomHeatFlux({
      ...fluxContext,
      pipeSpacingMm: spacingResolved.resolvedPipeSpacingMm,
      areaM2: heatedAreaM2,
    });

    const activeAreaCheck = assessUfhActiveAreaHeatFlux({
      heatedAreaM2,
      qRequiredWm2: requiredHeatFluxUpWm2,
      maxAllowableHeatFluxUpWm2: flux.maxAllowableHeatFluxUpWm2,
    });

    const coverage = assessUfhRoomHeatLossCoverage({
      heatFluxUpWatts: flux.heatFluxUpWatts,
      roomHeatLossWatts,
    });

    const loopGeom = computeUfhLoopGeometry({
      areaM2: heatedAreaM2,
      pipeSpacingMm: spacingResolved.resolvedPipeSpacingMm,
      heatLoadWatts: flux.heatFluxUpWatts,
      deltaTK: 10,
      maxLoopLengthM: maxUfhLoopLengthM,
      layoutFactor: ufhLoopLengthLayoutFactor,
      roomId: room.id,
    });

    const roomWarnings = flux.roomWarnings.map(
      (w) => `Кімната «${room.name}»: ${w}`,
    );

    /** @type {import('../types/shared-types.js').UfhTerminalControl} */
    const ufhTerminalControl =
      room.underfloorHeating?.ufhTerminalControl === 'unibox'
        ? 'unibox'
        : 'collector';

    /** @type {import('../types/shared-types.js').UnderfloorHeatingRoomReport} */
    const roomReport = {
      roomId: room.id,
      roomName: room.name,
      basePresetId,
      finishMaterialId,
      basePresetName: base.name,
      finishMaterialName: finish.name,
      ufhCircuitPresetId: preset.id,
      designAirTempC: insideC,
      designAirTempSource: airResolved?.source ?? 'survey',
      roomAreaM2,
      furnitureOccupiedAreaM2,
      heatedAreaM2,
      requestedPipeSpacingMm: spacingResolved.requestedPipeSpacingMm,
      resolvedPipeSpacingMm: spacingResolved.resolvedPipeSpacingMm,
      pipeSpacingResolution: spacingResolved.pipeSpacingResolution,
      areaM2: heatedAreaM2,
      pipeSpacingMm: spacingResolved.resolvedPipeSpacingMm,
      pipeEmbedmentResistanceM2KW: flux.pipeEmbedmentResistanceM2KW,
      baseCoveringResistanceM2KW: flux.baseCoveringResistanceM2KW,
      finishCoveringResistanceM2KW: flux.finishCoveringResistanceM2KW,
      coveringResistanceM2KW: flux.coveringResistanceM2KW,
      resistanceUpM2KW: flux.resistanceUpM2KW,
      resistanceDownM2KW: flux.resistanceDownM2KW,
      circuitSupplyC: flux.circuitSupplyC,
      circuitReturnC: flux.circuitReturnC,
      circuitMeanC: flux.circuitMeanC,
      heatFluxUpWm2: flux.heatFluxUpWm2,
      heatFluxDownWm2: flux.heatFluxDownWm2,
      maxAllowableHeatFluxUpWm2: flux.maxAllowableHeatFluxUpWm2,
      heatFluxUpWatts: flux.heatFluxUpWatts,
      heatFluxDownWatts: flux.heatFluxDownWatts,
      surfaceTempC: flux.surfaceTempC,
      maxSurfaceTemperatureCelsius: flux.maxSurfaceTemperatureCelsius,
      bottomBoundary: flux.bottomBoundary,
      neighborTempC: flux.neighborTempC,
      heatFluxUpLimitedBySurface: flux.heatFluxUpLimitedBySurface,
      warnings: roomWarnings,
    };
    roomReport.pipeMetersPerSqM = loopGeom.pipeMetersPerSqM;
    roomReport.loopLengthLayoutFactor = loopGeom.layoutFactor;
    roomReport.ufhTerminalControl = ufhTerminalControl;
    roomReport.heatLoadWatts = flux.heatFluxUpWatts;
    roomReport.flowRateM3PerHour = loopGeom.flowRateM3PerHour;
    roomReport.loopsCount = loopGeom.loopsCount;
    roomReport.loops = loopGeom.loops;
    roomReport.heatFluxCoverageStatus = coverage.coverageStatus;
    roomReport.activeAreaCheckStatus = activeAreaCheck.status;
    roomReport.finishMaxSurfaceTemperatureCelsius =
      flux.finishMaxSurfaceTemperatureCelsius;
    if (requiredHeatFluxUpWm2 != null) {
      roomReport.requiredHeatFluxUpWm2 = requiredHeatFluxUpWm2;
    }
    if (roomHeatLossWatts != null) {
      roomReport.roomHeatLossWatts = roomHeatLossWatts;
    }
    if (coverage.heatFluxCoverageRatio != null) {
      roomReport.heatFluxCoverageRatio = coverage.heatFluxCoverageRatio;
    }
    if (flux.comfortMaxSurfaceTemperatureCelsius !== undefined) {
      roomReport.comfortMaxSurfaceTemperatureCelsius =
        flux.comfortMaxSurfaceTemperatureCelsius;
    }
    if (flux.presetMaxSurfaceTemperatureCelsius != null) {
      roomReport.presetMaxSurfaceTemperatureCelsius =
        flux.presetMaxSurfaceTemperatureCelsius;
    }
    roomReports.push(roomReport);
  }

  if (roomReports.length === 0) {
    globalWarnings.push(
      'Водяну теплу підлогу увімкнено в анкеті, але жодній кімнаті не задано basePresetId і finishMaterialId.',
    );
  }

  let mixingRequired = false;
  const mixingForcedOffByPreset =
    modePreset != null && modePreset.technical.hasMixingNode === false;
  if (modePreset != null && modePreset.technical.hasMixingNode === false) {
    if (roomReports.length > 0) {
      globalWarnings.push(
        `Змішувальний вузол не потрібен за пресетом режиму ТП «${modePreset.ui.title}» (пряме підключення, котел ${boilerSupplyC ?? '—'} °C).`,
      );
    }
  } else {
    mixingRequired = isMixingNodeRequiredForProject(boilerSupplyC, roomReports);
  }

  const objectType = building?.objectMeta?.objectType;
  const distributionPreset = mixingRequired
    ? resolveUfhDistributionPreset(
        heatingSystem?.underfloorDistributionPreset,
        {
          ...(objectType !== undefined ? { objectType } : {}),
          roomsWithUfhCount: roomReports.length,
        },
      )
    : undefined;

  if (mixingRequired) {
    globalWarnings.push(
      `Потрібен насосно-змішувальний вузол: подача котла ${boilerSupplyC ?? '—'} °C вище температури контуру ТП ` +
        `(по комнатам ${roomReports.map((r) => `${r.circuitSupplyC}/${r.circuitReturnC}`).join(', ')} °C).`,
    );
  } else if (
    !mixingForcedOffByPreset &&
    roomReports.length > 0 &&
    typeof boilerSupplyC === 'number'
  ) {
    globalWarnings.push(
      `Змішувальний вузол не потрібен: подача котла ${boilerSupplyC} °C не вище подачі контуру ТП.`,
    );
  }

  const primaryRoom = roomReports[0];
  const circuitSource =
    modePreset?.presetId === UFH_PRESET_MIXED_RADIATORS
      ? 'finish_preset'
      : modePreset
        ? 'ufh_mode_preset'
        : primaryRoom
          ? 'finish_preset'
          : 'mixed_default';

  const totalHeatFluxUpWatts = round(
    roomReports.reduce((s, r) => s + r.heatFluxUpWatts, 0),
    0,
  );
  const totalHeatFluxDownWatts = round(
    roomReports.reduce((s, r) => s + r.heatFluxDownWatts, 0),
    0,
  );

  const underfloorHydraulics = computeUnderfloorHydraulicsCircuit({
    heatLoadWatts: totalHeatFluxUpWatts,
    deltaTK: 10,
  });

  /** @type {import('../types/shared-types.js').UfhMixingNodeSpec | null} */
  let mixingNode = null;
  if (mixingRequired && distributionPreset) {
    mixingNode = computeUfhMixingNodeSpec({
      powerKw: totalHeatFluxUpWatts / 1000,
      deltaTK: 10,
      distributionPreset,
    });
    if (boilerSupplyC !== undefined) {
      mixingNode.boilerSupplyC = boilerSupplyC;
    }
    if (primaryRoom?.circuitSupplyC !== undefined) {
      mixingNode.floorCircuitSupplyC = primaryRoom.circuitSupplyC;
    }
  }

  return {
    enabled: true,
    circuitSupplyC: primaryRoom?.circuitSupplyC ?? 45,
    circuitReturnC: primaryRoom?.circuitReturnC ?? 35,
    circuitMeanC: primaryRoom?.circuitMeanC ?? 40,
    circuitSource,
    isMixingNodeRequired: mixingRequired,
    ...(distributionPreset !== undefined ? { distributionPreset } : {}),
    ...(mixingNode != null ? { mixingNode } : {}),
    underfloorHydraulics,
    rooms: roomReports,
    totalHeatFluxUpWatts,
    totalHeatFluxDownWatts,
    // Только глобальные WARN: комнатные остаются в rooms[].warnings (без дубля в корне).
    warnings: globalWarnings,
  };
}

/**
 * Назначение: подбор котлов из каталога.
 * Описание: фильтрация по контуру, монтажу и типу горения; формирование основной линии и альтернатив
 * proposalEconomy/proposalEfficient; каскад, запас мощности и структурированные рекомендации.
 */
import { buildMatchingSortPools } from '../catalog/matchingSortPools.js';
import { logger } from '../utils/logger.js';
import {
  buildCondensingBoilerMatchingRecommendations,
  buildCondensingCascadeHint,
  buildTraditionalCascadeHint,
  chimneyNotesForBoilerCombustionType,
  condensingDrainNoteText,
  filterBoilersByCircuitMode,
  filterBoilersForEconomyLine,
  filterBoilersForEfficientLine,
  heatingLoadKwForCondensingLine,
  isCondensingBoiler,
  matchesCombustionTypePreference,
  requiredKwFromHeatingAndDhw,
} from '../utils/boilerMatchingByType.js';
import { pushRecommendation } from '../recommendations/recommendationResolver.js';
import { assertCalcRuntimeContext } from '../reference/assertCalcRuntimeContext.js';
import {
  SCHEME_BOILER_ELECTRIC_SEPARATE,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_COMBI_BUFFER_ELECTRIC,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
  SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC,
} from '../../../shared/heatingMatchingSchemes.js';
import {
  filterBoilersByMountingConstraints,
  resolveObjectType,
} from '../utils/boilerMountingConstraints.js';
import { smallestSingleCircuitMaxKw } from '../utils/apartmentMatching.js';
import {
  apartmentCombiSerialBufferTemplateVars,
  buildApartmentCombiSerialBufferRecommendation,
  isApartmentCombiSerialBufferEligible,
} from '../utils/apartmentCombiSerialBufferHint.js';
import { indirectMinSourcePowerKw } from './internal/indirectCatalogHelpers.js';
import { isHighTemperatureHeatingGraph } from '../logic/heatingThermalRegimes.js';

/**
 * Значение по умолчанию: двухконтурный котёл, при открытии крана — полная отдача на горячую воду (max по мощностям).
 * @type {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme}
 */
const DEFAULT_HOT_WATER_BOILER_POWER_MATCHING_SCHEME = SCHEME_BOILER_MAX_COMBI;

/**
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized} boiler
 * @param {number} requiredKw
 * @returns {{ count: number, totalNominalKw: number }}
 */
function cascadeForBoiler(boiler, requiredKw) {
  const maxPw = boiler?.powerKw?.max ?? 0;
  if (maxPw <= 0) return { count: 0, totalNominalKw: 0 };
  const count = Math.max(1, Math.ceil(requiredKw / maxPw));
  return { count, totalNominalKw: Number((count * maxPw).toFixed(2)) };
}

/**
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized[]} boilers
 * @param {number} requiredKw
 * @returns {{ boiler: import('../catalog/types.js').BoilerCatalogItemNormalized, count: number, totalNominalKw: number } | null}
 */
function pickBestCascade(boilers, requiredKw) {
  /** @type {{ boiler: import('../catalog/types.js').BoilerCatalogItemNormalized, count: number, totalNominalKw: number } | null} */
  let best = null;
  for (const b of boilers) {
    const { count, totalNominalKw } = cascadeForBoiler(b, requiredKw);
    if (count < 1) continue;
    if (
      !best ||
      count < best.count ||
      (count === best.count && totalNominalKw < best.totalNominalKw)
    ) {
      best = { boiler: b, count, totalNominalKw };
    }
  }
  return best;
}

/**
 * Самый мощный котёл в пуле по powerKw.max (один аппарат без каскада).
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized[]} boilers
 * @returns {import('../catalog/types.js').BoilerCatalogItemNormalized | null}
 */
function pickStrongestBoilerFromPool(boilers) {
  if (!boilers?.length) return null;
  /** @type {import('../catalog/types.js').BoilerCatalogItemNormalized | null} */
  let best = null;
  let bestMax = -Infinity;
  for (const b of boilers) {
    const m = Number(b?.powerKw?.max ?? 0);
    if (m > bestMax) {
      bestMax = m;
      best = b;
    }
  }
  return best;
}

/**
 * Разбивка для карточки proposal (поле powerRequirementBreakdown).
 * @param {number} heatingKw отопление×запас для линии карточки
 * @param {number} hwKw расчётная мощность ГВС из отчёта
 * @returns {import('../types/boiler-types.js').BoilerEquipmentProposalPowerBreakdown}
 */
function buildPowerRequirementBreakdown(heatingKw, hwKw) {
  return {
    heatingLoadKw: Number(Math.max(0, Number(heatingKw) || 0).toFixed(2)),
    hotWaterPowerKw: Number(Math.max(0, Number(hwKw) || 0).toFixed(2)),
  };
}

/**
 * Подпись линии «Эффективный» в headline proposal (квартира vs дом, схема ГВС).
 *
 * @param {boolean} electricSeparate
 * @param {'apartment' | 'house'} resolvedObjectType
 * @param {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} scheme
 * @returns {string}
 */
function efficientProposalHeadlineSuffix(
  electricSeparate,
  resolvedObjectType,
  scheme,
) {
  if (electricSeparate) {
    return 'конденсаційний одноконтурний (опалення; ГВП окремо)';
  }
  if (scheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC) {
    return 'конденсаційний двоконтурний (max) + буферний ЕВН';
  }
  if (scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM) {
    return 'конденсаційний одноконтурний + БКН';
  }
  if (resolvedObjectType === 'apartment') {
    return 'конденсаційний одноконтурний (опалення; ГВП — за обраною схемою)';
  }
  return 'конденсаційний одноконтурний + БКН';
}

/**
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized[]} boilers
 * @param {number} requiredKw
 * @param {'economy' | 'efficient'} tier
 * @param {string} tierHeadlineSuffix
 * @param {object} extra
 * @param {boolean} [extra.forceSingleUnit] без каскада
 * @param {number} [extra.heatingLoadKwForReserve] база для nominalReservePercent по отоплению
 * @param {import('../types/boiler-types.js').BoilerEquipmentProposalPowerBreakdown} extra.powerRequirementBreakdown
 * @param {import('../dhw/types.js').BoilerApplianceRules} extra.boilerRules
 * @returns {import('../types/boiler-types.js').BoilerEquipmentProposal | null}
 */
function pickSingleOrCascadeProposal(
  boilers,
  requiredKw,
  tier,
  tierHeadlineSuffix,
  extra,
) {
  const forceSingleUnit = extra.forceSingleUnit === true;
  const heatingLoadKwForReserve = extra.heatingLoadKwForReserve;
  const powerRequirementBreakdown = extra.powerRequirementBreakdown;
  const boilerRules = extra.boilerRules;
  const req = Math.max(0, Number(requiredKw) || 0);
  if (!boilers.length || req <= 0) return null;
  const selectedSingle =
    boilers.find((b) => (b?.powerKw?.max ?? 0) >= req) ?? null;
  if (selectedSingle) {
    return buildProposalObject(
      selectedSingle,
      'single',
      1,
      selectedSingle.powerKw.max,
      req,
      {
        tier,
        condensingDrainNote: isCondensingBoiler(selectedSingle),
        tierHeadlineSuffix,
        heatingLoadKwForReserve,
        powerRequirementBreakdown,
        boilerRules,
      },
    );
  }
  if (forceSingleUnit) {
    const strongest = pickStrongestBoilerFromPool(boilers);
    if (!strongest) return null;
    const maxPw = Number(strongest.powerKw?.max ?? 0);
    return buildProposalObject(strongest, 'single', 1, maxPw, req, {
      tier,
      condensingDrainNote: isCondensingBoiler(strongest),
      tierHeadlineSuffix,
      heatingLoadKwForReserve,
      powerRequirementBreakdown,
      boilerRules,
    });
  }
  const cascade = pickBestCascade(boilers, req);
  if (!cascade) return null;
  return buildProposalObject(
    cascade.boiler,
    'cascade',
    cascade.count,
    cascade.totalNominalKw,
    req,
    {
      tier,
      condensingDrainNote: isCondensingBoiler(cascade.boiler),
      tierHeadlineSuffix,
      powerRequirementBreakdown,
      boilerRules,
    },
  );
}

/**
 * Пояснения по сценариям горячей воды (дополнение к расчёту по расходам с точек разбора).
 * @param {import('../types/shared-types.js').HotWaterFixturesInput | undefined} fixtures
 * @param {number} hotWaterPowerKw
 * @param {number} heatLossKw потери отопления, кВт
 * @param {number} reserveFactor
 * @param {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} hotWaterBoilerPowerMatchingScheme
 * @param {'flowThrough' | 'storage' | undefined} dhwSupplyScenario
 * @param {import('../dhw/types.js').BoilerApplianceRules} boilerRules
 * @returns {import('../types/boiler-types.js').BoilerMatchingRecommendation[]}
 */
function buildHotWaterScenarioRecommendations(
  fixtures,
  hotWaterPowerKw,
  heatLossKw,
  reserveFactor,
  hotWaterBoilerPowerMatchingScheme,
  dhwSupplyScenario,
  boilerRules,
) {
  /** @type {import('../types/boiler-types.js').BoilerMatchingRecommendation[]} */
  const out = [];
  const sh = fixtures?.shower ?? 0;
  const bath = fixtures?.bath ?? 0;
  const toilet = fixtures?.toilet ?? 0;
  const sink = fixtures?.sink ?? 0;

  const heatPartKw = Number(heatLossKw) * Number(reserveFactor);
  const electricWaterHeaterScheme =
    hotWaterBoilerPowerMatchingScheme === SCHEME_BOILER_ELECTRIC_SEPARATE;
  const combiBufferElectricScheme =
    hotWaterBoilerPowerMatchingScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC;
  const singleIndirectSumScheme =
    hotWaterBoilerPowerMatchingScheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM;
  const storageScenario = dhwSupplyScenario === 'storage';

  if (sh >= 2) {
    if (electricWaterHeaterScheme) {
      out.push({
        type: 'parallel_hot_water_high_flow_two_showers_electric_storage_water_heater',
        message:
          'Враховуйте одночасний витрата двох душів: потужність котла за розрахунком лише для опалення з запасом; перевірте допустиму швидкість нагрівання та запас по електромережі для накопичувального водонагрівача.',
      });
    } else if (storageScenario && singleIndirectSumScheme) {
      out.push({
        type: 'parallel_hot_water_two_showers_single_indirect_sum',
        message:
          'Враховуйте одночасний витрата двох душів: за схемою «1К + БКН» потрібна потужність котла — сума опалення з запасом і нагрівання бака; перевірте об’єм БКН і час відновлення запасу гарячої води.',
      });
    } else if (combiBufferElectricScheme) {
      out.push({
        type: 'parallel_hot_water_two_showers_combi_buffer_electric',
        message:
          'Враховуйте одночасний витрата двох душів: котел підбирається за max(опалення з запасом, пік ГВП); буферний електробойлер згладжує температурні стрибки — перевірте об’єм буфера та потужність ТЕНa при тривалому піку.',
      });
    } else if (storageScenario) {
      out.push({
        type: 'parallel_hot_water_two_showers_storage_boiler_not_from_peak_flow',
        message:
          'Враховуйте одночасний витрата двох душів: для будинку з накопичувачем (БКН) розрахункова потужність на гарячу воду для котла береться від нагрівання бака за заданий час, а не від піку «проливу»; за потреби збільште об’єм бака або узгодьте час відновлення запасу гарячої води.',
      });
    } else {
      out.push({
        type: 'parallel_hot_water_high_flow_two_showers_combination_boiler_maximum_power_rule',
        message:
          'Враховуйте одночасний витрата двох душів: для двоконтурного котла з пріоритетом гарячої води потрібна потужність береться як максимум з опалення з запасом і розрахунку гарячої води (без сумування). За високих піків розгляньте схему одноконтурного котла з БКН (поле heatingSystem.hotWaterBoilerPowerMatchingScheme).',
      });
    }
  }

  const hintRules = boilerRules.hints;
  if (
    !electricWaterHeaterScheme &&
    !storageScenario &&
    sh <= 1 &&
    bath <= 1 &&
    toilet >= 1 &&
    sink >= 1 &&
    heatPartKw <= hintRules.comfortHotWaterHeatPartKwMax &&
    hotWaterPowerKw <= hintRules.comfortHotWaterDhwKwMax
  ) {
    const typicalKw = hintRules.comfortHotWaterTypicalBoilerKw;
    out.push({
      type: 'comfort_hot_water_typical_twenty_four_kilowatt_hint_combination_boiler',
      message: `За двох санвузлів з помірним водорозбором і невеликим тепловим навантаженням на опалення часто обирають котли близько ${typicalKw} кВт для комфорту гарячої води — звірте з розрахунковою потрібною потужністю котла та паспортом.`,
    });
  }

  return out;
}

/**
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized} boiler
 * @param {'single' | 'cascade'} kind
 * @param {number} unitsCount
 * @param {number} totalNominalKw
 * @param {number} requiredKw
 * @param {object} opts
 * @param {'economy' | 'efficient'} [opts.tier]
 * @param {boolean} [opts.condensingDrainNote]
 * @param {string} [opts.tierHeadlineSuffix]
 * @param {number} [opts.heatingLoadKwForReserve] база процента запаса для одиночного котла: отопление×запас (или конденсационная база), сравнение с powerKw.min
 * @param {import('../types/boiler-types.js').BoilerEquipmentProposalPowerBreakdown} opts.powerRequirementBreakdown составляющие для UI («из них на отопление / ГВС»)
 * @param {import('../dhw/types.js').BoilerApplianceRules} [opts.boilerRules]
 * @returns {import('../types/boiler-types.js').BoilerEquipmentProposal}
 */
function buildProposalObject(
  boiler,
  kind,
  unitsCount,
  totalNominalKw,
  requiredKw,
  opts,
) {
  const req = Math.max(0, Number(requiredKw) || 0);
  const heatingBasis = opts.heatingLoadKwForReserve;
  /** @type {number} */
  let nominalReservePercent = 0;
  if (kind === 'single' && heatingBasis != null && Number(heatingBasis) > 0) {
    const boilerMin = Number(boiler.powerKw?.min ?? boiler.powerKw?.max ?? 0);
    const hl = Number(heatingBasis);
    const cap = opts.boilerRules?.matching.nominalReservePercentCap ?? 150;
    nominalReservePercent = Math.min(
      Math.round(((boilerMin - hl) / hl) * 100),
      cap,
    );
  } else if (req > 0) {
    nominalReservePercent = Number(
      ((totalNominalKw / req - 1) * 100).toFixed(1),
    );
  }

  const tier = opts.tier;
  const tierHeadlineSuffix = opts.tierHeadlineSuffix ?? '';
  let headline = kind === 'single' ? 'Одиночний котел' : 'Каскадна котельня';
  if (tier === 'economy') {
    headline =
      kind === 'cascade'
        ? `Економ: каскад (${tierHeadlineSuffix})`
        : `Економ: один котел (${tierHeadlineSuffix})`;
  }
  if (tier === 'efficient') {
    headline =
      kind === 'cascade'
        ? `Ефективний: каскад (${tierHeadlineSuffix})`
        : `Ефективний: один котел (${tierHeadlineSuffix})`;
  }

  /** @type {string[]} */
  const advantages = [];
  if (kind === 'cascade' && unitsCount > 1) {
    advantages.push(
      `Резервування: за відмови одного апарата інші ${unitsCount - 1} продовжують опалення (зі зниженням потужності).`,
    );
  }
  const eff = boiler.efficiencyPercent;
  if (eff != null && Number.isFinite(eff)) {
    advantages.push(
      `Заявлений ККД до ${eff}% (за паспортними даними виробника; для конденсаційних моделей часто приводять до ВНК).`,
    );
  }

  /** @type {string[]} */
  const notes = [];
  if (req > 50) {
    notes.push(
      'Увага! За такої розрахункової потужності рекомендується гідравлічний роздільник (гідрострілка) та узгодження з проєктом.',
    );
  }
  if (opts.condensingDrainNote && isCondensingBoiler(boiler)) {
    notes.push(condensingDrainNoteText());
  }
  notes.push(...chimneyNotesForBoilerCombustionType(boiler));

  /** @type {import('../types/boiler-types.js').BoilerEquipmentProposal} */
  const proposal = {
    kind,
    headline,
    model: boiler.model,
    unitsCount,
    unitMaxPowerKw: Number((boiler.powerKw?.max ?? 0).toFixed(2)),
    totalNominalKw: Number(totalNominalKw.toFixed(2)),
    requiredKw: Number(req.toFixed(2)),
    powerRequirementBreakdown: opts.powerRequirementBreakdown,
    nominalReservePercent,
    advantages,
    notes,
  };
  if (tier) proposal.tier = tier;

  if (boiler.price != null && Number.isFinite(boiler.price)) {
    proposal.estimatedTotalPrice = Number(
      (boiler.price * unitsCount).toFixed(2),
    );
  }
  if (boiler.mountingType) proposal.mountingType = boiler.mountingType;
  if (boiler.connectionDiameters?.length) {
    proposal.connectionDiameters = [...boiler.connectionDiameters];
  }

  return proposal;
}

/**
 * Підбір котла з каталогу під розрахункове навантаження.
 *
 * @param {object} args
 * @param {number} args.heatLossWatts
 * @param {number} [args.hotWaterPowerKw]
 * @param {number} [args.peakThermalPowerKw] пик проточной ГВС, кВт — для max-combi при storage-сценарии (1К + электробойлер)
 * @param {number} [args.reserveFactor]
 * @param {import('../types/boiler-types.js').BoilerCombustionType} [args.boilerCombustionType]
 * @param {import('../types/shared-types.js').HotWaterFixturesInput} [args.hotWaterFixtures]
 * @param {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} [args.hotWaterBoilerPowerMatchingScheme]
 * @param {'flowThrough' | 'storage'} [args.dhwSupplyScenario] из расчёта hotWater (тип объекта)
 * @param {'double' | 'single' | null} [args.boilerCircuitFilterMode] фильтр каталога по контурам; из matchEquipment — всегда resolveBoilerCircuitFilterMode (single | double, без null)
 * @param {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized | null} [args.selectedWaterHeater] выбранный БКН (для схемы «1К + БКН» — учёт specs.minSourcePowerKw при подборе и в альтернативной линии «Эффективный»)
 * @param {'apartment' | 'house'} [args.objectType] квартира или двухконтурная схема — без каскада (один котёл)
 * @param {import('../types/shared-types.js').BuildingInput} [args.building] анкета (objectMeta, rooms) - фильтр монтажа
 * @param {import('../types/shared-types.js').HeatingSystemInput} [args.heatingSystem]
 * @param {import('../types/shared-types.js').CalcRuntimeContext} args.ctx
 * @returns {import('../types/boiler-types.js').BoilerMatchingReport}
 */
export function pickBoiler({
  heatLossWatts,
  hotWaterPowerKw = 0,
  peakThermalPowerKw = 0,
  reserveFactor: reserveFactorArg,
  boilerCombustionType = undefined,
  hotWaterFixtures = undefined,
  hotWaterBoilerPowerMatchingScheme = undefined,
  dhwSupplyScenario = undefined,
  boilerCircuitFilterMode = null,
  selectedWaterHeater = null,
  objectType = 'house',
  building = undefined,
  heatingSystem = undefined,
  ctx,
}) {
  assertCalcRuntimeContext(ctx);
  const { catalog, appliances, recommendations: recommendationsBundle } = ctx;
  const boilerRules = appliances.byKind.boiler;
  const reserveFactor =
    reserveFactorArg ?? boilerRules.matching.heatingReserveFactor;
  const objectMeta = building?.objectMeta;
  const resolvedObjectType = objectMeta
    ? resolveObjectType(objectMeta)
    : objectType === 'apartment'
      ? 'apartment'
      : 'house';
  const heatLossKw = (Number(heatLossWatts) || 0) / 1000;
  const heatingLoadKw = heatLossKw * reserveFactor;
  const heatingLoadKwCondensing = heatingLoadKwForCondensingLine(
    heatLossKw,
    boilerRules,
  );
  const hwKw = Number(hotWaterPowerKw) || 0;
  const peakHwKw = Number(peakThermalPowerKw) || 0;
  /** @type {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} */
  const scheme =
    hotWaterBoilerPowerMatchingScheme ??
    DEFAULT_HOT_WATER_BOILER_POWER_MATCHING_SCHEME;

  /** @type {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} */
  let effectiveScheme = scheme;
  /** @type {import('../types/boiler-types.js').BoilerCircuitFallbackReport | null} */
  let circuitFallback = null;

  const forceSingleBoiler =
    resolvedObjectType === 'apartment' ||
    scheme === SCHEME_BOILER_MAX_COMBI ||
    scheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC;

  const hwKwForBoilerFormulaEarly =
    scheme === SCHEME_BOILER_MAX_COMBI ||
    scheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC
      ? peakHwKw > 0
        ? peakHwKw
        : hwKw
      : hwKw;

  let requiredKw = requiredKwFromHeatingAndDhw(
    scheme,
    heatingLoadKw,
    hwKwForBoilerFormulaEarly,
  );
  let requiredKwCondensing = requiredKwFromHeatingAndDhw(
    scheme,
    heatingLoadKwCondensing,
    hwKwForBoilerFormulaEarly,
  );

  const minSourceKwBkn = indirectMinSourcePowerKw(selectedWaterHeater);
  if (scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM && minSourceKwBkn != null) {
    requiredKw = Math.max(requiredKw, minSourceKwBkn);
    requiredKwCondensing = Math.max(requiredKwCondensing, minSourceKwBkn);
  }

  logger.info('matching.boiler.start', null, {
    heatLossKw,
    reserveFactor,
    heatingLoadKw,
    heatingLoadKwCondensing,
    hotWaterPowerKw: hwKw,
    hotWaterBoilerPowerMatchingScheme: scheme,
    requiredKw,
    requiredKwCondensing,
    minSourcePowerKwIndirect: minSourceKwBkn,
    boilerCombustionType: boilerCombustionType ?? null,
    dhwSupplyScenario: dhwSupplyScenario ?? null,
    boilerCircuitFilterMode: boilerCircuitFilterMode ?? null,
    forceSingleBoiler,
    objectType: resolvedObjectType,
    boilerPlacementZone: objectMeta?.boilerPlacementZone ?? null,
  });

  const sortPools = buildMatchingSortPools(catalog);
  const boilersAll = sortPools.boilersSortedByMaxPower;
  const boilersPositive = boilersAll.filter(
    (b) => (Number(b?.powerKw?.max) || 0) > 0,
  );

  /** @type {import('../catalog/types.js').BoilerCatalogItemNormalized[]} */
  let boilersFiltered = boilersPositive.filter((b) =>
    matchesCombustionTypePreference(
      boilerCombustionType,
      /** @type {Record<string, unknown>} */ (/** @type {unknown} */ (b)),
    ),
  );
  /** @type {import('../types/boiler-types.js').BoilerCombustionType | null} */
  let combustionTypeFilterApplied = boilerCombustionType ?? null;

  const warnings = [];
  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const resolvedRecommendations = [];
  let boilerUnderpoweredFromCatalog = false;
  if (
    boilerCombustionType &&
    boilersFiltered.length === 0 &&
    boilersPositive.length > 0
  ) {
    warnings.push(
      `У каталозі немає котлів з combustionType="${boilerCombustionType}" — підбір виконано за повним списком.`,
    );
    boilersFiltered = boilersPositive;
    combustionTypeFilterApplied = null;
  }

  /** Пул после фильтра камеры — альтернативная линия «Эффективный» без ограничения контура основного режима */
  let boilersAfterCombustion = boilersFiltered;

  const countBeforeMounting = boilersFiltered.length;
  boilersFiltered = filterBoilersByMountingConstraints(
    boilersFiltered,
    objectMeta,
    building,
    boilerRules.mounting,
  );
  boilersAfterCombustion = filterBoilersByMountingConstraints(
    boilersAfterCombustion,
    objectMeta,
    building,
    boilerRules.mounting,
  );
  if (countBeforeMounting > 0 && boilersFiltered.length === 0) {
    warnings.push(
      resolvedObjectType === 'apartment'
        ? `Немає котлів у каталозі, придатних для квартири (настінні, номінал до ${boilerRules.mounting.maxApartmentNominalKw} кВт; напольні моделі виключено).`
        : 'Немає котлів, придатних за типом монтажу та зоною встановлення (напольні — лише при boilerPlacementZone=boiler_room і достатньому об’ємі котельні).',
    );
  }

  const countBeforeCircuit = boilersAfterCombustion.length;

  /** @type {'double' | 'single' | null} */
  let circuitFilterModeEffective = boilerCircuitFilterMode;
  const singlePoolPreview = filterBoilersByCircuitMode(
    boilersAfterCombustion,
    'single',
  );

  if (
    scheme === SCHEME_BOILER_ELECTRIC_SEPARATE &&
    resolvedObjectType === 'apartment'
  ) {
    const aptRules = boilerRules.apartmentClassification;
    const smallestSingleMax = smallestSingleCircuitMaxKw(singlePoolPreview);
    /** @type {'no_single_in_catalog' | null} */
    let fallbackReason = null;

    if (singlePoolPreview.length === 0 && boilersAfterCombustion.length > 0) {
      fallbackReason = 'no_single_in_catalog';
    } else if (
      singlePoolPreview.length > 0 &&
      heatingLoadKw > 0 &&
      smallestSingleMax != null &&
      smallestSingleMax / heatingLoadKw >= aptRules.singleCircuitOversizeRatio
    ) {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendationsBundle,
        'REC_APT_SINGLE_TO_COMBI_OPTIMIZATION',
        {
          heatingLoadKw: Number(heatingLoadKw.toFixed(1)),
          smallestSingleMaxKw: Number((smallestSingleMax ?? 0).toFixed(1)),
        },
      );
      warnings.push(
        `Мінімальний одноконтурний котел у каталозі (${Number(smallestSingleMax.toFixed(1))} кВт) суттєво вищий за розрахункове опалювальне навантаження (${Number(heatingLoadKw.toFixed(1))} кВт). Збережено схему «1К + електробойлер»: котел — лише опалення, ГВП — накопичувач. Для переходу на двоконтурний котел див. рекомендацію REC_APT_SINGLE_TO_COMBI_OPTIMIZATION.`,
      );
    }

    if (fallbackReason === 'no_single_in_catalog') {
      effectiveScheme = SCHEME_BOILER_MAX_COMBI;
      circuitFilterModeEffective = 'double';
      circuitFallback = {
        from: 'single',
        to: 'double',
        reason: fallbackReason,
        effectiveScheme,
        ...(smallestSingleMax != null
          ? { smallestSingleMaxKw: Number(smallestSingleMax.toFixed(1)) }
          : {}),
      };
      requiredKw = requiredKwFromHeatingAndDhw(
        effectiveScheme,
        heatingLoadKw,
        peakHwKw > 0 ? peakHwKw : hwKw,
      );
      requiredKwCondensing = requiredKwFromHeatingAndDhw(
        effectiveScheme,
        heatingLoadKwCondensing,
        peakHwKw > 0 ? peakHwKw : hwKw,
      );

      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendationsBundle,
        'WARN_APT_ELECTRIC_TO_COMBI_NO_SINGLE',
      );
    }
  }

  boilersFiltered = filterBoilersByCircuitMode(
    boilersAfterCombustion,
    circuitFilterModeEffective,
  );
  if (
    circuitFilterModeEffective === 'single' &&
    scheme === SCHEME_BOILER_ELECTRIC_SEPARATE &&
    !circuitFallback &&
    countBeforeCircuit > 0 &&
    boilersFiltered.length === 0
  ) {
    boilersFiltered = boilersAfterCombustion;
    warnings.push(
      'Для схеми з електробойлером рекомендується одноконтурний котел, але в каталозі під потрібну потужність (з урахуванням фільтра камери) знайдено лише двоконтурні моделі. Підібрано двоконтурну модель як вимушений технологічний резерв.',
    );
  } else if (
    circuitFilterModeEffective &&
    countBeforeCircuit > 0 &&
    boilersFiltered.length === 0
  ) {
    warnings.push(
      circuitFilterModeEffective === 'double'
        ? 'У каталозі немає двоконтурних котлів за фільтром — підбір за обраною схемою неможливий.'
        : 'У каталозі немає одноконтурних котлів за фільтром — підбір за схемою «1К + БКН» неможливий.',
    );
  }

  /** Для max-combi — пик проточки; для 1К + накопитель — мощность бака (к котлу не суммируется). */
  const hwKwForBoilerFormula =
    effectiveScheme === SCHEME_BOILER_MAX_COMBI ||
    effectiveScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC
      ? peakHwKw > 0
        ? peakHwKw
        : hwKw
      : hwKw;
  /** В карточках proposal — 0 для «1К + электро», иначе значение для формулы котла. */
  const hwKwForBreakdown =
    effectiveScheme === SCHEME_BOILER_ELECTRIC_SEPARATE ||
    effectiveScheme === SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC
      ? 0
      : hwKwForBoilerFormula;

  const selectedSingle =
    boilersFiltered.find((b) => (b?.powerKw?.max ?? 0) >= requiredKw) ?? null;

  /** @type {import('../types/boiler-types.js').BoilerMatchingRecommendation[]} */
  const recommendations = [];

  if (effectiveScheme === SCHEME_BOILER_MAX_COMBI) {
    const storageClause =
      dhwSupplyScenario === 'storage'
        ? ' Для будинку з накопичувачем потужність гарячої води в розрахунку береться від нагрівання бака за заданий час (не від піку проливу).'
        : '';
    recommendations.push({
      type: 'combination_boiler_hot_water_priority_maximum_formula',
      message:
        'Двоконтурний котел з пріоритетом гарячої води: розрахункова потрібна потужність — максимум з опалювального навантаження з запасом і розрахункової потужності на гарячу воду (без сумування).' +
        storageClause,
    });
  } else if (effectiveScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC) {
    recommendations.push({
      type: 'combination_boiler_buffer_electric_storage_maximum_formula',
      message:
        'Двоконтурний котел із буферним електробойлером: котел гріє проток ГВП — потрібна потужність max(опалення з запасом, пік ГВП); електробойлер — температурний буфер меншого об’єму для згладжування «холодного плевка» та піків.',
    });
  } else if (effectiveScheme === SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC) {
    recommendations.push({
      type: 'single_circuit_boiler_buffer_electric_storage_heating_only',
      message:
        'Одноконтурний котел із буферним електробойлером: котел підбирається лише за опаленням з запасом; гаряча вода — накопичувальний електробойлер за нормою singleCircuitBufferElectricStorage.',
    });
  } else if (effectiveScheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM) {
    recommendations.push({
      type: 'single_circuit_boiler_indirect_tank_sum_formula',
      message:
        'Одноконтурний котел із бойлером непрямого нагріву: розрахункова потрібна потужність котла — сума опалювального навантаження з запасом і потужності нагрівання бака за цільовий час (не максимум і не пік проточки).',
    });
  } else {
    recommendations.push({
      type: 'single_circuit_boiler_electric_storage_water_heater_heating_load_only',
      message:
        'Схема з окремим накопичувальним електричним водонагрівачем: котел підбирається лише за опалювальним навантаженням з запасом; розрахункова потужність на гарячу воду до котла не додається.',
    });
  }

  recommendations.push(
    ...buildHotWaterScenarioRecommendations(
      hotWaterFixtures,
      hwKw,
      heatLossKw,
      reserveFactor,
      effectiveScheme,
      dhwSupplyScenario,
      boilerRules,
    ),
  );

  if (
    isApartmentCombiSerialBufferEligible({
      objectType: resolvedObjectType,
      requestedScheme: scheme,
      circuitFallback,
      dhwSupplyScenario,
      fixtures: hotWaterFixtures,
      peakThermalPowerKw: peakHwKw > 0 ? peakHwKw : hwKw,
      serialBufferConfig: boilerRules.hints.apartmentCombiSerialBuffer,
    })
  ) {
    const serialRec = buildApartmentCombiSerialBufferRecommendation(
      boilerRules.hints.apartmentCombiSerialBuffer,
      recommendationsBundle,
    );
    if (serialRec) {
      recommendations.push(serialRec);
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendationsBundle,
        'REC_APT_COMBI_SERIAL_BUFFER',
        apartmentCombiSerialBufferTemplateVars(
          boilerRules.hints.apartmentCombiSerialBuffer,
        ),
      );
    }
  }

  /** @type {import('../catalog/types.js').BoilerCatalogItemNormalized | null} */
  let selected = selectedSingle;

  /** @type {import('../types/boiler-types.js').BoilerEquipmentProposal | null} */
  let proposal = null;

  if (!boilersFiltered.length) {
    warnings.push(
      boilersAll.length
        ? 'У каталозі є котли, але жоден не має додатної powerKw.max — перевірте дані.'
        : 'Каталог котлів порожній.',
    );
  } else if (requiredKw <= 0) {
    const fallback = boilersFiltered[0];
    if (!fallback) {
      selected = null;
      proposal = null;
    } else {
      selected = fallback;
      proposal = buildProposalObject(
        fallback,
        'single',
        1,
        fallback.powerKw.max,
        0,
        {
          condensingDrainNote: isCondensingBoiler(fallback),
          heatingLoadKwForReserve: heatingLoadKw,
          powerRequirementBreakdown: buildPowerRequirementBreakdown(
            heatingLoadKw,
            hwKwForBreakdown,
          ),
          boilerRules,
        },
      );
    }
  } else if (selectedSingle) {
    proposal = buildProposalObject(
      selectedSingle,
      'single',
      1,
      selectedSingle.powerKw.max,
      requiredKw,
      {
        condensingDrainNote: isCondensingBoiler(selectedSingle),
        heatingLoadKwForReserve: heatingLoadKw,
        powerRequirementBreakdown: buildPowerRequirementBreakdown(
          heatingLoadKw,
          hwKwForBreakdown,
        ),
        boilerRules,
      },
    );
  } else if (forceSingleBoiler) {
    const strongest = pickStrongestBoilerFromPool(boilersFiltered);
    if (strongest) {
      selected = strongest;
      const maxPw = Number(strongest.powerKw?.max ?? 0);
      proposal = buildProposalObject(
        strongest,
        'single',
        1,
        maxPw,
        requiredKw,
        {
          condensingDrainNote: isCondensingBoiler(strongest),
          heatingLoadKwForReserve: heatingLoadKw,
          powerRequirementBreakdown: buildPowerRequirementBreakdown(
            heatingLoadKw,
            hwKwForBreakdown,
          ),
          boilerRules,
        },
      );
      if (maxPw < requiredKw) {
        const pk = Number(maxPw.toFixed(1));
        const rq = Number(requiredKw.toFixed(1));
        if (
          effectiveScheme === SCHEME_BOILER_MAX_COMBI ||
          effectiveScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC
        ) {
          warnings.push(
            `Потужності проточного режиму котла (${pk} кВт) може не вистачити на одночасний жорсткий пік ГВП взимку, рекомендується обмежити витрата.`,
          );
        } else {
          boilerUnderpoweredFromCatalog = true;
          pushRecommendation(
            warnings,
            resolvedRecommendations,
            recommendationsBundle,
            'WARN_BOILER_UNDERPOWERED',
            {
              boilerMaxKw: pk,
              requiredKw: rq,
            },
          );
        }
      }
    }
  } else {
    const cascade = pickBestCascade(boilersFiltered, requiredKw);
    if (cascade) {
      selected = cascade.boiler;
      proposal = buildProposalObject(
        cascade.boiler,
        'cascade',
        cascade.count,
        cascade.totalNominalKw,
        requiredKw,
        {
          condensingDrainNote: isCondensingBoiler(cascade.boiler),
          powerRequirementBreakdown: buildPowerRequirementBreakdown(
            heatingLoadKw,
            hwKwForBreakdown,
          ),
          boilerRules,
        },
      );
    } else {
      logger.warn('matching.boiler.cascade_unexpected', null, {
        requiredKw,
        boilersWithMax: boilersFiltered.length,
      });
      warnings.push(
        'Не вдалося сформувати каскад за каталогом — перевірте поля powerKw у котлів.',
      );
    }
  }

  const economyPool = filterBoilersForEconomyLine(boilersFiltered);
  const efficientCandidates = filterBoilersForEfficientLine(
    boilersAfterCombustion,
  );
  const combiBufferScheme =
    scheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC ||
    effectiveScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC;
  const maxCombiEffective =
    effectiveScheme === SCHEME_BOILER_MAX_COMBI ||
    circuitFallback?.effectiveScheme === SCHEME_BOILER_MAX_COMBI;
  /** 2К + буфер / вынужденный max-combi после fallback — пул 2К; иначе 1К для «1К + БКН» / «1К + электро». */
  const efficientCircuitMode =
    combiBufferScheme || maxCombiEffective ? 'double' : 'single';
  const efficientPool = filterBoilersByCircuitMode(
    efficientCandidates,
    efficientCircuitMode,
  );

  if (efficientCandidates.length > 0) {
    recommendations.push(
      ...buildCondensingBoilerMatchingRecommendations(
        reserveFactor,
        boilerRules,
      ),
    );
  }

  /** @type {import('../types/boiler-types.js').BoilerEquipmentProposal | null} */
  let proposalEconomy = null;
  /** @type {import('../types/boiler-types.js').BoilerEquipmentProposal | null} */
  let proposalEfficient = null;

  /** Мощность для подсказки каскада по альтернативе «Эффективный» (та же база, что и proposalEfficient.requiredKw при успешном подборе). */
  let reqEfficientLine = 0;

  if (requiredKw > 0) {
    // Та же расчётная потребность, что у основной линии — чтобы totalNominalKw и requiredKw
    // в карточке «Эконом» сравнимы с proposal/proposalEfficient (не только отопление×запас).
    proposalEconomy = pickSingleOrCascadeProposal(
      economyPool,
      requiredKw,
      'economy',
      'традиційний / бюджетний',
      {
        forceSingleUnit: forceSingleBoiler,
        heatingLoadKwForReserve: heatingLoadKw,
        powerRequirementBreakdown: buildPowerRequirementBreakdown(
          heatingLoadKw,
          hwKwForBreakdown,
        ),
        boilerRules,
      },
    );

    // Схема с отдельным электробойлером: котёл только под отопление×запас (как proposal/requiredKw),
    // без суммы с ГВС и без порога minSourcePowerKw БКН — иначе ложно раздувает конденсационную ветку.
    const electricSeparate =
      effectiveScheme === SCHEME_BOILER_ELECTRIC_SEPARATE;
    const efficientHeatingBaseKw = electricSeparate
      ? heatingLoadKw
      : heatingLoadKwCondensing;

    let reqEfficient;
    if (electricSeparate) {
      reqEfficient = requiredKwFromHeatingAndDhw(
        SCHEME_BOILER_ELECTRIC_SEPARATE,
        heatingLoadKw,
        hwKw,
      );
    } else if (
      maxCombiEffective ||
      effectiveScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC
    ) {
      reqEfficient = requiredKwFromHeatingAndDhw(
        SCHEME_BOILER_MAX_COMBI,
        heatingLoadKwCondensing,
        hwKwForBoilerFormula,
      );
    } else {
      reqEfficient = requiredKwFromHeatingAndDhw(
        SCHEME_BOILER_SINGLE_INDIRECT_SUM,
        heatingLoadKwCondensing,
        hwKw,
      );
      if (minSourceKwBkn != null && minSourceKwBkn > reqEfficient) {
        reqEfficient = minSourceKwBkn;
      }
    }
    reqEfficientLine = reqEfficient;

    proposalEfficient = pickSingleOrCascadeProposal(
      efficientPool,
      reqEfficient,
      'efficient',
      efficientProposalHeadlineSuffix(
        electricSeparate,
        resolvedObjectType,
        scheme,
      ),
      {
        forceSingleUnit: forceSingleBoiler,
        heatingLoadKwForReserve: efficientHeatingBaseKw,
        powerRequirementBreakdown: buildPowerRequirementBreakdown(
          efficientHeatingBaseKw,
          hwKwForBreakdown,
        ),
        boilerRules,
      },
    );
  }

  if (!proposalEconomy && economyPool.length === 0 && requiredKw > 0) {
    warnings.push(
      'У каталозі немає традиційних (не конденсаційних) котлів для лінії «Економ».',
    );
  }
  if (!proposalEfficient && requiredKw > 0) {
    if (!efficientCandidates.length) {
      warnings.push(
        'У каталозі немає конденсаційних котлів для лінії «Ефективний».',
      );
    } else if (!efficientPool.length) {
      warnings.push(
        scheme === SCHEME_BOILER_ELECTRIC_SEPARATE
          ? 'Для лінії «Ефективний» потрібні одноконтурні конденсаційні котли — після фільтра камери їх у каталозі не знайдено.'
          : combiBufferScheme
            ? 'Для лінії «Ефективний» (2К + буферний ЕВН) потрібні двоконтурні конденсаційні котли — після фільтра камери їх у каталозі не знайдено.'
            : 'Для альтернативи «1К + БКН» потрібні одноконтурні конденсаційні котли — після фільтра камери їх у каталозі не знайдено.',
      );
    }
  }

  const tradCascade = buildTraditionalCascadeHint(requiredKw, boilerRules);
  if (
    proposal &&
    proposal.kind === 'single' &&
    tradCascade &&
    !forceSingleBoiler
  ) {
    recommendations.push(tradCascade);
  }

  if (selected && requiredKw > 0 && !boilerUnderpoweredFromCatalog) {
    const selMax = Number(selected.powerKw?.max ?? 0);
    const covers =
      proposal?.kind === 'cascade'
        ? Number(proposal.totalNominalKw ?? 0) >= requiredKw
        : selMax >= requiredKw;
    if (covers) {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendationsBundle,
        'REC_BOILER_OPTIMAL',
      );
    }
  }

  if (proposalEfficient?.kind === 'single' && !forceSingleBoiler) {
    const condHint =
      reqEfficientLine > 0
        ? buildCondensingCascadeHint(reqEfficientLine, boilerRules)
        : buildCondensingCascadeHint(requiredKwCondensing, boilerRules);
    if (condHint) recommendations.push(condHint);
  }

  if (proposal) {
    logger.info('matching.boiler.proposal', null, {
      kind: proposal.kind,
      model: proposal.model,
      unitsCount: proposal.unitsCount,
      totalNominalKw: proposal.totalNominalKw,
    });
  }
  if (proposalEfficient && selectedWaterHeater?.type === 'indirect_floor') {
    proposalEfficient.notes.push(
      'Для обраного напольного БКН потрібен додатковий напольний простір біля котла.',
    );
  }
  if (
    proposalEfficient &&
    resolvedObjectType === 'apartment' &&
    scheme === SCHEME_BOILER_MAX_COMBI
  ) {
    proposalEfficient.notes.push(
      'Лінія «Ефективний» — конденсаційний котел за опаленням; для max-combi в квартирі БКН у цю зв’язку не входить.',
    );
  }

  if (heatingSystem?.heatingEmittersMode === 'ufh_only') {
    const hs = heatingSystem;
    const boilerModel =
      typeof selected?.model === 'string' ? selected.model : 'котел';
    const highTempGraph = isHighTemperatureHeatingGraph(hs);
    const nonCondensing = Boolean(selected && !isCondensingBoiler(selected));

    if (highTempGraph || nonCondensing) {
      const thermalRegimeLabel =
        typeof hs.supplyC === 'number' && typeof hs.returnC === 'number'
          ? `${hs.supplyC}/${hs.returnC} °C`
          : hs.thermalRegimePreset === 'traditional_dt50_75_65'
            ? 'традиційний 75/65'
            : hs.thermalRegimePreset === 'condensing_dt30_55_45'
              ? '55/45'
              : 'не задано';
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendationsBundle,
        'WARN_UFH_ONLY_TRADITIONAL_BOILER',
        {
          supplyC: hs.supplyC,
          returnC: hs.returnC,
          thermalRegimeLabel,
          boilerModel,
        },
      );
    }
  }

  return {
    heatLossKw: Number(heatLossKw.toFixed(2)),
    reserveFactor,
    hotWaterPowerKw: Number(hwKw.toFixed(1)),
    heatingLoadKw: Number(heatingLoadKw.toFixed(2)),
    hotWaterBoilerPowerMatchingScheme: scheme,
    ...(effectiveScheme !== scheme
      ? { effectiveHotWaterBoilerPowerMatchingScheme: effectiveScheme }
      : {}),
    ...(circuitFallback ? { circuitFallback } : {}),
    requiredKw: Number(requiredKw.toFixed(2)),
    condensingHeatingReserveFactor:
      boilerRules.matching.condensingHeatingReserveFactor,
    heatingLoadKwCondensing: Number(heatingLoadKwCondensing.toFixed(2)),
    requiredKwForCondensingLine: Number(requiredKwCondensing.toFixed(2)),
    selected,
    warnings,
    resolvedRecommendations,
    recommendations,
    proposal,
    proposalEconomy,
    proposalEfficient,
    combustionTypeFilterApplied,
  };
}

/**
 * Назначение: обогащение карточек вариантов котла.
 * Описание: расчёт суммарной цены и состава комплекта (котёл + электробойлер и/или БКН) по схеме
 * ГВС и линии подбора — основная, эконом или эффективный.
 */
import {
  SCHEME_BOILER_COMBI_BUFFER_ELECTRIC,
  SCHEME_BOILER_ELECTRIC_SEPARATE,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
} from '../../../shared/heatingMatchingSchemes.js';

/**
 * @param {import('../types/shared-types.js').WaterHeaterMatchingReport | undefined} waterHeater
 * @returns {import('../types/boiler-types.js').EquipmentBundleCompanion | null}
 */
function buildWaterHeaterCompanion(waterHeater) {
  const selected = waterHeater?.selected;
  if (!selected?.model) return null;
  const variant = waterHeater?.chosenVariant;
  const price =
    typeof variant?.price === 'number' && Number.isFinite(variant.price)
      ? variant.price
      : undefined;
  const volumeLiters =
    typeof variant?.volumeLiters === 'number' &&
    Number.isFinite(variant.volumeLiters)
      ? variant.volumeLiters
      : undefined;
  return {
    role: 'water_heater',
    model: selected.model,
    ...(typeof selected.brand === 'string' && selected.brand.trim()
      ? { brand: selected.brand.trim() }
      : {}),
    ...(volumeLiters != null ? { volumeLiters } : {}),
    ...(price != null ? { price } : {}),
  };
}

/**
 * @param {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport | undefined} indirectWaterHeater
 * @returns {import('../types/boiler-types.js').EquipmentBundleCompanion | null}
 */
function buildIndirectWaterHeaterCompanion(indirectWaterHeater) {
  const selected = indirectWaterHeater?.selected;
  if (!selected?.model) return null;
  const price =
    typeof selected.price === 'number' && Number.isFinite(selected.price)
      ? selected.price
      : undefined;
  const volumeLiters =
    typeof selected.specs?.volumeLiters === 'number' &&
    Number.isFinite(selected.specs.volumeLiters)
      ? selected.specs.volumeLiters
      : undefined;
  return {
    role: 'indirect_water_heater',
    model: selected.model,
    ...(typeof selected.brand === 'string' && selected.brand.trim()
      ? { brand: selected.brand.trim() }
      : {}),
    ...(volumeLiters != null ? { volumeLiters } : {}),
    ...(price != null ? { price } : {}),
  };
}

/**
 * Какие companions показывать в карточке варианта.
 *
 * @param {object} ctx
 * @param {'proposal' | 'economy' | 'efficient'} ctx.tier
 * @param {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} ctx.scheme
 * @param {'apartment' | 'house'} ctx.objectType
 * @param {import('../types/boiler-types.js').BoilerCircuitFallbackReport | null | undefined} ctx.circuitFallback
 * @param {boolean} ctx.hasWaterHeater
 * @param {boolean} ctx.hasIndirect
 * @returns {{ includeWaterHeater: boolean; includeIndirect: boolean }}
 */
function resolveCompanionFlags({
  tier,
  scheme,
  objectType,
  circuitFallback,
  hasWaterHeater,
  hasIndirect,
}) {
  const activeScheme = circuitFallback?.effectiveScheme ?? scheme;

  if (activeScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC) {
    return { includeWaterHeater: hasWaterHeater, includeIndirect: false };
  }

  if (activeScheme === SCHEME_BOILER_ELECTRIC_SEPARATE) {
    return { includeWaterHeater: hasWaterHeater, includeIndirect: false };
  }

  if (activeScheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM) {
    return { includeWaterHeater: false, includeIndirect: hasIndirect };
  }

  if (activeScheme === SCHEME_BOILER_MAX_COMBI) {
    if (
      tier === 'efficient' &&
      objectType === 'house' &&
      hasIndirect
    ) {
      return { includeWaterHeater: false, includeIndirect: true };
    }
    return { includeWaterHeater: false, includeIndirect: false };
  }

  return { includeWaterHeater: false, includeIndirect: false };
}

/**
 * @param {import('../types/boiler-types.js').BoilerEquipmentProposal | null | undefined} proposal
 * @param {import('../types/shared-types.js').WaterHeaterMatchingReport | undefined} waterHeater
 * @param {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport | undefined} indirectWaterHeater
 * @param {object} ctx
 * @param {'proposal' | 'economy' | 'efficient'} ctx.tier
 * @param {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} ctx.scheme
 * @param {'apartment' | 'house'} ctx.objectType
 * @param {import('../types/boiler-types.js').BoilerCircuitFallbackReport | null | undefined} [ctx.circuitFallback]
 */
function enrichProposalWithBundlePrice(
  proposal,
  waterHeater,
  indirectWaterHeater,
  ctx,
) {
  if (!proposal || !ctx) return;

  const whCompanion = buildWaterHeaterCompanion(waterHeater);
  const bknCompanion = buildIndirectWaterHeaterCompanion(indirectWaterHeater);
  const flags = resolveCompanionFlags({
    tier: ctx.tier,
    scheme: ctx.scheme,
    objectType: ctx.objectType,
    circuitFallback: ctx.circuitFallback,
    hasWaterHeater: whCompanion != null,
    hasIndirect: bknCompanion != null,
  });

  /** @type {import('../types/boiler-types.js').EquipmentBundleCompanion[]} */
  const companions = [];
  if (flags.includeWaterHeater && whCompanion) companions.push(whCompanion);
  if (flags.includeIndirect && bknCompanion) companions.push(bknCompanion);
  if (companions.length) {
    proposal.equipmentBundleCompanions = companions;
  }

  /** @type {import('../types/boiler-types.js').EquipmentBundlePriceBreakdown} */
  const breakdown = {};
  let total = 0;
  let hasAny = false;

  if (
    proposal.estimatedTotalPrice != null &&
    Number.isFinite(proposal.estimatedTotalPrice)
  ) {
    breakdown.boilerPrice = proposal.estimatedTotalPrice;
    total += proposal.estimatedTotalPrice;
    hasAny = true;
  }

  const whPrice =
    flags.includeWaterHeater && whCompanion?.price != null
      ? whCompanion.price
      : null;
  if (whPrice != null) {
    breakdown.waterHeaterPrice = whPrice;
    total += whPrice;
    hasAny = true;
  }

  const bknPrice =
    flags.includeIndirect && bknCompanion?.price != null
      ? bknCompanion.price
      : null;
  if (bknPrice != null) {
    breakdown.indirectWaterHeaterPrice = bknPrice;
    total += bknPrice;
    hasAny = true;
  }

  if (!hasAny) return;

  const hasCompanion =
    breakdown.waterHeaterPrice != null ||
    breakdown.indirectWaterHeaterPrice != null;

  if (!hasCompanion) return;

  proposal.equipmentBundleTotalPrice = Number(total.toFixed(2));
  proposal.equipmentBundlePriceBreakdown = breakdown;
}

/**
 * @param {import('../types/boiler-types.js').BoilerMatchingReport | null | undefined} boiler
 * @param {import('../types/shared-types.js').WaterHeaterMatchingReport | undefined} waterHeater
 * @param {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport | undefined} indirectWaterHeater
 * @param {object} ctx
 * @param {import('../types/boiler-types.js').HotWaterBoilerPowerMatchingScheme} ctx.scheme
 * @param {'apartment' | 'house'} ctx.objectType
 */
export function enrichBoilerMatchingProposals(
  boiler,
  waterHeater,
  indirectWaterHeater,
  ctx,
) {
  if (!boiler || !ctx) return;
  const base = {
    scheme: ctx.scheme,
    objectType: ctx.objectType,
    circuitFallback: boiler.circuitFallback ?? null,
  };
  enrichProposalWithBundlePrice(boiler.proposal, waterHeater, indirectWaterHeater, {
    ...base,
    tier: 'proposal',
  });
  enrichProposalWithBundlePrice(
    boiler.proposalEconomy,
    waterHeater,
    indirectWaterHeater,
    { ...base, tier: 'economy' },
  );
  enrichProposalWithBundlePrice(
    boiler.proposalEfficient,
    waterHeater,
    indirectWaterHeater,
    { ...base, tier: 'efficient' },
  );
}

/**
 * Назначение: оркестрация подбора оборудования.
 * Описание: единая точка входа matchEquipment — последовательный подбор БКН, котла, радиаторов
 * и водонагревателя с учётом схемы ГВС и обогащением proposal-линий.
 */
import { pickBoiler } from './boiler.js';
import { pickRadiatorsWithProposalLines } from './radiators.js';
import { pickWaterHeater } from './waterHeater.js';
import {
  applyIndirectTankToHotWaterReport,
  attachIndirectBoilerCoupling,
  pickIndirectWaterHeater,
} from './indirectWaterHeater.js';
import { appendIndirectPriorityRoomWarnings } from './indirectPriorityRoomHint.js';
import {
  SCHEME_BOILER_COMBI_BUFFER_ELECTRIC,
  SCHEME_BOILER_ELECTRIC_SEPARATE,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
} from '../../../shared/heatingMatchingSchemes.js';
import { resolveBoilerCircuitFilterMode } from '../utils/boilerMatchingByType.js';
import { enrichBoilerMatchingProposals } from './enrichProposalBundlePrice.js';
import { alignHeatingGraphForCondensingBoiler } from '../logic/heatingThermalRegimes.js';
import { assertCalcRuntimeContext } from '../reference/assertCalcRuntimeContext.js';
import { logger } from '../utils/logger.js';

/**
 * База отопления для pickBoiler: при ufh_only - отдача ТП вверх, иначе теплопотери ограждения.
 *
 * @param {import('../types/shared-types.js').HeatingSystemInput | undefined} heatingSystem
 * @param {import('../types/shared-types.js').HeatLossReport | undefined} heatLoss
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} underfloorHeating
 * @returns {{ boilerHeatingLoadWatts: number, envelopeHeatLossWatts: number, usedUfhHeatFlux: boolean }}
 */
function resolveBoilerHeatingLoadWatts(heatingSystem, heatLoss, underfloorHeating) {
  const envelopeHeatLossWatts = heatLoss?.totalWatts ?? 0;
  const emittersMode = heatingSystem?.heatingEmittersMode;

  if (emittersMode !== 'ufh_only') {
    return {
      boilerHeatingLoadWatts: envelopeHeatLossWatts,
      envelopeHeatLossWatts,
      usedUfhHeatFlux: false,
    };
  }

  const ufhWatts = underfloorHeating?.totalHeatFluxUpWatts ?? 0;
  if (ufhWatts > 0) {
    return {
      boilerHeatingLoadWatts: ufhWatts,
      envelopeHeatLossWatts,
      usedUfhHeatFlux: true,
    };
  }

  return {
    boilerHeatingLoadWatts: envelopeHeatLossWatts,
    envelopeHeatLossWatts,
    usedUfhHeatFlux: false,
  };
}

/**
 * Єдина точка входу для підбору обладнання.
 * Приймає результати розрахунків та каталог і повертає підібрані позиції.
 *
 * Для дома с БКН: спочатку підбір БКН з каталогу,
 * потім уточнення потужності ГВС по фактичному об'єму бака і підбір котла
 * (схема max або сумма мощностей для «1К + БКН»).
 *
 * @param {object} args
 * @param {import('../types/shared-types.js').HeatLossReport} args.heatLoss
 * @param {import('../types/shared-types.js').HotWaterReport} args.hotWater
 * @param {import('../types/shared-types.js').HeatingSystemInput} args.heatingSystem
 * @param {import('../types/shared-types.js').BuildingInput | undefined} args.building
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null} [args.underfloorHeating]
 * @param {import('../types/shared-types.js').HydraulicsSurveyInput | undefined} [args.hydraulics]
 * @param {import('../types/shared-types.js').CalcRuntimeContext} args.ctx
 * @returns {{
 *   matching: import('../types/shared-types.js').MatchingReport,
 *   hotWaterForCalculations: import('../types/shared-types.js').HotWaterReport,
 * }}
 */
export function matchEquipment({
  heatLoss,
  hotWater,
  heatingSystem,
  building,
  underfloorHeating = null,
  hydraulics,
  ctx,
}) {
  assertCalcRuntimeContext(ctx);
  const { catalog, waterNorms, appliances, recommendations } = ctx;
  const heatingLoad = resolveBoilerHeatingLoadWatts(
    heatingSystem,
    heatLoss,
    underfloorHeating,
  );

  logger.debug('matching.start', null, {
    heatLossWatts: heatLoss?.totalWatts ?? null,
    boilerHeatingLoadWatts: heatingLoad.boilerHeatingLoadWatts,
    usedUfhHeatFlux: heatingLoad.usedUfhHeatFlux,
  });

  const scheme =
    heatingSystem?.hotWaterBoilerPowerMatchingScheme ?? SCHEME_BOILER_MAX_COMBI;

  const objectMetaType = building?.objectMeta?.objectType;
  const objectType =
    objectMetaType === 'apartment' || objectMetaType === 'house'
      ? objectMetaType
      : 'house';

  const useIndirectDhw =
    scheme !== SCHEME_BOILER_COMBI_BUFFER_ELECTRIC &&
    hotWater?.dhwSupplyScenario === 'storage' &&
    (objectType === 'house' ||
      (objectType === 'apartment' &&
        scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM &&
        building?.objectMeta?.indirectDhwSpaceAvailable === true)) &&
    (scheme === SCHEME_BOILER_MAX_COMBI ||
      scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM);

  /** @type {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport} */
  let indirectWaterHeater = pickIndirectWaterHeater({
    hotWater,
    catalog,
    useIndirectDhw,
    objectType,
  });

  /** @type {import('../types/shared-types.js').HotWaterReport | undefined} */
  let hotWaterResolved = hotWater;
  if (hotWaterResolved && indirectWaterHeater.selected) {
    hotWaterResolved = applyIndirectTankToHotWaterReport(
      hotWaterResolved,
      indirectWaterHeater.selected,
      waterNorms,
    );
  }

  const hwForBoiler = hotWaterResolved ?? hotWater;

  const boilerCircuitFilterMode = resolveBoilerCircuitFilterMode({
    scheme,
    dhwSupplyScenario: hwForBoiler?.dhwSupplyScenario,
  });

  const boiler = pickBoiler({
    heatLossWatts: heatingLoad.boilerHeatingLoadWatts,
    hotWaterPowerKw: hwForBoiler?.hotWaterPowerKw ?? 0,
    peakThermalPowerKw: hwForBoiler?.peakThermalPowerKw ?? 0,
    boilerCombustionType: heatingSystem?.boilerCombustionType,
    hotWaterFixtures: hwForBoiler?.fixtures,
    hotWaterBoilerPowerMatchingScheme: scheme,
    dhwSupplyScenario: hwForBoiler?.dhwSupplyScenario,
    boilerCircuitFilterMode,
    selectedWaterHeater: indirectWaterHeater?.selected ?? null,
    objectType,
    building,
    heatingSystem,
    ctx,
  });

  const normWarn =
    heatingSystem && typeof heatingSystem === 'object'
      ? /** @type {Record<string, unknown>} */ (heatingSystem)
          ._normalizationWarnings
      : undefined;
  if (Array.isArray(normWarn) && normWarn.length) {
    boiler.warnings.push(.../** @type {string[]} */ (normWarn));
    const hsForNorm = /** @type {Record<string, unknown>} */ (heatingSystem);
    delete hsForNorm._normalizationWarnings;
  }

  if (heatingSystem?.heatingEmittersMode === 'ufh_only') {
    if (heatingLoad.usedUfhHeatFlux) {
      const ufhRounded = Math.round(heatingLoad.boilerHeatingLoadWatts);
      const envelopeRounded = Math.round(heatingLoad.envelopeHeatLossWatts);
      if (heatingLoad.boilerHeatingLoadWatts < heatingLoad.envelopeHeatLossWatts) {
        boiler.warnings.push(
          `Режим «лише тепла підлога»: для підбору котла використано віддачу ТП ${ufhRounded} Вт при тепловтратах огородження ${envelopeRounded} Вт — можливий дефіцит покриття.`,
        );
      } else if (heatingLoad.boilerHeatingLoadWatts !== heatingLoad.envelopeHeatLossWatts) {
        boiler.warnings.push(
          `Режим «лише тепла підлога»: потужність котла за віддачею ТП (${ufhRounded} Вт), не за тепловтратами огородження (${envelopeRounded} Вт).`,
        );
      }
    } else {
      boiler.warnings.push(
        'Режим «лише тепла підлога»: віддача ТП не розрахована — підбір котла виконано за тепловтратами огородження.',
      );
    }
  }

  attachIndirectBoilerCoupling(
    indirectWaterHeater,
    boiler,
    hwForBoiler,
    ctx,
  );
  appendIndirectPriorityRoomWarnings(indirectWaterHeater, heatLoss);

  if (
    useIndirectDhw &&
    indirectWaterHeater.selected &&
    scheme === SCHEME_BOILER_MAX_COMBI &&
    boiler.selected?.isDoubleCircuit === true
  ) {
    boiler.warnings.unshift(
      'Двоконтурний котел із бойлером непрямого нагріву допускається, але гідравлічно часто складніше (пріоритет ГВП, узгодження контурів). Для типової зв’язки «1К + БКН» оберіть окрему схему сумування потужностей.',
    );
  }

  const graphAlignWarning = alignHeatingGraphForCondensingBoiler(
    heatingSystem,
    boiler.selected ?? null,
  );
  if (graphAlignWarning) {
    boiler.warnings.unshift(graphAlignWarning);
    logger.info('matching.boiler.graphAligned', null, {
      thermalRegimePreset: heatingSystem?.thermalRegimePreset ?? null,
      supplyC: heatingSystem?.supplyC ?? null,
      returnC: heatingSystem?.returnC ?? null,
    });
  }

  const radiators = pickRadiatorsWithProposalLines({
    roomsHeatLoss: heatLoss,
    heatingSystem,
    catalog,
    building,
    boiler,
    underfloorHeating,
    hydraulics,
    radiatorRules: appliances.byKind.radiator,
    recommendations,
  });

  /** @type {import('../types/shared-types.js').WaterHeaterMatchingReport} */
  let waterHeater = {
    selected: null,
    chosenVariant: null,
    warnings: [],
    requiredTankLiters: 0,
  };

  const boilerCircuitFallback = boiler.circuitFallback ?? null;

  if (scheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC) {
    waterHeater = pickWaterHeater({ hotWater: hwForBoiler, catalog });
    if ((waterHeater.requiredTankLiters ?? 0) > 0) {
      waterHeater.warnings.unshift(
        `Електробойлер підібрано як температурний буфер об’ємом ${waterHeater.requiredTankLiters} л для згладжування температурних стрибків ГВП двоконтурного котла.`,
      );
    }
  } else if (scheme === SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC) {
    waterHeater = pickWaterHeater({ hotWater: hwForBoiler, catalog });
    if ((waterHeater.requiredTankLiters ?? 0) > 0) {
      waterHeater.warnings.unshift(
        `Електробойлер підібрано як буфер/накопичувач об’ємом ${waterHeater.requiredTankLiters} л (схема 1К + буферний ЕВН).`,
      );
    }
  } else if (
    scheme === SCHEME_BOILER_ELECTRIC_SEPARATE &&
    boilerCircuitFallback?.reason === 'no_single_in_catalog'
  ) {
    waterHeater = {
      selected: null,
      chosenVariant: null,
      warnings: [],
      requiredTankLiters: 0,
    };
  } else if (scheme === SCHEME_BOILER_ELECTRIC_SEPARATE) {
    waterHeater = pickWaterHeater({ hotWater: hwForBoiler, catalog });
  } else if (useIndirectDhw) {
    if (!indirectWaterHeater.selected) {
      // Fallback: БКН не обрано — запасний ЕВН. При обраному БКН waterHeater лишається
      // порожньою заглушкою (requiredTankLiters: 0): не дзеркалимо recommendedTankLiters,
      // щоб UI не показував фальшивий електробойлер. Обсяг — у indirectWaterHeater.
      waterHeater = pickWaterHeater({ hotWater: hwForBoiler, catalog });
      const noIndirectInCatalog = !catalog?.indirectWaterHeaters?.length;
      const prefix = noIndirectInCatalog
        ? 'У каталозі немає БКН — показано запасний підбір електронакопичувача.'
        : 'БКН за розрахунковим об’ємом не знайдено — показано запасний підбір електронакопичувача.';
      waterHeater.warnings.unshift(prefix);
    }
  }

  enrichBoilerMatchingProposals(boiler, waterHeater, indirectWaterHeater, {
    scheme,
    objectType,
  });

  logger.debug('matching.done', null, {
    boilerModel: boiler?.selected?.model ?? null,
    radiatorModel: radiators?.chosen?.model ?? null,
    indirectModel: indirectWaterHeater?.selected?.model ?? null,
    waterHeaterModel: waterHeater?.selected?.model ?? null,
  });

  return {
    matching: {
      boiler,
      radiators,
      waterHeater,
      indirectWaterHeater,
    },
    hotWaterForCalculations: hotWaterResolved ?? hotWater,
  };
}

/**
 * Назначение: предупреждение по приоритету ГВС.
 * Описание: при длительном нагреве БКН добавляет в отчёт hint о возможном остывании самого
 * нагруженного по ограждениям помещения.
 */

/**
 * @param {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport | undefined} indirectReport
 * @param {import('../types/shared-types.js').HeatLossReport | undefined} heatLoss
 */
export function appendIndirectPriorityRoomWarnings(indirectReport, heatLoss) {
  if (
    !indirectReport
    || indirectReport.heatTimeMinutesFullTank == null
    || !heatLoss?.rooms?.length
  ) {
    return;
  }
  const t = indirectReport.heatTimeMinutesFullTank;
  if (t < 18) return;

  const firstRoom = heatLoss.rooms[0];
  if (!firstRoom) return;

  let worst = firstRoom;
  for (const r of heatLoss.rooms) {
    if ((r.envelopeWatts ?? 0) > (worst.envelopeWatts ?? 0)) worst = r;
  }
  const kw = (worst.envelopeWatts ?? 0) / 1000;
  const label = worst.name ?? worst.id ?? 'приміщення';
  indirectReport.warnings.push(
    `За пріоритету ГВП та тривалого нагрівання бака (~${t} хв) перевірте охолодження найнавантаженішого приміщення за огородженнями («${label}», ~${kw.toFixed(2)} кВт); за потреби збільште потужність котла або змійовик БКН.`,
  );
}

/**
 * Назначение: подбор БКН и связка с котлом.
 * Описание: выбор бойлера косвенного нагрева из каталога, пересчёт блока ГВС по фактическому объёму
 * бака, уточнение requiredKw котла и предупреждения по мощности змеевика и времени нагрева.
 */
import { tankFullHeatTimeMinutes, tankVolumeHeatPowerKw } from '../dhw/waterCalc.js';
import { pushRecommendation } from '../recommendations/recommendationResolver.js';
import { logger } from '../utils/logger.js';
import {
  indirectCoilPowerKw,
  indirectMinSourcePowerKw,
  indirectTankVolumeLiters,
} from './internal/indirectCatalogHelpers.js';

/**
 * Пересчёт блока ГВС после выбора конкретного БКН (объём и мощность для котла).
 *
 * @param {import('../types/shared-types.js').HotWaterReport | undefined} hotWater
 * @param {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized | null} indirectItem
 * @param {import('../dhw/types.js').NormalizedWaterNorms} waterNorms
 * @returns {import('../types/shared-types.js').HotWaterReport | undefined}
 */
export function applyIndirectTankToHotWaterReport(hotWater, indirectItem, waterNorms) {
  if (!hotWater || hotWater.dhwSupplyScenario !== 'storage') return hotWater;
  if (!indirectItem) return hotWater;
  if (!waterNorms) {
    throw new Error('applyIndirectTankToHotWaterReport: waterNorms обязательны.');
  }
  const vol = indirectTankVolumeLiters(indirectItem);
  if (vol <= 0) return hotWater;

  const norms = waterNorms;
  const deltaTK = Number(hotWater.deltaTK) || 0;
  const minutes = hotWater.storageHeatTimeMinutes ?? norms.storage.indirectHeatTimeMinutes;
  const storageIndirectHeatPowerKw = Number(
    tankVolumeHeatPowerKw(norms, vol, deltaTK, minutes).toFixed(2),
  );
  const hotWaterPowerKw = Number(
    Math.max(norms.storage.boilerDhwPowerMinKw, storageIndirectHeatPowerKw).toFixed(2),
  );

  return {
    ...hotWater,
    recommendedTankLiters: Math.round(vol),
    storageIndirectHeatPowerKw,
    hotWaterPowerKw,
  };
}

/**
 * Список БКН с учётом типа объекта: в квартире — только настенные (indirect_wall).
 *
 * @param {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized[]} list
 * @param {'apartment' | 'house'} objectType
 * @returns {{ pool: import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized[]; wallFallbackWarning: string | null }}
 */
function indirectPoolForObjectType(list, objectType) {
  if (objectType !== 'apartment') {
    return { pool: list, wallFallbackWarning: null };
  }
  const wallOnly = list.filter((h) => h.type === 'indirect_wall');
  if (wallOnly.length > 0) {
    return { pool: wallOnly, wallFallbackWarning: null };
  }
  if (list.length > 0) {
    return {
      pool: list,
      wallFallbackWarning:
        'Для квартири переважний настінний БКН (indirect_wall); у каталозі не знайдено — підібрано інший тип, перевірте габарити.',
    };
  }
  return { pool: [], wallFallbackWarning: null };
}

/**
 * @param {object} args
 * @param {import('../types/shared-types.js').HotWaterReport | undefined} args.hotWater
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @param {boolean} args.useIndirectDhw - дом + накопитель + схема двухконтурного котла
 * @param {'apartment' | 'house'} [args.objectType]
 * @returns {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport}
 */
export function pickIndirectWaterHeater({
  hotWater,
  catalog,
  useIndirectDhw,
  objectType = 'house',
}) {
  /** @type {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport} */
  const empty = {
    selected: null,
    requiredTankLiters: Number(hotWater?.recommendedTankLiters) || 0,
    coilPowerKw: null,
    heatTimeMinutesFullTank: null,
    effectiveHeatPowerKw: null,
    warnings: [],
    resolvedRecommendations: [],
    skippedReason: null,
  };

  if (!useIndirectDhw) {
    empty.skippedReason =
      'БКН не підбирається: квартира/проток, окремий електробойлер або схема без котлового контуру ГВП.';
    return empty;
  }

  const list = catalog?.indirectWaterHeaters ?? [];
  if (!Array.isArray(list) || list.length === 0) {
    empty.warnings.push('У каталозі немає бойлерів непрямого нагріву (БКН).');
    empty.skippedReason = 'Порожній каталог БКН.';
    return empty;
  }

  const need = Number(hotWater?.recommendedTankLiters) || 0;
  logger.info('matching.indirectWaterHeater.start', null, {
    requiredTankLiters: need,
    objectType,
  });

  const resolvedType =
    objectType === 'apartment' || objectType === 'house' ? objectType : 'house';
  const { pool, wallFallbackWarning } = indirectPoolForObjectType(
    list,
    resolvedType,
  );

  const sorted = [...pool].sort(
    (a, b) => indirectTankVolumeLiters(a) - indirectTankVolumeLiters(b),
  );

  /** @type {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized | null} */
  let selected =
    need > 0
      ? sorted.find((h) => indirectTankVolumeLiters(h) >= need) ?? null
      : sorted[0] ?? null;

  if (!selected && sorted.length) {
    selected = sorted[sorted.length - 1] ?? null;
  }

  const warnings = [];
  if (wallFallbackWarning) {
    warnings.push(wallFallbackWarning);
  }
  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const resolvedRecommendations = [];
  if (selected && need > 0 && indirectTankVolumeLiters(selected) < need) {
    warnings.push(
      `Підібраний БКН менший за розрахунковий мінімум за об’ємом (${indirectTankVolumeLiters(selected)} л при потребі ≥ ${need} л) — обмеження каталогу.`,
    );
  }

  const coilKw = selected ? indirectCoilPowerKw(selected) : null;

  logger.info('matching.indirectWaterHeater.done', null, {
    model: selected?.model ?? null,
    volumeLiters: selected ? indirectTankVolumeLiters(selected) : null,
    coilPowerKw: coilKw,
  });

  return {
    selected,
    requiredTankLiters: need,
    coilPowerKw: coilKw,
    heatTimeMinutesFullTank: null,
    effectiveHeatPowerKw: null,
    warnings,
    resolvedRecommendations,
    skippedReason: null,
  };
}

/**
 * Дополняет отчёт по БКН: время нагрева, согласование с котлом, подсказки по приоритету ГВС.
 *
 * @param {import('../types/shared-types.js').IndirectWaterHeaterMatchingReport | undefined} indirectReport
 * @param {import('../types/boiler-types.js').BoilerMatchingReport | undefined} boilerReport
 * @param {import('../types/shared-types.js').HotWaterReport | undefined} hotWater
 * @param {import('../types/shared-types.js').CalcRuntimeContext} ctx
 */
export function attachIndirectBoilerCoupling(
  indirectReport,
  boilerReport,
  hotWater,
  ctx,
) {
  if (!indirectReport?.selected || !hotWater || hotWater.dhwSupplyScenario !== 'storage') {
    return;
  }
  const { waterNorms, appliances, recommendations } = ctx;
  if (!waterNorms || !appliances) {
    throw new Error('attachIndirectBoilerCoupling: ctx.waterNorms и ctx.appliances обязательны.');
  }

  const norms = waterNorms;
  const rules = appliances.byKind.indirect_water_heater.coupling;

  const vol = indirectTankVolumeLiters(
    /** @type {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized} */ (
      indirectReport.selected
    ),
  );
  const deltaTK = Number(hotWater.deltaTK) || 0;
  const coilKw = indirectCoilPowerKw(
    /** @type {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized} */ (
      indirectReport.selected
    ),
  );

  const boilerNominalKw =
    boilerReport?.selected?.powerKw?.max != null
      ? Number(boilerReport.selected.powerKw.max)
      : null;

  const minSourceKw = indirectMinSourcePowerKw(
    /** @type {import('../catalog/types.js').IndirectWaterHeaterCatalogItemNormalized} */ (
      indirectReport.selected
    ),
  );
  if (
    minSourceKw != null &&
    boilerNominalKw != null &&
    boilerNominalKw + rules.boilerBelowMinSourceToleranceKw < minSourceKw
  ) {
    indirectReport.warnings.push(
      `За каталогом для обраного БКН рекомендується джерело не нижче ~${minSourceKw.toFixed(1)} кВт; номінал котла (${boilerNominalKw.toFixed(1)} кВт) може бути недостатнім для штатного режиму.`,
    );
  }

  if (
    coilKw != null &&
    boilerNominalKw != null &&
    coilKw < boilerNominalKw - rules.coilWeakerThanBoilerToleranceKw
  ) {
    indirectReport.warnings.push(
      `Потужність змійовика БКН (${coilKw.toFixed(1)} кВт) нижча за номінал котла (${boilerNominalKw.toFixed(1)} кВт): можливі тактування пальника та збільшений час нагрівання.`,
    );
  }

  let effectiveP =
    coilKw != null && boilerNominalKw != null
      ? Math.min(coilKw, boilerNominalKw)
      : coilKw ?? boilerNominalKw ?? null;

  if (effectiveP == null || effectiveP <= 0) return;

  indirectReport.effectiveHeatPowerKw = Number(effectiveP.toFixed(2));
  const tMin = tankFullHeatTimeMinutes(norms, vol, deltaTK, effectiveP);
  indirectReport.heatTimeMinutesFullTank = tMin;

  if (tMin != null) {
    if (tMin >= rules.heatTimeParasiticHintMinutes) {
      if (!indirectReport.resolvedRecommendations) {
        indirectReport.resolvedRecommendations = [];
      }
      pushRecommendation(
        indirectReport.warnings,
        indirectReport.resolvedRecommendations,
        recommendations,
        'WARN_DHW_TIME_LONG',
        {
          heatTimeMinutes: Math.round(tMin),
          thresholdMinutes: rules.heatTimeParasiticHintMinutes,
        },
      );
    } else if (tMin >= rules.heatTimeSoftHintMinutes) {
      indirectReport.warnings.push(
        `Орієнтовний час повного нагрівання бака ~${tMin} хв — орієнтир для комфорту за пріоритету ГВП (не норматив).`,
      );
    }
  }
}

/**
 * Назначение: глобальное решение типа излучателя на объект.
 * Описание: preference lock или majority по голосам Pass 1; ничья → sectional.
 */

/**
 * @typedef {'sectional' | 'panel'} EmitterKind
 */

/**
 * @typedef {object} EmitterKindVote
 * @property {string} roomId
 * @property {string} [roomName]
 * @property {EmitterKind} preferredKind
 * @property {string} reason
 */

/**
 * @typedef {object} EmitterKindDecision
 * @property {EmitterKind} resolvedEmitterKind
 * @property {{ sectional: number, panel: number }} emitterKindVotes
 * @property {string[]} emitterKindDecisionNotes
 * @property {'preference' | 'majority' | 'tie_break' | 'forced_override' | 'fallback'} decisionSource
 */

/**
 * @param {object} args
 * @param {'auto' | 'sectional' | 'panel'} args.preference
 * @param {EmitterKindVote[]} args.votes
 * @param {EmitterKind | null | undefined} [args.forcedOverride] - от primary для economy/efficient
 * @param {'sectional' | 'panel'} [args.tieBreakKind]
 * @returns {EmitterKindDecision}
 */
export function decideObjectEmitterKind({
  preference,
  votes,
  forcedOverride = null,
  tieBreakKind = 'sectional',
}) {
  /** @type {string[]} */
  const notes = [];

  if (forcedOverride === 'sectional' || forcedOverride === 'panel') {
    notes.push(
      `Тип приладів зафіксовано з основної лінії підбору: ${forcedOverride} `
        + '(єдиний kind для economy/efficient).',
    );
    return {
      resolvedEmitterKind: forcedOverride,
      emitterKindVotes: countVotes(votes),
      emitterKindDecisionNotes: notes,
      decisionSource: 'forced_override',
    };
  }

  if (preference === 'sectional' || preference === 'panel') {
    notes.push(
      `Тип приладів задано користувачем: heatingSystem.radiatorEmitterPreference=${preference}.`,
    );
    return {
      resolvedEmitterKind: preference,
      emitterKindVotes: countVotes(votes),
      emitterKindDecisionNotes: notes,
      decisionSource: 'preference',
    };
  }

  const tallies = countVotes(votes);
  const { sectional, panel } = tallies;

  if (sectional === 0 && panel === 0) {
    notes.push(
      'Немає голосів Pass 1 (усі кімнати skip / без радіаторів) — fallback sectional.',
    );
    return {
      resolvedEmitterKind: 'sectional',
      emitterKindVotes: tallies,
      emitterKindDecisionNotes: notes,
      decisionSource: 'fallback',
    };
  }

  if (sectional === panel) {
    notes.push(
      `Нічия голосів Pass 1 (sectional=${sectional}, panel=${panel}) — tie-break → ${tieBreakKind}.`,
    );
    for (const v of votes) {
      notes.push(`  · ${v.roomName ?? v.roomId}: ${v.preferredKind} — ${v.reason}`);
    }
    return {
      resolvedEmitterKind: tieBreakKind,
      emitterKindVotes: tallies,
      emitterKindDecisionNotes: notes,
      decisionSource: 'tie_break',
    };
  }

  const winner = sectional > panel ? 'sectional' : 'panel';
  notes.push(
    `Majority Pass 1: sectional=${sectional}, panel=${panel} → об’єкт ${winner}.`,
  );
  for (const v of votes) {
    notes.push(`  · ${v.roomName ?? v.roomId}: ${v.preferredKind} — ${v.reason}`);
  }

  return {
    resolvedEmitterKind: winner,
    emitterKindVotes: tallies,
    emitterKindDecisionNotes: notes,
    decisionSource: 'majority',
  };
}

/**
 * @param {EmitterKindVote[]} votes
 * @returns {{ sectional: number, panel: number }}
 */
function countVotes(votes) {
  let sectional = 0;
  let panel = 0;
  for (const v of votes) {
    if (v.preferredKind === 'panel') panel += 1;
    else if (v.preferredKind === 'sectional') sectional += 1;
  }
  return { sectional, panel };
}

/**
 * Назначение: Pass 1 — локальный «идеальный» kind комнаты (голос).
 * Описание: гейты окна / >N секций / bottom → только голос, не финальный подбор.
 */

import {
  adjustedRadiatorWatts,
  parsePanelHeightMm,
  pickPanelSkuForRoom,
} from '../radiatorSizingHelpers.js';

/**
 * @typedef {'sectional' | 'panel'} EmitterKind
 */

/**
 * @param {object} args
 * @param {number} args.qRad
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} args.sectionalPool
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} args.panelPoolFiltered
 * @param {50 | 70} args.baseDeltaT
 * @param {number} args.targetDeltaT
 * @param {'side' | 'bottom' | undefined} args.radiatorConnection
 * @param {number | null} [args.windowOpeningWidthMm]
 * @param {number} args.maxSectionsBeforeMultiUnit
 * @param {number} args.maxSectionsHeuristic
 * @param {number} args.sectionalCandidatesPerRoom
 * @param {number} args.ventilationReserveFactor
 * @returns {{ preferredKind: EmitterKind, reason: string } | null}
 */
export function exploreRoomEmitterKindVote(args) {
  const {
    qRad,
    sectionalPool,
    panelPoolFiltered,
    baseDeltaT,
    targetDeltaT,
    radiatorConnection,
    windowOpeningWidthMm,
    maxSectionsBeforeMultiUnit,
    maxSectionsHeuristic,
    sectionalCandidatesPerRoom,
    ventilationReserveFactor,
  } = args;

  if (qRad <= 0) return null;

  const sectionalThermal = sizeSectionalThermal(
    qRad,
    sectionalPool,
    baseDeltaT,
    targetDeltaT,
    sectionalCandidatesPerRoom,
  );
  const panelPick =
    panelPoolFiltered.length > 0
      ? pickPanelSkuForRoom(
        qRad,
        panelPoolFiltered,
        baseDeltaT,
        targetDeltaT,
        windowOpeningWidthMm ?? null,
      )
      : null;

  let sectionalWin = null;
  if (sectionalThermal) {
    const sectionWidthMm =
      sectionalThermal.radiator.sectionWidthMm
      ?? sectionalThermal.radiator.dimensions?.width
      ?? null;
    sectionalWin = applyWindowWidthRulesSectional({
      sections: sectionalThermal.sections,
      sectionWidthMm,
      windowOpeningWidthMm: windowOpeningWidthMm ?? null,
      ventilationReserveFactor,
      maxSectionsHeuristic,
    });
  }

  if (radiatorConnection === 'bottom' && panelPick) {
    return {
      preferredKind: 'panel',
      reason: 'Нижня підводка: локально переважна панель (голос Pass 1).',
    };
  }

  if (sectionalThermal && sectionalWin && panelPick) {
    const panelLen = panelPick.panelLengthMm;
    const panelWidthOk =
      windowOpeningWidthMm != null && panelLen != null
        ? panelLen / windowOpeningWidthMm >= 0.7
        : null;
    const secWidthOk = sectionalWin.widthOk;
    if (panelWidthOk === true && secWidthOk === false) {
      return {
        preferredKind: 'panel',
        reason:
          'Панель закриває ≥70% ширини вікна; секції після правила вікна — ні (голос Pass 1).',
      };
    }
    if (
      sectionalWin.sections != null
      && sectionalWin.sections > maxSectionsBeforeMultiUnit
      && panelPick.adjustedWatts >= qRad
    ) {
      return {
        preferredKind: 'panel',
        reason:
          `Секційний варіант >${maxSectionsBeforeMultiUnit} секцій `
          + `(${sectionalWin.sections}) — голос за панель.`,
      };
    }
  }

  if (!sectionalThermal && panelPick) {
    return {
      preferredKind: 'panel',
      reason: 'У пулі немає підходящих секцій — голос за панель.',
    };
  }

  if (sectionalThermal) {
    return {
      preferredKind: 'sectional',
      reason: 'Локально переважні секції (голос Pass 1).',
    };
  }

  if (panelPick) {
    return {
      preferredKind: 'panel',
      reason: 'Лише панель доступна в каталозі (голос Pass 1).',
    };
  }

  return null;
}

/**
 * @param {number} qRad
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} sectionalPool
 * @param {50 | 70} baseDeltaT
 * @param {number} targetDeltaT
 * @param {number} candidateLimit
 */
export function sizeSectionalThermal(
  qRad,
  sectionalPool,
  baseDeltaT,
  targetDeltaT,
  candidateLimit,
) {
  if (!sectionalPool.length || qRad <= 0) return null;
  const candidates = sectionalPool.slice(0, candidateLimit);
  /** @type {{ kind: 'section', radiator: import('../../catalog/types.js').RadiatorCatalogItemNormalized, sections: number, adjustedWatts: number, sectionsThermalMin: number } | null} */
  let best = null;
  for (const r of candidates) {
    const adjustedWatts = adjustedRadiatorWatts(r, baseDeltaT, targetDeltaT);
    if (adjustedWatts <= 0) continue;
    const sectionsThermalMin = Math.ceil(qRad / adjustedWatts);
    const isBetter =
      !best
      || sectionsThermalMin < best.sections
      || (sectionsThermalMin === best.sections && adjustedWatts < best.adjustedWatts);
    if (isBetter) {
      best = {
        kind: 'section',
        radiator: r,
        sections: sectionsThermalMin,
        adjustedWatts,
        sectionsThermalMin,
      };
    }
  }
  return best;
}

/**
 * @typedef {object} WindowWidthSectionalCtx
 * @property {number | null} sections
 * @property {number | null} sectionWidthMm
 * @property {number | null} windowOpeningWidthMm
 * @property {number} ventilationReserveFactor
 * @property {number} maxSectionsHeuristic
 */

/**
 * @param {WindowWidthSectionalCtx} roomCtx
 */
export function applyWindowWidthRulesSectional(roomCtx) {
  const {
    sections: initialSections,
    sectionWidthMm,
    windowOpeningWidthMm,
    ventilationReserveFactor,
    maxSectionsHeuristic,
  } = roomCtx;
  let sections = initialSections;
  /** @type {string[]} */
  const sizingNotes = [];
  const minSectionsForWindow =
    windowOpeningWidthMm != null && sectionWidthMm != null && sectionWidthMm > 0
      ? Math.ceil((0.7 * windowOpeningWidthMm) / sectionWidthMm)
      : null;

  if (sections != null && minSectionsForWindow != null && sections < minSectionsForWindow) {
    const prev = sections;
    sections = Math.min(Math.max(minSectionsForWindow, prev), maxSectionsHeuristic);
    if (sections > prev) {
      sizingNotes.push(
        `Для правила ≥70% ширини вікна число секцій збільшено з ${prev} до ${sections} `
          + `(теплове навантаження з kVent=${ventilationReserveFactor} уже було покрито меншою кількістю).`,
      );
    }
  }

  let radiatorWidthMm =
    sections != null && sectionWidthMm != null ? sections * sectionWidthMm : null;
  let widthCoverageRatio =
    radiatorWidthMm != null && windowOpeningWidthMm != null
      ? radiatorWidthMm / windowOpeningWidthMm
      : null;
  let widthOk = widthCoverageRatio != null ? widthCoverageRatio >= 0.7 : null;

  if (
    sections != null
    && sectionWidthMm != null
    && windowOpeningWidthMm != null
    && widthOk === false
  ) {
    let s = sections;
    while (s < maxSectionsHeuristic && sectionWidthMm * s < 0.7 * windowOpeningWidthMm) {
      s += 1;
    }
    if (s > sections) {
      sizingNotes.push(
        `Додатково збільшено число секцій до ${s} для наближення до покриття ≥70% ширини вікна.`,
      );
      sections = s;
      radiatorWidthMm = sections * sectionWidthMm;
      widthCoverageRatio = radiatorWidthMm / windowOpeningWidthMm;
      widthOk = widthCoverageRatio >= 0.7;
    }
  }

  return { sections, radiatorWidthMm, widthCoverageRatio, widthOk, sizingNotes };
}

/**
 * Сортировка секционного пула: выше/глубже (больше Вт/секцию) — для эскалации B.
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} pool
 * @param {50 | 70} baseDeltaT
 * @param {number} targetDeltaT
 */
export function sortSectionalByEscalationPower(pool, baseDeltaT, targetDeltaT) {
  return [...pool].sort((a, b) => {
    const wa = adjustedRadiatorWatts(a, baseDeltaT, targetDeltaT);
    const wb = adjustedRadiatorWatts(b, baseDeltaT, targetDeltaT);
    if (wb !== wa) return wb - wa;
    const ha = a.dimensions?.height ?? 0;
    const hb = b.dimensions?.height ?? 0;
    return hb - ha;
  });
}

// re-export для эскалации (высота панели)
export { parsePanelHeightMm };

/**
 * Назначение: ядро подбора радиаторов (Two-Pass Orchestrator).
 * Описание: Pass 1 — голоса kind; Pass 2 — forced kind + эскалация; единый тип на объект.
 */
import { round } from '../../utils/math.js';
import { resolveFlowDeltaTK } from '../../hydraulics/resolveFlowDeltaTK.js';
import { thermalLoadToFlow } from '../../hydraulics/thermalLoadToFlow.js';
import { logger } from '../../utils/logger.js';
import { buildWarmFloorMatchingNotes } from '../warmFloor.js';
import { buildRadiatorConnectionSelectionNotes } from './radiatorConnectionNotes.js';
import {
  buildUfhHeatFluxUpWattsByRoomId,
  resolveMixedRadiatorRoomLoad,
} from './resolveMixedRadiatorRoomLoad.js';
import { resolveMicroLoadRadiatorStrategy } from './resolveMicroLoadRadiatorStrategy.js';
import { summarizeRadiatorEmitters } from './summarizeRadiatorEmitters.js';
import { resolveRecommendation } from '../../recommendations/recommendationResolver.js';
import { isMixedRadiatorsUfhHeatingMode } from './mixedRadiatorsUfhMode.js';
import { resolveKVent } from '../../logic/ventilationReserve.js';
import { resolveDesignRoomAirTempC } from '../../../../shared/roomDesignAirTemp.js';
import {
  normalizeRadiatorEmitterPreference,
  radiatorEmitterPreferenceLabel,
} from '../../../../shared/radiatorEmitterPreference.js';
import {
  adjustOutputWatts,
  filterPanelsByConnection,
  isPanelRadiator,
  isSectionalRadiator,
} from '../radiatorSizingHelpers.js';
import { decideObjectEmitterKind } from './decideObjectEmitterKind.js';
import { exploreRoomEmitterKindVote } from './exploreRoomEmitterKind.js';
import {
  pickMinimumViableForcedKind,
  sizeForcedRoomEmitter,
} from './sizeForcedRoomEmitter.js';

/** @type {import('../../dhw/types.js').RadiatorEmitterKindRules} */
const DEFAULT_EMITTER_KIND_RULES = Object.freeze({
  maxSectionsBeforeMultiUnit: 24,
  maxUnitsPerRoom: 4,
  maxSectionsHeuristic: 80,
  sectionalCandidatesPerRoom: 16,
  tieBreakKind: 'sectional',
});

/**
 * @param {'panel' | 'section'} kind
 * @param {number} adjustedWatts
 * @param {number | null | undefined} sections
 * @param {number} [unitsCount]
 */
function emitterFieldsFromSized(kind, adjustedWatts, sections, unitsCount = 1) {
  const units = Math.max(1, Math.trunc(unitsCount) || 1);
  if (kind === 'panel') {
    return {
      outputPerSectionWatts: 0,
      deliverableWatts: Math.max(0, Math.round(adjustedWatts * units)),
      unitsCount: units,
      displayKind: /** @type {'panel'} */ ('panel'),
      priceBasis: /** @type {'panel'} */ ('panel'),
    };
  }
  const sec = typeof sections === 'number' && Number.isFinite(sections) ? sections : 1;
  const perSection = Math.max(1, Math.round(adjustedWatts));
  return {
    outputPerSectionWatts: perSection,
    deliverableWatts: Math.round(perSection * sec * units),
    unitsCount: units,
    displayKind: /** @type {'sectional'} */ ('sectional'),
    priceBasis: /** @type {'section'} */ ('section'),
  };
}

/**
 * Ціна позиції каталогу для смети (report.commercial).
 *
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized | null | undefined} radiator
 * @returns {{ unitPriceUah?: number }}
 */
function radiatorCommercialPriceFields(radiator) {
  if (
    radiator
    && typeof radiator.price === 'number'
    && Number.isFinite(radiator.price)
    && radiator.price > 0
  ) {
    return { unitPriceUah: radiator.price };
  }
  return {};
}

/**
 * @param {Pick<import('../../types/shared-types.js').RadiatorsByRoomItem, 'roomId' | 'roomName' | 'heatLossWatts' | 'radiatorDesignWatts'> & {
 *   designAirTempC?: number;
 *   designAirTempSource?: import('../../types/shared-types.js').DesignRoomAirTempSource;
 *   flowRateM3PerHour?: number;
 *   radiatorModel?: string;
 *   warnings?: string[];
 *   sizingNotes?: string[];
 * }} base
 * @returns {import('../../types/shared-types.js').RadiatorsByRoomItem}
 */
function skippedRoomEmitter(base) {
  return {
    roomId: base.roomId,
    roomName: base.roomName,
    heatLossWatts: base.heatLossWatts,
    radiatorDesignWatts: base.radiatorDesignWatts,
    ...(base.designAirTempC != null ? { designAirTempC: base.designAirTempC } : {}),
    ...(base.designAirTempSource != null
      ? { designAirTempSource: base.designAirTempSource }
      : {}),
    ...(base.flowRateM3PerHour != null
      ? { flowRateM3PerHour: base.flowRateM3PerHour }
      : {}),
    radiatorModel: base.radiatorModel ?? '—',
    outputPerSectionWatts: 0,
    sections: null,
    deliverableWatts: 0,
    displayKind: /** @type {'none'} */ ('none'),
    ...(base.warnings ? { warnings: base.warnings } : {}),
    ...(base.sizingNotes ? { sizingNotes: base.sizingNotes } : {}),
  };
}

/**
 * @param {{ supplyC: number, returnC: number, insideC: number }} args
 * @returns {number}
 */
function deltaTmeanK({ supplyC, returnC, insideC }) {
  return (supplyC + returnC) / 2 - insideC;
}

/**
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @param {50 | 70} baseDeltaT
 */
function sectionOutputPassport(r, baseDeltaT) {
  return baseDeltaT === 70 ? r.outputWatts.deltaT70 : r.outputWatts.deltaT50;
}

/**
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @param {'individual' | 'central'} heatingDistribution
 * @param {'side' | 'bottom' | undefined} connection
 */
function radiatorBrandPreferenceScore(r, heatingDistribution, connection) {
  const m = String(r?.model ?? '').toLowerCase();
  const mat = String(r?.material ?? '').toLowerCase();
  let score = 0;
  if (heatingDistribution === 'central') {
    if (m.includes('mirado') || mat.includes('бимет')) score += 120;
    if (m.includes('global')) score += 60;
  } else {
    if (m.includes('fondital')) score += 120;
    if (m.includes('radik')) score += 100;
    if (m.includes('korado')) score += 100;
    if (m.includes('global')) score += 70;
    if (m.includes('exclusivo') || m.includes('blitz')) score += 50;
    if (m.includes('mirado') || mat.includes('бимет')) score -= 40;
  }
  if (connection === 'bottom') {
    if (/\bvkp\b|\b\d{2}vk\b/i.test(m)) score += 60;
    if (isPanelRadiator(r)) score += 20;
  } else if (connection === 'side') {
    if (/-k\b|klasik|секцион|b3|b4/i.test(m)) score += 30;
  }
  return score;
}

/**
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @param {50 | 70} baseDeltaT
 * @param {'individual' | 'central'} heatingDistribution
 * @param {'side' | 'bottom' | undefined} connection
 */
function radiatorCompositeRank(r, baseDeltaT, heatingDistribution, connection) {
  const w = sectionOutputPassport(r, baseDeltaT);
  const b = radiatorBrandPreferenceScore(r, heatingDistribution, connection);
  if (heatingDistribution === 'individual') return w + b * 0.38;
  return w + b * 0.08;
}

/**
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} radiators
 * @param {50 | 70} baseDeltaT
 * @param {'individual' | 'central'} heatingDistribution
 * @param {'side' | 'bottom' | undefined} connection
 */
function sortRadiatorsForMatching(radiators, baseDeltaT, heatingDistribution, connection) {
  return [...radiators].sort((a, b) => {
    const ra = radiatorCompositeRank(a, baseDeltaT, heatingDistribution, connection);
    const rb = radiatorCompositeRank(b, baseDeltaT, heatingDistribution, connection);
    if (rb !== ra) return rb - ra;
    return sectionOutputPassport(b, baseDeltaT) - sectionOutputPassport(a, baseDeltaT);
  });
}

/**
 * @param {import('../../dhw/types.js').RadiatorApplianceRules | null | undefined} radiatorRules
 * @returns {import('../../dhw/types.js').RadiatorEmitterKindRules}
 */
function resolveEmitterKindRules(radiatorRules) {
  return radiatorRules?.emitterKind ?? DEFAULT_EMITTER_KIND_RULES;
}

/**
 * Підбір радіаторів: Two-Pass — голоса kind → глобальный lock → sizing с эскалацией.
 *
 * @param {object} args
 * @param {import('../../types/shared-types.js').HeatLossReport} args.roomsHeatLoss
 * @param {import('../../types/shared-types.js').HeatingSystemInput} [args.heatingSystem]
 * @param {import('../../catalog/types.js').NormalizedCatalog} args.catalog
 * @param {string|null} [args.radiatorModel]
 * @param {import('../../types/shared-types.js').BuildingInput | null} [args.building]
 * @param {import('../../types/boiler-types.js').BoilerMatchingReport | null} [args.boilerMatching]
 * @param {'economy' | 'efficient' | null} [args.radiatorLineTier]
 * @param {import('../../types/shared-types.js').UnderfloorHeatingReport | null} [args.underfloorHeating]
 * @param {number | undefined} [args.deltaTSystemK]
 * @param {import('../../dhw/types.js').RadiatorApplianceRules | null | undefined} [args.radiatorRules]
 * @param {import('../../recommendations/types.js').RecommendationsBundle | null | undefined} [args.recommendations]
 * @param {'sectional' | 'panel' | null} [args.forcedEmitterKind] - от primary для eco/eff
 * @returns {import('../../types/shared-types.js').RadiatorsMatchingReport}
 */
export function pickRadiators({
  roomsHeatLoss,
  heatingSystem = {},
  catalog,
  radiatorModel = null,
  building = null,
  boilerMatching = null,
  radiatorLineTier = null,
  underfloorHeating = null,
  deltaTSystemK,
  radiatorRules = null,
  recommendations = null,
  forcedEmitterKind = null,
}) {
  const supplyC = heatingSystem.supplyC ?? 75;
  const returnC = heatingSystem.returnC ?? 65;
  const insideC = heatingSystem.insideC ?? 20;
  const bathroomAirTempC =
    typeof building?.temps?.bathroomAirTempC === 'number'
    && Number.isFinite(building.temps.bathroomAirTempC)
      ? building.temps.bathroomAirTempC
      : undefined;

  const hasEfficientProposal =
    radiatorLineTier === 'efficient'
    || (radiatorLineTier == null && Boolean(boilerMatching?.proposalEfficient));
  let baseDeltaT = /** @type {50 | 70 | undefined} */ (heatingSystem.radiatorReferenceDeltaT);
  if (baseDeltaT == null) {
    if (radiatorLineTier === 'economy') {
      baseDeltaT = 70;
    } else if (radiatorLineTier === 'efficient') {
      baseDeltaT = 50;
    } else {
      baseDeltaT = hasEfficientProposal ? 50 : 70;
    }
  }

  const heatingDistribution =
    building?.objectMeta?.heatingDistribution === 'central' ? 'central' : 'individual';
  const radiatorConnection = heatingSystem.radiatorConnection;
  const radiatorEmitterPreference = normalizeRadiatorEmitterPreference(
    heatingSystem.radiatorEmitterPreference,
  );
  const ventilationReserveFactor = resolveKVent(
    building?.objectMeta?.ventilationReserveMode,
  );
  const emitterKindRules = resolveEmitterKindRules(radiatorRules);

  const targetDeltaT = deltaTmeanK({ supplyC, returnC, insideC });
  const flowDeltaTK = resolveFlowDeltaTK({ deltaTSystemK, supplyC, returnC });
  /**
   * @param {number} watts
   * @returns {number}
   */
  const radiatorFlowM3h = (watts) =>
    thermalLoadToFlow({
      heatLoadWatts: watts,
      deltaTK: flowDeltaTK,
    }).flowRateM3PerHour;

  logger.info('matching.radiators.start', null, {
    baseDeltaT,
    targetDeltaT: round(targetDeltaT, 1),
    rooms: roomsHeatLoss?.rooms?.length ?? 0,
    radiatorModel,
    heatingDistribution,
    radiatorConnection: radiatorConnection ?? null,
    radiatorEmitterPreference,
    forcedEmitterKind,
    hasEfficientProposal,
    waterUnderfloorHeating: Boolean(heatingSystem.waterUnderfloorHeating),
    thermalRegimePreset: heatingSystem.thermalRegimePreset ?? null,
    ventilationReserveFactor,
  });

  const allRadiators = catalog?.radiators ?? [];
  const sectionalPool = allRadiators.filter((r) => isSectionalRadiator(r));
  const panelPoolRaw = allRadiators.filter((r) => isPanelRadiator(r));
  const panelPoolFiltered = filterPanelsByConnection(panelPoolRaw, radiatorConnection);

  /** @type {string[]} */
  const radiatorSelectionNotes = [];
  if (panelPoolRaw.length > 0) {
    radiatorSelectionNotes.push(
      `У каталозі ${panelPoolRaw.length} панельних позицій (priceBasis=panel): `
        + 'підбір за довжиною SKU і потужністю на прилад; секції у звіті не застосовуються.',
    );
  }
  if (
    radiatorConnection === 'bottom'
    && panelPoolFiltered.length === 0
    && panelPoolRaw.length > 0
  ) {
    radiatorSelectionNotes.push(
      'Для нижньої підводки в каталозі немає панелей VKP/нижнього підключення — '
        + 'розгляньте секційні моделі або доповніть каталог.',
    );
  }
  if (radiatorConnection === 'bottom' && panelPoolRaw.length === 0) {
    radiatorSelectionNotes.push(
      'Запрошено нижню підводку, але панельних моделей у каталозі немає.',
    );
  }

  radiatorSelectionNotes.push(
    `Перевага типу приладів: ${radiatorEmitterPreferenceLabel(radiatorEmitterPreference)} `
      + `(heatingSystem.radiatorEmitterPreference=${radiatorEmitterPreference}).`,
  );

  if (hasEfficientProposal) {
    const passportHighDeltaT = 70;
    const lowSupplyC = 55;
    const lowReturnC = 45;
    const lowTargetDeltaT = deltaTmeanK({
      supplyC: lowSupplyC,
      returnC: lowReturnC,
      insideC,
    });
    const refWatts = 100;
    const atLow = adjustOutputWatts({
      baseWatts: refWatts,
      baseDeltaT: passportHighDeltaT,
      targetDeltaT: lowTargetDeltaT,
    });
    const relOut = atLow / refWatts;
    const sectionScale = relOut > 0 ? 1 / relOut : 0;
    radiatorSelectionNotes.push(
      `Конденсаційний контур: за орієнтовним графіком ${lowSupplyC}/${lowReturnC} °C і ${insideC} °C `
        + `в приміщенні середній температурний напір радіатора ≈ ${round(lowTargetDeltaT, 1)} К `
        + `(для порівняння — типовий паспорт ΔT≈70 К при ~90/70 °C). За степеневою моделлю (n≈1,3) `
        + `питома тепловіддача падає ≈у ${relOut > 0 ? (1 / relOut).toFixed(1) : '—'} раз — `
        + `орієнтовно потрібно ≈у ${sectionScale > 0 ? sectionScale.toFixed(1) : '—'} раз `
        + 'більше секцій/поверхні приладу, ніж у високотемпературній системі.',
    );
  }

  radiatorSelectionNotes.push(...buildRadiatorConnectionSelectionNotes(radiatorConnection));
  radiatorSelectionNotes.push(...buildWarmFloorMatchingNotes(heatingSystem));

  const ufhHeatFluxByRoomId = buildUfhHeatFluxUpWattsByRoomId(underfloorHeating);
  const applyUfhRadiatorOffset = isMixedRadiatorsUfhHeatingMode(heatingSystem);
  if (applyUfhRadiatorOffset && ufhHeatFluxByRoomId.size > 0) {
    radiatorSelectionNotes.push(
      'Змішаний режим (радіатори + ТП): навантаження на радіатор зменшується на віддачу теплої підлоги '
        + 'вгору (heatFluxUpWatts) по кожній кімнаті з ТП — без подвійного обліку потужності.',
    );
  }

  const sortedSectional = sortRadiatorsForMatching(
    radiatorModel
      ? sectionalPool.filter((r) => r.model === radiatorModel)
      : sectionalPool,
    baseDeltaT,
    heatingDistribution,
    radiatorConnection,
  );

  /** @type {NonNullable<import('../../types/shared-types.js').RadiatorsMatchingReport['inputs']>} */
  const emptyInputs = {
    supplyC,
    returnC,
    insideC,
    baseDeltaT,
    targetDeltaT: round(targetDeltaT, 1),
    ventilationReserveFactor,
    radiatorSizingAlignedWithCondensing: hasEfficientProposal,
    heatingDistribution,
    ...(radiatorConnection != null ? { radiatorConnection } : {}),
    radiatorEmitterPreference,
    ...(heatingSystem.thermalRegimePreset != null
      ? { thermalRegimePreset: heatingSystem.thermalRegimePreset }
      : {}),
  };

  if (sectionalPool.length === 0 && panelPoolRaw.length === 0) {
    logger.warn('matching.radiators.emptyCatalog', null);
    return {
      chosen: null,
      byRoom: [],
      emittersSummary: summarizeRadiatorEmitters([]),
      totalSections: null,
      warnings: ['У каталозі немає радіаторів.'],
      inputs: emptyInputs,
      radiatorSelectionNotes,
      resolvedEmitterKind: null,
      emitterKindVotes: { sectional: 0, panel: 0 },
      emitterKindDecisionNotes: [],
    };
  }

  /** @type {Map<string, number>} */
  const maxWindowWidthByRoom = new Map();
  /** @type {Map<string, number>} */
  const maxWindowHeightByRoom = new Map();
  const envelopeElements = building?.envelopeElements ?? [];
  for (const el of envelopeElements) {
    const kind = el?.kind ?? null;
    const construction = String(el?.construction ?? '').toLowerCase();
    const isWindow = kind === 'window' || construction.includes('окно');
    if (!isWindow) continue;
    const roomId = String(el?.roomId ?? '');
    if (!roomId) continue;
    const w = el?.openingWidthMm;
    if (typeof w === 'number' && Number.isFinite(w) && w > 0) {
      const prev = maxWindowWidthByRoom.get(roomId) ?? 0;
      if (w > prev) maxWindowWidthByRoom.set(roomId, w);
    }
    const h = el?.openingHeightMm;
    if (typeof h === 'number' && Number.isFinite(h) && h > 0) {
      const prevH = maxWindowHeightByRoom.get(roomId) ?? 0;
      if (h > prevH) maxWindowHeightByRoom.set(roomId, h);
    }
  }

  const minRoomWattsForWindowWidthRule = 800;

  /**
   * @typedef {object} RoomPrep
   * @property {string} roomId
   * @property {string} roomName
   * @property {number} roomInsideC
   * @property {import('../../../../shared/roomDesignAirTemp.js').DesignRoomAirTempSource | 'survey'} airSource
   * @property {number} roomTargetDeltaT
   * @property {number} qEnvelope
   * @property {number} qRad
   * @property {string[]} mixedNotes
   * @property {'skip' | 'minimum_viable' | 'normal'} action
   * @property {string[]} microNotes
   */

  /** @type {RoomPrep[]} */
  const roomPreps = [];
  /** @type {Set<string>} */
  const microRecCodes = new Set();

  for (const room of roomsHeatLoss?.rooms ?? []) {
    const roomType =
      room.type ?? building?.rooms?.find((r) => r.id === room.id)?.type;
    const air =
      typeof room.designAirTempC === 'number' && Number.isFinite(room.designAirTempC)
        ? {
            designAirTempC: room.designAirTempC,
            source: /** @type {import('../../../../shared/roomDesignAirTemp.js').DesignRoomAirTempSource} */ (
              room.designAirTempSource ?? 'survey'
            ),
          }
        : resolveDesignRoomAirTempC({
            ...(roomType !== undefined ? { roomType } : {}),
            insideC,
            ...(bathroomAirTempC !== undefined ? { bathroomAirTempC } : {}),
          });
    const roomInsideC = air?.designAirTempC ?? insideC;
    const roomTargetDeltaT = deltaTmeanK({
      supplyC,
      returnC,
      insideC: roomInsideC,
    });

    const qEnvelope = room.envelopeWatts ?? 0;
    const qDesignFull = room.designWatts ?? qEnvelope * ventilationReserveFactor;
    const mixedLoad = resolveMixedRadiatorRoomLoad({
      designWattsFull: qDesignFull,
      ufhHeatFluxUpWatts: applyUfhRadiatorOffset
        ? ufhHeatFluxByRoomId.get(room.id)
        : undefined,
    });
    const qRad = mixedLoad.qRad;

    if (mixedLoad.skipRadiator) {
      roomPreps.push({
        roomId: room.id,
        roomName: room.name,
        roomInsideC,
        airSource: air?.source ?? 'survey',
        roomTargetDeltaT,
        qEnvelope,
        qRad: 0,
        mixedNotes: mixedLoad.sizingNotes,
        action: 'skip',
        microNotes: [],
      });
      continue;
    }

    const microRules = radiatorRules?.microLoad ?? null;
    /** @type {'skip' | 'minimum_viable' | 'normal'} */
    let action = 'normal';
    /** @type {string[]} */
    let microNotes = [];

    if (microRules) {
      const microStrategy = resolveMicroLoadRadiatorStrategy({
        rules: microRules,
        room,
        building,
        qRad,
      });
      if (microStrategy.action === 'skip') {
        microRecCodes.add('REC_RADIATOR_MICRO_LOAD_SKIP');
        action = 'skip';
        microNotes = microStrategy.sizingNotes;
      } else if (microStrategy.action === 'minimum_viable') {
        microRecCodes.add('REC_RADIATOR_ENTRY_ZONE_MINIMUM');
        action = 'minimum_viable';
        microNotes = microStrategy.sizingNotes;
      }
    }

    roomPreps.push({
      roomId: room.id,
      roomName: room.name,
      roomInsideC,
      airSource: air?.source ?? 'survey',
      roomTargetDeltaT,
      qEnvelope,
      qRad,
      mixedNotes: mixedLoad.sizingNotes,
      action,
      microNotes,
    });
  }

  // ——— Pass 1: голоса (только при auto и без forced override) ———
  /** @type {import('./decideObjectEmitterKind.js').EmitterKindVote[]} */
  const votes = [];
  const needExplore =
    forcedEmitterKind == null
    && radiatorEmitterPreference === 'auto';

  if (needExplore) {
    for (const prep of roomPreps) {
      if (prep.action === 'skip' || prep.qRad <= 0) continue;
      const vote = exploreRoomEmitterKindVote({
        qRad: prep.qRad,
        sectionalPool: sortedSectional,
        panelPoolFiltered,
        baseDeltaT,
        targetDeltaT: prep.roomTargetDeltaT,
        radiatorConnection,
        windowOpeningWidthMm: maxWindowWidthByRoom.get(prep.roomId) ?? null,
        maxSectionsBeforeMultiUnit: emitterKindRules.maxSectionsBeforeMultiUnit,
        maxSectionsHeuristic: emitterKindRules.maxSectionsHeuristic,
        sectionalCandidatesPerRoom: emitterKindRules.sectionalCandidatesPerRoom,
        ventilationReserveFactor,
      });
      if (!vote) continue;
      votes.push({
        roomId: prep.roomId,
        roomName: prep.roomName,
        preferredKind: vote.preferredKind,
        reason: vote.reason,
      });
    }
  }

  const decision = decideObjectEmitterKind({
    preference: radiatorEmitterPreference,
    votes,
    forcedOverride: forcedEmitterKind,
    tieBreakKind: emitterKindRules.tieBreakKind,
  });

  const resolvedKind = decision.resolvedEmitterKind;
  radiatorSelectionNotes.push(...decision.emitterKindDecisionNotes);

  // ——— Pass 2: финальный sizing ———
  /** @type {import('../../types/shared-types.js').RadiatorsByRoomItem[]} */
  const byRoom = [];
  let anyMultiUnit = false;
  /** @type {Set<string>} */
  const underpoweredRoomIds = new Set();

  for (const prep of roomPreps) {
    if (prep.action === 'skip') {
      byRoom.push(
        skippedRoomEmitter({
          roomId: prep.roomId,
          roomName: prep.roomName,
          designAirTempC: prep.roomInsideC,
          designAirTempSource: prep.airSource,
          heatLossWatts: prep.qEnvelope,
          radiatorDesignWatts: 0,
          flowRateM3PerHour: 0,
          radiatorModel: '—',
          warnings: [],
          sizingNotes: [...prep.mixedNotes, ...prep.microNotes],
        }),
      );
      continue;
    }

    if (prep.action === 'minimum_viable') {
      const minSized = pickMinimumViableForcedKind({
        forcedKind: resolvedKind,
        sectionalPool: sortedSectional,
        panelPoolFiltered,
        baseDeltaT,
        targetDeltaT: prep.roomTargetDeltaT,
        windowOpeningWidthMm: maxWindowWidthByRoom.get(prep.roomId) ?? null,
        openingHeightMm: maxWindowHeightByRoom.get(prep.roomId) ?? null,
      });

      if (!minSized) {
        byRoom.push(
          skippedRoomEmitter({
            roomId: prep.roomId,
            roomName: prep.roomName,
            designAirTempC: prep.roomInsideC,
            designAirTempSource: prep.airSource,
            heatLossWatts: prep.qEnvelope,
            radiatorDesignWatts: Math.round(prep.qRad),
            flowRateM3PerHour: radiatorFlowM3h(prep.qRad),
            radiatorModel: '—',
            warnings: [
              `Не вдалося підібрати мінімальний ${resolvedKind} радіатор для вхідної зони.`,
            ],
            sizingNotes: [...prep.mixedNotes, ...prep.microNotes],
          }),
        );
        continue;
      }

      const emitter = emitterFieldsFromSized(
        minSized.kind === 'panel' ? 'panel' : 'section',
        minSized.adjustedWatts,
        minSized.sections,
        minSized.unitsCount,
      );
      const microThreshold =
        radiatorRules?.microLoad?.minDesignWattsThreshold ?? 150;
      const hydraulicsWatts = Math.max(
        prep.qRad,
        emitter.deliverableWatts,
        microThreshold,
      );

      byRoom.push({
        roomId: prep.roomId,
        roomName: prep.roomName,
        designAirTempC: prep.roomInsideC,
        designAirTempSource: prep.airSource,
        heatLossWatts: prep.qEnvelope,
        radiatorDesignWatts: Math.round(hydraulicsWatts),
        flowRateM3PerHour: radiatorFlowM3h(hydraulicsWatts),
        radiatorModel: minSized.radiator.model,
        outputPerSectionWatts: emitter.outputPerSectionWatts,
        sections: minSized.sections,
        sectionsThermalMin: minSized.sectionsThermalMin ?? minSized.sections,
        unitsCount: emitter.unitsCount,
        deliverableWatts: emitter.deliverableWatts,
        displayKind: emitter.displayKind,
        windowOpeningWidthMm: maxWindowWidthByRoom.get(prep.roomId) ?? null,
        radiatorWidthMm: minSized.radiatorWidthMm,
        widthCoverageRatio:
          minSized.widthCoverageRatio != null
            ? Math.round(minSized.widthCoverageRatio * 1000) / 1000
            : null,
        widthOk: minSized.widthOk,
        warnings: [],
        sizingNotes: [
          ...prep.mixedNotes,
          ...prep.microNotes,
          ...(minSized.sizingNotes ?? []),
        ],
        priceBasis: emitter.priceBasis,
        ...radiatorCommercialPriceFields(minSized.radiator),
        ...(minSized.panelLengthMm != null
          ? { panelLengthMm: minSized.panelLengthMm }
          : {}),
      });
      continue;
    }

    const sized = sizeForcedRoomEmitter({
      qRad: prep.qRad,
      forcedKind: resolvedKind,
      sectionalPool: sortedSectional,
      panelPoolFiltered,
      baseDeltaT,
      targetDeltaT: prep.roomTargetDeltaT,
      windowOpeningWidthMm: maxWindowWidthByRoom.get(prep.roomId) ?? null,
      openingHeightMm: maxWindowHeightByRoom.get(prep.roomId) ?? null,
      ventilationReserveFactor,
      emitterKindRules,
    });

    if (!sized) {
      byRoom.push(
        skippedRoomEmitter({
          roomId: prep.roomId,
          roomName: prep.roomName,
          designAirTempC: prep.roomInsideC,
          designAirTempSource: prep.airSource,
          heatLossWatts: prep.qEnvelope,
          radiatorDesignWatts: Math.round(prep.qRad),
          flowRateM3PerHour: radiatorFlowM3h(prep.qRad),
          radiatorModel: '—',
          warnings: [
            `Не вдалося підібрати ${resolvedKind} радіатор з каталогу (forced kind).`,
          ],
          sizingNotes: prep.mixedNotes,
        }),
      );
      continue;
    }

    if (sized.unitsCount > 1) anyMultiUnit = true;

    const emitter = emitterFieldsFromSized(
      sized.kind === 'panel' ? 'panel' : 'section',
      sized.adjustedWatts,
      sized.sections,
      sized.unitsCount,
    );

    /** @type {string[]} */
    const roomWarnings = [];
    if (sized.widthOk === false && prep.qEnvelope >= minRoomWattsForWindowWidthRule) {
      roomWarnings.push(
        `Радиатор перекрывает менее 70% ширины окна (${Math.round(
          (sized.widthCoverageRatio ?? 0) * 100,
        )}%). Рассмотрите другую длину/модель или перенос прибора.`,
      );
    }
    if (sized.underpowered) {
      underpoweredRoomIds.add(prep.roomId);
      roomWarnings.push(
        `У приміщенні «${prep.roomName}» секційний/панельний прилад типу «${resolvedKind}» `
          + `не покриває 100% тепловтрат. Нестача: ${sized.deficitWatts} Вт `
          + `(навантаження ${Math.round(prep.qRad)} Вт, віддача ${emitter.deliverableWatts} Вт).`,
      );
    }

    byRoom.push({
      roomId: prep.roomId,
      roomName: prep.roomName,
      designAirTempC: prep.roomInsideC,
      designAirTempSource: prep.airSource,
      heatLossWatts: prep.qEnvelope,
      radiatorDesignWatts: Math.round(prep.qRad),
      flowRateM3PerHour: radiatorFlowM3h(prep.qRad),
      radiatorModel: sized.radiator.model,
      outputPerSectionWatts: emitter.outputPerSectionWatts,
      sections: sized.sections,
      sectionsThermalMin: sized.sectionsThermalMin ?? sized.sections,
      unitsCount: emitter.unitsCount,
      deliverableWatts: emitter.deliverableWatts,
      displayKind: emitter.displayKind,
      windowOpeningWidthMm: maxWindowWidthByRoom.get(prep.roomId) ?? null,
      radiatorWidthMm: sized.radiatorWidthMm,
      widthCoverageRatio:
        sized.widthCoverageRatio != null
          ? Math.round(sized.widthCoverageRatio * 1000) / 1000
          : null,
      widthOk: sized.widthOk,
      warnings: roomWarnings,
      sizingNotes: [...prep.mixedNotes, ...(sized.sizingNotes ?? [])],
      priceBasis: emitter.priceBasis,
      ...radiatorCommercialPriceFields(sized.radiator),
      ...(sized.panelLengthMm != null ? { panelLengthMm: sized.panelLengthMm } : {}),
    });
  }

  // Инвариант: один displayKind на все подобранные комнаты
  const kindsOnObject = new Set(
    byRoom
      .filter((r) => r.displayKind === 'sectional' || r.displayKind === 'panel')
      .map((r) => r.displayKind),
  );
  if (kindsOnObject.size > 1) {
    logger.error('matching.radiators.mixedKindsOnObject', null, {
      kinds: [...kindsOnObject],
      resolvedKind,
    });
  }

  const firstSized = byRoom.find((r) => r.radiatorModel && r.radiatorModel !== '—');
  const chosenRadiator =
    firstSized != null
      ? (allRadiators.find((r) => r.model === firstSized.radiatorModel) ?? null)
      : (sortedSectional[0] ?? panelPoolFiltered[0] ?? null);

  const chosen = chosenRadiator;
  const baseWatts = chosen
    ? baseDeltaT === 70
      ? chosen.outputWatts.deltaT70
      : chosen.outputWatts.deltaT50
    : 0;
  const adjustedWatts = chosen
    ? adjustOutputWatts({ baseWatts, baseDeltaT, targetDeltaT })
    : 0;
  const sectionWidthMm = chosen?.sectionWidthMm ?? chosen?.dimensions?.width ?? null;

  /** @type {string[]} */
  const warnings = [];

  const graphAutoAdjusted =
    heatingSystem
    && typeof heatingSystem === 'object'
    && /** @type {Record<string, unknown>} */ (heatingSystem)._thermalRegimeAutoAdjusted
      === true;

  if (
    radiatorLineTier == null
    && !graphAutoAdjusted
    && hasEfficientProposal
    && supplyC >= 65
    && returnC >= 55
  ) {
    warnings.push(
      'Для вилучення ККД конденсаційного котла рекомендується нижчий графік теплоносія '
        + '(наприклад 55/45°C або тепла підлога) — за поточних supply/return розрахунок радіаторів консервативний.',
    );
  }

  if (sectionWidthMm == null && maxWindowWidthByRoom.size > 0 && !panelPoolRaw.length) {
    warnings.push(
      'Неможливо перевірити правило 70% ширини вікна: у обраного радіатора немає dimensions.width/sectionWidthMm.',
    );
  }
  if (sectionWidthMm != null && maxWindowWidthByRoom.size === 0) {
    warnings.push(
      'Неможливо перевірити правило 70% ширини вікна: в анкеті не задано openingWidthMm для вікон.',
    );
  }
  for (const item of byRoom) {
    for (const w of item.warnings ?? []) warnings.push(`[${item.roomName}] ${w}`);
  }

  /** @type {import('../../recommendations/types.js').ResolvedRecommendation[]} */
  const resolvedRecommendations = [];
  if (recommendations) {
    for (const code of microRecCodes) {
      const resolved = resolveRecommendation(recommendations, code);
      if (resolved) resolvedRecommendations.push(resolved);
    }
    if (decision.decisionSource === 'majority' || decision.decisionSource === 'tie_break') {
      const resolved = resolveRecommendation(
        recommendations,
        'REC_RADIATOR_EMITTER_KIND_MAJORITY',
        {
          resolvedEmitterKind: resolvedKind,
          sectionalVotes: decision.emitterKindVotes.sectional,
          panelVotes: decision.emitterKindVotes.panel,
          decisionSource: decision.decisionSource,
        },
      );
      if (resolved) resolvedRecommendations.push(resolved);
    }
    if (anyMultiUnit) {
      const resolved = resolveRecommendation(recommendations, 'REC_RADIATOR_MULTI_UNIT');
      if (resolved) resolvedRecommendations.push(resolved);
    }
    for (const row of byRoom) {
      if (!underpoweredRoomIds.has(row.roomId)) continue;
      const resolved = resolveRecommendation(
        recommendations,
        'WARN_RADIATOR_KIND_LOCKED_UNDERPOWERED',
        {
          roomName: row.roomName,
          resolvedEmitterKind: resolvedKind,
          deficitWatts: Math.max(
            0,
            Math.round((row.radiatorDesignWatts ?? 0) - (row.deliverableWatts ?? 0)),
          ),
          radiatorDesignWatts: Math.round(row.radiatorDesignWatts ?? 0),
          deliverableWatts: Math.round(row.deliverableWatts ?? 0),
        },
      );
      if (resolved) resolvedRecommendations.push(resolved);
    }
  }

  const emittersSummary = summarizeRadiatorEmitters(byRoom);

  return {
    chosen: chosen
      ? {
          model: chosen.model,
          ...(chosen.material != null ? { material: chosen.material } : {}),
          ...(chosen.volumeLiters != null
            ? { volumeLitersPerSection: chosen.volumeLiters }
            : {}),
          baseOutputWatts: baseWatts,
          baseDeltaT,
          adjustedOutputWatts: Math.round(adjustedWatts),
          targetDeltaT: round(targetDeltaT, 1),
          ...(sectionWidthMm != null ? { sectionWidthMm } : {}),
          ...(chosen.priceBasis != null ? { priceBasis: chosen.priceBasis } : {}),
        }
      : null,
    byRoom,
    emittersSummary,
    totalSections:
      emittersSummary.sectionalUnits > 0 || emittersSummary.panelUnits > 0
        ? emittersSummary.sectionalSections
        : null,
    warnings,
    inputs: {
      supplyC,
      returnC,
      insideC,
      baseDeltaT,
      targetDeltaT: round(targetDeltaT, 1),
      flowDeltaTK,
      ...(typeof deltaTSystemK === 'number' && deltaTSystemK > 0
        ? { deltaTSystemK }
        : {}),
      ventilationReserveFactor,
      radiatorSizingAlignedWithCondensing: hasEfficientProposal,
      heatingDistribution,
      ...(radiatorConnection != null ? { radiatorConnection } : {}),
      radiatorEmitterPreference,
      ...(heatingSystem.thermalRegimePreset != null
        ? { thermalRegimePreset: heatingSystem.thermalRegimePreset }
        : {}),
    },
    resolvedEmitterKind: resolvedKind,
    emitterKindVotes: decision.emitterKindVotes,
    emitterKindDecisionNotes: decision.emitterKindDecisionNotes,
    radiatorSelectionNotes,
    ...(resolvedRecommendations.length > 0 ? { resolvedRecommendations } : {}),
  };
}

/**
 * Назначение: стратегия подбора радиатора при малой остаточной нагрузке (Ф5 «Тамбур»).
 * Описание: Входная зона — минимальный жизнеспособный прибор; внутреннее помещение — без радиатора.
 */

import {
  countExteriorWallsForRoom,
  inferRoomExteriorLayoutFromWallCounts,
} from '../../logic/roomExteriorLayoutHeatLoss.js';

/**
 * @typedef {'normal' | 'skip' | 'minimum_viable'} MicroLoadRadiatorAction
 */

/**
 * @typedef {object} MicroLoadRadiatorStrategy
 * @property {MicroLoadRadiatorAction} action
 * @property {string[]} sizingNotes
 */

/**
 * @param {object} args
 * @param {import('../../dhw/types.js').RadiatorApplianceRules['microLoad']} args.rules
 * @param {import('../../types/shared-types.js').HeatLossRoomReport} args.room
 * @param {import('../../types/shared-types.js').BuildingInput | null} [args.building]
 * @param {number} args.qRad - остаточная нагрузка на радиатор, Вт
 * @returns {MicroLoadRadiatorStrategy}
 */
export function resolveMicroLoadRadiatorStrategy({ rules, room, building, qRad }) {
  const threshold = rules.minDesignWattsThreshold;
  if (!(qRad > 0) || qRad >= threshold) {
    return { action: 'normal', sizingNotes: [] };
  }

  const roomId = String(room?.id ?? '');
  const roomType = String(room?.type ?? '').trim().toLowerCase();
  const entryTypes = new Set(rules.entryRoomTypes.map((t) => String(t).toLowerCase()));

  /** @type {'corner' | 'facade' | 'internal' | undefined} */
  let layout = building?.rooms?.find((r) => r.id === roomId)?.roomExteriorLayout;
  if (layout !== 'corner' && layout !== 'facade' && layout !== 'internal') {
    const counts = countExteriorWallsForRoom(building?.envelopeElements ?? [], roomId);
    layout = inferRoomExteriorLayoutFromWallCounts(counts);
  }

  const hasOuterWalls = layout === 'corner' || layout === 'facade';
  const isEntryRoomType = entryTypes.has(roomType);

  if (isEntryRoomType || hasOuterWalls) {
    return {
      action: 'minimum_viable',
      sizingNotes: [
        `Залишкове навантаження ≈${Math.round(qRad)} Вт нижче порогу ${threshold} Вт — `
        + 'вхідна зона: підібрано мінімально життєздатний радіатор (захист від промерзання / комфорт біля дверей).',
      ],
    };
  }

  return {
    action: 'skip',
    sizingNotes: [
      `Залишкове навантаження ≈${Math.round(qRad)} Вт нижче порогу ${threshold} Вт — `
      + 'внутрішнє приміщення: радіатор не потрібен (перетік / мікроколектор гідравліки).',
    ],
  };
}

/**
 * Назначение: остаточная нагрузка на радиатор при смешанном режиме (радиаторы + ТП).
 * Описание: Вычитает heatFluxUpWatts из designWatts комнаты; при полном покрытии ТП подбор пропускается.
 */

/**
 * @param {import('../../types/shared-types.js').UnderfloorHeatingReport | null | undefined} underfloorHeating
 * @returns {Map<string, number>}
 */
export function buildUfhHeatFluxUpWattsByRoomId(underfloorHeating) {
  /** @type {Map<string, number>} */
  const map = new Map();
  for (const row of underfloorHeating?.rooms ?? []) {
    const roomId = String(row?.roomId ?? '');
    const watts = row?.heatFluxUpWatts;
    if (!roomId || typeof watts !== 'number' || !Number.isFinite(watts) || watts <= 0) {
      continue;
    }
    map.set(roomId, watts);
  }
  return map;
}

/**
 * @param {object} args
 * @param {number} args.designWattsFull — designWatts комнаты (envelope × kVent), Вт
 * @param {number | undefined | null} args.ufhHeatFluxUpWatts — отдача ТП вверх по комнате, Вт
 * @returns {{
 *   qRad: number,
 *   designWattsFull: number,
 *   ufhHeatFluxUpWatts: number | null,
 *   sizingNotes: string[],
 *   skipRadiator: boolean,
 * }}
 */
export function resolveMixedRadiatorRoomLoad(args) {
  const { designWattsFull, ufhHeatFluxUpWatts } = args;
  const qFull = Math.max(0, designWattsFull);
  const ufhW =
    typeof ufhHeatFluxUpWatts === 'number'
    && Number.isFinite(ufhHeatFluxUpWatts)
    && ufhHeatFluxUpWatts > 0
      ? ufhHeatFluxUpWatts
      : null;

  if (ufhW == null) {
    return {
      qRad: qFull,
      designWattsFull: qFull,
      ufhHeatFluxUpWatts: null,
      sizingNotes: [],
      skipRadiator: false,
    };
  }

  const qRad = Math.max(0, qFull - ufhW);
  /** @type {string[]} */
  const sizingNotes = [];

  if (qRad <= 0) {
    sizingNotes.push(
      `Віддача ТП ≈${Math.round(ufhW)} Вт покриває розрахункове навантаження ≈${Math.round(qFull)} Вт — радіатор не потрібен.`,
    );
    return {
      qRad: 0,
      designWattsFull: qFull,
      ufhHeatFluxUpWatts: ufhW,
      sizingNotes,
      skipRadiator: true,
    };
  }

  sizingNotes.push(
    `З урахуванням ТП (≈${Math.round(ufhW)} Вт): залишкове навантаження на радіатор ≈${Math.round(qRad)} Вт (з ≈${Math.round(qFull)} Вт).`,
  );

  return {
    qRad,
    designWattsFull: qFull,
    ufhHeatFluxUpWatts: ufhW,
    sizingNotes,
    skipRadiator: false,
  };
}

/**
 * Назначение: Pass 2 — подбор при forced kind с эскалацией.
 * Описание: без flip типа; высота/Вт → multi-unit → max + warning дефицита.
 */

import {
  adjustedRadiatorWatts,
  parsePanelHeightMm,
  pickPanelSkuForRoom,
  underwindowHeightWarning,
} from '../radiatorSizingHelpers.js';
import {
  applyWindowWidthRulesSectional,
  sortSectionalByEscalationPower,
} from './exploreRoomEmitterKind.js';

/**
 * @typedef {object} ForcedEmitterSized
 * @property {'section' | 'panel'} kind
 * @property {import('../../catalog/types.js').RadiatorCatalogItemNormalized} radiator
 * @property {number | null} sections
 * @property {number | null} sectionsThermalMin
 * @property {number} adjustedWatts
 * @property {number | null} radiatorWidthMm
 * @property {number | null} widthCoverageRatio
 * @property {boolean | null} widthOk
 * @property {string[]} sizingNotes
 * @property {number | null} panelLengthMm
 * @property {number} unitsCount
 * @property {boolean} underpowered
 * @property {number} deficitWatts
 */

/**
 * @param {object} args
 * @param {number} args.qRad
 * @param {'sectional' | 'panel'} args.forcedKind
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} args.sectionalPool
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} args.panelPoolFiltered
 * @param {50 | 70} args.baseDeltaT
 * @param {number} args.targetDeltaT
 * @param {number | null | undefined} [args.windowOpeningWidthMm]
 * @param {number | null | undefined} [args.openingHeightMm]
 * @param {number} args.ventilationReserveFactor
 * @param {import('../../dhw/types.js').RadiatorEmitterKindRules} args.emitterKindRules
 * @returns {ForcedEmitterSized | null}
 */
export function sizeForcedRoomEmitter(args) {
  const { forcedKind } = args;
  if (forcedKind === 'panel') {
    return sizeForcedPanel(args);
  }
  return sizeForcedSectional(args);
}

/**
 * @param {{
 *   qRad: number;
 *   sectionalPool: import('../../catalog/types.js').RadiatorCatalogItemNormalized[];
 *   baseDeltaT: 50 | 70;
 *   targetDeltaT: number;
 *   windowOpeningWidthMm?: number | null | undefined;
 *   openingHeightMm?: number | null | undefined;
 *   ventilationReserveFactor: number;
 *   emitterKindRules: import('../../dhw/types.js').RadiatorEmitterKindRules;
 * }} args
 * @returns {ForcedEmitterSized | null}
 */
function sizeForcedSectional(args) {
  const {
    qRad,
    sectionalPool,
    baseDeltaT,
    targetDeltaT,
    windowOpeningWidthMm,
    openingHeightMm,
    ventilationReserveFactor,
    emitterKindRules,
  } = args;

  if (!sectionalPool.length || qRad <= 0) return null;

  const {
    maxSectionsBeforeMultiUnit,
    maxUnitsPerRoom,
    maxSectionsHeuristic,
    sectionalCandidatesPerRoom,
  } = emitterKindRules;

  /** @type {ForcedEmitterSized | null} */
  let bestCovering = null;
  /** @type {ForcedEmitterSized | null} */
  let bestAny = null;

  const ranked = sortSectionalByEscalationPower(
    sectionalPool.slice(0, Math.max(sectionalCandidatesPerRoom * 2, 24)),
    baseDeltaT,
    targetDeltaT,
  );

  for (let unitsCount = 1; unitsCount <= maxUnitsPerRoom; unitsCount += 1) {
    const qPerUnit = qRad / unitsCount;
    for (const radiator of ranked) {
      const adjustedWatts = adjustedRadiatorWatts(radiator, baseDeltaT, targetDeltaT);
      if (adjustedWatts <= 0) continue;

      const sectionsThermalMin = Math.ceil(qPerUnit / adjustedWatts);
      const sectionWidthMm =
        radiator.sectionWidthMm ?? radiator.dimensions?.width ?? null;

      // Окно: доля ширины на один прибор при multi-unit
      const windowSlotMm =
        windowOpeningWidthMm != null && unitsCount > 1
          ? windowOpeningWidthMm / unitsCount
          : windowOpeningWidthMm;

      const win = applyWindowWidthRulesSectional({
        sections: sectionsThermalMin,
        sectionWidthMm,
        windowOpeningWidthMm: windowSlotMm ?? null,
        ventilationReserveFactor,
        maxSectionsHeuristic,
      });

      if (win.sections == null || win.sections > maxSectionsHeuristic) continue;

      const deliverablePerUnit = adjustedWatts * win.sections;
      const deliverableTotal = deliverablePerUnit * unitsCount;
      const underpowered = deliverableTotal + 1e-6 < qRad;
      const deficitWatts = underpowered
        ? Math.max(0, Math.round(qRad - deliverableTotal))
        : 0;

      const radiatorHeightMm = radiator.dimensions?.height ?? null;
      const hWarn = underwindowHeightWarning(openingHeightMm ?? null, radiatorHeightMm);
      /** @type {string[]} */
      const sizingNotes = [...win.sizingNotes];
      if (unitsCount > 1) {
        sizingNotes.push(
          `Ескалація: ${unitsCount} секційних приладів у приміщенні `
            + `(навантаження ≈${Math.round(qPerUnit)} Вт на прилад).`,
        );
      }
      if (windowOpeningWidthMm == null) {
        sizingNotes.push(
          'Глуха кімната (немає віконного прорізу) — правило ≥70% ширини вікна не застосовується.',
        );
      }
      if (hWarn) sizingNotes.push(hWarn);

      /** @type {ForcedEmitterSized} */
      const candidate = {
        kind: 'section',
        radiator,
        sections: win.sections,
        sectionsThermalMin,
        adjustedWatts,
        radiatorWidthMm:
          win.radiatorWidthMm != null ? win.radiatorWidthMm * unitsCount : null,
        widthCoverageRatio:
          windowOpeningWidthMm != null && win.radiatorWidthMm != null
            ? (win.radiatorWidthMm * unitsCount) / windowOpeningWidthMm
            : win.widthCoverageRatio,
        widthOk:
          windowOpeningWidthMm != null && win.radiatorWidthMm != null
            ? (win.radiatorWidthMm * unitsCount) / windowOpeningWidthMm >= 0.7
            : win.widthOk,
        sizingNotes,
        panelLengthMm: null,
        unitsCount,
        underpowered,
        deficitWatts,
      };

      if (!bestAny || scoreCandidate(candidate, qRad) > scoreCandidate(bestAny, qRad)) {
        bestAny = candidate;
      }

      const sectionsOk =
        win.sections <= maxSectionsBeforeMultiUnit
        || unitsCount > 1
        || !underpowered;
      if (!underpowered && sectionsOk) {
        if (
          !bestCovering
          || scoreCovering(candidate) > scoreCovering(bestCovering)
        ) {
          bestCovering = candidate;
        }
      }
    }

    // После unitsCount=1 без покрытия — пробуем multi-unit
    if (bestCovering && bestCovering.unitsCount === 1 && !bestCovering.underpowered) {
      break;
    }
  }

  const chosen = bestCovering ?? bestAny;
  if (!chosen) return null;

  if (chosen.underpowered) {
    chosen.sizingNotes.push(
      `Секційний радіатор не покриває 100% тепловтрат при lock типу. `
        + `Нестача: ${chosen.deficitWatts} Вт.`,
    );
  }

  return chosen;
}

/**
 * @param {{
 *   qRad: number;
 *   panelPoolFiltered: import('../../catalog/types.js').RadiatorCatalogItemNormalized[];
 *   baseDeltaT: 50 | 70;
 *   targetDeltaT: number;
 *   windowOpeningWidthMm?: number | null | undefined;
 *   openingHeightMm?: number | null | undefined;
 *   emitterKindRules: import('../../dhw/types.js').RadiatorEmitterKindRules;
 * }} args
 * @returns {ForcedEmitterSized | null}
 */
function sizeForcedPanel(args) {
  const {
    qRad,
    panelPoolFiltered,
    baseDeltaT,
    targetDeltaT,
    windowOpeningWidthMm,
    openingHeightMm,
    emitterKindRules,
  } = args;

  if (!panelPoolFiltered.length || qRad <= 0) return null;

  const { maxUnitsPerRoom } = emitterKindRules;

  /** @type {ForcedEmitterSized | null} */
  let bestCovering = null;
  /** @type {ForcedEmitterSized | null} */
  let bestAny = null;

  for (let unitsCount = 1; unitsCount <= maxUnitsPerRoom; unitsCount += 1) {
    const qPerUnit = qRad / unitsCount;
    const windowSlotMm =
      windowOpeningWidthMm != null && unitsCount > 1
        ? windowOpeningWidthMm / unitsCount
        : windowOpeningWidthMm;

    const panelPick = pickPanelSkuForRoom(
      qPerUnit,
      panelPoolFiltered,
      baseDeltaT,
      targetDeltaT,
      windowSlotMm ?? null,
    );
    if (!panelPick) continue;

    const panelLengthMm = panelPick.panelLengthMm;
    const radiatorHeightMm =
      parsePanelHeightMm(panelPick.radiator.model)
      ?? panelPick.radiator.dimensions?.height
      ?? null;
    const totalLength =
      panelLengthMm != null ? panelLengthMm * unitsCount : null;
    const widthCoverageRatio =
      windowOpeningWidthMm != null && totalLength != null
        ? totalLength / windowOpeningWidthMm
        : null;
    const widthOk =
      widthCoverageRatio != null ? widthCoverageRatio >= 0.7 : null;

    const deliverableTotal = panelPick.adjustedWatts * unitsCount;
    const underpowered = deliverableTotal + 1e-6 < qRad;
    const deficitWatts = underpowered
      ? Math.max(0, Math.round(qRad - deliverableTotal))
      : 0;

    /** @type {string[]} */
    const sizingNotes = [];
    if (unitsCount > 1) {
      sizingNotes.push(
        `Ескалація: ${unitsCount} панельних приладів у приміщенні `
          + `(навантаження ≈${Math.round(qPerUnit)} Вт на прилад).`,
      );
    }
    if (windowOpeningWidthMm == null) {
      sizingNotes.push(
        'Глуха кімната (немає віконного прорізу) — правило ≥70% ширини вікна не застосовується.',
      );
    } else if (panelPick.windowLengthFilterApplied === false && widthOk === false) {
      sizingNotes.push(
        'Панель обрана за тепловою потужністю, але сумарно не закриває ≥70% ширини вікна.',
      );
    }
    if (panelPick.underpowered || underpowered) {
      sizingNotes.push(
        `Панельний радіатор не покриває 100% тепловтрат при lock типу. `
          + `Нестача: ${deficitWatts} Вт.`,
      );
    }
    const hWarn = underwindowHeightWarning(openingHeightMm ?? null, radiatorHeightMm);
    if (hWarn) sizingNotes.push(hWarn);

    /** @type {ForcedEmitterSized} */
    const candidate = {
      kind: 'panel',
      radiator: panelPick.radiator,
      sections: null,
      sectionsThermalMin: null,
      adjustedWatts: panelPick.adjustedWatts,
      radiatorWidthMm: totalLength,
      widthCoverageRatio,
      widthOk,
      sizingNotes,
      panelLengthMm,
      unitsCount,
      underpowered: underpowered || Boolean(panelPick.underpowered),
      deficitWatts,
    };

    if (!bestAny || scoreCandidate(candidate, qRad) > scoreCandidate(bestAny, qRad)) {
      bestAny = candidate;
    }
    if (!underpowered && !panelPick.underpowered) {
      if (!bestCovering || scoreCovering(candidate) > scoreCovering(bestCovering)) {
        bestCovering = candidate;
      }
      if (unitsCount === 1) break;
    }
  }

  return bestCovering ?? bestAny;
}

/**
 * @param {ForcedEmitterSized} c
 * @param {number} qRad
 */
function scoreCandidate(c, qRad) {
  const deliverable =
    c.kind === 'panel'
      ? c.adjustedWatts * c.unitsCount
      : c.adjustedWatts * (c.sections ?? 0) * c.unitsCount;
  const cover = Math.min(deliverable, qRad);
  const widthBonus = c.widthOk === true ? 50_000 : 0;
  const multiPenalty = (c.unitsCount - 1) * 100;
  return cover * 10 + widthBonus - multiPenalty - c.deficitWatts;
}

/**
 * @param {ForcedEmitterSized} c
 */
function scoreCovering(c) {
  const widthBonus = c.widthOk === true ? 1000 : 0;
  const multiPenalty = (c.unitsCount - 1) * 100;
  const sectionsPenalty =
    c.kind === 'section' && c.sections != null ? c.sections : 0;
  return widthBonus - multiPenalty - sectionsPenalty;
}

/**
 * Минимальный прибор при forced kind (входные зоны).
 * @param {object} args
 * @param {'sectional' | 'panel'} args.forcedKind
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} args.sectionalPool
 * @param {import('../../catalog/types.js').RadiatorCatalogItemNormalized[]} args.panelPoolFiltered
 * @param {50 | 70} args.baseDeltaT
 * @param {number} args.targetDeltaT
 * @param {number | null} [args.windowOpeningWidthMm]
 * @param {number | null} [args.openingHeightMm]
 * @returns {ForcedEmitterSized | null}
 */
export function pickMinimumViableForcedKind(args) {
  const {
    forcedKind,
    sectionalPool,
    panelPoolFiltered,
    baseDeltaT,
    targetDeltaT,
    windowOpeningWidthMm,
    openingHeightMm,
  } = args;

  if (forcedKind === 'panel') {
    const panelPick =
      panelPoolFiltered.length > 0
        ? pickPanelSkuForRoom(
          1,
          panelPoolFiltered,
          baseDeltaT,
          targetDeltaT,
          windowOpeningWidthMm ?? null,
        )
        : null;
    if (!panelPick) return null;
    const panelLengthMm = panelPick.panelLengthMm;
    const radiatorHeightMm =
      parsePanelHeightMm(panelPick.radiator.model)
      ?? panelPick.radiator.dimensions?.height
      ?? null;
    const hWarn = underwindowHeightWarning(openingHeightMm ?? null, radiatorHeightMm);
    /** @type {string[]} */
    const sizingNotes = [
      'Мінімальний прилад: панель найменшої довжини з каталогу (вхідна зона, forced panel).',
    ];
    if (hWarn) sizingNotes.push(hWarn);
    return {
      kind: 'panel',
      radiator: panelPick.radiator,
      sections: null,
      sectionsThermalMin: null,
      adjustedWatts: panelPick.adjustedWatts,
      radiatorWidthMm: panelLengthMm,
      widthCoverageRatio:
        windowOpeningWidthMm != null && panelLengthMm != null
          ? panelLengthMm / windowOpeningWidthMm
          : null,
      widthOk:
        windowOpeningWidthMm != null && panelLengthMm != null
          ? panelLengthMm / windowOpeningWidthMm >= 0.7
          : null,
      sizingNotes,
      panelLengthMm,
      unitsCount: 1,
      underpowered: false,
      deficitWatts: 0,
    };
  }

  /** @type {{ radiator: import('../../catalog/types.js').RadiatorCatalogItemNormalized, adjustedWatts: number } | null} */
  let smallest = null;
  for (const r of sectionalPool.slice(0, 16)) {
    const adjustedWatts = adjustedRadiatorWatts(r, baseDeltaT, targetDeltaT);
    if (adjustedWatts <= 0) continue;
    if (!smallest || adjustedWatts < smallest.adjustedWatts) {
      smallest = { radiator: r, adjustedWatts };
    }
  }
  if (!smallest) return null;

  const sectionWidthMm =
    smallest.radiator.sectionWidthMm
    ?? smallest.radiator.dimensions?.width
    ?? null;
  const sections = 1;
  const radiatorWidthMm =
    sectionWidthMm != null ? sections * sectionWidthMm : null;
  const radiatorHeightMm = smallest.radiator.dimensions?.height ?? null;
  const hWarn = underwindowHeightWarning(openingHeightMm ?? null, radiatorHeightMm);
  /** @type {string[]} */
  const sizingNotes = [
    `Мінімальний прилад: 1 секція ${smallest.radiator.model} `
      + `(≈${Math.round(smallest.adjustedWatts)} Вт; forced sectional).`,
  ];
  if (hWarn) sizingNotes.push(hWarn);

  return {
    kind: 'section',
    radiator: smallest.radiator,
    sections,
    sectionsThermalMin: 1,
    adjustedWatts: smallest.adjustedWatts,
    radiatorWidthMm,
    widthCoverageRatio:
      radiatorWidthMm != null && windowOpeningWidthMm != null
        ? radiatorWidthMm / windowOpeningWidthMm
        : null,
    widthOk:
      radiatorWidthMm != null && windowOpeningWidthMm != null
        ? radiatorWidthMm / windowOpeningWidthMm >= 0.7
        : null,
    sizingNotes,
    panelLengthMm: null,
    unitsCount: 1,
    underpowered: false,
    deficitWatts: 0,
  };
}

/**
 * Назначение: агрегат приборов радиаторного подбора (панели vs секции).
 * Описание: totalSections = только sectionalSections; панели считаются отдельно.
 */

/**
 * @returns {import('../../types/shared-types.js').RadiatorsEmittersSummary}
 */
export function emptyRadiatorsEmittersSummary() {
  return {
    panelUnits: 0,
    sectionalUnits: 0,
    sectionalSections: 0,
    totalDeliverableWatts: 0,
    roomsWithEmitter: 0,
    roomsSkipped: 0,
  };
}

/**
 * Агрегація byRoom → emittersSummary.
 * @param {import('../../types/shared-types.js').RadiatorsByRoomItem[] | undefined | null} byRoom
 * @returns {import('../../types/shared-types.js').RadiatorsEmittersSummary}
 */
export function summarizeRadiatorEmitters(byRoom) {
  const summary = emptyRadiatorsEmittersSummary();
  for (const row of byRoom ?? []) {
    const kind = resolveDisplayKind(row);

    if (kind === 'none') {
      summary.roomsSkipped += 1;
      continue;
    }

    summary.roomsWithEmitter += 1;
    const deliverable =
      typeof row.deliverableWatts === 'number' && Number.isFinite(row.deliverableWatts)
        ? row.deliverableWatts
        : 0;
    summary.totalDeliverableWatts += deliverable;

    if (kind === 'panel') {
      const units =
        typeof row.unitsCount === 'number' && Number.isFinite(row.unitsCount)
          ? Math.max(1, Math.trunc(row.unitsCount))
          : 1;
      summary.panelUnits += units;
      continue;
    }

    if (typeof row.sections === 'number' && Number.isFinite(row.sections)) {
      const units =
        typeof row.unitsCount === 'number' && Number.isFinite(row.unitsCount)
          ? Math.max(1, Math.trunc(row.unitsCount))
          : 1;
      summary.sectionalUnits += units;
      summary.sectionalSections += Math.trunc(row.sections) * units;
    }
  }

  summary.totalDeliverableWatts = Math.round(summary.totalDeliverableWatts);
  return summary;
}

/**
 * Порівняння byRoom ліній economy / efficient по кімнатах.
 * @param {import('../../types/shared-types.js').RadiatorsByRoomItem[] | undefined | null} economyByRoom
 * @param {import('../../types/shared-types.js').RadiatorsByRoomItem[] | undefined | null} efficientByRoom
 * @returns {import('../../types/shared-types.js').RadiatorsRoomEmitterDiff[]}
 */
export function buildRadiatorRoomEmitterDiffs(economyByRoom, efficientByRoom) {
  /** @type {Map<string, import('../../types/shared-types.js').RadiatorsByRoomItem>} */
  const ecoMap = new Map();
  for (const row of economyByRoom ?? []) {
    if (row?.roomId) ecoMap.set(row.roomId, row);
  }
  /** @type {Map<string, import('../../types/shared-types.js').RadiatorsByRoomItem>} */
  const effMap = new Map();
  for (const row of efficientByRoom ?? []) {
    if (row?.roomId) effMap.set(row.roomId, row);
  }

  const roomIds = new Set([...ecoMap.keys(), ...effMap.keys()]);
  /** @type {import('../../types/shared-types.js').RadiatorsRoomEmitterDiff[]} */
  const diffs = [];

  for (const roomId of roomIds) {
    const eco = ecoMap.get(roomId);
    const eff = effMap.get(roomId);
    const roomName = eco?.roomName ?? eff?.roomName ?? roomId;
    const ecoKind = resolveDisplayKind(eco);
    const effKind = resolveDisplayKind(eff);
    const equipmentKindChanged = ecoKind !== effKind;

    diffs.push({
      roomId,
      roomName,
      equipmentKindChanged,
      economyDisplayKind: ecoKind,
      efficientDisplayKind: effKind,
      economyModel: eco?.radiatorModel && eco.radiatorModel !== '—' ? eco.radiatorModel : null,
      efficientModel: eff?.radiatorModel && eff.radiatorModel !== '—' ? eff.radiatorModel : null,
      economySections: typeof eco?.sections === 'number' ? eco.sections : null,
      efficientSections: typeof eff?.sections === 'number' ? eff.sections : null,
      economyPanelLengthMm:
        typeof eco?.panelLengthMm === 'number' ? eco.panelLengthMm : null,
      efficientPanelLengthMm:
        typeof eff?.panelLengthMm === 'number' ? eff.panelLengthMm : null,
      economyDeliverableWatts:
        typeof eco?.deliverableWatts === 'number' ? eco.deliverableWatts : null,
      efficientDeliverableWatts:
        typeof eff?.deliverableWatts === 'number' ? eff.deliverableWatts : null,
    });
  }

  return diffs.sort((a, b) => a.roomId.localeCompare(b.roomId));
}

/**
 * @param {import('../../types/shared-types.js').RadiatorsByRoomItem | undefined} row
 * @returns {'sectional' | 'panel' | 'none'}
 */
function resolveDisplayKind(row) {
  if (!row) return 'none';
  if (row.displayKind === 'sectional' || row.displayKind === 'panel' || row.displayKind === 'none') {
    return row.displayKind;
  }
  if (!row.radiatorModel || row.radiatorModel === '—') return 'none';
  if (row.priceBasis === 'panel') return 'panel';
  if (row.priceBasis === 'section') return 'sectional';
  return typeof row.sections === 'number' ? 'sectional' : 'none';
}

/**
 * Назначение: адаптер T повітря для підбору унібокса (обгортка shared SSOT).
 * Опис: не дублює константи — делегує shared/roomDesignAirTemp.js.
 */

import {
  BATHROOM_DESIGN_AIR_TEMP_FLOOR_C,
  SMALL_ZONE_ROOM_TYPES,
  resolveDesignRoomAirTempC,
  isSmallZoneRoomType,
} from '../../../../shared/roomDesignAirTemp.js';

/** @deprecated використовуйте SMALL_ZONE_ROOM_TYPES з shared */
export const UNIBOX_SMALL_ZONE_ROOM_TYPES = SMALL_ZONE_ROOM_TYPES;

/**
 * Сумісність зі старим API (санузел → підлога 24).
 * Нова семантика: max(bathroomAirTempC ?? insideC, 24), не «завжди 24».
 * @type {Readonly<Record<string, number>>}
 */
export const UNIBOX_ROOM_AIR_TEMP_PRESETS_C = Object.freeze({
  санузел: BATHROOM_DESIGN_AIR_TEMP_FLOOR_C,
});

/**
 * @typedef {import('../../types/shared-types.js').UniboxRoomAirTempSource} UniboxRoomAirTempSource
 */

/**
 * @typedef {object} UniboxRoomAirTempResolved
 * @property {number} roomAirTempC
 * @property {UniboxRoomAirTempSource} roomAirTempSource
 */

/**
 * Резолв T повітря для унібокса.
 *
 * @param {string | undefined | null} roomType
 * @param {number} surveyInsideC
 * @param {number | undefined | null} [bathroomAirTempC]
 * @returns {UniboxRoomAirTempResolved | null}
 */
export function resolveUniboxRoomAirTempC(roomType, surveyInsideC, bathroomAirTempC) {
  const resolved = resolveDesignRoomAirTempC({
    ...(roomType !== undefined ? { roomType } : {}),
    insideC: surveyInsideC,
    ...(bathroomAirTempC !== undefined ? { bathroomAirTempC } : {}),
  });
  if (!resolved) return null;

  /** @type {'preset' | 'survey' | 'bathroom_field' | 'floor'} */
  let roomAirTempSource = 'survey';
  if (resolved.source === 'floor' || resolved.source === 'bathroom_field') {
    roomAirTempSource = resolved.source;
  } else if (
    String(roomType ?? '')
      .trim()
      .toLowerCase() === 'санузел' &&
    resolved.designAirTempC === BATHROOM_DESIGN_AIR_TEMP_FLOOR_C &&
    Number(surveyInsideC) < BATHROOM_DESIGN_AIR_TEMP_FLOOR_C
  ) {
    roomAirTempSource = 'floor';
  } else if (resolved.source === 'survey') {
    roomAirTempSource = 'survey';
  }

  // Сумісність з H.16b: «preset» = спрацювала підлога/поле санузла
  if (roomAirTempSource === 'floor' || roomAirTempSource === 'bathroom_field') {
    return {
      roomAirTempC: resolved.designAirTempC,
      roomAirTempSource:
        roomAirTempSource === 'bathroom_field' ? 'bathroom_field' : 'preset',
    };
  }

  return {
    roomAirTempC: resolved.designAirTempC,
    roomAirTempSource: 'survey',
  };
}

export { isSmallZoneRoomType as isUniboxSmallZoneRoomType };

/**
 * Назначение: підбір колекторів з каталогу для смети.
 * Опис: ТП/радіаторні (manifolds) і котельні (boilerManifolds) за числом контурів,
 * призначенням і потужністю; відмінності house / apartment.
 */

import { logger } from '../utils/logger.js';

/** Макс. петель ТП на один колекторний вузол (бізнес-ліміт, не max каталогу). */
export const UFH_MANIFOLD_MAX_OUTLETS_PER_NODE = 12;

/** Критичний внутрішній збій підбору колекторів. */
export const MANIFOLD_FAILURE_CODE_INTERNAL = /** @type {const} */ ('MANIFOLD_INTERNAL');

/** Критичний збій через некоректні вхідні дані. */
export const MANIFOLD_FAILURE_CODE_INPUT = /** @type {const} */ ('MANIFOLD_INPUT_INVALID');

/**
 * Порожній звіт колекторів при soft-fail (ok: false).
 * Інваріант: underfloor=[], radiator/boilerManifold=null — унібокси не бачать каскад.
 *
 * @param {object} args
 * @param {import('../types/shared-types.js').ManifoldsMatchingFailureCode} args.failureCode
 * @param {string} args.message - людськочитабельний підсумок для warnings
 * @param {string} [args.causeMessage] - коротка причина без stack
 * @returns {import('../types/shared-types.js').ManifoldsMatchingReport}
 */
export function buildEmptyManifoldsFailure({ failureCode, message, causeMessage }) {
  const code =
    failureCode === MANIFOLD_FAILURE_CODE_INPUT
      ? MANIFOLD_FAILURE_CODE_INPUT
      : MANIFOLD_FAILURE_CODE_INTERNAL;
  const summary =
    typeof message === 'string' && message.trim()
      ? message.trim()
      : 'Кошторис колекторів порожній; розрахунок унібоксів і гідравліки продовжується.';
  /** @type {string[]} */
  const warnings = [`Колектори: підбір не виконано (${code}). ${summary}`];
  if (typeof causeMessage === 'string' && causeMessage.trim()) {
    warnings.push(`Причина: ${causeMessage.trim()}`);
  }
  return {
    ok: false,
    failureCode: code,
    underfloor: [],
    radiator: null,
    boilerManifold: null,
    warnings,
  };
}

/**
 * Штатний звіт колекторів (ok: true). Дефіцит SKU (selected=null) — не soft-fail.
 *
 * @param {object} args
 * @param {import('../types/shared-types.js').ManifoldUnderfloorPick[]} args.underfloor
 * @param {import('../types/shared-types.js').ManifoldRadiatorPick | null} args.radiator
 * @param {import('../types/shared-types.js').BoilerManifoldPick | null} args.boilerManifold
 * @param {string[]} args.warnings
 * @returns {import('../types/shared-types.js').ManifoldsMatchingReport}
 */
export function buildOkManifoldsReport({
  underfloor = [],
  radiator = null,
  boilerManifold = null,
  warnings = [],
}) {
  return {
    ok: true,
    underfloor,
    radiator,
    boilerManifold,
    warnings,
  };
}

/**
 * Обгортка core→звіт з catch (для verify ін'єкції throw без публічного _testThrow).
 * Лог: MANIFOLD_INPUT_INVALID — лише code/message (без stack);
 * MANIFOLD_INTERNAL — з Error (повний stack).
 *
 * @param {(args: object) => import('../types/shared-types.js').ManifoldsMatchingReport} core
 * @param {object} [args]
 * @returns {import('../types/shared-types.js').ManifoldsMatchingReport}
 */
export function pickManifoldsWithCore(core, args = {}) {
  try {
    return core(args);
  } catch (err) {
    const known =
      err && typeof err === 'object'
        ? /** @type {import('../types/shared-types.js').AppErrorLike & { message?: string }} */ (err)
        : null;
    const failureCode =
      known?.code === MANIFOLD_FAILURE_CODE_INPUT
        ? MANIFOLD_FAILURE_CODE_INPUT
        : MANIFOLD_FAILURE_CODE_INTERNAL;
    const errMessage = known?.message ? String(known.message) : null;
    const payload = {
      code: failureCode,
      message: errMessage,
    };
    if (failureCode === MANIFOLD_FAILURE_CODE_INTERNAL) {
      logger.warn('matching.manifold.fail', null, payload, err);
    } else {
      logger.warn('matching.manifold.fail', null, payload);
    }
    return buildEmptyManifoldsFailure({
      failureCode,
      message:
        'Кошторис колекторів порожній; розрахунок унібоксів і гідравліки продовжується.',
      ...(errMessage ? { causeMessage: errMessage } : {}),
    });
  }
}

/**
 * Рівномірний поділ петель на частини ≤ maxPerNode (каскад колекторів).
 * Приклади: 14 → [7,7]; 13 → [7,6]; 25 → [9,8,8].
 *
 * @param {number} total
 * @param {number} [maxPerNode=UFH_MANIFOLD_MAX_OUTLETS_PER_NODE]
 * @returns {number[]}
 */
export function splitOutletsForCascade(
  total,
  maxPerNode = UFH_MANIFOLD_MAX_OUTLETS_PER_NODE,
) {
  const n = Math.max(0, Math.floor(Number(total) || 0));
  const max = Math.max(1, Math.floor(Number(maxPerNode) || UFH_MANIFOLD_MAX_OUTLETS_PER_NODE));
  if (n <= 0) return [];
  if (n <= max) return [n];

  const units = Math.ceil(n / max);
  const base = Math.floor(n / units);
  const rem = n % units;
  /** @type {number[]} */
  const parts = [];
  for (let i = 0; i < units; i += 1) {
    parts.push(base + (i < rem ? 1 : 0));
  }
  return parts;
}

/**
 * Текст попередження про автокаскад ТП-колекторів.
 *
 * @param {number} unitCount
 * @param {number[]} parts
 * @returns {string}
 */
function buildUfhCascadeWarning(unitCount, parts) {
  const splitLabel = parts.join('+');
  return (
    `Перевищено ліміт петель на один вузол (max ${UFH_MANIFOLD_MAX_OUTLETS_PER_NODE}). `
    + `Систему автоматично розділено на ${unitCount} колектори (${splitLabel}).`
  );
}

/**
 * Підбір розподільного колектора (ТП або радіатори).
 *
 * @param {object} args
 * @param {import('../catalog/types.js').NormalizedCatalog | undefined} args.catalog
 * @param {'radiator' | 'underfloor'} args.application
 * @param {number} args.requiredOutlets
 * @returns {{
 *   selected: import('../catalog/types.js').ManifoldCatalogItemNormalized | null,
 *   warnings: string[],
 * }}
 */
export function pickDistributionManifold({ catalog, application, requiredOutlets }) {
  const need = Math.max(0, Math.floor(Number(requiredOutlets) || 0));
  /** @type {import('../catalog/types.js').ManifoldCatalogItemNormalized[]} */
  const pool = (catalog?.manifolds ?? []).filter(
    (m) => m.manifoldApplication === application,
  );

  if (need <= 0) {
    return { selected: null, warnings: [] };
  }

  if (!pool.length) {
    logger.warn('matching.manifold.emptyCatalog', null, { application, requiredOutlets: need });
    return {
      selected: null,
      warnings: [
        application === 'underfloor'
          ? 'У каталозі немає колекторів для теплої підлоги.'
          : 'У каталозі немає колекторів для радіаторного контуру.',
      ],
    };
  }

  /** @type {import('../catalog/types.js').ManifoldCatalogItemNormalized[]} */
  const fitting = pool.filter((m) => m.outletsCount >= need);
  /** @type {string[]} */
  const warnings = [];

  if (fitting.length) {
    fitting.sort((a, b) => {
      if (application === 'underfloor' && a.hasFlowMeters !== b.hasFlowMeters) {
        return a.hasFlowMeters ? -1 : 1;
      }
      if (a.outletsCount !== b.outletsCount) return a.outletsCount - b.outletsCount;
      return a.price - b.price;
    });
    return { selected: fitting[0] ?? null, warnings };
  }

  const fallback = [...pool].sort((a, b) => {
    if (b.outletsCount !== a.outletsCount) return b.outletsCount - a.outletsCount;
    return a.price - b.price;
  })[0];
  if (!fallback) {
    return { selected: null, warnings: ['У каталозі немає підходящих колекторів.'] };
  }
  warnings.push(
    `Підібрано колектор ${fallback.model} (${fallback.outletsCount} вих.) при потребі ${need} — обмеження каталогу.`,
  );
  return { selected: fallback, warnings };
}

/**
 * @param {object} args
 * @param {import('../catalog/types.js').NormalizedCatalog | undefined} args.catalog
 * @param {number} args.requiredCircuits
 * @param {number} args.requiredPowerKw
 * @returns {{
 *   selected: import('../catalog/types.js').BoilerManifoldCatalogItemNormalized | null,
 *   warnings: string[],
 * }}
 */
export function pickBoilerManifold({ catalog, requiredCircuits, requiredPowerKw }) {
  const needCircuits = Math.max(0, Math.floor(Number(requiredCircuits) || 0));
  const needKw = Math.max(0, Number(requiredPowerKw) || 0);
  /** @type {import('../catalog/types.js').BoilerManifoldCatalogItemNormalized[]} */
  const pool = catalog?.boilerManifolds ?? [];

  if (needCircuits <= 0) {
    return { selected: null, warnings: [] };
  }

  if (!pool.length) {
    logger.warn('matching.boilerManifold.emptyCatalog', null, {
      requiredCircuits: needCircuits,
      requiredPowerKw: needKw,
    });
    return {
      selected: null,
      warnings: ['У каталозі немає котельних колекторів.'],
    };
  }

  /** @type {import('../catalog/types.js').BoilerManifoldCatalogItemNormalized[]} */
  const fitting = pool.filter(
    (m) => m.circuitsCount >= needCircuits && m.maxPowerKw >= needKw,
  );
  /** @type {string[]} */
  const warnings = [];

  if (fitting.length) {
    fitting.sort((a, b) => {
      if (a.circuitsCount !== b.circuitsCount) return a.circuitsCount - b.circuitsCount;
      if (a.maxPowerKw !== b.maxPowerKw) return a.maxPowerKw - b.maxPowerKw;
      return a.price - b.price;
    });
    return { selected: fitting[0] ?? null, warnings };
  }

  const fallback = [...pool].sort((a, b) => {
    if (b.circuitsCount !== a.circuitsCount) return b.circuitsCount - a.circuitsCount;
    if (b.maxPowerKw !== a.maxPowerKw) return b.maxPowerKw - a.maxPowerKw;
    return a.price - b.price;
  })[0];
  if (!fallback) {
    return { selected: null, warnings: ['У каталозі немає підходящих котельних колекторів.'] };
  }

  /** @type {string[]} */
  const parts = [];
  if (fallback.circuitsCount < needCircuits) {
    parts.push(`контурів ${fallback.circuitsCount} < ${needCircuits}`);
  }
  if (fallback.maxPowerKw < needKw) {
    parts.push(`макс. ${fallback.maxPowerKw} кВт < ${needKw} кВт`);
  }
  logger.warn('matching.boilerManifold.fallbackApplied', null, {
    requestedCircuits: needCircuits,
    requestedPowerKw: needKw,
    selectedModel: fallback.model,
    selectedCircuits: fallback.circuitsCount,
    selectedPowerKw: fallback.maxPowerKw,
    deficits: parts,
  });
  warnings.push(
    `Підібрано котельний колектор ${fallback.model} з дефіцитом (${parts.join('; ') || 'обмеження каталогу'}).`,
  );
  return { selected: fallback, warnings };
}

/**
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @returns {Map<string, number>}
 */
function roomFloorById(building) {
  /** @type {Map<string, number>} */
  const map = new Map();
  for (const room of building?.rooms ?? []) {
    if (room?.id) map.set(room.id, Number(room.floor) || 1);
  }
  return map;
}

/**
 * Число петель ТП у кімнаті звіту.
 * @param {import('../types/shared-types.js').UnderfloorHeatingRoomReport} room
 * @returns {number}
 */
function roomLoopsCount(room) {
  if (typeof room.loopsCount === 'number' && room.loopsCount > 0) {
    return Math.floor(room.loopsCount);
  }
  if (Array.isArray(room.loops) && room.loops.length > 0) {
    return room.loops.length;
  }
  return 0;
}

/**
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} underfloorHeating
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @returns {Map<number, number>}
 */
/**
 * Терминал петли комнаты ТП (из отчёта или анкеты building).
 * @param {import('../types/shared-types.js').UnderfloorHeatingRoomReport} room
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @returns {'collector' | 'unibox'}
 */
function roomUfhTerminalControl(room, building) {
  if (room.ufhTerminalControl === 'unibox') return 'unibox';
  if (room.ufhTerminalControl === 'collector') return 'collector';
  const id = String(room.roomId ?? '');
  for (const r of building?.rooms ?? []) {
    if (String(r?.id) !== id) continue;
    if (r.underfloorHeating?.ufhTerminalControl === 'unibox') return 'unibox';
    break;
  }
  return 'collector';
}

/**
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} underfloorHeating
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @returns {Map<number, number>}
 */
function underfloorOutletsByFloor(underfloorHeating, building) {
  /** @type {Map<number, number>} */
  const byFloor = new Map();
  const floors = roomFloorById(building);
  for (const room of underfloorHeating?.rooms ?? []) {
    if (roomUfhTerminalControl(room, building) === 'unibox') continue;
    const loops = roomLoopsCount(room);
    if (loops <= 0) continue;
    const floor = floors.get(room.roomId) ?? 1;
    byFloor.set(floor, (byFloor.get(floor) ?? 0) + loops);
  }
  return byFloor;
}

/**
 * @param {import('../types/shared-types.js').RadiatorsMatchingReport | undefined} radiators
 * @returns {number}
 */
function radiatorOutletNeed(radiators) {
  let n = 0;
  for (const row of radiators?.byRoom ?? []) {
    if ((row.radiatorDesignWatts ?? 0) > 0) n += 1;
  }
  return n;
}

/**
 * Чи потрібен котельний колектор (лише house).
 * @param {object} args
 * @param {'apartment' | 'house'} args.objectType
 * @param {import('../types/shared-types.js').UfhDistributionPreset | undefined} args.distributionPreset
 * @param {boolean} args.hasRadiatorZone
 * @param {boolean} args.hasUfhZone
 * @returns {boolean}
 */
function needsBoilerManifold({
  objectType,
  distributionPreset,
  hasRadiatorZone,
  hasUfhZone,
}) {
  if (objectType !== 'house') return false;
  if (distributionPreset === 'hydraulic_separator') return true;
  return hasRadiatorZone && hasUfhZone;
}

/**
 * Ядро підбору колекторів (без catch). При критичній помилці може кинути;
 * публічний pickManifolds завжди ловить і повертає ok: false.
 *
 * @param {object} args
 * @param {import('../catalog/types.js').NormalizedCatalog} [args.catalog]
 * @param {import('../types/shared-types.js').BuildingInput | undefined} [args.building]
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} [args.underfloorHeating]
 * @param {import('../types/shared-types.js').RadiatorsMatchingReport | undefined} [args.radiators]
 * @param {import('../types/shared-types.js').BoilerMatchingReport | undefined} [args.boiler]
 * @param {import('../types/shared-types.js').HydraulicsSurveyInput | undefined} [args.hydraulics]
 * @returns {import('../types/shared-types.js').ManifoldsMatchingReport}
 */
export function pickManifoldsCore({
  catalog,
  building,
  underfloorHeating = null,
  radiators,
  boiler,
  hydraulics,
} = {}) {
  const objectMetaType = building?.objectMeta?.objectType;
  const objectType =
    objectMetaType === 'apartment' || objectMetaType === 'house'
      ? objectMetaType
      : 'house';

  /** @type {string[]} */
  const warnings = [];

  logger.info('matching.manifold.start', null, {
    objectType,
    distributionPreset: underfloorHeating?.distributionPreset ?? null,
    wiring: hydraulics?.radiatorWiringSystemType ?? null,
  });

  /** @type {import('../types/shared-types.js').ManifoldUnderfloorPick[]} */
  const underfloor = [];
  const outletsByFloor = underfloorOutletsByFloor(underfloorHeating, building);
  for (const floor of [...outletsByFloor.keys()].sort((a, b) => a - b)) {
    const requiredOutlets = outletsByFloor.get(floor) ?? 0;
    const parts = splitOutletsForCascade(requiredOutlets);
    /** @type {import('../types/shared-types.js').ManifoldUnderfloorUnitPick[]} */
    const units = [];
    /** @type {string[]} */
    const floorWarnings = [];

    if (parts.length > 1) {
      const cascadeMsg = buildUfhCascadeWarning(parts.length, parts);
      floorWarnings.push(cascadeMsg);
      warnings.push(cascadeMsg);
    }

    for (let i = 0; i < parts.length; i += 1) {
      const partNeed = parts[i];
      if (partNeed == null) continue;
      const pick = pickDistributionManifold({
        catalog,
        application: 'underfloor',
        requiredOutlets: partNeed,
      });
      floorWarnings.push(...pick.warnings);
      warnings.push(...pick.warnings);
      units.push({
        index: i + 1,
        requiredOutlets: partNeed,
        selected: pick.selected,
        warnings: pick.warnings,
      });
    }

    underfloor.push({
      floor,
      requiredOutlets,
      units,
      warnings: floorWarnings,
    });
  }

  /** @type {import('../types/shared-types.js').ManifoldRadiatorPick | null} */
  let radiator = null;
  if (hydraulics?.radiatorWiringSystemType === 'manifold') {
    const requiredOutlets = radiatorOutletNeed(radiators);
    const pick = pickDistributionManifold({
      catalog,
      application: 'radiator',
      requiredOutlets,
    });
    warnings.push(...pick.warnings);
    radiator = {
      requiredOutlets,
      selected: pick.selected,
      warnings: pick.warnings,
    };
  }

  const hasRadiatorZone = radiatorOutletNeed(radiators) > 0;
  const hasUfhZone = outletsByFloor.size > 0;
  const distributionPreset = underfloorHeating?.distributionPreset;
  const wantBoiler = needsBoilerManifold({
    objectType,
    distributionPreset,
    hasRadiatorZone,
    hasUfhZone,
  });

  /** @type {import('../types/shared-types.js').BoilerManifoldPick | null} */
  let boilerManifold = null;
  if (wantBoiler) {
    const requiredCircuits = (hasRadiatorZone ? 1 : 0) + (hasUfhZone ? 1 : 0);
    const requiredPowerKw = Number(boiler?.requiredKw) || 0;
    const pick = pickBoilerManifold({
      catalog,
      requiredCircuits: Math.max(requiredCircuits, 1),
      requiredPowerKw,
    });
    warnings.push(...pick.warnings);
    boilerManifold = {
      requiredCircuits: Math.max(requiredCircuits, 1),
      requiredPowerKw,
      selected: pick.selected,
      warnings: pick.warnings,
    };
  }

  logger.info('matching.manifold.done', null, {
    ok: true,
    underfloorFloors: underfloor.length,
    underfloorUnits: underfloor.reduce((s, f) => s + f.units.length, 0),
    radiatorSelected: radiator?.selected?.model ?? null,
    boilerManifoldSelected: boilerManifold?.selected?.model ?? null,
    warnings: warnings.length,
  });

  return buildOkManifoldsReport({
    underfloor,
    radiator,
    boilerManifold,
    warnings,
  });
}

/**
 * Оркестратор підбору колекторів після резолву distributionPreset ТП.
 * Ніколи не кидає назовні: критичний збій → ok: false + порожні структури.
 *
 * @param {object} [args]
 * @param {import('../catalog/types.js').NormalizedCatalog} [args.catalog]
 * @param {import('../types/shared-types.js').BuildingInput | undefined} [args.building]
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} [args.underfloorHeating]
 * @param {import('../types/shared-types.js').RadiatorsMatchingReport | undefined} [args.radiators]
 * @param {import('../types/shared-types.js').BoilerMatchingReport | undefined} [args.boiler]
 * @param {import('../types/shared-types.js').HydraulicsSurveyInput | undefined} [args.hydraulics]
 * @returns {import('../types/shared-types.js').ManifoldsMatchingReport}
 */
export function pickManifolds(args = {}) {
  return pickManifoldsWithCore(pickManifoldsCore, args);
}

/**
 * Назначение: вспомогательные функции подбора радиаторов.
 * Описание: различение панельных и секционных моделей, парсинг габаритов, пересчёт паспортной
 * мощности секции под реальный график (adjustOutputWatts) и правила под окном.
 */
const MIN_UNDERWINDOW_CLEARANCE_MM = 100;

/**
 * @param {import('../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @returns {boolean}
 */
export function isPanelRadiator(r) {
  return r?.priceBasis === 'panel';
}

/**
 * @param {import('../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @returns {boolean}
 */
export function isSectionalRadiator(r) {
  return r?.priceBasis !== 'panel';
}

/**
 * Длина панели по строке модели «500x1000» / «500×1000» (мм).
 * @param {string | undefined} model
 * @returns {number | null}
 */
export function parsePanelLengthMm(model) {
  const m = String(model ?? '');
  const match = m.match(/(\d{3,4})\s*[x×]\s*(\d{3,4})/i);
  if (!match) return null;
  const len = Number(match[2]);
  return Number.isFinite(len) && len > 0 ? len : null;
}

/**
 * Высота панели по строке модели (мм).
 * @param {string | undefined} model
 * @returns {number | null}
 */
export function parsePanelHeightMm(model) {
  const m = String(model ?? '');
  const match = m.match(/(\d{3,4})\s*[x×]\s*(\d{3,4})/i);
  if (!match) return null;
  const h = Number(match[1]);
  return Number.isFinite(h) && h > 0 ? h : null;
}

/**
 * @param {import('../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @returns {'side' | 'bottom' | null}
 */
export function inferPanelConnection(r) {
  const m = String(r?.model ?? '').toLowerCase();
  if (/\bvkp\b/i.test(m)) return 'bottom';
  if (/\b\d{2}k\b/i.test(m) || /klasik/i.test(m)) return 'side';
  return null;
}

/**
 * @param {import('../catalog/types.js').RadiatorCatalogItemNormalized[]} panelPool
 * @param {'side' | 'bottom' | undefined} radiatorConnection
 */
export function filterPanelsByConnection(panelPool, radiatorConnection) {
  if (!radiatorConnection) return [...panelPool];
  return panelPool.filter((p) => {
    const c = inferPanelConnection(p);
    if (c == null) return true;
    return c === radiatorConnection;
  });
}

/**
 * Перерахунок потужності до графіка (спільна формула для pickRadiatorsCore і verifyRadiatorSections).
 * @param {object} p
 * @param {number} p.baseWatts
 * @param {50 | 70} p.baseDeltaT
 * @param {number} p.targetDeltaT
 * @param {number} [p.exponent]
 * @returns {number}
 */
export function adjustOutputWatts({
  baseWatts,
  baseDeltaT,
  targetDeltaT,
  exponent = 1.3,
}) {
  if (targetDeltaT <= 0 || baseDeltaT <= 0) return 0;
  return baseWatts * (targetDeltaT / baseDeltaT) ** exponent;
}

/**
 * @param {import('../catalog/types.js').RadiatorCatalogItemNormalized} r
 * @param {50 | 70} baseDeltaT
 * @param {number} targetDeltaT
 */
export function adjustedRadiatorWatts(r, baseDeltaT, targetDeltaT) {
  const baseWatts =
    baseDeltaT === 70 ? r.outputWatts.deltaT70 : r.outputWatts.deltaT50;
  return adjustOutputWatts({ baseWatts, baseDeltaT, targetDeltaT });
}

/**
 * Минимальная панель из каталога (по длине), покрывающая нагрузку.
 * При заданном окне сначала ищет панели с length ≥ 70% openingWidth, затем fallback без этого фильтра.
 *
 * @param {number} qRad
 * @param {import('../catalog/types.js').RadiatorCatalogItemNormalized[]} panelPool
 * @param {50 | 70} baseDeltaT
 * @param {number} targetDeltaT
 * @param {number | null} [windowOpeningWidthMm]
 * @returns {{
 *   radiator: import('../catalog/types.js').RadiatorCatalogItemNormalized,
 *   adjustedWatts: number,
 *   panelLengthMm: number,
 *   underpowered?: boolean,
 *   windowLengthFilterApplied?: boolean,
 * } | null}
 */
export function pickPanelSkuForRoom(
  qRad,
  panelPool,
  baseDeltaT,
  targetDeltaT,
  windowOpeningWidthMm = null,
) {
  if (!panelPool.length || qRad <= 0) return null;

  const withLength = panelPool
    .map((r) => {
      const panelLengthMm = parsePanelLengthMm(r.model);
      const adjustedWatts = adjustedRadiatorWatts(r, baseDeltaT, targetDeltaT);
      return { r, panelLengthMm, adjustedWatts };
    })
    .flatMap((x) =>
      x.panelLengthMm != null && x.adjustedWatts > 0
        ? [{ r: x.r, panelLengthMm: x.panelLengthMm, adjustedWatts: x.adjustedWatts }]
        : [],
    )
    .sort((a, b) => a.panelLengthMm - b.panelLengthMm);

  if (!withLength.length) return null;

  const minLengthMm =
    typeof windowOpeningWidthMm === 'number'
    && Number.isFinite(windowOpeningWidthMm)
    && windowOpeningWidthMm > 0
      ? 0.7 * windowOpeningWidthMm
      : null;

  /**
   * @param {typeof withLength} pool
   * @returns {(typeof withLength)[number] | undefined}
   */
  const firstCovering = (pool) => pool.find((x) => x.adjustedWatts >= qRad);

  if (minLengthMm != null) {
    const windowOkPool = withLength.filter((x) => x.panelLengthMm >= minLengthMm);
    const fitWindow = firstCovering(windowOkPool);
    if (fitWindow) {
      return {
        radiator: fitWindow.r,
        adjustedWatts: fitWindow.adjustedWatts,
        panelLengthMm: fitWindow.panelLengthMm,
        windowLengthFilterApplied: true,
      };
    }
  }

  const fit = firstCovering(withLength);
  if (fit) {
    return {
      radiator: fit.r,
      adjustedWatts: fit.adjustedWatts,
      panelLengthMm: fit.panelLengthMm,
      windowLengthFilterApplied: false,
    };
  }

  const largest = withLength[withLength.length - 1];
  if (!largest) return null;
  return {
    radiator: largest.r,
    adjustedWatts: largest.adjustedWatts,
    panelLengthMm: largest.panelLengthMm,
    underpowered: true,
    windowLengthFilterApplied: false,
  };
}

/**
 * Проверка зазора под подоконником (упрощённо: высота прибора vs высота окна).
 * @param {number | null} openingHeightMm
 * @param {number | null} radiatorHeightMm
 * @returns {string | null}
 */
export function underwindowHeightWarning(openingHeightMm, radiatorHeightMm) {
  if (
    openingHeightMm == null
    || radiatorHeightMm == null
    || !Number.isFinite(openingHeightMm)
    || !Number.isFinite(radiatorHeightMm)
  ) {
    return null;
  }
  const maxRadiatorH = openingHeightMm - 2 * MIN_UNDERWINDOW_CLEARANCE_MM;
  if (maxRadiatorH <= 0) return null;
  if (radiatorHeightMm <= maxRadiatorH) return null;
  return (
    `Высота прибора ${Math.round(radiatorHeightMm)} мм превышает допустимую под окном ` +
    `≈${Math.round(maxRadiatorH)} мм (зазор ${MIN_UNDERWINDOW_CLEARANCE_MM} мм снизу и сверху от высоты окна ` +
    `${Math.round(openingHeightMm)} мм).`
  );
}

/**
 * Назначение: подбор радиаторов с линиями proposal.
 * Описание: primary Two-Pass → единый resolvedEmitterKind для economy/efficient.
 */
import { applyThermalRegimePresetToHeatingSystem } from '../logic/heatingThermalRegimes.js';
import { pickRadiators } from './internal/pickRadiatorsCore.js';
import {
  buildRadiatorRoomEmitterDiffs,
  emptyRadiatorsEmittersSummary,
  summarizeRadiatorEmitters,
} from './internal/summarizeRadiatorEmitters.js';

/**
 * @param {import('../types/shared-types.js').HeatingSystemInput} baseHeatingSystem
 * @param {'economy' | 'efficient'} tier
 * @returns {import('../types/shared-types.js').HeatingSystemInput}
 */
function heatingSystemSnapshotForRadiatorTier(baseHeatingSystem, tier) {
  /** @type {import('../types/shared-types.js').HeatingThermalRegimePreset} */
  const preset =
    tier === 'economy' ? 'traditional_dt50_75_65' : 'condensing_dt30_55_45';
  const hs = structuredClone(baseHeatingSystem ?? {});
  applyThermalRegimePresetToHeatingSystem(hs, preset);
  return hs;
}

/**
 * @param {import('../types/shared-types.js').RadiatorsMatchingReport} tierReport
 * @param {'economy' | 'efficient'} tier
 * @param {import('../types/boiler-types.js').BoilerEquipmentProposal} boilerProposal
 * @returns {import('../types/shared-types.js').RadiatorsProposalLineReport}
 */
function wrapRadiatorProposalLine(tierReport, tier, boilerProposal) {
  const emittersSummary =
    tierReport.emittersSummary ?? summarizeRadiatorEmitters(tierReport.byRoom);
  return {
    tier,
    boilerModel: boilerProposal.model ?? null,
    chosen: tierReport.chosen,
    byRoom: tierReport.byRoom,
    ...(tierReport.inputs != null ? { inputs: tierReport.inputs } : {}),
    warnings: tierReport.warnings,
    ...(tierReport.radiatorSelectionNotes != null
      ? { radiatorSelectionNotes: tierReport.radiatorSelectionNotes }
      : {}),
    emittersSummary,
    totalSections:
      emittersSummary.sectionalUnits > 0 || emittersSummary.panelUnits > 0
        ? emittersSummary.sectionalSections
        : null,
    resolvedEmitterKind: tierReport.resolvedEmitterKind ?? null,
    ...(tierReport.emitterKindVotes != null
      ? { emitterKindVotes: tierReport.emitterKindVotes }
      : {}),
    ...(tierReport.emitterKindDecisionNotes != null
      ? { emitterKindDecisionNotes: tierReport.emitterKindDecisionNotes }
      : {}),
  };
}

/**
 * @param {'economy' | 'efficient'} tier
 * @param {string} unavailableReason
 * @returns {import('../types/shared-types.js').RadiatorsProposalLineReport}
 */
function unavailableRadiatorProposalLine(tier, unavailableReason) {
  return {
    tier,
    boilerModel: null,
    chosen: null,
    byRoom: [],
    warnings: unavailableReason ? [unavailableReason] : [],
    unavailableReason,
    emittersSummary: emptyRadiatorsEmittersSummary(),
    totalSections: null,
    resolvedEmitterKind: null,
  };
}

/**
 * Підбір радіаторів: основна лінія + «Економ» / «Ефективний» з одним kind на объект.
 *
 * @param {object} args
 * @param {import('../types/shared-types.js').HeatLossReport} args.roomsHeatLoss
 * @param {import('../types/shared-types.js').HeatingSystemInput} [args.heatingSystem]
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @param {import('../types/shared-types.js').BuildingInput | null} [args.building]
 * @param {import('../types/boiler-types.js').BoilerMatchingReport} args.boiler
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null} [args.underfloorHeating]
 * @param {import('../types/shared-types.js').HydraulicsSurveyInput | undefined} [args.hydraulics]
 * @param {import('../dhw/types.js').RadiatorApplianceRules | null | undefined} [args.radiatorRules]
 * @param {import('../recommendations/types.js').RecommendationsBundle | null | undefined} [args.recommendations]
 * @returns {import('../types/shared-types.js').RadiatorsMatchingReport}
 */
export function pickRadiatorsWithProposalLines({
  roomsHeatLoss,
  heatingSystem = {},
  catalog,
  building = null,
  boiler,
  underfloorHeating = null,
  hydraulics,
  radiatorRules = null,
  recommendations = null,
}) {
  const deltaTSystemK = hydraulics?.deltaTSystemK;
  if (heatingSystem?.heatingEmittersMode === 'ufh_only') {
    const skipMsg =
      'Підбір радіаторів пропущено: обрано режим опалення лише теплою підлогою (heatingEmittersMode=ufh_only).';
    return {
      chosen: null,
      byRoom: [],
      emittersSummary: emptyRadiatorsEmittersSummary(),
      totalSections: null,
      skippedReason: /** @type {'ufh_only'} */ ('ufh_only'),
      roomEmitterDiffs: [],
      warnings: [skipMsg],
      radiatorSelectionNotes: [],
      resolvedEmitterKind: null,
      emitterKindVotes: { sectional: 0, panel: 0 },
      emitterKindDecisionNotes: [],
      lineEconomy: unavailableRadiatorProposalLine('economy', skipMsg),
      lineEfficient: unavailableRadiatorProposalLine('efficient', skipMsg),
    };
  }

  const primary = pickRadiators({
    roomsHeatLoss,
    heatingSystem,
    catalog,
    building,
    boilerMatching: boiler,
    underfloorHeating,
    deltaTSystemK,
    radiatorRules,
    recommendations,
  });

  const objectKind =
    primary.resolvedEmitterKind === 'sectional' || primary.resolvedEmitterKind === 'panel'
      ? primary.resolvedEmitterKind
      : null;

  /** @type {import('../types/shared-types.js').RadiatorsProposalLineReport} */
  let lineEconomy;
  if (boiler?.proposalEconomy) {
    const hsEco = heatingSystemSnapshotForRadiatorTier(heatingSystem, 'economy');
    const ecoReport = pickRadiators({
      roomsHeatLoss,
      heatingSystem: hsEco,
      catalog,
      building,
      boilerMatching: null,
      radiatorLineTier: 'economy',
      underfloorHeating,
      deltaTSystemK,
      radiatorRules,
      recommendations,
      forcedEmitterKind: objectKind,
    });
    lineEconomy = wrapRadiatorProposalLine(
      ecoReport,
      'economy',
      boiler.proposalEconomy,
    );
  } else {
    lineEconomy = unavailableRadiatorProposalLine(
      'economy',
      'Лінія «Економ» недоступна: у каталозі немає традиційних котлів для цієї схеми.',
    );
  }

  /** @type {import('../types/shared-types.js').RadiatorsProposalLineReport} */
  let lineEfficient;
  if (boiler?.proposalEfficient) {
    const hsEff = heatingSystemSnapshotForRadiatorTier(heatingSystem, 'efficient');
    const effReport = pickRadiators({
      roomsHeatLoss,
      heatingSystem: hsEff,
      catalog,
      building,
      boilerMatching: null,
      radiatorLineTier: 'efficient',
      underfloorHeating,
      deltaTSystemK,
      radiatorRules,
      recommendations,
      forcedEmitterKind: objectKind,
    });
    lineEfficient = wrapRadiatorProposalLine(
      effReport,
      'efficient',
      boiler.proposalEfficient,
    );
  } else {
    lineEfficient = unavailableRadiatorProposalLine(
      'efficient',
      'Лінія «Ефективний» недоступна: у каталозі немає конденсаційних котлів для цієї схеми.',
    );
  }

  const roomEmitterDiffs = buildRadiatorRoomEmitterDiffs(
    lineEconomy.byRoom,
    lineEfficient.byRoom,
  );

  /** @type {string[]} */
  const kindChangeWarnings = [];
  for (const diff of roomEmitterDiffs) {
    if (!diff.equipmentKindChanged) continue;
    kindChangeWarnings.push(
      `[${diff.roomName}] Тип приладу відрізняється між лініями «Економ» (${diff.economyDisplayKind}) `
        + `та «Ефективний» (${diff.efficientDisplayKind}) — порушення інваріанта єдиного kind.`,
    );
  }

  return {
    ...primary,
    roomEmitterDiffs,
    warnings: [...(primary.warnings ?? []), ...kindChangeWarnings],
    lineEconomy,
    lineEfficient,
  };
}

/**
 * Назначение: підбір унібоксів з каталогу для смети.
 * Опис: по одній позиції на петлю ТП; м'яке попередження від 4 петель; строгі нерівності за паспортом;
 * smart fallback T повітря за room.type (анкету не змінюємо).
 */

import { logger } from '../utils/logger.js';
import {
  resolveUniboxRoomAirTempC,
} from './internal/uniboxRoomAirPresets.js';

/**
 * @typedef {import('../catalog/types.js').UniboxCatalogItemNormalized} UniboxCatalogItemNormalized
 * @typedef {import('../types/shared-types.js').UniboxLoopDemand} UniboxLoopDemand
 * @typedef {import('../types/shared-types.js').UniboxesMatchingReport} UniboxesMatchingReport
 * @typedef {import('./internal/uniboxRoomAirPresets.js').UniboxRoomAirTempSource} UniboxRoomAirTempSource
 */

/** Розрахунковий робочий тиск закритої системи опалення, бар (PN-перевірка паспорта). */
export const UNIBOX_DESIGN_PRESSURE_BAR = 3;

/** Макс. Δp на клапані унібокса для оцінки мін. Kv, бар. */
export const UNIBOX_VALVE_MAX_DP_BAR = 0.25;

/** Унібокс — локальний регулятор; м'яке попередження від цього числа петель (включно). */
export const UNIBOX_MAX_LOOPS_FOR_MATCHING = 4;

/** Підключення петлі ТП (PEX) у цьому сервісі — євроконус. */
export const UNIBOX_REQUIRED_FIT = /** @type {const} */ ('eurocone');

/**
 * Мін. Kv (м³/ч) для витрати петлі при допустимому Δp на клапані.
 *
 * @param {number} flowLph
 * @param {number} [maxDpBar=UNIBOX_VALVE_MAX_DP_BAR]
 * @returns {number}
 */
export function minKvM3hForFlowLph(flowLph, maxDpBar = UNIBOX_VALVE_MAX_DP_BAR) {
  const q = Math.max(0, Number(flowLph) || 0) / 1000;
  const dp = Math.max(0.01, Number(maxDpBar) || UNIBOX_VALVE_MAX_DP_BAR);
  return q / Math.sqrt(dp);
}

/**
 * @param {UniboxCatalogItemNormalized['type']} type
 * @returns {number}
 */
function uniboxTypeRank(type) {
  switch (type) {
    case 'rtl_air':
      return 0;
    case 'rtl_afc':
      return 1;
    case 'rtl':
      return 2;
    case 'balancing_valve':
      return 3;
    case 'air_only':
      return 4;
    default:
      return 9;
  }
}

/**
 * Чи підходить унібокс під потребу петлі (строгі нерівності за паспортом).
 * Рівність на межі max/min паспорта → false.
 *
 * @param {UniboxCatalogItemNormalized} unibox
 * @param {UniboxLoopDemand} demand
 * @returns {boolean}
 */
export function uniboxFitsDemand(unibox, demand) {
  if (!(unibox.loopsCount >= 1)) return false;
  if (!(demand.loopLengthM > 0)) return false;
  if (!(demand.areaSqM < unibox.maxAreaSqM)) return false;
  if (!(demand.loopLengthM < unibox.maxLoopLengthM)) return false;
  if (!(demand.circuitSupplyC < unibox.maxTemperatureC)) return false;
  if (!(demand.systemPressureBar < unibox.maxPressureBar)) return false;
  if (!(demand.minKvM3h < unibox.kvM3h)) return false;
  if (unibox.connection?.fit !== demand.requiredFit) return false;

  if (typeof unibox.maxSupplyTempC === 'number') {
    if (!(demand.circuitSupplyC < unibox.maxSupplyTempC)) return false;
  }

  if (
    typeof unibox.minCoolantTempC === 'number' &&
    typeof unibox.maxCoolantTempC === 'number'
  ) {
    if (
      !(
        unibox.minCoolantTempC < demand.circuitReturnC &&
        demand.circuitReturnC < unibox.maxCoolantTempC
      )
    ) {
      return false;
    }
  }

  if (
    typeof unibox.minAirTempC === 'number' &&
    typeof unibox.maxAirTempC === 'number'
  ) {
    // roomAirTempC — лише T повітря приміщення (не теплоносій).
    if (
      !(
        unibox.minAirTempC < demand.roomAirTempC &&
        demand.roomAirTempC < unibox.maxAirTempC
      )
    ) {
      return false;
    }
  }

  if (typeof unibox.minFlowLph === 'number' && typeof unibox.maxFlowLph === 'number') {
    if (!(unibox.minFlowLph < demand.flowLph && demand.flowLph < unibox.maxFlowLph)) {
      return false;
    }
  }

  return true;
}

/**
 * Валідація demand петлі перед фільтром каталогу.
 *
 * @param {UniboxLoopDemand} demand
 * @param {{ roomId?: string, loopId?: string }} [meta]
 * @returns {{ ok: true } | { ok: false, code: string, message: string }}
 */
export function validateUniboxLoopDemand(demand, meta = {}) {
  const roomId = meta.roomId ? String(meta.roomId) : '';
  const loopId = meta.loopId ? String(meta.loopId) : '';
  const loc = [roomId && `кімната ${roomId}`, loopId && `петля ${loopId}`]
    .filter(Boolean)
    .join(', ');
  const prefix = loc ? `${loc}: ` : '';

  if (!(demand.loopLengthM > 0)) {
    return {
      ok: false,
      code: 'UNIBOX_LOOP_LENGTH',
      message: `${prefix}довжина петлі має бути > 0 м (зараз ${demand.loopLengthM}).`,
    };
  }
  if (!(demand.areaSqM > 0)) {
    return {
      ok: false,
      code: 'UNIBOX_AREA',
      message: `${prefix}площа зони має бути > 0 м² (зараз ${demand.areaSqM}).`,
    };
  }
  if (
    !Number.isFinite(demand.circuitSupplyC) ||
    !Number.isFinite(demand.circuitReturnC)
  ) {
    return {
      ok: false,
      code: 'UNIBOX_CIRCUIT_TEMP',
      message: `${prefix}температури подачі/звороту контуру ТП мають бути скінченними числами.`,
    };
  }
  if (!(demand.circuitReturnC < demand.circuitSupplyC)) {
    return {
      ok: false,
      code: 'UNIBOX_DT',
      message:
        `${prefix}зворот теплоносія (${demand.circuitReturnC} °C) має бути < подачі ` +
        `(${demand.circuitSupplyC} °C).`,
    };
  }
  if (!(demand.flowLph > 0)) {
    return {
      ok: false,
      code: 'UNIBOX_FLOW',
      message: `${prefix}витрата петлі має бути > 0 л/год (зараз ${demand.flowLph}).`,
    };
  }
  if (!Number.isFinite(demand.roomAirTempC)) {
    return {
      ok: false,
      code: 'UNIBOX_AIR_TEMP',
      message: `${prefix}розрахункова T повітря приміщення (roomAirTempC) має бути скінченним числом.`,
    };
  }
  if (demand.requiredFit !== UNIBOX_REQUIRED_FIT) {
    return {
      ok: false,
      code: 'UNIBOX_FIT',
      message:
        `${prefix}для ТП PEX потрібен fit=${UNIBOX_REQUIRED_FIT} ` +
        `(зараз ${String(demand.requiredFit)}).`,
    };
  }
  return { ok: true };
}

/**
 * @param {UniboxCatalogItemNormalized[]} pool
 * @param {UniboxLoopDemand} demand
 * @returns {UniboxCatalogItemNormalized | null}
 */
export function pickUniboxForDemand(pool, demand) {
  const fitting = pool.filter((unibox) => uniboxFitsDemand(unibox, demand));
  if (!fitting.length) return null;
  fitting.sort((a, b) => {
    const rankDiff = uniboxTypeRank(a.type) - uniboxTypeRank(b.type);
    if (rankDiff !== 0) return rankDiff;
    // Пріоритет G3/4 (типовий євроконус 16×2) над G1/2.
    /**
     * @param {UniboxCatalogItemNormalized} u
     * @returns {number}
     */
    const threadScore = (u) => (u.connection?.thread === 'G3/4' ? 0 : 1);
    const th = threadScore(a) - threadScore(b);
    if (th !== 0) return th;
    return a.price - b.price;
  });
  return fitting[0] ?? null;
}

/**
 * @param {Array<{ id?: string, type?: string }> | null | undefined} rooms
 * @returns {Map<string, string>}
 */
function buildRoomTypeById(rooms) {
  /** @type {Map<string, string>} */
  const map = new Map();
  for (const room of rooms ?? []) {
    const id = room?.id != null ? String(room.id) : '';
    if (!id) continue;
    map.set(id, String(room.type ?? '').trim().toLowerCase());
  }
  return map;
}

/**
 * Збирає потреби лише з реальних петель (loopLengthM > 0) кімнат з
 * ufhTerminalControl=unibox. Без fallback loopLengthM=0.
 * T повітря: пресет за room.type (санузел → 24 °C) або temps.insideC з анкети.
 *
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} underfloorHeating
 * @param {object} ctx
 * @param {number} [ctx.surveyInsideC] temps.insideC (T повітря за замовчуванням)
 * @param {number} [ctx.roomAirTempC] alias surveyInsideC (legacy)
 * @param {number | undefined | null} [ctx.bathroomAirTempC] temps.bathroomAirTempC
 * @param {number} [ctx.systemPressureBar]
 * @param {Array<{ id?: string, type?: string }> | null | undefined} [ctx.rooms]
 * @returns {Array<{ roomId: string, loopId: string, required: UniboxLoopDemand }>}
 */
export function collectUniboxLoopDemands(underfloorHeating, ctx) {
  const surveyInsideC = Number(ctx.surveyInsideC ?? ctx.roomAirTempC);
  const bathroomAirTempC =
    typeof ctx.bathroomAirTempC === 'number' && Number.isFinite(ctx.bathroomAirTempC)
      ? ctx.bathroomAirTempC
      : undefined;
  const systemPressureBar =
    typeof ctx.systemPressureBar === 'number' && Number.isFinite(ctx.systemPressureBar)
      ? ctx.systemPressureBar
      : UNIBOX_DESIGN_PRESSURE_BAR;
  const roomTypeById = buildRoomTypeById(ctx.rooms);

  /** @type {Array<{ roomId: string, loopId: string, required: UniboxLoopDemand }>} */
  const out = [];
  if (!Number.isFinite(surveyInsideC)) return out;

  for (const room of underfloorHeating?.rooms ?? []) {
    if (room.ufhTerminalControl !== 'unibox') continue;

    const roomId = String(room.roomId ?? '');
    const roomType = roomTypeById.get(roomId) || '';
    const airResolved = resolveUniboxRoomAirTempC(
      roomType || undefined,
      surveyInsideC,
      bathroomAirTempC,
    );
    if (!airResolved) continue;

    const areaSqM = Number(room.heatedAreaM2 ?? room.areaM2) || 0;
    const supplyC = Number(room.circuitSupplyC);
    const returnC = Number(room.circuitReturnC);
    if (!Number.isFinite(supplyC) || !Number.isFinite(returnC)) continue;

    const loops = Array.isArray(room.loops) ? room.loops : [];
    for (const loop of loops) {
      const loopLengthM = Number(loop.loopLengthM) || 0;
      if (loopLengthM <= 0) continue;
      const flowM3h = Number(loop.flowRateM3PerHour) || 0;
      const flowLph = flowM3h * 1000;

      /** @type {UniboxLoopDemand} */
      const required = {
        areaSqM,
        loopLengthM,
        circuitSupplyC: supplyC,
        circuitReturnC: returnC,
        flowLph,
        roomAirTempC: airResolved.roomAirTempC,
        roomAirTempSource: airResolved.roomAirTempSource,
        systemPressureBar,
        minKvM3h: minKvM3hForFlowLph(flowLph),
        requiredFit: UNIBOX_REQUIRED_FIT,
      };
      if (roomType) required.roomType = roomType;

      out.push({
        roomId,
        loopId: String(loop.loopId || `${roomId}-loop`),
        required,
      });
    }
  }
  return out;
}

/**
 * Чи є каскад ТП-колекторів (units > 1 на поверсі) — унібокси не підбираємо.
 * Сигнал з H.15 pickManifolds (не дублюємо splitOutletsForCascade).
 * manifolds.ok=false / порожній underfloor → не каскад (soft-fail колекторів).
 *
 * @param {import('../types/shared-types.js').ManifoldsMatchingReport | null | undefined} manifolds
 * @returns {boolean}
 */
export function hasUnderfloorManifoldCascade(manifolds) {
  for (const floor of manifolds?.underfloor ?? []) {
    if (floor == null || typeof floor !== 'object') continue;
    if ((floor.units?.length ?? 0) > 1) return true;
  }
  return false;
}

/**
 * Текст попередження, коли немає позиції під петлю.
 *
 * @param {string} loopId
 * @param {UniboxLoopDemand} required
 * @param {number} surveyInsideC
 * @returns {string}
 */
function buildNoMatchWarning(loopId, required, surveyInsideC) {
  let airSrc = `T повітря=${required.roomAirTempC} °C (анкета temps.insideC)`;
  if (required.roomAirTempSource === 'bathroom_field') {
    airSrc = `T повітря=${required.roomAirTempC} °C (temps.bathroomAirTempC)`;
  } else if (required.roomAirTempSource === 'preset') {
    airSrc =
      `T повітря=${required.roomAirTempC} °C (поверх 24 °C для «санузел»); ` +
      `анкета temps.insideC=${surveyInsideC} °C`;
  }
  const typePart = required.roomType ? `тип «${required.roomType}», ` : '';
  return (
    `Немає унібокса під петлю ${loopId} (${typePart}` +
    `площа ${required.areaSqM} м², довжина ${required.loopLengthM} м, ` +
    `подача ${required.circuitSupplyC} °C, зворот ${required.circuitReturnC} °C, ` +
    `${airSrc}, витрата ${required.flowLph} л/ч, ` +
    `P=${required.systemPressureBar} бар, Kv>${required.minKvM3h.toFixed(3)}, ` +
    `fit=${required.requiredFit}).`
  );
}

/**
 * Оркестратор підбору унібоксів після pickManifolds, до гідравліки.
 *
 * @param {object} args
 * @param {import('../catalog/types.js').NormalizedCatalog | undefined} args.catalog
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} args.underfloorHeating
 * @param {number} [args.roomAirTempC] temps.insideC (T повітря з анкети)
 * @param {number} [args.bathroomAirTempC] temps.bathroomAirTempC
 * @param {number} [args.systemPressureBar]
 * @param {import('../types/shared-types.js').ManifoldsMatchingReport | null | undefined} [args.manifolds]
 * @param {Array<{ id?: string, type?: string }> | null | undefined} [args.rooms] building.rooms для room.type
 * @returns {UniboxesMatchingReport}
 */
export function pickUniboxes({
  catalog,
  underfloorHeating = null,
  roomAirTempC,
  bathroomAirTempC,
  systemPressureBar,
  manifolds = null,
  rooms = null,
}) {
  /** @type {UniboxCatalogItemNormalized[]} */
  const pool = catalog?.uniboxes ?? [];
  /** @type {string[]} */
  const warnings = [];

  const surveyInsideC = Number(roomAirTempC);
  if (!Number.isFinite(surveyInsideC)) {
    logger.info('matching.unibox.skip', null, { reason: 'no_survey_inside_c' });
    return { byLoop: [], warnings: [] };
  }

  const bathAir =
    typeof bathroomAirTempC === 'number' && Number.isFinite(bathroomAirTempC)
      ? bathroomAirTempC
      : undefined;

  const demands = collectUniboxLoopDemands(underfloorHeating, {
    surveyInsideC,
    bathroomAirTempC: bathAir,
    systemPressureBar,
    rooms,
  });

  logger.info('matching.unibox.start', null, {
    catalogCount: pool.length,
    loopDemands: demands.length,
    surveyInsideC,
  });

  if (!demands.length) {
    logger.info('matching.unibox.done', null, { byLoop: 0, warnings: 0 });
    return { byLoop: [], warnings: [] };
  }

  // Soft-fail колекторів: underfloor=[] → каскаду немає; підбір петель триває.
  if (manifolds && manifolds.ok === false) {
    const codePart = manifolds.failureCode ? ` (${manifolds.failureCode})` : '';
    warnings.push(
      'Підбір унібоксів виконується без сигналу каскаду колекторів: '
        + `matching.manifolds.ok=false${codePart}.`,
    );
  }

  // Каскад колекторів стосується лише колекторної схеми; явні unibox-зони не блокуємо.
  // UNIBOX_MAX_LOOPS_FOR_MATCHING — м'яке попередження від 4 петель (не skip), бо вибір в анкеті явний.
  if (demands.length >= UNIBOX_MAX_LOOPS_FOR_MATCHING) {
    warnings.push(
      `Обрано ${demands.length} зон з унібоксом (орієнтир до ${UNIBOX_MAX_LOOPS_FOR_MATCHING}); ` +
        'перевірте гідравліку та доцільність локальних регуляторів.',
    );
  }

  if (!pool.length) {
    warnings.push('У каталозі немає унібоксів для підбору петель теплої підлоги.');
    const byLoop = demands.map((d) => ({
      roomId: d.roomId,
      loopId: d.loopId,
      required: d.required,
      selected: null,
      warnings: ['Немає позицій unibox у каталозі.'],
    }));
    logger.warn('matching.unibox.emptyCatalog', null, { loopDemands: demands.length });
    return { byLoop, warnings };
  }

  /** @type {import('../types/shared-types.js').UniboxLoopPick[]} */
  const byLoop = [];

  for (const demand of demands) {
    /** @type {string[]} */
    const rowWarnings = [];
    const validated = validateUniboxLoopDemand(demand.required, {
      roomId: demand.roomId,
      loopId: demand.loopId,
    });
    if (!validated.ok) {
      rowWarnings.push(validated.message);
      warnings.push(validated.message);
      byLoop.push({
        roomId: demand.roomId,
        loopId: demand.loopId,
        required: demand.required,
        selected: null,
        warnings: rowWarnings,
      });
      continue;
    }

    const selected = pickUniboxForDemand(pool, demand.required);
    if (!selected) {
      const msg = buildNoMatchWarning(demand.loopId, demand.required, surveyInsideC);
      rowWarnings.push(msg);
      warnings.push(msg);
    }
    byLoop.push({
      roomId: demand.roomId,
      loopId: demand.loopId,
      required: demand.required,
      selected,
      warnings: rowWarnings,
    });
  }

  logger.info('matching.unibox.done', null, {
    byLoop: byLoop.length,
    selected: byLoop.filter((r) => r.selected).length,
    warnings: warnings.length,
    airSamples: byLoop.map((r) => ({
      roomId: r.roomId,
      roomType: r.required.roomType ?? null,
      roomAirTempC: r.required.roomAirTempC,
      roomAirTempSource: r.required.roomAirTempSource ?? null,
      selectedId: r.selected?.id ?? null,
    })),
  });

  return { byLoop, warnings };
}

export {
  resolveUniboxRoomAirTempC,
  UNIBOX_ROOM_AIR_TEMP_PRESETS_C,
  UNIBOX_SMALL_ZONE_ROOM_TYPES,
  isUniboxSmallZoneRoomType,
} from './internal/uniboxRoomAirPresets.js';

/**
 * Назначение: пояснения и рекомендации по водяному тёплому полу.
 * Описание: matching-заметки и структурированные WARN/REC через recommendationResolver.
 */

import { pushRecommendation } from '../recommendations/recommendationResolver.js';

/** Финиши с лимитом материала 27 °C (деформация покрытия). */
const MATERIAL_LIMIT_FINISH_IDS = new Set([
  'pvc_glue',
  'pvc_click',
  'laminate_click',
]);

const SURFACE_TEMP_EPSILON_C = 0.05;
const SUGGESTED_MAX_PIPE_SPACING_MM = 200;
/** Порог q↓ (Вт/м²) для WARN паразитного потока — согласован с ufhParasiticDownTriggerWm2. */
const PARASITIC_DOWN_WARN_WM2 = 5;

/**
 * Текстовые подсказки для отчёта подбора, если в анкете отмечен водяной тёплый пол.
 *
 * @param {import('../types/shared-types.js').HeatingSystemInput | undefined | null} heatingSystem
 * @returns {string[]}
 */
export function buildWarmFloorMatchingNotes(heatingSystem) {
  if (!heatingSystem?.waterUnderfloorHeating) return [];
  return [
    'Зазначено водяну теплу підлогу: контур підлоги 45/35 °C (плитка) або 40/30 °C (ламінат/вініл) задається за фінішем кімнати. ' +
      'Якщо подача котла (75/65 або 55/45) вища за температуру контуру ТП — потрібен насосно-змішувальний вузол; ' +
      'за збігу температур (лише ТП) змішувач не потрібен.',
  ];
}

/**
 * Подсказки с расчётными цифрами ТП (warmFloorCalc).
 *
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} report
 * @returns {string[]}
 */
export function buildWarmFloorCalcMatchingNotes(report) {
  if (!report?.rooms?.length) return [];

  const notes = report.rooms.map((room) => {
    const finish = room.finishMaterialName ?? room.finishMaterialId ?? '—';
    const step = room.pipeSpacingMm ?? 150;
    return `ТП «${room.roomName}» (${finish}, крок ${step} мм): q↑≈${room.heatFluxUpWm2} Вт/м² (${room.heatFluxUpWatts} Вт), Tповерх≈${room.surfaceTempC} °C (ліміт ${room.maxSurfaceTemperatureCelsius} °C), Rфініш=${room.finishCoveringResistanceM2KW} м²·K/Вт.`;
  });

  if (report.totalHeatFluxUpWatts > 0) {
    notes.push(
      `Сумарна корисна віддача ТП вгору: ≈${report.totalHeatFluxUpWatts} Вт; паразитний потік униз: ≈${report.totalHeatFluxDownWatts} Вт (контур ${report.circuitSupplyC}/${report.circuitReturnC} °C).`,
    );
  }

  return notes;
}

/**
 * @param {import('../types/shared-types.js').UnderfloorHeatingRoomReport} room
 * @returns {Record<string, string | number | undefined>}
 */
function recommendationVarsForRoom(room) {
  const coveragePercent =
    typeof room.heatFluxCoverageRatio === 'number'
      ? Math.round(room.heatFluxCoverageRatio * 100)
      : undefined;

  return {
    roomName: room.roomName,
    surfaceTempC: room.surfaceTempC,
    maxTempC: room.maxSurfaceTemperatureCelsius,
    comfortMaxTempC: room.comfortMaxSurfaceTemperatureCelsius,
    finishName: room.finishMaterialName ?? room.finishMaterialId,
    circuitSupplyC: room.circuitSupplyC,
    circuitReturnC: room.circuitReturnC,
    heatFluxUpWm2: room.heatFluxUpWm2,
    heatFluxDownWm2: room.heatFluxDownWm2,
    heatFluxDownWatts: room.heatFluxDownWatts,
    maxAllowableHeatFluxUpWm2: room.maxAllowableHeatFluxUpWm2,
    pipeSpacingMm: room.pipeSpacingMm,
    requestedPipeSpacingMm: room.requestedPipeSpacingMm,
    resolvedPipeSpacingMm: room.resolvedPipeSpacingMm,
    suggestedPipeSpacingMm: SUGGESTED_MAX_PIPE_SPACING_MM,
    roomAreaM2: room.roomAreaM2,
    furnitureOccupiedAreaM2: room.furnitureOccupiedAreaM2,
    heatedAreaM2: room.heatedAreaM2,
    requiredHeatFluxUpWm2: room.requiredHeatFluxUpWm2,
    heatFluxUpWatts:
      typeof room.heatFluxUpWatts === 'number' && Number.isFinite(room.heatFluxUpWatts)
        ? Math.round(room.heatFluxUpWatts)
        : room.heatFluxUpWatts,
    roomHeatLossWatts:
      typeof room.roomHeatLossWatts === 'number' && Number.isFinite(room.roomHeatLossWatts)
        ? Math.round(room.roomHeatLossWatts)
        : room.roomHeatLossWatts,
    coveragePercent,
  };
}

/**
 * @param {import('../types/shared-types.js').UnderfloorHeatingRoomReport} room
 * @param {string[]} warnings
 * @param {import('../recommendations/types.js').ResolvedRecommendation[]} resolvedList
 * @param {import('../recommendations/types.js').RecommendationsBundle} recommendations
 * @param {string} code
 * @param {Record<string, string | number | undefined>} vars
 */
function pushUfhRecommendation(room, warnings, resolvedList, recommendations, code, vars) {
  const resolved = pushRecommendation(warnings, resolvedList, recommendations, code, vars);
  if (resolved?.category === 'warnings' && resolved.text) {
    room.warnings = [...(room.warnings ?? []), resolved.text];
  }
}

/**
 * Структурированные WARN/REC по перегреву поверхности; дополняет report на месте.
 *
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport | null | undefined} report
 * @param {import('../recommendations/types.js').RecommendationsBundle} recommendations
 * @param {{ heatingEmittersMode?: string | null }} [options]
 * @returns {{ warnings: string[], resolvedRecommendations: import('../recommendations/types.js').ResolvedRecommendation[] }}
 */
export function applyUnderfloorHeatingRecommendations(
  report,
  recommendations,
  options = {},
) {
  /** @type {string[]} */
  const warnings = [];
  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const resolvedRecommendations = [];

  if (!report?.rooms?.length) {
    return { warnings, resolvedRecommendations };
  }

  const isUfhOnly = options.heatingEmittersMode === 'ufh_only';

  for (const room of report.rooms) {
    const vars = recommendationVarsForRoom(room);

    if (room.activeAreaCheckStatus === 'zero_heated_area') {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_UFH_HEATED_AREA_ZERO',
        vars,
      );
    } else if (room.activeAreaCheckStatus === 'insufficient_active_area') {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        isUfhOnly
          ? 'WARN_UFH_ACTIVE_AREA_INSUFFICIENT_UFH_ONLY'
          : 'WARN_UFH_ACTIVE_AREA_INSUFFICIENT',
        vars,
      );
    }

    if (room.heatFluxCoverageStatus === 'low') {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        isUfhOnly ? 'WARN_UFH_COVERAGE_LOW_UFH_ONLY' : 'WARN_UFH_COVERAGE_LOW',
        vars,
      );
    }

    if (
      room.bottomBoundary === 'heated'
      && typeof room.heatFluxDownWm2 === 'number'
      && Number.isFinite(room.heatFluxDownWm2)
      && room.heatFluxDownWm2 > PARASITIC_DOWN_WARN_WM2
    ) {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_UFH_PARASITIC_DOWN_HEATED',
        vars,
      );
    }

    if (
      room.pipeSpacingResolution === 'tightened'
      && typeof room.requestedPipeSpacingMm === 'number'
      && typeof room.resolvedPipeSpacingMm === 'number'
      && room.requestedPipeSpacingMm !== room.resolvedPipeSpacingMm
    ) {
      pushRecommendation(
        warnings,
        resolvedRecommendations,
        recommendations,
        'REC_UFH_PIPE_SPACING_AUTO',
        vars,
      );
    }

    const presetMax = room.presetMaxSurfaceTemperatureCelsius;
    const finishMax = room.finishMaxSurfaceTemperatureCelsius;
    if (
      typeof presetMax === 'number'
      && Number.isFinite(presetMax)
      && typeof finishMax === 'number'
      && Number.isFinite(finishMax)
      && finishMax > presetMax
    ) {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        isUfhOnly
          ? 'WARN_UFH_SURFACE_TEMP_PRESET_OVERRIDE_UFH_ONLY'
          : 'WARN_UFH_SURFACE_TEMP_PRESET_OVERRIDE',
        {
          roomName: room.roomName,
          finishName: room.finishMaterialName ?? room.finishMaterialId,
          presetMaxTempC: presetMax,
          finishMaxTempC: finishMax,
        },
      );
    }

    const materialOverheat =
      MATERIAL_LIMIT_FINISH_IDS.has(room.finishMaterialId) &&
      (room.surfaceTempC >
        room.maxSurfaceTemperatureCelsius + SURFACE_TEMP_EPSILON_C
        || room.heatFluxUpLimitedBySurface === true);

    const comfortLimit = room.comfortMaxSurfaceTemperatureCelsius;
    const comfortOverheat =
      !MATERIAL_LIMIT_FINISH_IDS.has(room.finishMaterialId) &&
      typeof comfortLimit === 'number' &&
      Number.isFinite(comfortLimit) &&
      (room.surfaceTempC > comfortLimit + SURFACE_TEMP_EPSILON_C
        || room.heatFluxUpLimitedBySurface === true);

    if (materialOverheat) {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_FLOOR_OVERHEATING_MATERIAL',
        vars,
      );
      if (
        typeof room.pipeSpacingMm === 'number' &&
        room.pipeSpacingMm < SUGGESTED_MAX_PIPE_SPACING_MM
      ) {
        pushRecommendation(
          warnings,
          resolvedRecommendations,
          recommendations,
          'REC_UFH_ACTION_INCREASE_SPACING',
          vars,
        );
      }
      if (
        room.finishMaterialId === 'laminate_click' ||
        room.finishMaterialId === 'pvc_click'
      ) {
        pushRecommendation(
          warnings,
          resolvedRecommendations,
          recommendations,
          'REC_UFH_ACTION_CHANGE_FINISH',
          vars,
        );
      }
    } else if (comfortOverheat) {
      pushUfhRecommendation(
        room,
        warnings,
        resolvedRecommendations,
        recommendations,
        'WARN_FLOOR_OVERHEATING_COMFORT',
        {
          ...vars,
          maxTempC: comfortLimit,
        },
      );
      if (
        typeof room.pipeSpacingMm === 'number' &&
        room.pipeSpacingMm < SUGGESTED_MAX_PIPE_SPACING_MM
      ) {
        pushRecommendation(
          warnings,
          resolvedRecommendations,
          recommendations,
          'REC_UFH_ACTION_INCREASE_SPACING',
          vars,
        );
      }
    }
  }

  if (warnings.length > 0) {
    report.warnings = [...(report.warnings ?? []), ...warnings];
  }
  if (resolvedRecommendations.length > 0) {
    report.resolvedRecommendations = [
      ...(report.resolvedRecommendations ?? []),
      ...resolvedRecommendations,
    ];
  }

  return { warnings, resolvedRecommendations };
}

/**
 * REC/WARN по смесительному узлу и авто-схеме распределения (фаза 7).
 *
 * @param {import('../types/shared-types.js').UnderfloorHeatingReport} report
 * @param {object} ctx
 * @param {import('../types/shared-types.js').UfhDistributionPreset | undefined | null} ctx.requestedPreset
 * @param {Exclude<import('../types/shared-types.js').UfhDistributionPreset, 'auto'>} ctx.resolvedPreset
 * @param {number} ctx.minBoilerKw
 * @param {number | undefined} ctx.requiredBoilerKw
 * @param {import('../recommendations/types.js').RecommendationsBundle} recommendations
 */
export function applyUnderfloorMixingDistributionRecommendations(
  report,
  ctx,
  recommendations,
) {
  if (!report?.isMixingNodeRequired) return;

  /** @type {string[]} */
  const warnings = [];
  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const resolvedRecommendations = [];

  const mixing = report.mixingNode;
  const vars = {
    boilerSupplyC: mixing?.boilerSupplyC ?? report.circuitSupplyC,
    floorCircuitSupplyC: mixing?.floorCircuitSupplyC ?? report.circuitSupplyC,
    flowRateM3PerHour: mixing?.flowRateM3PerHour,
    headMetersMin: mixing?.headMetersMin,
    valveKvsMin: mixing?.valveKvsMin,
    distributionPreset: ctx.resolvedPreset,
    requiredBoilerKw: ctx.requiredBoilerKw,
    minBoilerKw: ctx.minBoilerKw,
  };

  pushRecommendation(
    warnings,
    resolvedRecommendations,
    recommendations,
    'WARN_UFH_MIXING_NODE_REQUIRED',
    vars,
  );

  if (
    (ctx.requestedPreset === 'auto' || ctx.requestedPreset == null) &&
    ctx.resolvedPreset === 'hydraulic_separator' &&
    typeof ctx.requiredBoilerKw === 'number' &&
    ctx.requiredBoilerKw > ctx.minBoilerKw
  ) {
    pushRecommendation(
      warnings,
      resolvedRecommendations,
      recommendations,
      'REC_UFH_HYDRAULIC_SEPARATOR_AUTO',
      vars,
    );
  }

  if (warnings.length > 0) {
    report.warnings = [...(report.warnings ?? []), ...warnings];
  }
  if (resolvedRecommendations.length > 0) {
    report.resolvedRecommendations = [
      ...(report.resolvedRecommendations ?? []),
      ...resolvedRecommendations,
    ];
  }
}

/**
 * Назначение: подбор электронакопительного водонагревателя.
 * Описание: выбор минимального достаточного объёма из каталога и минимальной цены при равном
 * объёме; при нехватке номенклатуры — максимально доступный вариант с предупреждением.
 */
import { buildMatchingSortPools } from '../catalog/matchingSortPools.js';
import { waterHeaterMaxVolumeLiters } from '../catalog/comparators.js';
import { logger } from '../utils/logger.js';

/**
 * Лучший вариант по потребности в литрах (минимальный объём среди ≥ need; иначе — максимальный у модели).
 * @param {import('../catalog/types.js').WaterHeaterCatalogItemNormalized} heater
 * @param {number} need
 */
function pickBestVariantForNeed(heater, need) {
  const variants = [...(heater.variants ?? [])].sort(
    (a, b) => a.volumeLiters - b.volumeLiters,
  );
  if (!variants.length) return null;
  if (need <= 0) return variants[0] ?? null;
  const ok = variants.find((v) => v.volumeLiters >= need);
  return ok ?? variants[variants.length - 1] ?? null;
}

/**
 * @param {object} args
 * @param {import('../types/shared-types.js').HotWaterReport} args.hotWater
 * @param {import('../catalog/types.js').NormalizedCatalog} args.catalog
 * @returns {import('../types/shared-types.js').WaterHeaterMatchingReport}
 */
export function pickWaterHeater({ hotWater, catalog }) {
  const sortPools = buildMatchingSortPools(catalog);
  const heaters = sortPools.waterHeatersSortedByMinVolume ?? [];
  if (!heaters.length) {
    logger.warn('matching.waterHeater.emptyCatalog', null);
    return {
      selected: null,
      chosenVariant: null,
      warnings: ['У каталозі немає водонагрівачів.'],
      requiredTankLiters: Number(hotWater?.recommendedTankLiters) || 0,
    };
  }

  const need = Number(hotWater?.recommendedTankLiters) || 0;
  logger.info('matching.waterHeater.start', null, { requiredTankLiters: need });

  /** @type {{ heater: import('../catalog/types.js').WaterHeaterCatalogItemNormalized; variant: import('../catalog/types.js').WaterHeaterVariantNormalized } | null} */
  let best = null;

  for (const h of heaters) {
    const maxCap = waterHeaterMaxVolumeLiters(h);
    if (need > 0 && maxCap < need) continue;

    const v = pickBestVariantForNeed(h, need);
    if (!v) continue;

    if (need > 0 && v.volumeLiters < need) continue;

    if (
      !best
      || v.volumeLiters < best.variant.volumeLiters
      || (
        v.volumeLiters === best.variant.volumeLiters
        && v.price < best.variant.price
      )
    ) {
      best = { heater: h, variant: v };
    }
  }

  const warnings = [];

  if (!best && heaters.length) {
    /** @type {{ heater: import('../catalog/types.js').WaterHeaterCatalogItemNormalized; variant: import('../catalog/types.js').WaterHeaterVariantNormalized } | null} */
    let largest = null;
    for (const h of heaters) {
      const vars = [...(h.variants ?? [])].sort(
        (a, b) => a.volumeLiters - b.volumeLiters,
      );
      const v = vars[vars.length - 1];
      if (!v) continue;
      if (
        !largest
        || v.volumeLiters > largest.variant.volumeLiters
        || (
          v.volumeLiters === largest.variant.volumeLiters
          && v.price < largest.variant.price
        )
      ) {
        largest = { heater: h, variant: v };
      }
    }
    best = largest;
    if (best && need > 0 && best.variant.volumeLiters < need) {
      warnings.push('Підібраний водонагрівач менший за розрахунковий об’єм (обмеження каталогу).');
    }
  }

  if (!best) {
    logger.info('matching.waterHeater.done', null, { selectedModel: null });
    return { selected: null, chosenVariant: null, warnings, requiredTankLiters: need };
  }

  /** @type {import('../types/shared-types.js').WaterHeaterChosenVariant} */
  const chosenVariant = {
    volumeLiters: best.variant.volumeLiters,
    price: best.variant.price,
    ...(best.variant.powerKw != null ? { powerKw: best.variant.powerKw } : {}),
    ...(best.variant.heatingTimeMinutes != null
      ? { heatingTimeMinutes: best.variant.heatingTimeMinutes }
      : {}),
  };

  logger.info('matching.waterHeater.done', null, {
    selectedModel: best.heater.model,
    chosenVolumeLiters: chosenVariant.volumeLiters,
    warnings: warnings.length,
  });

  return {
    selected: best.heater,
    chosenVariant,
    warnings,
    requiredTankLiters: need,
  };
}

/**
 * Назначение: HTML-документ финансовой сметы для серверного PDF.
 * Описание: таблица commercial + карточки proposalEconomy / proposalEfficient; не подменяет grandTotal.
 */

import { isPublisherSubscriptionTier } from '../auth/authorizationPolicy.js';
import { isPlainObject } from '../utils/isPlainObject.js';
import { escapeHtml } from './pdfHtmlEscape.js';
import { buildTechnicalPdfHtml } from './buildTechnicalPdfHtml.js';

/**
 * @param {unknown} value
 * @returns {Record<string, unknown> | null}
 */
function asObject(value) {
  return isPlainObject(value) ? value : null;
}

/**
 * @param {unknown} n
 * @returns {string}
 */
function money(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) return '—';
  return `${Math.round(n).toLocaleString('uk-UA')} ₴`;
}

/**
 * @param {unknown} unit
 * @returns {string}
 */
function qtyUnitLabel(unit) {
  switch (unit) {
    case 'pcs':
      return 'шт';
    case 'm':
      return 'м';
    case 'section':
      return 'сек.';
    case 'lot':
      return 'компл.';
    default:
      return '';
  }
}

/**
 * @param {Record<string, unknown> | null} proposal
 * @returns {{ model: string, brand: string, totalNominalKw: number | null, price: number | null, unavailableReason: string | null } | null}
 */
function readProposalCard(proposal) {
  if (!proposal) return null;
  if (typeof proposal.unavailableReason === 'string' && proposal.unavailableReason.trim()) {
    return {
      model: '',
      brand: '',
      totalNominalKw: null,
      price: null,
      unavailableReason: proposal.unavailableReason.trim(),
    };
  }
  const model = typeof proposal.model === 'string' ? proposal.model : '';
  const brand = typeof proposal.brand === 'string' ? proposal.brand : '';
  const selected = asObject(proposal.selected);
  const fromSelectedModel =
    selected && typeof selected.model === 'string' ? selected.model : '';
  const resolvedModel = model || fromSelectedModel;
  if (!resolvedModel && typeof proposal.requiredKw !== 'number') {
    return null;
  }
  const totalNominalKw =
    typeof proposal.totalNominalKw === 'number'
      ? proposal.totalNominalKw
      : typeof proposal.nominalKw === 'number'
        ? proposal.nominalKw
        : null;
  const price =
    typeof proposal.price === 'number'
      ? proposal.price
      : selected && typeof selected.price === 'number'
        ? selected.price
        : null;
  return {
    model: resolvedModel || '—',
    brand,
    totalNominalKw,
    price,
    unavailableReason: null,
  };
}

/**
 * @param {string} title
 * @param {ReturnType<typeof readProposalCard>} card
 * @returns {string}
 */
function proposalCardHtml(title, card) {
  if (!card) return '';
  if (card.unavailableReason) {
    return `<div class="card card-muted">
  <h3>${escapeHtml(title)}</h3>
  <p class="muted">${escapeHtml(card.unavailableReason)}</p>
</div>`;
  }
  const name = [card.brand, card.model].filter(Boolean).join(' ') || card.model;
  /** @type {string[]} */
  const lines = [`<div><strong>${escapeHtml(name)}</strong></div>`];
  if (card.totalNominalKw != null) {
    lines.push(
      `<div>Номінал: ${escapeHtml(
        card.totalNominalKw.toLocaleString('uk-UA', { maximumFractionDigits: 1 }),
      )} кВт</div>`,
    );
  }
  if (card.price != null) {
    lines.push(`<div>Орієнтир ціни: ${escapeHtml(money(card.price))}</div>`);
  }
  return `<div class="card">
  <h3>${escapeHtml(title)}</h3>
  ${lines.join('\n  ')}
</div>`;
}

/**
 * @param {unknown} commercial
 * @returns {string}
 */
function commercialTableHtml(commercial) {
  const bom = asObject(commercial);
  if (!bom) return '<p>Немає фінансової кошторису.</p>';
  const lines = Array.isArray(bom.lines) ? bom.lines : [];
  const totals = asObject(bom.totals) ?? {};

  const rows = lines
    .map((raw) => {
      if (!isPlainObject(raw)) return '';
      const typeLabel =
        typeof raw.equipmentTypeLabel === 'string'
          ? raw.equipmentTypeLabel
          : typeof raw.categoryId === 'string'
            ? raw.categoryId
            : '—';
      const name =
        [raw.brand, raw.model].filter((x) => typeof x === 'string' && x).join(' ') ||
        typeLabel;
      const qtyNum = typeof raw.qty === 'number' ? raw.qty : null;
      const qty =
        qtyNum != null
          ? `${qtyNum} ${qtyUnitLabel(raw.qtyUnit)}`.trim()
          : '—';
      return `<tr>
        <td>${escapeHtml(typeLabel)}</td>
        <td>${escapeHtml(name)}</td>
        <td>${escapeHtml(qty)}</td>
        <td>${escapeHtml(money(raw.unitPriceUah))}</td>
        <td>${escapeHtml(money(raw.lineTotalUah))}</td>
      </tr>`;
    })
    .join('');

  return `<table class="bom">
  <thead>
    <tr>
      <th>Тип</th>
      <th>Позиція</th>
      <th>К-сть</th>
      <th>Ціна</th>
      <th>Сума</th>
    </tr>
  </thead>
  <tbody>${rows}</tbody>
  <tfoot>
    <tr>
      <td colspan="4">Обладнання</td>
      <td>${escapeHtml(money(totals.equipmentTotalUah))}</td>
    </tr>
    <tr>
      <td colspan="4">Роботи</td>
      <td>${escapeHtml(money(totals.laborTotalUah))}</td>
    </tr>
    <tr>
      <td colspan="4">Витратні матеріали</td>
      <td>${escapeHtml(money(totals.consumablesTotalUah))}</td>
    </tr>
    <tr>
      <td colspan="4">Разом</td>
      <td>${escapeHtml(money(totals.grandTotalUah))}</td>
    </tr>
  </tfoot>
</table>
<p class="note">Разом за основною (рекомендованою) лінією. Картки нижче — альтернативні схеми, не змінюють суму кошторису.</p>`;
}

/**
 * @param {unknown} presentation
 * @returns {string}
 */
function publisherPresentationHtml(presentation) {
  const node = asObject(presentation);
  if (!node) return '';

  const tier = node.tier;
  if (!isPublisherSubscriptionTier(tier)) return '';

  const contactEmail = typeof node.contactEmail === 'string' ? node.contactEmail.trim() : '';
  if (!contactEmail) return '';

  const title = tier === 'marketplace' ? 'Контакт постачальника' : 'Контакт виконавця';
  const contactName =
    typeof node.contactName === 'string' && node.contactName.trim()
      ? node.contactName.trim()
      : '';

  /** @type {string[]} */
  const lines = [`<div>Email: <a href="mailto:${escapeHtml(contactEmail)}">${escapeHtml(contactEmail)}</a></div>`];
  if (contactName) {
    lines.unshift(`<div>${escapeHtml(contactName)}</div>`);
  }

  return `<div class="publisher-contact">
  <h2>${escapeHtml(title)}</h2>
  ${lines.join('\n  ')}
</div>`;
}

/**
 * Собирает полный HTML документ сметы.
 *
 * @param {import('../types/shared-types.js').ProjectShareSnapshot | Record<string, unknown>} snapshot
