  </div>
  ${publisherPresentationHtml(snap.publisherPresentation)}
  ${mainBlock ? `<div class="cards">${mainBlock}</div>` : ''}
  <h2>Кошторис</h2>
  ${commercialTableHtml(snap.commercial)}
  ${
    altCards
      ? `<h2>Альтернативні схеми котла</h2>
  <p class="note">Порівняння з основною лінією. Суму таблиці вище не перераховується.</p>
  <div class="cards">${altCards}</div>`
      : ''
  }
  ${technical}
</body>
</html>`;
}

/**
 * Назначение: whitelist-снимок отчёта для публичной презентации (без survey/input).
 */

import { isPlainObject } from '../utils/isPlainObject.js';

/**
 * @param {unknown} value
 * @returns {Record<string, unknown> | null}
 */
function asObject(value) {
  return isPlainObject(value) ? value : null;
}

/**
 * @param {Record<string, unknown> | null} matching
 * @param {string} key
 * @returns {unknown}
 */
function pickMatching(matching, key) {
  if (!matching) return undefined;
  return matching[key] !== undefined ? matching[key] : undefined;
}

/**
 * Строит shareSnapshot из полного CalcReport + meta проекта.
 * Только поля для UI сметы / оборудования / краткого техблока.
 *
 * @param {{
 *   clientName: string,
 *   label?: string | null,
 *   report: unknown,
 *   publisherPresentation?: import('../types/shared-types.js').SharePublisherPresentation,
 * }} args
 * @returns {import('../types/shared-types.js').ProjectShareSnapshot}
 */
export function buildShareSnapshot(args) {
  const report = asObject(args.report);
  if (!report) {
    /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
    const err = new Error('Немає звіту для публікації посилання');
    err.statusCode = 400;
    err.code = 'SHARE_REPORT_REQUIRED';
    throw err;
  }

  const commercial = report.commercial;
  if (!isPlainObject(commercial)) {
    /** @type {Error & import('../types/shared-types.js').AppErrorLike} */
    const err = new Error('У звіті немає фінансової смети (commercial)');
    err.statusCode = 400;
    err.code = 'SHARE_COMMERCIAL_REQUIRED';
    throw err;
  }

  const matching = asObject(report.matching);
  const calculations = asObject(report.calculations);
  const meta = asObject(report.meta);
  const temps = asObject(report.temps);
  const input = asObject(report.input);
  const building = input ? asObject(input.building) : null;
  const objectMeta = building ? asObject(building.objectMeta) : null;

  /** @type {'house' | 'apartment' | undefined} */
  let objectType;
  if (objectMeta?.objectType === 'house' || objectMeta?.objectType === 'apartment') {
    objectType = objectMeta.objectType;
  }

  /** @type {Record<string, unknown>} */
  const matchingSlice = {};
  for (const key of [
    'boiler',
    'radiators',
    'waterHeater',
    'indirectWaterHeater',
    'manifolds',
    'uniboxes',
    'hydraulics',
  ]) {
    const v = pickMatching(matching, key);
    if (v !== undefined) matchingSlice[key] = v;
  }

  /** @type {Record<string, unknown>} */
  const calculationsSlice = {};
  if (calculations) {
    for (const key of ['heatLoss', 'hotWater', 'underfloorHeating', 'hydraulics']) {
      if (calculations[key] !== undefined) calculationsSlice[key] = calculations[key];
    }
  }

  /** @type {import('../types/shared-types.js').ProjectShareSnapshot} */
  const snapshot = {
    schemaVersion: 1,
    clientName: String(args.clientName ?? '').trim() || 'Клієнт',
    publishedAt: new Date().toISOString(),
    commercial,
    matching: matchingSlice,
    calculations: calculationsSlice,
  };

  if (args.label != null && String(args.label).trim()) {
    snapshot.label = String(args.label).trim();
  }
  if (objectType) snapshot.objectType = objectType;
  if (temps) snapshot.temps = temps;
  if (Array.isArray(report.warnings)) {
    snapshot.warnings = report.warnings.filter((w) => typeof w === 'string').slice(0, 50);
  }
  if (meta && typeof meta.generatedAt === 'string') {
    snapshot.reportGeneratedAt = meta.generatedAt;
  }
  if (meta && (meta.catalogSource === 'file' || meta.catalogSource === 'mongo')) {
    snapshot.catalogSource = meta.catalogSource;
  }

  if (args.publisherPresentation) {
    snapshot.publisherPresentation = args.publisherPresentation;
  }

  return snapshot;
}

/**
 * Назначение: HTML техблока для серверного PDF (из shareSnapshot / report-like).
 * Описание: Упрощённый порт секций без frontend-парсеров; поля читаются напрямую.
 */

import { isPlainObject } from '../utils/isPlainObject.js';
import { escapeHtml } from './pdfHtmlEscape.js';

/**
 * @param {unknown} value
 * @returns {Record<string, unknown> | null}
 */
function asObject(value) {
  return isPlainObject(value) ? value : null;
}

/**
 * @param {number} watts
 * @param {number} [digits]
 * @returns {string}
 */
function formatKwFromWatts(watts, digits = 1) {
  return (watts / 1000).toLocaleString('uk-UA', {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  });
}

/**
 * @param {number} kw
 * @param {number} [digits]
 * @returns {string}
 */
function formatKw(kw, digits = 1) {
  return kw.toLocaleString('uk-UA', {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  });
}

/**
 * @param {string} title
 * @param {Array<[string, string]>} rows
 * @returns {string}
 */
function kvTable(title, rows) {
  if (rows.length === 0) return '';
  const body = rows
    .map(([k, v]) => `<tr><td>${escapeHtml(k)}</td><td>${escapeHtml(v)}</td></tr>`)
    .join('');
  return `<h3>${escapeHtml(title)}</h3>
<table class="tech">
  <thead><tr><th>Показник</th><th>Значення</th></tr></thead>
  <tbody>${body}</tbody>
</table>`;
}

/**
 * @param {string} title
 * @param {string[]} headers
 * @param {string[][]} rows
 * @returns {string}
 */
function dataTable(title, headers, rows) {
  if (rows.length === 0) return '';
  const head = headers.map((h) => `<th>${escapeHtml(h)}</th>`).join('');
  const body = rows
    .map((r) => `<tr>${r.map((c) => `<td>${escapeHtml(c)}</td>`).join('')}</tr>`)
    .join('');
  return `<h3>${escapeHtml(title)}</h3>
<table class="tech">
  <thead><tr>${head}</tr></thead>
  <tbody>${body}</tbody>
</table>`;
}

/**
 * @param {unknown} snapshotOrReport
 * @returns {string} HTML-фрагмент или пустая строка
 */
export function buildTechnicalPdfHtml(snapshotOrReport) {
  const root = asObject(snapshotOrReport);
  if (!root) return '';

  const parts = [];
  const calculations = asObject(root.calculations);
  const matching = asObject(root.matching);

  const heatLoss = calculations ? asObject(calculations.heatLoss) : null;
  if (heatLoss && typeof heatLoss.totalWatts === 'number') {
    const heatLossKw = heatLoss.totalWatts / 1000;
    const reserve = heatLossKw * 0.15;
    /** @type {Array<[string, string]>} */
    const rows = [
      ['Потужність приміщень', `${formatKw(heatLossKw)} кВт`],
      ['Запас', `${formatKw(reserve)} кВт`],
      ['Разом із запасом', `${formatKw(heatLossKw + reserve)} кВт`],
    ];
    parts.push(kvTable('Тепловтрати', rows));
    const byRoom = Array.isArray(heatLoss.byRoom) ? heatLoss.byRoom : [];
    /** @type {string[][]} */
    const roomRows = [];
    for (const item of byRoom) {
      if (!isPlainObject(item)) continue;
      const name =
        typeof item.roomName === 'string'
          ? item.roomName
          : typeof item.name === 'string'
            ? item.name
            : typeof item.roomId === 'string'
              ? item.roomId
              : '—';
      const watts =
        typeof item.totalWatts === 'number'
          ? item.totalWatts
          : typeof item.heatLossWatts === 'number'
            ? item.heatLossWatts
            : null;
      if (watts == null) continue;
      roomRows.push([name, `${formatKwFromWatts(watts, 2)} кВт`]);
    }
    if (roomRows.length > 0) {
      parts.push(dataTable('Тепловтрати за приміщеннями', ['Приміщення', 'Потужність'], roomRows));
    }
  }

  const hotWater = calculations ? asObject(calculations.hotWater) : null;
  if (hotWater && typeof hotWater.hotWaterPowerKw === 'number') {
    /** @type {Array<[string, string]>} */
    const rows = [['Пікова потужність ГВП', `${formatKw(hotWater.hotWaterPowerKw)} кВт`]];
    if (typeof hotWater.peakFlowLps === 'number') {
      rows.push([
        'Пікова витрата',
        `${hotWater.peakFlowLps.toLocaleString('uk-UA', { maximumFractionDigits: 3 })} л/с`,
      ]);
    }
    if (typeof hotWater.recommendedTankLiters === 'number') {
      rows.push(['Рекомендований бак', `${Math.round(hotWater.recommendedTankLiters)} л`]);
    }
    parts.push(kvTable('Гаряча вода', rows));
  }

  const boiler = matching ? asObject(matching.boiler) : null;
  if (boiler) {
    /** @type {Array<[string, string]>} */
    const rows = [];
    if (typeof boiler.requiredKw === 'number') {
      rows.push(['Потрібна потужність котла', `${formatKw(boiler.requiredKw)} кВт`]);
    }
    const proposal = asObject(boiler.proposal);
    if (proposal && typeof proposal.model === 'string') {
      rows.push(['Пропозиція (основна)', proposal.model]);
      if (typeof proposal.totalNominalKw === 'number') {
        rows.push(['Номінал', `${formatKw(proposal.totalNominalKw)} кВт`]);
      }
    }
    if (rows.length) parts.push(kvTable('Котел', rows));
  }

  const radiators = matching ? asObject(matching.radiators) : null;
  if (radiators) {
    if (radiators.skipped === true || radiators.status === 'skipped') {
      parts.push(kvTable('Радіатори', [['Статус', 'не потрібні (режим лише ТП)']]));
    } else {
      /** @type {Array<[string, string]>} */
      const rows = [];
      if (typeof radiators.chosenModel === 'string') {
        rows.push(['Модель (основна лінія)', radiators.chosenModel]);
      }
      if (typeof radiators.totalSections === 'number') {
        rows.push(['Секцій (осн.)', String(radiators.totalSections)]);
      }
      if (rows.length) parts.push(kvTable('Радіатори', rows));
    }
  }

  const ufh = calculations ? asObject(calculations.underfloorHeating) : null;
  if (ufh && Array.isArray(ufh.rooms) && ufh.rooms.length > 0) {
    parts.push(kvTable('Тепла підлога', [['Кімнат з ТП', String(ufh.rooms.length)]]));
  }

  const hydraulicsCalc = calculations ? asObject(calculations.hydraulics) : null;
  if (hydraulicsCalc) {
    /** @type {Array<[string, string]>} */
    const rows = [];
    if (typeof hydraulicsCalc.flowRateM3PerHour === 'number') {
      rows.push([
        'Витрата',
        `${hydraulicsCalc.flowRateM3PerHour.toLocaleString('uk-UA', { maximumFractionDigits: 3 })} м³/ч`,
      ]);
    }
    if (typeof hydraulicsCalc.headRequiredM === 'number') {
      rows.push([
        'Потрібний напір',
        `${hydraulicsCalc.headRequiredM.toLocaleString('uk-UA', { maximumFractionDigits: 2 })} м`,
      ]);
    }
    if (rows.length) parts.push(kvTable('Гідравліка', rows));
  }

  if (Array.isArray(root.warnings) && root.warnings.length > 0) {
    const warns = root.warnings.filter((w) => typeof w === 'string').slice(0, 40);
    if (warns.length > 0) {
      parts.push(
        `<h3>Попередження</h3><ul>${warns
          .map((w) => `<li>${escapeHtml(w)}</li>`)
          .join('')}</ul>`,
      );
    }
  }

  if (parts.length === 0) return '';
  return `<h2>Технічний розрахунок</h2>${parts.join('\n')}`;
}

/**
 * Назначение: извлечение KPI из отчёта расчёта.
 * Описание: формирует краткую сводку (теплопотери, мощность ГВС, котёл) для списка расчётов
 * в коллекции calculations MongoDB. objectType нормализуется под enum Mongoose summary.
 */
import { resolveObjectType } from '../utils/boilerMountingConstraints.js';
import { isPlainObject } from '../utils/isPlainObject.js';

/**
 * @param {import('../types/shared-types.js').HotWaterReport | undefined | null} hotWater
 * @param {import('../types/shared-types.js').BuildingObjectMeta | undefined} objectMeta
 * @returns {import('../types/shared-types.js').BuildingObjectType}
 */
function resolveSummaryObjectType(hotWater, objectMeta) {
  const fromHotWater = hotWater?.objectType;
  if (fromHotWater === 'apartment' || fromHotWater === 'house') {
    return fromHotWater;
  }
  return resolveObjectType(objectMeta);
}

/**
 * @param {import('../types/shared-types.js').CalcReport} report
 * @returns {import('../types/shared-types.js').CalculationSummary}
 */
export function extractCalculationSummary(report) {
  const heatLoss = report?.calculations?.heatLoss;
  const hotWater = report?.calculations?.hotWater;
  const boiler = report?.matching?.boiler;

  const totalWatts = heatLoss?.totalWatts;
  const heatLossKw =
    typeof totalWatts === 'number' && Number.isFinite(totalWatts)
      ? Math.round((totalWatts / 1000) * 100) / 100
      : undefined;

  const boilerModel =
    boiler?.selected?.model ??
    boiler?.proposal?.model ??
    boiler?.proposalEconomy?.model ??
    null;

  /** @type {import('../types/shared-types.js').CalculationSummary} */
  const summary = {
    insideTempC: report?.temps?.insideC,
    outsideTempC: report?.temps?.outsideC,
    objectType: resolveSummaryObjectType(
      hotWater,
      report?.input?.building?.objectMeta,
    ),
    warningsCount: Array.isArray(report?.warnings) ? report.warnings.length : 0,
    generatedAt: report?.meta?.generatedAt,
  };

  if (heatLossKw !== undefined) summary.heatLossKw = heatLossKw;
  if (typeof hotWater?.hotWaterPowerKw === 'number') {
    summary.hotWaterPowerKw = hotWater.hotWaterPowerKw;
  }
  if (typeof boiler?.requiredKw === 'number') {
    summary.boilerRequiredKw = boiler.requiredKw;
  }
  if (boilerModel) summary.boilerModel = String(boilerModel);

  return summary;
}

/**
 * Санитизация summary при чтении из MongoDB (legacy-документы с битым objectType).
 *
 * @param {unknown} summary
 * @returns {import('../types/shared-types.js').CalculationSummary}
 */
export function sanitizeCalculationSummary(summary) {
  const base = isPlainObject(summary)
      ? /** @type {import('../types/shared-types.js').CalculationSummary} */ ({ ...summary })
      : /** @type {import('../types/shared-types.js').CalculationSummary} */ ({});

  if (base.objectType === 'apartment' || base.objectType === 'house') {
    return base;
  }

  return {
    ...base,
    objectType: resolveObjectType(undefined),
  };
}

/**
 * Назначение: запись импортированного ProjectExportBundle в MongoDB.
 * Описание: создаёт project + calculations без runCalculation; ownerId — текущий пользователь.
 */

import { Project, Calculation } from '../models/public.js';
import {
  assertCanCreateCalculation,
  assertCanCreateProject,
} from './projectAccess.js';
import { assertCalculationDocumentSize } from './documentSizeLimits.js';
import {
  extractCalculationSummary,
  sanitizeCalculationSummary,
} from './extractCalculationSummary.js';
import { logger } from '../utils/logger.js';
import { sortCalculationsForImport } from './sortCalculationsForImport.js';

/**
 * @param {{
 *   ownerId: import('mongoose').Types.ObjectId,
 *   payload: {
 *     clientName: string,
 *     label?: string,
 *     survey?: Record<string, unknown>,
 *     lastCalcInput?: unknown,
 *     calculations: Array<{
 *       calcInput: unknown,
 *       report: unknown,
 *       summary?: unknown,
 *       sourceCreatedAt?: string,
 *     }>,
 *     sourceProjectId?: string,
 *   },
 *   requestId?: string | null,
 * }} args
 * @returns {Promise<{
 *   project: import('mongoose').HydratedDocument<import('../types/shared-types.js').ProjectMongoDoc>,
 *   calculationsImported: number,
 * }>}
 */
export async function importProjectBundle({ ownerId, payload, requestId = null }) {
  await assertCanCreateProject(ownerId);

  /** @type {import('../types/shared-types.js').ProjectMongoDoc} */
  const createDoc = {
    ownerId,
    clientName: payload.clientName,
  };
  if (payload.label !== undefined) createDoc.label = payload.label;
  if (payload.survey !== undefined) createDoc.survey = payload.survey;
  if (payload.lastCalcInput !== undefined) createDoc.lastCalcInput = payload.lastCalcInput;

  const project = await Project.create(createDoc);
  const projectId = project._id;
  if (!projectId) {
    throw new Error('Не вдалося створити проєкт при імпорті');
  }

  const sorted = sortCalculationsForImport(payload.calculations);
  let calculationsImported = 0;

  for (const item of sorted) {
    await assertCanCreateCalculation(projectId);

    const report = /** @type {import('../types/shared-types.js').CalcReport} */ (
      /** @type {unknown} */ (item.report)
    );
    const summary =
      item.summary !== undefined
        ? sanitizeCalculationSummary(item.summary)
        : extractCalculationSummary(report);

    const calculationDocPayload = {
      projectId,
      calcInput: item.calcInput,
      report,
      summary,
    };
    assertCalculationDocumentSize(calculationDocPayload);
    await Calculation.create(calculationDocPayload);
    calculationsImported += 1;
  }

  if (payload.lastCalcInput === undefined && sorted.length > 0) {
    const lastItem = sorted[sorted.length - 1];
    if (lastItem) {
      project.lastCalcInput = /** @type {import('../types/shared-types.js').CalcRequestBody} */ (
        /** @type {unknown} */ (lastItem.calcInput)
      );
      await project.save();
    }
  }

  logger.info('project.import', requestId ? { requestId } : null, {
    projectId: String(projectId),
    ownerId: String(ownerId),
    calculationsImported,
    ...(payload.sourceProjectId ? { sourceProjectId: payload.sourceProjectId } : {}),
  });

  return { project, calculationsImported };
}

/**
 * Назначение: миграция legacy projects.ownerId (JWT sub / dev-local string) → ObjectId ref User.
 * Описание: PR-6 — чистая логика для скрипта migrateProjectOwnerIds и verify без MongoDB.
 */

import mongoose from 'mongoose';

/** @typedef {'skip' | 'update'} MigrateOwnerIdAction */

/**
 * @typedef {Object} MigrateOwnerIdResolution
 * @property {MigrateOwnerIdAction} action
 * @property {import('mongoose').Types.ObjectId} [targetOwnerId]
 * @property {string} reason
 * @property {string} [legacyValue]
 */

/**
 * @typedef {Object} UserOwnerLookupHit
 * @property {import('mongoose').Types.ObjectId} _id
 * @property {import('../types/auth.js').AuthProvider} authProvider
 */

/**
 * @param {unknown} value
 * @returns {value is import('mongoose').Types.ObjectId}
 */
export function isObjectIdValue(value) {
  return value instanceof mongoose.Types.ObjectId;
}

/**
 * @param {unknown} rawOwnerId
 * @returns {'object_id' | 'missing' | 'string'}
 */
export function classifyLegacyOwnerId(rawOwnerId) {
  if (rawOwnerId === null || rawOwnerId === undefined) return 'missing';
  if (isObjectIdValue(rawOwnerId)) return 'object_id';
  if (typeof rawOwnerId === 'string') return 'string';
  return 'string';
}

/**
 * @param {string} legacyString
 * @returns {boolean}
 */
export function isLegacyDevOwnerString(legacyString) {
  const trimmed = legacyString.trim();
  return trimmed === '' || trimmed === 'dev-local';
}

/**
 * @param {string} legacyString
 * @returns {import('mongoose').Types.ObjectId | null}
 */
export function parseOwnerIdHexString(legacyString) {
  const trimmed = legacyString.trim();
  if (!/^[a-fA-F0-9]{24}$/.test(trimmed)) return null;
  if (String(new mongoose.Types.ObjectId(trimmed)) !== trimmed) return null;
  return new mongoose.Types.ObjectId(trimmed);
}

/**
 * @param {UserOwnerLookupHit[]} hits
 * @param {import('../types/auth.js').AuthProvider | null | undefined} preferredAuthProvider
 * @returns {UserOwnerLookupHit | null}
 */
export function pickUserOwnerLookupHit(hits, preferredAuthProvider) {
  if (hits.length === 0) return null;
  if (hits.length === 1) return hits[0] ?? null;

  if (preferredAuthProvider) {
    const preferred = hits.find((hit) => hit.authProvider === preferredAuthProvider);
    if (preferred) return preferred;
  }

  const clerk = hits.find((hit) => hit.authProvider === 'clerk');
  if (clerk) return clerk;

  return hits[0] ?? null;
}

/**
 * @param {unknown} rawOwnerId
 * @param {{
 *   devOwnerObjectId: import('mongoose').Types.ObjectId,
 *   findUsersByProviderUserId: (providerUserId: string) => Promise<UserOwnerLookupHit[]>,
 *   findUserByObjectId?: (ownerObjectId: import('mongoose').Types.ObjectId) => Promise<UserOwnerLookupHit | null>,
 *   preferredAuthProvider?: import('../types/auth.js').AuthProvider | null,
 * }} deps
 * @returns {Promise<MigrateOwnerIdResolution>}
 */
export async function resolveMigrationTarget(rawOwnerId, deps) {
  const kind = classifyLegacyOwnerId(rawOwnerId);

  if (kind === 'object_id') {
    return { action: 'skip', reason: 'already_object_id' };
  }

  if (kind === 'missing') {
    return {
      action: 'update',
      targetOwnerId: deps.devOwnerObjectId,
      reason: 'missing_owner_set_dev',
      legacyValue: '',
    };
  }

  const legacyString = String(rawOwnerId);

  if (isLegacyDevOwnerString(legacyString)) {
    return {
      action: 'update',
      targetOwnerId: deps.devOwnerObjectId,
      reason: 'dev_local_string',
      legacyValue: legacyString,
    };
  }

  const parsedHex = parseOwnerIdHexString(legacyString);
  if (parsedHex) {
    if (parsedHex.equals(deps.devOwnerObjectId)) {
      return {
        action: 'update',
        targetOwnerId: parsedHex,
        reason: 'dev_owner_hex_string',
        legacyValue: legacyString,
      };
    }

    if (deps.findUserByObjectId) {
      const userById = await deps.findUserByObjectId(parsedHex);
      if (userById) {
        return {
          action: 'update',
          targetOwnerId: userById._id,
          reason: 'user_object_id_hex_string',
          legacyValue: legacyString,
        };
      }
    }

    const usersBySub = await deps.findUsersByProviderUserId(legacyString);
    const pickedSub = pickUserOwnerLookupHit(usersBySub, deps.preferredAuthProvider);
    if (pickedSub) {
      return {
        action: 'update',
        targetOwnerId: pickedSub._id,
        reason: 'provider_user_id_hex_collision',
        legacyValue: legacyString,
      };
    }

    return {
      action: 'skip',
      reason: 'orphaned_hex_string',
      legacyValue: legacyString,
    };
  }

  const users = await deps.findUsersByProviderUserId(legacyString);
  const picked = pickUserOwnerLookupHit(users, deps.preferredAuthProvider);
  if (!picked) {
    return {
      action: 'skip',
      reason: 'orphaned_provider_user_id',
      legacyValue: legacyString,
    };
  }

  return {
    action: 'update',
    targetOwnerId: picked._id,
    reason: 'provider_user_id',
    legacyValue: legacyString,
  };
}

/**
 * @param {Iterable<MigrateOwnerIdResolution & { action: 'update' }>} updates
 * @returns {Record<string, number>}
 */
export function summarizeMigrationResolutions(updates) {
  /** @type {Record<string, number>} */
  const counts = {};
  for (const item of updates) {
    counts[item.reason] = (counts[item.reason] ?? 0) + 1;
  }
  return counts;
}

/**
 * Назначение: метаданные владельца проекта для admin list/detail.
 * Описание: batch-загрузка email из users по ownerId.
 */

import { User } from '../models/public.js';
import { parseObjectIdParam } from './parseObjectId.js';

/**
 * @param {import('../types/shared-types.js').ProjectMongoDoc[]} docs
 * @returns {Promise<Map<string, string>>} ownerId hex → email
 */
export async function loadOwnerEmailByOwnerId(docs) {
  /** @type {import('mongoose').Types.ObjectId[]} */
  const ownerIds = [];
  const seen = new Set();
  for (const doc of docs) {
    const raw = doc.ownerId;
    const hex = raw != null ? String(raw) : '';
    if (!hex || seen.has(hex)) continue;
    const oid = parseObjectIdParam(hex);
    if (!oid) continue;
    seen.add(hex);
    ownerIds.push(oid);
  }

  if (ownerIds.length === 0) return new Map();

  const users = await User.find({ _id: { $in: ownerIds } })
    .select('email')
    .lean();

  /** @type {Map<string, string>} */
  const map = new Map();
  for (const user of users) {
    const id = user._id != null ? String(user._id) : '';
    if (id && typeof user.email === 'string' && user.email.trim()) {
      map.set(id, user.email.trim());
    }
  }
  return map;
}

/**
 * @param {unknown} email
 * @returns {Promise<import('mongoose').Types.ObjectId | null>}
 */
export async function resolveOwnerObjectIdByEmail(email) {
  if (typeof email !== 'string') return null;
  const trimmed = email.trim();
  if (!trimmed) return null;

  const escaped = trimmed.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const user = await User.findOne({
    email: { $regex: new RegExp(`^${escaped}$`, 'i') },
  })
    .select('_id')
    .lean();

  if (!user?._id) return null;
  return parseObjectIdParam(String(user._id));
}

/**
 * Назначение: проверка доступности MongoDB для проектов.
 * Описание: гарантирует наличие конфигурации и успешное подключение перед операциями API
 * сохранения проектов; при недоступности — ошибка 503 MONGODB_UNAVAILABLE.
 */
import { ensureMongoReferenceConnection } from '../utils/mongoReferenceConnection.js';
import { createAppError } from '../utils/createAppError.js';

/**
 * Подключение к MongoDB обязательно для API проектов.
 * @returns {Promise<void>}
 */
export async function requireMongoForProjects() {
  const cfgMissing = !process.env.MONGODB_URI?.trim() &&
    !process.env.MONGODB_URI_FALLBACK?.trim() &&
    !(
      process.env.MONGODB_USER?.trim() &&
      process.env.MONGODB_PASSWORD?.trim() &&
      process.env.MONGODB_URL?.trim() &&
      process.env.MONGODB_DB?.trim()
    );

  if (cfgMissing) {
    throw createAppError(
      'Збереження проєктів недоступне: задайте MONGODB_URI або MONGODB_USER/PASSWORD/URL/DB у backend/.env',
      'MONGODB_UNAVAILABLE',
      503,
    );
  }

  try {
    const ok = await ensureMongoReferenceConnection();
    if (!ok) {
      throw createAppError('Не вдалося підключитися до MongoDB.', 'MONGODB_UNAVAILABLE', 503);
    }
  } catch (connectErr) {
    throw createAppError(
      connectErr instanceof Error ? connectErr.message : 'Не вдалося підключитися до MongoDB.',
      'MONGODB_UNAVAILABLE',
      503,
    );
  }
}

/**
 * Назначение: сериализация документов проектов.
 * Описание: преобразование MongoDB-документов Project и Calculation в DTO для API списка,
 * деталей проекта и вложенных расчётов.
 */
import { sanitizeCalculationSummary } from './extractCalculationSummary.js';
import { isPlainObject } from '../utils/isPlainObject.js';
import { serializeProjectShareMeta } from './serializeShare.js';

/**
 * @param {import('mongoose').Document | import('../types/shared-types.js').ProjectMongoDoc | import('../types/shared-types.js').CalculationMongoDoc | Record<string, unknown>} doc
 * @returns {Record<string, unknown>}
 */
function toPlainRecord(doc) {
  if (
    doc &&
    typeof doc === 'object' &&
    'toObject' in doc &&
    typeof /** @type {{ toObject?: () => unknown }} */ (doc).toObject === 'function'
  ) {
    const plain = /** @type {{ toObject: () => unknown }} */ (doc).toObject();
    return isPlainObject(plain) ? plain : {};
  }
  if (isPlainObject(doc)) return doc;
  return /** @type {Record<string, unknown>} */ (/** @type {unknown} */ (doc));
}

/**
 * @param {unknown} value
 * @returns {string}
 */
function formatTimestamp(value) {
  return value instanceof Date ? value.toISOString() : String(value ?? '');
}

/**
 * @param {import('mongoose').Document | import('../types/shared-types.js').ProjectMongoDoc | Record<string, unknown>} doc
 * @param {{ ownerEmail?: string }} [meta]
 * @returns {import('../types/shared-types.js').ProjectListItem}
 */
export function serializeProjectListItem(doc, meta = {}) {
  const rec = toPlainRecord(doc);
  const id = String(rec._id ?? '');

  /** @type {import('../types/shared-types.js').ProjectListItem} */
  const item = {
    id,
    clientName: String(rec.clientName ?? ''),
    createdAt: formatTimestamp(rec.createdAt),
    updatedAt: formatTimestamp(rec.updatedAt),
  };

  if (rec.label != null && rec.label !== '') {
    item.label = String(rec.label);
  }
  if (typeof rec.calculationsCount === 'number') {
    item.calculationsCount = rec.calculationsCount;
  }
  if (rec.ownerId != null && String(rec.ownerId).trim()) {
    item.ownerId = String(rec.ownerId);
  }
  if (meta.ownerEmail != null && meta.ownerEmail.trim()) {
    item.ownerEmail = meta.ownerEmail.trim();
  }

  return item;
}

/**
 * @param {import('mongoose').Document | import('../types/shared-types.js').ProjectMongoDoc | Record<string, unknown>} doc
 * @param {{ calculationsCount?: number, lastCalculation?: import('../types/shared-types.js').CalculationListItem | null, ownerEmail?: string }} [extra]
 * @returns {import('../types/shared-types.js').ProjectDetail}
 */
export function serializeProjectDetail(doc, extra = {}) {
  const rec = toPlainRecord(doc);
  const base = serializeProjectListItem(rec, {
    ...(extra.ownerEmail !== undefined ? { ownerEmail: extra.ownerEmail } : {}),
  });

  /** @type {import('../types/shared-types.js').ProjectDetail} */
  const detail = { ...base };

  if (extra.calculationsCount !== undefined) {
    detail.calculationsCount = extra.calculationsCount;
  } else if (typeof rec.calculationsCount === 'number') {
    detail.calculationsCount = rec.calculationsCount;
  }
  if (rec.survey !== undefined && rec.survey !== null) {
    detail.survey = rec.survey;
  }
  if (rec.lastCalcInput !== undefined && rec.lastCalcInput !== null) {
    detail.lastCalcInput = /** @type {import('../types/shared-types.js').CalcRequestBody} */ (
      /** @type {unknown} */ (rec.lastCalcInput)
    );
  }
  if (extra.lastCalculation !== undefined && extra.lastCalculation !== null) {
    detail.lastCalculation = extra.lastCalculation;
  }

  const shareMeta = serializeProjectShareMeta(rec);
  if (shareMeta) {
    detail.shareToken = shareMeta.shareToken;
    detail.sharePublishedAt = shareMeta.sharePublishedAt;
    detail.publicPath = shareMeta.publicPath;
  }

  return detail;
}

/**
 * @param {import('mongoose').Document | import('../types/shared-types.js').CalculationMongoDoc | Record<string, unknown>} doc
 * @returns {import('../types/shared-types.js').CalculationListItem}
 */
export function serializeCalculationListItem(doc) {
  const rec = toPlainRecord(doc);
  return {
    id: String(rec._id ?? ''),
    projectId: String(rec.projectId ?? ''),
    summary: sanitizeCalculationSummary(rec.summary),
    createdAt: formatTimestamp(rec.createdAt),
  };
}

/**
 * @param {import('mongoose').Document | import('../types/shared-types.js').CalculationMongoDoc | Record<string, unknown>} doc
 * @returns {import('../types/shared-types.js').CalculationDetail}
 */
export function serializeCalculationDetail(doc) {
  const rec = toPlainRecord(doc);
  return {
    ...serializeCalculationListItem(rec),
    calcInput: /** @type {import('../types/shared-types.js').CalcRequestBody} */ (
      /** @type {unknown} */ (rec.calcInput)
    ),
    report: /** @type {import('../types/shared-types.js').CalcReport} */ (
      /** @type {unknown} */ (rec.report)
    ),
  };
}

/**
 * Назначение: разрешение текстов рекомендаций.
 * Описание: подстановка шаблонов по code из переданного RecommendationsBundle; pushRecommendation
 * добавляет структурированные REC_* / WARN_* в отчёт matching. Без глобального кэша — bundle из ctx.
 */

/**
 * Подстановка {{key}} в шаблон.
 * @param {string} template
 * @param {Record<string, string | number | undefined>} [vars]
 */
function formatRecommendationText(template, vars = {}) {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => {
    const v = vars[key];
    return v === undefined || v === null ? '' : String(v);
  });
}

/**
 * @param {import('./types.js').RecommendationsBundle} recommendations
 * @param {string} code
 * @param {Record<string, string | number | undefined>} [vars]
 * @returns {import('./types.js').ResolvedRecommendation | null}
 */
export function resolveRecommendation(recommendations, code, vars = {}) {
  if (!recommendations?.byCode) {
    throw new Error(
      'resolveRecommendation: recommendations обязательны (передайте ctx.recommendations из CalcRuntimeContext).',
    );
  }
  const rec = recommendations.byCode[code];
  if (!rec) return null;
  const text = formatRecommendationText(rec.text, vars);
  return {
    code: rec.code,
    category: rec.category,
    equipmentType: rec.equipmentType,
    title: rec.title,
    text,
    ...(rec.resolutionSteps?.length
      ? {
          resolutionSteps: rec.resolutionSteps.map((s) => ({
            title: s.title,
            detail: s.detail,
          })),
        }
      : {}),
  };
}

/**
 * Добавить рекомендацию в warnings (текст) и в структурированный список.
 * @param {string[]} warnings
 * @param {import('./types.js').ResolvedRecommendation[]} resolvedList
 * @param {import('./types.js').RecommendationsBundle} recommendations
 * @param {string} code
 * @param {Record<string, string | number | undefined>} [vars]
 * @returns {import('./types.js').ResolvedRecommendation | null}
 */
export function pushRecommendation(
  warnings,
  resolvedList,
  recommendations,
  code,
  vars = {},
) {
  const resolved = resolveRecommendation(recommendations, code, vars);
  if (!resolved) {
    warnings.push(`[${code}] Текст рекомендації не знайдено в довіднику.`);
    return null;
  }
  if (resolved.category === 'warnings') {
    warnings.push(resolved.text);
  }
  resolvedList.push(resolved);
  return resolved;
}

/**
 * Назначение: валидация справочника recommendations.
 * Описание: проверка и нормализация массива документов с уникальными code, category и текстами
 * для использования в recommendationResolver и отчёте calc.
 */

/**
 * @param {unknown} json — массив документов
 * @param {'file' | 'mongo'} [source]
 * @returns {import('./types.js').RecommendationsBundle}
 */
export function validateAndNormalizeRecommendationsBundle(json, source = 'file') {
  if (!Array.isArray(json)) {
    throw new Error('recommendations: ожидается массив документов');
  }

  /** @type {Record<string, import('./types.js').NormalizedRecommendation>} */
  const byCode = {};

  for (let i = 0; i < json.length; i++) {
    const raw = json[i];
    if (!raw || typeof raw !== 'object') {
      throw new Error(`recommendations[${i}]: ожидается объект`);
    }
    const d = /** @type {Record<string, unknown>} */ (raw);
    const code = String(d.code ?? '').trim();
    if (!code) {
      throw new Error(`recommendations[${i}].code: обязательная непустая строка`);
    }
    if (byCode[code]) {
      throw new Error(`recommendations: дублирующийся code «${code}»`);
    }
    const schemaVersionRaw = Number(d.schemaVersion);
    if (!Number.isFinite(schemaVersionRaw) || Math.trunc(schemaVersionRaw) < 1) {
      throw new Error(`recommendations[${code}].schemaVersion: обязательное целое >= 1`);
    }
    const category = String(d.category ?? '').trim();
    if (category !== 'warnings' && category !== 'automationHints') {
      throw new Error(
        `recommendations[${code}].category: ожидается warnings или automationHints`,
      );
    }
    const equipmentType = String(d.equipmentType ?? '').trim();
    if (!equipmentType) {
      throw new Error(`recommendations[${code}].equipmentType: обязательная строка`);
    }
    const title = String(d.title ?? '').trim();
    const text = String(d.text ?? '').trim();
    if (!title) {
      throw new Error(`recommendations[${code}].title: обязательная непустая строка`);
    }
    if (!text) {
      throw new Error(`recommendations[${code}].text: обязательная непустая строка`);
    }

    /** @type {import('./types.js').RecommendationResolutionStep[] | undefined} */
    let resolutionSteps;
    if (d.resolutionSteps != null) {
      if (!Array.isArray(d.resolutionSteps)) {
        throw new Error(
          `recommendations[${code}].resolutionSteps: ожидается массив объектов {title, detail}`,
        );
      }
      // Пустой массив в Mongo (legacy / default схемы) = поле отсутствует
      if (d.resolutionSteps.length > 0) {
        resolutionSteps = [];
        for (let si = 0; si < d.resolutionSteps.length; si += 1) {
          const rawStep = d.resolutionSteps[si];
          if (!rawStep || typeof rawStep !== 'object' || Array.isArray(rawStep)) {
            throw new Error(
              `recommendations[${code}].resolutionSteps[${si}]: ожидается объект {title, detail}`,
            );
          }
          const stepObj = /** @type {Record<string, unknown>} */ (rawStep);
          const stepTitle = String(stepObj.title ?? '').trim();
          const stepDetail = String(stepObj.detail ?? '').trim();
          if (!stepTitle || !stepDetail) {
            throw new Error(
              `recommendations[${code}].resolutionSteps[${si}]: title и detail обязательны`,
            );
          }
          resolutionSteps.push({ title: stepTitle, detail: stepDetail });
        }
      }
    }

    byCode[code] = {
      code,
      schemaVersion: Math.trunc(schemaVersionRaw),
      category: /** @type {import('./types.js').RecommendationCategory} */ (category),
      equipmentType,
      title,
      text,
      ...(resolutionSteps ? { resolutionSteps } : {}),
    };
  }

  const required = /** @type {const} */ ([
    'REC_BOILER_OPTIMAL',
    'WARN_BOILER_UNDERPOWERED',
    'WARN_DHW_TIME_LONG',
  ]);
  for (const code of required) {
    if (!byCode[code]) {
      throw new Error(`recommendations: отсутствует обязательный code=${code}`);
    }
  }

  const resolvedSource = source === 'mongo' ? 'mongo' : 'file';
  return { byCode, source: resolvedSource };
}

/**
 * Назначение: fail-fast проверка CalcRuntimeContext на границе calc-пайплайна.
 * Описание: Дешёвая страховка в validate/buildReport; полная валидация — при загрузке справочников.
 */

/**
 * @param {unknown} ctx
 * @returns {asserts ctx is import('../types/shared-types.js').CalcRuntimeContext}
 */
export function assertCalcRuntimeContext(ctx) {
  if (!ctx || typeof ctx !== 'object') {
    throw new Error(
      'Критическая ошибка рантайма: CalcRuntimeContext отсутствует или не является объектом.',
    );
  }

  const c = /** @type {Record<string, unknown>} */ (ctx);

  if (!c.appliances || typeof c.appliances !== 'object') {
    throw new Error('CalcRuntimeContext: отсутствует appliances.');
  }
  if (!c.ufhPresets || typeof c.ufhPresets !== 'object') {
    throw new Error('CalcRuntimeContext: отсутствует ufhPresets.');
  }
  if (!c.waterNorms || typeof c.waterNorms !== 'object') {
    throw new Error('CalcRuntimeContext: отсутствует waterNorms.');
  }
  if (!c.catalog || typeof c.catalog !== 'object') {
    throw new Error('CalcRuntimeContext: отсутствует catalog.');
  }
  if (!c.recommendations || typeof c.recommendations !== 'object') {
    throw new Error('CalcRuntimeContext: отсутствует recommendations.');
  }
  if (!c.sources || typeof c.sources !== 'object') {
    throw new Error('CalcRuntimeContext: отсутствует sources.');
  }

  const ufh = /** @type {{ byPresetId?: unknown }} */ (c.ufhPresets);
  const app = /** @type {{ byKind?: unknown }} */ (c.appliances);
  if (!ufh.byPresetId || typeof ufh.byPresetId !== 'object') {
    throw new Error('CalcRuntimeContext: ufhPresets.byPresetId обязателен.');
  }
  if (!app.byKind || typeof app.byKind !== 'object') {
    throw new Error('CalcRuntimeContext: appliances.byKind обязателен.');
  }
}

/**
 * Назначение: подсказки автоматизации схем котёл/ГВС.
 * Описание: Формирует массив matchingAutomationHints для meta отчёта на основе типа объекта, пиковой мощности ГВС и активной схемы подбора котла. Предлагает альтернативные схемы (БКН, электробойлер, max-комби). Вызывается из buildReport.js.
 */

import {
  SCHEME_BOILER_ELECTRIC_SEPARATE,
  SCHEME_BOILER_MAX_COMBI,
  SCHEME_BOILER_SINGLE_INDIRECT_SUM,
} from '../../../shared/heatingMatchingSchemes.js';
import {
  isLargeApartment,
  isLargeApartmentByInput,
} from '../utils/apartmentMatching.js';

/**
 * @param {object} args
 * @param {'apartment' | 'house'} args.objectType
 * @param {import('../types/shared-types.js').HotWaterReport | undefined} args.hotWaterReport
 * @param {string | undefined} args.activeScheme
 * @param {import('../types/shared-types.js').BuildingInput | undefined} [args.building]
 * @param {number | undefined} [args.heatingLoadKw]
 * @param {import('../dhw/types.js').BoilerApplianceRules['apartmentClassification']} [args.apartmentClassification]
 * @returns {import('../types/shared-types.js').MatchingAutomationHint[]}
 */
export function buildMatchingAutomationHints({
  objectType,
  hotWaterReport,
  activeScheme,
  building,
  heatingLoadKw,
  apartmentClassification,
}) {
  /** @type {import('../types/shared-types.js').MatchingAutomationHint[]} */
  const hints = [];
  if (!hotWaterReport) return hints;

  const peak = Number(hotWaterReport.peakThermalPowerKw);
  const fx = hotWaterReport.fixtures ?? {};
  const thermalPoints =
    (fx.shower ?? 0) + (fx.bath ?? 0) + (fx.sink ?? 0) + (fx.kitchenSink ?? 0);

  const scheme = activeScheme ?? SCHEME_BOILER_MAX_COMBI;

  if (objectType === 'house' && hotWaterReport.dhwSupplyScenario === 'storage') {
    if (peak > 30 && scheme === SCHEME_BOILER_MAX_COMBI) {
      hints.push({
        type: 'suggest_single_indirect_sum',
        message:
          `Пікова теплова потужність проточного режиму (${peak.toFixed(1)} кВт) висока — для будинку з БКН рекомендується схема «одноконтурний котел + БКН» з сумуванням потужностей опалення та нагрівання бака.`,
        suggestedScheme: SCHEME_BOILER_SINGLE_INDIRECT_SUM,
      });
    }
    if (peak <= 24 && thermalPoints <= 4 && scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM) {
      hints.push({
        type: 'suggest_combi_budget',
        message:
          'За помірного водорозбору та піку ГВП до ~24 кВт двоконтурний котел за правилом max(опалення, ГВП) часто компактніший і дешевший — звірте з проєктом.',
        suggestedScheme: SCHEME_BOILER_MAX_COMBI,
      });
    }
  }

  if (objectType === 'apartment' && apartmentClassification) {
    const large =
      heatingLoadKw != null
        ? isLargeApartment(building, heatingLoadKw, fx, apartmentClassification)
        : isLargeApartmentByInput(building, fx, apartmentClassification);

    if (!large && scheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM) {
      hints.push({
        type: 'apartment_bkn_small_not_recommended',
        message:
          'Для малих квартир БКН зазвичай надлишковий — розгляньте двоконтурний котел або схему з електробойлером.',
        suggestedScheme: SCHEME_BOILER_MAX_COMBI,
      });
    }

    if (
      large &&
      scheme === SCHEME_BOILER_MAX_COMBI &&
      hotWaterReport.dhwSupplyScenario === 'flowThrough' &&
      peak > 20
    ) {
      hints.push({
        type: 'apartment_suggest_bkn_large',
        message:
          'Для великої квартири з високим піком ГВП може підійти схема «1К + БКН» за наявності місця під бойлер — вкажіть indirectDhwSpaceAvailable.',
        suggestedScheme: SCHEME_BOILER_SINGLE_INDIRECT_SUM,
      });
    }

    if (
      scheme === SCHEME_BOILER_ELECTRIC_SEPARATE &&
      (hotWaterReport.recommendedTankLiters ?? 0) > 0
    ) {
      hints.push({
        type: 'apartment_electric_storage_volume',
        message: `Об’єм електробойлера розраховано за нормою ${hotWaterReport.recommendedTankLiters} л (50 л на мешканця, мінімум 50 л).`,
      });
    }
  }

  return hints;
}

/**
 * Назначение: сборка коммерческой сметы (report.commercial).
 * Описание: Оборудование из основной линии matching и hydraulics; монтаж 40% и
 * расходники 15% от суммы оборудования; смесительный узел ТП — note без цены.
 */

/** @typedef {import('../types/shared-types.js').FinancialBomLine} FinancialBomLine */
/** @typedef {import('../types/shared-types.js').CommercialBomReport} CommercialBomReport */
/** @typedef {import('../types/shared-types.js').BuildingObjectType} BuildingObjectType */
/** @typedef {import('../types/shared-types.js').FinancialBomCategoryId} FinancialBomCategoryId */

export const FINANCIAL_BOM_SCHEMA_VERSION = 1;
export const FINANCIAL_LABOR_PERCENT = 40;
export const FINANCIAL_CONSUMABLES_PERCENT = 15;
export const MIXING_NODE_SELF_ASSEMBLY_NOTE = 'монтаж самостійно';

const CATEGORY_LABEL = /** @type {Record<FinancialBomCategoryId, string>} */ ({
  boiler_room: 'Котельня / СУ',
  radiators: 'Радіаторне опалення',
  ufh: 'Тепла підлога',
  hydraulics_heating: 'Гідравліка',
  works: 'Роботи',
});

/**
 * @param {number} n
 * @returns {number}
 */
function money(n) {
  return Math.round(n * 100) / 100;
}

/**
 * @param {unknown} v
 * @returns {string}
 */
function str(v) {
  return typeof v === 'string' ? v.trim() : '';
}

/**
 * @param {unknown} obj
 * @returns {string}
 */
function readBrand(obj) {
  if (!obj || typeof obj !== 'object') return '';
  return str(/** @type {Record<string, unknown>} */ (obj).brand);
}

/**
 * @param {BuildingObjectType} objectType
 * @returns {string}
 */
function objectLabel(objectType) {
  return objectType === 'apartment' ? 'Квартира' : 'Будинок';
}

/**
 * @param {BuildingObjectType} objectType
 * @param {FinancialBomCategoryId} categoryId
 * @param {string[]} [extra]
 * @returns {string[]}
 */
function scope(objectType, categoryId, extra = []) {
  return [objectLabel(objectType), CATEGORY_LABEL[categoryId], ...extra].filter(
    (s) => s.length > 0,
  );
}

/**
 * @param {Partial<FinancialBomLine> & Pick<FinancialBomLine, 'id' | 'kind' | 'objectType' | 'equipmentTypeLabel' | 'model' | 'qty' | 'qtyUnit' | 'categoryId' | 'source'>} partial
 * @returns {FinancialBomLine}
 */
function line(partial) {
  return {
    id: partial.id,
    kind: partial.kind,
    objectType: partial.objectType,
    equipmentTypeLabel: partial.equipmentTypeLabel,
    brand: partial.brand ?? '',
    model: partial.model,
    qty: partial.qty,
    qtyUnit: partial.qtyUnit,
    unitPriceUah: partial.unitPriceUah ?? null,
    lineTotalUah: partial.lineTotalUah ?? null,
    scopePath: partial.scopePath ?? scope(partial.objectType, partial.categoryId),
    categoryId: partial.categoryId,
    ...(partial.catalogId ? { catalogId: partial.catalogId } : {}),
    source: partial.source,
    ...(partial.note ? { note: partial.note } : {}),
  };
}

/**
 * @param {FinancialBomLine} l
 * @returns {string}
 */
function collapseKey(l) {
  return [
    l.kind,
    l.categoryId,
    l.catalogId ?? '',
    l.brand,
    l.model,
    l.qtyUnit,
    l.unitPriceUah == null ? 'null' : String(l.unitPriceUah),
    l.note ?? '',
  ].join('\u0001');
}

/**
 * Схлопывание одинаковых позиций: сумма qty и lineTotal.
 *
 * @param {FinancialBomLine[]} lines
 * @returns {FinancialBomLine[]}
 */
export function collapseFinancialBomLines(lines) {
  /** @type {Map<string, FinancialBomLine>} */
  const map = new Map();
  for (const raw of lines) {
    const key = collapseKey(raw);
    const prev = map.get(key);
    if (!prev) {
      map.set(key, { ...raw, scopePath: [...raw.scopePath] });
      continue;
    }
    const qty = money(prev.qty + raw.qty);
    const lineTotalUah =
      prev.lineTotalUah != null && raw.lineTotalUah != null
        ? money(prev.lineTotalUah + raw.lineTotalUah)
        : prev.lineTotalUah ?? raw.lineTotalUah;
    const sameScope =
      prev.scopePath.length === raw.scopePath.length
      && prev.scopePath.every((p, i) => p === raw.scopePath[i]);
    map.set(key, {
      ...prev,
      qty,
      lineTotalUah: lineTotalUah ?? null,
      scopePath: sameScope
        ? prev.scopePath
        : scope(prev.objectType, prev.categoryId),
    });
  }
  return [...map.values()];
}

/**
 * @param {import('../types/shared-types.js').CalcRequestBody | undefined} input
 * @returns {Map<string, { floor: number; name: string }>}
 */
function roomMetaById(input) {
  /** @type {Map<string, { floor: number; name: string }>} */
  const map = new Map();
  const rooms = input?.building?.rooms;
  if (!Array.isArray(rooms)) return map;
  for (const r of rooms) {
    if (!r || typeof r !== 'object') continue;
    const id = str(r.id);
    if (!id) continue;
    const floor =
      typeof r.floor === 'number' && Number.isFinite(r.floor) && r.floor >= 1
        ? Math.trunc(r.floor)
        : 1;
    const name = str(r.name) || id;
    map.set(id, { floor, name });
  }
  return map;
}

/**
 * @param {BuildingObjectType} objectType
 * @param {import('../types/shared-types.js').MatchingReport | undefined} matching
 * @param {FinancialBomLine[]} out
 */
function pushBoiler(objectType, matching, out) {
  const proposal = matching?.boiler?.proposal;
  if (!proposal?.model) return;
  const units = Math.max(1, Math.trunc(proposal.unitsCount) || 1);
  const total =
    typeof proposal.estimatedTotalPrice === 'number'
    && Number.isFinite(proposal.estimatedTotalPrice)
      ? money(proposal.estimatedTotalPrice)
      : null;
  const unitPrice = total != null ? money(total / units) : null;
  const brand = readBrand(matching?.boiler?.selected);
  out.push(
    line({
      id: `boiler:${proposal.model}`,
      kind: 'equipment',
      objectType,
      equipmentTypeLabel: 'Котел',
      brand,
      model: proposal.model,
      qty: units,
      qtyUnit: 'pcs',
      unitPriceUah: unitPrice,
      lineTotalUah: total,
      scopePath: scope(objectType, 'boiler_room'),
      categoryId: 'boiler_room',
      source: 'matching.boiler.proposal',
    }),
  );
}

/**
 * @param {BuildingObjectType} objectType
 * @param {import('../types/shared-types.js').MatchingReport | undefined} matching
 * @param {FinancialBomLine[]} out
 */
function pushWaterHeaters(objectType, matching, out) {
  const wh = matching?.waterHeater;
  if (wh?.selected?.model && wh.chosenVariant) {
    const price =
      typeof wh.chosenVariant.price === 'number' && Number.isFinite(wh.chosenVariant.price)
        ? money(wh.chosenVariant.price)
        : null;
    out.push(
      line({
        id: `waterHeater:${wh.selected.model}:${wh.chosenVariant.volumeLiters ?? ''}`,
        kind: 'equipment',
        objectType,
        equipmentTypeLabel: 'Електронакопичувач',
        brand: readBrand(wh.selected),
        model: wh.selected.model,
        qty: 1,
        qtyUnit: 'pcs',
        unitPriceUah: price,
        lineTotalUah: price,
        scopePath: scope(objectType, 'boiler_room'),
        categoryId: 'boiler_room',
        source: 'matching.waterHeater',
      }),
    );
  }

  const bkn = matching?.indirectWaterHeater;
  if (bkn?.selected?.model && !bkn.skippedReason) {
    const price =
      typeof bkn.selected.price === 'number' && Number.isFinite(bkn.selected.price)
        ? money(bkn.selected.price)
        : null;
    out.push(
      line({
        id: `indirectWaterHeater:${bkn.selected.model}`,
        kind: 'equipment',
        objectType,
        equipmentTypeLabel: 'Бойлер непрямого нагріву',
        brand: readBrand(bkn.selected),
        model: bkn.selected.model,
        qty: 1,
        qtyUnit: 'pcs',
        unitPriceUah: price,
        lineTotalUah: price,
        scopePath: scope(objectType, 'boiler_room'),
        categoryId: 'boiler_room',
        source: 'matching.indirectWaterHeater',
      }),
    );
  }
}

/**
 * @param {BuildingObjectType} objectType
 * @param {import('../types/shared-types.js').MatchingReport | undefined} matching
 * @param {Map<string, { floor: number; name: string }>} rooms
 * @param {FinancialBomLine[]} out
 */
function pushRadiators(objectType, matching, rooms, out) {
  const byRoom = matching?.radiators?.byRoom;
  if (!Array.isArray(byRoom) || matching?.radiators?.skippedReason) return;

  for (const row of byRoom) {
    if (!row || row.displayKind === 'none') continue;
    const model = str(row.radiatorModel);
    if (!model || model === '—') continue;
    const units = Math.max(1, Math.trunc(row.unitsCount ?? 1) || 1);
    const unitCatalog =
      typeof row.unitPriceUah === 'number' && Number.isFinite(row.unitPriceUah)
        ? money(row.unitPriceUah)
        : null;

    /** @type {number | null} */
    let applianceUnitPrice = null;
    /** @type {number | null} */
    let lineTotal = null;
    /** @type {string} */
    let modelLabel = model;

    if (row.priceBasis === 'panel') {
      applianceUnitPrice = unitCatalog;
      lineTotal = unitCatalog != null ? money(unitCatalog * units) : null;
    } else if (
      row.priceBasis === 'section'
      && typeof row.sections === 'number'
      && Number.isFinite(row.sections)
      && row.sections > 0
    ) {
      const sections = Math.trunc(row.sections);
      modelLabel = `${model}, ${sections} сек.`;
      applianceUnitPrice =
        unitCatalog != null ? money(unitCatalog * sections) : null;
      lineTotal =
        applianceUnitPrice != null ? money(applianceUnitPrice * units) : null;
    }

    const meta = rooms.get(str(row.roomId));
    const floorLabel = meta ? `Поверх ${meta.floor}` : '';
    const roomName = str(row.roomName) || meta?.name || str(row.roomId);

    out.push(
      line({
        id: `radiator:${modelLabel}:${applianceUnitPrice ?? 'x'}`,
        kind: 'equipment',
        objectType,
        equipmentTypeLabel: 'Радіатор',
        brand: '',
        model: modelLabel,
        qty: units,
        qtyUnit: 'pcs',
        unitPriceUah: applianceUnitPrice,
        lineTotalUah: lineTotal,
        scopePath: scope(objectType, 'radiators', [floorLabel, roomName]),
        categoryId: 'radiators',
        source: 'matching.radiators.byRoom',
      }),
    );
  }
}

/**
 * @param {BuildingObjectType} objectType
 * @param {import('../types/shared-types.js').MatchingReport | undefined} matching
 * @param {FinancialBomLine[]} out
 */
function pushManifolds(objectType, matching, out) {
  const m = matching?.manifolds;
  if (!m || m.ok === false) return;

  for (const floorBlock of m.underfloor ?? []) {
    const floor = floorBlock?.floor;
    const floorLabel =
      typeof floor === 'number' && Number.isFinite(floor)
        ? `Поверх ${Math.trunc(floor)}`
        : '';
    for (const unit of floorBlock?.units ?? []) {
      const sel = unit?.selected;
      if (!sel?.model) continue;
      const price =
        typeof sel.price === 'number' && Number.isFinite(sel.price)
          ? money(sel.price)
          : null;
      out.push(
        line({
          id: `manifold.ufh:${sel.model}:${sel.article ?? unit.index}`,
          kind: 'equipment',
          objectType,
          equipmentTypeLabel: 'Колектор ТП',
          brand: readBrand(sel),
          model: sel.model,
          qty: 1,
          qtyUnit: 'pcs',
          unitPriceUah: price,
          lineTotalUah: price,
          scopePath: scope(objectType, 'ufh', [floorLabel, 'Колектор ТП']),
          categoryId: 'ufh',
          source: 'matching.manifolds.underfloor',
        }),
      );
    }
  }

  const rad = m.radiator?.selected;
  if (rad?.model) {
    const price =
      typeof rad.price === 'number' && Number.isFinite(rad.price)
        ? money(rad.price)
        : null;
    out.push(
      line({
        id: `manifold.radiator:${rad.model}`,
        kind: 'equipment',
        objectType,
        equipmentTypeLabel: 'Колектор радіаторів',
        brand: readBrand(rad),
        model: rad.model,
        qty: 1,
        qtyUnit: 'pcs',
        unitPriceUah: price,
        lineTotalUah: price,
        scopePath: scope(objectType, 'radiators'),
        categoryId: 'radiators',
        source: 'matching.manifolds.radiator',
      }),
    );
  }

  const bm = m.boilerManifold?.selected;
  if (bm?.model) {
    const price =
      typeof bm.price === 'number' && Number.isFinite(bm.price)
        ? money(bm.price)
        : null;
    out.push(
      line({
        id: `manifold.boiler:${bm.model}`,
        kind: 'equipment',
        objectType,
        equipmentTypeLabel: 'Котельний колектор',
        brand: readBrand(bm),
        model: bm.model,
        qty: 1,
        qtyUnit: 'pcs',
        unitPriceUah: price,
        lineTotalUah: price,
        scopePath: scope(objectType, 'boiler_room'),
        categoryId: 'boiler_room',
        source: 'matching.manifolds.boilerManifold',
      }),
    );
  }
}

