/**
 * Структурированные WARN_* / REC_* по подбору труб pipeline.
 * @param {object} args
 * @param {import('../hydraulics/types.js').HydraulicsMatchingReport} args.hydraulicsMatching
 * @param {import('../types/shared-types.js').HydraulicsReport} args.hydraulics
 * @param {import('../dhw/types.js').HydraulicsApplianceRulesDoc} args.hydraulicsRules
 * @param {string[]} args.warnings
 * @param {import('../recommendations/types.js').RecommendationsBundle} args.recommendations
 * @returns {import('../recommendations/types.js').ResolvedRecommendation[]}
 */
function applyHydraulicsPipeRecommendations({
  hydraulicsMatching,
  hydraulics,
  hydraulicsRules,
  warnings,
  recommendations,
}) {
  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const resolved = [];
  const edgesById = new Map(
    (hydraulics.graph?.edges ?? []).map((edge) => [edge.id, edge]),
  );
  const nodesById = new Map(
    (hydraulics.graph?.nodes ?? []).map((node) => [node.id, node]),
  );

  for (const pipe of hydraulicsMatching.pipes ?? []) {
    const edge = edgesById.get(pipe.edgeId);
    const vMax =
      edge?.isMainLine === true || edge?.segmentRole === 'main'
        ? hydraulicsRules.velocityLimitsMps.mainMax
        : hydraulicsRules.velocityLimitsMps.branchMax;
    const vMin =
      edge?.isMainLine === true
        ? hydraulicsRules.velocityLimitsMps.mainMin
        : edge?.segmentRole === 'main'
          ? hydraulicsRules.velocityLimitsMps.mainMin
          : (hydraulicsRules.velocityLimitsMps.branchMin ?? 0);

    if (pipe.catalogPoolExhausted) {
      const minInternal = edge?.isMainLine === true
        ? hydraulicsRules.mainTransitMinInternalDiameterMm
        : hydraulicsRules.branchMinInternalDiameterMm;
      pushRecommendation(
        warnings,
        resolved,
        recommendations,
        'WARN_PIPE_CATALOG_NO_INTERNAL_DIAMETER',
        {
          edgeId: pipe.edgeId,
          minInternalDiameterMm: minInternal,
        },
      );
      continue;
    }

    if (pipe.velocityLimitExceeded) {
      pushRecommendation(
        warnings,
        resolved,
        recommendations,
        'WARN_PIPE_VELOCITY_EXCEEDED',
        {
          edgeId: pipe.edgeId,
          velocityMps: Math.round(pipe.velocityMps * 100) / 100,
          velocityMaxMps: vMax,
          catalogPipeId: pipe.catalogPipeId,
        },
      );
    } else if (pipe.velocityBelowMin) {
      if (pipe.mainTransitGuardApplied) {
        pushRecommendation(
          warnings,
          resolved,
          recommendations,
          'WARN_PIPE_MAIN_TRANSIT_LOW_VELOCITY',
          {
            edgeId: pipe.edgeId,
            velocityMps: Math.round(pipe.velocityMps * 100) / 100,
            velocityMinMps: vMin,
            catalogPipeId: pipe.catalogPipeId,
            minInternalDiameterMm: hydraulicsRules.mainTransitMinInternalDiameterMm,
          },
        );
      } else {
        pushRecommendation(
          warnings,
          resolved,
          recommendations,
          'WARN_PIPE_VELOCITY_BELOW_MIN',
          {
            edgeId: pipe.edgeId,
            velocityMps: Math.round(pipe.velocityMps * 100) / 100,
            velocityMinMps: vMin,
            catalogPipeId: pipe.catalogPipeId,
          },
        );
      }
    } else if (pipe.mainTransitGuardApplied) {
      pushRecommendation(
        warnings,
        resolved,
        recommendations,
        'REC_PIPE_MAIN_TRANSIT_GUARD_APPLIED',
        {
          edgeId: pipe.edgeId,
          catalogPipeId: pipe.catalogPipeId,
          internalDiameterMm: pipe.internalDiameterMm,
          minInternalDiameterMm: hydraulicsRules.mainTransitMinInternalDiameterMm,
        },
      );
    }
  }

  for (const node of nodesById.values()) {
    if (node.kind !== 'radiator_manifold' || !node.roomIds?.length) continue;
    const manifoldEdge = (hydraulics.graph?.edges ?? []).find(
      (e) => e.to === node.id && e.segmentRole === 'branch',
    );
    pushRecommendation(
      warnings,
      resolved,
      recommendations,
      'REC_RADIATOR_MICRO_BRANCH_MANIFOLD',
      {
        roomCount: node.roomIds.length,
        roomNames: node.label,
        totalFlowM3PerHour: manifoldEdge?.designFlowM3PerHour ?? 0,
      },
    );
  }

  const builtinDuty = hydraulicsMatching.builtinPumpDuty;
  if (builtinDuty?.status === 'below_manufacturer_qmin') {
    pushRecommendation(
      warnings,
      resolved,
      recommendations,
      'WARN_BOILER_HEATING_FLOW_BELOW_MIN',
      {
        designFlowM3PerHour: builtinDuty.designFlowM3PerHour,
        qMinM3h: builtinDuty.heatingCircuitMinFlowM3h,
        catalogBoilerModel: builtinDuty.catalogBoilerModel ?? builtinDuty.catalogBoilerId ?? 'котел',
      },
    );
  }

  return resolved;
}

/**
 * @param {object} args
 * @param {import('../types/shared-types.js').CalcRequestBody} args.input
 * @param {import('../types/shared-types.js').CalcRuntimeContext} args.ctx
 * @returns {Promise<import('../types/shared-types.js').CalcReport>}
 */
export async function buildReport({ input, ctx }) {
  assertCalcRuntimeContext(ctx);
  const {
    catalog,
    waterNorms,
    appliances,
    recommendations,
    ufhPresets,
    sources,
  } = ctx;
  const catalogSource = sources.catalog;
  const waterNormsSource = sources.waterNorms;
  const appliancesSource = sources.appliances;
  const recommendationsSource = sources.recommendations;
  const ufhPresetsSource = sources.ufhPresets;
  const referenceBundleLoadedAt = sources.loadedAt;
  const ufhPresetsSchemaVersion = ufhPresets.schemaVersion;
  const warnings = [];
  logger.info('report.build.start', null);

  // 1) Клімат / розрахункова зовнішня температура
  let climate = null;
  const inputTemps = input.building?.temps ?? input.temps ?? null;
  if (input.location && inputTemps?.outsideC == null) {
    logger.info('report.climate.start', null, { hasLocation: true });
    climate = await getDesignOutsideTempC(input.location);
    if (climate?.designOutsideTempC == null) {
      warnings.push(
        'Не вдалося визначити розрахункову зовнішню температуру за геолокацією — задайте temps.outsideC вручну.',
      );
    }
  }

  const temps = {
    insideC: inputTemps?.insideC,
    outsideC: inputTemps?.outsideC ?? climate?.designOutsideTempC,
    ...(typeof inputTemps?.bathroomAirTempC === 'number' &&
    Number.isFinite(inputTemps.bathroomAirTempC)
      ? { bathroomAirTempC: inputTemps.bathroomAirTempC }
      : {}),
  };
  if (temps.insideC == null) {
    throw createAppError(
      'Не задано внутрішню температуру building.temps.insideC.',
      'INSIDE_TEMP_REQUIRED',
      400,
    );
  }
  if (temps.outsideC == null) {
    throw createAppError(
      'Не задано зовнішню температуру temps.outsideC і не отримано клімат.',
      'OUTSIDE_TEMP_REQUIRED',
      400,
    );
  }

  /** @type {{ insideC: number, outsideC: number, bathroomAirTempC?: number }} */
  const designTemps = {
    insideC: temps.insideC,
    outsideC: temps.outsideC,
    ...(typeof temps.bathroomAirTempC === 'number'
      ? { bathroomAirTempC: temps.bathroomAirTempC }
      : {}),
  };

  // Прокинути bathroomAirTempC у building.temps (радіатори / shared resolve).
  if (input.building && typeof designTemps.bathroomAirTempC === 'number') {
    const bt = input.building.temps ?? { insideC: designTemps.insideC };
    input.building.temps = {
      ...bt,
      insideC: bt.insideC ?? designTemps.insideC,
      bathroomAirTempC: designTemps.bathroomAirTempC,
    };
  }

  // 2) Теплопотери (по комнатам/элементам)
  logger.info('report.heatloss.start', null, {
    rooms: input.building?.rooms?.length ?? 0,
    elements: input.building?.envelopeElements?.length ?? 0,
  });
  const heatLoss = calculateHeatLossForBuilding({
    temps: designTemps,
    building: input.building,
  });
  logger.info('report.heatloss.done', null, { totalWatts: heatLoss.totalWatts });

  // 2b) Водяной тёплый пол — теплоотдача вверх/вниз, Tповерх
  const underfloorHeating = calculateUnderfloorHeating({
    temps: designTemps,
    building: input.building,
    heatingSystem: input.heatingSystem,
    heatLoss,
    ufhPresets,
    maxUfhLoopLengthM: appliances.byKind.hydraulics.maxUfhLoopLengthM,
    ufhLoopLengthLayoutFactor:
      appliances.byKind.hydraulics.ufhLoopLengthLayoutFactor,
  });
  if (underfloorHeating?.rooms?.length) {
    enrichUnderfloorHeatingLoopHydraulics(underfloorHeating, {
      catalog,
      hydraulicsRules: appliances.byKind.hydraulics,
      materialPreference: input.hydraulics?.pipeMaterialPreference,
    });
    applyUfhLoopHydraulicsRecommendations(
      underfloorHeating,
      recommendations,
      appliances.byKind.hydraulics,
    );
    applyUnderfloorHeatingRecommendations(underfloorHeating, recommendations, {
      heatingEmittersMode: input.heatingSystem?.heatingEmittersMode ?? null,
    });
    logger.info('report.underfloorHeating.done', null, {
      rooms: underfloorHeating.rooms.length,
      totalHeatFluxUpWatts: underfloorHeating.totalHeatFluxUpWatts,
    });
  }

  // 3) Гаряче водопостачання (ГВП) — тип объекта влияет на нормы и одновременность
  const objectType = input.building?.objectMeta?.objectType;
  const objectTypeNorm =
    objectType === 'apartment' || objectType === 'house' ? objectType : 'house';

  const activeScheme =
    input.heatingSystem?.hotWaterBoilerPowerMatchingScheme ??
    SCHEME_BOILER_MAX_COMBI;
  const hsRecord =
    input.heatingSystem && typeof input.heatingSystem === 'object'
      ? /** @type {Record<string, unknown>} */ (input.heatingSystem)
      : null;
  const apartmentIndirectStorage =
    hsRecord?._apartmentIndirectDhwStorage === true &&
    activeScheme === SCHEME_BOILER_SINGLE_INDIRECT_SUM &&
    objectTypeNorm === 'apartment';

  /** @type {{ dhwSupplyScenarioOverride?: 'flowThrough' | 'storage' }} */
  const hotWaterOptions = apartmentIndirectStorage
    ? { dhwSupplyScenarioOverride: 'storage' }
    : objectTypeNorm === 'apartment' &&
        activeScheme === SCHEME_BOILER_ELECTRIC_SEPARATE
      ? { dhwSupplyScenarioOverride: 'storage' }
      : {};

  let hotWaterInitial = calculateHotWaterDemand(
    {
      ...(input.hotWater ?? {}),
      objectType: objectTypeNorm,
    },
    waterNorms,
    hotWaterOptions,
  );

  const tropicalShower = hotWaterInitial.tropicalShower === true;

  if (
    objectTypeNorm === 'apartment' &&
    activeScheme === SCHEME_BOILER_ELECTRIC_SEPARATE
  ) {
    const tankLiters = recommendedApartmentElectricTankLiters(
      waterNorms,
      hotWaterInitial.residents ?? 0,
      tropicalShower,
    );
    hotWaterInitial = {
      ...hotWaterInitial,
      recommendedTankLiters: tankLiters ?? 0,
    };
  }

  if (activeScheme === SCHEME_BOILER_COMBI_BUFFER_ELECTRIC) {
    const tankLiters = recommendedCombiBufferTankLiters(
      waterNorms,
      hotWaterInitial.residents ?? 0,
      tropicalShower,
    );
    hotWaterInitial = {
      ...hotWaterInitial,
      recommendedTankLiters: tankLiters ?? 0,
    };
  }

  if (activeScheme === SCHEME_BOILER_SINGLE_BUFFER_ELECTRIC) {
    const tankLiters = recommendedSingleCircuitBufferTankLiters(
      waterNorms,
      hotWaterInitial.residents ?? 0,
      tropicalShower,
    );
    hotWaterInitial = {
      ...hotWaterInitial,
      recommendedTankLiters: tankLiters ?? 0,
      dhwSupplyScenario: 'storage',
    };
  }
  logger.info('report.hotwater.done', null, {
    hotWaterPowerKw: hotWaterInitial?.hotWaterPowerKw ?? null,
    recommendedTankLiters: hotWaterInitial?.recommendedTankLiters ?? null,
    peakFlowLps: hotWaterInitial?.peakFlowLps ?? null,
  });

  const isUfhOnly = input.heatingSystem?.heatingEmittersMode === 'ufh_only';
  const heatingReserveFactor =
    appliances.byKind.boiler.matching.heatingReserveFactor;
  const heatingBaseKw =
    isUfhOnly && underfloorHeating?.totalHeatFluxUpWatts
      ? underfloorHeating.totalHeatFluxUpWatts / 1000
      : heatLoss.totalWatts / 1000;

  const automationHints = buildMatchingAutomationHints({
    objectType: objectTypeNorm,
    hotWaterReport: hotWaterInitial,
    activeScheme,
    building: input.building,
    heatingLoadKw: heatingBaseKw * heatingReserveFactor,
    apartmentClassification: appliances.byKind.boiler.apartmentClassification,
  });

  // 4) Подбор оборудования
  logger.info('report.matching.start', null);
  const { matching, hotWaterForCalculations } = matchEquipment({
    heatLoss,
    hotWater: hotWaterInitial,
    heatingSystem: input.heatingSystem ?? {},
    building: input.building,
    underfloorHeating,
    hydraulics: input.hydraulics,
    ctx,
  });

  const hotWater = hotWaterForCalculations ?? hotWaterInitial;

  if (underfloorHeating?.rooms?.length && matching.radiators) {
    matching.radiators.radiatorSelectionNotes = [
      ...(matching.radiators.radiatorSelectionNotes ?? []),
      ...buildWarmFloorCalcMatchingNotes(underfloorHeating),
    ];
  }

  appendApartmentCombiSerialBufferAutomationHint(automationHints, {
    objectType: objectTypeNorm,
    requestedScheme: activeScheme,
    circuitFallback: matching.boiler?.circuitFallback ?? null,
    hotWaterReport: hotWater,
    serialBufferConfig: appliances.byKind.boiler.hints.apartmentCombiSerialBuffer,
    recommendations,
  });

  appendApartmentSingleOversizeCombiHint(automationHints, {
    objectType: objectTypeNorm,
    requestedScheme: activeScheme,
    circuitFallback: matching.boiler?.circuitFallback ?? null,
    resolvedRecommendations: matching.boiler?.resolvedRecommendations ?? [],
    recommendations,
  });

  const reqBoilerKw = matching.boiler?.requiredKw;

  if (underfloorHeating?.isMixingNodeRequired) {
    const requestedPreset =
      input.heatingSystem?.underfloorDistributionPreset ?? 'auto';
    const ufhAppliance = appliances.byKind.underfloor_heating;
    const minBoilerKw = ufhAppliance.distribution.autoHydraulicSeparatorMinBoilerKw;
    const resolvedPreset = resolveUfhDistributionWithAppliances(
      requestedPreset,
      {
        objectType: input.building?.objectMeta?.objectType,
        roomsWithUfhCount: underfloorHeating.rooms?.length ?? 0,
        requiredBoilerKw: reqBoilerKw,
      },
      appliances,
    );
    const prevPreset = underfloorHeating.distributionPreset;
    underfloorHeating.distributionPreset = resolvedPreset;

    if (
      (requestedPreset === 'auto' || requestedPreset == null)
      && typeof reqBoilerKw === 'number'
      && reqBoilerKw > minBoilerKw
      && resolvedPreset === 'hydraulic_separator'
      && prevPreset !== 'hydraulic_separator'
    ) {
      underfloorHeating.warnings = [
        ...(underfloorHeating.warnings ?? []),
        `Схема ТП (авто): за потужності котла > ${minBoilerKw} кВт обрано гідравлічну стрілку.`,
      ];
    }

    const primaryRoom = underfloorHeating.rooms?.[0];
    underfloorHeating.mixingNode = computeUfhMixingNodeSpec({
      powerKw: (underfloorHeating.totalHeatFluxUpWatts ?? 0) / 1000,
      deltaTK: ufhAppliance.mixingNode.deltaTK,
      distributionPreset: resolvedPreset,
      mixingNodeRules: ufhAppliance.mixingNode,
    });
    if (typeof input.heatingSystem?.supplyC === 'number') {
      underfloorHeating.mixingNode.boilerSupplyC = input.heatingSystem.supplyC;
    }
    if (typeof primaryRoom?.circuitSupplyC === 'number') {
      underfloorHeating.mixingNode.floorCircuitSupplyC = primaryRoom.circuitSupplyC;
    }

    applyUnderfloorMixingDistributionRecommendations(
      underfloorHeating,
      {
        requestedPreset,
        resolvedPreset,
        minBoilerKw,
        requiredBoilerKw: reqBoilerKw,
      },
      recommendations,
    );
  }

  // 4b) Підбір колекторів — soft-fail: не валимо весь report
  /** @type {import('../types/shared-types.js').ManifoldsMatchingReport} */
  let manifoldsReport;
  try {
    manifoldsReport = pickManifolds({
      catalog: ctx.catalog,
      building: input.building,
      underfloorHeating,
      radiators: matching.radiators,
      boiler: matching.boiler,
      hydraulics: input.hydraulics,
    });
  } catch (err) {
    // Страховка, якщо контракт модуля порушено (pickManifolds не повинен кидати)
    const known = isPlainObject(err)
      ? /** @type {import('../types/shared-types.js').AppErrorLike & { message?: string }} */ (err)
      : null;
    logger.warn('matching.manifold.throw', null, {
      code: 'MANIFOLD_INTERNAL',
      message: known?.message ?? null,
    }, err);
    manifoldsReport = buildEmptyManifoldsFailure({
      failureCode: 'MANIFOLD_INTERNAL',
      message:
        'Кошторис колекторів порожній; розрахунок унібоксів і гідравліки продовжується.',
      ...(known?.message ? { causeMessage: String(known.message) } : {}),
    });
  }

  if (!manifoldsReport || typeof manifoldsReport.ok !== 'boolean') {
    logger.warn('matching.manifold.invalid_shape', null, {
      shape: manifoldsReport == null ? 'null' : typeof manifoldsReport,
    });
    manifoldsReport = buildEmptyManifoldsFailure({
      failureCode: 'MANIFOLD_INTERNAL',
      message: 'Некоректна відповідь підбору колекторів.',
    });
  }

  matching.manifolds = manifoldsReport;

  if (manifoldsReport.ok === false) {
    logger.info('report.matching.manifolds.degraded', null, {
      failureCode: manifoldsReport.failureCode ?? null,
      warnings: manifoldsReport.warnings?.length ?? 0,
    });
  }

  // 4c) Підбір унібоксів — завжди після колекторів (навіть при ok: false)
  const roomAirTempC =
    typeof input.temps?.insideC === 'number'
      ? input.temps.insideC
      : typeof input.building?.temps?.insideC === 'number'
        ? input.building.temps.insideC
        : undefined;
  matching.uniboxes = pickUniboxes({
    catalog: ctx.catalog,
    underfloorHeating,
    ...(roomAirTempC !== undefined ? { roomAirTempC } : {}),
    ...(typeof designTemps.bathroomAirTempC === 'number'
      ? { bathroomAirTempC: designTemps.bathroomAirTempC }
      : {}),
    manifolds: matching.manifolds,
    rooms: input.building?.rooms,
  });

  logger.info('report.matching.done', null, {
    boilerModel: matching?.boiler?.selected?.model ?? null,
    requiredBoilerKw: matching?.boiler?.requiredKw ?? null,
    radiatorModel: matching?.radiators?.chosen?.model ?? null,
    waterHeaterModel: matching?.waterHeater?.selected?.model ?? null,
    indirectWaterHeaterModel: matching?.indirectWaterHeater?.selected?.model ?? null,
    waterHeaterVolumeLiters: matching?.waterHeater?.chosenVariant?.volumeLiters ?? null,
    manifoldsOk: matching?.manifolds?.ok ?? null,
    manifoldsFailureCode: matching?.manifolds?.failureCode ?? null,
    manifoldUnderfloorCount: matching?.manifolds?.underfloor?.length ?? 0,
    manifoldUnderfloorUnits:
      matching?.manifolds?.underfloor?.reduce(
        /**
         * @param {number} s
         * @param {import('../types/shared-types.js').ManifoldUnderfloorPick} f
         */
        (s, f) => s + (f.units?.length ?? 0),
        0,
      ) ?? 0,
    manifoldRadiatorModel: matching?.manifolds?.radiator?.selected?.model ?? null,
    boilerManifoldModel: matching?.manifolds?.boilerManifold?.selected?.model ?? null,
    uniboxLoopCount: matching?.uniboxes?.byLoop?.length ?? 0,
    uniboxSelectedCount:
      matching?.uniboxes?.byLoop?.filter(
        /** @param {import('../types/shared-types.js').UniboxLoopPick} row */
        (row) => row.selected,
      )?.length ?? 0,
    warnings: (matching?.boiler?.warnings?.length ?? 0)
      + (matching?.radiators?.warnings?.length ?? 0)
      + (matching?.waterHeater?.warnings?.length ?? 0)
      + (matching?.indirectWaterHeater?.warnings?.length ?? 0)
      + (matching?.manifolds?.warnings?.length ?? 0)
      + (matching?.uniboxes?.warnings?.length ?? 0),
  });

  // 5) Гідравліка Pure Pipeline (после matching)
  logger.info('report.hydraulics.start', null);
  /** @type {import('../types/shared-types.js').HydraulicsReport} */
  let hydraulics;
  try {
    const pipelineDto = buildHydraulicsSnapshots({
      input,
      hotWater,
      underfloorHeating,
      matching,
      hydraulicsRules: appliances.byKind.hydraulics,
    });
    await validateHydraulicsPipelineInput(pipelineDto);
    const pipelineResult = runHydraulicsPipeline({
      dto: pipelineDto,
      catalog: ctx.catalog,
    });
    hydraulics = pipelineResult.hydraulics;
    matching.hydraulics = pipelineResult.hydraulicsMatching;
    const hydraulicsResolved = applyHydraulicsPipeRecommendations({
      hydraulicsMatching: pipelineResult.hydraulicsMatching,
      hydraulics: pipelineResult.hydraulics,
      hydraulicsRules: appliances.byKind.hydraulics,
      warnings,
      recommendations,
    });
    if (hydraulicsResolved.length) {
      matching.hydraulics.resolvedRecommendations = hydraulicsResolved;
    }
    if (pipelineResult.hydraulicsMatching.warnings?.length) {
      warnings.push(...pipelineResult.hydraulicsMatching.warnings);
    }
  } catch (hydErr) {
    const known = isPlainObject(hydErr)
      ? /** @type {import('../types/shared-types.js').AppErrorLike & { message?: string }} */ (hydErr)
      : null;
    logger.warn('report.hydraulics.fail', null, {
      code: known?.code ?? null,
    }, hydErr);
    const hydraulicsFailMessage =
      known?.message
        ? `Гідравліка: ${known.message}`
        : 'Гідравліка: не вдалося виконати pipeline.';
    warnings.push(hydraulicsFailMessage);
    hydraulics = {
      schemaVersion: 1,
      notes: ['Розрахунок гідравліки pipeline не виконано — див. warnings.'],
    };
    matching.hydraulics = {
      proposal: {
        designFlowM3PerHour: 0,
        headRequiredM: 0,
        pipeLines: [],
        pipeSegments: [],
        pumps: [],
        estimatedPipesPrice: 0,
        estimatedPumpPrice: 0,
        estimatedTotalPrice: 0,
        unavailableReason: known?.message ?? 'Розрахунок гідравліки не виконано.',
      },
      warnings: [hydraulicsFailMessage],
      pipes: [],
    };
  }
  logger.info('report.hydraulics.done', null, {
    flowRateM3PerHour: hydraulics?.flowRateM3PerHour ?? null,
    headRequiredM: hydraulics?.pressure?.headRequiredM ?? null,
  });

  const allWarnings = [
    ...warnings,
    ...(underfloorHeating?.warnings ?? []),
    ...(matching.boiler?.warnings ?? []),
    ...(matching.radiators?.warnings ?? []),
    ...(matching.waterHeater?.warnings ?? []),
    ...(matching.indirectWaterHeater?.warnings ?? []),
    ...(matching.manifolds?.warnings ?? []),
    ...(matching.uniboxes?.warnings ?? []),
    ...(matching.hydraulics?.warnings ?? []),
  ];

  /** @type {import('../recommendations/types.js').ResolvedRecommendation[]} */
  const reportRecommendations = [
    ...(matching.boiler?.resolvedRecommendations ?? []),
    ...(matching.indirectWaterHeater?.resolvedRecommendations ?? []),
    ...(underfloorHeating?.resolvedRecommendations ?? []),
    ...(matching.radiators?.resolvedRecommendations ?? []),
    ...(matching.hydraulics?.resolvedRecommendations ?? []),
  ];

  /** Внутренние флаги нормализации не попадают в echo input отчёта. */
  const inputForReport = structuredClone(input);
  if (
    inputForReport.heatingSystem &&
    typeof inputForReport.heatingSystem === 'object'
  ) {
    const hsClean = /** @type {Record<string, unknown>} */ ({
      ...inputForReport.heatingSystem,
    });
    delete hsClean._apartmentIndirectDhwStorage;
    delete hsClean._normalizationWarnings;
    delete hsClean._thermalRegimeAutoAdjusted;
    inputForReport.heatingSystem =
      /** @type {import('../types/shared-types.js').HeatingSystemInput} */ (hsClean);
  }

  const commercial = buildFinancialBom({
    input: inputForReport,
    matching,
    underfloorHeating: underfloorHeating ?? null,
  });
  logger.info('report.commercial.done', null, {
    equipmentLines: commercial.lines.filter((l) => l.kind === 'equipment').length,
    equipmentTotalUah: commercial.totals.equipmentTotalUah,
    grandTotalUah: commercial.totals.grandTotalUah,
  });

  return {
    meta: {
      generatedAt: new Date().toISOString(),
      schemaVersion: 1,
      catalogSource,
      waterNormsSource,
      waterNormsSchemaVersion: waterNorms.schemaVersion,
      appliancesSource,
      appliancesSchemaVersions: appliances.schemaVersions,
      ...(typeof referenceBundleLoadedAt === 'number' && Number.isFinite(referenceBundleLoadedAt)
        ? { referenceBundleLoadedAt: new Date(referenceBundleLoadedAt).toISOString() }
        : {}),
      recommendationsSource,
      ufhPresetsSource,
      ...(typeof ufhPresetsSchemaVersion === 'number'
        ? { ufhPresetsSchemaVersion }
        : {}),
      automationHints,
    },
    input: inputForReport,
    climate,
    temps: designTemps,
    calculations: {
      heatLoss,
      hotWater,
      hydraulics,
      underfloorHeating: underfloorHeating ?? null,
    },
    matching,
    commercial,
    ...(reportRecommendations.length > 0
      ? { recommendations: reportRecommendations }
      : {}),
    warnings: allWarnings,
  };
}

/**
 * Назначение: валидация и нормализация underfloor_heating_presets.
 * Описание: Проверка документов из Mongo/file; derive supplyC/returnC (Δt=10 K).
 */
import { UFH_MODE_PRESET_IDS, isUfhModePresetId } from '../../../shared/ufhModePresetIds.js';

const UFH_CIRCUIT_DELTA_T_K = 10;

/**
 * @param {unknown} value
 * @param {string} path
 * @returns {number}
 */
function requireFiniteNum(value, path) {
  const n = Number(value);
  if (!Number.isFinite(n)) {
    throw new Error(`${path}: ожидается число`);
  }
  return n;
}

/**
 * @param {unknown} value
 * @param {string} path
 * @returns {boolean}
 */
function requireBoolean(value, path) {
  if (typeof value !== 'boolean') {
    throw new Error(`${path}: ожидается boolean`);
  }
  return value;
}

/**
 * @param {unknown} value
 * @param {string} path
 * @returns {string}
 */
function requireNonEmptyString(value, path) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${path}: ожидается непустая строка`);
  }
  return value.trim();
}

/**
 * @param {Record<string, unknown>} raw
 * @returns {import('./types.js').NormalizedUfhModePreset}
 */
function normalizeOnePreset(raw) {
  const presetId = requireNonEmptyString(raw.presetId, 'underfloor_heating_presets.presetId');
  if (!isUfhModePresetId(presetId)) {
    throw new Error(`underfloor_heating_presets: неизвестный presetId "${presetId}"`);
  }

  const technicalRaw = raw.technical;
  if (!technicalRaw || typeof technicalRaw !== 'object') {
    throw new Error(`underfloor_heating_presets[${presetId}].technical: обязателен`);
  }
  /** @type {Record<string, unknown>} */
  const tech = /** @type {Record<string, unknown>} */ (technicalRaw);

  const maxSupplyTemperatureC = requireFiniteNum(
    tech.maxSupplyTemperatureC,
    `underfloor_heating_presets[${presetId}].technical.maxSupplyTemperatureC`,
  );
  const maxSurfaceTemperatureC = requireFiniteNum(
    tech.maxSurfaceTemperatureC,
    `underfloor_heating_presets[${presetId}].technical.maxSurfaceTemperatureC`,
  );
  const hasMixingNode = requireBoolean(
    tech.hasMixingNode,
    `underfloor_heating_presets[${presetId}].technical.hasMixingNode`,
  );
  const requiresCondensingBoiler = requireBoolean(
    tech.requiresCondensingBoiler,
    `underfloor_heating_presets[${presetId}].technical.requiresCondensingBoiler`,
  );

  const supplyC = maxSupplyTemperatureC;
  const returnC = supplyC - UFH_CIRCUIT_DELTA_T_K;

  const uiRaw = raw.ui;
  if (!uiRaw || typeof uiRaw !== 'object') {
    throw new Error(`underfloor_heating_presets[${presetId}].ui: обязателен`);
  }
  /** @type {Record<string, unknown>} */
  const uiObj = /** @type {Record<string, unknown>} */ (uiRaw);

  return {
    presetId,
    technical: {
      hasMixingNode,
      requiresCondensingBoiler,
      maxSupplyTemperatureC,
      maxSurfaceTemperatureC,
      supplyC,
      returnC,
    },
    ui: {
      title: requireNonEmptyString(uiObj.title, `underfloor_heating_presets[${presetId}].ui.title`),
      badge: requireNonEmptyString(uiObj.badge, `underfloor_heating_presets[${presetId}].ui.badge`),
      description: requireNonEmptyString(
        uiObj.description,
        `underfloor_heating_presets[${presetId}].ui.description`,
      ),
    },
  };
}

/**
 * @param {unknown} json — массив документов или один bundle-объект
 * @returns {import('./types.js').UnderfloorHeatingPresetsBundle}
 */
export function validateAndNormalizeUnderfloorHeatingPresets(json) {
  /** @type {unknown[]} */
  let docs;
  if (Array.isArray(json)) {
    docs = json;
  } else if (json && typeof json === 'object' && Array.isArray(/** @type {{ presets?: unknown[] }} */ (json).presets)) {
    docs = /** @type {{ presets: unknown[] }} */ (json).presets;
  } else {
    throw new Error('underfloor_heating_presets: ожидается массив документов');
  }

  const activeDocs = docs.filter((d) => {
    if (!d || typeof d !== 'object') return false;
    return /** @type {{ isActive?: boolean }} */ (d).isActive !== false;
  });

  /** @type {import('./types.js').NormalizedUfhModePreset[]} */
  const presets = [];
  /** @type {Record<string, import('./types.js').NormalizedUfhModePreset>} */
  const byPresetId = {};

  for (const doc of activeDocs) {
    const normalized = normalizeOnePreset(/** @type {Record<string, unknown>} */ (doc));
    if (byPresetId[normalized.presetId]) {
      throw new Error(`underfloor_heating_presets: дубликат presetId "${normalized.presetId}"`);
    }
    presets.push(normalized);
    byPresetId[normalized.presetId] = normalized;
  }

  for (const id of UFH_MODE_PRESET_IDS) {
    if (!byPresetId[id]) {
      throw new Error(`underfloor_heating_presets: отсутствует обязательный presetId "${id}"`);
    }
  }

  const schemaVersion =
    activeDocs[0] &&
    typeof activeDocs[0] === 'object' &&
    /** @type {{ meta?: { schemaVersion?: number } }} */ (activeDocs[0]).meta?.schemaVersion != null
      ? Math.trunc(
          Number(/** @type {{ meta: { schemaVersion: number } }} */ (activeDocs[0]).meta.schemaVersion),
        )
      : 1;

  return {
    schemaVersion: Number.isFinite(schemaVersion) && schemaVersion > 0 ? schemaVersion : 1,
    presets,
    byPresetId,
  };
}

/**
 * Назначение: критерии классификации квартиры и вспомогательные расчёты для подбора котла.
 * Описание: Пороговые значения из appliances.boiler.apartmentClassification; площадь, санузлы, схемы ГВС.
 */

import { resolveObjectType } from './boilerMountingConstraints.js';

/**
 * @param {import('../dhw/types.js').BoilerApplianceRules['apartmentClassification'] | undefined} classification
 * @returns {import('../dhw/types.js').BoilerApplianceRules['apartmentClassification']}
 */
function resolveApartmentClassification(classification) {
  if (classification) return classification;
  throw new Error(
    'apartmentMatching: apartmentClassification обязателен (передайте appliances.byKind.boiler.apartmentClassification из CalcRuntimeContext).',
  );
}

/**
 * Суммарная площадь помещений, м².
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 */
export function sumRoomsAreaM2(building) {
  const rooms = building?.rooms;
  if (!Array.isArray(rooms)) return 0;
  return rooms.reduce((s, r) => s + (Number(r?.areaM2) || 0), 0);
}

/**
 * Число санузлов: комнаты type=bathroom/санузел или точки bath+shower ≥ порога.
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @param {import('../types/shared-types.js').HotWaterFixturesInput | undefined} fixtures
 */
export function countApartmentBathrooms(building, fixtures) {
  const rooms = building?.rooms ?? [];
  let fromRooms = 0;
  for (const r of rooms) {
    const t = String(r?.type ?? '').trim().toLowerCase();
    if (
      t === 'bathroom' ||
      t === 'санузел' ||
      t.includes('сануз') ||
      t.includes('bathroom')
    ) {
      fromRooms += 1;
    }
  }
  const fx = fixtures ?? {};
  const fromFixtures =
    (Number(fx.bath) || 0) + (Number(fx.shower) || 0);
  return Math.max(fromRooms, fromFixtures);
}

/**
 * «Большая квартира» по данным анкеты (до расчёта теплопотерь).
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @param {import('../types/shared-types.js').HotWaterFixturesInput | undefined} fixtures
 * @param {import('../dhw/types.js').BoilerApplianceRules['apartmentClassification']} apartmentClassification
 */
export function isLargeApartmentByInput(building, fixtures, apartmentClassification) {
  const objectMeta = building?.objectMeta;
  if (resolveObjectType(objectMeta) !== 'apartment') return false;
  const rules = resolveApartmentClassification(apartmentClassification);
  const area = sumRoomsAreaM2(building);
  const bathrooms = countApartmentBathrooms(building, fixtures);
  return (
    area > rules.largeAreaM2Min ||
    bathrooms >= rules.minBathroomsForLargeApartment
  );
}

/**
 * «Большая квартира» с учётом расчётной отопительной нагрузки, кВт (после heatLoss).
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @param {number} heatingLoadKw отопление × запас
 * @param {import('../types/shared-types.js').HotWaterFixturesInput | undefined} fixtures
 * @param {import('../dhw/types.js').BoilerApplianceRules['apartmentClassification']} apartmentClassification
 */
export function isLargeApartment(
  building,
  heatingLoadKw,
  fixtures,
  apartmentClassification,
) {
  if (isLargeApartmentByInput(building, fixtures, apartmentClassification)) return true;
  const objectMeta = building?.objectMeta;
  if (resolveObjectType(objectMeta) !== 'apartment') return false;
  const rules = resolveApartmentClassification(apartmentClassification);
  return Number(heatingLoadKw) > rules.largeHeatingLoadKwMin;
}

/**
 * Округлення потреби в літрах до типорозміру бака; опційно +tropicalShower.
 * @param {import('../dhw/types.js').NormalizedWaterNorms} norms
 * @param {number} needLiters
 * @param {boolean} [tropicalShower]
 * @returns {number}
 */
function snapTankLitersWithTropical(norms, needLiters, tropicalShower = false) {
  let need = Math.max(0, Math.ceil(Number(needLiters) || 0));
  if (tropicalShower) {
    need = Math.ceil(need * norms.storage.tropicalShowerVolumeFactor);
  }
  const sizes = norms.storage.typicalTankSizes;
  const fallback = sizes[sizes.length - 1];
  if (fallback === undefined) {
    throw new Error('water_norms.storage.typicalTankSizes пуст');
  }
  return sizes.find((t) => t >= need) ?? fallback;
}

/**
 * Объём электробойлера для квартиры (л) по норме apartmentElectricStorage.
 * @param {import('../dhw/types.js').NormalizedWaterNorms} norms
 * @param {number} residents
 * @param {boolean} [tropicalShower]
 */
export function recommendedApartmentElectricTankLiters(
  norms,
  residents,
  tropicalShower = false,
) {
  const aes = norms.apartmentElectricStorage;
  const pop = Math.max(0, Math.trunc(Number(residents) || 0));
  const raw = pop * aes.litersPerResident;
  const need = Math.max(aes.minTankLiters, Math.ceil(raw));
  return snapTankLitersWithTropical(norms, need, tropicalShower);
}

/**
 * Объём буферного электробойлера для схемы 2К + буфер (л) по норме combiBufferElectricStorage.
 * @param {import('../dhw/types.js').NormalizedWaterNorms} norms
 * @param {number} residents
 * @param {boolean} [tropicalShower]
 */
export function recommendedCombiBufferTankLiters(
  norms,
  residents,
  tropicalShower = false,
) {
  const cfg = norms.combiBufferElectricStorage;
  const pop = Math.max(0, Math.trunc(Number(residents) || 0));
  const raw = pop * cfg.litersPerResident;
  const need = Math.max(cfg.minTankLiters, Math.ceil(raw));
  return snapTankLitersWithTropical(norms, need, tropicalShower);
}

/**
 * Объём буферного электробойлера для схемы 1К + буфер (л) по норме singleCircuitBufferElectricStorage.
 * @param {import('../dhw/types.js').NormalizedWaterNorms} norms
 * @param {number} residents
 * @param {boolean} [tropicalShower]
 */
export function recommendedSingleCircuitBufferTankLiters(
  norms,
  residents,
  tropicalShower = false,
) {
  const cfg = norms.singleCircuitBufferElectricStorage;
  const pop = Math.max(0, Math.trunc(Number(residents) || 0));
  const raw = pop * cfg.litersPerResident;
  const need = Math.max(cfg.minTankLiters, Math.ceil(raw));
  return snapTankLitersWithTropical(norms, need, tropicalShower);
}

/**
 * Минимальный powerKw.max среди одноконтурных котлов пула.
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized[]} boilers
 */
export function smallestSingleCircuitMaxKw(boilers) {
  if (!boilers?.length) return null;
  let min = Infinity;
  for (const b of boilers) {
    const max = Number(b?.powerKw?.max);
    if (Number.isFinite(max) && max > 0 && max < min) min = max;
  }
  return Number.isFinite(min) ? min : null;
}

/**
 * Назначение: ограничения монтажа котла и объёма котельной.
 * Описание: Фильтрация настенных/напольных моделей по типу объекта, зоне размещения и нормам из appliances.boiler.mounting.
 */

/**
 * @param {import('../dhw/types.js').BoilerApplianceRules['mounting'] | undefined} mounting
 * @returns {import('../dhw/types.js').BoilerApplianceRules['mounting']}
 */
function resolveMounting(mounting) {
  if (mounting) return mounting;
  throw new Error(
    'boilerMountingConstraints: mounting обязателен (передайте appliances.byKind.boiler.mounting из CalcRuntimeContext).',
  );
}

/**
 * Канонический type комнаты «котельная» в анкете (rooms[].type).
 *
 * @param {import('../dhw/types.js').BoilerApplianceRules['mounting']} [mounting]
 */
export function getBoilerRoomType(mounting) {
  return resolveMounting(mounting).boilerRoomType;
}

/** @typedef {'kitchen' | 'living_zone' | 'boiler_room'} BoilerPlacementZone */

/** @typedef {'wall' | 'floor'} BoilerMountingType */

/**
 * @param {import('../types/shared-types.js').BuildingObjectMeta | undefined} objectMeta
 * @returns {'house' | 'apartment'}
 */
export function resolveObjectType(objectMeta) {
  return objectMeta?.objectType === 'apartment' ? 'apartment' : 'house';
}

/**
 * @param {import('../types/shared-types.js').BuildingInput | undefined} building
 * @param {import('../types/shared-types.js').BuildingObjectMeta | undefined} objectMeta
 * @param {import('../dhw/types.js').BoilerApplianceRules['mounting']} [mounting]
 * @returns {{ volumeM3: number, heightM: number, source: 'room' | 'meta' } | null}
 */
export function resolveBoilerRoomMetrics(building, objectMeta, mounting) {
  const boilerRoomType = getBoilerRoomType(mounting);
  const rooms = building?.rooms;
  if (Array.isArray(rooms)) {
    /** @type {{ volumeM3: number, heightM: number, source: 'room' } | null} */
    let best = null;
    for (const r of rooms) {
      if (!r || r.type !== boilerRoomType) continue;
      const area = Number(r.areaM2);
      const height = Number(r.heightM);
      if (!Number.isFinite(area) || !Number.isFinite(height) || area <= 0 || height <= 0) {
        continue;
      }
      const volumeM3 = area * height;
      if (!best || volumeM3 > best.volumeM3) {
        best = { volumeM3, heightM: height, source: 'room' };
      }
    }
    if (best) return best;
  }

  const area = objectMeta?.boilerRoomAreaM2;
  const height = objectMeta?.ceilingHeightM;
  if (area != null && height != null) {
    const a = Number(area);
    const h = Number(height);
    if (Number.isFinite(a) && Number.isFinite(h) && a > 0 && h > 0) {
      return { volumeM3: a * h, heightM: h, source: 'meta' };
    }
  }

  return null;
}

/**
 * @param {{ volumeM3: number, heightM: number } | null | undefined} metrics
 * @param {import('../dhw/types.js').BoilerApplianceRules['mounting']} [mounting]
 * @returns {boolean}
 */
export function isBoilerRoomVolumeCompliant(metrics, mounting) {
  if (!metrics) return false;
  const m = resolveMounting(mounting);
  return (
    metrics.heightM >= m.minBoilerRoomHeightM && metrics.volumeM3 >= m.minBoilerRoomVolumeM3
  );
}

/**
 * Подходит ли котёл из каталога под объект (монтаж + зона; объём котельной — на входе API).
 *
 * @param {import('../types/shared-types.js').BuildingObjectMeta | undefined} objectMeta
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized} boiler
 * @param {import('../types/shared-types.js').BuildingInput | undefined} [building]
 * @param {import('../dhw/types.js').BoilerApplianceRules['mounting']} [mounting]
 * @returns {boolean}
 */
export function checkMountingConstraints(objectMeta, boiler, building = undefined, mounting) {
  const objectType = resolveObjectType(objectMeta);
  const mt = boiler.mountingType;
  const m = resolveMounting(mounting);

  if (objectType === 'apartment') {
    if (mt === 'floor') return false;
    const maxKw = Number(boiler.powerKw?.max ?? 0);
    if (maxKw > m.maxApartmentNominalKw) return false;
    return true;
  }

  if (mt === 'floor') {
    if (objectMeta?.boilerPlacementZone !== 'boiler_room') return false;
    return isBoilerRoomVolumeCompliant(
      resolveBoilerRoomMetrics(building, objectMeta, mounting),
      mounting,
    );
  }

  return true;
}

/**
 * @param {import('../catalog/types.js').BoilerCatalogItemNormalized[]} boilers
 * @param {import('../types/shared-types.js').BuildingObjectMeta | undefined} objectMeta
 * @param {import('../types/shared-types.js').BuildingInput | undefined} [building]
 * @param {import('../dhw/types.js').BoilerApplianceRules['mounting']} [mounting]
 * @returns {import('../catalog/types.js').BoilerCatalogItemNormalized[]}
 */
export function filterBoilersByMountingConstraints(boilers, objectMeta, building = undefined, mounting) {
  if (!boilers?.length) return [];
  return boilers.filter((b) => checkMountingConstraints(objectMeta, b, building, mounting));
}

/**
 * Назначение: конфигурация подключения к MongoDB.
 * Описание: Сборка URI из переменных окружения, нормализация пути БД и список кандидатов для seed и runtime справочников.
 */

/** Таймаут выбора сервера Mongo (мс) — быстрый fallback file при CATALOG_SOURCE=auto. */
const MONGO_SERVER_SELECTION_TIMEOUT_MS = 8_000;

/**
 * @returns {import('mongoose').ConnectOptions}
 */
function defaultMongoConnectOptions() {
  return {
    serverSelectionTimeoutMS: MONGO_SERVER_SELECTION_TIMEOUT_MS,
    connectTimeoutMS: MONGO_SERVER_SELECTION_TIMEOUT_MS,
  };
}

/**
 * @returns {{ authMechanism: import('mongodb').AuthMechanism, authSource: string }}
 */
function readMongoAuthEnv() {
  const raw = process.env.MONGODB_AUTH_MECHANISM?.trim() || 'SCRAM-SHA-256';
  return {
    authMechanism: /** @type {import('mongodb').AuthMechanism} */ (raw),
    authSource: process.env.MONGODB_AUTH_SOURCE?.trim() || 'admin',
  };
}

/**
 * Если в URI нет имени БД (путь пустой или «/»), подставляет MONGODB_DB.
 * @param {string} uri
 * @returns {string}
 */
export function normalizeMongoUri(uri) {
  const trimmed = uri.trim();
  try {
    const url = new URL(trimmed);
    const pathname = url.pathname?.replace(/^\/+|\/+$/g, '') ?? '';
    if (!pathname) {
      const db = process.env.MONGODB_DB?.trim();
      if (!db) {
        throw new Error(
          'MONGODB_URI без имени базы: задайте MONGODB_DB или укажите БД в пути URI',
        );
      }
      url.pathname = `/${db}`;
    }
    if (!url.searchParams.has('retryWrites')) {
      url.searchParams.set('retryWrites', 'true');
    }
    if (!url.searchParams.has('w')) {
      url.searchParams.set('w', 'majority');
    }
    return url.toString();
  } catch (err) {
    if (err instanceof Error && err.message.includes('MONGODB_URI без имени')) {
      throw err;
    }
    return trimmed;
  }
}

/**
 * Все кандидаты подключения MongoDB (для seed: перебор при сбое DNS/сети).
 * @returns {{ uri: string, options: import('mongoose').ConnectOptions, label: string }[]}
 */
export function getMongoConnectionConfigs() {
  const userRaw = process.env.MONGODB_USER?.trim();
  const passRaw = process.env.MONGODB_PASSWORD?.trim();
  const hostRaw = process.env.MONGODB_URL?.trim();
  const dbRaw = process.env.MONGODB_DB?.trim();
  const uriRaw = process.env.MONGODB_URI?.trim();
  const uriFallbackRaw = process.env.MONGODB_URI_FALLBACK?.trim();

  const { authMechanism, authSource } = readMongoAuthEnv();
  const baseOptions = defaultMongoConnectOptions();

  /** @type {{ uri: string, options: import('mongoose').ConnectOptions, label: string }[]} */
  const candidates = [];

  if (uriRaw) {
    candidates.push({
      uri: normalizeMongoUri(uriRaw),
      options: { ...baseOptions },
      label: 'MONGODB_URI',
    });
  }
  if (uriFallbackRaw) {
    candidates.push({
      uri: normalizeMongoUri(uriFallbackRaw),
      options: { ...baseOptions },
      label: 'MONGODB_URI_FALLBACK',
    });
  }
  if (userRaw && passRaw && hostRaw && dbRaw) {
    candidates.push({
      uri: normalizeMongoUri(
        `mongodb+srv://${hostRaw}/${dbRaw}?retryWrites=true&w=majority`,
      ),
      options: {
        ...baseOptions,
        user: userRaw,
        pass: passRaw,
        dbName: dbRaw,
        authMechanism,
        authSource,
      },
      label: 'MONGODB_URL+MONGODB_DB (mongodb+srv)',
    });
  }

  return candidates;
}

/**
 * Первый кандидат подключения или null, если переменные окружения не заданы.
 * @returns {{ uri: string, options: import('mongoose').ConnectOptions } | null}
 */
export function getMongoConnectionConfigOrNull() {
  const candidates = getMongoConnectionConfigs();
  const first = candidates[0];
  if (!first) return null;
  return { uri: first.uri, options: first.options };
}

/**
 * @param {string} envName
 * @param {'file' | 'mongo' | 'auto'} [fallback]
 * @returns {'file' | 'mongo' | 'auto'}
 */
export function resolveReferenceSourceMode(envName, fallback = 'file') {
  const raw = String(process.env[envName] ?? fallback).trim().toLowerCase();
  if (raw === 'mongo') return 'mongo';
  if (raw === 'auto') return 'auto';
  return 'file';
}
